import React, { useState, useEffect } from 'react';
import { CompanyConfig, Employee, Role, AttendanceRecord, Payment, GlobalSettings } from './types';
import AdminDashboard from './views/AdminDashboard';
import AttendanceSystem from './views/AttendanceSystem';
import Modal from './components/Modal';

const App: React.FC = () => {
  const [currentUserRole, setCurrentUserRole] = useState<Role | null>(null);
  const [view, setView] = useState<'selection' | 'admin' | 'attendance'>('selection');

  // Data State (Simulated Firebase/Local Storage Sync)
  const [company, setCompany] = useState<CompanyConfig | null>(() => {
    const saved = localStorage.getItem('asistup_company');
    return saved ? JSON.parse(saved) : null;
  });

  const [employees, setEmployees] = useState<Employee[]>(() => {
    const saved = localStorage.getItem('asistup_employees');
    return saved ? JSON.parse(saved) : [];
  });

  const [attendance, setAttendance] = useState<AttendanceRecord[]>(() => {
    const saved = localStorage.getItem('asistup_attendance');
    return saved ? JSON.parse(saved) : [];
  });

  const [payments, setPayments] = useState<Payment[]>(() => {
    const saved = localStorage.getItem('asistup_payments');
    return saved ? JSON.parse(saved) : [];
  });

  const [settings, setSettings] = useState<GlobalSettings>({
    sbu: 460,
    iessRate: 0.0945,
    reserveRate: 0.0833
  });

  // Persist to Local Storage
  useEffect(() => {
    localStorage.setItem('asistup_company', JSON.stringify(company));
    localStorage.setItem('asistup_employees', JSON.stringify(employees));
    localStorage.setItem('asistup_attendance', JSON.stringify(attendance));
    localStorage.setItem('asistup_payments', JSON.stringify(payments));
  }, [company, employees, attendance, payments]);

  const handleRegisterAttendance = (record: AttendanceRecord) => {
    setAttendance(prev => [...prev, record]);
  };

  const handleUpdateEmployees = (newEmployees: Employee[]) => {
    setEmployees(newEmployees);
  };

  const handleUpdateCompany = (config: CompanyConfig) => {
    setCompany(config);
  };

  const handleUpdatePayments = (newPayments: Payment[]) => {
    setPayments(newPayments);
  };

  if (view === 'selection') {
    return (
      <div className="min-h-screen gradient-blue flex flex-col items-center justify-center p-4">
        <div className="bg-white p-8 rounded-3xl shadow-2xl max-w-md w-full text-center">
          <div className="mb-6 flex justify-center">
            <div className="w-20 h-20 bg-blue-600 rounded-2xl flex items-center justify-center shadow-lg transform -rotate-6">
              <span className="text-white text-3xl font-bold">A+</span>
            </div>
          </div>
          <h1 className="text-3xl font-bold text-blue-900 mb-2">ASIST UP</h1>
          <p className="text-gray-500 mb-8">Gestión de Talento Humano & Asistencia</p>

          <div className="space-y-4">
            <button 
              onClick={() => { setCurrentUserRole(Role.SUPER_ADMIN); setView('admin'); }}
              className="w-full py-3 bg-blue-700 hover:bg-blue-800 text-white font-semibold rounded-xl transition-all shadow-md"
            >
              Panel Administrativo (Super Admin)
            </button>
            <button 
              onClick={() => { setCurrentUserRole(Role.PARTIAL_ADMIN); setView('admin'); }}
              className="w-full py-3 bg-blue-500 hover:bg-blue-600 text-white font-semibold rounded-xl transition-all shadow-md"
            >
              Panel Administrativo (Admin Parcial)
            </button>
            <button 
              onClick={() => { setView('attendance'); }}
              className="w-full py-3 border-2 border-blue-600 text-blue-700 hover:bg-blue-50 font-semibold rounded-xl transition-all"
            >
              Sistema de Marcaje de Asistencia
            </button>
          </div>
        </div>
      </div>
    );
  }

  if (view === 'attendance') {
    return (
      <AttendanceSystem 
        employees={employees} 
        onRegister={handleRegisterAttendance} 
        onBack={() => setView('selection')}
        onUpdateEmployees={handleUpdateEmployees}
      />
    );
  }

  return (
    <AdminDashboard 
      role={currentUserRole!} 
      onLogout={() => setView('selection')} 
      company={company}
      onUpdateCompany={handleUpdateCompany}
      employees={employees}
      onUpdateEmployees={handleUpdateEmployees}
      attendance={attendance}
      payments={payments}
      onUpdatePayments={handleUpdatePayments}
      settings={settings}
      onUpdateSettings={setSettings}
    />
  );
};

export default App;

import React from 'react';

interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  title: string;
  type?: 'info' | 'warning' | 'error' | 'success';
  children: React.ReactNode;
  footer?: React.ReactNode;
}

const Modal: React.FC<ModalProps> = ({ isOpen, onClose, title, type = 'info', children, footer }) => {
  if (!isOpen) return null;

  const headerColors = {
    info: 'bg-blue-600',
    warning: 'bg-yellow-500',
    error: 'bg-red-600',
    success: 'bg-emerald-600'
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-2xl overflow-hidden animate-in fade-in zoom-in duration-200">
        <div className={`${headerColors[type]} p-4 flex justify-between items-center text-white`}>
          <h3 className="text-xl font-bold">{title}</h3>
          <button onClick={onClose} className="hover:bg-white/20 p-1 rounded-full">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
          </button>
        </div>
        <div className="p-6 max-h-[80vh] overflow-y-auto">
          {children}
        </div>
        {footer && (
          <div className="p-4 border-t bg-gray-50 flex justify-end space-x-3">
            {footer}
          </div>
        )}
      </div>
    </div>
  );
};

export default Modal;

import React, { useState, useEffect } from 'react';

const Clock: React.FC = () => {
  const [time, setTime] = useState(new Date());

  useEffect(() => {
    const timer = setInterval(() => setTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  return (
    <div className="text-center">
      <div className="text-8xl font-black text-blue-900 tracking-tighter tabular-nums drop-shadow-md">
        {time.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })}
      </div>
      <div className="text-2xl text-blue-600 font-medium mt-2">
        {time.toLocaleDateString('es-EC', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}
      </div>
    </div>
  );
};

export default Clock;

import React, { useState, useEffect, useCallback } from 'react';
import { Employee, AttendanceRecord } from '../types';
import Clock from '../components/Clock';
import { APP_NAME, MOTIVATIONAL_MESSAGES_START, MOTIVATIONAL_MESSAGES_END } from '../constants';

interface AttendanceSystemProps {
  employees: Employee[];
  onRegister: (record: AttendanceRecord) => void;
  onBack: () => void;
  onUpdateEmployees: (employees: Employee[]) => void;
}

const AttendanceSystem: React.FC<AttendanceSystemProps> = ({ employees, onRegister, onBack, onUpdateEmployees }) => {
  const [pin, setPin] = useState('');
  const [message, setMessage] = useState<{ text: string; type: 'info' | 'success' | 'error' } | null>(null);
  const [isBlocked, setIsBlocked] = useState(false);
  const [currentEmployee, setCurrentEmployee] = useState<Employee | null>(null);

  const handleMark = useCallback((type: 'in' | 'out') => {
    if (!currentEmployee) return;

    const record: AttendanceRecord = {
      id: Math.random().toString(36).substr(2, 9),
      employeeId: currentEmployee.id,
      timestamp: new Date().toISOString(),
      type
    };

    onRegister(record);

    const messages = type === 'in' ? MOTIVATIONAL_MESSAGES_START : MOTIVATIONAL_MESSAGES_END;
    const motivationalText = messages[Math.floor(Math.random() * messages.length)];

    setMessage({ 
      text: `${motivationalText} Marcado de ${type === 'in' ? 'Entrada' : 'Salida'} exitoso.`, 
      type: 'success' 
    });

    setIsBlocked(true);
    setPin('');

    setTimeout(() => {
      setIsBlocked(false);
      setMessage(null);
      setCurrentEmployee(null);
    }, 5000);
  }, [currentEmployee, onRegister]);

  const handlePinSubmit = useCallback(() => {
    const employee = employees.find(e => e.pin === pin && e.status === 'active');
    if (employee) {
      setCurrentEmployee(employee);
      setMessage({ text: `¿Desea marcar asistencia, ${employee.name}?`, type: 'info' });
    } else {
      setMessage({ text: 'PIN incorrecto o empleado no encontrado.', type: 'error' });
      setPin('');
      setTimeout(() => setMessage(null), 3000);
    }
  }, [pin, employees]);

  useEffect(() => {
    if (pin.length === 6 && !isBlocked) {
      handlePinSubmit();
    }
  }, [pin, handlePinSubmit, isBlocked]);

  // Handle physical keyboard
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (isBlocked) return;
      if (e.key >= '0' && e.key <= '9') {
        if (pin.length < 6) setPin(prev => prev + e.key);
      } else if (e.key === 'Backspace') {
        setPin(prev => prev.slice(0, -1));
      } else if (e.key === 'Escape') {
        setPin('');
        setCurrentEmployee(null);
        setMessage(null);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [pin, isBlocked]);

  return (
    <div className="min-h-screen gradient-blue flex flex-col items-center justify-center p-8">
      <button 
        onClick={onBack}
        className="absolute top-8 left-8 text-white/70 hover:text-white flex items-center gap-2 font-medium"
      >
        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 19l-7-7m0 0l7-7m-7 7h18"></path></svg>
        Salir al menú
      </button>

      <div className="w-full max-w-4xl bg-white rounded-[2.5rem] shadow-2xl p-12 flex flex-col items-center">
        <div className="mb-12">
          <h1 className="text-4xl font-bold text-blue-900 mb-2 flex items-center justify-center gap-3">
            <span className="p-2 bg-blue-600 rounded-lg text-white">A+</span> {APP_NAME}
          </h1>
          <Clock />
        </div>

        {isBlocked ? (
          <div className="text-center animate-pulse">
            <div className="w-24 h-24 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mx-auto mb-6">
              <svg className="w-12 h-12" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7"></path></svg>
            </div>
            <h2 className="text-3xl font-bold text-blue-900 mb-2">{message?.text}</h2>
            <p className="text-gray-500 text-xl">Reiniciando sistema en unos segundos...</p>
          </div>
        ) : currentEmployee ? (
          <div className="text-center w-full max-w-lg">
            <div className="mb-8">
              <img src={currentEmployee.photo || 'https://picsum.photos/200'} className="w-32 h-32 rounded-full border-4 border-blue-600 mx-auto object-cover" alt="Employee" />
              <h2 className="text-3xl font-bold text-blue-900 mt-4">{currentEmployee.name}</h2>
              <p className="text-blue-600 font-medium">Confirme su marcaje</p>
            </div>
            <div className="grid grid-cols-2 gap-6">
              <button 
                onClick={() => handleMark('in')}
                className="py-6 bg-emerald-600 hover:bg-emerald-700 text-white text-2xl font-bold rounded-2xl shadow-lg transition-all"
              >
                ENTRADA
              </button>
              <button 
                onClick={() => handleMark('out')}
                className="py-6 bg-blue-600 hover:bg-blue-700 text-white text-2xl font-bold rounded-2xl shadow-lg transition-all"
              >
                SALIDA
              </button>
            </div>
            <button 
              onClick={() => { setCurrentEmployee(null); setPin(''); setMessage(null); }}
              className="mt-8 text-gray-500 hover:text-red-500 font-medium underline"
            >
              Cancelar
            </button>
          </div>
        ) : (
          <div className="w-full max-w-sm text-center">
            <h3 className="text-xl font-medium text-gray-600 mb-6 italic">Ingrese su PIN de 6 dígitos</h3>
            <div className="flex gap-4 justify-center mb-10">
              {[...Array(6)].map((_, i) => (
                <div 
                  key={i}
                  className={`w-12 h-16 border-b-4 flex items-center justify-center text-4xl font-bold transition-all ${pin.length > i ? 'border-blue-600 text-blue-900' : 'border-gray-200 text-gray-300'}`}
                >
                  {pin[i] ? '•' : ''}
                </div>
              ))}
            </div>

            {message?.type === 'error' && (
              <div className="mb-6 p-4 bg-red-50 text-red-600 rounded-xl font-medium border border-red-100">
                {message.text}
              </div>
            )}

            <div className="grid grid-cols-3 gap-4">
              {[1, 2, 3, 4, 5, 6, 7, 8, 9].map(num => (
                <button 
                  key={num}
                  onClick={() => pin.length < 6 && setPin(p => p + num)}
                  className="w-full h-16 bg-gray-50 hover:bg-blue-50 text-blue-900 text-2xl font-bold rounded-2xl transition-all border border-gray-100"
                >
                  {num}
                </button>
              ))}
              <button 
                onClick={() => setPin('')}
                className="w-full h-16 text-red-500 font-bold text-lg rounded-2xl hover:bg-red-50 transition-all"
              >
                BORRAR
              </button>
              <button 
                onClick={() => pin.length < 6 && setPin(p => p + '0')}
                className="w-full h-16 bg-gray-50 hover:bg-blue-50 text-blue-900 text-2xl font-bold rounded-2xl transition-all border border-gray-100"
              >
                0
              </button>
              <button 
                onClick={() => setPin(p => p.slice(0, -1))}
                className="w-full h-16 text-blue-600 font-bold text-lg rounded-2xl hover:bg-blue-50 transition-all"
              >
                ←
              </button>
            </div>
          </div>
        )}
      </div>

      <div className="mt-8 text-white/50 text-sm font-medium tracking-widest uppercase">
        Seguridad Controlada • Sincronización Real-time
      </div>
    </div>
  );
};

export default AttendanceSystem;

import React, { useState, useMemo } from 'react';
import { Role, CompanyConfig, Employee, AttendanceRecord, Payment, GlobalSettings } from '../types';
import Sidebar from '../components/Sidebar';
import CompanyModule from './modules/CompanyModule';
import EmployeeModule from './modules/EmployeeModule';
import PayrollModule from './modules/PayrollModule';
import PaymentsModule from './modules/PaymentsModule';
import SettingsModule from './modules/SettingsModule';

interface AdminDashboardProps {
  role: Role;
  onLogout: () => void;
  company: CompanyConfig | null;
  onUpdateCompany: (config: CompanyConfig) => void;
  employees: Employee[];
  onUpdateEmployees: (employees: Employee[]) => void;
  attendance: AttendanceRecord[];
  payments: Payment[];
  onUpdatePayments: (payments: Payment[]) => void;
  settings: GlobalSettings;
  onUpdateSettings: (settings: GlobalSettings) => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  role, onLogout, company, onUpdateCompany, employees, onUpdateEmployees, attendance, payments, onUpdatePayments, settings, onUpdateSettings 
}) => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'company' | 'employees' | 'payroll' | 'payments' | 'settings'>('dashboard');

  const upcomingBirthdays = useMemo(() => {
    const today = new Date();
    return employees.filter(emp => {
      if (emp.status !== 'active') return false;
      const bday = new Date(emp.birthDate);
      const bdayThisYear = new Date(today.getFullYear(), bday.getMonth(), bday.getDate());
      const diff = (bdayThisYear.getTime() - today.getTime()) / (1000 * 3600 * 24);
      return diff >= 0 && diff <= 3;
    });
  }, [employees]);

  return (
    <div className="flex h-screen bg-gray-50 overflow-hidden">
      <Sidebar 
        role={role} 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        onLogout={onLogout} 
        companyName={company?.name}
      />

      <main className="flex-1 overflow-y-auto p-8">
        <header className="flex justify-between items-center mb-10">
          <div>
            <h1 className="text-3xl font-bold text-gray-900">
              {activeTab === 'dashboard' ? 'Panel Principal' : 
               activeTab === 'company' ? 'Configuración de Empresa' : 
               activeTab === 'employees' ? 'Gestión de Personal' : 
               activeTab === 'payroll' ? 'Rol de Pagos' : 
               activeTab === 'payments' ? 'Tesorería y Pagos' : 'Ajustes de Sistema'}
            </h1>
            <p className="text-gray-500">Sesión iniciada como: <span className="text-blue-600 font-semibold">{role}</span></p>
          </div>

          <div className="flex items-center gap-4">
             {upcomingBirthdays.length > 0 && (
               <div className="bg-emerald-100 border border-emerald-200 p-3 rounded-xl flex items-center gap-3 animate-bounce">
                 <div className="bg-emerald-500 text-white p-2 rounded-lg">🎂</div>
                 <div>
                   <p className="text-emerald-800 text-xs font-bold uppercase tracking-wider">Próximos Cumpleaños</p>
                   <p className="text-emerald-700 text-sm font-medium">
                    {upcomingBirthdays.map(e => e.name).join(', ')}
                   </p>
                 </div>
               </div>
             )}
          </div>
        </header>

        <div className="animate-in fade-in slide-in-from-bottom-4 duration-300">
          {activeTab === 'dashboard' && (
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
                <h3 className="text-gray-500 text-sm font-medium uppercase mb-4">Personal Activo</h3>
                <div className="flex items-end justify-between">
                  <span className="text-4xl font-bold text-blue-900">{employees.filter(e => e.status === 'active').length}</span>
                  <div className="text-emerald-600 text-sm font-medium">Empresas vinculadas</div>
                </div>
              </div>
              <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
                <h3 className="text-gray-500 text-sm font-medium uppercase mb-4">Marcajes de Hoy</h3>
                <div className="flex items-end justify-between">
                  <span className="text-4xl font-bold text-blue-900">
                    {attendance.filter(a => a.timestamp.split('T')[0] === new Date().toISOString().split('T')[0]).length}
                  </span>
                </div>
              </div>
              <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
                <h3 className="text-gray-500 text-sm font-medium uppercase mb-4">Pagos del Mes</h3>
                <div className="flex items-end justify-between">
                  <span className="text-4xl font-bold text-blue-900">
                    ${payments.filter(p => p.status === 'paid').reduce((sum, p) => sum + p.amount, 0).toLocaleString()}
                  </span>
                </div>
              </div>

              <div className="md:col-span-3 bg-blue-900 rounded-3xl p-8 text-white relative overflow-hidden shadow-xl">
                 <div className="relative z-10">
                    <h2 className="text-2xl font-bold mb-2">Bienvenido a ASIST UP</h2>
                    <p className="text-blue-100 mb-6 max-w-xl">El sistema está sincronizado y funcionando correctamente. Recuerde realizar respaldos cada 15 días.</p>
                    <button className="px-6 py-2 bg-white text-blue-900 font-bold rounded-xl hover:bg-blue-50 transition-colors">
                      Explorar Reportes
                    </button>
                 </div>
                 <div className="absolute top-0 right-0 p-10 opacity-10">
                    <svg className="w-64 h-64" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1 15h-2v-6h2v6zm0-8h-2V7h2v2z"/></svg>
                 </div>
              </div>
            </div>
          )}

          {activeTab === 'company' && (
            <CompanyModule company={company} onUpdate={onUpdateCompany} role={role} />
          )}

          {activeTab === 'employees' && (
            <EmployeeModule employees={employees} onUpdate={onUpdateEmployees} role={role} attendance={attendance} payments={payments} />
          )}

          {activeTab === 'payroll' && (
            <PayrollModule employees={employees} payments={payments} company={company} settings={settings} role={role} />
          )}

          {activeTab === 'payments' && (
            <PaymentsModule employees={employees} payments={payments} onUpdate={onUpdatePayments} role={role} />
          )}

          {activeTab === 'settings' && (
            <SettingsModule settings={settings} onUpdate={onUpdateSettings} role={role} />
          )}
        </div>
      </main>
    </div>
  );
};

