import React, { useState } from 'react';
import { Employee, Role, BloodType, TerminationReason, AttendanceRecord, Payment } from '../../types';
import Modal from '../../components/Modal';

interface EmployeeModuleProps {
  employees: Employee[];
  onUpdate: (employees: Employee[]) => void;
  role: Role;
  attendance: AttendanceRecord[];
  payments: Payment[];
}

const EmployeeModule: React.FC<EmployeeModuleProps> = ({ employees, onUpdate, role, attendance, payments }) => {
  const [isRegisterModalOpen, setIsRegisterModalOpen] = useState(false);
  const [selectedEmployee, setSelectedEmployee] = useState<Employee | null>(null);
  const [isTerminationModalOpen, setIsTerminationModalOpen] = useState(false);
  const [terminationForm, setTerminationForm] = useState({
    date: new Date().toISOString().split('T')[0],
    reason: TerminationReason.VOLUNTARY,
    details: ''
  });

  const [formData, setFormData] = useState<Partial<Employee>>({
    name: '', identification: '', birthDate: '', origin: '', address: '', phone: '', email: '',
    bloodType: BloodType.O_POS, emergencyContact: { name: '', phone: '' }, startDate: '',
    role: Role.EMPLOYEE, isFixed: true, salary: 460, isAffiliated: true,
    overSalaryType: 'monthly', bankInfo: { ifi: '', type: 'Ahorros', account: '' },
    photo: '', pin: '', pinChanges: 0, status: 'active', observations: []
  });

  const handleSaveEmployee = () => {
    if (formData.pin?.length !== 6) {
      alert("PIN debe ser estrictamente de 6 dígitos");
      return;
    }

    if (formData.id) {
      // Edit
      const newEmployees = employees.map(e => e.id === formData.id ? { ...e, ...formData } as Employee : e);
      onUpdate(newEmployees);
    } else {
      // New
      const newEmployee: Employee = {
        ...formData,
        id: Math.random().toString(36).substr(2, 9),
        totalHoursWorked: 0,
        observations: []
      } as Employee;
      onUpdate([...employees, newEmployee]);
    }
    setIsRegisterModalOpen(false);
    resetForm();
  };

  const handleTerminate = () => {
    if (!selectedEmployee) return;
    const updatedEmployees = employees.map(e => {
      if (e.id === selectedEmployee.id) {
        return {
          ...e,
          status: 'terminated' as const,
          terminationDate: terminationForm.date,
          terminationReason: terminationForm.reason,
          terminationDetails: terminationForm.details
        };
      }
      return e;
    });
    onUpdate(updatedEmployees);
    setIsTerminationModalOpen(false);
    setSelectedEmployee(null);
    alert('Empleado desvinculado correctamente. Se ha bloqueado su acceso.');
  };

  const resetForm = () => {
    setFormData({
      name: '', identification: '', birthDate: '', origin: '', address: '', phone: '', email: '',
      bloodType: BloodType.O_POS, emergencyContact: { name: '', phone: '' }, startDate: '',
      role: Role.EMPLOYEE, isFixed: true, salary: 460, isAffiliated: true,
      overSalaryType: 'monthly', bankInfo: { ifi: '', type: 'Ahorros', account: '' },
      photo: '', pin: '', pinChanges: 0, status: 'active', observations: []
    });
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div className="relative w-72">
          <input 
            className="w-full pl-10 pr-4 py-2 bg-white rounded-xl border border-gray-200 outline-none focus:border-blue-500"
            placeholder="Buscar empleado..."
          />
          <svg className="w-5 h-5 absolute left-3 top-2.5 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"></path></svg>
        </div>
        <button 
          onClick={() => { resetForm(); setIsRegisterModalOpen(true); }}
          className="px-6 py-2 bg-blue-700 hover:bg-blue-800 text-white font-bold rounded-xl shadow-lg transition-all flex items-center gap-2"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6v6m0 0v6m0-6h6m-6 0H6"></path></svg>
          Registrar Empleado
        </button>
      </div>

      <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-gray-50 border-b">
            <tr>
              <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Empleado</th>
              <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">ID / RUC</th>
              <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Rol</th>
              <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Estado</th>
              <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Acciones</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-100">
            {employees.map(emp => (
              <tr key={emp.id} className="hover:bg-blue-50/30 transition-colors">
