                  <span className={`px-2 py-1 text-[10px] font-bold rounded-lg uppercase ${emp.role === Role.SUPER_ADMIN ? 'bg-purple-100 text-purple-700' : emp.role === Role.PARTIAL_ADMIN ? 'bg-blue-100 text-blue-700' : 'bg-gray-100 text-gray-700'}`}>
                    {emp.role}
