                <td className="px-6 py-4">
                  <span className={`px-2 py-1 text-[10px] font-bold rounded-lg uppercase ${emp.status === 'active' ? 'bg-emerald-100 text-emerald-700' : 'bg-red-100 text-red-700'}`}>
