                <label className="text-xs font-bold text-gray-500">Sobre sueldos</label>
                <select 
                  disabled={!formData.isAffiliated} 
                  value={formData.isAffiliated ? formData.overSalaryType : 'none'} 
                  onChange={e => setFormData({...formData, overSalaryType: e.target.value as any})} 
                  className="w-full border rounded-lg p-2"
                >
                  <option value="monthly">Mensualiza</option>
                  <option value="accumulate">Acumula</option>
                  <option value="none">No tiene derecho</option>
                </select>
              </div>
            </div>
          </div>
        </div>
      </Modal>

      {/* Employee File (Ficha) Modal */}
      {selectedEmployee && (
        <Modal 
          isOpen={!!selectedEmployee} 
          onClose={() => setSelectedEmployee(null)} 
          title={`Ficha Laboral: ${selectedEmployee.name}`}
          footer={
            <div className="w-full flex justify-between">
              {selectedEmployee.status === 'active' && (
                <button 
                  onClick={() => { 
                    if(confirm("¿Está seguro de desvincular este empleado? Esta acción es irreversible.")) {
                      setIsTerminationModalOpen(true);
                    }
                  }} 
                  className="px-6 py-2 bg-red-600 text-white rounded-lg font-bold"
                >
                  Desvincular Empleado
                </button>
              )}
              <button onClick={() => setSelectedEmployee(null)} className="px-4 py-2 text-gray-500 font-bold">Cerrar</button>
            </div>
          }
        >
          <div className="space-y-6">
            <div className="flex gap-6 items-start">
              <img src={selectedEmployee.photo || 'https://picsum.photos/200'} className="w-32 h-32 rounded-2xl border-4 border-gray-100 object-cover" />
              <div className="flex-1 grid grid-cols-2 gap-y-2">
                 <p className="text-xs font-bold text-gray-400 uppercase">Nombre</p>
                 <p className="text-xs font-bold text-gray-400 uppercase">Identificación</p>
                 <p className="font-bold">{selectedEmployee.name}</p>
                 <p className="font-bold">{selectedEmployee.identification}</p>
                 <p className="text-xs font-bold text-gray-400 uppercase">Ingreso</p>
                 <p className="text-xs font-bold text-gray-400 uppercase">Sueldo</p>
                 <p className="font-bold">{selectedEmployee.startDate}</p>
                 <p className="font-bold">${selectedEmployee.salary}</p>
              </div>
            </div>

            <div className="grid grid-cols-3 gap-4">
              <div className="p-3 bg-gray-50 rounded-xl text-center">
                <p className="text-[10px] font-bold text-gray-400 uppercase">Días Faltas</p>
                <p className="text-2xl font-black text-gray-900">0</p>
              </div>
              <div className="p-3 bg-gray-50 rounded-xl text-center">
                <p className="text-[10px] font-bold text-gray-400 uppercase">Atrasos</p>
                <p className="text-2xl font-black text-gray-900">0</p>
              </div>
              <div className="p-3 bg-gray-50 rounded-xl text-center">
                <p className="text-[10px] font-bold text-gray-400 uppercase">Horas Totales</p>
                <p className="text-2xl font-black text-blue-700">{selectedEmployee.totalHoursWorked}</p>
              </div>
            </div>

            <div>
              <h4 className="font-bold text-gray-900 border-b mb-3 pb-2">Historial de Pagos</h4>
              <div className="max-h-40 overflow-y-auto space-y-2">
                {payments.filter(p => p.employeeId === selectedEmployee.id).length > 0 ? (
                  payments.filter(p => p.employeeId === selectedEmployee.id).map(p => (
                    <div key={p.id} className="flex justify-between items-center text-sm p-2 bg-gray-50 rounded-lg">
                      <span>{p.date} - {p.type} ({p.month})</span>
                      <span className="font-bold">${p.amount}</span>
                    </div>
                  ))
                ) : <p className="text-center text-gray-400 text-sm py-4">No hay pagos registrados</p>}
              </div>
            </div>

            {selectedEmployee.status === 'terminated' && (
              <div className="p-4 bg-red-50 border border-red-100 rounded-xl">
                <h4 className="font-bold text-red-700 uppercase text-xs mb-2 tracking-widest">Información de Desvinculación</h4>
                <div className="grid grid-cols-2 gap-2 text-sm">
                  <p className="font-bold text-red-600">Fecha:</p> <p>{selectedEmployee.terminationDate}</p>
                  <p className="font-bold text-red-600">Motivo:</p> <p>{selectedEmployee.terminationReason}</p>
                  <p className="font-bold text-red-600">Detalles:</p> <p>{selectedEmployee.terminationDetails || '-'}</p>
                </div>
              </div>
            )}
          </div>
        </Modal>
      )}

      {/* Termination Workflow Modal */}
      <Modal 
        isOpen={isTerminationModalOpen} 
        onClose={() => setIsTerminationModalOpen(false)} 
        title="Formulario de Desvinculación"
        footer={
          <>
            <button onClick={() => setIsTerminationModalOpen(false)} className="px-4 py-2 text-gray-500 font-bold">Cancelar</button>
            <button onClick={handleTerminate} className="px-6 py-2 bg-red-600 text-white rounded-lg font-bold">Confirmar y Guardar</button>
          </>
        }
      >
        <div className="space-y-4">
          <p className="p-4 bg-red-100 text-red-700 text-sm font-bold rounded-lg border border-red-200">
            Atención: Una vez guardado, el empleado perderá acceso al sistema y será dado de baja de la nómina activa.
          </p>
          <div>
            <label className="text-xs font-bold uppercase text-gray-500">Fecha de Desvinculación</label>
            <input type="date" value={terminationForm.date} onChange={e => setTerminationForm({...terminationForm, date: e.target.value})} className="w-full border rounded-lg p-2" />
          </div>
          <div>
            <label className="text-xs font-bold uppercase text-gray-500">Motivo</label>
            <select value={terminationForm.reason} onChange={e => setTerminationForm({...terminationForm, reason: e.target.value as any})} className="w-full border rounded-lg p-2">
              {Object.values(TerminationReason).map(r => <option key={r} value={r}>{r}</option>)}
            </select>
          </div>
          {terminationForm.reason === TerminationReason.OTHER && (
            <div>
              <label className="text-xs font-bold uppercase text-gray-500">Argumentar Motivo</label>
              <textarea value={terminationForm.details} onChange={e => setTerminationForm({...terminationForm, details: e.target.value})} className="w-full border rounded-lg p-2" rows={3} />
            </div>
          )}
        </div>
      </Modal>
    </div>
  );
};

export default EmployeeModule;

