import React, { useState } from 'react';
import { Employee, Payment, Role } from '../../types';
import Modal from '../../components/Modal';

interface PaymentsModuleProps {
  employees: Employee[];
  payments: Payment[];
  onUpdate: (payments: Payment[]) => void;
  role: Role;
}

const PaymentsModule: React.FC<PaymentsModuleProps> = ({ employees, payments, onUpdate, role }) => {
  const [isPayModalOpen, setIsPayModalOpen] = useState(false);
  const [filterEmployee, setFilterEmployee] = useState('');

  const [paymentForm, setPaymentForm] = useState<Partial<Payment>>({
    employeeId: '',
    amount: 0,
    date: new Date().toISOString().split('T')[0],
    month: new Date().toLocaleString('es-EC', { month: 'long' }),
    type: 'Salary',
    method: 'Transferencia',
    bankSource: 'Banco del Austro',
    concept: '',
    status: 'paid'
  });

  const handleCreatePayment = () => {
    if (!paymentForm.employeeId || !paymentForm.amount || paymentForm.amount <= 0) {
      alert("Por favor complete los campos obligatorios.");
      return;
    }

    const newPayment: Payment = {
      ...paymentForm,
      id: Math.random().toString(36).substr(2, 9),
    } as Payment;

    onUpdate([...payments, newPayment]);
    setIsPayModalOpen(false);
    alert('Pago registrado correctamente.');
  };

  const handleVoid = (p: Payment) => {
    const just = prompt("Justificación para anular el pago:");
    if (!just) return;

    onUpdate(payments.map(pay => pay.id === p.id ? { ...pay, status: 'void', voidJustification: just } : pay));
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center bg-white p-4 rounded-2xl shadow-sm border border-gray-100">
        <div className="flex gap-4 items-center">
          <label className="text-sm font-bold text-gray-500 uppercase">Filtrar:</label>
          <select value={filterEmployee} onChange={e => setFilterEmployee(e.target.value)} className="border rounded-lg px-4 py-2">
            <option value="">Todos los empleados</option>
            {employees.map(e => <option key={e.id} value={e.id}>{e.name}</option>)}
          </select>
        </div>
        <button onClick={() => setIsPayModalOpen(true)} className="px-6 py-2 bg-blue-700 text-white font-bold rounded-xl shadow-lg">
          Nuevo Desembolso
        </button>
      </div>

      <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-gray-50 border-b">
            <tr>
              <th className="px-6 py-4 text-xs font-bold text-gray-500">FECHA</th>
              <th className="px-6 py-4 text-xs font-bold text-gray-500">EMPLEADO</th>
              <th className="px-6 py-4 text-xs font-bold text-gray-500">CONCEPTO</th>
              <th className="px-6 py-4 text-xs font-bold text-gray-500">VALOR</th>
              <th className="px-6 py-4 text-xs font-bold text-gray-500">ESTADO</th>
              <th className="px-6 py-4 text-xs font-bold text-gray-500">ACCIONES</th>
            </tr>
          </thead>
          <tbody className="divide-y">
            {payments.filter(p => !filterEmployee || p.employeeId === filterEmployee).map(p => {
              const emp = employees.find(e => e.id === p.employeeId);
              return (
                <tr key={p.id} className={`${p.status === 'void' ? 'bg-red-50 opacity-60' : ''}`}>
                  <td className="px-6 py-4 text-sm">{p.date}</td>
                  <td className="px-6 py-4 font-bold">{emp?.name || 'Unknown'}</td>
                  <td className="px-6 py-4 text-sm">{p.concept}</td>
                  <td className="px-6 py-4 font-black text-blue-800">${p.amount.toFixed(2)}</td>
                  <td className="px-6 py-4">
                    <span className={`px-2 py-1 text-[10px] font-bold rounded-lg uppercase ${p.status === 'paid' ? 'bg-emerald-100 text-emerald-700' : 'bg-red-100 text-red-700'}`}>
                      {p.status === 'paid' ? 'Pagado' : 'Anulado'}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                    {p.status === 'paid' && (
                      <button onClick={() => handleVoid(p)} className="text-red-500 hover:text-red-700 font-bold text-xs uppercase underline">Anular</button>
                    )}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      <Modal 
        isOpen={isPayModalOpen} 
        onClose={() => setIsPayModalOpen(false)} 
        title="Registrar Nuevo Pago"
        footer={
          <>
            <button onClick={() => setIsPayModalOpen(false)} className="px-4 py-2 text-gray-500 font-bold">Cancelar</button>
            <button onClick={handleCreatePayment} className="px-6 py-2 bg-blue-700 text-white rounded-lg font-bold">Registrar Pago</button>
          </>
        }
      >
        <div className="grid grid-cols-2 gap-4">
          <div className="col-span-2">
            <label className="text-xs font-bold text-gray-500 uppercase">Seleccionar Empleado</label>
            <select value={paymentForm.employeeId} onChange={e => setPaymentForm({...paymentForm, employeeId: e.target.value})} className="w-full border rounded-lg p-2">
              <option value="">-- Seleccionar --</option>
              {employees.filter(e => e.status === 'active').map(e => <option key={e.id} value={e.id}>{e.name}</option>)}
            </select>
          </div>
          <div>
            <label className="text-xs font-bold text-gray-500 uppercase">Valor a Pagar</label>
            <input type="number" value={paymentForm.amount} onChange={e => setPaymentForm({...paymentForm, amount: Number(e.target.value)})} className="w-full border rounded-lg p-2" />
          </div>
          <div>
            <label className="text-xs font-bold text-gray-500 uppercase">Mes correspondiente</label>
            <select value={paymentForm.month} onChange={e => setPaymentForm({...paymentForm, month: e.target.value})} className="w-full border rounded-lg p-2">
              {["Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio", "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre"].map(m => <option key={m} value={m}>{m}</option>)}
            </select>
          </div>
          <div>
            <label className="text-xs font-bold text-gray-500 uppercase">Tipo de Pago</label>
            <select value={paymentForm.type} onChange={e => setPaymentForm({...paymentForm, type: e.target.value as any})} className="w-full border rounded-lg p-2">
              <option value="Salary">Sueldo</option>
              <option value="OverSalary">Sobre sueldo</option>
              <option value="Loan">Préstamo</option>
              <option value="Bonus">Bono / Gratificación</option>
              <option value="Settlement">Liquidación</option>
            </select>
          </div>
          <div>
            <label className="text-xs font-bold text-gray-500 uppercase">Método</label>
            <select value={paymentForm.method} onChange={e => setPaymentForm({...paymentForm, method: e.target.value as any})} className="w-full border rounded-lg p-2">
              <option value="Transferencia">Transferencia</option>
              <option value="Efectivo">Efectivo</option>
              <option value="Cheque">Cheque</option>
            </select>
          </div>
          {paymentForm.method === 'Transferencia' && (
            <div className="col-span-2">
              <label className="text-xs font-bold text-gray-500 uppercase">Institución Financiera de Origen</label>
              <select value={paymentForm.bankSource} onChange={e => setPaymentForm({...paymentForm, bankSource: e.target.value as any})} className="w-full border rounded-lg p-2">
                <option value="Banco del Austro">Banco del Austro</option>
                <option value="Banco Guayaquil">Banco Guayaquil</option>
              </select>
            </div>
          )}
          <div className="col-span-2">
            <label className="text-xs font-bold text-gray-500 uppercase">Concepto detallado</label>
            <textarea value={paymentForm.concept} onChange={e => setPaymentForm({...paymentForm, concept: e.target.value})} className="w-full border rounded-lg p-2" rows={2} placeholder="Ej. Pago quincenal de sueldo..." />
          </div>
        </div>
      </Modal>
    </div>
  );
};

export default PaymentsModule;

import React, { useState } from 'react';
import { GlobalSettings, Role } from '../../types';

interface SettingsModuleProps {
  settings: GlobalSettings;
  onUpdate: (settings: GlobalSettings) => void;
  role: Role;
}

const SettingsModule: React.FC<SettingsModuleProps> = ({ settings, onUpdate, role }) => {
  const [localSettings, setLocalSettings] = useState(settings);

  const handleBackup = () => {
    alert("¡IMPORTANTE! Recuerde respaldar sus datos cada 15 días para evitar pérdidas accidentales. Iniciando descarga de respaldo...");
    const data = {
      company: localStorage.getItem('asistup_company'),
      employees: localStorage.getItem('asistup_employees'),
      attendance: localStorage.getItem('asistup_attendance'),
      payments: localStorage.getItem('asistup_payments'),
      timestamp: new Date().toISOString()
    };
    const blob = new Blob([JSON.stringify(data)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `ASISTUP_BACKUP_${new Date().toISOString().split('T')[0]}.json`;
    link.click();
  };

  const handleSave = () => {
    if (confirm("Está a punto de modificar parámetros críticos del sistema que afectarán todos los cálculos de nómina. ¿Desea continuar?")) {
      onUpdate(localSettings);
      alert("Parámetros actualizados correctamente.");
    }
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8">
      <div className="bg-white p-8 rounded-3xl shadow-sm border border-gray-100">
        <h3 className="text-xl font-bold text-gray-900 mb-6">Parámetros Laborales Generales</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="space-y-2">
            <label className="text-sm font-bold text-gray-500 uppercase tracking-widest">SBU Nacional (Anual)</label>
            <input 
              type="number"
              value={localSettings.sbu}
              onChange={e => setLocalSettings({...localSettings, sbu: Number(e.target.value)})}
              className="w-full px-4 py-3 rounded-xl border border-gray-200 focus:border-blue-500 outline-none"
            />
            <p className="text-[10px] text-gray-400">Este valor se utiliza para el cálculo del Décimo Cuarto Sueldo.</p>
          </div>
          <div className="space-y-2">
            <label className="text-sm font-bold text-gray-500 uppercase tracking-widest">Aporte Personal IESS (%)</label>
            <div className="relative">
              <input 
                type="number"
                step="0.01"
                value={localSettings.iessRate * 100}
