import React, { useState, useEffect } from 'react';
import { CompanyConfig, Employee, Role, AttendanceRecord, Payment, GlobalSettings } from './types';
import AdminDashboard from './views/AdminDashboard';
import AttendanceSystem from './views/AttendanceSystem';
import { db, collection, doc, onSnapshot, setDoc, addDoc } from './firebase';

const App: React.FC = () => {
  const [currentUserRole, setCurrentUserRole] = useState<Role | null>(null);
  const [view, setView] = useState<'selection' | 'admin' | 'attendance'>('selection');

  // Data State
  const [company, setCompany] = useState<CompanyConfig | null>(null);
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);
  const [payments, setPayments] = useState<Payment[]>([]);
  const [settings, setSettings] = useState<GlobalSettings>({
    sbu: 460,
    iessRate: 0.0945,
    reserveRate: 0.0833
  });

  // Real-time Subscriptions with Firebase
  useEffect(() => {
    // Sync Company
    const unsubCompany = onSnapshot(doc(db, "config", "company"), (docSnap) => {
      if (docSnap.exists()) setCompany(docSnap.data() as CompanyConfig);
    });

    // Sync Settings
    const unsubSettings = onSnapshot(doc(db, "config", "settings"), (docSnap) => {
      if (docSnap.exists()) setSettings(docSnap.data() as GlobalSettings);
    });

    // Sync Employees
    const unsubEmployees = onSnapshot(collection(db, "employees"), (snapshot) => {
      const data = snapshot.docs.map(d => ({ ...d.data(), id: d.id })) as Employee[];
      setEmployees(data);
    });

    // Sync Attendance
    const unsubAttendance = onSnapshot(collection(db, "attendance"), (snapshot) => {
      const data = snapshot.docs.map(d => ({ ...d.data(), id: d.id })) as AttendanceRecord[];
      setAttendance(data);
    });

    // Sync Payments
    const unsubPayments = onSnapshot(collection(db, "payments"), (snapshot) => {
      const data = snapshot.docs.map(d => ({ ...d.data(), id: d.id })) as Payment[];
      setPayments(data);
    });

    return () => {
      unsubCompany();
      unsubSettings();
      unsubEmployees();
      unsubAttendance();
      unsubPayments();
    };
  }, []);

  // Handlers for Writing to Firebase
  const handleRegisterAttendance = async (record: AttendanceRecord) => {
    try {
      await addDoc(collection(db, "attendance"), record);
    } catch (e) {
      console.error("Error al registrar asistencia:", e);
    }
  };

  const handleUpdateEmployees = async (newEmployees: Employee[]) => {
    // En Firestore actualizamos individualmente o por lote.
    // Para simplificar esta migración, identificamos qué cambió.
    // En una implementación real se usaría writeBatch.
    for (const emp of newEmployees) {
      await setDoc(doc(db, "employees", emp.id), emp);
    }
  };

  const handleUpdateCompany = async (config: CompanyConfig) => {
    await setDoc(doc(db, "config", "company"), config);
  };

  const handleUpdatePayments = async (newPayments: Payment[]) => {
    for (const pay of newPayments) {
      await setDoc(doc(db, "payments", pay.id), pay);
    }
  };

  const handleUpdateSettings = async (newSettings: GlobalSettings) => {
    await setDoc(doc(db, "config", "settings"), newSettings);
  };

  if (view === 'selection') {
    return (
      <div className="min-h-screen gradient-blue flex flex-col items-center justify-center p-4">
        <div className="bg-white p-8 rounded-3xl shadow-2xl max-w-md w-full text-center">
          <div className="mb-6 flex justify-center">
            <div className="w-20 h-20 bg-blue-600 rounded-2xl flex items-center justify-center shadow-lg transform -rotate-6">
              <span className="text-white text-3xl font-bold">A+</span>
            </div>
          </div>
          <h1 className="text-3xl font-bold text-blue-900 mb-2">ASIST UP</h1>
          <p className="text-gray-500 mb-8">Gestión de Talento Humano & Asistencia</p>

          <div className="space-y-4">
            <button 
              onClick={() => { setCurrentUserRole(Role.SUPER_ADMIN); setView('admin'); }}
              className="w-full py-3 bg-blue-700 hover:bg-blue-800 text-white font-semibold rounded-xl transition-all shadow-md"
            >
              Panel Administrativo (Super Admin)
            </button>
            <button 
              onClick={() => { setCurrentUserRole(Role.PARTIAL_ADMIN); setView('admin'); }}
              className="w-full py-3 bg-blue-500 hover:bg-blue-600 text-white font-semibold rounded-xl transition-all shadow-md"
            >
              Panel Administrativo (Admin Parcial)
            </button>
            <button 
              onClick={() => { setView('attendance'); }}
              className="w-full py-3 border-2 border-blue-600 text-blue-700 hover:bg-blue-50 font-semibold rounded-xl transition-all"
            >
              Sistema de Marcaje de Asistencia
            </button>
          </div>
          <div className="mt-6 text-[10px] text-gray-400 uppercase tracking-widest font-bold">
            Cloud Sync Active ☁️
          </div>
        </div>
      </div>
    );
  }

  if (view === 'attendance') {
    return (
      <AttendanceSystem 
        employees={employees} 
        onRegister={handleRegisterAttendance} 
        onBack={() => setView('selection')}
        onUpdateEmployees={handleUpdateEmployees}
      />
    );
  }

  return (
    <AdminDashboard 
      role={currentUserRole!} 
      onLogout={() => setView('selection')} 
      company={company}
      onUpdateCompany={handleUpdateCompany}
      employees={employees}
      onUpdateEmployees={handleUpdateEmployees}
      attendance={attendance}
      payments={payments}
      onUpdatePayments={handleUpdatePayments}
      settings={settings}
      onUpdateSettings={handleUpdateSettings}
    />
  );
};

export default App;

