import React, { useState } from 'react';
import { Employee, Role, BloodType, TerminationReason, AttendanceRecord, Payment } from '../../types';
import Modal from '../../components/Modal';

interface EmployeeModuleProps {
  employees: Employee[];
  onUpdate: (employees: Employee[]) => void;
  role: Role;
  attendance: AttendanceRecord[];
  payments: Payment[];
}

const EmployeeModule: React.FC<EmployeeModuleProps> = ({ employees, onUpdate, role, attendance, payments }) => {
  const [isRegisterModalOpen, setIsRegisterModalOpen] = useState(false);
  const [selectedEmployee, setSelectedEmployee] = useState<Employee | null>(null);
  const [isTerminationModalOpen, setIsTerminationModalOpen] = useState(false);
  const [terminationForm, setTerminationForm] = useState({
    date: new Date().toISOString().split('T')[0],
    reason: TerminationReason.VOLUNTARY,
    details: ''
  });

  const [formData, setFormData] = useState<Partial<Employee>>({
    name: '', identification: '', birthDate: '', origin: '', address: '', phone: '', email: '',
    bloodType: BloodType.O_POS, emergencyContact: { name: '', phone: '' }, startDate: '',
    role: Role.EMPLOYEE, isFixed: true, salary: 460, isAffiliated: true,
    overSalaryType: 'monthly', bankInfo: { ifi: '', type: 'Ahorros', account: '' },
    photo: '', pin: '', pinChanges: 0, status: 'active', observations: [], justifications: [], totalHoursWorked: 0
  });

  const handleSaveEmployee = () => {
    if (!formData.name || !formData.identification || !formData.phone || !formData.pin || !formData.emergencyContact?.name || !formData.emergencyContact?.phone) {
      alert("Todos los campos marcados como obligatorios deben llenarse.");
      return;
    }
    if (formData.pin?.length !== 6) {
      alert("PIN debe ser estrictamente de 6 dígitos numéricos.");
      return;
    }
    if (formData.phone?.length !== 10) {
      alert("El celular debe tener estrictamente 10 dígitos.");
      return;
    }

    // Logic: If not affiliated, no oversalary
    const finalFormData = { ...formData };
    if (!formData.isAffiliated) {
      finalFormData.overSalaryType = 'none';
    }

    if (formData.id) {
      const newEmployees = employees.map(e => e.id === formData.id ? { ...e, ...finalFormData } as Employee : e);
      onUpdate(newEmployees);
    } else {
      const newEmployee: Employee = {
        ...finalFormData,
        id: Math.random().toString(36).substr(2, 9),
        totalHoursWorked: 0,
        observations: [],
        justifications: [],
        status: 'active'
      } as Employee;
      onUpdate([...employees, newEmployee]);
    }
    setIsRegisterModalOpen(false);
    resetForm();
  };

  const handleTerminate = () => {
    if (!selectedEmployee) return;
    const updatedEmployees = employees.map(e => {
      if (e.id === selectedEmployee.id) {
        return {
          ...e,
          status: 'terminated' as const,
          terminationDate: terminationForm.date,
          terminationReason: terminationForm.reason,
          terminationDetails: terminationForm.details,
          isFixed: false // Se lo da de baja de los registros de empleados fijos
        };
      }
      return e;
    });
    onUpdate(updatedEmployees);
    setIsTerminationModalOpen(false);
    setSelectedEmployee(null);
    alert('Empleado desvinculado. El acceso ha sido bloqueado y se ha generado el registro histórico.');
    window.print(); // Imprimible de archivo
  };

  const resetForm = () => {
    setFormData({
      name: '', identification: '', birthDate: '', origin: '', address: '', phone: '', email: '',
      bloodType: BloodType.O_POS, emergencyContact: { name: '', phone: '' }, startDate: new Date().toISOString().split('T')[0],
      role: Role.EMPLOYEE, isFixed: true, salary: 460, isAffiliated: true,
      overSalaryType: 'monthly', bankInfo: { ifi: '', type: 'Ahorros', account: '' },
      photo: '', pin: '', pinChanges: 0, status: 'active', observations: [], justifications: [], totalHoursWorked: 0
    });
  };

  const addObservation = (emp: Employee) => {
    const obs = prompt("Ingrese la observación:");
    if (obs) {
      const updated = employees.map(e => e.id === emp.id ? { ...e, observations: [...e.observations, { date: new Date().toLocaleDateString(), text: obs }] } : e);
      onUpdate(updated);
      setSelectedEmployee(updated.find(e => e.id === emp.id) || null);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center bg-white p-6 rounded-3xl shadow-sm border border-gray-100">
        <div className="flex-1 max-w-md">
          <h2 className="text-xl font-bold text-blue-900">Directorio de Personal</h2>
          <p className="text-sm text-gray-500">Gestión de expedientes y registros laborales</p>
        </div>
        <button 
          onClick={() => { resetForm(); setIsRegisterModalOpen(true); }}
          className="px-8 py-3 bg-blue-700 hover:bg-blue-800 text-white font-bold rounded-2xl shadow-lg transition-all flex items-center gap-2"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6v6m0 0v6m0-6h6m-6 0H6"></path></svg>
