}

const AttendanceSystem: React.FC<AttendanceSystemProps> = ({ employees, onRegister, onBack, onUpdateEmployees }) => {
  const [pin, setPin] = useState('');
  const [message, setMessage] = useState<{ text: string; type: 'info' | 'success' | 'error' } | null>(null);
  const [isBlocked, setIsBlocked] = useState(false);
  const [currentEmployee, setCurrentEmployee] = useState<Employee | null>(null);

  const handleMark = useCallback((type: 'in' | 'out') => {
    if (!currentEmployee) return;

    const record: AttendanceRecord = {
      id: Math.random().toString(36).substr(2, 9),
      employeeId: currentEmployee.id,
      timestamp: new Date().toISOString(),
      type
    };

    onRegister(record);

    const messages = type === 'in' ? MOTIVATIONAL_MESSAGES_START : MOTIVATIONAL_MESSAGES_END;
    const motivationalText = messages[Math.floor(Math.random() * messages.length)];

    setMessage({ 
      text: `${motivationalText}\nMarcado de ${type === 'in' ? 'Entrada' : 'Salida'} exitoso.`, 
      type: 'success' 
    });

    setIsBlocked(true);
    setPin('');

    setTimeout(() => {
      setIsBlocked(false);
      setMessage(null);
      setCurrentEmployee(null);
    }, 5000);
  }, [currentEmployee, onRegister]);

  const handlePinSubmit = useCallback(() => {
    const employee = employees.find(e => e.pin === pin && e.status === 'active');
    if (employee) {
      setCurrentEmployee(employee);
      setMessage({ text: `¿Confirma marcar su asistencia, ${employee.name}?`, type: 'info' });
    } else {
      setMessage({ text: 'PIN INCORRECTO O ACCESO BLOQUEADO.', type: 'error' });
      setPin('');
      setTimeout(() => setMessage(null), 3000);
    }
  }, [pin, employees]);

  useEffect(() => {
    if (pin.length === 6 && !isBlocked && !currentEmployee) {
      handlePinSubmit();
    }
  }, [pin, handlePinSubmit, isBlocked, currentEmployee]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (isBlocked) return;
      if (e.key >= '0' && e.key <= '9') {
        if (pin.length < 6) setPin(prev => prev + e.key);
      } else if (e.key === 'Backspace') {
        setPin(prev => prev.slice(0, -1));
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [pin, isBlocked]);

  return (
    <div className="min-h-screen gradient-blue flex flex-col items-center justify-center p-8">
      <button 
        onClick={onBack}
        className="absolute top-8 left-8 text-white/50 hover:text-white flex items-center gap-3 font-black text-[10px] tracking-widest uppercase transition-all no-print"
      >
        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M10 19l-7-7m0 0l7-7m-7 7h18"></path></svg>
        SISTEMA ADMINISTRATIVO
      </button>

      <div className="w-full max-w-4xl bg-white rounded-[4rem] shadow-2xl p-16 flex flex-col items-center border border-white/20 backdrop-blur-sm">
        <div className="mb-14 text-center">
          <h1 className="text-5xl font-black text-blue-900 mb-6 flex items-center justify-center gap-4 tracking-tighter uppercase">
            <span className="p-3 bg-blue-600 rounded-2xl text-white shadow-xl rotate-3">A+</span> {APP_NAME}
          </h1>
          <Clock />
        </div>

        {isBlocked ? (
          <div className="text-center animate-in zoom-in duration-500">
            <div className="w-28 h-28 bg-emerald-50 text-emerald-500 rounded-[2.5rem] flex items-center justify-center mx-auto mb-8 border-2 border-emerald-100 shadow-inner">
              <svg className="w-16 h-16" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M5 13l4 4L19 7"></path></svg>
            </div>
            <h2 className="text-4xl font-black text-blue-900 mb-4 whitespace-pre-line leading-tight">{message?.text}</h2>
            <div className="flex items-center justify-center gap-3">
               <span className="w-2 h-2 bg-blue-600 rounded-full animate-ping"></span>
               <p className="text-gray-400 font-bold uppercase tracking-widest text-xs">Sistema bloqueado temporalmente...</p>
            </div>
          </div>
        ) : currentEmployee ? (
          <div className="text-center w-full max-w-xl animate-in fade-in slide-in-from-bottom-4">
            <div className="mb-10">
              <img src={currentEmployee.photo || `https://api.dicebear.com/7.x/avataaars/svg?seed=${currentEmployee.name}`} className="w-36 h-36 rounded-3xl border-8 border-gray-50 mx-auto object-cover shadow-2xl" alt="Employee" />
              <h2 className="text-4xl font-black text-blue-900 mt-6 tracking-tight uppercase">{currentEmployee.name}</h2>
              <div className="inline-block px-4 py-1 bg-blue-100 text-blue-700 rounded-full font-black text-[10px] tracking-widest uppercase mt-2">PIN CORRECTO</div>
            </div>
            <div className="grid grid-cols-2 gap-8">
              <button 
                onClick={() => handleMark('in')}
                className="group py-8 bg-emerald-600 hover:bg-emerald-700 text-white rounded-3xl shadow-xl transition-all active:scale-95"
              >
                <span className="block text-4xl font-black uppercase mb-1">ENTRADA</span>
                <span className="text-emerald-200 font-bold text-xs group-hover:text-white">REGISTRAR INGRESO</span>
              </button>
              <button 
                onClick={() => handleMark('out')}
                className="group py-8 bg-blue-700 hover:bg-blue-800 text-white rounded-3xl shadow-xl transition-all active:scale-95"
              >
                <span className="block text-4xl font-black uppercase mb-1">SALIDA</span>
                <span className="text-blue-300 font-bold text-xs group-hover:text-white">REGISTRAR EGRESO</span>
              </button>
            </div>
            <button 
              onClick={() => { setCurrentEmployee(null); setPin(''); setMessage(null); }}
              className="mt-12 text-gray-400 hover:text-red-500 font-black text-xs uppercase tracking-widest transition-all"
            >
              Cancelar Marcaje
            </button>
          </div>
        ) : (
          <div className="w-full max-w-md text-center">
            <h3 className="text-xs font-black text-gray-400 mb-10 tracking-[0.3em] uppercase">Ingrese su PIN de 6 dígitos para marcar</h3>

            <div className="flex gap-4 justify-center mb-16">
              {[...Array(6)].map((_, i) => (
                <div 
                  key={i}
                  className={`w-14 h-20 border-b-8 flex items-center justify-center text-5xl font-black transition-all duration-300 ${pin.length > i ? 'border-blue-600 text-blue-900 transform -translate-y-2' : 'border-gray-100 text-gray-100'}`}
                >
                  {pin[i] ? '•' : ''}
                </div>
              ))}
            </div>

            {message?.type === 'error' && (
              <div className="mb-10 p-5 bg-red-50 text-red-600 rounded-[2rem] font-black text-xs border-2 border-red-100 uppercase tracking-widest animate-bounce">
                {message.text}
              </div>
            )}

            <div className="grid grid-cols-3 gap-5">
              {[1, 2, 3, 4, 5, 6, 7, 8, 9].map(num => (
                <button 
                  key={num}
                  onClick={() => pin.length < 6 && setPin(p => p + num)}
                  className="w-full h-20 bg-gray-50 hover:bg-blue-600 hover:text-white text-blue-900 text-3xl font-black rounded-[2rem] transition-all border-2 border-transparent hover:shadow-2xl"
                >
                  {num}
                </button>
              ))}
              <button onClick={() => setPin('')} className="w-full h-20 text-red-500 font-black text-sm rounded-[2rem] hover:bg-red-50 transition-all uppercase tracking-widest">Borrar</button>
              <button onClick={() => pin.length < 6 && setPin(p => p + '0')} className="w-full h-20 bg-gray-50 hover:bg-blue-600 hover:text-white text-blue-900 text-3xl font-black rounded-[2rem] border-2 border-transparent">0</button>
              <button onClick={() => setPin(p => p.slice(0, -1))} className="w-full h-20 text-blue-600 flex items-center justify-center hover:bg-blue-50 rounded-[2rem] transition-all"><svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M12 14l2-2m0 0l2-2m-2 2l-2-2m2 2l2 2M3 12l6.414 6.414a2 2 0 001.414.586H19a2 2 0 002-2V7a2 2 0 00-2-2h-8.172a2 2 0 00-1.414.586L3 12z"></path></svg></button>
            </div>
          </div>
        )}
      </div>

      <div className="mt-12 text-white/40 text-[10px] font-black tracking-[0.4em] uppercase">
        Seguridad de Acceso Controlada • Cloud Sync Pro
      </div>
    </div>
  );
};

export default AttendanceSystem;

