               activeTab === 'company' ? 'Identidad Corporativa' : 
               activeTab === 'employees' ? 'Gestión de Talento' : 
               activeTab === 'payroll' ? 'Nómina y Tributación' : 
               activeTab === 'payments' ? 'Tesorería' : 'Configuración Maestra'}
