          <div className="flex flex-col items-end gap-3">
             {currentHoliday && (
               <div className="bg-blue-600 text-white px-6 py-2 rounded-2xl shadow-xl flex items-center gap-3 animate-pulse">
                 <span className="text-xl">🇪🇨</span>
                 <div>
                   <p className="text-[9px] font-black uppercase tracking-widest opacity-80">Festividad Nacional</p>
                   <p className="font-bold text-sm">¡Feliz {currentHoliday.name}!</p>
                 </div>
