                 </div>
               </div>
             )}
          </div>
        </header>

        <div className="animate-in fade-in slide-in-from-bottom-6 duration-500">
          {activeTab === 'dashboard' && (
            <div className="space-y-8">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                <div className="bg-white p-8 rounded-[2.5rem] shadow-sm border border-gray-100 group hover:shadow-xl transition-all">
                  <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] mb-4">Talento Humano</p>
                  <div className="flex items-end justify-between">
                    <div>
                      <span className="text-5xl font-black text-blue-900">{employees.filter(e => e.status === 'active').length}</span>
                      <p className="text-xs font-bold text-gray-500 mt-1 uppercase">Empleados Activos</p>
