      {/* Modal Desvinculación Formal */}
      <Modal isOpen={isTerminationModalOpen} onClose={() => setIsTerminationModalOpen(false)} title="Formulario de Desvinculación Laboral">
        <div className="space-y-6">
          <div>
            <label className="text-[10px] font-black text-gray-500 uppercase">Fecha de Desvinculación</label>
            <input type="date" value={terminationForm.date} onChange={e => setTerminationForm({...terminationForm, date: e.target.value})} className="w-full border-gray-200 border rounded-xl p-3 font-bold" />
