            <div>
              <label className="text-[10px] font-black text-gray-500 uppercase">Argumentar Motivo *</label>
              <textarea value={terminationForm.details} onChange={e => setTerminationForm({...terminationForm, details: e.target.value})} className="w-full border-gray-200 border rounded-xl p-3 min-h-[100px]" placeholder="Justificación obligatoria..." />
