import React, { useState } from 'react';
import { Employee, Role, BloodType, TerminationReason, AttendanceRecord, Payment } from '../../types';
import Modal from '../../components/Modal';

interface EmployeeModuleProps {
  employees: Employee[];
  onUpdate: (employees: Employee[]) => void;
  role: Role;
  attendance: AttendanceRecord[];
  payments: Payment[];
}

const EmployeeModule: React.FC<EmployeeModuleProps> = ({ employees, onUpdate, role, attendance, payments }) => {
  const [isRegisterModalOpen, setIsRegisterModalOpen] = useState(false);
  const [selectedEmployee, setSelectedEmployee] = useState<Employee | null>(null);
  const [isTerminationModalOpen, setIsTerminationModalOpen] = useState(false);
  const [isAbsenceModalOpen, setIsAbsenceModalOpen] = useState(false);

  const [terminationForm, setTerminationForm] = useState({
    date: new Date().toISOString().split('T')[0],
    reason: TerminationReason.VOLUNTARY,
    details: ''
  });

  const [absenceForm, setAbsenceForm] = useState({
    date: new Date().toISOString().split('T')[0],
    reason: '',
    type: 'Falta' as 'Falta' | 'Permiso'
  });

  const [formData, setFormData] = useState<Partial<Employee>>({
    name: '', identification: '', birthDate: '', origin: '', address: '', phone: '', email: '',
    bloodType: BloodType.O_POS, emergencyContact: { name: '', phone: '' }, startDate: new Date().toISOString().split('T')[0],
    role: Role.EMPLOYEE, isFixed: true, salary: 460, isAffiliated: true,
    overSalaryType: 'monthly', bankInfo: { ifi: '', type: 'Ahorros', account: '' },
    photo: '', pin: '', pinChanges: 0, status: 'active', observations: [], justifications: [], totalHoursWorked: 0
  });

  const handleSaveEmployee = () => {
    // Validaciones estrictas según requerimiento
    if (!formData.name || !formData.identification || !formData.phone || !formData.pin || !formData.emergencyContact?.name || !formData.emergencyContact?.phone || !formData.startDate) {
      alert("ERROR: Todos los campos marcados como obligatorios (*) deben ser llenados, incluyendo Fecha de Vinculación y Contacto de Emergencia.");
      return;
    }
    if (formData.pin?.length !== 6) {
      alert("ERROR: El PIN debe ser estrictamente de 6 dígitos.");
      return;
    }
    if (formData.phone?.length !== 10) {
      alert("ERROR: El número de celular debe tener estrictamente 10 dígitos.");
      return;
    }

    // Lógica de Afiliación: Si no es afiliado, bloquear sobre-sueldos
    const finalFormData = { ...formData };
    if (!formData.isAffiliated) {
      finalFormData.overSalaryType = 'none';
    }

    if (formData.id) {
      const newEmployees = employees.map(e => e.id === formData.id ? { ...e, ...finalFormData } as Employee : e);
      onUpdate(newEmployees);
    } else {
      const newEmployee: Employee = {
        ...finalFormData,
        id: Math.random().toString(36).substr(2, 9),
        totalHoursWorked: 0,
        observations: [],
        justifications: [],
        status: 'active'
      } as Employee;
      onUpdate([...employees, newEmployee]);
    }
    setIsRegisterModalOpen(false);
    resetForm();
  };

  const handleTerminate = () => {
    if (!selectedEmployee) return;
    const updatedEmployees = employees.map(e => {
      if (e.id === selectedEmployee.id) {
        return {
          ...e,
          status: 'terminated' as const,
          terminationDate: terminationForm.date,
          terminationReason: terminationForm.reason,
          terminationDetails: terminationForm.reason === TerminationReason.OTHER ? terminationForm.details : terminationForm.reason,
          isFixed: false 
        };
      }
      return e;
    });
    onUpdate(updatedEmployees);
    setIsTerminationModalOpen(false);
    setSelectedEmployee(null);
    alert('Desvinculación procesada. El acceso al sistema ha sido revocado permanentemente.');
    setTimeout(() => window.print(), 500); 
  };

  const handleAddAbsence = () => {
    if (!selectedEmployee || !absenceForm.reason) return;
    const updated = employees.map(e => {
      if (e.id === selectedEmployee.id) {
        return {
          ...e,
          justifications: [...e.justifications, { date: absenceForm.date, reason: absenceForm.reason }]
        };
      }
      return e;
    });
    onUpdate(updated);
    setIsAbsenceModalOpen(false);
    setSelectedEmployee(updated.find(e => e.id === selectedEmployee.id) || null);
  };

  const resetForm = () => {
    setFormData({
      name: '', identification: '', birthDate: '', origin: '', address: '', phone: '', email: '',
      bloodType: BloodType.O_POS, emergencyContact: { name: '', phone: '' }, startDate: new Date().toISOString().split('T')[0],
      role: Role.EMPLOYEE, isFixed: true, salary: 460, isAffiliated: true,
      overSalaryType: 'monthly', bankInfo: { ifi: '', type: 'Ahorros', account: '' },
      photo: '', pin: '', pinChanges: 0, status: 'active', observations: [], justifications: [], totalHoursWorked: 0
    });
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center bg-white p-6 rounded-3xl shadow-sm border border-gray-100 no-print">
        <div className="flex-1">
          <h2 className="text-xl font-bold text-blue-900">Módulo de Talento Humano</h2>
          <p className="text-sm text-gray-500">Registro de empleados y gestión de expedientes</p>
        </div>
        <button 
          onClick={() => { resetForm(); setIsRegisterModalOpen(true); }}
          className="px-8 py-3 bg-blue-700 hover:bg-blue-800 text-white font-bold rounded-2xl shadow-lg transition-all flex items-center gap-2"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6v6m0 0v6m0-6h6m-6 0H6"></path></svg>
          Registrar Empleado
        </button>
      </div>

      <div className="bg-white rounded-[2rem] shadow-sm border border-gray-100 overflow-hidden no-print">
        <table className="w-full text-left">
          <thead className="bg-gray-50 border-b border-gray-100">
            <tr>
              <th className="px-6 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest">Colaborador</th>
              <th className="px-6 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest">Identificación</th>
              <th className="px-6 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest">Estado</th>
              <th className="px-6 py-5 text-right text-[10px] font-black text-gray-400 uppercase tracking-widest">Acciones</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-100">
            {employees.map(emp => (
              <tr key={emp.id} className={`hover:bg-blue-50/50 transition-all ${emp.status === 'terminated' ? 'opacity-50' : ''}`}>
                <td className="px-6 py-4">
                  <div className="flex items-center gap-4">
                    <img src={emp.photo || `https://api.dicebear.com/7.x/avataaars/svg?seed=${emp.name}`} className="w-12 h-12 rounded-2xl border border-gray-100 object-cover" alt="User" />
                    <div>
                      <p className="font-bold text-gray-900">{emp.name}</p>
                      <p className="text-[10px] font-bold text-blue-600 uppercase tracking-wider">{emp.role}</p>
                    </div>
                  </div>
                </td>
                <td className="px-6 py-4 text-sm font-medium text-gray-600">{emp.identification}</td>
                <td className="px-6 py-4">
                  <span className={`px-3 py-1 text-[9px] font-black rounded-full uppercase tracking-widest ${emp.status === 'active' ? 'bg-emerald-100 text-emerald-700' : 'bg-red-100 text-red-700'}`}>
                    {emp.status === 'active' ? 'Activo' : 'Desvinculado'}
                  </span>
                </td>
                <td className="px-6 py-4 text-right">
                  <button onClick={() => setSelectedEmployee(emp)} className="px-4 py-2 bg-blue-50 text-blue-700 font-bold text-xs rounded-xl hover:bg-blue-700 hover:text-white transition-all mr-2">Ver Ficha</button>
                  {emp.status === 'active' && (
                    <button onClick={() => { setFormData(emp); setIsRegisterModalOpen(true); }} className="p-2 text-gray-400 hover:text-blue-600 transition-all"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z"></path></svg></button>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Modal de Registro Integral con todos los campos requeridos */}
      <Modal isOpen={isRegisterModalOpen} onClose={() => setIsRegisterModalOpen(false)} title="Formulario de Datos de Empleado">
        <div className="space-y-6">
          <div className="grid grid-cols-2 gap-4">
            <div className="col-span-2">
              <label className="text-[10px] font-black text-gray-500 uppercase">Nombre y Apellido del Empleado *</label>
              <input value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} className="w-full border-gray-200 border rounded-xl p-3" />
            </div>
            <div>
              <label className="text-[10px] font-black text-gray-500 uppercase">N° Identificación *</label>
              <input value={formData.identification} onChange={e => setFormData({...formData, identification: e.target.value})} className="w-full border-gray-200 border rounded-xl p-3" />
            </div>
            <div>
              <label className="text-[10px] font-black text-gray-500 uppercase">Fecha Nacimiento *</label>
              <input type="date" value={formData.birthDate} onChange={e => setFormData({...formData, birthDate: e.target.value})} className="w-full border-gray-200 border rounded-xl p-3" />
            </div>
            <div>
              <label className="text-[10px] font-black text-gray-500 uppercase">Procedencia</label>
              <input value={formData.origin} onChange={e => setFormData({...formData, origin: e.target.value})} className="w-full border-gray-200 border rounded-xl p-3" />
            </div>
            <div>
              <label className="text-[10px] font-black text-gray-500 uppercase">Celular (10 dígitos) *</label>
              <input maxLength={10} value={formData.phone} onChange={e => setFormData({...formData, phone: e.target.value.replace(/\D/g, '')})} className="w-full border-gray-200 border rounded-xl p-3" />
            </div>
            <div className="col-span-2">
              <label className="text-[10px] font-black text-gray-500 uppercase">Dirección Domicilio</label>
              <input value={formData.address} onChange={e => setFormData({...formData, address: e.target.value})} className="w-full border-gray-200 border rounded-xl p-3" />
            </div>
            <div>
              <label className="text-[10px] font-black text-gray-500 uppercase">Correo Electrónico</label>
              <input type="email" value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} className="w-full border-gray-200 border rounded-xl p-3" />
            </div>
            <div>
               <label className="text-[10px] font-black text-gray-500 uppercase">Tipo de Sangre</label>
               <select value={formData.bloodType} onChange={e => setFormData({...formData, bloodType: e.target.value as any})} className="w-full border-gray-200 border rounded-xl p-3">
                 {Object.values(BloodType).map(t => <option key={t} value={t}>{t}</option>)}
               </select>
            </div>
            <div className="col-span-2 grid grid-cols-2 gap-4">
              <div>
                <label className="text-[10px] font-black text-gray-500 uppercase">Contacto Emergencia (Nombre) *</label>
                <input value={formData.emergencyContact?.name} onChange={e => setFormData({...formData, emergencyContact: { ...formData.emergencyContact!, name: e.target.value }})} className="w-full border-gray-200 border rounded-xl p-3" />
              </div>
              <div>
                <label className="text-[10px] font-black text-gray-500 uppercase">Contacto Emergencia (Teléfono) *</label>
                <input value={formData.emergencyContact?.phone} onChange={e => setFormData({...formData, emergencyContact: { ...formData.emergencyContact!, phone: e.target.value }})} className="w-full border-gray-200 border rounded-xl p-3" />
              </div>
            </div>
            <div>
               <label className="text-[10px] font-black text-gray-500 uppercase">Fecha de Vinculación *</label>
               <input type="date" value={formData.startDate} onChange={e => setFormData({...formData, startDate: e.target.value})} className="w-full border-gray-200 border rounded-xl p-3 font-bold text-blue-800" />
            </div>
            <div>
               <label className="text-[10px] font-black text-gray-500 uppercase">Rol en el Sistema *</label>
               <select value={formData.role} onChange={e => setFormData({...formData, role: e.target.value as Role})} className="w-full border-gray-200 border rounded-xl p-3">
                 {Object.values(Role).map(r => <option key={r} value={r}>{r}</option>)}
               </select>
            </div>
            <div className="col-span-2">
               <label className="text-[10px] font-black text-gray-500 uppercase">PIN de Asistencia (6 dígitos) *</label>
               <input maxLength={6} type="password" value={formData.pin} onChange={e => setFormData({...formData, pin: e.target.value.replace(/\D/g, '')})} className="w-full border-gray-200 border rounded-xl p-3 font-mono tracking-widest" />
            </div>
          </div>

          <div className="bg-blue-50 p-6 rounded-3xl border border-blue-100 space-y-4">
            <h4 className="text-xs font-black text-blue-800 uppercase tracking-widest">Condiciones Laborales</h4>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-[10px] font-black text-blue-500 uppercase">Tipo de Contrato</label>
                <div className="flex gap-4 mt-1">
                  <label className="flex items-center gap-2 text-xs font-bold"><input type="radio" checked={formData.isFixed} onChange={() => setFormData({...formData, isFixed: true})} /> Fijo</label>
                  <label className="flex items-center gap-2 text-xs font-bold"><input type="radio" checked={!formData.isFixed} onChange={() => setFormData({...formData, isFixed: false})} /> Temporal</label>
                </div>
              </div>
              <div>
                <label className="text-[10px] font-black text-blue-500 uppercase">Afiliación IESS</label>
                <div className="flex gap-4 mt-1">
                  <label className="flex items-center gap-2 text-xs font-bold"><input type="radio" checked={formData.isAffiliated} onChange={() => setFormData({...formData, isAffiliated: true})} /> Sí</label>
                  <label className="flex items-center gap-2 text-xs font-bold"><input type="radio" checked={!formData.isAffiliated} onChange={() => setFormData({...formData, isAffiliated: false})} /> No</label>
                </div>
              </div>
              <div>
                <label className="text-[10px] font-black text-blue-500 uppercase">Sueldo</label>
                <input type="number" value={formData.salary} onChange={e => setFormData({...formData, salary: Number(e.target.value)})} className="w-full border-gray-200 border rounded-xl p-3 font-bold" />
              </div>
              <div>
                <label className="text-[10px] font-black text-blue-500 uppercase">Sobre Sueldos</label>
                <select 
                  disabled={!formData.isAffiliated} 
                  value={formData.isAffiliated ? formData.overSalaryType : 'none'} 
                  onChange={e => setFormData({...formData, overSalaryType: e.target.value as any})} 
                  className={`w-full border-gray-200 border rounded-xl p-3 font-bold ${!formData.isAffiliated ? 'bg-gray-100 cursor-not-allowed' : ''}`}
                >
                  <option value="monthly">Mensualiza</option>
                  <option value="accumulate">Acumula</option>
                  <option value="none">Bloqueado</option>
                </select>
              </div>
              <div className="col-span-2">
                <label className="text-[10px] font-black text-blue-500 uppercase">Imagen (URL de Foto)</label>
                <input value={formData.photo} onChange={e => setFormData({...formData, photo: e.target.value})} className="w-full border-gray-200 border rounded-xl p-3" placeholder="https://ejemplo.com/foto.jpg" />
              </div>
            </div>
          </div>
          <button onClick={handleSaveEmployee} className="w-full py-4 bg-blue-700 text-white font-black rounded-2xl shadow-xl hover:bg-blue-800">Guardar Registro Completo</button>
        </div>
      </Modal>

      {/* Ficha Laboral y Desvinculación */}
      {selectedEmployee && (
        <Modal isOpen={!!selectedEmployee} onClose={() => setSelectedEmployee(null)} title={`Ficha Laboral: ${selectedEmployee.name}`}>
          <div className="space-y-6 print:space-y-4">
            <div className="flex gap-6 items-center border-b pb-6">
               <img src={selectedEmployee.photo || `https://api.dicebear.com/7.x/avataaars/svg?seed=${selectedEmployee.name}`} className="w-24 h-24 rounded-3xl border border-gray-100 object-cover" />
               <div className="flex-1 grid grid-cols-2 gap-2 text-xs">
                  <p><span className="font-black text-gray-400 uppercase">Vinculación:</span> <span className="font-bold">{selectedEmployee.startDate}</span></p>
                  <p><span className="font-black text-gray-400 uppercase">Identificación:</span> <span className="font-bold">{selectedEmployee.identification}</span></p>
                  <p><span className="font-black text-gray-400 uppercase">Afiliación:</span> <span className="font-bold">{selectedEmployee.isAffiliated ? 'SÍ' : 'NO'}</span></p>
                  <p><span className="font-black text-gray-400 uppercase">Horas Totales:</span> <span className="font-bold">{selectedEmployee.totalHoursWorked.toFixed(1)} h</span></p>
               </div>
            </div>

            <div className="space-y-2">
               <h5 className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Faltas y Permisos Justificados</h5>
               <div className="bg-gray-50 rounded-2xl p-4 max-h-32 overflow-y-auto">
                 {selectedEmployee.justifications.length > 0 ? selectedEmployee.justifications.map((j, i) => (
                   <p key={i} className="text-[11px] font-bold text-gray-600 mb-1">📅 {j.date}: {j.reason}</p>
                 )) : <p className="text-[11px] text-gray-400 italic">No hay registros de faltas.</p>}
               </div>
               {selectedEmployee.status === 'active' && (
                 <button onClick={() => setIsAbsenceModalOpen(true)} className="text-[10px] font-black text-blue-600 uppercase">+ Registrar Falta/Permiso</button>
               )}
            </div>

            {selectedEmployee.status === 'active' ? (
              <button 
                onClick={() => { if(confirm("ADVERTENCIA: ¿Desea iniciar el proceso de desvinculación? El empleado perderá el acceso.")) setIsTerminationModalOpen(true); }}
                className="w-full py-4 bg-red-50 text-red-600 font-black rounded-2xl border border-red-100 hover:bg-red-600 hover:text-white transition-all"
              >
                DESVINCULAR EMPLEADO
              </button>
            ) : (
              <div className="bg-red-900 text-white p-6 rounded-3xl">
                <h4 className="font-black uppercase text-xs mb-2">Registro de Desvinculación</h4>
                <p className="text-sm font-bold">Fecha: {selectedEmployee.terminationDate}</p>
                <p className="text-sm font-bold">Motivo: {selectedEmployee.terminationReason}</p>
                <p className="text-xs mt-2 opacity-80">{selectedEmployee.terminationDetails}</p>
              </div>
            )}
          </div>
        </Modal>
      )}

      {/* Modal Desvinculación Formal */}
      <Modal isOpen={isTerminationModalOpen} onClose={() => setIsTerminationModalOpen(false)} title="Formulario de Desvinculación Laboral">
        <div className="space-y-6">
          <div>
            <label className="text-[10px] font-black text-gray-500 uppercase">Fecha de Desvinculación</label>
            <input type="date" value={terminationForm.date} onChange={e => setTerminationForm({...terminationForm, date: e.target.value})} className="w-full border-gray-200 border rounded-xl p-3 font-bold" />
          </div>
          <div>
            <label className="text-[10px] font-black text-gray-500 uppercase">Motivo de Desvinculación</label>
            <select value={terminationForm.reason} onChange={e => setTerminationForm({...terminationForm, reason: e.target.value as any})} className="w-full border-gray-200 border rounded-xl p-3 font-bold">
              {Object.values(TerminationReason).map(r => <option key={r} value={r}>{r}</option>)}
            </select>
          </div>
          {terminationForm.reason === TerminationReason.OTHER && (
            <div>
              <label className="text-[10px] font-black text-gray-500 uppercase">Argumentar Motivo *</label>
              <textarea value={terminationForm.details} onChange={e => setTerminationForm({...terminationForm, details: e.target.value})} className="w-full border-gray-200 border rounded-xl p-3 min-h-[100px]" placeholder="Justificación obligatoria..." />
            </div>
          )}
          <button onClick={handleTerminate} className="w-full py-4 bg-red-600 text-white font-black rounded-2xl shadow-xl">Confirmar y Registrar Desvinculación</button>
        </div>
      </Modal>

      {/* Modal Falta/Permiso */}
      <Modal isOpen={isAbsenceModalOpen} onClose={() => setIsAbsenceModalOpen(false)} title="Registrar Falta o Permiso">
        <div className="space-y-4">
           <div>
              <label className="text-[10px] font-black text-gray-500 uppercase">Fecha</label>
              <input type="date" value={absenceForm.date} onChange={e => setAbsenceForm({...absenceForm, date: e.target.value})} className="w-full border-gray-200 border rounded-xl p-3" />
           </div>
           <div>
              <label className="text-[10px] font-black text-gray-500 uppercase">Concepto/Motivo (Obligatorio)</label>
              <textarea value={absenceForm.reason} onChange={e => setAbsenceForm({...absenceForm, reason: e.target.value})} className="w-full border-gray-200 border rounded-xl p-3" />
           </div>
           <button onClick={handleAddAbsence} className="w-full py-3 bg-blue-700 text-white font-black rounded-xl">Registrar</button>
        </div>
      </Modal>
    </div>
  );
};

export default EmployeeModule;

export enum Role {
  SUPER_ADMIN = 'Super Administrador',
  PARTIAL_ADMIN = 'Administrador Parcial',
  EMPLOYEE = 'Empleado'
}

export enum BloodType {
  A_POS = 'A+', A_NEG = 'A-', B_POS = 'B+', B_NEG = 'B-', 
  AB_POS = 'AB+', AB_NEG = 'AB-', O_POS = 'O+', O_NEG = 'O-'
}

export enum TerminationReason {
  VOLUNTARY = 'Renuncia Voluntaria',
  LAYOFF = 'Despido',
  UNILATERAL = 'Terminación unilateral',
  BILATERAL = 'Terminación bilateral',
  VISTO_BUENO = 'Visto Bueno',
  OTHER = 'Otro'
}

export interface CompanyConfig {
  name: string;
  legalRep: string;
  ruc: string;
  address: string;
  phone: string;
  email: string;
  logo: string;
}

export interface Observation {
  date: string;
  text: string;
}

export interface AbsenceJustification {
  date: string;
  documentUrl?: string;
  reason: string;
}

export interface Employee {
  id: string;
  name: string;
  identification: string;
  birthDate: string;
  origin: string;
  address: string;
  phone: string;
  email: string;
  bloodType: BloodType;
  emergencyContact: { name: string; phone: string; };
  startDate: string;
  role: Role;
  isFixed: boolean;
  salary: number;
  isAffiliated: boolean;
  overSalaryType: 'accumulate' | 'monthly' | 'none';
  bankInfo: { ifi: string; type: 'Ahorros' | 'Corriente'; account: string; };
  photo: string;
  pin: string;
  pinChanges: number;
  status: 'active' | 'terminated';
  terminationDate?: string;
  terminationReason?: string;
  terminationDetails?: string;
  totalHoursWorked: number;
  observations: Observation[];
  justifications: AbsenceJustification[];
}

export interface AttendanceRecord {
  id: string;
  employeeId: string;
  timestamp: string;
  type: 'in' | 'out';
}

export interface Payment {
  id: string;
  employeeId: string;
  amount: number;
  date: string;
  month: string;
  year: string;
  type: 'Salary' | 'OverSalary' | 'Loan' | 'Emergency' | 'Bonus' | 'Vacation' | 'Settlement' | 'Compensation';
  overSalaryType?: '13vo' | '14vo' | 'Vacaciones' | 'Fondos de Reserva';
  method: 'Efectivo' | 'Cheque' | 'Transferencia';
  bankSource?: 'Banco del Austro' | 'Banco Guayaquil';
  concept: string;
  status: 'paid' | 'void';
  voidJustification?: string;
  isPartial?: boolean;
  balanceAfter?: number;
}

export interface WorkShift {
  start: string;
  end: string;
  enabled: boolean;
}

export interface DaySchedule {
  morning: WorkShift;
  afternoon: WorkShift;
}

export interface GlobalSettings {
  sbu: number;
  iessRate: number; // 9.45%
  reserveRate: number; // 8.33%
  schedule: {
    weekdays: DaySchedule;
    saturdays: DaySchedule;
  };
}

import React, { useState, useEffect } from 'react';
import { CompanyConfig, Employee, Role, AttendanceRecord, Payment, GlobalSettings } from './types';
import AdminDashboard from './views/AdminDashboard';
import AttendanceSystem from './views/AttendanceSystem';
import { db, collection, doc, onSnapshot, setDoc, addDoc, compressData, decompressData } from './firebase';

const App: React.FC = () => {
  const [currentUserRole, setCurrentUserRole] = useState<Role | null>(null);
  const [view, setView] = useState<'selection' | 'admin' | 'attendance'>('selection');
  const [isLoading, setIsLoading] = useState(true);

  // Data State
  const [company, setCompany] = useState<CompanyConfig | null>(null);
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);
  const [payments, setPayments] = useState<Payment[]>([]);
  const [settings, setSettings] = useState<GlobalSettings>({
    sbu: 460,
    iessRate: 0.0945,
    reserveRate: 0.0833,
    schedule: {
      weekdays: {
        morning: { start: '08:30', end: '13:00', enabled: true },
        afternoon: { start: '14:30', end: '18:30', enabled: true }
      },
      saturdays: {
        morning: { start: '08:30', end: '13:00', enabled: true },
        afternoon: { start: '14:00', end: '18:00', enabled: false }
      }
    }
  });

  // Real-time Subscriptions con manejo de datos comprimidos
  useEffect(() => {
    // Empresa
    const unsubCompany = onSnapshot(doc(db, "config", "company"), (docSnap) => {
      if (docSnap.exists()) {
        const data = docSnap.data();
        setCompany(data.payload ? decompressData(data.payload) : data as CompanyConfig);
      }
      setIsLoading(false);
    });

    // Ajustes
    const unsubSettings = onSnapshot(doc(db, "config", "settings"), (docSnap) => {
      if (docSnap.exists()) {
        const data = docSnap.data();
        const loadedSettings = data.payload ? decompressData(data.payload) : data as GlobalSettings;
        // Merge with defaults to handle new schema fields if needed
        setSettings(prev => ({ ...prev, ...loadedSettings }));
      }
    });

    // Empleados
    const unsubEmployees = onSnapshot(collection(db, "employees"), (snapshot) => {
      const data = snapshot.docs.map(d => {
        const raw = d.data();
        return raw.payload ? { ...decompressData(raw.payload), id: d.id } : { ...raw, id: d.id };
      }) as Employee[];
      setEmployees(data);
    });

    // Asistencia
    const unsubAttendance = onSnapshot(collection(db, "attendance"), (snapshot) => {
      const data = snapshot.docs.map(d => {
        const raw = d.data();
        return raw.payload ? { ...decompressData(raw.payload), id: d.id } : { ...raw, id: d.id };
      }) as AttendanceRecord[];
      setAttendance(data);
    });

    // Pagos
    const unsubPayments = onSnapshot(collection(db, "payments"), (snapshot) => {
      const data = snapshot.docs.map(d => {
        const raw = d.data();
        return raw.payload ? { ...decompressData(raw.payload), id: d.id } : { ...raw, id: d.id };
      }) as Payment[];
      setPayments(data);
    });

    return () => {
      unsubCompany();
      unsubSettings();
      unsubEmployees();
      unsubAttendance();
      unsubPayments();
    };
  }, []);

  // Handlers con Compresión Activa
  const handleRegisterAttendance = async (record: AttendanceRecord) => {
    try {
      const compressedPayload = compressData(record);
      await addDoc(collection(db, "attendance"), { payload: compressedPayload, timestamp: record.timestamp });
    } catch (e) {
      console.error("Error al registrar asistencia comprimida:", e);
    }
  };

  const handleUpdateEmployees = async (newEmployees: Employee[]) => {
    for (const emp of newEmployees) {
      const compressedPayload = compressData(emp);
      await setDoc(doc(db, "employees", emp.id), { payload: compressedPayload });
    }
  };

  const handleUpdateCompany = async (config: CompanyConfig) => {
    const compressedPayload = compressData(config);
    await setDoc(doc(db, "config", "company"), { payload: compressedPayload });
  };

  const handleUpdatePayments = async (newPayments: Payment[]) => {
    for (const pay of newPayments) {
      const compressedPayload = compressData(pay);
      await setDoc(doc(db, "payments", pay.id), { payload: compressedPayload });
    }
  };

  const handleUpdateSettings = async (newSettings: GlobalSettings) => {
    const compressedPayload = compressData(newSettings);
    await setDoc(doc(db, "config", "settings"), { payload: compressedPayload });
  };

  if (view === 'selection') {
    return (
      <div className="min-h-screen gradient-blue flex flex-col items-center justify-center p-4">
        <div className="bg-white p-8 md:p-12 rounded-[2.5rem] shadow-2xl max-w-md w-full text-center fade-in">
          <div className="mb-8 flex justify-center">
            <div className="w-24 h-24 bg-blue-600 rounded-3xl flex items-center justify-center shadow-xl transform -rotate-6 transition-transform hover:rotate-0">
              <span className="text-white text-4xl font-black">A+</span>
            </div>
          </div>
          <h1 className="text-4xl font-black text-blue-900 mb-2 tracking-tight">ASIST UP</h1>
          <p className="text-gray-500 font-medium mb-10">Talento Humano & Asistencia</p>

          <div className="space-y-4">
            <button 
              onClick={() => { setCurrentUserRole(Role.SUPER_ADMIN); setView('admin'); }}
              className="w-full py-4 bg-blue-700 hover:bg-blue-800 text-white font-bold rounded-2xl transition-all shadow-lg active:scale-95"
            >
              Panel Administrativo
            </button>
            <button 
              onClick={() => { setView('attendance'); }}
              className="w-full py-4 border-2 border-blue-600 text-blue-700 hover:bg-blue-50 font-bold rounded-2xl transition-all active:scale-95"
            >
              Reloj de Asistencia
            </button>
