          <div className="mt-10 pt-6 border-t border-gray-100 flex items-center justify-center gap-4">
            <div className="flex items-center gap-2">
              <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></span>
              <span className="text-[10px] text-gray-400 font-black uppercase tracking-[0.2em]">Cloud Sync</span>
            </div>
            <div className="flex items-center gap-2">
              <span className="w-2 h-2 bg-blue-500 rounded-full"></span>
              <span className="text-[10px] text-gray-400 font-black uppercase tracking-[0.2em]">Data Compressed</span>
            </div>
          </div>
