import React, { useState, useEffect } from 'react';
import { CompanyConfig, Employee, Role, AttendanceRecord, Payment, GlobalSettings } from './types';
import AdminDashboard from './views/AdminDashboard';
import AttendanceSystem from './views/AttendanceSystem';
import { db, collection, doc, onSnapshot, setDoc, addDoc, compressData, decompressData } from './firebase';

const App: React.FC = () => {
  const [currentUserRole, setCurrentUserRole] = useState<Role | null>(null);
  const [view, setView] = useState<'selection' | 'admin' | 'attendance'>('selection');
  const [isLoading, setIsLoading] = useState(true);

  // Data State
  const [company, setCompany] = useState<CompanyConfig | null>(null);
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);
  const [payments, setPayments] = useState<Payment[]>([]);
  const [settings, setSettings] = useState<GlobalSettings>({
    sbu: 460,
    iessRate: 0.0945,
    reserveRate: 0.0833,
    schedule: {
      weekdays: {
        morning: { start: '08:30', end: '13:00', enabled: true },
        afternoon: { start: '14:30', end: '18:30', enabled: true }
      },
      saturdays: {
        morning: { start: '08:30', end: '13:00', enabled: true },
        afternoon: { start: '14:00', end: '18:00', enabled: false }
      }
    }
  });

  useEffect(() => {
    const unsubCompany = onSnapshot(doc(db, "config", "company"), (docSnap) => {
      if (docSnap.exists()) {
        const data = docSnap.data();
        setCompany(data.payload ? decompressData(data.payload) : data as CompanyConfig);
      }
      setIsLoading(false);
    });

    const unsubSettings = onSnapshot(doc(db, "config", "settings"), (docSnap) => {
      if (docSnap.exists()) {
        const data = docSnap.data();
        const loadedSettings = data.payload ? decompressData(data.payload) : data as GlobalSettings;
        setSettings(prev => ({ ...prev, ...loadedSettings }));
      }
    });

    const unsubEmployees = onSnapshot(collection(db, "employees"), (snapshot) => {
      const data = snapshot.docs.map(d => {
        const raw = d.data();
        return raw.payload ? { ...decompressData(raw.payload), id: d.id } : { ...raw, id: d.id };
      }) as Employee[];
      setEmployees(data);
    });

    const unsubAttendance = onSnapshot(collection(db, "attendance"), (snapshot) => {
      const data = snapshot.docs.map(d => {
        const raw = d.data();
        return raw.payload ? { ...decompressData(raw.payload), id: d.id } : { ...raw, id: d.id };
      }) as AttendanceRecord[];
      setAttendance(data);
    });

    const unsubPayments = onSnapshot(collection(db, "payments"), (snapshot) => {
      const data = snapshot.docs.map(d => {
        const raw = d.data();
        return raw.payload ? { ...decompressData(raw.payload), id: d.id } : { ...raw, id: d.id };
      }) as Payment[];
      setPayments(data);
    });

    return () => {
      unsubCompany(); unsubSettings(); unsubEmployees(); unsubAttendance(); unsubPayments();
    };
  }, []);

  const handleRegisterAttendance = async (record: AttendanceRecord) => {
    try {
      const compressedPayload = compressData(record);
      await addDoc(collection(db, "attendance"), { payload: compressedPayload, timestamp: record.timestamp });
    } catch (e) {
      console.error("Error al registrar asistencia:", e);
    }
  };

  const handleUpdateEmployees = async (newEmployees: Employee[]) => {
    for (const emp of newEmployees) {
      const compressedPayload = compressData(emp);
      await setDoc(doc(db, "employees", emp.id), { payload: compressedPayload });
    }
  };

  const handleUpdateCompany = async (config: CompanyConfig) => {
    const compressedPayload = compressData(config);
    await setDoc(doc(db, "config", "company"), { payload: compressedPayload });
  };

  const handleUpdatePayments = async (newPayments: Payment[]) => {
    for (const pay of newPayments) {
      const compressedPayload = compressData(pay);
      await setDoc(doc(db, "payments", pay.id), { payload: compressedPayload });
    }
  };

  const handleUpdateSettings = async (newSettings: GlobalSettings) => {
    const compressedPayload = compressData(newSettings);
    await setDoc(doc(db, "config", "settings"), { payload: compressedPayload });
  };

  if (view === 'selection') {
    return (
      <div className="min-h-screen gradient-blue flex flex-col items-center justify-center p-6 relative overflow-hidden">
        {/* Acceso Administrativo Discreto (Candado 20% opacidad) */}
        <button 
          onClick={() => { setCurrentUserRole(Role.SUPER_ADMIN); setView('admin'); }}
          className="absolute top-8 right-8 text-white opacity-20 hover:opacity-100 hover:scale-110 transition-all duration-500 z-50 p-2"
          title="Administración"
        >
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"></path>
          </svg>
        </button>

        <div className="w-full max-w-lg bg-white/95 backdrop-blur-2xl p-12 md:p-16 rounded-[4rem] shadow-[0_32px_64px_-15px_rgba(0,0,0,0.5)] text-center fade-in">
          <div className="mb-12 flex justify-center">
            <div className="w-28 h-28 bg-slate-900 rounded-[2.5rem] flex items-center justify-center shadow-2xl transform transition-all hover:rotate-6 duration-500">
              <span className="text-white text-5xl font-black tracking-tighter">A+</span>
            </div>
          </div>

          <h1 className="text-5xl font-black text-slate-900 mb-3 tracking-tight">ASIST UP</h1>
          <p className="text-slate-500 font-bold uppercase tracking-[0.3em] text-[11px] mb-12">Portal de Colaboradores</p>

          <button 
            onClick={() => { setView('attendance'); }}
            className="w-full py-6 bg-slate-900 text-white font-black rounded-3xl transition-all shadow-xl active:scale-95 hover:bg-blue-600 flex items-center justify-center gap-4 text-lg group"
          >
            <svg className="w-6 h-6 transition-transform group-hover:scale-125" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
            REGISTRAR ASISTENCIA
          </button>

          <div className="mt-16 pt-8 border-t border-slate-100 flex items-center justify-center gap-8">
            <div className="flex items-center gap-3">
              <span className="w-2.5 h-2.5 bg-emerald-500 rounded-full animate-ping"></span>
              <span className="text-[10px] text-slate-400 font-black uppercase tracking-widest">Sincronizado</span>
            </div>
            <div className="flex items-center gap-3">
              <span className="w-2.5 h-2.5 bg-blue-500 rounded-full"></span>
              <span className="text-[10px] text-slate-400 font-black uppercase tracking-widest">Encriptado</span>
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (view === 'attendance') {
    return (
      <AttendanceSystem 
        employees={employees} 
        onRegister={handleRegisterAttendance} 
        onBack={() => setView('selection')}
        onUpdateEmployees={handleUpdateEmployees}
      />
    );
  }

  return (
    <AdminDashboard 
      role={currentUserRole!} 
      onLogout={() => setView('selection')} 
      company={company}
      onUpdateCompany={handleUpdateCompany}
      employees={employees}
      onUpdateEmployees={handleUpdateEmployees}
      attendance={attendance}
      payments={payments}
      onUpdatePayments={handleUpdatePayments}
      settings={settings}
      onUpdateSettings={handleUpdateSettings}
    />
  );
};

export default App;

