import React, { useState, useEffect } from 'react';
import { CompanyConfig, Employee, Role, AttendanceRecord, Payment, GlobalSettings } from './types';
import AdminDashboard from './views/AdminDashboard';
import AttendanceSystem from './views/AttendanceSystem';
import Modal from './components/Modal';
import { db, collection, doc, onSnapshot, setDoc, addDoc, compressData, decompressData } from './firebase';

const App: React.FC = () => {
  const [currentUserRole, setCurrentUserRole] = useState<Role | null>(null);
  const [view, setView] = useState<'selection' | 'admin' | 'attendance'>('selection');
  const [isLoading, setIsLoading] = useState(true);
  const [isAdminLoginModalOpen, setIsAdminLoginModalOpen] = useState(false);
  const [adminPassInput, setAdminPassInput] = useState('');

  // Data State
  const [company, setCompany] = useState<CompanyConfig | null>(null);
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);
  const [payments, setPayments] = useState<Payment[]>([]);
  const [settings, setSettings] = useState<GlobalSettings>({
    sbu: 460,
    iessRate: 0.0945,
    reserveRate: 0.0833,
    schedule: {
      weekdays: {
        morning: { start: '08:30', end: '13:00', enabled: true },
        afternoon: { start: '14:30', end: '18:30', enabled: true }
      },
      saturdays: {
        morning: { start: '08:30', end: '13:00', enabled: true },
        afternoon: { start: '14:00', end: '18:00', enabled: false }
      }
    }
  });

  useEffect(() => {
    const unsubCompany = onSnapshot(doc(db, "config", "company"), (docSnap) => {
      if (docSnap.exists()) {
        const data = docSnap.data();
        setCompany(data.payload ? decompressData(data.payload) : data as CompanyConfig);
      }
      setIsLoading(false);
    });

    const unsubSettings = onSnapshot(doc(db, "config", "settings"), (docSnap) => {
      if (docSnap.exists()) {
        const data = docSnap.data();
        const loadedSettings = data.payload ? decompressData(data.payload) : data as GlobalSettings;
        setSettings(prev => ({ ...prev, ...loadedSettings }));
      }
    });

    const unsubEmployees = onSnapshot(collection(db, "employees"), (snapshot) => {
      const data = snapshot.docs.map(d => {
        const raw = d.data();
        return raw.payload ? { ...decompressData(raw.payload), id: d.id } : { ...raw, id: d.id };
      }) as Employee[];
      setEmployees(data);
    });

    const unsubAttendance = onSnapshot(collection(db, "attendance"), (snapshot) => {
      const data = snapshot.docs.map(d => {
        const raw = d.data();
        return raw.payload ? { ...decompressData(raw.payload), id: d.id } : { ...raw, id: d.id };
      }) as AttendanceRecord[];
      setAttendance(data);
    });

    const unsubPayments = onSnapshot(collection(db, "payments"), (snapshot) => {
      const data = snapshot.docs.map(d => {
        const raw = d.data();
        return raw.payload ? { ...decompressData(raw.payload), id: d.id } : { ...raw, id: d.id };
      }) as Payment[];
      setPayments(data);
    });

    return () => {
      unsubCompany(); unsubSettings(); unsubEmployees(); unsubAttendance(); unsubPayments();
    };
  }, []);

  const handleRegisterAttendance = async (record: AttendanceRecord) => {
    try {
      const compressedPayload = compressData(record);
      await addDoc(collection(db, "attendance"), { payload: compressedPayload, timestamp: record.timestamp });
    } catch (e) {
      console.error("Error al registrar asistencia:", e);
    }
  };

  const handleUpdateEmployees = async (newEmployees: Employee[]) => {
    for (const emp of newEmployees) {
      const compressedPayload = compressData(emp);
      await setDoc(doc(db, "employees", emp.id), { payload: compressedPayload });
    }
  };

  const handleUpdateCompany = async (config: CompanyConfig) => {
    const compressedPayload = compressData(config);
    await setDoc(doc(db, "config", "company"), { payload: compressedPayload });
  };

  const handleUpdatePayments = async (newPayments: Payment[]) => {
    for (const pay of newPayments) {
      const compressedPayload = compressData(pay);
      await setDoc(doc(db, "payments", pay.id), { payload: compressedPayload });
    }
  };

  const handleUpdateSettings = async (newSettings: GlobalSettings) => {
    const compressedPayload = compressData(newSettings);
    await setDoc(doc(db, "config", "settings"), { payload: compressedPayload });
  };

  const handleAdminLogin = () => {
    // Contraseña maestra por defecto
    if (adminPassInput === 'admin123') {
      setCurrentUserRole(Role.SUPER_ADMIN);
      setView('admin');
      setIsAdminLoginModalOpen(false);
      setAdminPassInput('');
    } else if (adminPassInput === 'partial123') {
      setCurrentUserRole(Role.PARTIAL_ADMIN);
      setView('admin');
      setIsAdminLoginModalOpen(false);
      setAdminPassInput('');
    } else {
      alert('Contraseña Incorrecta');
      setAdminPassInput('');
    }
  };

  if (view === 'selection') {
    return (
      <div className="min-h-screen gradient-blue flex flex-col items-center justify-center p-6 relative overflow-hidden">
        {/* Acceso Administrativo Discreto (Candado 20% opacidad) */}
        <button 
          onClick={() => setIsAdminLoginModalOpen(true)}
          className="absolute top-10 right-10 text-white opacity-20 hover:opacity-100 hover:scale-110 transition-all duration-700 z-50 p-2"
          title="Administración"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"></path>
          </svg>
        </button>

        <div className="w-full max-w-lg bg-white/95 backdrop-blur-2xl p-16 md:p-20 rounded-[4rem] shadow-[0_40px_100px_-20px_rgba(0,0,0,0.6)] text-center fade-in border border-white/20">
          <div className="mb-14 flex justify-center">
            {/* Isotipo Profesional Gráfico Sophisticated */}
            <div className="w-32 h-32 bg-gradient-to-br from-slate-800 to-slate-950 rounded-[2.5rem] flex items-center justify-center shadow-[0_20px_50px_rgba(0,0,0,0.4)] ring-1 ring-white/10 logo-shimmer group transform transition-transform duration-700 hover:scale-105">
              <svg viewBox="0 0 100 100" className="w-16 h-16 fill-none stroke-white" strokeWidth="6" strokeLinecap="round" strokeLinejoin="round">
                {/* Barras de crecimiento */}
                <path d="M25 75V60" strokeOpacity="0.3" />
                <path d="M45 75V45" strokeOpacity="0.6" />
                <path d="M65 75V30" strokeOpacity="0.8" />
                {/* Línea de verificación / check ascendente */}
                <path d="M25 55L45 35L60 50L85 15" stroke="#3b82f6" strokeWidth="8" />
              </svg>
            </div>
          </div>

          <h1 className="text-5xl font-[900] text-slate-900 mb-4 tracking-tight">ASIST UP</h1>
          <p className="text-slate-400 font-black uppercase tracking-[0.4em] text-[10px] mb-14 opacity-80">Enterprise Resource Planning</p>

          <button 
            onClick={() => { setView('attendance'); }}
            className="w-full py-6 bg-slate-900 text-white font-[900] rounded-3xl transition-all shadow-[0_20px_40px_-10px_rgba(0,0,0,0.3)] active:scale-95 hover:bg-blue-600 flex items-center justify-center gap-4 text-lg group overflow-hidden relative"
          >
            <span className="relative z-10 flex items-center gap-3">
              <svg className="w-6 h-6 transition-transform group-hover:rotate-12" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
              CONTROL DE ASISTENCIA
            </span>
          </button>

          <div className="mt-16 pt-10 border-t border-slate-100 flex items-center justify-center gap-10">
            <div className="flex items-center gap-3">
              <span className="w-2 h-2 bg-emerald-500 rounded-full"></span>
              <span className="text-[9px] text-slate-400 font-black uppercase tracking-widest">Real-time Sync</span>
            </div>
            <div className="flex items-center gap-3">
              <span className="w-2 h-2 bg-blue-500 rounded-full"></span>
              <span className="text-[9px] text-slate-400 font-black uppercase tracking-widest">AES-256 Cloud</span>
            </div>
          </div>
        </div>

        {/* Modal de Acceso Administrativo */}
        <Modal 
          isOpen={isAdminLoginModalOpen} 
          onClose={() => setIsAdminLoginModalOpen(false)} 
          title="Acceso Administrativo"
          footer={
            <div className="flex gap-2">
              <button onClick={() => setIsAdminLoginModalOpen(false)} className="px-6 py-2 text-gray-400 font-black text-[10px] uppercase">Cancelar</button>
              <button onClick={handleAdminLogin} className="px-8 py-2 bg-blue-600 text-white font-black rounded-xl text-[10px] uppercase">Ingresar</button>
            </div>
          }
        >
          <div className="space-y-4">
            <p className="text-xs text-slate-500 font-medium">Por favor, ingrese la contraseña de acceso para el panel de control:</p>
            <input 
              type="password" 
              value={adminPassInput} 
              onChange={e => setAdminPassInput(e.target.value)} 
              onKeyDown={e => e.key === 'Enter' && handleAdminLogin()}
              className="w-full border-gray-200 border-2 rounded-2xl p-4 text-center text-xl font-black tracking-[0.5em] outline-none focus:border-blue-500"
              placeholder="••••••••"
              autoFocus
            />
            <p className="text-[9px] text-slate-400 font-bold uppercase text-center italic">Cifrado de grado militar activo</p>
          </div>
        </Modal>

        {/* Footer Discreto */}
        <div className="absolute bottom-8 text-white/20 text-[9px] font-black uppercase tracking-[0.5em] select-none">
          Ecuador Industrial Standard Compliance
        </div>
      </div>
    );
  }

  if (view === 'attendance') {
    return (
      <AttendanceSystem 
        employees={employees} 
        onRegister={handleRegisterAttendance} 
        onBack={() => setView('selection')}
        onUpdateEmployees={handleUpdateEmployees}
      />
    );
  }

  return (
    <AdminDashboard 
      role={currentUserRole!} 
      onLogout={() => setView('selection')} 
      company={company}
      onUpdateCompany={handleUpdateCompany}
      employees={employees}
      onUpdateEmployees={handleUpdateEmployees}
      attendance={attendance}
      payments={payments}
      onUpdatePayments={handleUpdatePayments}
      settings={settings}
      onUpdateSettings={handleUpdateSettings}
    />
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Role, CompanyConfig, Employee, AttendanceRecord, Payment, GlobalSettings } from '../types';
import Sidebar from '../components/Sidebar';
import CompanyModule from './modules/CompanyModule';
import EmployeeModule from './modules/EmployeeModule';
import PayrollModule from './modules/PayrollModule';
import PaymentsModule from './modules/PaymentsModule';
import SettingsModule from './modules/SettingsModule';
import { ECUADOR_HOLIDAYS, DAILY_QUOTES, ACTIVE_BREAKS } from '../constants';

interface AdminDashboardProps {
  role: Role;
  onLogout: () => void;
  company: CompanyConfig | null;
  onUpdateCompany: (config: CompanyConfig) => void;
  employees: Employee[];
  onUpdateEmployees: (employees: Employee[]) => void;
  attendance: AttendanceRecord[];
  payments: Payment[];
  onUpdatePayments: (payments: Payment[]) => void;
  settings: GlobalSettings;
  onUpdateSettings: (settings: GlobalSettings) => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  role, onLogout, company, onUpdateCompany, employees, onUpdateEmployees, attendance, payments, onUpdatePayments, settings, onUpdateSettings 
}) => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'company' | 'employees' | 'payroll' | 'payments' | 'settings'>('dashboard');

  const today = useMemo(() => new Date(), []);

  const dayOfYear = useMemo(() => {
    const start = new Date(today.getFullYear(), 0, 0);
    const diff = today.getTime() - start.getTime();
    const oneDay = 1000 * 60 * 60 * 24;
    return Math.floor(diff / oneDay);
  }, [today]);

  const dailyQuote = useMemo(() => DAILY_QUOTES[dayOfYear % DAILY_QUOTES.length], [dayOfYear]);
  const activeBreak = useMemo(() => ACTIVE_BREAKS[dayOfYear % ACTIVE_BREAKS.length], [dayOfYear]);

  const upcomingBirthdays = useMemo(() => {
    return employees.filter(emp => {
      if (emp.status !== 'active') return false;
      const bday = new Date(emp.birthDate);
      const bdayThisYear = new Date(today.getFullYear(), bday.getMonth(), bday.getDate());
      const diff = (bdayThisYear.getTime() - today.getTime()) / (1000 * 3600 * 24);
      return diff >= 0 && diff <= 3;
    });
  }, [employees, today]);

  const currentHoliday = useMemo(() => {
    return ECUADOR_HOLIDAYS.find(h => {
      if (h.duration) {
        return today.getMonth() === h.month && today.getDate() >= h.day && today.getDate() < h.day + h.duration;
      }
      return today.getMonth() === h.month && today.getDate() === h.day;
    });
  }, [today]);

  return (
    <div className="flex h-screen bg-[#fcfdfe] overflow-hidden">
      <Sidebar 
        role={role} 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        onLogout={onLogout} 
        companyName={company?.name}
      />

      <main className="flex-1 overflow-y-auto px-12 py-12 scroll-smooth">
        <header className="flex justify-between items-center mb-16 fade-in">
          <div>
            <h1 className="text-[2.75rem] font-[900] text-slate-900 tracking-tight leading-tight">
              {activeTab === 'dashboard' ? 'Centro de Bienestar' : 
               activeTab === 'company' ? 'Perfil Institucional' : 
               activeTab === 'employees' ? 'Gestión de Talento' : 
               activeTab === 'payroll' ? 'Nómina General' : 
               activeTab === 'payments' ? 'Tesorería' : 'Ajustes Maestros'}
            </h1>
            <div className="flex items-center gap-3 mt-2">
              <span className="px-3 py-1 bg-slate-100 text-slate-500 font-black text-[9px] uppercase tracking-widest rounded-full">{role}</span>
              <span className="w-1.5 h-1.5 bg-emerald-500 rounded-full"></span>
              <span className="text-slate-400 font-bold text-[10px] uppercase tracking-widest">Entorno de Liderazgo Positivo</span>
            </div>
          </div>

          <div className="flex flex-col items-end gap-3">
             {currentHoliday && (
               <div className="bg-slate-900 text-white px-8 py-3 rounded-2xl shadow-2xl flex items-center gap-4 transition-transform hover:scale-105">
                 <span className="text-2xl">🇪🇨</span>
                 <div>
                   <p className="text-[8px] font-black uppercase tracking-[0.2em] opacity-50">Festividad Nacional</p>
                   <p className="font-black text-sm">¡Feliz {currentHoliday.name}!</p>
                 </div>
               </div>
             )}
             {upcomingBirthdays.length > 0 && (
               <div className="bg-emerald-600 text-white px-8 py-3 rounded-2xl shadow-2xl flex items-center gap-4 transition-transform hover:scale-105">
                 <span className="text-2xl">🎂</span>
                 <div>
                   <p className="text-[8px] font-black uppercase tracking-[0.2em] opacity-60">Próximos Cumpleaños</p>
                   <p className="font-black text-sm">{upcomingBirthdays.map(e => e.name).join(', ')}</p>
                 </div>
               </div>
             )}
          </div>
        </header>

        <div className="animate-in fade-in duration-700">
          {activeTab === 'dashboard' && (
            <div className="space-y-12">
              {/* Sección de Frase Diaria - Hero UX Reducido */}
              <div className="bg-white p-10 md:p-12 rounded-[3rem] shadow-[0_30px_60px_-15px_rgba(0,0,0,0.03)] border border-slate-50 relative overflow-hidden group">
                <div className="absolute top-0 right-0 p-8 opacity-[0.02] group-hover:scale-110 transition-transform duration-700">
                   <svg className="w-48 h-48" fill="currentColor" viewBox="0 0 24 24"><path d="M14.017 21L14.017 18C14.017 16.8954 14.9124 16 16.017 16H19.017C19.5693 16 20.017 15.5523 20.017 15V9C20.017 8.44772 19.5693 8 19.017 8H16.017C14.9124 8 14.017 7.10457 14.017 6V3L22.017 3V15C22.017 18.3137 19.3307 21 16.017 21H14.017ZM2.01697 21L2.01697 18C2.01697 16.8954 2.9124 16 4.01697 16H7.01697C7.56925 16 8.01697 15.5523 8.01697 15V9C8.01697 8.44772 7.56925 8 7.01697 8H4.01697C2.9124 8 2.01697 7.10457 2.01697 6V3L10.017 3V15C10.017 18.3137 7.33068 21 4.01697 21H2.01697Z"/></svg>
                </div>
                <div className="relative z-10 max-w-2xl">
                  <p className="text-[10px] font-black text-blue-600 uppercase tracking-[0.3em] mb-4">Reflexión del día</p>
                  <h2 className="text-2xl md:text-3xl font-[800] text-slate-900 leading-[1.2] tracking-tight mb-6 italic">
                    "{dailyQuote}"
                  </h2>
                  <div className="h-1 w-16 bg-blue-600 rounded-full"></div>
                </div>
              </div>

              {/* Grid de Pausas Activas y Mensaje Principal */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                <div className="bg-slate-900 rounded-[3rem] p-10 text-white relative overflow-hidden shadow-2xl flex flex-col justify-center">
