          footer={<button onClick={() => window.print()} className="px-8 py-2 bg-blue-700 text-white rounded-xl font-black text-xs">IMPRIMIR ROL INDIVIDUAL</button>}
        >
          <div className="p-8 text-gray-900 font-medium printable-role">
