        <Modal isOpen={!!selectedEmployee} onClose={() => setSelectedEmployee(null)} title="Ficha Técnica y Historial Laboral">
          <div className="space-y-8 printable-report p-4">
            {/* Encabezado Institucional (Solo Visible en Impresión) */}
