              className="w-full bg-red-50 border border-red-100 rounded-xl p-4 font-black text-center text-2xl tracking-[0.5em] focus:border-red-500 outline-none transition-all"
              placeholder="••••••"
            />
          </div>
        </div>
      </Modal>
    </div>
  );
};

