        <button 
          onClick={() => setIsNewPaymentModalOpen(true)}
          className="px-8 py-4 bg-emerald-600 text-white font-black rounded-2xl shadow-xl hover:bg-emerald-700 transition-all uppercase text-[10px] tracking-widest"
