                  <p className="text-[9px] font-black text-slate-400 uppercase mb-2">Desempeño Anual</p>
                  <p className="mb-1"><b>Horas Totales:</b> {selectedEmployee.totalHoursWorked.toFixed(1)} h</p>
                  <p className="mb-1"><b>Faltas:</b> 0</p>
