import React, { useState } from 'react';
import { Employee, Payment, Role } from '../../types.ts';
import Modal from '../../components/Modal.tsx';

interface PaymentsModuleProps {
  employees: Employee[];
  payments: Payment[];
  onUpdate: (payments: Payment[]) => void;
  role: Role;
}

const PaymentsModule: React.FC<PaymentsModuleProps> = ({ employees, payments, onUpdate, role }) => {
  const [isPayOpen, setIsPayOpen] = useState(false);
  const [payForm, setPayForm] = useState<Partial<Payment>>({
    type: 'Salary', amount: 0, method: 'Efectivo', concept: '', month: new Date().toLocaleString('es-EC', {month: 'long'}).toUpperCase(), year: '2024', status: 'paid'
  });

  const getPendingBalance = (empId: string, type: string) => {
    const emp = employees.find(e => e.id === empId);
    if (!emp) return 0;

    // Simplificación: Solo calculamos sobre el sueldo mensual si es tipo Salary
    if (type !== 'Salary') return 0;

    const paidThisMonth = payments
      .filter(p => p.employeeId === empId && p.month === payForm.month && p.type === 'Salary' && p.status === 'paid')
      .reduce((acc, curr) => acc + curr.amount, 0);

    return Math.max(0, emp.salary - paidThisMonth);
  };

  const handleCreate = () => {
    if (!payForm.employeeId || !payForm.amount) return alert("Seleccione empleado y monto.");

    const balance = getPendingBalance(payForm.employeeId, payForm.type!);
    const newPay: Payment = {
      ...payForm,
      id: Math.random().toString(36).substr(2, 15),
      date: new Date().toISOString(),
      balanceAfter: balance - payForm.amount!,
      isPartial: (balance - payForm.amount!) > 0
    } as Payment;

    onUpdate([newPay, ...payments]);
    setIsPayOpen(false);
    alert("Pago registrado exitosamente.");
  };

  const handleVoid = (id: string) => {
    const reason = prompt("Justificación obligatoria de anulación:");
    if (!reason) return alert("La anulación requiere justificación.");
    onUpdate(payments.map(p => p.id === id ? { ...p, status: 'void', voidJustification: reason } : p));
  };

  return (
    <div className="space-y-6 fade-in">
      <div className="flex justify-between items-center bg-white p-8 rounded-[2rem] shadow-sm border border-slate-100">
        <h2 className="text-2xl font-black text-slate-900 uppercase">Tesorería y Desembolsos</h2>
        <button onClick={() => setIsPayOpen(true)} className="px-8 py-4 bg-emerald-600 text-white font-black rounded-2xl shadow-lg hover:bg-emerald-700 transition-all uppercase text-[10px] tracking-widest">Registrar Pago / Abono</button>
      </div>

      <div className="bg-white rounded-[2rem] shadow-sm border overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest">
            <tr>
              <th className="px-8 py-4">Fecha / Período</th>
              <th className="px-8 py-4">Beneficiario</th>
              <th className="px-8 py-4">Monto</th>
              <th className="px-8 py-4">Saldo Pendiente</th>
              <th className="px-8 py-4">Estado</th>
              <th className="px-8 py-4 text-right">Acción</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {payments.map(p => {
              const emp = employees.find(e => e.id === p.employeeId);
              return (
                <tr key={p.id} className="text-xs hover:bg-slate-50/50">
                  <td className="px-8 py-4">
                    <p className="font-bold">{new Date(p.date).toLocaleDateString()}</p>
                    <p className="text-[9px] uppercase font-black text-slate-400">{p.month}</p>
                  </td>
                  <td className="px-8 py-4 font-black uppercase text-slate-700">
                    {emp?.name || '---'}
                    <span className="block text-[8px] font-normal text-slate-400 italic lowercase">{p.concept}</span>
                  </td>
                  <td className="px-8 py-4 font-black text-slate-900 text-sm">${p.amount.toFixed(2)}</td>
                  <td className="px-8 py-4 font-black text-blue-600">
                    {p.type === 'Salary' ? `$${(p.balanceAfter || 0).toFixed(2)}` : 'N/A'}
                  </td>
                  <td className="px-8 py-4">
                    <span className={`px-2 py-0.5 rounded text-[8px] font-black uppercase ${p.status === 'paid' ? 'bg-emerald-500 text-white' : 'bg-red-500 text-white'}`}>{p.status}</span>
                  </td>
                  <td className="px-8 py-4 text-right">
                    {p.status === 'paid' && <button onClick={() => handleVoid(p.id)} className="text-red-500 font-black text-[10px] uppercase hover:underline">Anular</button>}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      <Modal isOpen={isPayOpen} onClose={() => setIsPayOpen(false)} title="Formulario de Pagos y Abonos">
        <div className="space-y-4">
          <div>
            <label className="text-[9px] font-black uppercase text-slate-400">Seleccionar Empleado</label>
            <select className="w-full border-2 p-3 rounded-xl bg-slate-50 focus:border-blue-500 outline-none" onChange={e => setPayForm({...payForm, employeeId: e.target.value})}>
              <option value="">Beneficiario...</option>
              {employees.filter(e => e.status === 'active').map(e => <option key={e.id} value={e.id}>{e.name}</option>)}
            </select>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="text-[9px] font-black uppercase text-slate-400">Categoría</label>
              <select className="w-full border-2 p-3 rounded-xl bg-slate-50" onChange={e => setPayForm({...payForm, type: e.target.value as any})}>
                <option value="Salary">Sueldo / Abono</option>
                <option value="Loan">Préstamo / Anticipo</option>
                <option value="Bonus">Bono / Gratificación</option>
                <option value="Settlement">Liquidación Haberes</option>
              </select>
            </div>
            <div>
              <label className="text-[9px] font-black uppercase text-slate-400">Forma de Pago</label>
              <select className="w-full border-2 p-3 rounded-xl bg-slate-50" onChange={e => setPayForm({...payForm, method: e.target.value as any})}>
                <option value="Efectivo">Efectivo</option>
                <option value="Transferencia">Transferencia</option>
                <option value="Cheque">Cheque</option>
              </select>
            </div>
          </div>
          {payForm.method === 'Transferencia' && (
             <div>
               <label className="text-[9px] font-black uppercase text-slate-400">Banco de Origen</label>
               <select className="w-full border-2 p-3 rounded-xl bg-slate-50" onChange={e => setPayForm({...payForm, bankSource: e.target.value as any})}>
                  <option value="Banco del Austro">Banco del Austro</option>
                  <option value="Banco Guayaquil">Banco Guayaquil</option>
               </select>
             </div>
          )}
          <div>
            <label className="text-[9px] font-black uppercase text-slate-400">Monto del Pago ($)</label>
            <input type="number" className="w-full border-2 p-3 rounded-xl bg-slate-50 font-black text-xl" onChange={e => setPayForm({...payForm, amount: Number(e.target.value)})} />
          </div>
          <div>
            <label className="text-[9px] font-black uppercase text-slate-400">Concepto del Pago</label>
            <textarea className="w-full border-2 p-3 rounded-xl bg-slate-50 h-20" placeholder="Detalle del movimiento..." onChange={e => setPayForm({...payForm, concept: e.target.value})}></textarea>
          </div>
          <button onClick={handleCreate} className="w-full py-4 bg-emerald-600 text-white font-black rounded-xl uppercase text-xs shadow-xl">Registrar Movimiento</button>
        </div>
      </Modal>
    </div>
  );
};

export default PaymentsModule;

