import React, { useState } from 'react';
import { Employee, Payment, CompanyConfig, GlobalSettings, Role } from '../../types.ts';
import Modal from '../../components/Modal.tsx';

interface PayrollModuleProps {
  employees: Employee[];
  payments: Payment[];
  company: CompanyConfig | null;
  settings: GlobalSettings;
  role: Role;
}

const PayrollModule: React.FC<PayrollModuleProps> = ({ employees, payments, company, settings, role }) => {
  const [selectedMonth, setSelectedMonth] = useState(new Date().toLocaleString('es-EC', {month: 'long'}).toUpperCase());
  const [selectedYear] = useState('2024');
  const [individualPayroll, setIndividualPayroll] = useState<Employee | null>(null);

  const calculatePayrollData = (emp: Employee) => {
    const isAffiliated = emp.isAffiliated;
    const baseSalary = emp.salary;

    // Ingresos
    // Nota: Fondos de reserva solo a partir del 2do año (365 días)
    const startDate = new Date(emp.startDate);
    const today = new Date();
    const diffTime = Math.abs(today.getTime() - startDate.getTime());
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

    const hasRightToReserve = isAffiliated && diffDays >= 365;
    const reserveFund = (hasRightToReserve && emp.overSalaryType === 'monthly') ? (baseSalary * settings.reserveRate) : 0;
    const thirteenth = (isAffiliated && emp.overSalaryType === 'monthly') ? (baseSalary / 12) : 0;
    const fourteenth = (isAffiliated && emp.overSalaryType === 'monthly') ? (settings.sbu / 12) : 0;

    const totalIncome = baseSalary + reserveFund + thirteenth + fourteenth;

    // Egresos
    const iessContribution = isAffiliated ? (baseSalary * settings.iessRate) : 0;
    // Simulación de otros egresos (anticipos o multas registrados en el mes)
    const otherDeductions = payments
      .filter(p => p.employeeId === emp.id && p.month === selectedMonth && p.status === 'paid' && (p.type === 'Loan' || p.type === 'Emergency'))
      .reduce((sum, p) => sum + p.amount, 0);

    const totalExpenses = iessContribution + otherDeductions;

    return { 
      baseSalary, 
      reserveFund, 
      thirteenth, 
      fourteenth, 
      iessContribution, 
      otherDeductions,
      totalIncome, 
      totalExpenses, 
      netToReceive: totalIncome - totalExpenses 
    };
  };

  return (
    <div className="space-y-8 fade-in">
      {/* Panel de Control de Impresión */}
      <div className="flex justify-between items-center bg-white p-8 rounded-[2rem] shadow-sm border border-slate-100 no-print">
        <div>
          <h2 className="text-2xl font-black text-slate-900 tracking-tighter uppercase">Nómina General de Personal</h2>
          <div className="flex gap-4 mt-2">
            <select className="bg-slate-50 border rounded-lg px-4 py-1 text-[10px] font-black uppercase outline-none focus:border-blue-500" value={selectedMonth} onChange={e => setSelectedMonth(e.target.value)}>
              {['ENERO', 'FEBRERO', 'MARZO', 'ABRIL', 'MAYO', 'JUNIO', 'JULIO', 'AGOSTO', 'SEPTIEMBRE', 'OCTUBRE', 'NOVIEMBRE', 'DICIEMBRE'].map(m => <option key={m} value={m}>{m}</option>)}
            </select>
            <span className="text-[10px] font-black text-slate-300 self-center">PDF / EXCEL Habilitado</span>
          </div>
        </div>
        <div className="flex gap-3">
           <button onClick={() => window.print()} className="px-8 py-4 bg-blue-600 text-white font-black rounded-2xl shadow-xl uppercase text-[10px] tracking-widest hover:bg-blue-700 transition-all">Imprimir Rol General A4</button>
        </div>
      </div>

      {/* Diseño de Hoja A4 Horizontal para Impresión */}
      <div className="payroll-container bg-white p-12 rounded-[2rem] shadow-2xl border border-slate-100 print:shadow-none print:border-none print:p-4 mx-auto overflow-x-auto">
        <header className="flex justify-between items-start mb-12 border-b-2 border-slate-900 pb-8">
           <div className="space-y-4">
              <h1 className="text-4xl font-black text-slate-900 leading-none uppercase">ROL DE PAGOS GENERAL <br/> 
                <span className="text-blue-600 text-2xl">{company?.name.toUpperCase() || 'EMPRESA'}</span>
              </h1>
              <div className="grid grid-cols-1 gap-1 text-[11px] font-bold text-slate-600 uppercase">
                <p><span className="text-slate-400">Razón Social:</span> {company?.legalRep.toUpperCase()}</p>
                <p><span className="text-slate-400">RUC:</span> {company?.ruc}</p>
              </div>
           </div>
           <div className="text-right">
              <div className="text-emerald-700 font-black text-4xl uppercase leading-none">
                {selectedMonth}
              </div>
              <div className="text-slate-400 font-black text-xl uppercase tracking-widest">
                {selectedYear}
              </div>
           </div>
        </header>

        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="bg-slate-900 text-white text-[9px] font-black uppercase tracking-widest text-center">
              <th className="border border-slate-700 p-3">Empleado</th>
              <th className="border border-slate-700 p-3">Sueldo Base</th>
              <th className="border border-slate-700 p-3">F. Reserva (8.33%)</th>
              <th className="border border-slate-700 p-3">13vo Mens.</th>
              <th className="border border-slate-700 p-3">14vo Mens.</th>
              <th className="border border-slate-700 p-3 bg-blue-900">Total Ingresos</th>
              <th className="border border-slate-700 p-3">IESS (9.45%)</th>
              <th className="border border-slate-700 p-3">Otros Egresos</th>
              <th className="border border-slate-700 p-3 bg-red-900">Total Egresos</th>
              <th className="border border-slate-700 p-3 font-black text-sm">Neto Recibir</th>
              <th className="border border-slate-700 p-3">Firma del Empleado</th>
            </tr>
          </thead>
          <tbody className="text-[10px] uppercase font-bold text-slate-700">
            {employees.filter(e => e.status === 'active').map(emp => {
              const data = calculatePayrollData(emp);
              const isFixed = emp.isFixed;

              return (
                <tr key={emp.id} className="hover:bg-slate-50 transition-colors">
                  <td className="border border-slate-200 p-3 font-black whitespace-nowrap">{emp.name}</td>
                  <td className="border border-slate-200 p-3 text-right">${data.baseSalary.toFixed(2)}</td>
                  <td className="border border-slate-200 p-3 text-right">{isFixed ? `$${data.reserveFund.toFixed(2)}` : '---'}</td>
                  <td className="border border-slate-200 p-3 text-right">{isFixed ? `$${data.thirteenth.toFixed(2)}` : '---'}</td>
                  <td className="border border-slate-200 p-3 text-right">{isFixed ? `$${data.fourteenth.toFixed(2)}` : '---'}</td>
                  <td className="border border-slate-200 p-3 text-right bg-blue-50/50 font-black text-blue-900">${data.totalIncome.toFixed(2)}</td>
                  <td className="border border-slate-200 p-3 text-right">{isFixed ? `$${data.iessContribution.toFixed(2)}` : '---'}</td>
                  <td className="border border-slate-200 p-3 text-right">${data.otherDeductions.toFixed(2)}</td>
                  <td className="border border-slate-200 p-3 text-right bg-red-50/50 font-black text-red-900">${data.totalExpenses.toFixed(2)}</td>
                  <td className="border border-slate-200 p-3 text-right font-black text-slate-900 text-xs bg-slate-100">${data.netToReceive.toFixed(2)}</td>
                  <td className="border border-slate-200 p-3">
                     <div className="w-full border-b border-slate-400 h-8 flex items-end justify-center">
                        <button onClick={() => setIndividualPayroll(emp)} className="no-print text-[8px] text-blue-500 font-black hover:underline mb-1">Generar Individual</button>
                     </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>

        {/* Líneas de Firma para el Rol General */}
        <div className="mt-20 flex justify-between px-20">
           <div className="text-center">
              <div className="w-64 border-t-2 border-slate-900 pt-2">
                <p className="font-black text-xs uppercase">Firma del Empleador</p>
                <p className="text-[9px] text-slate-400 font-bold uppercase mt-1">Gerente General</p>
              </div>
           </div>
           <div className="text-center">
              <div className="w-64 border-t-2 border-slate-900 pt-2">
                <p className="font-black text-xs uppercase">Firma del Administrador</p>
                <p className="text-[9px] text-slate-400 font-bold uppercase mt-1">Talento Humano</p>
              </div>
           </div>
        </div>
      </div>

      {/* Modal para Rol Individual */}
      <Modal isOpen={!!individualPayroll} onClose={() => setIndividualPayroll(null)} title="Comprobante de Pago Individual">
        {individualPayroll && (
          <div className="p-4 space-y-6">
            <div className="text-center border-b pb-4">
               <h2 className="text-xl font-black text-slate-900 uppercase">Comprobante de Nómina Individual</h2>
               <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest">{company?.name}</p>
            </div>
            <div className="grid grid-cols-2 gap-4 text-xs font-bold uppercase">
               <p>Colaborador: <span className="text-slate-500 font-black">{individualPayroll.name}</span></p>
               <p className="text-right">Período: <span className="text-slate-500 font-black">{selectedMonth} {selectedYear}</span></p>
            </div>

            <div className="bg-slate-50 p-6 rounded-2xl border space-y-3">
               <div className="flex justify-between font-black text-slate-400 text-[10px] uppercase tracking-widest"><span>Descripción de Haberes</span><span>Valor ($)</span></div>
               <hr/>
               <div className="flex justify-between text-xs"><span>Sueldo Base</span><span>{calculatePayrollData(individualPayroll).baseSalary.toFixed(2)}</span></div>
               <div className="flex justify-between text-xs"><span>(+) Fondos de Reserva</span><span>{calculatePayrollData(individualPayroll).reserveFund.toFixed(2)}</span></div>
               <div className="flex justify-between text-xs"><span>(+) Décimo Tercero</span><span>{calculatePayrollData(individualPayroll).thirteenth.toFixed(2)}</span></div>
               <div className="flex justify-between text-xs"><span>(+) Décimo Cuarto</span><span>{calculatePayrollData(individualPayroll).fourteenth.toFixed(2)}</span></div>
               <hr/>
               <div className="flex justify-between text-xs text-red-600"><span>(-) Aporte IESS (9.45%)</span><span>-{calculatePayrollData(individualPayroll).iessContribution.toFixed(2)}</span></div>
               <div className="flex justify-between text-xs text-red-600"><span>(-) Otros Egresos / Multas</span><span>-{calculatePayrollData(individualPayroll).otherDeductions.toFixed(2)}</span></div>
               <hr className="border-slate-900"/>
               <div className="flex justify-between text-lg font-black text-blue-900 uppercase"><span>Neto a Recibir</span><span>${calculatePayrollData(individualPayroll).netToReceive.toFixed(2)}</span></div>
            </div>

            <div className="pt-16 grid grid-cols-2 gap-8 text-center">
               <div className="border-t border-slate-400 pt-2">
                  <p className="text-[9px] font-black uppercase">Administración</p>
               </div>
               <div className="border-t border-slate-400 pt-2">
                  <p className="text-[9px] font-black uppercase">Firma del Recibí Conforme</p>
               </div>
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
};

export default PayrollModule;

import React, { useState, useEffect } from 'react';
import { Employee, AttendanceRecord } from '../types.ts';
import Clock from '../components/Clock.tsx';
import { APP_NAME, MOTIVATIONAL_MESSAGES_START, MOTIVATIONAL_MESSAGES_END, ECUADOR_HOLIDAYS } from '../constants.tsx';

interface AttendanceSystemProps {
  employees: Employee[];
  onRegister: (record: AttendanceRecord) => void;
  onBack: () => void;
  onUpdateEmployees: (employees: Employee[]) => void;
}

const AttendanceSystem: React.FC<AttendanceSystemProps> = ({ employees, onRegister, onBack, onUpdateEmployees }) => {
  const [pin, setPin] = useState('');
  const [status, setStatus] = useState<'idle' | 'confirm' | 'success' | 'error'>('idle');
  const [currentEmp, setCurrentEmp] = useState<Employee | null>(null);
  const [motivationalMsg, setMotivationalMsg] = useState('');

  const today = new Date();
  const currentHoliday = ECUADOR_HOLIDAYS.find(h => h.month === today.getMonth() && h.day === today.getDate());

  const handleMark = (type: 'in' | 'out') => {
    if (!currentEmp) return;

    const record: AttendanceRecord = {
      id: Math.random().toString(36).substr(2, 9),
      employeeId: currentEmp.id,
      timestamp: new Date().toISOString(),
      type
    };

    onRegister(record);

    const msgs = type === 'in' ? MOTIVATIONAL_MESSAGES_START : MOTIVATIONAL_MESSAGES_END;
    setMotivationalMsg(msgs[Math.floor(Math.random() * msgs.length)]);
    setStatus('success');
    setPin('');

    // Bloqueo estricto de 5 segundos tras marcaje
    setTimeout(() => {
      setStatus('idle');
      setCurrentEmp(null);
    }, 5000);
  };

  useEffect(() => {
    if (pin.length === 6 && status === 'idle') {
      const emp = employees.find(e => e.pin === pin && e.status === 'active');
      if (emp) {
        setCurrentEmp(emp);
        setStatus('confirm');
      } else {
        setStatus('error');
        setTimeout(() => { setStatus('idle'); setPin(''); }, 2000);
      }
    }
  }, [pin, employees, status]);

  // Soporte para Teclado Físico habilitado permanentemente
  useEffect(() => {
    const handleKey = (e: KeyboardEvent) => {
      if (status !== 'idle') return;
      if (e.key >= '0' && e.key <= '9' && pin.length < 6) setPin(p => p + e.key);
      if (e.key === 'Backspace') setPin(p => p.slice(0, -1));
    };
    window.addEventListener('keydown', handleKey);
    return () => window.removeEventListener('keydown', handleKey);
  }, [pin, status]);

  return (
    <div className="min-h-screen gradient-blue flex flex-col items-center justify-center p-8">
      <div className="w-full max-w-4xl bg-white/95 backdrop-blur-3xl rounded-[4rem] shadow-2xl p-16 flex flex-col items-center fade-in relative overflow-hidden">

        {/* Notificación de Cumpleaños o Festivos en el sistema de asistencia */}
        {currentHoliday && (
          <div className="absolute top-0 w-full bg-emerald-600 text-white py-2 text-center text-[10px] font-black uppercase tracking-[0.4em]">
            ¡Hoy celebramos: {currentHoliday.name}!
          </div>
        )}

        <h1 className="text-5xl font-black text-slate-900 mb-8 tracking-tighter uppercase italic">{APP_NAME}</h1>
        <div className="mb-14"><Clock /></div>

        {status === 'idle' && (
          <div className="w-full max-w-md text-center">
            <p className="text-[11px] font-black text-slate-400 uppercase tracking-[0.5em] mb-12">DIGITE SU CÓDIGO DE IDENTIDAD</p>
            <div className="flex gap-4 justify-center mb-16">
              {[...Array(6)].map((_, i) => (
                <div key={i} className={`w-14 h-20 border-b-8 flex items-center justify-center text-5xl font-black transition-all duration-300 ${pin.length > i ? 'border-blue-600 text-slate-900 scale-110' : 'border-slate-100'}`}>
                  {pin[i] ? '•' : ''}
                </div>
              ))}
            </div>

            {/* Teclado Visual Aesthetic */}
            <div className="grid grid-cols-3 gap-6">
              {[1, 2, 3, 4, 5, 6, 7, 8, 9, 'C', 0, '←'].map(btn => (
                <button 
                  key={btn}
                  onClick={() => {
                    if (btn === 'C') setPin('');
                    else if (btn === '←') setPin(p => p.slice(0, -1));
                    else if (pin.length < 6) setPin(p => p + btn);
                  }}
                  className="h-20 bg-slate-50 hover:bg-blue-600 hover:text-white rounded-[1.5rem] text-3xl font-black transition-all active:scale-90 shadow-sm hover:shadow-xl"
                >
                  {btn}
                </button>
              ))}
            </div>
          </div>
        )}

        {status === 'confirm' && currentEmp && (
          <div className="text-center animate-in zoom-in duration-300 w-full max-w-lg">
            <div className="mb-8">
               <div className="w-24 h-24 bg-blue-100 rounded-3xl mx-auto flex items-center justify-center text-4xl font-black text-blue-600 uppercase">
                 {currentEmp.name[0]}
               </div>
            </div>
            <h2 className="text-4xl font-black text-slate-900 mb-2 uppercase tracking-tighter leading-tight">{currentEmp.name}</h2>
            <p className="text-slate-400 font-bold uppercase tracking-widest text-xs mb-14 italic">Verificación biométrica por PIN completada</p>
            <div className="grid grid-cols-2 gap-8">
              <button onClick={() => handleMark('in')} className="py-14 bg-emerald-600 text-white rounded-[2.5rem] font-black text-3xl uppercase shadow-2xl hover:bg-emerald-700 transition-all active:scale-95 group relative overflow-hidden">
                <span className="relative z-10">Ingreso</span>
                <div className="absolute inset-0 bg-white/10 translate-y-full group-hover:translate-y-0 transition-transform"></div>
              </button>
              <button onClick={() => handleMark('out')} className="py-14 bg-blue-700 text-white rounded-[2.5rem] font-black text-3xl uppercase shadow-2xl hover:bg-blue-800 transition-all active:scale-95 group relative overflow-hidden">
                <span className="relative z-10">Salida</span>
                <div className="absolute inset-0 bg-white/10 translate-y-full group-hover:translate-y-0 transition-transform"></div>
              </button>
            </div>
          </div>
        )}

        {status === 'success' && (
          <div className="text-center animate-in zoom-in">
            <div className="w-32 h-32 bg-emerald-50 text-emerald-600 rounded-full flex items-center justify-center text-6xl mx-auto mb-10 shadow-inner">✓</div>
            <h2 className="text-4xl font-black text-slate-900 mb-6 italic tracking-tight">"{motivationalMsg}"</h2>
            <p className="text-emerald-600 font-black uppercase tracking-[0.3em] text-sm">Marcaje Registrado Correctamente</p>
            <p className="text-slate-300 text-[10px] mt-12 uppercase font-black animate-pulse">El sistema se reiniciará para el próximo empleado...</p>
          </div>
        )}

        {status === 'error' && (
          <div className="text-center text-red-600 animate-bounce">
            <div className="text-8xl mb-4">✕</div>
            <h2 className="text-3xl font-black uppercase tracking-tighter">ACCESO DENEGADO</h2>
            <p className="font-black text-xs uppercase tracking-widest mt-2">PIN incorrecto o empleado inactivo</p>
          </div>
        )}
      </div>

      <button onClick={onBack} className="mt-12 text-white/40 hover:text-white font-black text-[11px] uppercase tracking-[0.5em] transition-all">Administración ASIST UP</button>
    </div>
  );
};

export default AttendanceSystem;

import React from 'react';
import { createRoot } from 'react-dom/client';
import App from './App.tsx';

const rootElement = document.getElementById('root');
if (rootElement) {
  const root = createRoot(rootElement);
  root.render(
    <React.StrictMode>
      <App />
    </React.StrictMode>
  );

  // Quitar el loader después de que React tome el control
  const loader = document.getElementById('initial-loader');
  if (loader) {
    setTimeout(() => {
      loader.classList.add('hidden');
    }, 100);
  }
}

import React, { useState, useEffect } from 'react';
import { CompanyConfig, Employee, Role, AttendanceRecord, Payment, GlobalSettings } from './types.ts';
import AdminDashboard from './views/AdminDashboard.tsx';
import AttendanceSystem from './views/AttendanceSystem.tsx';
import Modal from './components/Modal.tsx';
import { db, collection, doc, onSnapshot, setDoc, addDoc, compressData, decompressData } from './firebase.ts';

const App: React.FC = () => {
  const [currentUserRole, setCurrentUserRole] = useState<Role | null>(null);
  const [view, setView] = useState<'selection' | 'admin' | 'attendance'>('selection');
  const [isLoading, setIsLoading] = useState(true);
  const [isAdminLoginModalOpen, setIsAdminLoginModalOpen] = useState(false);
  const [adminPassInput, setAdminPassInput] = useState('');

  const [company, setCompany] = useState<CompanyConfig | null>(null);
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);
  const [payments, setPayments] = useState<Payment[]>([]);
  const [settings, setSettings] = useState<GlobalSettings>({
    sbu: 460,
    iessRate: 0.0945,
    reserveRate: 0.0833,
    schedule: {
      weekdays: {
        morning: { start: '08:30', end: '13:00', enabled: true },
        afternoon: { start: '14:30', end: '18:30', enabled: true }
      },
      saturdays: {
        morning: { start: '08:30', end: '13:00', enabled: true },
        afternoon: { start: '14:00', end: '18:00', enabled: false }
      }
    }
  });

  useEffect(() => {
    let activeSnapshots = 0;
    const totalExpected = 4;

    const checkLoaded = () => {
      activeSnapshots++;
      if (activeSnapshots >= totalExpected) {
        setIsLoading(false);
        const loader = document.getElementById('initial-loader');
        if (loader) loader.classList.add('hidden');
      }
    };

    const unsub = [
      onSnapshot(doc(db, "config", "company"), (docSnap) => {
        if (docSnap.exists()) {
          const data = docSnap.data();
          if (data.payload) {
            setCompany(decompressData(data.payload));
          } else {
            const { name, legalRep, ruc, address, phone, email, logo } = data as any;
            setCompany({ name: name || '', legalRep: legalRep || '', ruc: ruc || '', address: address || '', phone: phone || '', email: email || '', logo: logo || '' });
          }
        }
        checkLoaded();
      }, (err) => {
        console.error("Firebase Company Error:", err);
        checkLoaded();
      }),

      onSnapshot(collection(db, "employees"), (snapshot) => {
        setEmployees(snapshot.docs.map(d => {
          const raw = d.data();
          return raw.payload ? { ...decompressData(raw.payload), id: d.id } : { ...raw, id: d.id };
        }) as Employee[]);
        if (activeSnapshots < totalExpected) checkLoaded();
      }),

      onSnapshot(collection(db, "attendance"), (snapshot) => {
        setAttendance(snapshot.docs.map(d => {
          const raw = d.data();
          return raw.payload ? { ...decompressData(raw.payload), id: d.id } : { ...raw, id: d.id };
        }) as AttendanceRecord[]);
        if (activeSnapshots < totalExpected) checkLoaded();
      }),

      onSnapshot(collection(db, "payments"), (snapshot) => {
        setPayments(snapshot.docs.map(d => {
          const raw = d.data();
          return raw.payload ? { ...decompressData(raw.payload), id: d.id } : { ...raw, id: d.id };
        }) as Payment[]);
        if (activeSnapshots < totalExpected) checkLoaded();
      })
    ];

    const safetyTimeout = setTimeout(() => {
      setIsLoading(false);
      const loader = document.getElementById('initial-loader');
      if (loader) loader.classList.add('hidden');
    }, 5000);

    return () => {
      unsub.forEach(u => u());
      clearTimeout(safetyTimeout);
    };
  }, []);

  const handleAdminLogin = () => {
    // Lógica estricta de roles solicitada
    if (adminPassInput === 'admin123') {
      setCurrentUserRole(Role.SUPER_ADMIN);
      setView('admin');
      setIsAdminLoginModalOpen(false);
    } else if (adminPassInput === 'partial123') {
      setCurrentUserRole(Role.PARTIAL_ADMIN);
      setView('admin');
      setIsAdminLoginModalOpen(false);
    } else {
      alert('Clave de acceso incorrecta para el rol seleccionado.');
    }
    setAdminPassInput('');
  };

  if (isLoading) return null;

  if (view === 'selection') {
    return (
      <div className="min-h-screen gradient-blue flex flex-col items-center justify-center p-6 relative">
        <div className="w-full max-w-lg bg-white/95 backdrop-blur-2xl p-16 rounded-[4rem] shadow-2xl text-center fade-in border border-white/20">
          <div className="mb-14 flex justify-center">
            <div className="w-24 h-24 bg-blue-700 rounded-3xl flex items-center justify-center shadow-2xl logo-shimmer border-4 border-blue-500/20">
              <svg viewBox="0 0 100 100" className="w-12 h-12 stroke-white fill-none" strokeWidth="8" strokeLinecap="round"><path d="M20 70L50 40L80 10" strokeWidth="12" /></svg>
            </div>
          </div>
          <h1 className="text-5xl font-[900] text-slate-900 mb-2 tracking-tighter uppercase italic">ASIST UP</h1>
          <p className="text-blue-600 font-black uppercase tracking-[0.5em] text-[9px] mb-12">Talento Humano & Asistencia</p>

          <div className="space-y-4">
            <button 
              onClick={() => setView('attendance')} 
              className="w-full py-6 bg-blue-700 text-white font-black rounded-3xl shadow-xl hover:bg-blue-800 transition-all uppercase text-xs tracking-widest active:scale-95"
            >
              Registro de Asistencia
            </button>
            <button 
              onClick={() => setIsAdminLoginModalOpen(true)} 
              className="w-full py-4 text-slate-400 font-black hover:text-slate-900 transition-all uppercase text-[10px] tracking-widest"
            >
              Acceso Administrativo
            </button>
          </div>
        </div>

        <Modal isOpen={isAdminLoginModalOpen} onClose={() => setIsAdminLoginModalOpen(false)} title="Login Administrativo">
          <div className="space-y-6">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Ingrese PIN de Administrador (Super o Parcial)</p>
            <input 
              type="password" 
              value={adminPassInput} 
              onChange={e => setAdminPassInput(e.target.value)}
              onKeyDown={e => e.key === 'Enter' && handleAdminLogin()}
              className="w-full border-2 border-slate-100 rounded-2xl p-5 text-center text-3xl font-black focus:border-blue-600 outline-none transition-all bg-slate-50"
              placeholder="••••••"
              autoFocus
            />
            <button 
              onClick={handleAdminLogin} 
              className="w-full py-5 bg-blue-700 text-white font-black rounded-2xl uppercase text-xs tracking-widest shadow-lg hover:bg-blue-800 transition-all"
            >
              Entrar al Sistema
            </button>
          </div>
        </Modal>
      </div>
    );
  }

  if (view === 'attendance') {
    return (
      <AttendanceSystem 
        employees={employees} 
        onBack={() => setView('selection')}
        onRegister={async (r) => {
          await addDoc(collection(db, "attendance"), { payload: compressData(r), timestamp: r.timestamp });
        }}
        onUpdateEmployees={async (emps) => {
          for (const e of emps) {
            await setDoc(doc(db, "employees", e.id), { payload: compressData(e) });
          }
        }}
      />
    );
  }

  return (
    <AdminDashboard 
      role={currentUserRole!} 
      onLogout={() => {
        setCurrentUserRole(null);
        setView('selection');
      }} 
      company={company}
      onUpdateCompany={async (c) => await setDoc(doc(db, "config", "company"), { payload: compressData(c) })}
      employees={employees}
      onUpdateEmployees={async (emps) => {
        for (const e of emps) {
          await setDoc(doc(db, "employees", e.id), { payload: compressData(e) });
        }
      }}
      attendance={attendance}
      payments={payments}
      onUpdatePayments={async (pys) => {
        for (const p of pys) {
          if (p.id.length > 15) await addDoc(collection(db, "payments"), { payload: compressData(p) });
          else await setDoc(doc(db, "payments", p.id), { payload: compressData(p) });
        }
      }}
      settings={settings}
      onUpdateSettings={async (s) => await setDoc(doc(db, "config", "settings"), { payload: compressData(s) })}
    />
  );
};

export default App;

