import React, { useState, useEffect } from 'react';
import { CompanyConfig, Employee, Role, AttendanceRecord, Payment, GlobalSettings } from './types.ts';
import AdminDashboard from './views/AdminDashboard.tsx';
import AttendanceSystem from './views/AttendanceSystem.tsx';
import Modal from './components/Modal.tsx';
import { db, collection, doc, onSnapshot, setDoc, addDoc, compressData, decompressData } from './firebase.ts';

const App: React.FC = () => {
  const [currentUserRole, setCurrentUserRole] = useState<Role | null>(null);
  const [view, setView] = useState<'selection' | 'admin' | 'attendance'>('selection');
  const [isLoadingData, setIsLoadingData] = useState(true);
  const [isAdminLoginModalOpen, setIsAdminLoginModalOpen] = useState(false);
  const [adminPassInput, setAdminPassInput] = useState('');

  const [company, setCompany] = useState<CompanyConfig | null>(null);
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);
  const [payments, setPayments] = useState<Payment[]>([]);
  const [settings, setSettings] = useState<GlobalSettings>({
    sbu: 482.00, // ACTUALIZADO SEGÚN REQUERIMIENTO 2026
    iessRate: 0.0945,
    reserveRate: 0.0833,
    schedule: {
      monFri: { in: '08:30', out: '13:00' },
      sat: { in: '08:30', out: '13:00' },
      halfDayOff: 'Miércoles tarde'
    }
  });

  useEffect(() => {
    const rescueTimer = setTimeout(() => setIsLoadingData(false), 6000);
    const unsubscribes: (() => void)[] = [];

    try {
      const unsubCompany = onSnapshot(doc(db, "config", "company"), (docSnap) => {
        if (docSnap.exists()) {
          const data = docSnap.data();
          setCompany(data.payload ? decompressData(data.payload) : data as any);
        }
        setIsLoadingData(false);
        clearTimeout(rescueTimer);
      });
      unsubscribes.push(unsubCompany);

      const unsubEmployees = onSnapshot(collection(db, "employees"), (snapshot) => {
        setEmployees(snapshot.docs.map(d => {
          const raw = d.data();
          return raw.payload ? { ...decompressData(raw.payload), id: d.id } : { ...raw, id: d.id };
        }) as Employee[]);
      });
      unsubscribes.push(unsubEmployees);

      const unsubAttendance = onSnapshot(collection(db, "attendance"), (snapshot) => {
        setAttendance(snapshot.docs.map(d => {
          const raw = d.data();
          return raw.payload ? { ...decompressData(raw.payload), id: d.id } : { ...raw, id: d.id };
        }) as AttendanceRecord[]);
      });
      unsubscribes.push(unsubAttendance);

      const unsubPayments = onSnapshot(collection(db, "payments"), (snapshot) => {
        setPayments(snapshot.docs.map(d => {
          const raw = d.data();
          return raw.payload ? { ...decompressData(raw.payload), id: d.id } : { ...raw, id: d.id };
        }) as Payment[]);
      });
      unsubscribes.push(unsubPayments);
    } catch (e) {
      setIsLoadingData(false);
    }

    return () => { unsubscribes.forEach(unsub => unsub()); clearTimeout(rescueTimer); };
  }, []);

  const handleAdminLogin = () => {
    if (adminPassInput === 'admin123') {
      setCurrentUserRole(Role.SUPER_ADMIN);
      setView('admin');
      setIsAdminLoginModalOpen(false);
    } else if (adminPassInput === 'partial123') {
      setCurrentUserRole(Role.PARTIAL_ADMIN);
      setView('admin');
      setIsAdminLoginModalOpen(false);
    } else { alert('Clave incorrecta.'); }
    setAdminPassInput('');
  };

  if (isLoadingData) return null;

  if (view === 'selection') {
    return (
      <div className="min-h-screen gradient-blue flex flex-col items-center justify-center p-6">
        <div className="w-full max-w-lg bg-white/95 backdrop-blur-2xl p-16 rounded-[4rem] shadow-2xl text-center border border-white/20">
          <div className="mb-14 flex justify-center">
            <div className="w-24 h-24 bg-blue-700 rounded-3xl flex items-center justify-center shadow-2xl border-4 border-blue-500/20 italic font-black text-white text-4xl">AU</div>
          </div>
          <h1 className="text-5xl font-[900] text-slate-900 mb-2 tracking-tighter uppercase italic leading-none">ASIST UP</h1>
          <p className="text-blue-600 font-black uppercase tracking-[0.5em] text-[9px] mb-12">Control de Talento Humano</p>
          <div className="space-y-4">
            <button onClick={() => setView('attendance')} className="w-full py-6 bg-blue-700 text-white font-black rounded-3xl shadow-xl hover:bg-blue-800 transition-all uppercase text-xs tracking-widest active:scale-95">Control de Asistencia</button>
            <button onClick={() => setIsAdminLoginModalOpen(true)} className="w-full py-4 text-slate-400 font-black hover:text-slate-900 transition-all uppercase text-[10px] tracking-widest">Acceso Administrativo</button>
          </div>
        </div>

        <Modal isOpen={isAdminLoginModalOpen} onClose={() => setIsAdminLoginModalOpen(false)} title="Login Administrativo">
          <div className="space-y-6">
            <input type="password" value={adminPassInput} onChange={e => setAdminPassInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleAdminLogin()} className="w-full border-2 border-slate-100 rounded-2xl p-5 text-center text-3xl font-black focus:border-blue-600 outline-none transition-all bg-slate-50" placeholder="••••••" autoFocus />
            <button onClick={handleAdminLogin} className="w-full py-5 bg-blue-700 text-white font-black rounded-2xl uppercase text-xs tracking-widest shadow-lg">Entrar al Sistema</button>
          </div>
        </Modal>
      </div>
    );
  }

  if (view === 'attendance') {
    return <AttendanceSystem employees={employees} onBack={() => setView('selection')} onRegister={async (r) => { await addDoc(collection(db, "attendance"), { payload: compressData(r), timestamp: r.timestamp }); }} onUpdateEmployees={async (emps) => { for (const e of emps) { await setDoc(doc(db, "employees", e.id), { payload: compressData(e) }); } }} />;
  }

  return (
    <AdminDashboard 
      role={currentUserRole!} 
      onLogout={() => { setCurrentUserRole(null); setView('selection'); }} 
      company={company}
      onUpdateCompany={async (c) => await setDoc(doc(db, "config", "company"), { payload: compressData(c) })}
      employees={employees}
      onUpdateEmployees={async (emps) => { for (const e of emps) { await setDoc(doc(db, "employees", e.id), { payload: compressData(e) }); } }}
      attendance={attendance}
      payments={payments}
      onUpdatePayments={async (pys) => { for (const p of pys) { if (p.id.length > 15) await addDoc(collection(db, "payments"), { payload: compressData(p) }); else await setDoc(doc(db, "payments", p.id), { payload: compressData(p) }); } }}
      settings={settings}
      onUpdateSettings={async (s) => await setDoc(doc(db, "config", "settings"), { payload: compressData(s) })}
    />
  );
};

export default App;

import React, { useState } from 'react';
import { Employee, Role, BloodType, TerminationReason, AbsenceRecord, CompanyConfig } from '../../types.ts';
import Modal from '../../components/Modal.tsx';

interface EmployeeModuleProps {
  employees: Employee[];
  onUpdate: (employees: Employee[]) => void;
  role: Role;
  attendance: any[];
  payments: any[];
  company: CompanyConfig | null;
}

const EmployeeModule: React.FC<EmployeeModuleProps> = ({ employees, onUpdate, role, company }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingEmp, setEditingEmp] = useState<Employee | null>(null);
  const [viewingEmp, setViewingEmp] = useState<Employee | null>(null);
  const [isTermModalOpen, setIsTermModalOpen] = useState(false);
  const [isAbsenceModalOpen, setIsAbsenceModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  const initialForm: Partial<Employee> = {
    name: '', surname: '', identification: '', birthDate: '', origin: '', address: '',
    phone: '', email: '', bloodType: BloodType.O_POS,
    emergencyContact: { name: '', phone: '' }, startDate: new Date().toISOString().split('T')[0],
    role: Role.EMPLOYEE, isFixed: true, salary: 482.00, isAffiliated: true, overSalaryType: 'accumulate',
    bankInfo: { ifi: '', type: 'Ahorros', account: '' }, photo: '', pin: '',
    status: 'active', observations: [], absences: [], totalHoursWorked: 0
  };

  const [form, setForm] = useState<Partial<Employee>>(initialForm);

  const validateForm = () => {
    if (!form.name || !form.surname || !form.identification || !form.pin) return "Datos básicos obligatorios faltantes.";
    if (form.pin?.length !== 6) return "PIN debe ser de 6 dígitos estrictamente.";
    if (form.phone?.length !== 10) return "Celular debe tener 10 dígitos.";
    if (form.emergencyContact?.name === '' || form.emergencyContact?.phone === '') return "Contacto de emergencia obligatorio.";
    if (form.isAffiliated === false && form.overSalaryType !== 'none') return "Si no es afiliado, no tiene derecho a sobresueldos.";
    return null;
  };

  const handleSave = () => {
    const error = validateForm();
    if (error) return alert(error);

    let updatedList;
    if (editingEmp) {
      updatedList = employees.map(e => e.id === editingEmp.id ? { ...e, ...form } as Employee : e);
    } else {
      const newEmp = { ...form, id: Math.random().toString(36).substr(2, 9), pinChanges: 0 } as Employee;
      updatedList = [...employees, newEmp];
    }

    onUpdate(updatedList);
    setIsModalOpen(false);
    setEditingEmp(null);
    setForm(initialForm);
    alert("Información guardada.");
  };

  const handleRegisterAbsence = (data: any) => {
    if (!viewingEmp) return;
    const newAbsence: AbsenceRecord = {
      id: Math.random().toString(36).substr(2, 5),
      date: data.date!,
      type: data.type!,
      reason: data.reason!,
      justified: data.justified || false
    };
    const updated = employees.map(e => e.id === viewingEmp.id ? { ...e, absences: [...(e.absences || []), newAbsence] } : e);
    onUpdate(updated);
    setIsAbsenceModalOpen(false);
    alert("Ausencia/Permiso registrado.");
  };

  const handleTermination = (data: any) => {
    if (!viewingEmp) return;
    const updated = employees.map(e => e.id === viewingEmp.id ? {
      ...e,
      status: 'terminated' as const,
      terminationDate: data.date,
      terminationReason: data.reason,
      terminationDetails: data.details
    } : e);
    onUpdate(updated);
    setIsTermModalOpen(false);
    alert("Proceso de desvinculación completado. Imprima el acta.");
    setTimeout(() => window.print(), 500);
  };

  return (
    <div className="space-y-6 fade-in">
      <div className="bg-white p-8 rounded-[2.5rem] shadow-sm border flex justify-between items-center no-print">
        <h2 className="text-3xl font-black text-slate-900 tracking-tighter uppercase">Expedientes de Personal</h2>
        <button onClick={() => { setForm(initialForm); setEditingEmp(null); setIsModalOpen(true); }} className="px-8 py-4 bg-blue-700 text-white font-black rounded-2xl shadow-xl uppercase text-[10px] tracking-widest">Nuevo Registro</button>
      </div>

      <div className="bg-white rounded-[2.5rem] shadow-sm border overflow-hidden no-print">
        <div className="p-6 bg-slate-50 border-b flex gap-4">
          <input type="text" placeholder="Buscar por nombre o ID..." className="flex-1 bg-white border p-3 rounded-xl text-xs font-bold" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
        </div>
        <table className="w-full text-left">
          <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest">
            <tr>
              <th className="px-8 py-4">Foto</th>
              <th className="px-8 py-4">Colaborador</th>
              <th className="px-8 py-4">Rol en Sistema</th>
              <th className="px-8 py-4">Estado</th>
              <th className="px-8 py-4 text-right">Ficha</th>
            </tr>
          </thead>
          <tbody className="divide-y text-xs">
            {employees.filter(e => (e.name + e.surname).toLowerCase().includes(searchTerm.toLowerCase())).map(emp => (
              <tr key={emp.id} className="hover:bg-slate-50 transition-colors">
                <td className="px-8 py-4">
                  <div className="w-10 h-10 rounded-full overflow-hidden bg-slate-100 border">
                    {emp.photo ? <img src={emp.photo} className="w-full h-full object-cover" /> : null}
                  </div>
                </td>
                <td className="px-8 py-4 font-black uppercase text-slate-900">{emp.name} {emp.surname}</td>
                <td className="px-8 py-4 font-bold text-slate-400">{emp.role}</td>
                <td className="px-8 py-4">
                  <span className={`px-2 py-1 rounded-full text-[8px] font-black uppercase ${emp.status === 'active' ? 'bg-emerald-100 text-emerald-700' : 'bg-red-100 text-red-700'}`}>{emp.status}</span>
                </td>
                <td className="px-8 py-4 text-right">
                   <button onClick={() => setViewingEmp(emp)} className="text-blue-600 font-black uppercase hover:underline">Ver Ficha</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Formulario de Registro Integral */}
      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title="Expediente de Talento Humano">
        <div className="space-y-6 max-h-[75vh] overflow-y-auto pr-4 custom-scroll">
           <div className="grid grid-cols-2 gap-6">
              <div className="col-span-2 flex justify-center">
                 <div className="w-32 h-32 rounded-3xl bg-slate-100 border-2 border-dashed border-slate-300 flex items-center justify-center overflow-hidden relative">
                    {form.photo ? <img src={form.photo} className="w-full h-full object-cover" /> : <span className="text-[10px] font-black text-slate-400 uppercase">Subir Foto</span>}
                    <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={(e) => {
                       const file = e.target.files?.[0];
                       if(file) {
                          const reader = new FileReader();
                          reader.onloadend = () => setForm({...form, photo: reader.result as string});
                          reader.readAsDataURL(file);
                       }
                    }} />
                 </div>
              </div>
              <div><label className="text-[9px] font-black uppercase text-slate-400">Nombres</label><input className="w-full border p-3 rounded-xl" value={form.name} onChange={e => setForm({...form, name: e.target.value})} /></div>
              <div><label className="text-[9px] font-black uppercase text-slate-400">Apellidos</label><input className="w-full border p-3 rounded-xl" value={form.surname} onChange={e => setForm({...form, surname: e.target.value})} /></div>
              <div><label className="text-[9px] font-black uppercase text-slate-400">Cédula / ID</label><input className="w-full border p-3 rounded-xl" value={form.identification} onChange={e => setForm({...form, identification: e.target.value})} /></div>
              <div><label className="text-[9px] font-black uppercase text-slate-400">PIN Asistencia (6 dígitos)</label><input maxLength={6} className="w-full border-2 border-blue-500 p-3 rounded-xl text-center font-black text-xl" value={form.pin} onChange={e => setForm({...form, pin: e.target.value.replace(/\D/g,'')})} /></div>
              <div><label className="text-[9px] font-black uppercase text-slate-400">Fecha Nacimiento</label><input type="date" className="w-full border p-3 rounded-xl" value={form.birthDate} onChange={e => setForm({...form, birthDate: e.target.value})} /></div>
              <div><label className="text-[9px] font-black uppercase text-slate-400">Procedencia</label><input className="w-full border p-3 rounded-xl" value={form.origin} onChange={e => setForm({...form, origin: e.target.value})} /></div>
              <div className="col-span-2"><label className="text-[9px] font-black uppercase text-slate-400">Dirección Domicilio</label><input className="w-full border p-3 rounded-xl" value={form.address} onChange={e => setForm({...form, address: e.target.value})} /></div>
              <div><label className="text-[9px] font-black uppercase text-slate-400">Celular (10 dígitos)</label><input maxLength={10} className="w-full border p-3 rounded-xl" value={form.phone} onChange={e => setForm({...form, phone: e.target.value.replace(/\D/g,'')})} /></div>
              <div><label className="text-[9px] font-black uppercase text-slate-400">Email</label><input type="email" className="w-full border p-3 rounded-xl" value={form.email} onChange={e => setForm({...form, email: e.target.value})} /></div>
              <div><label className="text-[9px] font-black uppercase text-slate-400">Tipo Sangre</label>
                 <select className="w-full border p-3 rounded-xl" value={form.bloodType} onChange={e => setForm({...form, bloodType: e.target.value as BloodType})}>
                    {Object.values(BloodType).map(t => <option key={t} value={t}>{t}</option>)}
                 </select>
              </div>
              <div><label className="text-[9px] font-black uppercase text-slate-400">Rol Sistema</label>
                 <select className="w-full border p-3 rounded-xl" value={form.role} onChange={e => setForm({...form, role: e.target.value as Role})}>
                    {Object.values(Role).map(r => <option key={r} value={r}>{r}</option>)}
                 </select>
              </div>
              <div className="col-span-2 bg-blue-50 p-6 rounded-3xl border border-blue-100">
                 <h4 className="text-[10px] font-black text-blue-800 uppercase tracking-widest mb-4">Condiciones Laborales y Bancarias</h4>
                 <div className="grid grid-cols-2 gap-4">
                    <div><label className="text-[9px] font-black uppercase">Contrato</label><select className="w-full border p-2 rounded-lg" value={form.isFixed ? 'f' : 't'} onChange={e => setForm({...form, isFixed: e.target.value === 'f'})}><option value="f">Fijo</option><option value="t">Temporal</option></select></div>
                    <div><label className="text-[9px] font-black uppercase">Sueldo ($)</label><input type="number" className="w-full border p-2 rounded-lg" value={form.salary} onChange={e => setForm({...form, salary: Number(e.target.value)})} /></div>
                    <div><label className="text-[9px] font-black uppercase">Afiliación IESS</label><select className="w-full border p-2 rounded-lg" value={form.isAffiliated ? 'si' : 'no'} onChange={e => {const isA = e.target.value === 'si'; setForm({...form, isAffiliated: isA, overSalaryType: isA ? 'accumulate' : 'none'})}}><option value="si">Sí</option><option value="no">No</option></select></div>
                    <div><label className="text-[9px] font-black uppercase">Sobresueldos</label><select disabled={!form.isAffiliated} className="w-full border p-2 rounded-lg disabled:bg-slate-200" value={form.overSalaryType} onChange={e => setForm({...form, overSalaryType: e.target.value as any})}><option value="accumulate">Acumula</option><option value="monthly">Mensualiza</option><option value="none">No tiene derecho</option></select></div>
                    <div className="col-span-2 grid grid-cols-3 gap-2">
                       <div><label className="text-[8px] font-black uppercase">IFI (Banco)</label><input className="w-full border p-2 rounded-lg" value={form.bankInfo?.ifi} onChange={e => setForm({...form, bankInfo: {...form.bankInfo!, ifi: e.target.value}})} /></div>
                       <div><label className="text-[8px] font-black uppercase">Tipo Cuenta</label><select className="w-full border p-2 rounded-lg" value={form.bankInfo?.type} onChange={e => setForm({...form, bankInfo: {...form.bankInfo!, type: e.target.value as any}})}><option value="Ahorros">Ahorros</option><option value="Corriente">Corriente</option></select></div>
                       <div><label className="text-[8px] font-black uppercase"># Cuenta</label><input className="w-full border p-2 rounded-lg" value={form.bankInfo?.account} onChange={e => setForm({...form, bankInfo: {...form.bankInfo!, account: e.target.value}})} /></div>
                    </div>
                 </div>
              </div>
              <div className="col-span-2 border-t pt-4">
                 <h4 className="text-[10px] font-black text-slate-400 uppercase mb-2">Contacto Emergencia (Obligatorio)</h4>
                 <div className="grid grid-cols-2 gap-4">
                    <input placeholder="Nombre Completo" className="w-full border p-3 rounded-xl" value={form.emergencyContact?.name} onChange={e => setForm({...form, emergencyContact: {...form.emergencyContact!, name: e.target.value}})} />
                    <input placeholder="Teléfono" className="w-full border p-3 rounded-xl" value={form.emergencyContact?.phone} onChange={e => setForm({...form, emergencyContact: {...form.emergencyContact!, phone: e.target.value}})} />
                 </div>
              </div>
           </div>
           <button onClick={handleSave} className="w-full py-5 bg-blue-700 text-white font-black rounded-3xl shadow-xl uppercase text-xs">Guardar Expediente Maestro</button>
        </div>
      </Modal>

      {/* Ficha Laboral Integral e Historial (Imprimible) */}
      <Modal isOpen={!!viewingEmp} onClose={() => setViewingEmp(null)} title="Ficha Laboral Integral">
        {viewingEmp && (
          <div className="space-y-8 print:p-0">
             <header className="flex gap-8 items-center bg-slate-900 p-10 rounded-[2.5rem] text-white print:bg-white print:text-black print:border-b-2 print:border-black print:rounded-none">
                <div className="w-28 h-28 rounded-3xl overflow-hidden border-4 border-white/20 print:border-black">
                   {viewingEmp.photo && <img src={viewingEmp.photo} className="w-full h-full object-cover" />}
                </div>
                <div className="flex-1">
                   <h1 className="text-3xl font-black uppercase tracking-tighter leading-none mb-2">{viewingEmp.name} {viewingEmp.surname}</h1>
                   <p className="text-blue-400 font-black text-xs uppercase tracking-widest print:text-black">ID: {viewingEmp.identification} • Sangre: {viewingEmp.bloodType}</p>
                   <div className="flex gap-3 mt-6 no-print">
                      <span className="px-3 py-1 bg-white/10 rounded-full text-[9px] font-black uppercase tracking-widest">Ingreso: {viewingEmp.startDate}</span>
                      <span className={`px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest ${viewingEmp.status === 'active' ? 'bg-emerald-500' : 'bg-red-500'}`}>{viewingEmp.status}</span>
                   </div>
                </div>
                <div className="no-print"><button onClick={() => window.print()} className="p-4 bg-white/10 rounded-2xl hover:bg-white/20 transition-all">🖨️</button></div>
             </header>

             <div className="grid grid-cols-2 gap-8 print:grid-cols-1">
                <section className="space-y-4">
                   <h3 className="text-[11px] font-black text-blue-700 uppercase tracking-widest border-b pb-2">Información de Contacto</h3>
                   <div className="text-xs space-y-2">
                      <p className="flex justify-between"><span>Teléfono:</span> <span className="font-black">{viewingEmp.phone}</span></p>
                      <p className="flex justify-between"><span>Email:</span> <span className="font-black">{viewingEmp.email}</span></p>
                      <p className="flex justify-between"><span>Dirección:</span> <span className="font-black text-right">{viewingEmp.address}</span></p>
                      <p className="flex justify-between mt-4 text-[10px] font-black text-slate-400">EMERGENCIA: {viewingEmp.emergencyContact?.name} ({viewingEmp.emergencyContact?.phone})</p>
                   </div>
                </section>
                <section className="space-y-4">
                   <h3 className="text-[11px] font-black text-blue-700 uppercase tracking-widest border-b pb-2">Condiciones Contractuales</h3>
                   <div className="text-xs space-y-2">
                      <p className="flex justify-between"><span>Tipo de Personal:</span> <span className="font-black">{viewingEmp.isFixed ? 'Fijo / Indefinido' : 'Temporal / Eventual'}</span></p>
                      <p className="flex justify-between"><span>Sueldo Mensual:</span> <span className="font-black text-lg text-emerald-600">${viewingEmp.salary.toFixed(2)}</span></p>
                      <p className="flex justify-between"><span>IESS:</span> <span className="font-black">{viewingEmp.isAffiliated ? 'Afiliado' : 'No Afiliado'}</span></p>
                      <p className="flex justify-between"><span>Sobresueldos:</span> <span className="font-black">{viewingEmp.overSalaryType === 'accumulate' ? 'Acumula' : viewingEmp.overSalaryType === 'monthly' ? 'Mensualiza' : 'No'}</span></p>
                   </div>
                </section>
             </div>

             <section className="bg-slate-50 p-6 rounded-3xl border print:border-black print:bg-white">
                <h3 className="text-[11px] font-black text-slate-500 uppercase tracking-widest mb-4">Historial de Marcajes y Ausencias</h3>
                <div className="text-[10px] font-bold">
                   <p>Días de faltas acumulados al año: <span className="text-red-600">{viewingEmp.absences?.filter(a => a.type === 'Falta').length || 0}</span></p>
                   <p>Atrasos registrados: <span className="text-orange-600">{viewingEmp.absences?.filter(a => a.type === 'Atraso').length || 0}</span></p>
                   <p className="text-xs mt-2 border-t pt-2">Total de horas trabajadas (Corte hoy): <span className="font-black text-blue-600">{viewingEmp.totalHoursWorked || 0} horas</span></p>
                </div>
             </section>

             <div className="flex gap-4 no-print">
                {viewingEmp.status === 'active' && (
                  <button onClick={() => { setIsTermModalOpen(true); }} className="flex-1 py-4 bg-red-600 text-white font-black rounded-2xl uppercase text-[10px] shadow-lg">Iniciar Desvinculación</button>
                )}
                <button onClick={() => { setEditingEmp(viewingEmp); setForm(viewingEmp); setIsModalOpen(true); setViewingEmp(null); }} className="flex-1 py-4 bg-slate-900 text-white font-black rounded-2xl uppercase text-[10px] shadow-lg">Editar Información</button>
             </div>
          </div>
        )}
      </Modal>

      {/* Modal Desvinculación - Formulario Legal Imprimible */}
      <Modal isOpen={isTermModalOpen} onClose={() => setIsTermModalOpen(false)} title="Confirmación de Desvinculación">
         <div className="space-y-6">
            <div className="p-5 bg-red-50 border border-red-200 text-red-800 rounded-2xl text-[10px] font-black uppercase italic leading-relaxed text-center">
               ADVERTENCIA: Esta acción es irreversible, bloqueará el acceso al sistema y dará de baja al empleado de los registros activos.
            </div>
            <div className="space-y-4">
               <div><label className="text-[9px] font-black uppercase">Fecha de Salida</label><input type="date" id="t_date" className="w-full border p-3 rounded-xl" defaultValue={new Date().toISOString().split('T')[0]} /></div>
               <div><label className="text-[9px] font-black uppercase">Motivo Legal</label>
                  <select id="t_reason" className="w-full border p-3 rounded-xl">
                     {Object.values(TerminationReason).map(r => <option key={r} value={r}>{r}</option>)}
                  </select>
               </div>
               <div><label className="text-[9px] font-black uppercase">Argumentación / Observaciones</label><textarea id="t_details" className="w-full border p-3 rounded-xl h-24" placeholder="Detalle el motivo del cese de funciones..."></textarea></div>
               <button onClick={() => {
                  const date = (document.getElementById('t_date') as HTMLInputElement).value;
                  const reason = (document.getElementById('t_reason') as HTMLSelectElement).value;
                  const details = (document.getElementById('t_details') as HTMLTextAreaElement).value;
                  if (reason === 'Otro' && !details) return alert("Debe argumentar el motivo.");
                  handleTermination({ date, reason, details });
               }} className="w-full py-5 bg-red-600 text-white font-black rounded-3xl uppercase text-xs shadow-xl">Registrar Baja Laboral</button>
            </div>
         </div>
      </Modal>
    </div>
  );
};

export default EmployeeModule;

import React, { useState, useMemo, useEffect } from 'react';
import { Role, CompanyConfig, Employee, AttendanceRecord, Payment, GlobalSettings } from '../types.ts';
import Sidebar from '../components/Sidebar.tsx';
import CompanyModule from './modules/CompanyModule.tsx';
import EmployeeModule from './modules/EmployeeModule.tsx';
import PayrollModule from './modules/PayrollModule.tsx';
import PaymentsModule from './modules/PaymentsModule.tsx';
import SettingsModule from './modules/SettingsModule.tsx';
import ReportsModule from './modules/ReportsModule.tsx';
import Modal from '../components/Modal.tsx';
import { ECUADOR_HOLIDAYS, DAILY_QUOTES, ACTIVE_BREAKS } from '../constants.tsx';

interface AdminDashboardProps {
  role: Role;
  onLogout: () => void;
  company: CompanyConfig | null;
  onUpdateCompany: (config: CompanyConfig) => void;
  employees: Employee[];
  onUpdateEmployees: (employees: Employee[]) => void;
  attendance: AttendanceRecord[];
  payments: Payment[];
  onUpdatePayments: (payments: Payment[]) => void;
  settings: GlobalSettings;
  onUpdateSettings: (settings: GlobalSettings) => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  role, onLogout, company, onUpdateCompany, employees, onUpdateEmployees, attendance, payments, onUpdatePayments, settings, onUpdateSettings 
}) => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'company' | 'employees' | 'payroll' | 'payments' | 'settings' | 'reports'>('dashboard');
  const [isBackupReminderOpen, setIsBackupReminderOpen] = useState(false);

  const today = useMemo(() => new Date(), []);

  const dayOfYear = useMemo(() => {
    const start = new Date(today.getFullYear(), 0, 0);
    const diff = today.getTime() - start.getTime();
    const oneDay = 1000 * 60 * 60 * 24;
    return Math.floor(diff / oneDay);
  }, [today]);

  const dailyQuote = useMemo(() => DAILY_QUOTES[dayOfYear % DAILY_QUOTES.length], [dayOfYear]);
  const activeBreak = useMemo(() => ACTIVE_BREAKS[dayOfYear % ACTIVE_BREAKS.length], [dayOfYear]);

  useEffect(() => {
    const lastBackup = localStorage.getItem('lastBackupDate');
    if (lastBackup) {
      const lastDate = new Date(lastBackup);
      const diffTime = Math.abs(today.getTime() - lastDate.getTime());
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      if (diffDays >= 15) {
        setIsBackupReminderOpen(true);
      }
    } else {
      localStorage.setItem('lastBackupDate', today.toISOString());
    }
  }, [today]);

  const upcomingBirthdays = useMemo(() => {
    return employees.filter(emp => {
      if (emp.status !== 'active') return false;
      const bday = new Date(emp.birthDate);
      const bdayThisYear = new Date(today.getFullYear(), bday.getMonth(), bday.getDate());
      const diff = (bdayThisYear.getTime() - today.getTime()) / (1000 * 3600 * 24);
      return diff >= 0 && diff <= 3;
    });
  }, [employees, today]);

  const currentHoliday = useMemo(() => {
    return ECUADOR_HOLIDAYS.find(h => {
      if (h.duration) {
        return today.getMonth() === h.month && today.getDate() >= h.day && today.getDate() < h.day + h.duration;
      }
      return today.getMonth() === h.month && today.getDate() === h.day;
    });
  }, [today]);

  const handleGoToBackup = () => {
    setIsBackupReminderOpen(false);
    setActiveTab('settings');
  };

  return (
    <div className="flex h-screen bg-[#fcfdfe] overflow-hidden">
      <Sidebar 
        role={role} 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        onLogout={onLogout} 
        companyName={company?.name}
      />

      <main className="flex-1 overflow-y-auto px-12 py-12 scroll-smooth">
        <header className="flex justify-between items-center mb-16 fade-in no-print">
          <div>
            <h1 className="text-[2.75rem] font-[900] text-slate-900 tracking-tight leading-tight">
              {activeTab === 'dashboard' ? 'Centro de Bienestar' : 
               activeTab === 'company' ? 'Perfil Institucional' : 
               activeTab === 'employees' ? 'Gestión de Talento' : 
               activeTab === 'payroll' ? 'Nómina General' : 
               activeTab === 'payments' ? 'Tesorería' : 
               activeTab === 'reports' ? 'Centro de Reportes' : 'Ajustes Maestros'}
            </h1>
            <div className="flex items-center gap-3 mt-2">
              <span className="px-3 py-1 bg-slate-100 text-slate-500 font-black text-[9px] uppercase tracking-widest rounded-full">{role}</span>
              <span className="w-1.5 h-1.5 bg-emerald-500 rounded-full"></span>
              <span className="text-slate-400 font-bold text-[10px] uppercase tracking-widest">Entorno de Liderazgo Positivo</span>
            </div>
          </div>

          <div className="flex flex-col items-end gap-3">
             {currentHoliday && (
               <div className="bg-slate-900 text-white px-8 py-3 rounded-2xl shadow-2xl flex items-center gap-4 transition-transform hover:scale-105">
                 <span className="text-2xl">🇪🇨</span>
                 <div>
                   <p className="text-[8px] font-black uppercase tracking-[0.2em] opacity-50">Festividad Nacional</p>
                   <p className="font-black text-sm">¡Feliz {currentHoliday.name}!</p>
                 </div>
               </div>
             )}
             {upcomingBirthdays.length > 0 && (
               <div className="bg-emerald-600 text-white px-8 py-3 rounded-2xl shadow-2xl flex items-center gap-4 transition-transform hover:scale-105">
                 <span className="text-2xl">🎂</span>
                 <div>
                   <p className="text-[8px] font-black uppercase tracking-[0.2em] opacity-60">Próximos Cumpleaños</p>
                   <p className="font-black text-sm">{upcomingBirthdays.map(e => e.name).join(', ')}</p>
                 </div>
               </div>
             )}
          </div>
        </header>

        <div className="animate-in fade-in duration-700">
          {activeTab === 'dashboard' && (
            <div className="space-y-12 no-print">
              <div className="bg-white p-10 md:p-12 rounded-[3rem] shadow-[0_30px_60px_-15px_rgba(0,0,0,0.03)] border border-slate-50 relative overflow-hidden group">
                <div className="absolute top-0 right-0 p-8 opacity-[0.02] group-hover:scale-110 transition-transform duration-700">
                   <svg className="w-48 h-48" fill="currentColor" viewBox="0 0 24 24"><path d="M14.017 21L14.017 18C14.017 16.8954 14.9124 16 16.017 16H19.017C19.5693 16 20.017 15.5523 20.017 15V9C20.017 8.44772 19.5693 8 19.017 8H16.017C14.9124 8 14.017 7.10457 14.017 6V3L22.017 3V15C22.017 18.3137 19.3307 21 16.017 21H14.017ZM2.01697 21L2.01697 18C2.01697 16.8954 2.9124 16 4.01697 16H7.01697C7.56925 16 8.01697 15.5523 8.01697 15V9C8.01697 8.44772 7.56925 8 7.01697 8H4.01697C2.9124 8 2.01697 7.10457 2.01697 6V3L10.017 3V15C10.017 18.3137 7.33068 21 4.01697 21H2.01697Z"/></svg>
                </div>
                <div className="relative z-10 max-w-2xl">
                  <p className="text-[10px] font-black text-blue-600 uppercase tracking-[0.3em] mb-4">Reflexión del día</p>
                  <h2 className="text-2xl md:text-3xl font-[800] text-slate-900 leading-[1.2] tracking-tight mb-6 italic">
                    "{dailyQuote}"
                  </h2>
                  <div className="h-1 w-16 bg-blue-600 rounded-full"></div>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                <div className="bg-slate-900 rounded-[3rem] p-10 text-white relative overflow-hidden shadow-2xl flex flex-col justify-center">
                   <div className="relative z-10">
                      <h2 className="text-3xl font-[900] mb-4 tracking-tighter uppercase italic text-blue-400">Cultura ASIST UP</h2>
                      <p className="text-slate-400 mb-8 text-base font-medium leading-relaxed">El éxito de una empresa no se mide solo en números, sino en el bienestar y la motivación de quienes la construyen día a día.</p>
                      <button onClick={() => setActiveTab('employees')} className="px-10 py-4 bg-white text-slate-900 font-[900] rounded-2xl hover:bg-slate-100 transition-all shadow-xl uppercase text-[10px] tracking-widest">Ver mi equipo</button>
                   </div>
                </div>

                <div className="bg-white p-10 rounded-[3rem] shadow-[0_20px_50px_rgba(0,0,0,0.02)] border border-slate-50">
                  <div className="flex items-center gap-4 mb-6">
                    <div className="w-12 h-12 bg-emerald-50 text-emerald-600 rounded-2xl flex items-center justify-center text-2xl shadow-inner">
                      {activeBreak.icon}
                    </div>
                    <div>
                      <p className="text-[9px] font-black text-emerald-600 uppercase tracking-widest">Pausa Activa Sugerida</p>
                      <h3 className="text-lg font-black text-slate-900 uppercase tracking-tight">{activeBreak.title}</h3>
                    </div>
                  </div>
                  <p className="text-slate-500 font-medium leading-relaxed mb-6 text-sm">
                    {activeBreak.description}
                  </p>
                  <div className="p-4 bg-emerald-50/50 rounded-2xl border border-emerald-100 text-emerald-800 text-[10px] font-bold italic flex items-center gap-3">
                    <span className="text-lg">💡</span>
                    <span>Tomar descansos cortos cada hora aumenta la productividad y reduce el estrés laboral.</span>
                  </div>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'company' && <CompanyModule company={company} onUpdate={onUpdateCompany} role={role} />}
          {/* Fix: Pass missing company prop to EmployeeModule */}
          {activeTab === 'employees' && <EmployeeModule employees={employees} onUpdate={onUpdateEmployees} role={role} attendance={attendance} payments={payments} company={company} />}
          {activeTab === 'payroll' && <PayrollModule employees={employees} payments={payments} company={company} settings={settings} role={role} />}
          {activeTab === 'payments' && <PaymentsModule employees={employees} payments={payments} onUpdate={onUpdatePayments} role={role} />}
          {activeTab === 'settings' && <SettingsModule settings={settings} onUpdate={onUpdateSettings} role={role} />}
          {activeTab === 'reports' && (
            <ReportsModule 
              employees={employees} 
              payments={payments} 
              attendance={attendance} 
              company={company} 
              settings={settings}
            />
          )}
        </div>
      </main>

      <Modal 
        isOpen={isBackupReminderOpen} 
        onClose={() => setIsBackupReminderOpen(false)} 
        title="Protección de Activos Digitales"
        type="success"
        footer={
          <div className="flex gap-2">
            <button onClick={() => setIsBackupReminderOpen(false)} className="px-6 py-2 text-gray-400 font-bold text-[10px] uppercase">Luego</button>
            <button onClick={handleGoToBackup} className="px-8 py-2 bg-emerald-600 text-white font-black rounded-xl text-[10px] uppercase shadow-lg">Asegurar Información Ahora</button>
          </div>
        }
      >
        <div className="space-y-6 text-center">
           <div className="w-20 h-20 bg-emerald-50 text-emerald-600 rounded-full flex items-center justify-center text-4xl mx-auto shadow-inner">🛡️</div>
           <div>
             <h3 className="text-xl font-black text-slate-800 uppercase tracking-tighter mb-2">¡La seguridad de sus datos es prioridad!</h3>
             <p className="text-sm text-slate-500 font-medium leading-relaxed">Han pasado 15 días desde su último respaldo integral. Mantener una copia local de su base de datos garantiza la continuidad operativa ante cualquier imprevisto.</p>
           </div>
           <div className="p-4 bg-emerald-50 rounded-2xl border border-emerald-100 text-emerald-800 text-[10px] font-black uppercase tracking-widest italic">
              Proceso rápido • Encriptado • Seguro
           </div>
        </div>
      </Modal>
    </div>
  );
};

