    const lastBackup = localStorage.getItem('lastBackupDate');
    if (lastBackup) {
      const lastDate = new Date(lastBackup);
      const diffTime = Math.abs(today.getTime() - lastDate.getTime());
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      if (diffDays >= 15) {
