                                 {a.status === 'confirmed' ? 'Aprobado' : a.status === 'rejected' ? 'Rechazado' : 'Pendiente'}
                               </span>
                             </td>
                          </tr>
                         );
                       })}
                    </tbody>
                  </table>
               </div>
            )}
         </div>
      </div>
    </div>
  );
};

