import React, { useState, useMemo, useEffect } from 'react';
import { Role, CompanyConfig, Employee, AttendanceRecord, Payment, GlobalSettings } from '../types.ts';
import Sidebar from '../components/Sidebar.tsx';
import CompanyModule from './modules/CompanyModule.tsx';
import EmployeeModule from './modules/EmployeeModule.tsx';
import PayrollModule from './modules/PayrollModule.tsx';
import PaymentsModule from './modules/PaymentsModule.tsx';
import SettingsModule from './modules/SettingsModule.tsx';
import ReportsModule from './modules/ReportsModule.tsx';
import Modal from '../components/Modal.tsx';
import { ECUADOR_HOLIDAYS, DAILY_QUOTES, ACTIVE_BREAKS } from '../constants.tsx';

interface AdminDashboardProps {
  role: Role;
  isDbConnected?: boolean;
  onLogout: () => void;
  company: CompanyConfig | null;
  onUpdateCompany: (config: CompanyConfig) => void;
  employees: Employee[];
  onUpdateEmployees: (employees: Employee[]) => void;
  attendance: AttendanceRecord[];
  payments: Payment[];
  onUpdatePayments: (payments: Payment[]) => void;
  settings: GlobalSettings;
  onUpdateSettings: (settings: GlobalSettings) => void;
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  role, isDbConnected, onLogout, company, onUpdateCompany, employees, onUpdateEmployees, attendance, payments, onUpdatePayments, settings, onUpdateSettings 
}) => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'company' | 'employees' | 'payroll' | 'payments' | 'settings' | 'reports'>('dashboard');
  const [isBackupReminderOpen, setIsBackupReminderOpen] = useState(false);

  const today = useMemo(() => new Date(), []);

  const dayOfYear = useMemo(() => {
    const start = new Date(today.getFullYear(), 0, 0);
    const diff = today.getTime() - start.getTime();
    const oneDay = 1000 * 60 * 60 * 24;
    return Math.floor(diff / oneDay);
  }, [today]);

  const dailyQuote = useMemo(() => DAILY_QUOTES[dayOfYear % DAILY_QUOTES.length], [dayOfYear]);
  const activeBreak = useMemo(() => ACTIVE_BREAKS[dayOfYear % ACTIVE_BREAKS.length], [dayOfYear]);

  useEffect(() => {
    const lastBackup = localStorage.getItem('lastBackupDate');
    if (lastBackup) {
      const lastDate = new Date(lastBackup);
      const diffTime = Math.abs(today.getTime() - lastDate.getTime());
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      if (diffDays >= 15) setIsBackupReminderOpen(true);
    } else {
      localStorage.setItem('lastBackupDate', today.toISOString());
    }
  }, [today]);

  const upcomingBirthdays = useMemo(() => {
    return employees.filter(emp => {
      if (emp.status !== 'active') return false;
      const bday = new Date(emp.birthDate);
      const bdayThisYear = new Date(today.getFullYear(), bday.getMonth(), bday.getDate());
      const diff = (bdayThisYear.getTime() - today.getTime()) / (1000 * 3600 * 24);
      return diff >= 0 && diff <= 3;
    });
  }, [employees, today]);

  const currentHoliday = useMemo(() => {
    return ECUADOR_HOLIDAYS.find(h => {
      if (h.duration) {
        return today.getMonth() === h.month && today.getDate() >= h.day && today.getDate() < h.day + h.duration;
      }
      return today.getMonth() === h.month && today.getDate() === h.day;
    });
  }, [today]);

  const handleGoToBackup = () => {
    setIsBackupReminderOpen(false);
    setActiveTab('settings');
  };

  return (
    <div className="flex h-screen bg-[#fcfdfe] overflow-hidden flex-col md:flex-row">
      <Sidebar 
        role={role} 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        onLogout={onLogout} 
        companyName={company?.name}
      />

      <main className="flex-1 overflow-y-auto px-6 py-10 md:px-12 md:py-12 scroll-smooth custom-scroll">
        <header className="flex flex-col md:flex-row justify-between items-start md:items-center mb-10 md:mb-16 gap-6 fade-in no-print pt-14 md:pt-0">
          <div className="flex items-center gap-4 md:gap-6">
            {activeTab !== 'dashboard' && (
              <button 
                onClick={() => setActiveTab('dashboard')} 
                className="w-10 h-10 md:w-12 md:h-12 rounded-2xl bg-white shadow-xl border border-slate-100 flex items-center justify-center text-blue-600 hover:bg-blue-600 hover:text-white transition-all"
              >
                <svg className="w-5 h-5 md:w-6 md:h-6 transform rotate-180" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M13 7l5 5m0 0l-5 5m5-5H6"></path></svg>
              </button>
            )}
            <div>
              <h1 className="text-2xl md:text-4xl font-[900] text-slate-900 tracking-tight">
                {activeTab === 'dashboard' ? 'Bienestar' : 
                 activeTab === 'company' ? 'Institucional' : 
                 activeTab === 'employees' ? 'Talento' : 
                 activeTab === 'payroll' ? 'Nómina' : 
                 activeTab === 'payments' ? 'Tesorería' : 
                 activeTab === 'reports' ? 'Reportes' : 'Ajustes'}
              </h1>
              <div className="flex items-center gap-2 mt-1">
                  <span className={`w-2 h-2 rounded-full ${isDbConnected ? 'bg-emerald-500' : 'bg-red-500 animate-pulse'}`}></span>
                  <span className="text-slate-400 font-bold text-[8px] uppercase tracking-widest">
                    {isDbConnected ? 'Cloud Sync' : 'Offline Mode'}
                  </span>
              </div>
            </div>
          </div>

          <div className="flex gap-2 overflow-x-auto w-full md:w-auto pb-2 md:pb-0">
             {currentHoliday && (
               <div className="bg-slate-900 text-white px-4 py-2 md:px-6 md:py-3 rounded-xl flex items-center gap-3 shrink-0">
                 <span className="text-xl">🇪🇨</span>
                 <p className="font-black text-[10px] md:text-xs">¡{currentHoliday.name}!</p>
               </div>
             )}
             {upcomingBirthdays.length > 0 && (
               <div className="bg-emerald-600 text-white px-4 py-2 md:px-6 md:py-3 rounded-xl flex items-center gap-3 shrink-0">
                 <span className="text-xl">🎂</span>
                 <p className="font-black text-[10px] md:text-xs">{upcomingBirthdays[0].name}</p>
               </div>
             )}
          </div>
        </header>

        <div className="animate-in fade-in duration-700">
          {activeTab === 'dashboard' && (
            <div className="space-y-8 md:space-y-12 no-print">
              <div className="bg-white p-8 md:p-12 rounded-[2.5rem] md:rounded-[3rem] shadow-sm border border-slate-50 relative overflow-hidden group">
                <div className="relative z-10 max-w-2xl">
                  <p className="text-[9px] font-black text-blue-600 uppercase tracking-[0.3em] mb-4">Reflexión</p>
                  <h2 className="text-xl md:text-3xl font-[800] text-slate-900 italic leading-snug">"{dailyQuote}"</h2>
                </div>
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 md:gap-12">
                <div className="bg-slate-900 rounded-[2.5rem] md:rounded-[3rem] p-8 md:p-10 text-white relative overflow-hidden flex flex-col justify-center">
                   <h2 className="text-2xl md:text-3xl font-[900] mb-4 tracking-tighter uppercase italic text-blue-400">Cultura</h2>
                   <p className="text-slate-400 mb-8 text-sm md:text-base font-medium">Gestionando el activo más valioso: Las personas.</p>
                   <button onClick={() => setActiveTab('employees')} className="w-fit px-8 py-3 bg-white text-slate-900 font-[900] rounded-xl uppercase text-[9px] tracking-widest">Ver equipo</button>
                </div>

                <div className="bg-white p-8 md:p-10 rounded-[2.5rem] md:rounded-[3rem] shadow-sm border border-slate-50">
                  <div className="flex items-center gap-4 mb-6">
                    <div className="w-12 h-12 bg-emerald-50 text-emerald-600 rounded-xl flex items-center justify-center text-2xl">{activeBreak.icon}</div>
                    <h3 className="text-base md:text-lg font-black text-slate-900 uppercase">{activeBreak.title}</h3>
                  </div>
                  <p className="text-slate-500 font-medium mb-4 text-xs md:text-sm">{activeBreak.description}</p>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'company' && <CompanyModule company={company} onUpdate={onUpdateCompany} role={role} />}
          {activeTab === 'employees' && <EmployeeModule employees={employees} onUpdate={onUpdateEmployees} role={role} attendance={attendance} payments={payments} company={company} />}
          {activeTab === 'payroll' && <PayrollModule employees={employees} payments={payments} company={company} settings={settings} role={role} />}
          {activeTab === 'payments' && <PaymentsModule employees={employees} payments={payments} onUpdate={onUpdatePayments} role={role} />}
          {activeTab === 'settings' && <SettingsModule settings={settings} onUpdate={onUpdateSettings} role={role} />}
          {activeTab === 'reports' && <ReportsModule employees={employees} payments={payments} attendance={attendance} company={company} settings={settings} />}
        </div>
      </main>

      <Modal isOpen={isBackupReminderOpen} onClose={() => setIsBackupReminderOpen(false)} title="Seguridad de Datos" type="success">
        <div className="text-center space-y-4">
           <div className="w-16 h-16 bg-emerald-50 text-emerald-600 rounded-full flex items-center justify-center text-3xl mx-auto">🛡️</div>
           <p className="text-sm text-slate-500">Es momento de realizar un respaldo integral de su base de datos.</p>
           <button onClick={handleGoToBackup} className="w-full py-4 bg-emerald-600 text-white font-black rounded-xl text-[10px] uppercase shadow-lg">Respaldar Ahora</button>
        </div>
      </Modal>
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useEffect } from 'react';
import { CompanyConfig, Employee, Role, AttendanceRecord, Payment, GlobalSettings } from './types.ts';
import AdminDashboard from './views/AdminDashboard.tsx';
import AttendanceSystem from './views/AttendanceSystem.tsx';
import Modal from './components/Modal.tsx';
import { db, collection, doc, onSnapshot, setDoc, addDoc, compressData, decompressData } from './firebase.ts';

const App: React.FC = () => {
  const [currentUserRole, setCurrentUserRole] = useState<Role | null>(null);
  const [view, setView] = useState<'selection' | 'admin' | 'attendance'>('selection');
  const [isLoadingData, setIsLoadingData] = useState(true);
  const [isDbConnected, setIsDbConnected] = useState(false);
  const [isAdminLoginModalOpen, setIsAdminLoginModalOpen] = useState(false);
  const [adminPassInput, setAdminPassInput] = useState('');
  const [showPass, setShowPass] = useState(false);
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);
  const [isMobile, setIsMobile] = useState(false);

  // Nuevos estados para feedback formal de sesión
  const [showWelcome, setShowWelcome] = useState(false);
  const [showLogoutFeedback, setShowLogoutFeedback] = useState(false);

  const [company, setCompany] = useState<CompanyConfig | null>(null);
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);
  const [payments, setPayments] = useState<Payment[]>([]);
  const [settings, setSettings] = useState<GlobalSettings>({
    sbu: 482.00,
    iessRate: 0.0945,
    reserveRate: 0.0833,
    schedule: {
      monFri: { in: '08:30', out: '13:00' },
      sat: { in: '08:30', out: '13:00' },
      halfDayOff: 'Miércoles tarde'
    }
  });

  useEffect(() => {
    const checkMobile = () => setIsMobile(/iPhone|iPad|iPod|Android/i.test(navigator.userAgent));
    checkMobile();
    window.addEventListener('resize', checkMobile);

    window.addEventListener('beforeinstallprompt', (e) => {
      e.preventDefault();
      setDeferredPrompt(e);
    });

    const rescueTimer = setTimeout(() => setIsLoadingData(false), 4000);
    const unsubscribes: (() => void)[] = [];

    const updateConnectionStatus = (metadata: any) => {
      if (!metadata.fromCache) setIsDbConnected(true);
    };

    try {
      const unsubCompany = onSnapshot(doc(db, "config", "company"), (docSnap) => {
        if (docSnap.exists()) {
          const data = docSnap.data();
          setCompany(data.payload ? decompressData(data.payload) : data as any);
        }
        updateConnectionStatus(docSnap.metadata);
        setIsLoadingData(false);
        clearTimeout(rescueTimer);
      }, () => setIsDbConnected(false));
      unsubscribes.push(unsubCompany);

      const unsubEmployees = onSnapshot(collection(db, "employees"), (snapshot) => {
        setEmployees(snapshot.docs.map(d => {
          const raw = d.data();
          return raw.payload ? { ...decompressData(raw.payload), id: d.id } : { ...raw, id: d.id };
        }) as Employee[]);
        updateConnectionStatus(snapshot.metadata);
      }, () => setIsDbConnected(false));
      unsubscribes.push(unsubEmployees);

      const unsubAttendance = onSnapshot(collection(db, "attendance"), (snapshot) => {
        setAttendance(snapshot.docs.map(d => {
          const raw = d.data();
          return raw.payload ? { ...decompressData(raw.payload), id: d.id } : { ...raw, id: d.id };
        }) as AttendanceRecord[]);
        updateConnectionStatus(snapshot.metadata);
      }, () => setIsDbConnected(false));
      unsubscribes.push(unsubAttendance);

      const unsubPayments = onSnapshot(collection(db, "payments"), (snapshot) => {
        setPayments(snapshot.docs.map(d => {
          const raw = d.data();
          return raw.payload ? { ...decompressData(raw.payload), id: d.id } : { ...raw, id: d.id };
        }) as Payment[]);
        updateConnectionStatus(snapshot.metadata);
      }, () => setIsDbConnected(false));
      unsubscribes.push(unsubPayments);

    } catch (e) {
      console.error(e);
      setIsLoadingData(false);
      setIsDbConnected(false);
    }

    return () => { 
      unsubscribes.forEach(unsub => unsub()); 
      clearTimeout(rescueTimer); 
      window.removeEventListener('resize', checkMobile);
    };
  }, []);

  const handleAdminLogin = () => {
    let role: Role | null = null;
    if (adminPassInput === 'admin123') role = Role.SUPER_ADMIN;
    else if (adminPassInput === 'partial123') role = Role.PARTIAL_ADMIN;

    if (role) {
      if (isMobile && role === Role.PARTIAL_ADMIN) {
        alert("Acceso Restringido: El Administrador Parcial solo puede acceder desde una computadora de escritorio.");
        return;
      }
      setCurrentUserRole(role);
      setShowWelcome(true); // Mostrar bienvenida
      setView('admin');
      setIsAdminLoginModalOpen(false);
    } else {
      alert('Clave incorrecta.');
    }
    setAdminPassInput('');
  };

  const handleLogoutRequest = () => {
    setShowLogoutFeedback(true); // Mostrar feedback de cierre
  };

  const finalizeLogout = () => {
    setCurrentUserRole(null);
    setView('selection');
    setShowLogoutFeedback(false);
  };

  const handleInstall = async () => {
    if (deferredPrompt) {
      deferredPrompt.prompt();
      const { outcome } = await deferredPrompt.userChoice;
      if (outcome === 'accepted') setDeferredPrompt(null);
    }
  };

  if (isLoadingData) return null;

  if (view === 'selection') {
    return (
      <div className="min-h-screen gradient-blue flex flex-col items-center justify-center p-4">
        <div className="w-full max-w-lg bg-white/95 backdrop-blur-2xl p-8 md:p-16 rounded-[3rem] shadow-2xl text-center border border-white/20">
          <div className="mb-10 flex justify-center">
            <div className="w-20 h-20 bg-blue-700 rounded-3xl flex items-center justify-center shadow-2xl border-4 border-blue-500/20 italic font-black text-white text-3xl">AU</div>
          </div>
          <h1 className="text-4xl md:text-5xl font-[900] text-slate-900 mb-2 tracking-tighter uppercase italic leading-none">ASIST UP</h1>
          <p className="text-blue-600 font-black uppercase tracking-[0.5em] text-[8px] mb-10">Control de Talento Humano</p>

          <div className="space-y-3">
            <button onClick={() => setView('attendance')} className="w-full py-5 bg-blue-700 text-white font-black rounded-3xl shadow-xl hover:bg-blue-800 transition-all uppercase text-[10px] tracking-widest active:scale-95">Control de Asistencia</button>
            <button onClick={() => setIsAdminLoginModalOpen(true)} className="w-full py-4 text-slate-400 font-black hover:text-slate-900 transition-all uppercase text-[10px] tracking-widest">Acceso Administrativo</button>

            {deferredPrompt && (
              <button onClick={handleInstall} className="w-full mt-6 py-3 bg-emerald-50 text-emerald-600 font-black rounded-2xl border border-emerald-100 uppercase text-[9px] tracking-widest hover:bg-emerald-100 transition-all">Instalar App en este equipo</button>
            )}
          </div>

          <div className="mt-8 flex items-center justify-center gap-2">
             <div className={`w-2 h-2 rounded-full ${isDbConnected ? 'bg-emerald-500' : 'bg-red-500 animate-pulse'}`}></div>
             <span className="text-[8px] font-black uppercase tracking-widest text-slate-400">
               {isDbConnected ? 'Sistema en línea y estable' : 'Buscando servidor...'}
             </span>
          </div>
        </div>

        <Modal isOpen={isAdminLoginModalOpen} onClose={() => setIsAdminLoginModalOpen(false)} title="Acceso de Gestión">
          <div className="space-y-6">
            <div className="relative">
              <input 
                type={showPass ? "text" : "password"} 
                value={adminPassInput} 
                onChange={e => setAdminPassInput(e.target.value)} 
                onKeyDown={e => e.key === 'Enter' && handleAdminLogin()} 
                className="w-full border-2 border-slate-100 rounded-2xl p-5 text-center text-3xl font-black focus:border-blue-600 outline-none transition-all bg-slate-50 pr-16" 
                placeholder="••••••" 
                autoFocus 
              />
              <button 
                onClick={() => setShowPass(!showPass)}
                className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 hover:text-blue-600 transition-colors"
              >
                {showPass ? (
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" /></svg>
                ) : (
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l18 18" /></svg>
                )}
              </button>
            </div>
            <button onClick={handleAdminLogin} className="w-full py-5 bg-blue-700 text-white font-black rounded-2xl uppercase text-[10px] tracking-widest shadow-lg active:scale-95 transition-all">Validar Credenciales</button>
          </div>
        </Modal>

        <Modal isOpen={showLogoutFeedback} onClose={finalizeLogout} title="Cierre de Sesión Seguro" type="success">
           <div className="text-center space-y-6">
              <div className="w-20 h-20 bg-emerald-50 text-emerald-600 rounded-full flex items-center justify-center text-4xl mx-auto shadow-inner">☁️</div>
              <h3 className="text-xl font-black text-slate-900 uppercase">Sincronización Exitosa</h3>
              <p className="text-sm text-slate-500 font-medium leading-relaxed">Sesión cerrada exitosamente.<br/><span className="font-bold text-emerald-600">Todos los registros han sido sincronizados y protegidos en la nube.</span></p>
              <button onClick={finalizeLogout} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] tracking-widest">Entendido</button>
           </div>
        </Modal>
      </div>
    );
  }

  if (view === 'attendance') {
    return <AttendanceSystem employees={employees} onBack={() => setView('selection')} onRegister={async (r: AttendanceRecord) => { await addDoc(collection(db, "attendance"), { payload: compressData(r), timestamp: r.timestamp }); }} onUpdateEmployees={async (emps: Employee[]) => { for (const e of emps) { await setDoc(doc(db, "employees", e.id), { payload: compressData(e) }); } }} />;
  }

  return (
    <>
      <AdminDashboard 
        role={currentUserRole!} 
        isDbConnected={isDbConnected}
        onLogout={handleLogoutRequest} 
        company={company}
        onUpdateCompany={async (c: CompanyConfig) => await setDoc(doc(db, "config", "company"), { payload: compressData(c) })}
        employees={employees}
        onUpdateEmployees={async (emps: Employee[]) => { for (const e of emps) { await setDoc(doc(db, "employees", e.id), { payload: compressData(e) }); } }}
        attendance={attendance}
        payments={payments}
        onUpdatePayments={async (pys: Payment[]) => { for (const p of pys) { if (p.id.length > 15) await addDoc(collection(db, "payments"), { payload: compressData(p) }); else await setDoc(doc(db, "payments", p.id), { payload: compressData(p) }); } }}
        settings={settings}
        onUpdateSettings={async (s: GlobalSettings) => await setDoc(doc(db, "config", "settings"), { payload: compressData(s) })}
      />

      <Modal isOpen={showWelcome} onClose={() => setShowWelcome(false)} title="Acceso Autorizado" type="success">
         <div className="text-center space-y-4">
            <div className="text-5xl">🏢</div>
            <h2 className="text-2xl font-black text-slate-900">¡Bienvenido al Panel de Gestión!</h2>
            <p className="text-slate-500 text-xs font-bold uppercase tracking-widest">Sesión iniciada como: <span className="text-blue-600">{currentUserRole}</span></p>
            <button onClick={() => setShowWelcome(false)} className="w-full py-4 bg-blue-700 text-white font-black rounded-xl uppercase text-[10px] tracking-widest shadow-xl">Comenzar Gestión</button>
         </div>
      </Modal>
    </>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Employee, AttendanceRecord } from '../types.ts';
import Clock from '../components/Clock.tsx';
import { APP_NAME, MOTIVATIONAL_MESSAGES_START, MOTIVATIONAL_MESSAGES_END, ECUADOR_HOLIDAYS } from '../constants.tsx';

interface AttendanceSystemProps {
  employees: Employee[];
  onRegister: (record: AttendanceRecord) => void;
  onBack: () => void;
  onUpdateEmployees: (employees: Employee[]) => void;
}

const AttendanceSystem: React.FC<AttendanceSystemProps> = ({ employees, onRegister, onBack, onUpdateEmployees }) => {
  const [pin, setPin] = useState('');
  const [status, setStatus] = useState<'idle' | 'confirm' | 'forgotten_form' | 'success' | 'error'>('idle');
  const [currentEmp, setCurrentEmp] = useState<Employee | null>(null);
  const [motivationalMsg, setMotivationalMsg] = useState('');

  const [forgottenData, setForgottenData] = useState({
    date: new Date().toISOString().split('T')[0],
    type: 'in' as 'in' | 'out',
    justification: ''
  });

  const today = new Date();
  const currentHoliday = ECUADOR_HOLIDAYS.find(h => h.month === today.getMonth() && h.day === today.getDate());

  const handleMark = (type: 'in' | 'out') => {
    if (!currentEmp) return;

    // Bloqueo inmediato para evitar doble marcación
    setStatus('success');

    const record: AttendanceRecord = {
      id: Math.random().toString(36).substr(2, 9),
      employeeId: currentEmp.id,
      timestamp: new Date().toISOString(),
      type,
      status: 'confirmed'
    };

    onRegister(record);

    const msgs = type === 'in' ? MOTIVATIONAL_MESSAGES_START : MOTIVATIONAL_MESSAGES_END;
    setMotivationalMsg(msgs[Math.floor(Math.random() * msgs.length)]);
    setPin('');

    // El sistema se mantiene bloqueado durante este tiempo
    setTimeout(() => {
      setStatus('idle');
      setCurrentEmp(null);
    }, 4500);
  };

  const handleForgottenSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentEmp || !forgottenData.justification) return alert("Debe ingresar una justificación.");

    // Bloqueo inmediato
    setStatus('success');

    const record: AttendanceRecord = {
      id: Math.random().toString(36).substr(2, 9),
      employeeId: currentEmp.id,
      timestamp: new Date(forgottenData.date + 'T12:00:00').toISOString(),
      type: forgottenData.type,
      status: 'pending_approval',
      isForgotten: true,
      justification: forgottenData.justification
    };

    onRegister(record);
    setMotivationalMsg("Solicitud enviada con éxito. El administrador validará su jornada.");
    setPin('');

    setTimeout(() => {
      setStatus('idle');
      setCurrentEmp(null);
      setForgottenData({ date: new Date().toISOString().split('T')[0], type: 'in', justification: '' });
    }, 4500);
  };

  useEffect(() => {
    if (pin.length === 6 && status === 'idle') {
      const emp = employees.find(e => e.pin === pin && e.status === 'active');
      if (emp) {
        setCurrentEmp(emp);
        setStatus('confirm');
      } else {
        setStatus('error');
        setTimeout(() => { setStatus('idle'); setPin(''); }, 2000);
      }
    }
  }, [pin, employees, status]);

  // Teclado físico habilitado
  useEffect(() => {
    const handleKey = (e: KeyboardEvent) => {
      // Si el sistema está bloqueado o en proceso, ignorar teclas
      if (status !== 'idle') return;
      if (e.key >= '0' && e.key <= '9' && pin.length < 6) setPin(p => p + e.key);
      if (e.key === 'Backspace') setPin(p => p.slice(0, -1));
    };
    window.addEventListener('keydown', handleKey);
    return () => window.removeEventListener('keydown', handleKey);
  }, [pin, status]);

  return (
    <div className="min-h-screen gradient-blue flex flex-col items-center justify-center p-4">
      {/* Overlay de Bloqueo durante Success para garantizar el proceso */}
      {status === 'success' && (
        <div className="fixed inset-0 z-[100] bg-slate-900/60 backdrop-blur-xl flex flex-col items-center justify-center fade-in">
           <div className="w-24 h-24 bg-emerald-500 text-white rounded-full flex items-center justify-center text-4xl mb-8 shadow-[0_0_50px_rgba(16,185,129,0.4)] animate-in zoom-in">✓</div>
           <p className="text-white font-black text-xl md:text-2xl uppercase tracking-tighter italic text-center px-8 mb-4">"{motivationalMsg}"</p>
           <div className="flex items-center gap-2">
              <span className="w-2 h-2 bg-emerald-400 rounded-full animate-ping"></span>
              <p className="text-emerald-400 font-black uppercase text-[10px] tracking-[0.4em]">Marcaje Registrado Correctamente</p>
           </div>
        </div>
      )}

      <div className={`w-full max-w-xl bg-white/95 backdrop-blur-3xl rounded-[3rem] shadow-2xl p-8 md:p-12 flex flex-col items-center transition-all duration-700 relative overflow-hidden ${status === 'success' ? 'scale-95 opacity-0 pointer-events-none' : 'fade-in'}`}>

        {currentHoliday && (
          <div className="absolute top-0 w-full bg-emerald-600 text-white py-1.5 text-center text-[9px] font-black uppercase tracking-[0.3em]">
            FESTIVO: {currentHoliday.name}
          </div>
        )}

        <h1 className="text-3xl font-black text-slate-900 mb-6 tracking-tighter uppercase italic">{APP_NAME}</h1>
        <div className="mb-8 transform scale-75 md:scale-90"><Clock /></div>

        {status === 'idle' && (
          <div className="w-full text-center">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em] mb-8">INGRESE PIN DE ASISTENCIA</p>
            <div className="flex gap-3 justify-center mb-10">
              {[...Array(6)].map((_, i) => (
                <div key={i} className={`w-10 h-14 border-b-4 flex items-center justify-center text-3xl font-black transition-all ${pin.length > i ? 'border-blue-600 text-slate-900 scale-105' : 'border-slate-100'}`}>
                  {pin[i] ? '•' : ''}
                </div>
              ))}
            </div>

            <div className="grid grid-cols-3 gap-3 md:gap-4 max-w-[320px] mx-auto">
              {[1, 2, 3, 4, 5, 6, 7, 8, 9, 'C', 0, '←'].map(btn => (
                <button 
                  key={btn}
                  onClick={() => {
                    if (btn === 'C') setPin('');
                    else if (btn === '←') setPin(p => p.slice(0, -1));
                    else if (pin.length < 6) setPin(p => p + btn);
                  }}
                  className="h-14 md:h-16 bg-slate-50 hover:bg-blue-600 hover:text-white rounded-2xl text-xl font-black transition-all active:scale-90"
                >
                  {btn}
                </button>
              ))}
            </div>
          </div>
        )}

        {status === 'confirm' && currentEmp && (
          <div className="text-center animate-in zoom-in duration-300 w-full">
            <div className="mb-6">
               <div className="w-20 h-20 bg-blue-100 rounded-2xl mx-auto flex items-center justify-center text-3xl font-black text-blue-600 uppercase">
                 {currentEmp.name[0]}
               </div>
            </div>
            <h2 className="text-3xl font-black text-slate-900 mb-1 uppercase tracking-tighter leading-tight">{currentEmp.name}</h2>
            <p className="text-slate-400 font-bold uppercase tracking-widest text-[10px] mb-10 italic">Validación de Identidad Exitosa</p>

            <div className="grid grid-cols-2 gap-4 mb-6">
              <button onClick={() => handleMark('in')} className="py-8 bg-emerald-600 text-white rounded-3xl font-black text-xl uppercase shadow-xl hover:bg-emerald-700 transition-all active:scale-95">Marcar Ingreso</button>
              <button onClick={() => handleMark('out')} className="py-8 bg-blue-700 text-white rounded-3xl font-black text-xl uppercase shadow-xl hover:bg-blue-800 transition-all active:scale-95">Marcar Salida</button>
            </div>

            <button onClick={() => setStatus('forgotten_form')} className="text-blue-600 font-black uppercase text-[10px] tracking-widest hover:underline">Olvidé mi registro anterior</button>
          </div>
        )}

        {status === 'forgotten_form' && currentEmp && (
          <form onSubmit={handleForgottenSubmit} className="w-full space-y-4 animate-in slide-in-from-bottom">
            <h2 className="text-xl font-black text-slate-900 uppercase text-center mb-4">Registro Extemporáneo</h2>
            <div className="space-y-3">
              <div>
                <label className="text-[9px] font-black uppercase text-slate-400">Fecha del registro olvidado</label>
                <input type="date" required className="w-full border p-3 rounded-xl text-xs font-bold" value={forgottenData.date} onChange={e => setForgottenData({...forgottenData, date: e.target.value})} />
              </div>
              <div className="grid grid-cols-2 gap-3">
                <button type="button" onClick={() => setForgottenData({...forgottenData, type: 'in'})} className={`py-3 rounded-xl text-[10px] font-black uppercase ${forgottenData.type === 'in' ? 'bg-blue-600 text-white' : 'bg-slate-100 text-slate-400'}`}>Entrada</button>
                <button type="button" onClick={() => setForgottenData({...forgottenData, type: 'out'})} className={`py-3 rounded-xl text-[10px] font-black uppercase ${forgottenData.type === 'out' ? 'bg-blue-600 text-white' : 'bg-slate-100 text-slate-400'}`}>Salida</button>
              </div>
              <div>
                <label className="text-[9px] font-black uppercase text-slate-400">Justificación formal</label>
                <textarea required className="w-full border p-3 rounded-xl text-xs h-24 focus:border-blue-500 outline-none" placeholder="Especifique el motivo de la omisión..." value={forgottenData.justification} onChange={e => setForgottenData({...forgottenData, justification: e.target.value})}></textarea>
              </div>
            </div>
            <div className="flex gap-3">
              <button type="button" onClick={() => setStatus('confirm')} className="flex-1 py-4 bg-slate-100 text-slate-500 rounded-2xl font-black uppercase text-[10px]">Cancelar</button>
              <button type="submit" className="flex-[2] py-4 bg-blue-700 text-white rounded-2xl font-black uppercase text-[10px] shadow-lg">Solicitar Registro</button>
            </div>
          </form>
        )}

        {status === 'error' && (
          <div className="text-center text-red-600 animate-bounce">
            <div className="text-6xl mb-2">✕</div>
            <h2 className="text-xl font-black uppercase tracking-tighter">PIN INCORRECTO</h2>
          </div>
        )}
      </div>

      <button onClick={onBack} className={`mt-8 text-white/40 hover:text-white font-black text-[10px] uppercase tracking-[0.4em] transition-all ${status === 'success' ? 'opacity-0' : 'opacity-100'}`}>Gestión Administrativa</button>
    </div>
  );
};

export default AttendanceSystem;

import React, { useState, useEffect } from 'react';
import { CompanyConfig, Employee, Role, AttendanceRecord, Payment, GlobalSettings } from './types.ts';
import AdminDashboard from './views/AdminDashboard.tsx';
import AttendanceSystem from './views/AttendanceSystem.tsx';
import Modal from './components/Modal.tsx';
import { db, collection, doc, onSnapshot, setDoc, addDoc, compressData, decompressData } from './firebase.ts';

const App: React.FC = () => {
  const [currentUserRole, setCurrentUserRole] = useState<Role | null>(null);
  const [view, setView] = useState<'selection' | 'admin' | 'attendance'>('selection');
  const [isLoadingData, setIsLoadingData] = useState(true);
  const [isDbConnected, setIsDbConnected] = useState(false);
  const [isAdminLoginModalOpen, setIsAdminLoginModalOpen] = useState(false);
  const [adminPassInput, setAdminPassInput] = useState('');
  const [showPass, setShowPass] = useState(false);
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);
  const [isMobile, setIsMobile] = useState(false);

  // Estados de Modales Formales
  const [showWelcome, setShowWelcome] = useState(false);
  const [showLogoutFeedback, setShowLogoutFeedback] = useState(false);
  const [modalAlert, setModalAlert] = useState<{isOpen: boolean, title: string, message: string, type: 'info' | 'success' | 'error'}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  const [company, setCompany] = useState<CompanyConfig | null>(null);
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);
  const [payments, setPayments] = useState<Payment[]>([]);
  const [settings, setSettings] = useState<GlobalSettings>({
    sbu: 482.00,
    iessRate: 0.0945,
    reserveRate: 0.0833,
    schedule: {
      monFri: { in: '08:30', out: '13:00' },
      sat: { in: '08:30', out: '13:00' },
      halfDayOff: 'Miércoles tarde'
    }
  });

  const showAlert = (title: string, message: string, type: 'info' | 'success' | 'error' = 'info') => {
    setModalAlert({ isOpen: true, title, message, type });
  };

  useEffect(() => {
    const checkMobile = () => setIsMobile(/iPhone|iPad|iPod|Android/i.test(navigator.userAgent));
    checkMobile();
    window.addEventListener('resize', checkMobile);

    window.addEventListener('beforeinstallprompt', (e) => {
      e.preventDefault();
      setDeferredPrompt(e);
    });

    const rescueTimer = setTimeout(() => setIsLoadingData(false), 4000);
    const unsubscribes: (() => void)[] = [];

    const updateConnectionStatus = (metadata: any) => {
      if (!metadata.fromCache) setIsDbConnected(true);
    };

    try {
      const unsubCompany = onSnapshot(doc(db, "config", "company"), (docSnap) => {
        if (docSnap.exists()) {
          const data = docSnap.data();
          setCompany(data.payload ? decompressData(data.payload) : data as any);
        }
        updateConnectionStatus(docSnap.metadata);
        setIsLoadingData(false);
        clearTimeout(rescueTimer);
      }, () => setIsDbConnected(false));
      unsubscribes.push(unsubCompany);

      const unsubEmployees = onSnapshot(collection(db, "employees"), (snapshot) => {
        setEmployees(snapshot.docs.map(d => {
          const raw = d.data();
          return raw.payload ? { ...decompressData(raw.payload), id: d.id } : { ...raw, id: d.id };
        }) as Employee[]);
        updateConnectionStatus(snapshot.metadata);
      }, () => setIsDbConnected(false));
      unsubscribes.push(unsubEmployees);

      const unsubAttendance = onSnapshot(collection(db, "attendance"), (snapshot) => {
        setAttendance(snapshot.docs.map(d => {
          const raw = d.data();
          return raw.payload ? { ...decompressData(raw.payload), id: d.id } : { ...raw, id: d.id };
        }) as AttendanceRecord[]);
        updateConnectionStatus(snapshot.metadata);
      }, () => setIsDbConnected(false));
      unsubscribes.push(unsubAttendance);

      const unsubPayments = onSnapshot(collection(db, "payments"), (snapshot) => {
        setPayments(snapshot.docs.map(d => {
          const raw = d.data();
          return raw.payload ? { ...decompressData(raw.payload), id: d.id } : { ...raw, id: d.id };
        }) as Payment[]);
        updateConnectionStatus(snapshot.metadata);
      }, () => setIsDbConnected(false));
      unsubscribes.push(unsubPayments);

    } catch (e) {
      setIsLoadingData(false);
      setIsDbConnected(false);
    }

    return () => { 
      unsubscribes.forEach(unsub => unsub()); 
      clearTimeout(rescueTimer); 
      window.removeEventListener('resize', checkMobile);
    };
  }, []);

  const handleAdminLogin = () => {
    let role: Role | null = null;
    if (adminPassInput === 'admin123') role = Role.SUPER_ADMIN;
    else if (adminPassInput === 'partial123') role = Role.PARTIAL_ADMIN;

    if (role) {
      if (isMobile && role === Role.PARTIAL_ADMIN) {
        showAlert("Acceso Restringido", "El Administrador Parcial solo puede acceder desde una computadora de escritorio.", "error");
        return;
      }
      setCurrentUserRole(role);
      setShowWelcome(true);
      setView('admin');
      setIsAdminLoginModalOpen(false);
    } else {
      showAlert("Error de Autenticación", "Las credenciales ingresadas son incorrectas.", "error");
    }
    setAdminPassInput('');
  };

  const handleLogoutRequest = () => {
    setShowLogoutFeedback(true);
  };

  const finalizeLogout = () => {
    setCurrentUserRole(null);
    setView('selection');
    setShowLogoutFeedback(false);
  };

  const handleInstall = async () => {
    if (deferredPrompt) {
      deferredPrompt.prompt();
      const { outcome } = await deferredPrompt.userChoice;
      if (outcome === 'accepted') setDeferredPrompt(null);
    }
  };

  if (isLoadingData) return null;

  if (view === 'selection') {
    return (
      <div className="min-h-screen gradient-blue flex flex-col items-center justify-center p-4">
        <div className="w-full max-w-lg bg-white/95 backdrop-blur-2xl p-8 md:p-16 rounded-[3rem] shadow-2xl text-center border border-white/20">
          <div className="mb-10 flex justify-center">
            <div className="w-20 h-20 bg-blue-700 rounded-3xl flex items-center justify-center shadow-2xl border-4 border-blue-500/20 italic font-black text-white text-3xl">AU</div>
          </div>
          <h1 className="text-4xl md:text-5xl font-[900] text-slate-900 mb-2 tracking-tighter uppercase italic leading-none">ASIST UP</h1>
          <p className="text-blue-600 font-black uppercase tracking-[0.5em] text-[8px] mb-10">Control de Talento Humano</p>

          <div className="space-y-3">
            <button onClick={() => setView('attendance')} className="w-full py-5 bg-blue-700 text-white font-black rounded-3xl shadow-xl hover:bg-blue-800 transition-all uppercase text-[10px] tracking-widest active:scale-95">Control de Asistencia</button>
            <button onClick={() => setIsAdminLoginModalOpen(true)} className="w-full py-4 text-slate-400 font-black hover:text-slate-900 transition-all uppercase text-[10px] tracking-widest">Acceso Administrativo</button>

            {deferredPrompt && (
              <button onClick={handleInstall} className="w-full mt-6 py-3 bg-emerald-50 text-emerald-600 font-black rounded-2xl border border-emerald-100 uppercase text-[9px] tracking-widest hover:bg-emerald-100 transition-all">Instalar App en este equipo</button>
            )}
          </div>

          <div className="mt-8 flex items-center justify-center gap-2">
             <div className={`w-2 h-2 rounded-full ${isDbConnected ? 'bg-emerald-500' : 'bg-red-500 animate-pulse'}`}></div>
             <span className="text-[8px] font-black uppercase tracking-widest text-slate-400">
               {isDbConnected ? 'Sistema en línea y estable' : 'Sincronizando con la nube...'}
             </span>
          </div>
        </div>

        <Modal isOpen={isAdminLoginModalOpen} onClose={() => setIsAdminLoginModalOpen(false)} title="Acceso de Gestión">
          <div className="space-y-6">
            <div className="relative">
              <input 
                type={showPass ? "text" : "password"} 
                value={adminPassInput} 
                onChange={e => setAdminPassInput(e.target.value)} 
                onKeyDown={e => e.key === 'Enter' && handleAdminLogin()} 
                className="w-full border-2 border-slate-100 rounded-2xl p-5 text-center text-3xl font-black focus:border-blue-600 outline-none transition-all bg-slate-50 pr-16" 
                placeholder="••••••" 
                autoFocus 
              />
              <button 
                onClick={() => setShowPass(!showPass)}
                className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 hover:text-blue-600 transition-colors"
              >
                {showPass ? (
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" /></svg>
                ) : (
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l18 18" /></svg>
                )}
              </button>
            </div>
            <button onClick={handleAdminLogin} className="w-full py-5 bg-blue-700 text-white font-black rounded-2xl uppercase text-[10px] tracking-widest shadow-lg active:scale-95 transition-all">Validar Credenciales</button>
          </div>
        </Modal>

        <Modal isOpen={showLogoutFeedback} onClose={finalizeLogout} title="Cierre de Sesión Seguro" type="success">
           <div className="text-center space-y-6">
              <div className="w-20 h-20 bg-emerald-50 text-emerald-600 rounded-full flex items-center justify-center text-4xl mx-auto shadow-inner">☁️</div>
              <h3 className="text-xl font-black text-slate-900 uppercase">Sincronización Exitosa</h3>
              <p className="text-sm text-slate-500 font-medium leading-relaxed">Sesión cerrada exitosamente.<br/><span className="font-bold text-emerald-600">Todos los registros han sido sincronizados y protegidos en la nube.</span></p>
              <button onClick={finalizeLogout} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] tracking-widest">Entendido</button>
           </div>
        </Modal>

        <Modal isOpen={modalAlert.isOpen} onClose={() => setModalAlert({...modalAlert, isOpen: false})} title={modalAlert.title} type={modalAlert.type}>
           <div className="text-center space-y-4">
              <p className="text-slate-600 font-medium">{modalAlert.message}</p>
              <button onClick={() => setModalAlert({...modalAlert, isOpen: false})} className="w-full py-3 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] tracking-widest">Aceptar</button>
           </div>
        </Modal>
      </div>
    );
  }

  if (view === 'attendance') {
    return <AttendanceSystem employees={employees} attendance={attendance} onBack={() => setView('selection')} onRegister={async (r: AttendanceRecord) => { await addDoc(collection(db, "attendance"), { payload: compressData(r), timestamp: r.timestamp }); }} onUpdateEmployees={async (emps: Employee[]) => { for (const e of emps) { await setDoc(doc(db, "employees", e.id), { payload: compressData(e) }); } }} />;
  }

  return (
    <>
      <AdminDashboard 
        role={currentUserRole!} 
        isDbConnected={isDbConnected}
        onLogout={handleLogoutRequest} 
        company={company}
        onUpdateCompany={async (c: CompanyConfig) => await setDoc(doc(db, "config", "company"), { payload: compressData(c) })}
        employees={employees}
        onUpdateEmployees={async (emps: Employee[]) => { for (const e of emps) { await setDoc(doc(db, "employees", e.id), { payload: compressData(e) }); } }}
        attendance={attendance}
        payments={payments}
        onUpdatePayments={async (pys: Payment[]) => { for (const p of pys) { if (p.id.length > 15) await addDoc(collection(db, "payments"), { payload: compressData(p) }); else await setDoc(doc(db, "payments", p.id), { payload: compressData(p) }); } }}
        settings={settings}
        onUpdateSettings={async (s: GlobalSettings) => await setDoc(doc(db, "config", "settings"), { payload: compressData(s) })}
      />

      <Modal isOpen={showWelcome} onClose={() => setShowWelcome(false)} title="Acceso Autorizado" type="success">
         <div className="text-center space-y-4">
            <div className="text-5xl">🏢</div>
            <h2 className="text-2xl font-black text-slate-900">¡Bienvenido al Panel de Gestión!</h2>
            <p className="text-slate-500 text-xs font-bold uppercase tracking-widest">Sesión iniciada como: <span className="text-blue-600">{currentUserRole}</span></p>
            <button onClick={() => setShowWelcome(false)} className="w-full py-4 bg-blue-700 text-white font-black rounded-xl uppercase text-[10px] tracking-widest shadow-xl">Comenzar Gestión</button>
         </div>
      </Modal>

      <Modal isOpen={modalAlert.isOpen} onClose={() => setModalAlert({...modalAlert, isOpen: false})} title={modalAlert.title} type={modalAlert.type}>
           <div className="text-center space-y-4">
              <p className="text-slate-600 font-medium">{modalAlert.message}</p>
              <button onClick={() => setModalAlert({...modalAlert, isOpen: false})} className="w-full py-3 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] tracking-widest">Aceptar</button>
           </div>
      </Modal>
    </>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Employee, AttendanceRecord } from '../types.ts';
import Clock from '../components/Clock.tsx';
import Modal from '../components/Modal.tsx';
import { APP_NAME, MOTIVATIONAL_MESSAGES_START, MOTIVATIONAL_MESSAGES_END, ECUADOR_HOLIDAYS } from '../constants.tsx';

interface AttendanceSystemProps {
  employees: Employee[];
  attendance: AttendanceRecord[];
  onRegister: (record: AttendanceRecord) => void;
  onBack: () => void;
  onUpdateEmployees: (employees: Employee[]) => void;
}

const AttendanceSystem: React.FC<AttendanceSystemProps> = ({ employees, attendance, onRegister, onBack, onUpdateEmployees }) => {
  const [pin, setPin] = useState('');
  const [status, setStatus] = useState<'idle' | 'confirm' | 'forgotten_form' | 'success' | 'error'>('idle');
  const [currentEmp, setCurrentEmp] = useState<Employee | null>(null);
  const [motivationalMsg, setMotivationalMsg] = useState('');

  // Modales de validación
  const [validationMsg, setValidationMsg] = useState<{isOpen: boolean, message: string, type: 'success' | 'error'}>({
    isOpen: false, message: '', type: 'success'
  });

  const [forgottenData, setForgottenData] = useState({
    date: new Date().toISOString().split('T')[0],
    type: 'in' as 'in' | 'out',
    justification: ''
  });

  const today = new Date();
  const currentHoliday = ECUADOR_HOLIDAYS.find(h => h.month === today.getMonth() && h.day === today.getDate());

  const handleMark = (type: 'in' | 'out') => {
    if (!currentEmp) return;

    setStatus('success');

    const record: AttendanceRecord = {
      id: Math.random().toString(36).substr(2, 9),
      employeeId: currentEmp.id,
      timestamp: new Date().toISOString(),
      type,
      status: 'confirmed'
    };

    onRegister(record);

    const msgs = type === 'in' ? MOTIVATIONAL_MESSAGES_START : MOTIVATIONAL_MESSAGES_END;
    setMotivationalMsg(msgs[Math.floor(Math.random() * msgs.length)]);
    setPin('');

    setTimeout(() => {
      setStatus('idle');
      setCurrentEmp(null);
    }, 4500);
  };

  const handleForgottenSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentEmp || !forgottenData.justification) {
      setValidationMsg({ isOpen: true, message: "Debe ingresar una justificación válida para el registro.", type: 'error' });
      return;
    }

    setStatus('success');

    const record: AttendanceRecord = {
      id: Math.random().toString(36).substr(2, 9),
      employeeId: currentEmp.id,
      timestamp: new Date(forgottenData.date + 'T12:00:00').toISOString(),
      type: forgottenData.type,
      status: 'pending_approval',
      isForgotten: true,
      justification: forgottenData.justification
    };

    onRegister(record);
    setMotivationalMsg("Solicitud enviada con éxito. El administrador validará su jornada.");
    setPin('');

    setTimeout(() => {
      setStatus('idle');
      setCurrentEmp(null);
      setForgottenData({ date: new Date().toISOString().split('T')[0], type: 'in', justification: '' });
    }, 4500);
  };

  useEffect(() => {
    if (pin.length === 6 && status === 'idle') {
      const emp = employees.find(e => e.pin === pin && e.status === 'active');
      if (emp) {
        // Verificar marcajes extemporáneos validados recientemente
        const recentlyValidated = attendance
          .filter(a => a.employeeId === emp.id && a.isForgotten && a.status !== 'pending_approval' && a.validatedAt)
          .sort((a, b) => new Date(b.validatedAt!).getTime() - new Date(a.validatedAt!).getTime())[0];

        if (recentlyValidated) {
          const dateStr = new Date(recentlyValidated.timestamp).toLocaleDateString();
          const state = recentlyValidated.status === 'confirmed' ? 'APROBADO' : 'RECHAZADO';
          setValidationMsg({
            isOpen: true,
            message: `NOTIFICACIÓN: Su solicitud de marcaje extemporáneo del día ${dateStr} ha sido ${state} por la administración.`,
            type: recentlyValidated.status === 'confirmed' ? 'success' : 'error'
          });
        }

        setCurrentEmp(emp);
        setStatus('confirm');
      } else {
        setStatus('error');
        setTimeout(() => { setStatus('idle'); setPin(''); }, 2000);
      }
    }
  }, [pin, employees, status, attendance]);

  useEffect(() => {
    const handleKey = (e: KeyboardEvent) => {
      if (status !== 'idle' || validationMsg.isOpen) return;
      if (e.key >= '0' && e.key <= '9' && pin.length < 6) setPin(p => p + e.key);
      if (e.key === 'Backspace') setPin(p => p.slice(0, -1));
    };
    window.addEventListener('keydown', handleKey);
    return () => window.removeEventListener('keydown', handleKey);
  }, [pin, status, validationMsg.isOpen]);

  return (
    <div className="min-h-screen gradient-blue flex flex-col items-center justify-center p-4">
      {status === 'success' && (
        <div className="fixed inset-0 z-[100] bg-slate-900/60 backdrop-blur-xl flex flex-col items-center justify-center fade-in">
           <div className="w-24 h-24 bg-emerald-500 text-white rounded-full flex items-center justify-center text-4xl mb-8 shadow-[0_0_50px_rgba(16,185,129,0.4)] animate-in zoom-in">✓</div>
           <p className="text-white font-black text-xl md:text-2xl uppercase tracking-tighter italic text-center px-8 mb-4">"{motivationalMsg}"</p>
           <div className="flex items-center gap-2">
              <span className="w-2 h-2 bg-emerald-400 rounded-full animate-ping"></span>
              <p className="text-emerald-400 font-black uppercase text-[10px] tracking-[0.4em]">Marcaje Registrado Correctamente</p>
           </div>
        </div>
      )}

      <div className={`w-full max-w-xl bg-white/95 backdrop-blur-3xl rounded-[3rem] shadow-2xl p-8 md:p-12 flex flex-col items-center transition-all duration-700 relative overflow-hidden ${status === 'success' ? 'scale-95 opacity-0 pointer-events-none' : 'fade-in'}`}>

        {currentHoliday && (
          <div className="absolute top-0 w-full bg-emerald-600 text-white py-1.5 text-center text-[9px] font-black uppercase tracking-[0.3em]">
            FESTIVO: {currentHoliday.name}
          </div>
        )}

        <h1 className="text-3xl font-black text-slate-900 mb-6 tracking-tighter uppercase italic">{APP_NAME}</h1>
        <div className="mb-8 transform scale-75 md:scale-90"><Clock /></div>

        {status === 'idle' && (
          <div className="w-full text-center">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em] mb-8">INGRESE PIN DE ASISTENCIA</p>
            <div className="flex gap-3 justify-center mb-10">
              {[...Array(6)].map((_, i) => (
                <div key={i} className={`w-10 h-14 border-b-4 flex items-center justify-center text-3xl font-black transition-all ${pin.length > i ? 'border-blue-600 text-slate-900 scale-105' : 'border-slate-100'}`}>
                  {pin[i] ? '•' : ''}
                </div>
              ))}
            </div>

            <div className="grid grid-cols-3 gap-3 md:gap-4 max-w-[320px] mx-auto">
              {[1, 2, 3, 4, 5, 6, 7, 8, 9, 'C', 0, '←'].map(btn => (
                <button 
                  key={btn}
                  onClick={() => {
                    if (btn === 'C') setPin('');
                    else if (btn === '←') setPin(p => p.slice(0, -1));
                    else if (pin.length < 6) setPin(p => p + btn);
                  }}
                  className="h-14 md:h-16 bg-slate-50 hover:bg-blue-600 hover:text-white rounded-2xl text-xl font-black transition-all active:scale-90"
                >
                  {btn}
                </button>
              ))}
            </div>
          </div>
        )}

        {status === 'confirm' && currentEmp && (
          <div className="text-center animate-in zoom-in duration-300 w-full">
            <div className="mb-6">
               <div className="w-20 h-20 bg-blue-100 rounded-2xl mx-auto flex items-center justify-center text-3xl font-black text-blue-600 uppercase">
                 {currentEmp.name[0]}
               </div>
            </div>
            <h2 className="text-3xl font-black text-slate-900 mb-1 uppercase tracking-tighter leading-tight">{currentEmp.name}</h2>
            <p className="text-slate-400 font-bold uppercase tracking-widest text-[10px] mb-10 italic">Validación de Identidad Exitosa</p>

            <div className="grid grid-cols-2 gap-4 mb-6">
              <button onClick={() => handleMark('in')} className="py-8 bg-emerald-600 text-white rounded-3xl font-black text-xl uppercase shadow-xl hover:bg-emerald-700 transition-all active:scale-95">Marcar Ingreso</button>
              <button onClick={() => handleMark('out')} className="py-8 bg-blue-700 text-white rounded-3xl font-black text-xl uppercase shadow-xl hover:bg-blue-800 transition-all active:scale-95">Marcar Salida</button>
            </div>

            <button onClick={() => setStatus('forgotten_form')} className="text-blue-600 font-black uppercase text-[10px] tracking-widest hover:underline">Olvidé mi registro anterior</button>
          </div>
        )}

        {status === 'forgotten_form' && currentEmp && (
          <form onSubmit={handleForgottenSubmit} className="w-full space-y-4 animate-in slide-in-from-bottom">
            <h2 className="text-xl font-black text-slate-900 uppercase text-center mb-4">Registro Extemporáneo</h2>
            <div className="space-y-3">
              <div>
                <label className="text-[9px] font-black uppercase text-slate-400">Fecha del registro olvidado</label>
                <input type="date" required className="w-full border p-3 rounded-xl text-xs font-bold" value={forgottenData.date} onChange={e => setForgottenData({...forgottenData, date: e.target.value})} />
              </div>
              <div className="grid grid-cols-2 gap-3">
                <button type="button" onClick={() => setForgottenData({...forgottenData, type: 'in'})} className={`py-3 rounded-xl text-[10px] font-black uppercase ${forgottenData.type === 'in' ? 'bg-blue-600 text-white' : 'bg-slate-100 text-slate-400'}`}>Entrada</button>
                <button type="button" onClick={() => setForgottenData({...forgottenData, type: 'out'})} className={`py-3 rounded-xl text-[10px] font-black uppercase ${forgottenData.type === 'out' ? 'bg-blue-600 text-white' : 'bg-slate-100 text-slate-400'}`}>Salida</button>
              </div>
              <div>
                <label className="text-[9px] font-black uppercase text-slate-400">Justificación formal</label>
                <textarea required className="w-full border p-3 rounded-xl text-xs h-24 focus:border-blue-500 outline-none" placeholder="Especifique el motivo de la omisión..." value={forgottenData.justification} onChange={e => setForgottenData({...forgottenData, justification: e.target.value})}></textarea>
              </div>
            </div>
            <div className="flex gap-3">
              <button type="button" onClick={() => setStatus('confirm')} className="flex-1 py-4 bg-slate-100 text-slate-400 rounded-2xl font-black uppercase text-[10px]">Cancelar</button>
              <button type="submit" className="flex-[2] py-4 bg-blue-700 text-white rounded-2xl font-black uppercase text-[10px] shadow-lg">Solicitar Registro</button>
            </div>
          </form>
        )}

        {status === 'error' && (
          <div className="text-center text-red-600 animate-bounce">
            <div className="text-6xl mb-2">✕</div>
            <h2 className="text-xl font-black uppercase tracking-tighter">PIN INCORRECTO</h2>
          </div>
        )}
      </div>

      <button onClick={onBack} className={`mt-8 text-white/40 hover:text-white font-black text-[10px] uppercase tracking-[0.4em] transition-all ${status === 'success' ? 'opacity-0' : 'opacity-100'}`}>Gestión Administrativa</button>

      <Modal isOpen={validationMsg.isOpen} onClose={() => setValidationMsg({...validationMsg, isOpen: false})} title="Validación Administrativa" type={validationMsg.type}>
          <div className="text-center space-y-6">
              <div className={`w-16 h-16 ${validationMsg.type === 'success' ? 'bg-emerald-50 text-emerald-600' : 'bg-red-50 text-red-600'} rounded-full flex items-center justify-center text-3xl mx-auto shadow-sm`}>
                {validationMsg.type === 'success' ? '✓' : '✕'}
              </div>
              <p className="text-slate-700 font-bold uppercase text-[11px] leading-relaxed italic">{validationMsg.message}</p>
              <button onClick={() => setValidationMsg({...validationMsg, isOpen: false})} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] tracking-widest">Continuar</button>
          </div>
      </Modal>
    </div>
  );
};

export default AttendanceSystem;

import React, { useState, useEffect } from 'react';
import { CompanyConfig, Role } from '../../types.ts';
import Modal from '../../components/Modal.tsx';

interface CompanyModuleProps {
  company: CompanyConfig | null;
  onUpdate: (config: CompanyConfig) => void;
  role: Role;
}

const CompanyModule: React.FC<CompanyModuleProps> = ({ company, onUpdate, role }) => {
  const [formData, setFormData] = useState<CompanyConfig>({
    name: '', legalRep: '', ruc: '', address: '', phone: '', email: '', logo: ''
  });
  const [modalFeedback, setModalFeedback] = useState<{isOpen: boolean, title: string, message: string, type: 'info' | 'success' | 'error'}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  useEffect(() => {
    if (company) setFormData(company);
  }, [company]);

  const canEdit = role === Role.SUPER_ADMIN;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!canEdit) {
      setModalFeedback({ isOpen: true, title: "Acceso Denegado", message: "Solo el Super Administrador puede editar los datos de la empresa.", type: "error" });
      return;
    }

    if (formData.ruc.length !== 13 || !formData.ruc.endsWith('001')) {
      setModalFeedback({ isOpen: true, title: "Dato Inválido", message: "El RUC debe tener estrictamente 13 dígitos y terminar en '001'.", type: "error" });
      return;
    }

    const isMobile = formData.phone.startsWith('09');
    if (isMobile && formData.phone.length !== 10) {
      setModalFeedback({ isOpen: true, title: "Dato Inválido", message: "El celular debe tener estrictamente 10 dígitos.", type: "error" });
      return;
    }
    if (!isMobile && formData.phone.length !== 9) {
      setModalFeedback({ isOpen: true, title: "Dato Inválido", message: "El teléfono fijo debe tener estrictamente 9 dígitos.", type: "error" });
      return;
    }

    onUpdate(formData);
    setModalFeedback({ isOpen: true, title: "Actualización Exitosa", message: "Los datos corporativos han sido sincronizados correctamente.", type: "success" });
  };

  return (
    <div className="max-w-4xl mx-auto bg-white p-6 md:p-10 rounded-[2rem] md:rounded-[3rem] shadow-sm border border-slate-100 fade-in">
      <div className="flex flex-col md:flex-row items-center gap-6 mb-10 pb-6 border-b">
        <div className="w-24 h-24 bg-slate-50 rounded-3xl flex items-center justify-center overflow-hidden border border-slate-100">
           {formData.logo ? <img src={formData.logo} className="w-full h-full object-cover" /> : <span className="text-4xl">🏢</span>}
        </div>
        <div className="text-center md:text-left">
          <h2 className="text-2xl md:text-3xl font-black text-slate-900 uppercase tracking-tighter italic">Configuración Institucional</h2>
          <p className="text-slate-400 font-bold text-[9px] md:text-[10px] uppercase tracking-widest mt-1">Identidad Legal y Corporativa</p>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 gap-4 md:gap-6">
        <div className="space-y-1">
          <label className="text-[9px] font-black text-blue-600 uppercase tracking-widest">Nombre Comercial</label>
          <input required disabled={!canEdit} className="w-full p-4 rounded-xl border-2 bg-slate-50 focus:border-blue-500 outline-none transition-all disabled:opacity-50 text-xs font-bold" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
        </div>
        <div className="space-y-1">
          <label className="text-[9px] font-black text-blue-600 uppercase tracking-widest">Representante Legal</label>
