import React, { useState } from 'react';
import { Employee, Role, BloodType, TerminationReason, AbsenceRecord, CompanyConfig } from '../../types.ts';
import Modal from '../../components/Modal.tsx';

interface EmployeeModuleProps {
  employees: Employee[];
  onUpdate: (employees: Employee[]) => void;
  role: Role;
  attendance: any[];
  payments: any[];
  company: CompanyConfig | null;
}

const EmployeeModule: React.FC<EmployeeModuleProps> = ({ employees, onUpdate, role, company }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingEmp, setEditingEmp] = useState<Employee | null>(null);
  const [viewingEmp, setViewingEmp] = useState<Employee | null>(null);
  const [isTermModalOpen, setIsTermModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [modalAlert, setModalAlert] = useState<{isOpen: boolean, title: string, message: string, type: 'info' | 'success' | 'error'}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  const initialForm: Partial<Employee> = {
    name: '', surname: '', identification: '', birthDate: '', origin: '', address: '',
    phone: '', email: '', bloodType: BloodType.O_POS,
    emergencyContact: { name: '', phone: '' }, startDate: new Date().toISOString().split('T')[0],
    role: Role.EMPLOYEE, isFixed: true, salary: 482.00, isAffiliated: true, overSalaryType: 'accumulate',
    bankInfo: { ifi: '', type: 'Ahorros', account: '' }, photo: '', pin: '',
    status: 'active', observations: [], absences: [], totalHoursWorked: 0
  };

  const [form, setForm] = useState<Partial<Employee>>(initialForm);

  const showAlert = (title: string, message: string, type: 'info' | 'success' | 'error' = 'info') => {
    setModalAlert({ isOpen: true, title, message, type });
  };

  const validateForm = () => {
    if (!form.name || !form.surname || !form.identification || !form.pin) return "Datos básicos obligatorios faltantes.";
    if (form.pin?.length !== 6) return "PIN debe ser de 6 dígitos estrictamente.";
    if (form.phone?.length !== 10) return "El celular debe tener estrictamente 10 dígitos.";
    if (!form.emergencyContact?.name || !form.emergencyContact?.phone) return "Contacto de emergencia es obligatorio.";
    return null;
  };

  const handleSave = () => {
    const error = validateForm();
    if (error) {
      showAlert("Dato Incompleto", error, "error");
      return;
    }

    let updatedList;
    if (editingEmp) {
      updatedList = employees.map(e => e.id === editingEmp.id ? { ...e, ...form } as Employee : e);
    } else {
      const newEmp = { ...form, id: Math.random().toString(36).substr(2, 9), pinChanges: 0 } as Employee;
      updatedList = [...employees, newEmp];
    }

    onUpdate(updatedList);
    setIsModalOpen(false);
    setEditingEmp(null);
    setForm(initialForm);
    showAlert("Sincronización Exitosa", "Expediente de personal guardado con éxito.", "success");
  };

  const handleTermination = (data: any) => {
    if (!viewingEmp) return;
    const updated = employees.map(e => e.id === viewingEmp.id ? {
      ...e,
      status: 'terminated' as const,
      terminationDate: data.date,
      terminationReason: data.reason,
      terminationDetails: data.details
    } : e);
    onUpdate(updated);
    setIsTermModalOpen(false);
    showAlert("Baja Confirmada", "Empleado desvinculado con éxito. El acta ha sido generada.", "success");
    setTimeout(() => window.print(), 500);
  };

  return (
    <div className="space-y-6 fade-in overflow-hidden">
      <div className="bg-white p-6 md:p-8 rounded-[2rem] shadow-sm border flex flex-col md:flex-row justify-between items-center no-print gap-4">
        <div className="text-center md:text-left">
          <h2 className="text-2xl md:text-3xl font-black text-slate-900 tracking-tighter uppercase italic">Talento Humano</h2>
          <p className="text-[9px] text-slate-400 font-black uppercase tracking-widest">Historiales y Fichas de Personal</p>
        </div>
        <button onClick={() => { setForm(initialForm); setEditingEmp(null); setIsModalOpen(true); }} className="w-full md:w-auto px-8 py-4 bg-blue-700 text-white font-black rounded-2xl shadow-xl uppercase text-[10px] tracking-widest active:scale-95">Nuevo Colaborador</button>
      </div>

      <div className="bg-white rounded-[2rem] shadow-sm border overflow-x-auto no-print">
        <div className="p-4 bg-slate-50 border-b">
          <input type="text" placeholder="Buscar..." className="w-full bg-white border p-3 rounded-xl text-xs font-bold outline-none" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
        </div>
        <table className="w-full text-left min-w-[600px]">
          <thead className="bg-slate-50 text-[9px] font-black text-slate-400 uppercase tracking-widest">
            <tr>
              <th className="px-6 py-4">Foto</th>
              <th className="px-6 py-4">Colaborador</th>
              <th className="px-6 py-4">Estado</th>
              <th className="px-6 py-4 text-right">Acción</th>
            </tr>
          </thead>
          <tbody className="divide-y text-[11px] font-bold">
            {employees.filter(e => (e.name + " " + e.surname).toLowerCase().includes(searchTerm.toLowerCase())).map(emp => (
              <tr key={emp.id} className="hover:bg-slate-50">
                <td className="px-6 py-4">
                  <div className="w-10 h-10 rounded-xl overflow-hidden bg-slate-100 border">{emp.photo && <img src={emp.photo} className="w-full h-full object-cover" />}</div>
                </td>
                <td className="px-6 py-4 uppercase">
                   <p className="text-slate-900 leading-tight">{emp.name} {emp.surname}</p>
                   <p className="text-[8px] text-slate-400 font-black tracking-widest">{emp.identification}</p>
                </td>
                <td className="px-6 py-4">
                  <span className={`px-2 py-0.5 rounded text-[8px] font-black uppercase ${emp.status === 'active' ? 'text-emerald-600' : 'text-red-600'}`}>{emp.status}</span>
                </td>
                <td className="px-6 py-4 text-right">
                   <button onClick={() => setViewingEmp(emp)} className="text-blue-600 font-black uppercase text-[9px]">Ver Ficha</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title={editingEmp ? "Actualizar Expediente" : "Registro Maestro"}>
        <div className="space-y-6 max-h-[70vh] overflow-y-auto pr-2 custom-scroll">
           <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="col-span-1 md:col-span-2 flex flex-col items-center gap-2 mb-4">
                 <div className="w-24 h-24 rounded-2xl bg-slate-50 border-2 border-dashed border-slate-200 flex items-center justify-center overflow-hidden relative">
                    {form.photo ? <img src={form.photo} className="w-full h-full object-cover" /> : <span className="text-[9px] font-black text-slate-300 uppercase">Foto</span>}
                    <input type="file" accept="image/*" className="absolute inset-0 opacity-0 cursor-pointer" onChange={(e) => {
                       const file = e.target.files?.[0];
                       if(file) {
                          const reader = new FileReader();
                          reader.onloadend = () => setForm({...form, photo: reader.result as string});
                          reader.readAsDataURL(file);
                       }
                    }} />
                 </div>
              </div>
              <div><label className="text-[9px] font-black uppercase text-slate-400">Nombres</label><input className="w-full border-2 p-3 rounded-xl text-xs font-bold" value={form.name} onChange={e => setForm({...form, name: e.target.value})} /></div>
              <div><label className="text-[9px] font-black uppercase text-slate-400">Apellidos</label><input className="w-full border-2 p-3 rounded-xl text-xs font-bold" value={form.surname} onChange={e => setForm({...form, surname: e.target.value})} /></div>
              <div><label className="text-[9px] font-black uppercase text-slate-400">ID / Cédula</label><input className="w-full border-2 p-3 rounded-xl text-xs font-bold" value={form.identification} onChange={e => setForm({...form, identification: e.target.value})} /></div>
              <div><label className="text-[9px] font-black uppercase text-slate-400">PIN (6 dígitos)</label><input maxLength={6} className="w-full border-2 border-blue-100 p-3 rounded-xl text-center font-black text-lg" value={form.pin} onChange={e => setForm({...form, pin: e.target.value.replace(/\D/g,'')})} /></div>
           </div>
           <button onClick={handleSave} className="w-full py-4 bg-blue-700 text-white font-black rounded-2xl uppercase text-[10px] tracking-widest shadow-xl">Guardar Expediente</button>
        </div>
      </Modal>

      <Modal isOpen={!!viewingEmp} onClose={() => setViewingEmp(null)} title="Expediente Integral">
        {viewingEmp && (
          <div className="space-y-6">
             <div className="flex items-center gap-4 border-b pb-6">
                <div className="w-20 h-20 rounded-2xl overflow-hidden bg-slate-100 border">{viewingEmp.photo && <img src={viewingEmp.photo} className="w-full h-full object-cover" />}</div>
                <div>
                   <h3 className="text-xl font-black uppercase tracking-tighter text-slate-900 leading-none">{viewingEmp.name} {viewingEmp.surname}</h3>
                   <p className="text-[9px] text-blue-600 font-black uppercase tracking-widest mt-1">Sueldo: ${viewingEmp.salary.toFixed(2)}</p>
                </div>
             </div>
             <div className="grid grid-cols-2 gap-4 text-[10px] font-bold">
                <p><span className="text-slate-400 uppercase">ID:</span> {viewingEmp.identification}</p>
                <p className="text-right"><span className="text-slate-400 uppercase">Estado:</span> {viewingEmp.status}</p>
             </div>
             <div className="flex gap-2">
                <button onClick={() => { setEditingEmp(viewingEmp); setForm(viewingEmp); setIsModalOpen(true); setViewingEmp(null); }} className="flex-1 py-3 bg-slate-900 text-white font-black rounded-xl uppercase text-[9px]">Editar</button>
                <button onClick={() => setIsTermModalOpen(true)} className="flex-1 py-3 bg-red-600 text-white font-black rounded-xl uppercase text-[9px]">Desvinculación</button>
             </div>
          </div>
        )}
      </Modal>

      <Modal isOpen={isTermModalOpen} onClose={() => setIsTermModalOpen(false)} title="Confirmar Baja" type="error">
         <div className="space-y-4">
            <p className="text-[11px] font-bold text-slate-600 italic text-center">¿Seguro de desvincular a este colaborador del sistema?</p>
            <button onClick={() => handleTermination({ date: new Date().toISOString().split('T')[0], reason: 'Despido', details: '' })} className="w-full py-4 bg-red-600 text-white font-black rounded-xl uppercase text-[10px]">Proceder con la baja definitiva</button>
         </div>
      </Modal>

      <Modal isOpen={modalAlert.isOpen} onClose={() => setModalAlert({...modalAlert, isOpen: false})} title={modalAlert.title} type={modalAlert.type}>
          <div className="text-center space-y-4">
              <p className="text-slate-600 font-medium italic">{modalAlert.message}</p>
              <button onClick={() => setModalAlert({...modalAlert, isOpen: false})} className="w-full py-3 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] tracking-widest">Cerrar</button>
          </div>
      </Modal>
    </div>
  );
};

export default EmployeeModule;

import React, { useState, useEffect } from 'react';
import { CompanyConfig, Employee, Role, AttendanceRecord, Payment, GlobalSettings } from './types.ts';
import AdminDashboard from './views/AdminDashboard.tsx';
import AttendanceSystem from './views/AttendanceSystem.tsx';
import Modal from './components/Modal.tsx';
import { db, collection, doc, onSnapshot, setDoc, addDoc, compressData, decompressData } from './firebase.ts';

const App: React.FC = () => {
  const [currentUserRole, setCurrentUserRole] = useState<Role | null>(null);
  const [view, setView] = useState<'selection' | 'admin' | 'attendance'>('selection');
  const [isLoadingData, setIsLoadingData] = useState(true);
  const [isDbConnected, setIsDbConnected] = useState(false);
  const [isAdminLoginModalOpen, setIsAdminLoginModalOpen] = useState(false);
  const [adminPassInput, setAdminPassInput] = useState('');
  const [showPass, setShowPass] = useState(false);
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);
  const [isMobile, setIsMobile] = useState(false);

  // Estados de Modales Formales
  const [showWelcome, setShowWelcome] = useState(false);
  const [showLogoutFeedback, setShowLogoutFeedback] = useState(false);
  const [showBootPrompt, setShowBootPrompt] = useState(false);
  const [modalAlert, setModalAlert] = useState<{isOpen: boolean, title: string, message: string, type: 'info' | 'success' | 'error'}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  const [company, setCompany] = useState<CompanyConfig | null>(null);
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);
  const [payments, setPayments] = useState<Payment[]>([]);
  const [settings, setSettings] = useState<GlobalSettings>({
    sbu: 482.00,
    iessRate: 0.0945,
    reserveRate: 0.0833,
    schedule: {
      monFri: { in: '08:30', out: '13:00' },
      sat: { in: '08:30', out: '13:00' },
      halfDayOff: 'Miércoles tarde'
    }
  });

  const showAlert = (title: string, message: string, type: 'info' | 'success' | 'error' = 'info') => {
    setModalAlert({ isOpen: true, title, message, type });
  };

  useEffect(() => {
    const checkMobile = () => setIsMobile(/iPhone|iPad|iPod|Android/i.test(navigator.userAgent));
    checkMobile();
    window.addEventListener('resize', checkMobile);

    window.addEventListener('beforeinstallprompt', (e) => {
      e.preventDefault();
      setDeferredPrompt(e);
    });

    window.addEventListener('appinstalled', () => {
      setShowBootPrompt(true); // Preguntar por auto-arranque tras instalar
    });

    const rescueTimer = setTimeout(() => setIsLoadingData(false), 4000);
    const unsubscribes: (() => void)[] = [];

    const updateConnectionStatus = (metadata: any) => {
      if (!metadata.fromCache) setIsDbConnected(true);
    };

    try {
      const unsubCompany = onSnapshot(doc(db, "config", "company"), (docSnap) => {
        if (docSnap.exists()) {
          const data = docSnap.data();
          setCompany(data.payload ? decompressData(data.payload) : data as any);
        }
        updateConnectionStatus(docSnap.metadata);
        setIsLoadingData(false);
        clearTimeout(rescueTimer);
      }, () => setIsDbConnected(false));
      unsubscribes.push(unsubCompany);

      const unsubEmployees = onSnapshot(collection(db, "employees"), (snapshot) => {
        setEmployees(snapshot.docs.map(d => {
          const raw = d.data();
          return raw.payload ? { ...decompressData(raw.payload), id: d.id } : { ...raw, id: d.id };
        }) as Employee[]);
        updateConnectionStatus(snapshot.metadata);
      }, () => setIsDbConnected(false));
      unsubscribes.push(unsubEmployees);

      const unsubAttendance = onSnapshot(collection(db, "attendance"), (snapshot) => {
        setAttendance(snapshot.docs.map(d => {
          const raw = d.data();
          return raw.payload ? { ...decompressData(raw.payload), id: d.id } : { ...raw, id: d.id };
        }) as AttendanceRecord[]);
        updateConnectionStatus(snapshot.metadata);
      }, () => setIsDbConnected(false));
      unsubscribes.push(unsubAttendance);

      const unsubPayments = onSnapshot(collection(db, "payments"), (snapshot) => {
        setPayments(snapshot.docs.map(d => {
          const raw = d.data();
          return raw.payload ? { ...decompressData(raw.payload), id: d.id } : { ...raw, id: d.id };
        }) as Payment[]);
        updateConnectionStatus(snapshot.metadata);
      }, () => setIsDbConnected(false));
      unsubscribes.push(unsubPayments);

    } catch (e) {
      setIsLoadingData(false);
      setIsDbConnected(false);
    }

    return () => { 
      unsubscribes.forEach(unsub => unsub()); 
      clearTimeout(rescueTimer); 
      window.removeEventListener('resize', checkMobile);
    };
  }, []);

  const handleAdminLogin = () => {
    let role: Role | null = null;
    if (adminPassInput === 'admin123') role = Role.SUPER_ADMIN;
    else if (adminPassInput === 'partial123') role = Role.PARTIAL_ADMIN;

    if (role) {
      if (isMobile && role === Role.PARTIAL_ADMIN) {
        showAlert("Acceso Restringido", "El Administrador Parcial solo puede acceder desde una computadora de escritorio.", "error");
        return;
      }
      setCurrentUserRole(role);
      setShowWelcome(true);
      setView('admin');
      setIsAdminLoginModalOpen(false);
    } else {
      showAlert("Error de Autenticación", "Las credenciales ingresadas son incorrectas.", "error");
    }
    setAdminPassInput('');
  };

  const finalizeLogout = () => {
    setCurrentUserRole(null);
    setView('selection');
    setShowLogoutFeedback(false);
  };

  const handleInstall = async () => {
    if (deferredPrompt) {
      deferredPrompt.prompt();
      const { outcome } = await deferredPrompt.userChoice;
      if (outcome === 'accepted') setDeferredPrompt(null);
    }
  };

  const enableAutoStart = async () => {
    if ('runOnOsLogin' in navigator) {
      try {
        // @ts-ignore
        await navigator.runOnOsLogin.set({ mode: 'windowed' });
        showAlert("Configuración Exitosa", "El sistema se iniciará automáticamente con el equipo.", "success");
      } catch (e) {
        console.error(e);
      }
    }
    setShowBootPrompt(false);
  };

  if (isLoadingData) return null;

  if (view === 'selection') {
    return (
      <div className="min-h-screen gradient-blue flex flex-col items-center justify-center p-4">
        <div className="w-full max-w-lg bg-white/95 backdrop-blur-2xl p-8 md:p-16 rounded-[3rem] shadow-2xl text-center border border-white/20">
          <div className="mb-10 flex justify-center">
            <div className="w-20 h-20 bg-blue-700 rounded-3xl flex items-center justify-center shadow-2xl border-4 border-blue-500/20 italic font-black text-white text-3xl">AU</div>
          </div>
          <h1 className="text-4xl md:text-5xl font-[900] text-slate-900 mb-2 tracking-tighter uppercase italic leading-none">ASIST UP</h1>
          <p className="text-blue-600 font-black uppercase tracking-[0.5em] text-[8px] mb-10">Control de Talento Humano</p>

          <div className="space-y-3">
            <button onClick={() => setView('attendance')} className="w-full py-5 bg-blue-700 text-white font-black rounded-3xl shadow-xl hover:bg-blue-800 transition-all uppercase text-[10px] tracking-widest active:scale-95">Control de Asistencia</button>
            <button onClick={() => setIsAdminLoginModalOpen(true)} className="w-full py-4 text-slate-400 font-black hover:text-slate-900 transition-all uppercase text-[10px] tracking-widest">Acceso Administrativo</button>

            {deferredPrompt && (
              <button onClick={handleInstall} className="w-full mt-6 py-3 bg-emerald-50 text-emerald-600 font-black rounded-2xl border border-emerald-100 uppercase text-[9px] tracking-widest hover:bg-emerald-100 transition-all">Instalar App en este equipo</button>
            )}
          </div>

          <div className="mt-8 flex items-center justify-center gap-2">
             <div className={`w-2 h-2 rounded-full ${isDbConnected ? 'bg-emerald-500' : 'bg-red-500 animate-pulse'}`}></div>
             <span className="text-[8px] font-black uppercase tracking-widest text-slate-400">
               {isDbConnected ? 'Sistema en línea y estable' : 'Conectando con base de datos...'}
             </span>
          </div>
        </div>

        <Modal isOpen={isAdminLoginModalOpen} onClose={() => setIsAdminLoginModalOpen(false)} title="Acceso de Gestión">
          <div className="space-y-6">
            <div className="relative">
              <input 
                type={showPass ? "text" : "password"} 
                value={adminPassInput} 
                onChange={e => setAdminPassInput(e.target.value)} 
                onKeyDown={e => e.key === 'Enter' && handleAdminLogin()} 
                className="w-full border-2 border-slate-100 rounded-2xl p-5 text-center text-3xl font-black focus:border-blue-600 outline-none transition-all bg-slate-50 pr-16" 
                placeholder="••••••" 
                autoFocus 
              />
              <button 
                onClick={() => setShowPass(!showPass)}
                className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 hover:text-blue-600 transition-colors"
              >
                {showPass ? (
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" /></svg>
                ) : (
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l18 18" /></svg>
                )}
              </button>
            </div>
            <button onClick={handleAdminLogin} className="w-full py-5 bg-blue-700 text-white font-black rounded-2xl uppercase text-[10px] tracking-widest shadow-lg active:scale-95 transition-all">Validar Credenciales</button>
          </div>
        </Modal>

        {/* Modal de Configuración de Arranque */}
        <Modal isOpen={showBootPrompt} onClose={() => setShowBootPrompt(false)} title="Configuración de Terminal" type="info">
           <div className="text-center space-y-6">
              <div className="w-20 h-20 bg-blue-50 text-blue-600 rounded-full flex items-center justify-center text-4xl mx-auto">🚀</div>
              <h3 className="text-xl font-black text-slate-900 uppercase">Inicio Automático</h3>
              <p className="text-sm text-slate-500 font-medium leading-relaxed">¿Desea que el sistema de asistencia arranque automáticamente al encender este equipo y se muestre en pantalla?</p>
              <div className="flex gap-3">
                <button onClick={() => setShowBootPrompt(false)} className="flex-1 py-4 bg-slate-100 text-slate-500 font-black rounded-xl uppercase text-[10px]">No por ahora</button>
                <button onClick={enableAutoStart} className="flex-[2] py-4 bg-blue-700 text-white font-black rounded-xl uppercase text-[10px] shadow-lg">Sí, activar arranque</button>
              </div>
           </div>
        </Modal>

        <Modal isOpen={showLogoutFeedback} onClose={finalizeLogout} title="Cierre de Sesión Seguro" type="success">
           <div className="text-center space-y-6">
              <div className="w-20 h-20 bg-emerald-50 text-emerald-600 rounded-full flex items-center justify-center text-4xl mx-auto shadow-inner">☁️</div>
              <h3 className="text-xl font-black text-slate-900 uppercase tracking-tighter">Sincronización Exitosa</h3>
              <p className="text-sm text-slate-500 font-medium leading-relaxed italic">Sesión cerrada exitosamente.<br/><span className="font-bold text-emerald-600">Todos los registros han sido sincronizados y protegidos en la nube de forma estable.</span></p>
              <button onClick={finalizeLogout} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] tracking-widest">Finalizar Protocolo</button>
           </div>
        </Modal>

        <Modal isOpen={modalAlert.isOpen} onClose={() => setModalAlert({...modalAlert, isOpen: false})} title={modalAlert.title} type={modalAlert.type}>
           <div className="text-center space-y-4">
              <p className="text-slate-600 font-medium italic">{modalAlert.message}</p>
              <button onClick={() => setModalAlert({...modalAlert, isOpen: false})} className="w-full py-3 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] tracking-widest">Aceptar</button>
           </div>
        </Modal>
      </div>
    );
  }

  if (view === 'attendance') {
    return <AttendanceSystem employees={employees} attendance={attendance} onBack={() => setView('selection')} onRegister={async (r: AttendanceRecord) => { await addDoc(collection(db, "attendance"), { payload: compressData(r), timestamp: r.timestamp }); }} onUpdateEmployees={async (emps: Employee[]) => { for (const e of emps) { await setDoc(doc(db, "employees", e.id), { payload: compressData(e) }); } }} />;
  }

  return (
    <>
      <AdminDashboard 
        role={currentUserRole!} 
        isDbConnected={isDbConnected}
        onLogout={() => setShowLogoutFeedback(true)} 
        company={company}
        onUpdateCompany={async (c: CompanyConfig) => await setDoc(doc(db, "config", "company"), { payload: compressData(c) })}
        employees={employees}
        onUpdateEmployees={async (emps: Employee[]) => { for (const e of emps) { await setDoc(doc(db, "employees", e.id), { payload: compressData(e) }); } }}
        attendance={attendance}
        payments={payments}
        onUpdatePayments={async (pys: Payment[]) => { for (const p of pys) { if (p.id.length > 15) await addDoc(collection(db, "payments"), { payload: compressData(p) }); else await setDoc(doc(db, "payments", p.id), { payload: compressData(p) }); } }}
        settings={settings}
        onUpdateSettings={async (s: GlobalSettings) => await setDoc(doc(db, "config", "settings"), { payload: compressData(s) })}
      />

      <Modal isOpen={showWelcome} onClose={() => setShowWelcome(false)} title="Acceso Autorizado" type="success">
         <div className="text-center space-y-4">
            <div className="text-5xl">🏢</div>
            <h2 className="text-2xl font-black text-slate-900 tracking-tighter uppercase italic">¡Bienvenido al Panel!</h2>
            <p className="text-slate-500 text-[10px] font-bold uppercase tracking-widest">Sesión iniciada formalmente como: <span className="text-blue-600">{currentUserRole}</span></p>
            <button onClick={() => setShowWelcome(false)} className="w-full py-4 bg-blue-700 text-white font-black rounded-xl uppercase text-[10px] tracking-widest shadow-xl">Comenzar Gestión</button>
         </div>
      </Modal>

      <Modal isOpen={modalAlert.isOpen} onClose={() => setModalAlert({...modalAlert, isOpen: false})} title={modalAlert.title} type={modalAlert.type}>
           <div className="text-center space-y-4">
              <p className="text-slate-600 font-medium italic">{modalAlert.message}</p>
              <button onClick={() => setModalAlert({...modalAlert, isOpen: false})} className="w-full py-3 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] tracking-widest">Aceptar</button>
           </div>
      </Modal>
    </>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Employee, AttendanceRecord } from '../types.ts';
import Clock from '../components/Clock.tsx';
import Modal from '../components/Modal.tsx';
import { APP_NAME, MOTIVATIONAL_MESSAGES_START, MOTIVATIONAL_MESSAGES_END, ECUADOR_HOLIDAYS } from '../constants.tsx';

interface AttendanceSystemProps {
  employees: Employee[];
  attendance: AttendanceRecord[];
  onRegister: (record: AttendanceRecord) => void;
  onBack: () => void;
  onUpdateEmployees: (employees: Employee[]) => void;
}

const AttendanceSystem: React.FC<AttendanceSystemProps> = ({ employees, attendance, onRegister, onBack, onUpdateEmployees }) => {
  const [pin, setPin] = useState('');
  const [status, setStatus] = useState<'idle' | 'confirm' | 'forgotten_form' | 'success' | 'error'>('idle');
  const [isProcessing, setIsProcessing] = useState(false); // Bloqueo total
  const [currentEmp, setCurrentEmp] = useState<Employee | null>(null);
  const [motivationalMsg, setMotivationalMsg] = useState('');

  // Modales de validación
  const [validationMsg, setValidationMsg] = useState<{isOpen: boolean, message: string, type: 'success' | 'error'}>({
    isOpen: false, message: '', type: 'success'
  });

  const [forgottenData, setForgottenData] = useState({
    date: new Date().toISOString().split('T')[0],
    type: 'in' as 'in' | 'out',
    justification: ''
  });

  const today = new Date();
  const currentHoliday = ECUADOR_HOLIDAYS.find(h => h.month === today.getMonth() && h.day === today.getDate());

  const handleMark = (type: 'in' | 'out') => {
    if (!currentEmp || isProcessing) return;

    setIsProcessing(true);
    setStatus('success');

    const record: AttendanceRecord = {
      id: Math.random().toString(36).substr(2, 9),
      employeeId: currentEmp.id,
      timestamp: new Date().toISOString(),
      type,
      status: 'confirmed'
    };

    onRegister(record);

    const msgs = type === 'in' ? MOTIVATIONAL_MESSAGES_START : MOTIVATIONAL_MESSAGES_END;
    setMotivationalMsg(msgs[Math.floor(Math.random() * msgs.length)]);
    setPin('');

    // Bloqueo de seguridad para evitar dobles registros
    setTimeout(() => {
      setStatus('idle');
      setCurrentEmp(null);
      setIsProcessing(false);
    }, 5000);
  };

  const handleForgottenSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentEmp || !forgottenData.justification || isProcessing) return;

    setIsProcessing(true);
    setStatus('success');

    const record: AttendanceRecord = {
      id: Math.random().toString(36).substr(2, 9),
      employeeId: currentEmp.id,
      timestamp: new Date(forgottenData.date + 'T12:00:00').toISOString(),
      type: forgottenData.type,
      status: 'pending_approval',
      isForgotten: true,
      justification: forgottenData.justification
    };

    onRegister(record);
    setMotivationalMsg("Solicitud de marcaje enviada. Administración validará su reporte.");
    setPin('');

    setTimeout(() => {
      setStatus('idle');
      setCurrentEmp(null);
      setIsProcessing(false);
      setForgottenData({ date: new Date().toISOString().split('T')[0], type: 'in', justification: '' });
    }, 5000);
  };

  useEffect(() => {
    if (pin.length === 6 && status === 'idle' && !isProcessing) {
      const emp = employees.find(e => e.pin === pin && e.status === 'active');
      if (emp) {
        // Buscar validación reciente
        const recentlyValidated = attendance
          .filter(a => a.employeeId === emp.id && a.isForgotten && a.status !== 'pending_approval' && a.validatedAt)
          .sort((a, b) => new Date(b.validatedAt!).getTime() - new Date(a.validatedAt!).getTime())[0];

        if (recentlyValidated) {
          const dateStr = new Date(recentlyValidated.timestamp).toLocaleDateString();
          const state = recentlyValidated.status === 'confirmed' ? 'APROBADO' : 'RECHAZADO';
          setValidationMsg({
            isOpen: true,
            message: `TALENTO HUMANO: Su registro manual del ${dateStr} ha sido ${state}.`,
            type: recentlyValidated.status === 'confirmed' ? 'success' : 'error'
          });
        }

        setCurrentEmp(emp);
        setStatus('confirm');
      } else {
        setStatus('error');
        setTimeout(() => { setStatus('idle'); setPin(''); }, 2000);
      }
    }
  }, [pin, employees, status, attendance, isProcessing]);

  useEffect(() => {
    const handleKey = (e: KeyboardEvent) => {
      if (status !== 'idle' || validationMsg.isOpen || isProcessing) return;
      if (e.key >= '0' && e.key <= '9' && pin.length < 6) setPin(p => p + e.key);
      if (e.key === 'Backspace') setPin(p => p.slice(0, -1));
    };
    window.addEventListener('keydown', handleKey);
    return () => window.removeEventListener('keydown', handleKey);
  }, [pin, status, validationMsg.isOpen, isProcessing]);

  return (
    <div className="min-h-screen gradient-blue flex flex-col items-center justify-center p-4">
      {/* Overlay de Bloqueo tras éxito */}
      {status === 'success' && (
        <div className="fixed inset-0 z-[100] bg-slate-900/80 backdrop-blur-2xl flex flex-col items-center justify-center fade-in">
           <div className="w-24 h-24 bg-emerald-500 text-white rounded-full flex items-center justify-center text-4xl mb-8 shadow-[0_0_60px_rgba(16,185,129,0.5)] animate-in zoom-in">✓</div>
           <p className="text-white font-black text-2xl md:text-3xl uppercase tracking-tighter italic text-center px-10 mb-4 leading-tight">"{motivationalMsg}"</p>
           <div className="flex items-center gap-3">
              <span className="w-3 h-3 bg-emerald-400 rounded-full animate-ping"></span>
              <p className="text-emerald-400 font-black uppercase text-[10px] tracking-[0.5em]">Registro Almacenado y Sincronizado</p>
           </div>
           <p className="mt-12 text-slate-500 text-[8px] font-black uppercase tracking-widest">Espere el reinicio para el siguiente colaborador...</p>
        </div>
      )}

      <div className={`w-full max-w-xl bg-white/95 backdrop-blur-3xl rounded-[3.5rem] shadow-2xl p-8 md:p-14 flex flex-col items-center transition-all duration-700 relative overflow-hidden ${status === 'success' ? 'scale-90 opacity-0' : 'fade-in'}`}>

        {currentHoliday && (
          <div className="absolute top-0 w-full bg-emerald-600 text-white py-2 text-center text-[10px] font-black uppercase tracking-[0.4em]">
            FESTIVIDAD: {currentHoliday.name}
          </div>
        )}

        <h1 className="text-3xl font-black text-slate-900 mb-8 tracking-tighter uppercase italic">{APP_NAME}</h1>
        <div className="mb-10 transform scale-75 md:scale-95"><Clock /></div>

        {status === 'idle' && (
          <div className="w-full text-center">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em] mb-10">VALIDE SU IDENTIDAD (PIN)</p>
            <div className="flex gap-4 justify-center mb-12">
              {[...Array(6)].map((_, i) => (
                <div key={i} className={`w-12 h-16 border-b-4 flex items-center justify-center text-4xl font-black transition-all ${pin.length > i ? 'border-blue-600 text-slate-900 scale-110' : 'border-slate-100'}`}>
                  {pin[i] ? '•' : ''}
                </div>
              ))}
            </div>

            <div className="grid grid-cols-3 gap-3 md:gap-5 max-w-[340px] mx-auto no-print">
              {[1, 2, 3, 4, 5, 6, 7, 8, 9, 'C', 0, '←'].map(btn => (
                <button 
                  key={btn}
                  onClick={() => {
                    if (btn === 'C') setPin('');
                    else if (btn === '←') setPin(p => p.slice(0, -1));
                    else if (pin.length < 6) setPin(p => p + btn);
                  }}
                  className="h-16 md:h-20 bg-slate-50 hover:bg-blue-600 hover:text-white rounded-[1.5rem] text-2xl font-black transition-all active:scale-90 shadow-sm"
                >
                  {btn}
                </button>
              ))}
            </div>
          </div>
        )}

        {status === 'confirm' && currentEmp && (
          <div className="text-center animate-in zoom-in duration-500 w-full">
            <div className="mb-8">
               <div className="w-24 h-24 bg-blue-100 rounded-3xl mx-auto flex items-center justify-center text-4xl font-black text-blue-600 uppercase border-4 border-white shadow-xl">
                 {currentEmp.name[0]}
               </div>
            </div>
            <h2 className="text-3xl md:text-4xl font-black text-slate-900 mb-2 uppercase tracking-tighter leading-none">{currentEmp.name} {currentEmp.surname}</h2>
            <p className="text-slate-400 font-bold uppercase tracking-widest text-[11px] mb-12 italic">Identidad Validada • Seleccione Marcaje</p>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-5 mb-8">
              <button onClick={() => handleMark('in')} className="py-10 bg-emerald-600 text-white rounded-[2rem] font-black text-2xl uppercase shadow-xl hover:bg-emerald-700 transition-all active:scale-95">Ingreso</button>
              <button onClick={() => handleMark('out')} className="py-10 bg-blue-700 text-white rounded-[2rem] font-black text-2xl uppercase shadow-xl hover:bg-blue-800 transition-all active:scale-95">Salida</button>
            </div>

            <button onClick={() => setStatus('forgotten_form')} className="text-blue-600 font-black uppercase text-[10px] tracking-widest hover:underline hover:scale-105 transition-all">Reportar marcaje olvidado</button>
          </div>
        )}

        {status === 'forgotten_form' && currentEmp && (
          <form onSubmit={handleForgottenSubmit} className="w-full space-y-5 animate-in slide-in-from-bottom duration-500">
            <h2 className="text-2xl font-black text-slate-900 uppercase text-center mb-6 tracking-tight">Formulario de Excepción</h2>
            <div className="space-y-4">
              <div>
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Fecha Omitida</label>
                <input type="date" required className="w-full border-2 p-4 rounded-2xl text-xs font-bold bg-slate-50 focus:border-blue-600 outline-none" value={forgottenData.date} onChange={e => setForgottenData({...forgottenData, date: e.target.value})} />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <button type="button" onClick={() => setForgottenData({...forgottenData, type: 'in'})} className={`py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${forgottenData.type === 'in' ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-100 text-slate-400'}`}>Entrada</button>
                <button type="button" onClick={() => setForgottenData({...forgottenData, type: 'out'})} className={`py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${forgottenData.type === 'out' ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-100 text-slate-400'}`}>Salida</button>
              </div>
              <div>
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Justificación Institucional</label>
                <textarea required className="w-full border-2 p-4 rounded-2xl text-xs h-32 focus:border-blue-500 outline-none bg-slate-50" placeholder="Describa el motivo por el cual omitió el registro en tiempo real..." value={forgottenData.justification} onChange={e => setForgottenData({...forgottenData, justification: e.target.value})}></textarea>
              </div>
            </div>
            <div className="flex gap-4 pt-4">
              <button type="button" onClick={() => setStatus('confirm')} className="flex-1 py-5 bg-slate-100 text-slate-500 rounded-[1.5rem] font-black uppercase text-[10px] tracking-widest">Regresar</button>
              <button type="submit" className="flex-[2] py-5 bg-blue-700 text-white rounded-[1.5rem] font-black uppercase text-[10px] shadow-lg tracking-widest">Enviar Solicitud</button>
            </div>
          </form>
        )}

        {status === 'error' && (
          <div className="text-center text-red-600 animate-in zoom-in">
            <div className="text-7xl mb-4">✕</div>
            <h2 className="text-2xl font-black uppercase tracking-tighter italic">Credencial Inválida</h2>
            <p className="text-[10px] font-bold uppercase mt-2 text-slate-400">Verifique su PIN de 6 dígitos</p>
          </div>
        )}
      </div>

      <button onClick={onBack} className={`mt-10 text-white/30 hover:text-white font-black text-[11px] uppercase tracking-[0.5em] transition-all hover:scale-105 ${status === 'success' ? 'opacity-0' : 'opacity-100'}`}>Administración Central</button>

      {/* Modal de Feedback de Validaciones */}
      <Modal isOpen={validationMsg.isOpen} onClose={() => setValidationMsg({...validationMsg, isOpen: false})} title="Comunicado Interno" type={validationMsg.type}>
          <div className="text-center space-y-8">
              <div className={`w-20 h-20 ${validationMsg.type === 'success' ? 'bg-emerald-50 text-emerald-600' : 'bg-red-50 text-red-600'} rounded-full flex items-center justify-center text-4xl mx-auto shadow-sm border border-white`}>
                {validationMsg.type === 'success' ? '✓' : '✕'}
              </div>
              <p className="text-slate-800 font-bold uppercase text-[12px] leading-relaxed italic tracking-tight">{validationMsg.message}</p>
              <button onClick={() => setValidationMsg({...validationMsg, isOpen: false})} className="w-full py-5 bg-slate-900 text-white font-black rounded-2xl uppercase text-[11px] tracking-widest shadow-xl">Aceptar y Continuar</button>
          </div>
      </Modal>
    </div>
  );
};

export default AttendanceSystem;

import React, { useState } from 'react';
import { Employee, Role, BloodType, TerminationReason, AbsenceRecord, CompanyConfig } from '../../types.ts';
import Modal from '../../components/Modal.tsx';

interface EmployeeModuleProps {
  employees: Employee[];
  onUpdate: (employees: Employee[]) => void;
  role: Role;
  attendance: any[];
  payments: any[];
  company: CompanyConfig | null;
}

const EmployeeModule: React.FC<EmployeeModuleProps> = ({ employees, onUpdate, role, company }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingEmp, setEditingEmp] = useState<Employee | null>(null);
  const [viewingEmp, setViewingEmp] = useState<Employee | null>(null);
  const [isTermModalOpen, setIsTermModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [modalAlert, setModalAlert] = useState<{isOpen: boolean, title: string, message: string, type: 'info' | 'success' | 'error'}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  const initialForm: Partial<Employee> = {
    name: '', surname: '', identification: '', birthDate: '', origin: '', address: '',
    phone: '', email: '', bloodType: BloodType.O_POS,
    emergencyContact: { name: '', phone: '' }, startDate: new Date().toISOString().split('T')[0],
    role: Role.EMPLOYEE, isFixed: true, salary: 482.00, isAffiliated: true, overSalaryType: 'accumulate',
    bankInfo: { ifi: '', type: 'Ahorros', account: '' }, photo: '', pin: '',
    status: 'active', observations: [], absences: [], totalHoursWorked: 0
  };

  const [form, setForm] = useState<Partial<Employee>>(initialForm);

  const showAlert = (title: string, message: string, type: 'info' | 'success' | 'error' = 'info') => {
    setModalAlert({ isOpen: true, title, message, type });
  };

  const validateForm = () => {
    if (!form.name || !form.surname || !form.identification || !form.pin) return "Campos obligatorios marcados con asterisco faltantes.";
    if (form.pin?.length !== 6) return "El PIN debe ser estrictamente de 6 caracteres.";
    if (form.phone?.length !== 10) return "El formato de celular es inválido (10 dígitos).";
    return null;
  };

  const handleSave = () => {
    const error = validateForm();
    if (error) {
      showAlert("Validación Fallida", error, "error");
      return;
    }

    let updatedList;
    if (editingEmp) {
      updatedList = employees.map(e => e.id === editingEmp.id ? { ...e, ...form } as Employee : e);
    } else {
      const newEmp = { ...form, id: Math.random().toString(36).substr(2, 9), pinChanges: 0 } as Employee;
      updatedList = [...employees, newEmp];
    }

    onUpdate(updatedList);
    setIsModalOpen(false);
    setEditingEmp(null);
    setForm(initialForm);
    showAlert("Actualización Exitosa", "Registro de personal sincronizado con éxito.", "success");
  };

  const handleTermination = (data: any) => {
    if (!viewingEmp) return;
    const updated = employees.map(e => e.id === viewingEmp.id ? {
      ...e,
      status: 'terminated' as const,
      terminationDate: data.date,
      terminationReason: data.reason,
      terminationDetails: data.details
    } : e);
    onUpdate(updated);
    setIsTermModalOpen(false);
    showAlert("Baja Procesada", "Empleado desvinculado. Generando Acta...", "success");
    setTimeout(() => window.print(), 800);
  };

  return (
    <div className="space-y-6 fade-in overflow-hidden">
      <div className="bg-white p-6 md:p-10 rounded-[2.5rem] shadow-sm border border-slate-100 flex flex-col md:flex-row justify-between items-center no-print gap-6">
        <div className="text-center md:text-left">
          <h2 className="text-2xl md:text-4xl font-black text-slate-900 tracking-tighter uppercase italic leading-none">Capital Humano</h2>
          <p className="text-[10px] text-slate-400 font-black uppercase tracking-[0.3em] mt-2">Gestión de Expedientes y Fichas Técnicas</p>
        </div>
        <button onClick={() => { setForm(initialForm); setEditingEmp(null); setIsModalOpen(true); }} className="w-full md:w-auto px-10 py-5 bg-blue-700 text-white font-black rounded-2xl shadow-xl uppercase text-[11px] tracking-widest hover:bg-blue-800 transition-all active:scale-95">Alta de Colaborador</button>
      </div>

      <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-100 overflow-hidden no-print">
        <div className="p-6 bg-slate-50/50 border-b">
          <div className="relative">
            <input type="text" placeholder="Filtrar por nombre, apellido o identificación..." className="w-full bg-white border-2 border-slate-100 p-4 pl-12 rounded-2xl text-[13px] font-bold outline-none focus:border-blue-500 transition-all shadow-inner" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
            <svg className="w-5 h-5 absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
          </div>
        </div>

        {/* Contenedor de Tabla Responsiva */}
        <div className="overflow-x-auto custom-scroll">
          <table className="w-full text-left min-w-[700px]">
            <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest">
              <tr>
                <th className="px-8 py-5">Perfil</th>
                <th className="px-8 py-5">Apellidos y Nombres</th>
                <th className="px-8 py-5">Estatus Lab.</th>
                <th className="px-8 py-5">Identidad</th>
                <th className="px-8 py-5 text-right">Ficha</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50 text-[12px] font-bold">
              {employees.filter(e => (e.name + " " + e.surname).toLowerCase().includes(searchTerm.toLowerCase()) || e.identification.includes(searchTerm)).map(emp => (
                <tr key={emp.id} className="hover:bg-blue-50/30 transition-colors group">
                  <td className="px-8 py-5">
                    <div className="w-12 h-12 rounded-2xl overflow-hidden bg-slate-100 border-2 border-white shadow-sm group-hover:scale-110 transition-transform">
                      {emp.photo ? <img src={emp.photo} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center text-slate-300">👤</div>}
                    </div>
                  </td>
                  <td className="px-8 py-5 uppercase text-slate-900 tracking-tight">
                    {emp.surname} {emp.name}
                  </td>
                  <td className="px-8 py-5">
                    <span className={`px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-tighter ${emp.status === 'active' ? 'bg-emerald-50 text-emerald-600 border border-emerald-100' : 'bg-red-50 text-red-600 border border-red-100'}`}>
                      {emp.status === 'active' ? 'Activo' : 'Liquidado'}
                    </span>
                  </td>
                  <td className="px-8 py-5 font-mono text-slate-500">{emp.identification}</td>
                  <td className="px-8 py-5 text-right">
                     <button onClick={() => setViewingEmp(emp)} className="p-3 bg-white text-blue-600 rounded-xl border border-slate-100 shadow-sm hover:bg-blue-600 hover:text-white transition-all">
                       <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" /></svg>
                     </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Modales Reemplazando Alerts */}
      <Modal isOpen={modalAlert.isOpen} onClose={() => setModalAlert({...modalAlert, isOpen: false})} title={modalAlert.title} type={modalAlert.type}>
          <div className="text-center space-y-6">
              <p className="text-slate-700 font-bold uppercase text-[11px] leading-relaxed italic">{modalAlert.message}</p>
              <button onClick={() => setModalAlert({...modalAlert, isOpen: false})} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] tracking-widest shadow-xl">Entendido</button>
          </div>
      </Modal>

      {/* ... (resto de modales existentes) ... */}
    </div>
  );
};

export default EmployeeModule;

import React, { useState, useEffect } from 'react';
import { CompanyConfig, Employee, Role, AttendanceRecord, Payment, GlobalSettings } from './types.ts';
import AdminDashboard from './views/AdminDashboard.tsx';
import AttendanceSystem from './views/AttendanceSystem.tsx';
import Modal from './components/Modal.tsx';
import { db, collection, doc, onSnapshot, setDoc, addDoc, compressData, decompressData } from './firebase.ts';

const App: React.FC = () => {
  const [currentUserRole, setCurrentUserRole] = useState<Role | null>(null);
  const [view, setView] = useState<'selection' | 'admin' | 'attendance'>('selection');
  const [isLoadingData, setIsLoadingData] = useState(true);
  const [isDbConnected, setIsDbConnected] = useState(false);
  const [isAdminLoginModalOpen, setIsAdminLoginModalOpen] = useState(false);
  const [adminPassInput, setAdminPassInput] = useState('');
  const [showPass, setShowPass] = useState(false);
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);
  const [isMobile, setIsMobile] = useState(false);

  // App Mode State
  const [appMode, setAppMode] = useState<'full' | 'attendance'>(
    (localStorage.getItem('app_mode') as 'full' | 'attendance') || 'full'
  );

  // Formal Modal States
  const [showWelcome, setShowWelcome] = useState(false);
  const [showLogoutFeedback, setShowLogoutFeedback] = useState(false);
  const [showConfigPrompt, setShowConfigPrompt] = useState(false);
  const [configBoot, setConfigBoot] = useState(true);
  const [configMode, setConfigMode] = useState<'full' | 'attendance'>('full');

  const [modalAlert, setModalAlert] = useState<{isOpen: boolean, title: string, message: string, type: 'info' | 'success' | 'error'}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  const [company, setCompany] = useState<CompanyConfig | null>(null);
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);
  const [payments, setPayments] = useState<Payment[]>([]);
  const [settings, setSettings] = useState<GlobalSettings>({
    sbu: 482.00,
    iessRate: 0.0945,
    reserveRate: 0.0833,
    schedule: {
      monFri: { in: '08:30', out: '13:00' },
      sat: { in: '08:30', out: '13:00' },
      halfDayOff: 'Miércoles tarde'
    }
  });

  const showAlert = (title: string, message: string, type: 'info' | 'success' | 'error' = 'info') => {
    setModalAlert({ isOpen: true, title, message, type });
  };

  useEffect(() => {
    const checkMobile = () => setIsMobile(/iPhone|iPad|iPod|Android/i.test(navigator.userAgent));
    checkMobile();
    window.addEventListener('resize', checkMobile);

    window.addEventListener('beforeinstallprompt', (e) => {
      e.preventDefault();
      setDeferredPrompt(e);
    });

    window.addEventListener('appinstalled', () => {
      setShowConfigPrompt(true);
    });

    const rescueTimer = setTimeout(() => setIsLoadingData(false), 4000);
    const unsubscribes: (() => void)[] = [];

    const updateConnectionStatus = (metadata: any) => {
      if (!metadata.fromCache) setIsDbConnected(true);
    };

    try {
      const unsubCompany = onSnapshot(doc(db, "config", "company"), (docSnap) => {
        if (docSnap.exists()) {
          const data = docSnap.data();
          setCompany(data.payload ? decompressData(data.payload) : data as any);
        }
        updateConnectionStatus(docSnap.metadata);
        setIsLoadingData(false);
        clearTimeout(rescueTimer);
      }, () => setIsDbConnected(false));
      unsubscribes.push(unsubCompany);

      const unsubEmployees = onSnapshot(collection(db, "employees"), (snapshot) => {
        setEmployees(snapshot.docs.map(d => {
          const raw = d.data();
          return raw.payload ? { ...decompressData(raw.payload), id: d.id } : { ...raw, id: d.id };
        }) as Employee[]);
        updateConnectionStatus(snapshot.metadata);
      }, () => setIsDbConnected(false));
      unsubscribes.push(unsubEmployees);

      const unsubAttendance = onSnapshot(collection(db, "attendance"), (snapshot) => {
        setAttendance(snapshot.docs.map(d => {
          const raw = d.data();
          return raw.payload ? { ...decompressData(raw.payload), id: d.id } : { ...raw, id: d.id };
        }) as AttendanceRecord[]);
        updateConnectionStatus(snapshot.metadata);
      }, () => setIsDbConnected(false));
      unsubscribes.push(unsubAttendance);

      const unsubPayments = onSnapshot(collection(db, "payments"), (snapshot) => {
        setPayments(snapshot.docs.map(d => {
          const raw = d.data();
          return raw.payload ? { ...decompressData(raw.payload), id: d.id } : { ...raw, id: d.id };
        }) as Payment[]);
        updateConnectionStatus(snapshot.metadata);
      }, () => setIsDbConnected(false));
      unsubscribes.push(unsubPayments);

    } catch (e) {
      setIsLoadingData(false);
      setIsDbConnected(false);
    }

    return () => { 
      unsubscribes.forEach(unsub => unsub()); 
      clearTimeout(rescueTimer); 
      window.removeEventListener('resize', checkMobile);
    };
  }, []);

  const handleAdminLogin = () => {
    let role: Role | null = null;
    if (adminPassInput === 'admin123') role = Role.SUPER_ADMIN;
    else if (adminPassInput === 'partial123') role = Role.PARTIAL_ADMIN;

    if (role) {
      if (isMobile && role === Role.PARTIAL_ADMIN) {
        showAlert("Acceso Restringido", "El Administrador Parcial requiere una estación de escritorio para su operatividad.", "error");
        return;
      }
      setCurrentUserRole(role);
      setShowWelcome(true);
      setView('admin');
      setIsAdminLoginModalOpen(false);
    } else {
      showAlert("Acceso Denegado", "Las credenciales no coinciden con nuestros registros.", "error");
    }
    setAdminPassInput('');
  };

  const finalizeLogout = () => {
    setCurrentUserRole(null);
    setView('selection');
    setShowLogoutFeedback(false);
  };

  const saveConfig = async () => {
    localStorage.setItem('app_mode', configMode);
    setAppMode(configMode);

    if (configBoot && 'runOnOsLogin' in navigator) {
      try {
        // @ts-ignore
        await navigator.runOnOsLogin.set({ mode: 'windowed' });
      } catch (e) { console.debug(e); }
    }

    setShowConfigPrompt(false);
    showAlert("Terminal Configurada", "Los parámetros del equipo han sido establecidos correctamente.", "success");
  };

  if (isLoadingData) return null;

  if (view === 'selection') {
    return (
      <div className="min-h-screen gradient-blue flex flex-col items-center justify-center p-6">
        <div className="w-full max-w-lg bg-white/95 backdrop-blur-3xl p-10 md:p-16 rounded-[3.5rem] shadow-2xl text-center border border-white/20">
          <div className="mb-12 flex justify-center">
            <div className="relative flex items-center justify-center">
                <div className="loading-ring absolute opacity-20"></div>
                <div className="geometric-logo">
                    <div className="shape"></div>
                    <div className="shape shape-2"></div>
                </div>
            </div>
          </div>
          <h1 className="text-4xl md:text-5xl font-[900] text-slate-900 mb-2 tracking-tighter uppercase leading-none">ASIST UP</h1>
          <p className="text-blue-600 font-black uppercase tracking-[0.5em] text-[8px] mb-12">Enterprise Human Capital Suite</p>

          <div className="space-y-4">
            <button onClick={() => setView('attendance')} className="w-full py-6 bg-blue-700 text-white font-black rounded-3xl shadow-2xl hover:bg-blue-800 transition-all uppercase text-[11px] tracking-widest active:scale-95">Sistema de Asistencia</button>

            {appMode === 'full' && (
              <button onClick={() => setIsAdminLoginModalOpen(true)} className="w-full py-5 text-slate-400 font-black hover:text-slate-900 transition-all uppercase text-[10px] tracking-widest">Consola Administrativa</button>
            )}

            {!localStorage.getItem('app_mode') && deferredPrompt && (
              <button onClick={() => deferredPrompt.prompt()} className="w-full mt-6 py-4 bg-emerald-50 text-emerald-600 font-black rounded-2xl border border-emerald-100 uppercase text-[9px] tracking-widest hover:bg-emerald-100 transition-all">Habilitar Estación de Trabajo</button>
            )}
          </div>

          <div className="mt-10 flex items-center justify-center gap-2">
             <div className={`w-2 h-2 rounded-full ${isDbConnected ? 'bg-emerald-500' : 'bg-red-500 animate-pulse'}`}></div>
             <span className="text-[9px] font-black uppercase tracking-widest text-slate-400">
               {isDbConnected ? 'Sincronización Cloud Activa' : 'Buscando servidor...'}
             </span>
          </div>
        </div>

        <Modal isOpen={isAdminLoginModalOpen} onClose={() => setIsAdminLoginModalOpen(false)} title="Validación de Credenciales">
          <div className="space-y-6">
            <div className="relative">
              <input 
                type={showPass ? "text" : "password"} 
                value={adminPassInput} 
                onChange={e => setAdminPassInput(e.target.value)} 
                onKeyDown={e => e.key === 'Enter' && handleAdminLogin()} 
                className="w-full border-2 border-slate-100 rounded-3xl p-6 text-center text-4xl font-black focus:border-blue-600 outline-none transition-all bg-slate-50 pr-20" 
                placeholder="••••••" 
                autoFocus 
              />
              <button onClick={() => setShowPass(!showPass)} className="absolute right-6 top-1/2 -translate-y-1/2 text-slate-300 hover:text-blue-600">
                {showPass ? (
                  <svg className="w-7 h-7" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" /></svg>
                ) : (
                  <svg className="w-7 h-7" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l18 18" /></svg>
                )}
              </button>
            </div>
            <button onClick={handleAdminLogin} className="w-full py-5 bg-blue-700 text-white font-black rounded-2xl uppercase text-[11px] tracking-widest shadow-xl">Iniciar Gestión</button>
          </div>
        </Modal>

        {/* Modal de Configuración de Terminal */}
        <Modal isOpen={showConfigPrompt} onClose={() => setShowConfigPrompt(false)} title="Protocolo de Instalación">
           <div className="space-y-8">
              <div className="space-y-4">
                 <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Modo de Operación de este equipo</p>
                 <div className="grid grid-cols-2 gap-4">
                    <button onClick={() => setConfigMode('attendance')} className={`p-4 rounded-2xl border-2 transition-all ${configMode === 'attendance' ? 'border-blue-600 bg-blue-50' : 'border-slate-100 opacity-60'}`}>
                       <p className="text-xl mb-1">⏰</p>
                       <p className="text-[10px] font-black uppercase text-slate-900 leading-tight">Terminal de Asistencia</p>
                       <p className="text-[8px] text-slate-400 uppercase font-bold mt-1">Solo marcajes</p>
                    </button>
                    <button onClick={() => setConfigMode('full')} className={`p-4 rounded-2xl border-2 transition-all ${configMode === 'full' ? 'border-blue-600 bg-blue-50' : 'border-slate-100 opacity-60'}`}>
                       <p className="text-xl mb-1">🖥️</p>
                       <p className="text-[10px] font-black uppercase text-slate-900 leading-tight">Consola de Gestión</p>
                       <p className="text-[8px] text-slate-400 uppercase font-bold mt-1">Acceso total</p>
                    </button>
                 </div>
              </div>
              <div className="flex items-center justify-between p-5 bg-slate-50 rounded-2xl border">
                 <div>
                    <p className="text-[11px] font-black text-slate-900 uppercase">Inicio Automático</p>
                    <p className="text-[9px] text-slate-400 font-bold uppercase">Arrancar con el sistema</p>
                 </div>
                 <button onClick={() => setConfigBoot(!configBoot)} className={`w-14 h-8 rounded-full relative transition-all ${configBoot ? 'bg-blue-600' : 'bg-slate-300'}`}>
                    <div className={`absolute top-1 w-6 h-6 bg-white rounded-full transition-all ${configBoot ? 'left-7' : 'left-1'}`}></div>
                 </button>
              </div>
              <button onClick={saveConfig} className="w-full py-5 bg-slate-900 text-white font-black rounded-2xl uppercase text-[11px] tracking-widest shadow-2xl">Finalizar Configuración</button>
           </div>
        </Modal>

        <Modal isOpen={showLogoutFeedback} onClose={finalizeLogout} title="Sincronización Finalizada" type="success">
           <div className="text-center space-y-8 p-4">
              <div className="w-24 h-24 bg-emerald-50 text-emerald-600 rounded-full flex items-center justify-center text-5xl mx-auto shadow-inner border-2 border-white">✓</div>
              <div className="space-y-3">
                 <h3 className="text-2xl font-black text-slate-900 uppercase tracking-tighter">Sesión Cerrada</h3>
                 <p className="text-sm text-slate-500 font-medium leading-relaxed italic">Todos los registros y cambios han sido sincronizados y protegidos en la nube de forma segura.</p>
              </div>
              <button onClick={finalizeLogout} className="w-full py-5 bg-slate-900 text-white font-black rounded-2xl uppercase text-[11px] tracking-widest shadow-xl">Finalizar Protocolo</button>
           </div>
        </Modal>

        <Modal isOpen={modalAlert.isOpen} onClose={() => setModalAlert({...modalAlert, isOpen: false})} title={modalAlert.title} type={modalAlert.type}>
           <div className="text-center space-y-6 p-2">
              <p className="text-slate-700 font-bold text-sm uppercase leading-relaxed tracking-tight">{modalAlert.message}</p>
              <button onClick={() => setModalAlert({...modalAlert, isOpen: false})} className="w-full py-4 bg-slate-900 text-white font-black rounded-2xl uppercase text-[11px] tracking-widest">Entendido</button>
           </div>
        </Modal>
      </div>
    );
  }

  if (view === 'attendance') {
    return <AttendanceSystem employees={employees} attendance={attendance} onBack={() => setView('selection')} onRegister={async (r: AttendanceRecord) => { await addDoc(collection(db, "attendance"), { payload: compressData(r), timestamp: r.timestamp }); }} onUpdateEmployees={async (emps: Employee[]) => { for (const e of emps) { await setDoc(doc(db, "employees", e.id), { payload: compressData(e) }); } }} />;
  }

  return (
    <>
      <AdminDashboard 
        role={currentUserRole!} 
        isDbConnected={isDbConnected}
        onLogout={() => setShowLogoutFeedback(true)} 
        company={company}
        onUpdateCompany={async (c: CompanyConfig) => await setDoc(doc(db, "config", "company"), { payload: compressData(c) })}
        employees={employees}
        onUpdateEmployees={async (emps: Employee[]) => { for (const e of emps) { await setDoc(doc(db, "employees", e.id), { payload: compressData(e) }); } }}
        attendance={attendance}
        payments={payments}
        onUpdatePayments={async (pys: Payment[]) => { for (const p of pys) { if (p.id.length > 15) await addDoc(collection(db, "payments"), { payload: compressData(p) }); else await setDoc(doc(db, "payments", p.id), { payload: compressData(p) }); } }}
        settings={settings}
        onUpdateSettings={async (s: GlobalSettings) => await setDoc(doc(db, "config", "settings"), { payload: compressData(s) })}
      />

      <Modal isOpen={showWelcome} onClose={() => setShowWelcome(false)} title="Acceso Autorizado" type="success">
         <div className="text-center space-y-6">
            <div className="geometric-logo mx-auto scale-125 my-8">
                <div className="shape"></div>
                <div className="shape shape-2"></div>
            </div>
            <div className="space-y-2">
               <h2 className="text-3xl font-black text-slate-900 tracking-tighter uppercase">¡Bienvenido!</h2>
               <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest">Iniciando sesión como: <span className="text-blue-600">{currentUserRole}</span></p>
            </div>
            <button onClick={() => setShowWelcome(false)} className="w-full py-5 bg-blue-700 text-white font-black rounded-2xl uppercase text-[11px] tracking-widest shadow-2xl">Entrar al Sistema</button>
         </div>
      </Modal>

      <Modal isOpen={modalAlert.isOpen} onClose={() => setModalAlert({...modalAlert, isOpen: false})} title={modalAlert.title} type={modalAlert.type}>
           <div className="text-center space-y-6">
              <p className="text-slate-700 font-bold uppercase text-[11px] tracking-tight">{modalAlert.message}</p>
              <button onClick={() => setModalAlert({...modalAlert, isOpen: false})} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] tracking-widest shadow-xl">Continuar</button>
           </div>
      </Modal>
    </>
  );
};

export default App;

