import React, { useState, useEffect } from 'react';
import { Employee, AttendanceRecord } from '../types.ts';
import Clock from '../components/Clock.tsx';
import Modal from '../components/Modal.tsx';
import { APP_NAME, MOTIVATIONAL_MESSAGES_START, MOTIVATIONAL_MESSAGES_END, ECUADOR_HOLIDAYS } from '../constants.tsx';

interface AttendanceSystemProps {
  employees: Employee[];
  attendance: AttendanceRecord[];
  onRegister: (record: AttendanceRecord) => void;
  onBack: () => void;
  onUpdateEmployees: (employees: Employee[]) => void;
}

const AttendanceSystem: React.FC<AttendanceSystemProps> = ({ employees, attendance, onRegister, onBack, onUpdateEmployees }) => {
  const [pin, setPin] = useState('');
  const [status, setStatus] = useState<'idle' | 'confirm' | 'forgotten_form' | 'success' | 'error'>('idle');
  const [isProcessing, setIsProcessing] = useState(false);
  const [currentEmp, setCurrentEmp] = useState<Employee | null>(null);
  const [motivationalMsg, setMotivationalMsg] = useState('');

  const [validationMsg, setValidationMsg] = useState<{isOpen: boolean, message: string, type: 'success' | 'error'}>({
    isOpen: false, message: '', type: 'success'
  });

  const [forgottenData, setForgottenData] = useState({
    date: new Date().toISOString().split('T')[0],
    type: 'in' as 'in' | 'out',
    justification: ''
  });

  const today = new Date();
  const currentHoliday = ECUADOR_HOLIDAYS.find(h => h.month === today.getMonth() && h.day === today.getDate());

  const handleMark = (type: 'in' | 'out') => {
    if (!currentEmp || isProcessing) return;

    setIsProcessing(true);
    setStatus('success');

    const record: AttendanceRecord = {
      id: Math.random().toString(36).substr(2, 9),
      employeeId: currentEmp.id,
      timestamp: new Date().toISOString(),
      type,
      status: 'confirmed'
    };

    onRegister(record);

    const msgs = type === 'in' ? MOTIVATIONAL_MESSAGES_START : MOTIVATIONAL_MESSAGES_END;
    setMotivationalMsg(msgs[Math.floor(Math.random() * msgs.length)]);
    setPin('');

    setTimeout(() => {
      setStatus('idle');
      setCurrentEmp(null);
      setIsProcessing(false);
    }, 5000);
  };

  const handleForgottenSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentEmp || !forgottenData.justification || isProcessing) return;

    setIsProcessing(true);
    setStatus('success');

    const record: AttendanceRecord = {
      id: Math.random().toString(36).substr(2, 9),
      employeeId: currentEmp.id,
      timestamp: new Date(forgottenData.date + 'T12:00:00').toISOString(),
      type: forgottenData.type,
      status: 'pending_approval',
      isForgotten: true,
      justification: forgottenData.justification
    };

    onRegister(record);
    setMotivationalMsg("Reporte enviado correctamente. Su marcaje será validado por la administración.");
    setPin('');

    setTimeout(() => {
      setStatus('idle');
      setCurrentEmp(null);
      setIsProcessing(false);
      setForgottenData({ date: new Date().toISOString().split('T')[0], type: 'in', justification: '' });
    }, 5000);
  };

  useEffect(() => {
    if (pin.length === 6 && status === 'idle' && !isProcessing) {
      const emp = employees.find(e => e.pin === pin && e.status === 'active');
      if (emp) {
        const recentlyValidated = attendance
          .filter(a => a.employeeId === emp.id && a.isForgotten && a.status !== 'pending_approval' && a.validatedAt)
          .sort((a, b) => new Date(b.validatedAt!).getTime() - new Date(a.validatedAt!).getTime())[0];

        if (recentlyValidated) {
          const dateStr = new Date(recentlyValidated.timestamp).toLocaleDateString();
          const state = recentlyValidated.status === 'confirmed' ? 'APROBADO' : 'RECHAZADO';
          setValidationMsg({
            isOpen: true,
            message: `TALENTO HUMANO: Su registro manual del día ${dateStr} ha sido ${state} por la gerencia.`,
            type: recentlyValidated.status === 'confirmed' ? 'success' : 'error'
          });
        }

        setCurrentEmp(emp);
        setStatus('confirm');
      } else {
        setStatus('error');
        setTimeout(() => { setStatus('idle'); setPin(''); }, 2000);
      }
    }
  }, [pin, employees, status, attendance, isProcessing]);

  useEffect(() => {
    const handleKey = (e: KeyboardEvent) => {
      if (status !== 'idle' || validationMsg.isOpen || isProcessing) return;
      if (e.key >= '0' && e.key <= '9' && pin.length < 6) setPin(p => p + e.key);
      if (e.key === 'Backspace') setPin(p => p.slice(0, -1));
    };
    window.addEventListener('keydown', handleKey);
    return () => window.removeEventListener('keydown', handleKey);
  }, [pin, status, validationMsg.isOpen, isProcessing]);

  return (
    <div className="min-h-screen gradient-blue flex flex-col items-center justify-center p-4">
      {/* Overlay de Bloqueo tras registro exitoso */}
      {status === 'success' && (
        <div className="fixed inset-0 z-[100] bg-slate-900/80 backdrop-blur-2xl flex flex-col items-center justify-center fade-in">
           <div className="w-24 h-24 bg-emerald-500 text-white rounded-full flex items-center justify-center text-4xl mb-10 shadow-[0_0_80px_rgba(16,185,129,0.5)] animate-in zoom-in">✓</div>
           <p className="text-white font-black text-2xl md:text-3xl uppercase tracking-tighter text-center px-10 mb-6 leading-tight max-w-2xl">"{motivationalMsg}"</p>
           <div className="flex flex-col items-center gap-4">
              <div className="flex items-center gap-3">
                <span className="w-3 h-3 bg-emerald-400 rounded-full animate-ping"></span>
                <p className="text-emerald-400 font-black uppercase text-[10px] tracking-[0.5em]">Registro Almacenado y Protegido</p>
              </div>
              <p className="text-slate-500 text-[8px] font-black uppercase tracking-[0.3em]">Reiniciando estación en 5 segundos...</p>
           </div>
        </div>
      )}

      <div className={`w-full max-w-xl bg-white/95 backdrop-blur-3xl rounded-[3.5rem] shadow-2xl p-6 md:p-14 flex flex-col items-center transition-all duration-700 relative overflow-hidden ${status === 'success' ? 'scale-90 opacity-0 pointer-events-none' : 'fade-in'}`}>

        {currentHoliday && (
          <div className="absolute top-0 w-full bg-emerald-600 text-white py-2.5 text-center text-[10px] font-black uppercase tracking-[0.4em]">
            FESTIVIDAD: {currentHoliday.name}
          </div>
        )}

        <h1 className="text-2xl font-black text-slate-900 mb-6 tracking-tighter uppercase">{APP_NAME}</h1>
        <div className="mb-8 transform scale-[0.65] md:scale-95"><Clock /></div>

        {status === 'idle' && (
          <div className="w-full text-center">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em] mb-8">INGRESE PIN DE ASISTENCIA</p>
            <div className="flex gap-3 md:gap-4 justify-center mb-10">
              {[...Array(6)].map((_, i) => (
                <div key={i} className={`w-10 h-14 md:w-12 md:h-16 border-b-4 flex items-center justify-center text-3xl md:text-4xl font-black transition-all ${pin.length > i ? 'border-blue-600 text-slate-900 scale-110' : 'border-slate-100'}`}>
                  {pin[i] ? '•' : ''}
                </div>
              ))}
            </div>

            <div className="grid grid-cols-3 gap-3 md:gap-5 max-w-[340px] mx-auto no-print">
              {[1, 2, 3, 4, 5, 6, 7, 8, 9, 'C', 0, '←'].map(btn => (
                <button 
                  key={btn}
                  onClick={() => {
                    if (btn === 'C') setPin('');
                    else if (btn === '←') setPin(p => p.slice(0, -1));
                    else if (pin.length < 6) setPin(p => p + btn);
                  }}
                  className="h-14 md:h-20 bg-slate-50 hover:bg-blue-600 hover:text-white rounded-2xl md:rounded-[1.5rem] text-xl md:text-2xl font-black transition-all active:scale-90 shadow-sm border border-slate-100"
                >
                  {btn}
                </button>
              ))}
            </div>
          </div>
        )}

        {status === 'confirm' && currentEmp && (
          <div className="text-center animate-in zoom-in duration-500 w-full">
            <div className="mb-8">
               <div className="w-24 h-24 bg-blue-100 rounded-[2rem] mx-auto flex items-center justify-center text-4xl font-black text-blue-600 uppercase border-4 border-white shadow-xl">
                 {currentEmp.name[0]}
               </div>
            </div>
            <h2 className="text-3xl font-black text-slate-900 mb-1 uppercase tracking-tighter leading-none">{currentEmp.name} {currentEmp.surname}</h2>
            <p className="text-slate-400 font-bold uppercase tracking-widest text-[10px] mb-12">Identidad Validada</p>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-5 mb-8">
              <button onClick={() => handleMark('in')} className="py-8 md:py-10 bg-emerald-600 text-white rounded-[2rem] font-black text-2xl uppercase shadow-xl hover:bg-emerald-700 transition-all active:scale-95">Ingreso</button>
              <button onClick={() => handleMark('out')} className="py-8 md:py-10 bg-blue-700 text-white rounded-[2rem] font-black text-2xl uppercase shadow-xl hover:bg-blue-800 transition-all active:scale-95">Salida</button>
            </div>

            <button onClick={() => setStatus('forgotten_form')} className="text-blue-600 font-black uppercase text-[10px] tracking-widest hover:underline transition-all">Reportar omisión de registro</button>
          </div>
        )}

        {status === 'forgotten_form' && currentEmp && (
          <form onSubmit={handleForgottenSubmit} className="w-full space-y-5 animate-in slide-in-from-bottom duration-500 max-h-[60vh] overflow-y-auto pr-2 custom-scroll">
            <h2 className="text-2xl font-black text-slate-900 uppercase text-center mb-6 tracking-tight leading-none">Registro de Excepción</h2>
            <div className="space-y-5">
              <div>
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Fecha Omitida</label>
                <input type="date" required className="w-full border-2 p-4 rounded-2xl text-xs font-bold bg-slate-50 focus:border-blue-600 outline-none mt-1" value={forgottenData.date} onChange={e => setForgottenData({...forgottenData, date: e.target.value})} />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <button type="button" onClick={() => setForgottenData({...forgottenData, type: 'in'})} className={`py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${forgottenData.type === 'in' ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-100 text-slate-400'}`}>Entrada</button>
                <button type="button" onClick={() => setForgottenData({...forgottenData, type: 'out'})} className={`py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${forgottenData.type === 'out' ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-100 text-slate-400'}`}>Salida</button>
              </div>
              <div>
                <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Justificación Técnica</label>
                <textarea required className="w-full border-2 p-4 rounded-2xl text-xs h-32 focus:border-blue-500 outline-none bg-slate-50 mt-1" placeholder="Detalle el motivo institucional por el cual no se realizó el marcaje en tiempo real..." value={forgottenData.justification} onChange={e => setForgottenData({...forgottenData, justification: e.target.value})}></textarea>
              </div>
            </div>
            <div className="flex gap-4 pt-4">
              <button type="button" onClick={() => setStatus('confirm')} className="flex-1 py-5 bg-slate-100 text-slate-500 rounded-[1.5rem] font-black uppercase text-[10px] tracking-widest">Regresar</button>
              <button type="submit" className="flex-[2] py-5 bg-blue-700 text-white rounded-[1.5rem] font-black uppercase text-[10px] shadow-lg tracking-widest">Enviar Reporte</button>
            </div>
          </form>
        )}

        {status === 'error' && (
          <div className="text-center text-red-600 animate-in zoom-in">
            <div className="text-7xl mb-4">✕</div>
            <h2 className="text-2xl font-black uppercase tracking-tighter leading-none">Acceso Denegado</h2>
            <p className="text-[10px] font-bold uppercase mt-2 text-slate-400">PIN ingresado no válido</p>
          </div>
        )}
      </div>

      <button onClick={onBack} className={`mt-10 text-white/30 hover:text-white font-black text-[11px] uppercase tracking-[0.5em] transition-all hover:scale-105 ${status === 'success' ? 'opacity-0' : 'opacity-100'}`}>Estación Administrativa</button>

      <Modal isOpen={validationMsg.isOpen} onClose={() => setValidationMsg({...validationMsg, isOpen: false})} title="Notificación Administrativa" type={validationMsg.type}>
          <div className="text-center space-y-8 p-4">
              <div className={`w-24 h-24 ${validationMsg.type === 'success' ? 'bg-emerald-50 text-emerald-600' : 'bg-red-50 text-red-600'} rounded-[2rem] flex items-center justify-center text-5xl mx-auto shadow-sm border-2 border-white`}>
                {validationMsg.type === 'success' ? '✓' : '✕'}
              </div>
              <p className="text-slate-800 font-bold uppercase text-[12px] leading-relaxed tracking-tight italic">"{validationMsg.message}"</p>
              <button onClick={() => setValidationMsg({...validationMsg, isOpen: false})} className="w-full py-5 bg-slate-900 text-white font-black rounded-2xl uppercase text-[11px] tracking-widest shadow-xl">Confirmar Lectura</button>
          </div>
      </Modal>
    </div>
  );
};

