import React, { useState, useEffect, useMemo } from 'react';
import { Employee, AttendanceRecord, GlobalSettings } from '../types.ts';
import Clock from '../components/Clock.tsx';
import Modal from '../components/Modal.tsx';
import { APP_NAME, MOTIVATIONAL_MESSAGES_START, MOTIVATIONAL_MESSAGES_END, ECUADOR_HOLIDAYS } from '../constants.tsx';

interface AttendanceSystemProps {
  employees: Employee[];
  attendance: AttendanceRecord[];
  onRegister: (record: AttendanceRecord) => void;
  onBack: () => void;
  onUpdateEmployees: (employees: Employee[]) => void;
  settings: GlobalSettings;
}

const AttendanceSystem: React.FC<AttendanceSystemProps> = ({ employees, attendance, onRegister, onBack, onUpdateEmployees, settings }) => {
  const [pin, setPin] = useState('');
  const [status, setStatus] = useState<'idle' | 'confirm' | 'forgotten_form' | 'success' | 'error'>('idle');
  const [isProcessing, setIsProcessing] = useState(false);
  const [currentEmp, setCurrentEmp] = useState<Employee | null>(null);
  const [motivationalMsg, setMotivationalMsg] = useState('');

  const [specialModal, setSpecialModal] = useState<{isOpen: boolean, title: string, message: string, type: 'success' | 'error' | 'info'}>({
    isOpen: false, title: '', message: '', type: 'success'
  });

  const [forgottenData, setForgottenData] = useState({
    date: new Date().toISOString().split('T')[0],
    type: 'in' as 'in' | 'out',
    justification: ''
  });

  const today = new Date();
  const currentHoliday = ECUADOR_HOLIDAYS.find(h => h.month === today.getMonth() && h.day === today.getDate());

  const isBirthday = useMemo(() => {
    if (!currentEmp) return false;
    const bday = new Date(currentEmp.birthDate);
    return bday.getDate() === today.getDate() && bday.getMonth() === today.getMonth();
  }, [currentEmp, today]);

  const handleMark = (type: 'in' | 'out') => {
    if (!currentEmp || isProcessing) return;

    setIsProcessing(true);
    setStatus('success');

    // Validar Atraso Crítico (> 15 mins)
    let isCriticalLate = false;
    if (type === 'in') {
      const now = new Date();
      const [schedH, schedM] = settings.schedule.monFri.in.split(':').map(Number);
      const schedDate = new Date();
      schedDate.setHours(schedH, schedM, 0, 0);

      const diffMins = (now.getTime() - schedDate.getTime()) / (1000 * 60);
      if (diffMins > 15) {
        isCriticalLate = true;
      }
    }

    const record: AttendanceRecord = {
      id: Math.random().toString(36).substr(2, 9),
      employeeId: currentEmp.id,
      timestamp: new Date().toISOString(),
      type,
      status: 'confirmed',
      isLate: isCriticalLate
    };

    onRegister(record);

    let baseMsg = type === 'in' ? MOTIVATIONAL_MESSAGES_START[Math.floor(Math.random() * MOTIVATIONAL_MESSAGES_START.length)] : MOTIVATIONAL_MESSAGES_END[Math.floor(Math.random() * MOTIVATIONAL_MESSAGES_END.length)];

    if (isBirthday) {
      baseMsg = `¡FELIZ CUMPLEAÑOS ${currentEmp.name.toUpperCase()}! 🎂 La organización celebra tu vida. ¡Disfruta tu día!`;
    } else if (isCriticalLate) {
      // Fix: Corrected typo "crético" to "crítico" in the feedback message.
      baseMsg = `Registro de ingreso completado. Se ha notificado a Administración sobre el atraso crítico.`;
    }

    setMotivationalMsg(baseMsg);
    setPin('');

    setTimeout(() => {
      setStatus('idle');
      setCurrentEmp(null);
      setIsProcessing(false);
    }, 6000);
  };

  const handleForgottenSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentEmp || !forgottenData.justification || isProcessing) return;

    setIsProcessing(true);
    setStatus('success');

    const record: AttendanceRecord = {
      id: Math.random().toString(36).substr(2, 9),
      employeeId: currentEmp.id,
      timestamp: new Date(forgottenData.date + 'T12:00:00').toISOString(),
      type: forgottenData.type,
      status: 'pending_approval',
      isForgotten: true,
      justification: forgottenData.justification
    };

    onRegister(record);
    setMotivationalMsg("Reporte excepcional enviado. El Administrador recibirá una notificación push para su validación inmediata.");
    setPin('');

    setTimeout(() => {
      setStatus('idle');
      setCurrentEmp(null);
      setIsProcessing(false);
      setForgottenData({ date: new Date().toISOString().split('T')[0], type: 'in', justification: '' });
    }, 6000);
  };

  useEffect(() => {
    if (pin.length === 6 && status === 'idle' && !isProcessing) {
      const emp = employees.find(e => e.pin === pin && e.status === 'active');
      if (emp) {
        const recentlyValidated = attendance
          .filter(a => a.employeeId === emp.id && a.isForgotten && a.status !== 'pending_approval' && a.validatedAt)
          .sort((a, b) => new Date(b.validatedAt!).getTime() - new Date(a.validatedAt!).getTime())[0];

        if (recentlyValidated) {
          const dateStr = new Date(recentlyValidated.timestamp).toLocaleDateString();
          const state = recentlyValidated.status === 'confirmed' ? 'APROBADO' : 'RECHAZADO';
          setSpecialModal({
            isOpen: true,
            title: "Resolución de Gestión",
            message: `TALENTO HUMANO: Su registro extemporáneo del día ${dateStr} ha sido formalmente ${state}.`,
            type: recentlyValidated.status === 'confirmed' ? 'success' : 'error'
          });
        }

        setCurrentEmp(emp);
        setStatus('confirm');
      } else {
        setStatus('error');
        setTimeout(() => { setStatus('idle'); setPin(''); }, 2000);
      }
    }
  }, [pin, employees, status, attendance, isProcessing]);

  useEffect(() => {
    const handleKey = (e: KeyboardEvent) => {
      if (status !== 'idle' || specialModal.isOpen || isProcessing) return;
      if (e.key >= '0' && e.key <= '9' && pin.length < 6) setPin(p => p + e.key);
      if (e.key === 'Backspace') setPin(p => p.slice(0, -1));
    };
    window.addEventListener('keydown', handleKey);
    return () => window.removeEventListener('keydown', handleKey);
  }, [pin, status, specialModal.isOpen, isProcessing]);

  return (
    <div className="min-h-screen gradient-blue flex flex-col items-center justify-center p-4">
      {status === 'success' && (
        <div className="fixed inset-0 z-[100] bg-slate-900/90 backdrop-blur-3xl flex flex-col items-center justify-center fade-in">
           {isBirthday && <div className="absolute top-10 text-6xl animate-bounce">🎈 🎊 🎈</div>}
           <div className={`w-28 h-28 ${isBirthday ? 'bg-blue-600' : 'bg-emerald-500'} text-white rounded-[2.5rem] flex items-center justify-center text-5xl mb-12 shadow-[0_0_100px_rgba(59,130,246,0.6)] animate-in zoom-in duration-500`}>
             {isBirthday ? '🎂' : '✓'}
           </div>
           <p className="text-white font-[950] text-3xl md:text-4xl uppercase tracking-tighter text-center px-12 mb-10 leading-none max-w-4xl">
             {motivationalMsg}
           </p>
           <div className="flex flex-col items-center gap-6">
              <div className="flex items-center gap-4">
                <span className="w-4 h-4 bg-blue-400 rounded-full animate-ping"></span>
                <p className="text-blue-400 font-black uppercase text-[12px] tracking-[0.6em]">Protocolo de Registro Finalizado</p>
              </div>
              <p className="text-slate-600 text-[9px] font-black uppercase tracking-[0.4em]">Estación se reiniciará en breves segundos...</p>
           </div>
        </div>
      )}

      <div className={`w-full max-w-xl bg-white/95 backdrop-blur-3xl rounded-[4rem] shadow-2xl p-6 md:p-16 flex flex-col items-center transition-all duration-700 relative overflow-hidden ${status === 'success' ? 'scale-90 opacity-0 pointer-events-none' : 'fade-in'}`}>

        {currentHoliday && (
          <div className="absolute top-0 w-full bg-blue-700 text-white py-3 text-center text-[10px] font-black uppercase tracking-[0.5em]">
            FESTIVIDAD NACIONAL: {currentHoliday.name}
          </div>
        )}

        <h1 className="text-2xl font-[950] text-slate-900 mb-8 tracking-tighter uppercase leading-none">ASIST UP</h1>
        <div className="mb-12 transform scale-[0.6] md:scale-95"><Clock /></div>

        {status === 'idle' && (
          <div className="w-full text-center">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.5em] mb-10">VALIDACIÓN DE IDENTIDAD (PIN)</p>
            <div className="flex gap-4 justify-center mb-12">
              {[...Array(6)].map((_, i) => (
                <div key={i} className={`w-10 h-16 md:w-14 md:h-20 border-b-4 flex items-center justify-center text-4xl md:text-5xl font-black transition-all ${pin.length > i ? 'border-blue-600 text-slate-900 scale-110' : 'border-slate-100'}`}>
                  {pin[i] ? '•' : ''}
                </div>
              ))}
            </div>

            <div className="grid grid-cols-3 gap-3 md:gap-6 max-w-[360px] mx-auto no-print">
              {[1, 2, 3, 4, 5, 6, 7, 8, 9, 'C', 0, '←'].map(btn => (
                <button 
                  key={btn}
                  onClick={() => {
                    if (btn === 'C') setPin('');
                    else if (btn === '←') setPin(p => p.slice(0, -1));
                    else if (pin.length < 6) setPin(p => p + btn);
                  }}
                  className="h-16 md:h-24 bg-slate-50 hover:bg-blue-700 hover:text-white rounded-3xl text-2xl md:text-3xl font-black transition-all active:scale-90 shadow-sm border border-slate-100/50"
                >
                  {btn}
                </button>
              ))}
            </div>
          </div>
        )}

        {status === 'confirm' && currentEmp && (
          <div className="text-center animate-in zoom-in duration-500 w-full">
            <div className="mb-10 relative flex justify-center">
               <div className="loading-ring absolute opacity-10"></div>
               <div className="w-28 h-28 bg-blue-50 rounded-[2.5rem] mx-auto flex items-center justify-center text-5xl font-black text-blue-700 uppercase border-4 border-white shadow-2xl relative z-10">
                 {currentEmp.name[0]}
               </div>
            </div>
            <h2 className="text-4xl font-[950] text-slate-900 mb-2 uppercase tracking-tighter leading-none">{currentEmp.name} {currentEmp.surname}</h2>
            <p className="text-slate-400 font-bold uppercase tracking-[0.4em] text-[11px] mb-14">Identidad Validada Correctamente</p>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-10">
              <button onClick={() => handleMark('in')} className="py-10 md:py-12 bg-blue-700 text-white rounded-[2.5rem] font-black text-2xl uppercase shadow-2xl hover:bg-blue-800 transition-all active:scale-95 shimmer-effect">Ingreso</button>
              <button onClick={() => handleMark('out')} className="py-10 md:py-12 bg-slate-900 text-white rounded-[2.5rem] font-black text-2xl uppercase shadow-2xl hover:bg-black transition-all active:scale-95">Salida</button>
            </div>

            <button onClick={() => setStatus('forgotten_form')} className="text-blue-600 font-black uppercase text-[11px] tracking-widest hover:underline transition-all">Reportar Incidencia de Marcaje</button>
          </div>
        )}

        {status === 'forgotten_form' && currentEmp && (
          <form onSubmit={handleForgottenSubmit} className="w-full space-y-6 animate-in slide-in-from-bottom duration-500 custom-scroll max-h-[60vh] overflow-y-auto pr-2">
            <h2 className="text-3xl font-[950] text-slate-900 uppercase text-center mb-10 tracking-tighter leading-none">Formulario de Excepción</h2>
            <div className="space-y-6">
              <div>
                <label className="text-[11px] font-black uppercase text-slate-400 tracking-widest ml-2">Fecha de la Incidencia</label>
                <input type="date" required className="w-full border-2 p-5 rounded-[1.5rem] text-sm font-black bg-slate-50 focus:border-blue-600 outline-none mt-2" value={forgottenData.date} onChange={e => setForgottenData({...forgottenData, date: e.target.value})} />
              </div>
              <div className="grid grid-cols-2 gap-5">
                <button type="button" onClick={() => setForgottenData({...forgottenData, type: 'in'})} className={`py-5 rounded-[1.5rem] text-[11px] font-black uppercase tracking-widest transition-all ${forgottenData.type === 'in' ? 'bg-blue-700 text-white shadow-xl' : 'bg-slate-100 text-slate-400'}`}>Entrada</button>
                <button type="button" onClick={() => setForgottenData({...forgottenData, type: 'out'})} className={`py-5 rounded-[1.5rem] text-[11px] font-black uppercase tracking-widest transition-all ${forgottenData.type === 'out' ? 'bg-blue-700 text-white shadow-xl' : 'bg-slate-100 text-slate-400'}`}>Salida</button>
              </div>
              <div>
                <label className="text-[11px] font-black uppercase text-slate-400 tracking-widest ml-2">Justificación Detallada</label>
                <textarea required className="w-full border-2 p-5 rounded-[1.5rem] text-sm h-40 focus:border-blue-500 outline-none bg-slate-50 mt-2" placeholder="Describa el motivo institucional o técnico por el cual no se realizó el marcaje regular..." value={forgottenData.justification} onChange={e => setForgottenData({...forgottenData, justification: e.target.value})}></textarea>
              </div>
            </div>
            <div className="flex gap-5 pt-6">
              <button type="button" onClick={() => setStatus('confirm')} className="flex-1 py-6 bg-slate-100 text-slate-500 rounded-3xl font-black uppercase text-[11px] tracking-widest">Regresar</button>
              <button type="submit" className="flex-[2] py-6 bg-blue-700 text-white rounded-3xl font-black uppercase text-[11px] shadow-2xl tracking-widest active:scale-95 transition-all">Enviar a Validación</button>
            </div>
          </form>
        )}

        {status === 'error' && (
          <div className="text-center text-red-600 animate-in zoom-in">
            <div className="text-8xl mb-6">✕</div>
            <h2 className="text-3xl font-[950] uppercase tracking-tighter leading-none">Acceso Denegado</h2>
            <p className="text-[11px] font-black uppercase mt-4 text-slate-400 tracking-widest">PIN de Identidad Incorrecto</p>
          </div>
        )}
      </div>

      <button onClick={onBack} className={`mt-14 text-white/30 hover:text-white font-black text-[12px] uppercase tracking-[0.6em] transition-all hover:scale-105 ${status === 'success' ? 'opacity-0' : 'opacity-100'}`}>Estación de Gestión Central</button>

      <Modal isOpen={specialModal.isOpen} onClose={() => setSpecialModal({...specialModal, isOpen: false})} title={specialModal.title} type={specialModal.type as any}>
          <div className="text-center space-y-10 p-6">
              <div className={`w-28 h-28 ${specialModal.type === 'success' ? 'bg-emerald-50 text-emerald-600' : 'bg-red-50 text-red-600'} rounded-[2.5rem] flex items-center justify-center text-6xl mx-auto shadow-sm border-2 border-white`}>
                {specialModal.type === 'success' ? '✓' : '✕'}
              </div>
              <p className="text-slate-900 font-black uppercase text-[14px] leading-relaxed tracking-tighter">"{specialModal.message}"</p>
              <button onClick={() => setSpecialModal({...specialModal, isOpen: false})} className="w-full py-6 bg-slate-900 text-white font-black rounded-3xl uppercase text-[11px] tracking-widest shadow-2xl active:scale-95 transition-all">Confirmar Lectura</button>
          </div>
      </Modal>
    </div>
  );
};

export default AttendanceSystem;

import React, { useState, useEffect, useCallback } from 'react';
import { CompanyConfig, Employee, Role, AttendanceRecord, Payment, GlobalSettings } from './types.ts';
import AdminDashboard from './views/AdminDashboard.tsx';
import AttendanceSystem from './views/AttendanceSystem.tsx';
import Modal from './components/Modal.tsx';
import { db, collection, doc, onSnapshot, setDoc, addDoc, compressData, decompressData } from './firebase.ts';

const App: React.FC = () => {
  const [currentUserRole, setCurrentUserRole] = useState<Role | null>(null);
  const [view, setView] = useState<'selection' | 'admin' | 'attendance'>('selection');
  const [isLoadingData, setIsLoadingData] = useState(true);
  const [isDbConnected, setIsDbConnected] = useState(false);
  const [isAdminLoginModalOpen, setIsAdminLoginModalOpen] = useState(false);
  const [adminPassInput, setAdminPassInput] = useState('');
  const [showPass, setShowPass] = useState(false);
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);
  const [isMobile, setIsMobile] = useState(false);

  const [appMode, setAppMode] = useState<'full' | 'attendance'>(
    (localStorage.getItem('app_mode') as 'full' | 'attendance') || 'full'
  );

  const [showWelcome, setShowWelcome] = useState(false);
  const [showLogoutFeedback, setShowLogoutFeedback] = useState(false);
  const [showConfigPrompt, setShowConfigPrompt] = useState(false);
  const [configBoot, setConfigBoot] = useState(true);
  const [configMode, setConfigMode] = useState<'full' | 'attendance'>('full');

  const [modalAlert, setModalAlert] = useState<{isOpen: boolean, title: string, message: string, type: 'info' | 'success' | 'error'}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  const [company, setCompany] = useState<CompanyConfig | null>(null);
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);
  const [payments, setPayments] = useState<Payment[]>([]);
  const [settings, setSettings] = useState<GlobalSettings>({
    sbu: 482.00,
    iessRate: 0.0945,
    reserveRate: 0.0833,
    schedule: {
      monFri: { in: '08:30', out: '13:00' },
      sat: { in: '08:30', out: '13:00' },
      halfDayOff: 'Miércoles tarde'
    }
  });

  const showAlert = (title: string, message: string, type: 'info' | 'success' | 'error' = 'info') => {
    setModalAlert({ isOpen: true, title, message, type });
  };

  const sendPushNotification = useCallback((title: string, body: string) => {
    if (Notification.permission === 'granted') {
      new Notification(title, { body, icon: 'https://cdn-icons-png.flaticon.com/512/1063/1063376.png' });
    }
  }, []);

  useEffect(() => {
    const checkMobile = () => setIsMobile(/iPhone|iPad|iPod|Android/i.test(navigator.userAgent));
    checkMobile();
    window.addEventListener('resize', checkMobile);

    if (Notification.permission === 'default') {
      Notification.requestPermission();
    }

    window.addEventListener('beforeinstallprompt', (e) => {
      e.preventDefault();
      setDeferredPrompt(e);
    });

    window.addEventListener('appinstalled', () => {
      setShowConfigPrompt(true);
    });

    const unsubscribes: (() => void)[] = [];
    const rescueTimer = setTimeout(() => setIsLoadingData(false), 3000);

    const updateConnectionStatus = (metadata: any) => {
      if (!metadata.fromCache) setIsDbConnected(true);
    };

    try {
      const unsubCompany = onSnapshot(doc(db, "config", "company"), (docSnap) => {
        if (docSnap.exists()) {
          const data = docSnap.data();
          setCompany(data.payload ? decompressData(data.payload) : data as any);
        }
        updateConnectionStatus(docSnap.metadata);
        setIsLoadingData(false);
        clearTimeout(rescueTimer);
      }, () => setIsDbConnected(false));
      unsubscribes.push(unsubCompany);

      const unsubEmployees = onSnapshot(collection(db, "employees"), (snapshot) => {
        setEmployees(snapshot.docs.map(d => {
          const raw = d.data();
          return raw.payload ? { ...decompressData(raw.payload), id: d.id } : { ...raw, id: d.id };
        }) as Employee[]);
        updateConnectionStatus(snapshot.metadata);
      }, () => setIsDbConnected(false));
      unsubscribes.push(unsubEmployees);

      const unsubAttendance = onSnapshot(collection(db, "attendance"), (snapshot) => {
        const newRecords = snapshot.docs.map(d => {
          const raw = d.data();
          return raw.payload ? { ...decompressData(raw.payload), id: d.id } : { ...raw, id: d.id };
        }) as AttendanceRecord[];

        // Notificaciones Push para el Admin
        if (localStorage.getItem('admin_logged_in') === 'true') {
          snapshot.docChanges().forEach((change) => {
            if (change.type === "added" && !change.doc.metadata.fromCache) {
              const rec = decompressData(change.doc.data().payload) as AttendanceRecord;
              const emp = employees.find(e => e.id === rec.employeeId);
              if (rec.isForgotten) {
                sendPushNotification("Solicitud de Marcaje", `${emp?.surname} ha enviado una justificación.`);
              }
              if (rec.isLate) {
                sendPushNotification("Atraso Crítico", `${emp?.surname} ha marcado con más de 15m de atraso.`);
              }
            }
          });
        }

        setAttendance(newRecords);
        updateConnectionStatus(snapshot.metadata);
      }, () => setIsDbConnected(false));
      unsubscribes.push(unsubAttendance);

      onSnapshot(collection(db, "payments"), (snapshot) => {
        setPayments(snapshot.docs.map(d => {
          const raw = d.data();
          return raw.payload ? { ...decompressData(raw.payload), id: d.id } : { ...raw, id: d.id };
        }) as Payment[]);
      });

    } catch (e) {
      setIsLoadingData(false);
      setIsDbConnected(false);
    }

    return () => { 
      unsubscribes.forEach(unsub => unsub()); 
      clearTimeout(rescueTimer);
      window.removeEventListener('resize', checkMobile);
    };
  }, [employees, sendPushNotification]);

  const handleAdminLogin = () => {
    let role: Role | null = null;
    if (adminPassInput === 'admin123') role = Role.SUPER_ADMIN;
    else if (adminPassInput === 'partial123') role = Role.PARTIAL_ADMIN;

    if (role) {
      setCurrentUserRole(role);
      localStorage.setItem('admin_logged_in', 'true');
      setShowWelcome(true);
      setView('admin');
      setIsAdminLoginModalOpen(false);
    } else {
      showAlert("Error Jerárquico", "Las credenciales no tienen autorización para acceder a la gestión central.", "error");
    }
    setAdminPassInput('');
  };

  const finalizeLogout = () => {
    setCurrentUserRole(null);
    localStorage.removeItem('admin_logged_in');
    setView('selection');
    setShowLogoutFeedback(false);
  };

  const saveConfig = async () => {
    localStorage.setItem('app_mode', configMode);
    setAppMode(configMode);

    if (configBoot && 'runOnOsLogin' in navigator) {
      try {
        // @ts-ignore
        await navigator.runOnOsLogin.set({ mode: 'windowed' });
      } catch (e) { console.debug(e); }
    }

    setShowConfigPrompt(false);
    showAlert("Terminal Aprovisionada", "El equipo ha sido configurado como " + (configMode === 'full' ? "Consola Total" : "Terminal de Asistencia") + ".", "success");
  };

  if (isLoadingData) return null;

  if (view === 'selection') {
    return (
      <div className="min-h-screen gradient-blue flex flex-col items-center justify-center p-6">
        <div className="w-full max-w-lg bg-white/95 backdrop-blur-3xl p-10 md:p-16 rounded-[4.5rem] shadow-2xl text-center border border-white/20">
          <div className="mb-14 flex justify-center">
            <div className="relative flex items-center justify-center logo-container">
                <div className="loading-ring absolute opacity-10"></div>
                <div className="geometric-logo">
                    <div className="shape shape-1"></div>
                    <div className="shape shape-2"></div>
                    <div className="shape shape-3"></div>
                </div>
            </div>
          </div>
          <h1 className="text-4xl md:text-5xl font-[950] text-slate-900 mb-2 tracking-tighter uppercase leading-none">ASIST UP</h1>
          <p className="text-blue-600 font-black uppercase tracking-[0.6em] text-[10px] mb-14">Enterprise Control Suite</p>

          <div className="space-y-4">
            <button onClick={() => setView('attendance')} className="w-full py-6 bg-blue-700 text-white font-black rounded-[2.5rem] shadow-2xl hover:bg-blue-800 transition-all uppercase text-[11px] tracking-widest active:scale-95 shimmer-effect">Sistema de Asistencia</button>

            {appMode === 'full' && (
              <button onClick={() => setIsAdminLoginModalOpen(true)} className="w-full py-5 text-slate-400 font-black hover:text-slate-900 transition-all uppercase text-[10px] tracking-widest">Consola Administrativa</button>
            )}

            {!localStorage.getItem('app_mode') && deferredPrompt && (
              <button onClick={() => deferredPrompt.prompt()} className="w-full mt-8 py-4 bg-slate-50 text-slate-400 font-black rounded-2xl border-2 border-dashed uppercase text-[9px] tracking-widest">Configurar Equipo</button>
            )}
          </div>

          <div className="mt-14 flex items-center justify-center gap-3">
             <div className={`w-3 h-3 rounded-full ${isDbConnected ? 'bg-emerald-500 shadow-[0_0_12px_rgba(16,185,129,0.6)]' : 'bg-red-500 animate-pulse'}`}></div>
             <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">
               {isDbConnected ? 'Cloud Sync Activo' : 'Offline Mode'}
             </span>
          </div>
        </div>

        <Modal isOpen={isAdminLoginModalOpen} onClose={() => setIsAdminLoginModalOpen(false)} title="Autorización de Gestión">
          <div className="space-y-8 p-2">
            <div className="relative">
              <input 
                type={showPass ? "text" : "password"} 
                value={adminPassInput} 
                onChange={e => setAdminPassInput(e.target.value)} 
                onKeyDown={e => e.key === 'Enter' && handleAdminLogin()} 
                className="w-full border-2 border-slate-100 rounded-[2.5rem] p-8 text-center text-4xl font-black focus:border-blue-600 outline-none transition-all bg-slate-50 pr-24" 
                placeholder="••••••" 
                autoFocus 
              />
              <button onClick={() => setShowPass(!showPass)} className="absolute right-8 top-1/2 -translate-y-1/2 text-slate-300 hover:text-blue-600 transition-colors">
                {showPass ? (
                  <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" /></svg>
                ) : (
                  <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l18 18" /></svg>
                )}
              </button>
            </div>
            <button onClick={handleAdminLogin} className="w-full py-6 bg-blue-700 text-white font-black rounded-3xl uppercase text-[11px] tracking-widest shadow-2xl active:scale-95 transition-all">Ingresar al Centro de Control</button>
          </div>
        </Modal>

        {/* Modal de Configuración de Terminal */}
        <Modal isOpen={showConfigPrompt} onClose={() => setShowConfigPrompt(false)} title="Configuración de Estación">
           <div className="space-y-10 p-2">
              <div className="space-y-6">
                 <p className="text-[11px] font-black text-slate-400 uppercase tracking-widest text-center">Modo de Operación</p>
                 <div className="grid grid-cols-2 gap-5">
                    <button onClick={() => setConfigMode('attendance')} className={`p-8 rounded-[2.5rem] border-2 transition-all flex flex-col items-center gap-4 ${configMode === 'attendance' ? 'border-blue-600 bg-blue-50' : 'border-slate-100 opacity-50'}`}>
                       <div className="geometric-logo scale-50"><div className="shape shape-1"></div></div>
                       <p className="text-[12px] font-[900] uppercase text-slate-900 leading-none">Asistencia</p>
                       <p className="text-[8px] font-bold text-slate-400 uppercase">Solo marcajes</p>
                    </button>
                    <button onClick={() => setConfigMode('full')} className={`p-8 rounded-[2.5rem] border-2 transition-all flex flex-col items-center gap-4 ${configMode === 'full' ? 'border-blue-600 bg-blue-50' : 'border-slate-100 opacity-50'}`}>
                       <div className="geometric-logo scale-50"><div className="shape shape-1"></div><div className="shape shape-2"></div></div>
                       <p className="text-[12px] font-[900] uppercase text-slate-900 leading-none">Consola</p>
                       <p className="text-[8px] font-bold text-slate-400 uppercase">Gestión Total</p>
                    </button>
                 </div>
              </div>
              <div className="flex items-center justify-between p-7 bg-slate-50 rounded-[2rem] border">
                 <div className="space-y-1">
                    <p className="text-[12px] font-black text-slate-900 uppercase">Auto-Arranque</p>
                    <p className="text-[10px] text-slate-400 font-bold uppercase tracking-tight">Iniciar con el Sistema Operativo</p>
                 </div>
                 <button onClick={() => setConfigBoot(!configBoot)} className={`w-16 h-9 rounded-full relative transition-all ${configBoot ? 'bg-blue-600 shadow-[0_0_12px_rgba(37,99,235,0.4)]' : 'bg-slate-300'}`}>
                    <div className={`absolute top-1 w-7 h-7 bg-white rounded-full transition-all shadow-md ${configBoot ? 'left-8' : 'left-1'}`}></div>
                 </button>
              </div>
              <button onClick={saveConfig} className="w-full py-6 bg-slate-900 text-white font-black rounded-3xl uppercase text-[11px] tracking-widest shadow-2xl active:scale-95 transition-all">Finalizar Configuración</button>
           </div>
        </Modal>

        <Modal isOpen={showLogoutFeedback} onClose={finalizeLogout} title="Cierre de Sesión" type="success">
           <div className="text-center space-y-10 p-6">
              <div className="relative flex justify-center">
                 <div className="loading-ring opacity-20 absolute"></div>
                 <div className="w-24 h-24 bg-emerald-50 text-emerald-600 rounded-[2.5rem] flex items-center justify-center text-5xl mx-auto shadow-inner border-2 border-white">✓</div>
              </div>
              <div className="space-y-4">
                 <h3 className="text-3xl font-[950] text-slate-900 uppercase tracking-tighter">Sincronización Cloud</h3>
                 <p className="text-sm text-slate-500 font-medium leading-relaxed max-w-xs mx-auto">La terminal ha finalizado el volcado de datos. La información de talento está protegida.</p>
              </div>
              <button onClick={finalizeLogout} className="w-full py-6 bg-slate-900 text-white font-black rounded-3xl uppercase text-[11px] tracking-widest shadow-2xl active:scale-95 transition-all">Finalizar Protocolo</button>
           </div>
        </Modal>

        <Modal isOpen={modalAlert.isOpen} onClose={() => setModalAlert({...modalAlert, isOpen: false})} title={modalAlert.title} type={modalAlert.type}>
           <div className="text-center space-y-8 p-4">
              <p className="text-slate-800 font-bold text-sm uppercase leading-relaxed tracking-tight">{modalAlert.message}</p>
              <button onClick={() => setModalAlert({...modalAlert, isOpen: false})} className="w-full py-5 bg-slate-900 text-white font-black rounded-2xl uppercase text-[11px] tracking-widest shadow-xl">Aceptar</button>
           </div>
        </Modal>
      </div>
    );
  }

  if (view === 'attendance') {
    return <AttendanceSystem employees={employees} attendance={attendance} onBack={() => setView('selection')} settings={settings} onRegister={async (r: AttendanceRecord) => { await addDoc(collection(db, "attendance"), { payload: compressData(r), timestamp: r.timestamp }); }} onUpdateEmployees={async (emps: Employee[]) => { for (const e of emps) { await setDoc(doc(db, "employees", e.id), { payload: compressData(e) }); } }} />;
  }

  return (
    <>
      <AdminDashboard 
        role={currentUserRole!} 
        isDbConnected={isDbConnected}
        onLogout={() => setShowLogoutFeedback(true)} 
        company={company}
        onUpdateCompany={async (c: CompanyConfig) => await setDoc(doc(db, "config", "company"), { payload: compressData(c) })}
        employees={employees}
        onUpdateEmployees={async (emps: Employee[]) => { for (const e of emps) { await setDoc(doc(db, "employees", e.id), { payload: compressData(e) }); } }}
        attendance={attendance}
        payments={payments}
        onUpdatePayments={async (pys: Payment[]) => { for (const p of pys) { if (p.id.length > 15) await addDoc(collection(db, "payments"), { payload: compressData(p) }); else await setDoc(doc(db, "payments", p.id), { payload: compressData(p) }); } }}
        settings={settings}
        onUpdateSettings={async (s: GlobalSettings) => await setDoc(doc(db, "config", "settings"), { payload: compressData(s) })}
      />

      <Modal isOpen={showWelcome} onClose={() => setShowWelcome(false)} title="Terminal Autorizada" type="success">
         <div className="text-center space-y-8 p-4">
            <div className="logo-container mx-auto flex justify-center py-6">
                <div className="geometric-logo scale-150">
                    <div className="shape shape-1"></div>
                    <div className="shape shape-2"></div>
                    <div className="shape shape-3"></div>
                </div>
            </div>
            <div className="space-y-2">
               <h2 className="text-3xl font-[950] text-slate-900 tracking-tighter uppercase leading-none">Acceso Validado</h2>
               <p className="text-slate-400 text-[10px] font-bold uppercase tracking-[0.4em]">Rol: <span className="text-blue-600">{currentUserRole}</span></p>
            </div>
            <button onClick={() => setShowWelcome(false)} className="w-full py-6 bg-blue-700 text-white font-black rounded-3xl uppercase text-[11px] tracking-widest shadow-2xl active:scale-95 transition-all">Iniciar Gestión</button>
         </div>
      </Modal>

      <Modal isOpen={modalAlert.isOpen} onClose={() => setModalAlert({...modalAlert, isOpen: false})} title={modalAlert.title} type={modalAlert.type}>
           <div className="text-center space-y-8 p-4">
              <p className="text-slate-800 font-bold uppercase text-[12px] leading-relaxed tracking-tight">{modalAlert.message}</p>
              <button onClick={() => setModalAlert({...modalAlert, isOpen: false})} className="w-full py-5 bg-slate-900 text-white font-black rounded-2xl uppercase text-[11px] tracking-widest shadow-2xl">Confirmar</button>
           </div>
      </Modal>
    </>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { Employee, AttendanceRecord, GlobalSettings } from '../types.ts';
import Clock from '../components/Clock.tsx';
import Modal from '../components/Modal.tsx';
import { APP_NAME, MOTIVATIONAL_MESSAGES_START, MOTIVATIONAL_MESSAGES_END, ECUADOR_HOLIDAYS } from '../constants.tsx';

interface AttendanceSystemProps {
  employees: Employee[];
  attendance: AttendanceRecord[];
  onRegister: (record: AttendanceRecord) => void;
  onBack: () => void;
  onUpdateEmployees: (employees: Employee[]) => void;
  settings: GlobalSettings;
}

const AttendanceSystem: React.FC<AttendanceSystemProps> = ({ employees, attendance, onRegister, onBack, onUpdateEmployees, settings }) => {
  const [pin, setPin] = useState('');
  const [status, setStatus] = useState<'idle' | 'confirm' | 'forgotten_form' | 'success' | 'error'>('idle');
  const [isProcessing, setIsProcessing] = useState(false);
  const [currentEmp, setCurrentEmp] = useState<Employee | null>(null);
  const [motivationalMsg, setMotivationalMsg] = useState('');

  const [specialModal, setSpecialModal] = useState<{isOpen: boolean, title: string, message: string, type: 'success' | 'error' | 'info'}>({
    isOpen: false, title: '', message: '', type: 'success'
  });

  const [forgottenData, setForgottenData] = useState({
    date: new Date().toISOString().split('T')[0],
    type: 'in' as 'in' | 'out',
    justification: ''
  });

  const today = new Date();
  const currentHoliday = ECUADOR_HOLIDAYS.find(h => h.month === today.getMonth() && h.day === today.getDate());

  const isBirthday = useMemo(() => {
    if (!currentEmp) return false;
    const bday = new Date(currentEmp.birthDate);
    // Ajuste de zona horaria para comparación de solo fecha
    return bday.getUTCDate() === today.getDate() && bday.getUTCMonth() === today.getMonth();
  }, [currentEmp, today]);

  const handleMark = (type: 'in' | 'out') => {
    if (!currentEmp || isProcessing) return;

    setIsProcessing(true);

    // Validar Atraso Crítico (> 15 mins)
    let isCriticalLate = false;
    if (type === 'in') {
      const now = new Date();
      const [schedH, schedM] = settings.schedule.monFri.in.split(':').map(Number);
      const schedDate = new Date();
      schedDate.setHours(schedH, schedM, 0, 0);

      const diffMins = (now.getTime() - schedDate.getTime()) / (1000 * 60);
      if (diffMins > 15) isCriticalLate = true;
    }

    const record: AttendanceRecord = {
      id: Math.random().toString(36).substr(2, 9),
      employeeId: currentEmp.id,
      timestamp: new Date().toISOString(),
      type,
      status: 'confirmed',
      isLate: isCriticalLate
    };

    onRegister(record);

    let baseMsg = type === 'in' 
      ? MOTIVATIONAL_MESSAGES_START[Math.floor(Math.random() * MOTIVATIONAL_MESSAGES_START.length)] 
      : MOTIVATIONAL_MESSAGES_END[Math.floor(Math.random() * MOTIVATIONAL_MESSAGES_END.length)];

    if (isBirthday) {
      baseMsg = `¡FELIZ CUMPLEAÑOS ${currentEmp.name.toUpperCase()}! 🎂 La organización celebra tu vida. ¡Disfruta al máximo tu día especial!`;
    } else if (isCriticalLate) {
      baseMsg = `Marcaje de entrada procesado. Se ha notificado a Administración sobre el atraso crítico superior a 15 minutos.`;
    }

    setMotivationalMsg(baseMsg);
    setStatus('success');
    setPin('');

    setTimeout(() => {
      setStatus('idle');
      setCurrentEmp(null);
      setIsProcessing(false);
    }, 6000);
  };

  const handleForgottenSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentEmp || !forgottenData.justification || isProcessing) return;

    setIsProcessing(true);

    const record: AttendanceRecord = {
      id: Math.random().toString(36).substr(2, 9),
      employeeId: currentEmp.id,
      timestamp: new Date(forgottenData.date + 'T12:00:00').toISOString(),
      type: forgottenData.type,
      status: 'pending_approval',
      isForgotten: true,
      justification: forgottenData.justification
    };

    onRegister(record);
    setMotivationalMsg("Solicitud de excepción enviada. El Administrador ha sido notificado para la validación de su reporte.");
    setStatus('success');
    setPin('');

    setTimeout(() => {
      setStatus('idle');
      setCurrentEmp(null);
      setIsProcessing(false);
      setForgottenData({ date: new Date().toISOString().split('T')[0], type: 'in', justification: '' });
    }, 6000);
  };

  useEffect(() => {
    if (pin.length === 6 && status === 'idle' && !isProcessing) {
      const emp = employees.find(e => e.pin === pin && e.status === 'active');
      if (emp) {
        const recentlyValidated = attendance
          .filter(a => a.employeeId === emp.id && a.isForgotten && a.status !== 'pending_approval' && a.validatedAt)
          .sort((a, b) => new Date(b.validatedAt!).getTime() - new Date(a.validatedAt!).getTime())[0];

        if (recentlyValidated) {
          const dateStr = new Date(recentlyValidated.timestamp).toLocaleDateString();
          const state = recentlyValidated.status === 'confirmed' ? 'APROBADO' : 'RECHAZADO';
          setSpecialModal({
            isOpen: true,
            title: "Comunicado de Talento Humano",
            message: `Su reporte de marcaje olvidado del día ${dateStr} ha sido formalmente ${state}.`,
            type: recentlyValidated.status === 'confirmed' ? 'success' : 'error'
          });
        }

        setCurrentEmp(emp);
        setStatus('confirm');
      } else {
        setStatus('error');
        setTimeout(() => { setStatus('idle'); setPin(''); }, 2000);
      }
    }
  }, [pin, employees, status, attendance, isProcessing]);

  useEffect(() => {
    const handleKey = (e: KeyboardEvent) => {
      if (status !== 'idle' || specialModal.isOpen || isProcessing) return;
      if (e.key >= '0' && e.key <= '9' && pin.length < 6) setPin(p => p + e.key);
      if (e.key === 'Backspace') setPin(p => p.slice(0, -1));
    };
    window.addEventListener('keydown', handleKey);
    return () => window.removeEventListener('keydown', handleKey);
  }, [pin, status, specialModal.isOpen, isProcessing]);

  return (
    <div className="min-h-screen gradient-blue flex flex-col items-center justify-center p-4">
      {status === 'success' && (
        <div className="fixed inset-0 z-[100] bg-slate-900/90 backdrop-blur-3xl flex flex-col items-center justify-center fade-in">
           {isBirthday && <div className="absolute top-10 text-7xl animate-bounce">🎊 🎈 🎁</div>}
           <div className={`w-32 h-32 ${isBirthday ? 'bg-blue-600' : 'bg-emerald-500'} text-white rounded-[3rem] flex items-center justify-center text-6xl mb-12 shadow-[0_0_120px_rgba(59,130,246,0.5)] animate-in zoom-in duration-500`}>
             {isBirthday ? '🎂' : '✓'}
           </div>
           <p className="text-white font-[950] text-3xl md:text-5xl uppercase tracking-tighter text-center px-12 mb-12 leading-tight max-w-4xl">
             {motivationalMsg}
           </p>
           <div className="flex flex-col items-center gap-8">
              <div className="flex items-center gap-5">
                <span className="w-5 h-5 bg-blue-400 rounded-full animate-ping"></span>
                <p className="text-blue-400 font-black uppercase text-[14px] tracking-[0.6em]">Registro Procesado Exitosamente</p>
              </div>
              <p className="text-slate-600 text-[10px] font-black uppercase tracking-[0.4em]">Estación activa para el siguiente colaborador en 6s...</p>
           </div>
        </div>
      )}

      <div className={`w-full max-w-xl bg-white/95 backdrop-blur-3xl rounded-[4.5rem] shadow-2xl p-6 md:p-16 flex flex-col items-center transition-all duration-700 relative overflow-hidden ${status === 'success' ? 'scale-90 opacity-0 pointer-events-none' : 'fade-in'}`}>

        {currentHoliday && (
          <div className="absolute top-0 w-full bg-blue-700 text-white py-4 text-center text-[10px] font-[900] uppercase tracking-[0.6em] shadow-lg">
            FESTIVIDAD: {currentHoliday.name}
          </div>
        )}

        <h1 className="text-2xl font-[950] text-slate-900 mb-10 tracking-tighter uppercase leading-none">ASIST UP</h1>
        <div className="mb-14 transform scale-[0.6] md:scale-95"><Clock /></div>

        {status === 'idle' && (
          <div className="w-full text-center">
            <p className="text-[11px] font-black text-slate-400 uppercase tracking-[0.5em] mb-12">VALIDAR IDENTIDAD (PIN)</p>
            <div className="flex gap-4 justify-center mb-14">
              {[...Array(6)].map((_, i) => (
                <div key={i} className={`w-10 h-16 md:w-16 md:h-24 border-b-4 flex items-center justify-center text-4xl md:text-6xl font-black transition-all ${pin.length > i ? 'border-blue-600 text-slate-900 scale-110' : 'border-slate-100'}`}>
                  {pin[i] ? '•' : ''}
                </div>
              ))}
            </div>

            <div className="grid grid-cols-3 gap-3 md:gap-6 max-w-[400px] mx-auto no-print">
              {[1, 2, 3, 4, 5, 6, 7, 8, 9, 'C', 0, '←'].map(btn => (
                <button 
                  key={btn}
                  onClick={() => {
                    if (btn === 'C') setPin('');
                    else if (btn === '←') setPin(p => p.slice(0, -1));
                    else if (pin.length < 6) setPin(p => p + btn);
                  }}
                  className="h-16 md:h-24 bg-slate-50 hover:bg-blue-700 hover:text-white rounded-[2rem] text-2xl md:text-4xl font-black transition-all active:scale-90 shadow-sm border border-slate-100/50"
                >
                  {btn}
                </button>
              ))}
            </div>
          </div>
        )}

        {status === 'confirm' && currentEmp && (
          <div className="text-center animate-in zoom-in duration-500 w-full">
            <div className="mb-12 relative flex justify-center">
               <div className="loading-ring absolute opacity-10"></div>
               <div className="w-32 h-32 bg-blue-50 rounded-[3rem] mx-auto flex items-center justify-center text-6xl font-black text-blue-700 uppercase border-4 border-white shadow-2xl relative z-10">
                 {currentEmp.name[0]}
               </div>
            </div>
            <h2 className="text-4xl font-[950] text-slate-900 mb-2 uppercase tracking-tighter leading-none">{currentEmp.name} {currentEmp.surname}</h2>
            <p className="text-slate-400 font-bold uppercase tracking-[0.4em] text-[12px] mb-16">Acceso Validado</p>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-12">
              <button onClick={() => handleMark('in')} className="py-12 bg-blue-700 text-white rounded-[2.5rem] font-black text-3xl uppercase shadow-2xl hover:bg-blue-800 transition-all active:scale-95 shimmer-effect">Ingreso</button>
              <button onClick={() => handleMark('out')} className="py-12 bg-slate-900 text-white rounded-[2.5rem] font-black text-3xl uppercase shadow-2xl hover:bg-black transition-all active:scale-95">Salida</button>
            </div>

            <button onClick={() => setStatus('forgotten_form')} className="text-blue-600 font-black uppercase text-[12px] tracking-[0.2em] hover:underline transition-all">Informar Incidencia de Registro</button>
          </div>
        )}

        {status === 'forgotten_form' && currentEmp && (
          <form onSubmit={handleForgottenSubmit} className="w-full space-y-6 animate-in slide-in-from-bottom duration-500 custom-scroll max-h-[60vh] overflow-y-auto pr-2">
            <h2 className="text-3xl font-[950] text-slate-900 uppercase text-center mb-10 tracking-tighter leading-none">Reporte de Excepción</h2>
            <div className="space-y-6">
              <div>
                <label className="text-[11px] font-black uppercase text-slate-400 tracking-widest ml-3">Fecha del Marcaje Omitido</label>
                <input type="date" required className="w-full border-2 p-5 rounded-[2rem] text-sm font-black bg-slate-50 focus:border-blue-600 outline-none mt-2 shadow-inner" value={forgottenData.date} onChange={e => setForgottenData({...forgottenData, date: e.target.value})} />
              </div>
              <div className="grid grid-cols-2 gap-5">
                <button type="button" onClick={() => setForgottenData({...forgottenData, type: 'in'})} className={`py-6 rounded-[2rem] text-[12px] font-black uppercase tracking-widest transition-all ${forgottenData.type === 'in' ? 'bg-blue-700 text-white shadow-xl' : 'bg-slate-100 text-slate-400'}`}>Entrada</button>
                <button type="button" onClick={() => setForgottenData({...forgottenData, type: 'out'})} className={`py-6 rounded-[2rem] text-[12px] font-black uppercase tracking-widest transition-all ${forgottenData.type === 'out' ? 'bg-blue-700 text-white shadow-xl' : 'bg-slate-100 text-slate-400'}`}>Salida</button>
              </div>
              <div>
                <label className="text-[11px] font-black uppercase text-slate-400 tracking-widest ml-3">Justificación Institucional</label>
                <textarea required className="w-full border-2 p-6 rounded-[2rem] text-sm h-40 focus:border-blue-500 outline-none bg-slate-50 mt-2 shadow-inner" placeholder="Especifique el motivo de la omisión del registro regular..." value={forgottenData.justification} onChange={e => setForgottenData({...forgottenData, justification: e.target.value})}></textarea>
              </div>
            </div>
            <div className="flex gap-5 pt-6">
              <button type="button" onClick={() => setStatus('confirm')} className="flex-1 py-6 bg-slate-100 text-slate-500 rounded-[2rem] font-black uppercase text-[11px] tracking-widest">Cancelar</button>
              <button type="submit" className="flex-[2] py-6 bg-blue-700 text-white rounded-[2rem] font-black uppercase text-[12px] shadow-2xl tracking-[0.2em] active:scale-95 transition-all">Enviar a Revisión</button>
            </div>
          </form>
        )}

        {status === 'error' && (
          <div className="text-center text-red-600 animate-in zoom-in">
            <div className="text-9xl mb-8">✕</div>
            <h2 className="text-4xl font-[950] uppercase tracking-tighter leading-none">Error de PIN</h2>
            <p className="text-[12px] font-black uppercase mt-4 text-slate-400 tracking-[0.3em]">Credencial no reconocida</p>
          </div>
        )}
      </div>

      <button onClick={onBack} className={`mt-14 text-white/30 hover:text-white font-black text-[12px] uppercase tracking-[0.6em] transition-all hover:scale-105 ${status === 'success' ? 'opacity-0' : 'opacity-100'}`}>Gestión Administrativa Central</button>

      <Modal isOpen={specialModal.isOpen} onClose={() => setSpecialModal({...specialModal, isOpen: false})} title={specialModal.title} type={specialModal.type as any}>
          <div className="text-center space-y-12 p-8">
              <div className={`w-32 h-32 ${specialModal.type === 'success' ? 'bg-emerald-50 text-emerald-600' : 'bg-red-50 text-red-600'} rounded-[3rem] flex items-center justify-center text-7xl mx-auto shadow-sm border-2 border-white`}>
                {specialModal.type === 'success' ? '✓' : '✕'}
              </div>
              <p className="text-slate-950 font-[900] uppercase text-[16px] leading-relaxed tracking-tighter">"{specialModal.message}"</p>
              <button onClick={() => setSpecialModal({...specialModal, isOpen: false})} className="w-full py-7 bg-slate-950 text-white font-black rounded-[2rem] uppercase text-[12px] tracking-widest shadow-2xl active:scale-95 transition-all">Entendido</button>
          </div>
      </Modal>
    </div>
  );
};

