import React, { useState } from 'react';
import { Employee, Role, BloodType, TerminationReason } from '../../types.ts';
import Modal from '../../components/Modal.tsx';

interface EmployeeModuleProps {
  employees: Employee[];
  onUpdate: (employees: Employee[]) => void;
  role: Role;
  attendance: any[];
  payments: any[];
  company: any;
}

const EmployeeModule: React.FC<EmployeeModuleProps> = ({ employees, onUpdate, role }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingEmp, setEditingEmp] = useState<Employee | null>(null);
  const [viewingEmp, setViewingEmp] = useState<Employee | null>(null);
  const [isTermModalOpen, setIsTermModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  const [termData, setTermData] = useState({
    date: new Date().toISOString().split('T')[0],
    reason: TerminationReason.VOLUNTARY,
    details: ''
  });

  const [modalAlert, setModalAlert] = useState<{isOpen: boolean, title: string, message: string, type: 'info' | 'success' | 'error'}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  const initialForm: Partial<Employee> = {
    name: '', surname: '', identification: '', birthDate: '', phone: '', email: '', 
    bloodType: BloodType.O_POS, startDate: new Date().toISOString().split('T')[0],
    role: Role.EMPLOYEE, salary: 482.00, status: 'active', photo: '', pin: '',
    bankInfo: { ifi: 'Banco del Austro', type: 'Ahorros', account: '' }, isAffiliated: true
  };

  const [form, setForm] = useState<Partial<Employee>>(initialForm);

  const showAlert = (title: string, message: string, type: 'info' | 'success' | 'error' = 'info') => {
    setModalAlert({ isOpen: true, title, message, type });
  };

  const handleSave = () => {
    if (!form.name || !form.surname || !form.identification || !form.pin) {
      showAlert("Validación Obligatoria", "Todos los campos marcados son requeridos para la ficha legal.", "error");
      return;
    }
    if (form.pin?.length !== 6) {
      showAlert("Seguridad de Acceso", "El PIN debe consistir exactamente en 6 dígitos.", "error");
      return;
    }

    let updatedList;
    if (editingEmp) {
      updatedList = employees.map(e => e.id === editingEmp.id ? { ...e, ...form } as Employee : e);
    } else {
      const newEmp = { 
        ...form, 
        id: Math.random().toString(36).substr(2, 9), 
        pinChanges: 0,
        observations: [],
        absences: [],
        totalHoursWorked: 0
      } as Employee;
      updatedList = [...employees, newEmp];
    }

    onUpdate(updatedList);
    setIsModalOpen(false);
    showAlert("Sincronización Exitosa", "La ficha del colaborador ha sido actualizada en la nube.", "success");
  };

  const handleTermination = () => {
    if (!viewingEmp) return;
    const updated = employees.map(e => e.id === viewingEmp.id ? {
      ...e,
      status: 'terminated' as const,
      terminationDate: termData.date,
      terminationReason: termData.reason,
      terminationDetails: termData.details
    } : e);
    onUpdate(updated);
    setIsTermModalOpen(false);
    setViewingEmp(null);
    showAlert("Baja Procesada", "El colaborador ha sido desvinculado. Acceso a terminal revocado.", "success");
  };

  return (
    <div className="space-y-8 fade-in overflow-hidden">
      <div className="bg-white p-8 md:p-14 rounded-[4rem] shadow-sm border border-slate-100 flex flex-col md:flex-row justify-between items-center gap-8 no-print">
        <div className="text-center md:text-left">
          <h2 className="text-3xl md:text-5xl font-[950] text-slate-900 tracking-tighter uppercase leading-none">Capital Humano</h2>
          <p className="text-[11px] text-slate-400 font-black uppercase tracking-[0.5em] mt-4">Gestión de Expedientes y Fichas Corporativas</p>
        </div>
        <button onClick={() => { setForm(initialForm); setEditingEmp(null); setIsModalOpen(true); }} className="w-full md:w-auto px-12 py-6 bg-blue-700 text-white font-black rounded-3xl shadow-2xl uppercase text-[12px] tracking-[0.2em] hover:bg-blue-800 transition-all active:scale-95 shimmer-effect">Alta de Personal</button>
      </div>

      <div className="bg-white rounded-[4rem] shadow-sm border border-slate-100 overflow-hidden no-print">
        <div className="p-8 bg-slate-50/50 border-b">
          <div className="relative">
            <input type="text" placeholder="Buscar expediente por apellido o ID fiscal..." className="w-full bg-white border-2 border-slate-100 p-6 pl-16 rounded-[2.5rem] text-[15px] font-black outline-none focus:border-blue-700 transition-all shadow-inner" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
            <svg className="w-7 h-7 absolute left-6 top-1/2 -translate-y-1/2 text-slate-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
          </div>
        </div>

        <div className="overflow-x-auto custom-scroll">
          <table className="w-full text-left min-w-[900px]">
            <thead className="bg-slate-50 text-[11px] font-[900] text-slate-400 uppercase tracking-widest">
              <tr>
                <th className="px-10 py-7">Perfil</th>
                <th className="px-10 py-7">Colaborador</th>
                <th className="px-10 py-7 text-center">Estatus Laboral</th>
                <th className="px-10 py-7">Cargo / Rol</th>
                <th className="px-10 py-7 text-right">Expediente</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50 text-[14px] font-[900]">
              {employees.filter(e => (e.name + " " + e.surname).toLowerCase().includes(searchTerm.toLowerCase())).map(emp => (
                <tr key={emp.id} className="hover:bg-blue-50/40 transition-colors group">
                  <td className="px-10 py-6">
                    <div className="w-16 h-16 rounded-[1.5rem] overflow-hidden bg-slate-100 border-2 border-white shadow-lg group-hover:scale-110 transition-transform flex items-center justify-center">
                      {emp.photo ? <img src={emp.photo} className="w-full h-full object-cover" /> : <span className="text-3xl opacity-20">👤</span>}
