      {/* Modal: Ficha Detallada */}
      <Modal isOpen={!!viewingEmp} onClose={() => setViewingEmp(null)} title="Expediente del Colaborador">
        {viewingEmp && (
          <div className="space-y-10">
            <div className="flex flex-col md:flex-row gap-10 items-center border-b pb-10">
               <div className="w-32 h-32 rounded-[2.5rem] overflow-hidden bg-slate-50 border-4 border-white shadow-2xl">
                 {viewingEmp.photo ? <img src={viewingEmp.photo} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center text-5xl">👤</div>}
               </div>
               <div className="text-center md:text-left flex-1">
                 <h3 className="text-3xl font-[950] text-slate-900 uppercase tracking-tighter leading-none">{viewingEmp.name} {viewingEmp.surname}</h3>
                 <p className="text-blue-600 font-black uppercase text-[11px] tracking-[0.4em] mt-3">{viewingEmp.role}</p>
                 <div className="flex gap-4 mt-6 justify-center md:justify-start">
                    <button onClick={() => { setForm(viewingEmp); setEditingEmp(viewingEmp); setIsModalOpen(true); setViewingEmp(null); }} className="px-6 py-2 bg-slate-900 text-white font-black text-[9px] uppercase tracking-widest rounded-xl shadow-lg">Editar Ficha</button>
                    {viewingEmp.status === 'active' && (
                      <button onClick={() => setIsTermModalOpen(true)} className="px-6 py-2 bg-red-100 text-red-600 font-black text-[9px] uppercase tracking-widest rounded-xl hover:bg-red-600 hover:text-white transition-all">Liquidación</button>
                    )}
                 </div>
               </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 text-[12px]">
               <div className="space-y-4">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Información Contractual</p>
                  <div className="space-y-2 font-black text-slate-700 uppercase">
                     <p><span className="text-slate-400">ID Fiscal:</span> {viewingEmp.identification}</p>
                     <p><span className="text-slate-400">Ingreso:</span> {new Date(viewingEmp.startDate).toLocaleDateString()}</p>
                     <p><span className="text-slate-400">Sueldo Base:</span> <span className="text-emerald-600">${viewingEmp.salary.toFixed(2)}</span></p>
                     <p><span className="text-slate-400">Tipo PIN:</span> <span className="font-mono tracking-widest">******</span></p>
                  </div>
               </div>
               <div className="space-y-4">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Información Bancaria</p>
                  <div className="space-y-2 font-black text-slate-700 uppercase">
                     <p><span className="text-slate-400">IFI:</span> {viewingEmp.bankInfo.ifi}</p>
                     <p><span className="text-slate-400">Tipo:</span> {viewingEmp.bankInfo.type}</p>
                     <p><span className="text-slate-400">Cuenta:</span> {viewingEmp.bankInfo.account}</p>
                     <p><span className="text-slate-400">Afiliado IESS:</span> {viewingEmp.isAffiliated ? 'SÍ' : 'NO'}</p>
                  </div>
               </div>
            </div>

            {viewingEmp.status === 'terminated' && (
              <div className="p-6 bg-red-50 border-2 border-red-100 rounded-3xl">
                 <p className="text-[10px] font-black text-red-600 uppercase tracking-widest mb-2">Historial de Desvinculación</p>
                 <div className="space-y-1 text-xs font-bold text-red-950">
                    <p>Fecha de Salida: {new Date(viewingEmp.terminationDate!).toLocaleDateString()}</p>
                    <p>Causa Legal: {viewingEmp.terminationReason}</p>
                    <p className="italic mt-2">Detalles: {viewingEmp.terminationDetails}</p>
                 </div>
              </div>
            )}
          </div>
        )}
      </Modal>

      {/* Modal: Alta / Edición */}
      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title={editingEmp ? "Actualizar Colaborador" : "Nuevo Ingreso Administrativo"}>
         <div className="space-y-8 p-2">
            <div className="grid grid-cols-2 gap-6">
               <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Nombres</label>
                  <input className="w-full border-2 p-4 rounded-2xl text-sm font-black focus:border-blue-600 outline-none mt-1" value={form.name} onChange={e => setForm({...form, name: e.target.value.toUpperCase()})} />
               </div>
               <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Apellidos</label>
                  <input className="w-full border-2 p-4 rounded-2xl text-sm font-black focus:border-blue-600 outline-none mt-1" value={form.surname} onChange={e => setForm({...form, surname: e.target.value.toUpperCase()})} />
               </div>
               <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Cédula / ID</label>
                  <input maxLength={10} className="w-full border-2 p-4 rounded-2xl text-sm font-black focus:border-blue-600 outline-none mt-1" value={form.identification} onChange={e => setForm({...form, identification: e.target.value.replace(/\D/g,'')})} />
               </div>
               <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Fecha Nacimiento</label>
                  <input type="date" className="w-full border-2 p-4 rounded-2xl text-sm font-black focus:border-blue-600 outline-none mt-1" value={form.birthDate} onChange={e => setForm({...form, birthDate: e.target.value})} />
               </div>
               <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Sueldo Base ($)</label>
                  <input type="number" className="w-full border-2 p-4 rounded-2xl text-sm font-black focus:border-blue-600 outline-none mt-1" value={form.salary} onChange={e => setForm({...form, salary: Number(e.target.value)})} />
               </div>
               <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-2">Asignar PIN (6 dígitos)</label>
                  <input maxLength={6} type="password" placeholder="••••••" className="w-full border-2 p-4 rounded-2xl text-center text-xl font-black focus:border-blue-600 outline-none mt-1" value={form.pin} onChange={e => setForm({...form, pin: e.target.value.replace(/\D/g,'')})} />
               </div>
            </div>
            <button onClick={handleSave} className="w-full py-6 bg-slate-950 text-white font-black rounded-3xl uppercase text-[12px] tracking-widest shadow-2xl active:scale-95 transition-all">Guardar Cambios de Expediente</button>
         </div>
      </Modal>

      {/* Modal: Desvinculación */}
      <Modal isOpen={isTermModalOpen} onClose={() => setIsTermModalOpen(false)} title="Protocolo de Desvinculación Laboral" type="error">
         <div className="space-y-6">
            <p className="text-sm font-bold text-red-900 bg-red-50 p-4 rounded-2xl">Advertencia: Esta acción dará de baja al empleado en el sistema de asistencia de forma inmediata y permanente.</p>
            <div className="space-y-4">
               <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Fecha de Cese de Funciones</label>
                  <input type="date" className="w-full border-2 p-4 rounded-2xl text-sm font-black mt-1" value={termData.date} onChange={e => setTermData({...termData, date: e.target.value})} />
               </div>
               <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Causa de la Terminación</label>
                  <select className="w-full border-2 p-4 rounded-2xl text-sm font-black mt-1" value={termData.reason} onChange={e => setTermData({...termData, reason: e.target.value as any})}>
                     {Object.values(TerminationReason).map(r => <option key={r} value={r}>{r}</option>)}
                  </select>
               </div>
               <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Detalles Adicionales / Acta</label>
                  <textarea className="w-full border-2 p-4 rounded-2xl text-sm font-black mt-1 h-32" placeholder="Especifique pormenores de la salida para el expediente..." value={termData.details} onChange={e => setTermData({...termData, details: e.target.value})}></textarea>
               </div>
            </div>
            <button onClick={handleTermination} className="w-full py-6 bg-red-600 text-white font-black rounded-3xl uppercase text-[12px] tracking-widest shadow-2xl active:scale-95 transition-all">Ejecutar Baja Definitiva</button>
         </div>
      </Modal>

      <Modal isOpen={modalAlert.isOpen} onClose={() => setModalAlert({...modalAlert, isOpen: false})} title={modalAlert.title} type={modalAlert.type}>
          <div className="text-center space-y-8 p-4">
              <p className="text-slate-950 font-black uppercase text-[13px] leading-relaxed tracking-tighter">"{modalAlert.message}"</p>
              <button onClick={() => setModalAlert({...modalAlert, isOpen: false})} className="w-full py-6 bg-slate-950 text-white font-black rounded-3xl uppercase text-[12px] tracking-widest shadow-2xl active:scale-95 transition-all">Entendido</button>
          </div>
      </Modal>
    </div>
  );
};

export default EmployeeModule;

import React, { useState, useEffect, useCallback } from 'react';
import { CompanyConfig, Employee, Role, AttendanceRecord, Payment, GlobalSettings } from './types.ts';
import AdminDashboard from './views/AdminDashboard.tsx';
import AttendanceSystem from './views/AttendanceSystem.tsx';
import Modal from './components/Modal.tsx';
import { db, collection, doc, onSnapshot, setDoc, addDoc, compressData, decompressData } from './firebase.ts';

const App: React.FC = () => {
  const [currentUserRole, setCurrentUserRole] = useState<Role | null>(null);
  const [view, setView] = useState<'selection' | 'admin' | 'attendance'>('selection');
  const [isLoadingData, setIsLoadingData] = useState(true);
  const [isDbConnected, setIsDbConnected] = useState(false);
  const [isAdminLoginModalOpen, setIsAdminLoginModalOpen] = useState(false);
  const [adminPassInput, setAdminPassInput] = useState('');
  const [showPass, setShowPass] = useState(false);
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);
  const [isMobile, setIsMobile] = useState(false);

  const [appMode, setAppMode] = useState<'full' | 'attendance'>(
    (localStorage.getItem('app_mode') as 'full' | 'attendance') || 'full'
  );

  const [showWelcome, setShowWelcome] = useState(false);
  const [showLogoutFeedback, setShowLogoutFeedback] = useState(false);
  const [showConfigPrompt, setShowConfigPrompt] = useState(false);
  const [configBoot, setConfigBoot] = useState(true);
  const [configMode, setConfigMode] = useState<'full' | 'attendance'>('full');

  const [modalAlert, setModalAlert] = useState<{isOpen: boolean, title: string, message: string, type: 'info' | 'success' | 'error'}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  const [company, setCompany] = useState<CompanyConfig | null>(null);
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);
  const [payments, setPayments] = useState<Payment[]>([]);
  const [settings, setSettings] = useState<GlobalSettings>({
    sbu: 482.00,
    iessRate: 0.0945,
    reserveRate: 0.0833,
    schedule: {
      monFri: { in: '08:30', out: '13:00' },
      sat: { in: '08:30', out: '13:00' },
      halfDayOff: 'Miércoles tarde'
    }
  });

  const showAlert = (title: string, message: string, type: 'info' | 'success' | 'error' = 'info') => {
    setModalAlert({ isOpen: true, title, message, type });
  };

  const sendPushNotification = useCallback((title: string, body: string) => {
    if (Notification.permission === 'granted') {
      new Notification(title, { body, icon: 'https://cdn-icons-png.flaticon.com/512/1063/1063376.png' });
    }
  }, []);

  useEffect(() => {
    const checkMobile = () => setIsMobile(/iPhone|iPad|iPod|Android/i.test(navigator.userAgent));
    checkMobile();
    window.addEventListener('resize', checkMobile);

    if (Notification.permission === 'default') {
      Notification.requestPermission();
    }

    window.addEventListener('beforeinstallprompt', (e) => {
      e.preventDefault();
      setDeferredPrompt(e);
    });

    window.addEventListener('appinstalled', () => {
      setShowConfigPrompt(true);
    });

    const unsubscribes: (() => void)[] = [];
    const rescueTimer = setTimeout(() => setIsLoadingData(false), 3000);

    const updateConnectionStatus = (metadata: any) => {
      if (!metadata.fromCache) setIsDbConnected(true);
    };

    try {
      const unsubCompany = onSnapshot(doc(db, "config", "company"), (docSnap) => {
        if (docSnap.exists()) {
          const data = docSnap.data();
          setCompany(data.payload ? decompressData(data.payload) : data as any);
        }
        updateConnectionStatus(docSnap.metadata);
        setIsLoadingData(false);
        clearTimeout(rescueTimer);
      }, () => setIsDbConnected(false));
      unsubscribes.push(unsubCompany);

      const unsubEmployees = onSnapshot(collection(db, "employees"), (snapshot) => {
        setEmployees(snapshot.docs.map(d => {
          const raw = d.data();
          return raw.payload ? { ...decompressData(raw.payload), id: d.id } : { ...raw, id: d.id };
        }) as Employee[]);
        updateConnectionStatus(snapshot.metadata);
      }, () => setIsDbConnected(false));
      unsubscribes.push(unsubEmployees);

      const unsubAttendance = onSnapshot(collection(db, "attendance"), (snapshot) => {
        const newRecords = snapshot.docs.map(d => {
          const raw = d.data();
          return raw.payload ? { ...decompressData(raw.payload), id: d.id } : { ...raw, id: d.id };
        }) as AttendanceRecord[];

        if (localStorage.getItem('admin_logged_in') === 'true') {
          snapshot.docChanges().forEach((change) => {
            if (change.type === "added" && !change.doc.metadata.fromCache) {
              const rec = decompressData(change.doc.data().payload) as AttendanceRecord;
              const emp = employees.find(e => e.id === rec.employeeId);
              if (rec.isForgotten) {
                sendPushNotification("Solicitud de Marcaje", `${emp?.surname} ha enviado una justificación.`);
              }
              if (rec.isLate) {
                sendPushNotification("Atraso Crítico", `${emp?.surname} ha marcado con más de 15m de atraso.`);
              }
            }
          });
        }

        setAttendance(newRecords);
        updateConnectionStatus(snapshot.metadata);
      }, () => setIsDbConnected(false));
      unsubscribes.push(unsubAttendance);

      onSnapshot(collection(db, "payments"), (snapshot) => {
        setPayments(snapshot.docs.map(d => {
          const raw = d.data();
          return raw.payload ? { ...decompressData(raw.payload), id: d.id } : { ...raw, id: d.id };
        }) as Payment[]);
      });

    } catch (e) {
      setIsLoadingData(false);
      setIsDbConnected(false);
    }

    return () => { 
      unsubscribes.forEach(unsub => unsub()); 
      clearTimeout(rescueTimer);
      window.removeEventListener('resize', checkMobile);
    };
  }, [employees, sendPushNotification]);

  const handleAdminLogin = () => {
    let role: Role | null = null;

    // Passwords estáticos para emergencia
    if (adminPassInput === 'admin123') role = Role.SUPER_ADMIN;
    else if (adminPassInput === 'partial123') role = Role.PARTIAL_ADMIN;
    else {
      // Verificar si el PIN pertenece a un empleado con rol administrativo
      const foundAdmin = employees.find(e => e.pin === adminPassInput && (e.role === Role.SUPER_ADMIN || e.role === Role.PARTIAL_ADMIN));
      if (foundAdmin) role = foundAdmin.role;
    }

    if (role) {
      setCurrentUserRole(role);
      localStorage.setItem('admin_logged_in', 'true');
      setShowWelcome(true);
      setView('admin');
      setIsAdminLoginModalOpen(false);
    } else {
      showAlert("Error Jerárquico", "Las credenciales (Password o PIN) no tienen autorización administrativa.", "error");
    }
    setAdminPassInput('');
  };

  const finalizeLogout = () => {
    setCurrentUserRole(null);
    localStorage.removeItem('admin_logged_in');
    setView('selection');
    setShowLogoutFeedback(false);
  };

  const saveConfig = async () => {
    localStorage.setItem('app_mode', configMode);
    setAppMode(configMode);
    if (configBoot && 'runOnOsLogin' in navigator) {
      try {
        // @ts-ignore
        await navigator.runOnOsLogin.set({ mode: 'windowed' });
      } catch (e) { console.debug(e); }
    }
    setShowConfigPrompt(false);
    showAlert("Terminal Aprovisionada", "Configuración finalizada.", "success");
  };

  if (isLoadingData) return null;

  return (
    <div className="min-h-screen bg-[#f8fafc]">
      {view === 'selection' && (
        <div className="min-h-screen gradient-blue flex flex-col items-center justify-center p-6">
          <div className="w-full max-w-lg bg-white/95 backdrop-blur-3xl p-10 md:p-16 rounded-[4.5rem] shadow-2xl text-center border border-white/20">
            <div className="mb-14 flex justify-center">
              <div className="ring-container scale-75">
                  <div className="ring ring-1"></div>
                  <div className="ring ring-2"></div>
                  <div className="ring ring-3"></div>
                  <div className="w-10 h-10 bg-blue-600 rounded-full"></div>
              </div>
            </div>
            <h1 className="text-4xl md:text-5xl font-[950] text-slate-900 mb-2 tracking-tighter uppercase leading-none">ASIST UP</h1>
            <p className="text-blue-600 font-black uppercase tracking-[0.6em] text-[10px] mb-14">Management Suite</p>

            <div className="space-y-4">
              <button onClick={() => setView('attendance')} className="w-full py-6 bg-blue-700 text-white font-black rounded-[2.5rem] shadow-2xl hover:bg-blue-800 transition-all uppercase text-[11px] tracking-widest active:scale-95">Panel de Asistencia</button>
              {appMode === 'full' && (
                <button onClick={() => setIsAdminLoginModalOpen(true)} className="w-full py-5 text-slate-400 font-black hover:text-slate-900 transition-all uppercase text-[10px] tracking-widest">Consola Administrativa</button>
              )}
            </div>
          </div>

          <Modal isOpen={isAdminLoginModalOpen} onClose={() => setIsAdminLoginModalOpen(false)} title="Autorización">
            <div className="space-y-8 p-2 text-center">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Ingrese Password o PIN Administrativo</p>
              <div className="relative">
                <input 
                  type={showPass ? "text" : "password"} 
                  value={adminPassInput} 
                  onChange={e => setAdminPassInput(e.target.value)} 
                  onKeyDown={e => e.key === 'Enter' && handleAdminLogin()} 
                  className="w-full border-2 border-slate-100 rounded-[2.5rem] p-8 text-center text-4xl font-black focus:border-blue-600 outline-none transition-all bg-slate-50" 
                  placeholder="••••••" 
                  autoFocus 
                />
              </div>
              <button onClick={handleAdminLogin} className="w-full py-6 bg-blue-700 text-white font-black rounded-3xl uppercase text-[11px] tracking-widest shadow-2xl">Validar</button>
            </div>
          </Modal>
        </div>
      )}

      {view === 'attendance' && (
        <AttendanceSystem 
          employees={employees} 
          attendance={attendance} 
          onBack={() => setView('selection')} 
          settings={settings} 
          onRegister={async (r) => { await addDoc(collection(db, "attendance"), { payload: compressData(r), timestamp: r.timestamp }); }} 
          onUpdateEmployees={async (emps) => { for (const e of emps) { await setDoc(doc(db, "employees", e.id), { payload: compressData(e) }); } }} 
        />
      )}

      {view === 'admin' && currentUserRole && (
        <AdminDashboard 
          role={currentUserRole} 
          isDbConnected={isDbConnected}
          onLogout={() => setShowLogoutFeedback(true)} 
          company={company}
          onUpdateCompany={async (c) => await setDoc(doc(db, "config", "company"), { payload: compressData(c) })}
          employees={employees}
          onUpdateEmployees={async (emps) => { for (const e of emps) { await setDoc(doc(db, "employees", e.id), { payload: compressData(e) }); } }}
          attendance={attendance}
          payments={payments}
          onUpdatePayments={async (pys) => { for (const p of pys) { if (p.id.length > 15) await addDoc(collection(db, "payments"), { payload: compressData(p) }); else await setDoc(doc(db, "payments", p.id), { payload: compressData(p) }); } }}
          settings={settings}
          onUpdateSettings={async (s) => await setDoc(doc(db, "config", "settings"), { payload: compressData(s) })}
        />
      )}

      {/* Welcome & Feedback Modals */}
      <Modal isOpen={showWelcome} onClose={() => setShowWelcome(false)} title="Acceso Exitoso" type="success">
         <div className="text-center space-y-8 p-4">
            <h2 className="text-3xl font-[950] text-slate-900 uppercase">Bienvenido</h2>
            <button onClick={() => setShowWelcome(false)} className="w-full py-6 bg-blue-700 text-white font-black rounded-3xl uppercase text-[11px] tracking-widest">Entrar</button>
         </div>
      </Modal>

      <Modal isOpen={showLogoutFeedback} onClose={finalizeLogout} title="Cierre de Sesión" type="success">
         <div className="text-center space-y-10 p-6">
            <h3 className="text-3xl font-[950] text-slate-900 uppercase">Sincronizado</h3>
            <button onClick={finalizeLogout} className="w-full py-6 bg-slate-900 text-white font-black rounded-3xl uppercase text-[11px] tracking-widest">Finalizar</button>
         </div>
      </Modal>

      <Modal isOpen={modalAlert.isOpen} onClose={() => setModalAlert({...modalAlert, isOpen: false})} title={modalAlert.title} type={modalAlert.type}>
           <div className="text-center p-4">
              <p className="text-slate-800 font-bold uppercase text-[12px]">{modalAlert.message}</p>
              <button onClick={() => setModalAlert({...modalAlert, isOpen: false})} className="w-full py-5 bg-slate-900 text-white font-black rounded-2xl uppercase mt-6">Aceptar</button>
           </div>
      </Modal>
    </div>
  );
};

