                  <td className="px-6 py-3 text-right flex gap-2 justify-end">
                     <button onClick={() => resetPin(emp.id)} className="px-3 py-1.5 bg-slate-50 text-slate-400 rounded-lg text-[8px] font-black uppercase">Reset PIN</button>
