                   <button onClick={() => setViewingEmp(emp)} className="px-3 py-1.5 bg-blue-50 text-blue-700 rounded-lg text-[8px] font-black uppercase">Ver Ficha</button>
                   {role === Role.SUPER_ADMIN && <button onClick={() => { setEditingEmp(emp); setForm(emp); setIsModalOpen(true); }} className="px-3 py-1.5 bg-slate-100 text-slate-600 rounded-lg text-[8px] font-black uppercase">Editar</button>}
                </td>
              </tr>
            ))}
