            <div className="flex gap-3 mt-6 no-print">
               <button onClick={handleSave} className="w-full py-5 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] tracking-widest">Sincronizar Expediente</button>
            </div>
         </div>
      </Modal>

      {/* Ficha Completa del Empleado */}
