                      <span className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase ${viewingEmp.status === 'active' ? 'bg-emerald-100 text-emerald-700' : 'bg-red-100 text-red-700'}`}>{viewingEmp.status === 'active' ? 'Activo' : 'Liquidado'}</span>
