import React, { useState } from 'react';
import { Employee, Payment, CompanyConfig, GlobalSettings, Role } from '../../types.ts';
import Modal from '../../components/Modal.tsx';

interface PayrollModuleProps {
  employees: Employee[];
  payments: Payment[];
  company: CompanyConfig | null;
  settings: GlobalSettings;
  role: Role;
}

const PayrollModule: React.FC<PayrollModuleProps> = ({ employees, payments, company, settings, role }) => {
  const [selectedMonth, setSelectedMonth] = useState(new Date().toLocaleString('es-EC', {month: 'long'}).toUpperCase());
  const [individualPayroll, setIndividualPayroll] = useState<Employee | null>(null);

  const calculatePayrollData = (emp: Employee) => {
    const baseSalary = emp.salary;

    // Ingresos
    const reserveFund = emp.isAffiliated && emp.overSalaryType === 'monthly' ? (baseSalary * settings.reserveRate) : 0;
    // Bonos registrados en tesorería para este mes
    const bonuses = payments
      .filter(p => p.employeeId === emp.id && p.month === selectedMonth && p.status === 'paid' && p.type === 'Bonus')
      .reduce((sum, p) => sum + p.amount, 0);

    const totalIncomes = baseSalary + reserveFund + bonuses;

    // Egresos
    const iessContribution = emp.isAffiliated ? (baseSalary * settings.iessRate) : 0;
    // Préstamos o anticipos en tesorería
    const loans = payments
      .filter(p => p.employeeId === emp.id && p.month === selectedMonth && p.status === 'paid' && (p.type === 'Loan' || p.type === 'Emergency'))
      .reduce((sum, p) => sum + p.amount, 0);

    const totalExpenses = iessContribution + loans;

    return { 
      baseSalary, reserveFund, bonuses, iessContribution, loans,
      totalIncomes, totalExpenses, netToReceive: totalIncomes - totalExpenses 
    };
  };

  const exportGeneralExcel = () => {
    const headers = "Empleado,Sueldo Base,Fondos Reserva,Bonos,Ingreso Total,Aporte IESS,Préstamos,Egreso Total,Neto a Recibir\n";
    const rows = employees.map(emp => {
      const d = calculatePayrollData(emp);
      return `${emp.surname} ${emp.name},${d.baseSalary},${d.reserveFund},${d.bonuses},${d.totalIncomes},${d.iessContribution},${d.loans},${d.totalExpenses},${d.netToReceive}`;
    }).join("\n");
    const blob = new Blob([headers + rows], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `Nomina_Detallada_${selectedMonth}_2026.csv`;
    link.click();
  };

  return (
    <div className="space-y-8 fade-in">
      <div className="flex justify-between items-center bg-white p-8 rounded-[2rem] shadow-sm border border-slate-100 no-print">
        <div>
          <h2 className="text-2xl font-[950] text-slate-900 uppercase tracking-tighter italic">Liquidación de Nómina Analítica</h2>
          <select className="mt-2 p-2 border rounded-lg text-[10px] font-black uppercase" value={selectedMonth} onChange={e => setSelectedMonth(e.target.value)}>
             {['ENERO','FEBRERO','MARZO','ABRIL','MAYO','JUNIO','JULIO','AGOSTO','SEPTIEMBRE','OCTUBRE','NOVIEMBRE','DICIEMBRE'].map(m => <option key={m} value={m}>{m}</option>)}
          </select>
        </div>
        <div className="flex gap-3">
           <button onClick={exportGeneralExcel} className="px-6 py-4 bg-emerald-50 text-emerald-600 font-black rounded-2xl border border-emerald-100 uppercase text-[9px] tracking-widest">Descargar Reporte Excel</button>
           <button onClick={() => window.print()} className="px-6 py-4 bg-slate-900 text-white font-black rounded-2xl uppercase text-[9px] tracking-widest">Generar PDF Masivo</button>
        </div>
      </div>

      <div className="bg-white p-10 rounded-[3rem] shadow-sm overflow-x-auto border">
        <table className="w-full text-left border-collapse">
          <thead className="bg-slate-900 text-white text-[9px] font-black uppercase">
            <tr>
              <th className="p-4 rounded-tl-2xl">Colaborador</th>
              <th className="p-4">Sueldo Base</th>
              <th className="p-4">Ingresos (+)</th>
              <th className="p-4">Egresos (-)</th>
              <th className="p-4">A Recibir</th>
              <th className="p-4 no-print text-center rounded-tr-2xl">Acciones</th>
            </tr>
          </thead>
          <tbody className="text-[10px] uppercase font-bold text-slate-700">
            {employees.filter(e => e.status === 'active').map(emp => {
              const d = calculatePayrollData(emp);
              return (
                <tr key={emp.id} className="border-b hover:bg-slate-50 transition-colors">
                  <td className="p-4 font-black text-slate-900">{emp.surname} {emp.name}</td>
                  <td className="p-4">${d.baseSalary.toFixed(2)}</td>
                  <td className="p-4 text-emerald-600">${d.totalIncomes.toFixed(2)}</td>
                  <td className="p-4 text-red-600">${d.totalExpenses.toFixed(2)}</td>
                  <td className="p-4 font-[950] text-blue-700 text-xs">${d.netToReceive.toFixed(2)}</td>
                  <td className="p-4 no-print text-center">
                     <button onClick={() => setIndividualPayroll(emp)} className="px-3 py-1.5 bg-blue-50 text-blue-700 rounded-lg font-black hover:bg-blue-600 hover:text-white transition-all">Ver Rol Individual</button>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {/* Rol Individual Detallado */}
      <Modal isOpen={!!individualPayroll} onClose={() => setIndividualPayroll(null)} title="Comprobante de Pago Individual">
        {individualPayroll && (() => {
          const d = calculatePayrollData(individualPayroll);
          return (
            <div className="p-2 space-y-8 print:p-0">
               <div className="text-center border-b-2 border-slate-900 pb-6">
                  <h3 className="text-2xl font-[950] tracking-tighter uppercase leading-none">{company?.name || 'ESTRUCTURA CORPORATIVA'}</h3>
                  <p className="text-[10px] font-black text-slate-400 mt-2 uppercase tracking-[0.4em]">Rol Individual de Pagos - {selectedMonth} 2026</p>
               </div>

               <div className="grid grid-cols-2 gap-x-12 gap-y-4 text-[10px] font-black uppercase">
                  <div>
                     <p className="text-slate-400 mb-0.5">Colaborador</p>
                     <p className="text-slate-900">{individualPayroll.surname} {individualPayroll.name}</p>
                  </div>
                  <div className="text-right">
                     <p className="text-slate-400 mb-0.5">Identificación</p>
                     <p className="text-slate-900">{individualPayroll.identification}</p>
                  </div>
                  <div>
                     <p className="text-slate-400 mb-0.5">Cargo Institucional</p>
                     <p className="text-slate-900">{individualPayroll.role}</p>
                  </div>
                  <div className="text-right">
                     <p className="text-slate-400 mb-0.5">Fecha Generación</p>
                     <p className="text-slate-900">{new Date().toLocaleDateString()}</p>
                  </div>
               </div>

               <div className="grid grid-cols-2 gap-8">
                  {/* Sección Ingresos */}
                  <div className="space-y-4">
                     <h4 className="text-[9px] font-black text-emerald-600 uppercase tracking-widest border-b border-emerald-100 pb-2">Desglose de Ingresos</h4>
                     <div className="space-y-2 text-[10px] font-bold">
                        <div className="flex justify-between"><span>Sueldo Base</span> <span className="text-slate-900 font-black">${d.baseSalary.toFixed(2)}</span></div>
                        <div className="flex justify-between"><span>Fondos Reserva</span> <span className="text-slate-900 font-black">${d.reserveFund.toFixed(2)}</span></div>
                        <div className="flex justify-between"><span>Bonos / Extras</span> <span className="text-slate-900 font-black">${d.bonuses.toFixed(2)}</span></div>
                        <div className="flex justify-between pt-2 border-t font-black text-emerald-600 italic"><span>TOTAL INGRESOS</span> <span>${d.totalIncomes.toFixed(2)}</span></div>
                     </div>
