                        <div className="flex justify-between"><span>Préstamos / Anticipos</span> <span className="text-slate-900 font-black">${d.loans.toFixed(2)}</span></div>
                        <div className="flex justify-between pt-2 border-t font-black text-red-600 italic"><span>TOTAL EGRESOS</span> <span>${d.totalExpenses.toFixed(2)}</span></div>
