                  </div>
                  <div className="text-right">
                    <p className="text-4xl font-[950] tracking-tighter">${d.netToReceive.toFixed(2)}</p>
                  </div>
               </div>

               <div className="pt-12 grid grid-cols-2 gap-20 text-center no-print-flex">
                  <div className="border-t border-slate-300 pt-4">
                     <p className="text-[8px] font-black uppercase text-slate-400">Firma Representante Legal</p>
                  </div>
