                     <select className="w-full border-2 p-3 rounded-xl text-xs font-black" value={form.gender} onChange={e => setForm({...form, gender: e.target.value as Gender})}>
                        {Object.values(Gender).map(g => <option key={g} value={g}>{g}</option>)}
