import React, { useState } from 'react';
import { GlobalSettings, Role } from '../../types.ts';
import Modal from '../../components/Modal.tsx';
import LZString from 'lz-string';

interface SettingsModuleProps {
  settings: GlobalSettings;
  onUpdate: (settings: GlobalSettings) => void;
  role: Role;
  onPurge?: () => void;
  // Añadimos acceso a datos para respaldo
  allData?: any;
}

const SettingsModule: React.FC<SettingsModuleProps> = ({ settings, onUpdate, role, onPurge, allData }) => {
  const [local, setLocal] = useState<GlobalSettings>({ ...settings });
  const [showPurgeConfirm, setShowPurgeConfirm] = useState(false);
  const [feedback, setFeedback] = useState<{isOpen: boolean, title: string, message: string, type: 'success' | 'error' | 'info'}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  const handleBackup = () => {
    try {
      if (!allData) return;
      const dataStr = JSON.stringify(allData);
      const compressed = LZString.compressToEncodedURIComponent(dataStr);
      const blob = new Blob([compressed], { type: 'application/octet-stream' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `Respaldo_ASISTUP_${new Date().getMonth() + 1}_${new Date().getFullYear()}.bak`;
      link.click();
      setFeedback({ isOpen: true, title: "Respaldo Generado", message: "El archivo de respaldo comprimido se ha descargado con éxito.", type: "success" });
    } catch (e) {
      setFeedback({ isOpen: true, title: "Error", message: "No se pudo generar el respaldo.", type: "error" });
    }
  };

  const handleSave = () => {
    if (role !== Role.SUPER_ADMIN) {
        setFeedback({ isOpen: true, title: "Acceso Denegado", message: "Solo el Super Administrador puede modificar los parámetros maestros.", type: "error" });
        return;
    }
    onUpdate(local);
    setFeedback({ isOpen: true, title: "Sincronizado", message: "Parámetros globales actualizados correctamente.", type: "success" });
  };

  return (
    <div className="max-w-4xl mx-auto space-y-10 fade-in pb-20">
      <div className="bg-white p-12 rounded-[3.5rem] shadow-sm border space-y-12">
        <header className="border-b pb-6">
          <h2 className="text-3xl font-[900] text-slate-900 tracking-tighter uppercase italic">Configuración Maestra</h2>
        </header>

        <section className="grid grid-cols-2 gap-10">
           <div className="space-y-4">
              <label className="text-[11px] font-black text-blue-700 uppercase tracking-widest">Sueldo Básico (SBU)</label>
              <input type="number" step="0.01" className="w-full p-6 border-2 rounded-3xl font-[950] text-3xl focus:border-blue-500 outline-none transition-all" value={local.sbu} onChange={e => setLocal({...local, sbu: Number(e.target.value)})} />
           </div>
           <div className="space-y-4">
              <label className="text-[11px] font-black text-blue-700 uppercase tracking-widest">Aporte IESS (%)</label>
              <input type="number" step="0.01" className="w-full p-6 border-2 rounded-3xl font-[950] text-3xl focus:border-blue-500 outline-none transition-all" value={(local.iessRate * 100).toFixed(2)} onChange={e => setLocal({...local, iessRate: Number(e.target.value) / 100})} />
           </div>
        </section>

        {/* Sección de Respaldo y Mantenimiento */}
        {role === Role.SUPER_ADMIN && (
          <section className="p-10 border-2 border-dashed border-slate-200 rounded-[3rem] bg-slate-50 space-y-8">
             <div className="flex justify-between items-center border-b pb-4">
                <h3 className="text-[11px] font-black text-slate-900 uppercase tracking-widest">Mantenimiento y Seguridad</h3>
             </div>
             <div className="grid grid-cols-2 gap-4">
                <button onClick={handleBackup} className="flex flex-col items-center gap-4 p-8 bg-white border rounded-3xl hover:border-blue-500 transition-all group">
                   <span className="text-4xl group-hover:scale-110 transition-transform">📦</span>
                   <span className="text-[9px] font-black uppercase tracking-widest text-slate-500 group-hover:text-blue-600">Generar Respaldo Mensual</span>
                </button>
                <button onClick={() => setShowPurgeConfirm(true)} className="flex flex-col items-center gap-4 p-8 bg-white border rounded-3xl hover:border-red-500 transition-all group">
                   <span className="text-4xl group-hover:scale-110 transition-transform">🧹</span>
                   <span className="text-[9px] font-black uppercase tracking-widest text-slate-500 group-hover:text-red-600">Limpiar Base de Datos</span>
                </button>
             </div>
          </section>
        )}

        <button onClick={handleSave} className="w-full py-6 bg-slate-900 text-white font-[900] rounded-[2.5rem] shadow-2xl uppercase text-xs tracking-[0.3em] hover:scale-[1.02] transition-all">Actualizar Parámetros</button>
      </div>

      <Modal isOpen={showPurgeConfirm} onClose={() => setShowPurgeConfirm(false)} title="AVISO DE SEGURIDAD" type="error">
         <div className="space-y-6 text-center">
            <p className="text-xs font-black text-red-600 uppercase tracking-tighter">¡ADVERTENCIA: ESTA ACCIÓN ELIMINARÁ LOS DATOS OPERATIVOS!</p>
            <p className="text-[11px] text-slate-500 font-medium">Se borrará personal, pagos y asistencia. Los datos de la empresa permanecerán intactos.</p>
            <div className="flex gap-3">
               <button onClick={() => setShowPurgeConfirm(false)} className="flex-1 py-4 bg-slate-100 text-slate-600 font-black rounded-xl uppercase text-[9px]">Cancelar</button>
               <button onClick={() => { onPurge?.(); setShowPurgeConfirm(false); setFeedback({isOpen: true, title: "Purga Completa", message: "Sistema reiniciado con éxito.", type: "success"}); }} className="flex-1 py-4 bg-red-600 text-white font-black rounded-xl uppercase text-[9px] shadow-lg">Confirmar Limpieza</button>
            </div>
         </div>
      </Modal>

      <Modal isOpen={feedback.isOpen} onClose={() => setFeedback({...feedback, isOpen: false})} title={feedback.title} type={feedback.type}>
          <div className="text-center space-y-6">
              <p className="text-slate-600 font-bold uppercase text-[12px]">{feedback.message}</p>
              <button onClick={() => setFeedback({...feedback, isOpen: false})} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] tracking-widest">Aceptar</button>
          </div>
      </Modal>
    </div>
  );
};

export default SettingsModule;

import React, { useState, useMemo, useEffect } from 'react';
import { Role, CompanyConfig, Employee, AttendanceRecord, Payment, GlobalSettings } from '../types.ts';
import Sidebar from '../components/Sidebar.tsx';
import CompanyModule from './modules/CompanyModule.tsx';
import EmployeeModule from './modules/EmployeeModule.tsx';
import PayrollModule from './modules/PayrollModule.tsx';
import PaymentsModule from './modules/PaymentsModule.tsx';
import SettingsModule from './modules/SettingsModule.tsx';
import ReportsModule from './modules/ReportsModule.tsx';
import Modal from '../components/Modal.tsx';
import { DAILY_QUOTES } from '../constants.tsx';

interface AdminDashboardProps {
  role: Role;
  isDbConnected?: boolean;
  onLogout: () => void;
  company: CompanyConfig | null;
  onUpdateCompany: (config: CompanyConfig) => void;
  employees: Employee[];
  onUpdateEmployees: (employees: Employee[]) => void;
  attendance: AttendanceRecord[];
  payments: Payment[];
  onUpdatePayments: (payments: Payment[]) => void;
  settings: GlobalSettings;
  onUpdateSettings: (settings: GlobalSettings) => void;
  onUpdateAppMode: (mode: 'full' | 'attendance') => void;
  appMode: 'full' | 'attendance';
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  role, isDbConnected, onLogout, company, onUpdateCompany, employees, onUpdateEmployees, attendance, payments, onUpdatePayments, settings, onUpdateSettings, onUpdateAppMode, appMode 
}) => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'company' | 'employees' | 'payroll' | 'payments' | 'settings' | 'reports'>('dashboard');
  const [showInstallModal, setShowInstallModal] = useState(false);

  const today = useMemo(() => new Date(), []);
  const dayOfYear = useMemo(() => {
    const start = new Date(today.getFullYear(), 0, 0);
    const diff = today.getTime() - start.getTime();
    return Math.floor(diff / (1000 * 60 * 60 * 24));
  }, [today]);

  const dailyQuote = DAILY_QUOTES[dayOfYear % DAILY_QUOTES.length];

  const handlePurgeData = async () => {
    if (role !== Role.SUPER_ADMIN) return;
    onUpdateEmployees([]);
    onUpdatePayments([]);
    // La limpieza de asistencia debe manejarse en el componente padre si persiste en DB
  };

  const allAppData = {
    company,
    employees,
    attendance,
    payments,
    settings,
    exportDate: new Date().toISOString()
  };

  return (
    <div className="flex h-screen bg-[#fcfdfe] overflow-hidden flex-col md:flex-row">
      <Sidebar role={role} activeTab={activeTab} setActiveTab={setActiveTab} onLogout={onLogout} companyName={company?.name} />

      <main className="flex-1 overflow-y-auto px-6 py-8 md:px-10 md:py-10 scroll-smooth custom-scroll">
        <header className="flex flex-col md:flex-row justify-between items-start md:items-center mb-10 gap-6 no-print pt-10 md:pt-0">
          <h1 className="text-xl md:text-2xl font-[950] text-slate-900 tracking-tight uppercase">Panel Administrativo</h1>
          <div className="flex gap-3">
             {role === Role.SUPER_ADMIN && (
               <button onClick={() => setShowInstallModal(true)} className="px-4 py-2 bg-slate-100 text-slate-600 rounded-xl text-[9px] font-black uppercase border border-slate-200">Instalar Kiosco</button>
             )}
          </div>
        </header>

        <div className="animate-in fade-in duration-500">
          {activeTab === 'dashboard' && (
            <div className="space-y-6">
              <div className="bg-white p-8 rounded-[2.5rem] shadow-sm border border-slate-50">
                  <p className="text-[8px] font-black text-blue-600 uppercase tracking-widest mb-3">Reflexión Diaria</p>
                  <h2 className="text-lg md:text-xl font-[800] text-slate-800 leading-snug">"{dailyQuote}"</h2>
              </div>
              <div className="grid grid-cols-3 gap-6">
                 <div className="bg-blue-600 p-6 rounded-[2rem] text-white">
                    <p className="text-[8px] font-black uppercase tracking-widest opacity-60">Personal Activo</p>
                    <p className="text-4xl font-black mt-1">{employees.length}</p>
                 </div>
                 <div className="bg-slate-900 p-6 rounded-[2rem] text-white">
                    <p className="text-[8px] font-black uppercase tracking-widest opacity-60">SBU 2026</p>
                    <p className="text-4xl font-black mt-1">${settings.sbu}</p>
                 </div>
                 <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm">
                    <p className="text-[8px] font-black text-blue-600 uppercase tracking-widest">Estatus DB</p>
                    <p className="text-xl font-black mt-1 uppercase text-slate-900">{isDbConnected ? 'Sincronizado' : 'Offline'}</p>
                 </div>
              </div>
            </div>
          )}

          {activeTab === 'company' && <CompanyModule company={company} onUpdate={onUpdateCompany} role={role} />}
          {activeTab === 'employees' && <EmployeeModule employees={employees} onUpdate={onUpdateEmployees} role={role} attendance={attendance} payments={payments} company={company} />}
          {activeTab === 'payroll' && <PayrollModule employees={employees} payments={payments} company={company} settings={settings} role={role} />}
          {activeTab === 'payments' && <PaymentsModule employees={employees} payments={payments} onUpdate={onUpdatePayments} role={role} />}
          {activeTab === 'settings' && <SettingsModule settings={settings} onUpdate={onUpdateSettings} role={role} onPurge={handlePurgeData} allData={allAppData} />}
          {activeTab === 'reports' && <ReportsModule employees={employees} payments={payments} attendance={attendance} company={company} settings={settings} />}
        </div>
      </main>

      <Modal isOpen={showInstallModal} onClose={() => setShowInstallModal(false)} title="Configuración de Equipo" maxWidth="max-w-md">
         <div className="space-y-6">
            <p className="text-xs text-slate-500 text-center">Seleccione el modo operativo para esta estación de trabajo.</p>
            <div className="space-y-3">
               <button onClick={() => { onUpdateAppMode('full'); setShowInstallModal(false); }} className={`w-full p-6 rounded-2xl border-2 text-left flex items-center justify-between ${appMode === 'full' ? 'border-blue-600 bg-blue-50' : 'border-slate-100'}`}>
                  <div>
                    <p className="font-black text-sm text-slate-900 uppercase">Administración Full</p>
                    <p className="text-[10px] text-slate-400 font-bold uppercase">Acceso total a módulos.</p>
                  </div>
               </button>
               <button onClick={() => { onUpdateAppMode('attendance'); setShowInstallModal(false); }} className={`w-full p-6 rounded-2xl border-2 text-left flex items-center justify-between ${appMode === 'attendance' ? 'border-blue-600 bg-blue-50' : 'border-slate-100'}`}>
                  <div>
                    <p className="font-black text-sm text-slate-900 uppercase">Sólo Marcación</p>
                    <p className="text-[10px] text-slate-400 font-bold uppercase">Modo kiosco seguro.</p>
