import React, { useState } from 'react';
import { Employee, Payment, Role } from '../../types.ts';
import Modal from '../../components/Modal.tsx';

interface PaymentsModuleProps {
  employees: Employee[];
  payments: Payment[];
  onUpdate: (payments: Payment[]) => void;
  role: Role;
}

const PaymentsModule: React.FC<PaymentsModuleProps> = ({ employees, payments, onUpdate, role }) => {
  const [isPayOpen, setIsPayOpen] = useState(false);
  const [feedback, setFeedback] = useState<{isOpen: boolean, title: string, message: string, type: 'success' | 'error' | 'info'}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  const [payForm, setPayForm] = useState<Partial<Payment>>({
    type: 'Salary', 
    amount: 0, 
    method: 'Efectivo', 
    concept: '', 
    month: new Date().toLocaleString('es-EC', {month: 'long'}).toUpperCase(), 
    year: '2026', 
    status: 'paid'
  });

  const getPendingBalance = (empId: string, month: string) => {
    const emp = employees.find(e => e.id === empId);
    if (!emp) return 0;

    const totalPaid = payments
      .filter(p => p.employeeId === empId && p.month === month && p.status === 'paid' && p.type === 'Salary')
      .reduce((sum, p) => sum + p.amount, 0);

    return Math.max(0, emp.salary - totalPaid);
  };

  const handleCreate = () => {
    if (!payForm.employeeId || !payForm.amount) {
        setFeedback({ isOpen: true, title: "Falta Información", message: "Seleccione empleado y monto para el pago.", type: "error" });
        return;
    }

    const balanceBefore = getPendingBalance(payForm.employeeId, payForm.month!);
    const remaining = payForm.type === 'Salary' ? balanceBefore - payForm.amount! : 0;

    const newPay: Payment = {
      ...payForm,
      id: Math.random().toString(36).substr(2, 15),
      date: new Date().toISOString(),
      balanceAfter: remaining,
      isPartial: remaining > 0
    } as Payment;

    onUpdate([newPay, ...payments]);
    setIsPayOpen(false);
    setFeedback({ isOpen: true, title: "Operación Exitosa", message: "Haber registrado y sincronizado con tesorería.", type: "success" });
  };

  const handleVoid = (id: string) => {
    const reason = prompt("Justificación obligatoria de anulación:");
    if (!reason) {
        setFeedback({ isOpen: true, title: "Cancelado", message: "La anulación requiere una justificación válida.", type: "error" });
        return;
    }
    onUpdate(payments.map(p => p.id === id ? { ...p, status: 'void', voidJustification: reason } : p));
    setFeedback({ isOpen: true, title: "Anulado", message: "El registro ha sido invalidado.", type: "info" });
  };

  return (
    <div className="space-y-6 fade-in">
      <div className="flex justify-between items-center bg-white p-8 rounded-[2rem] shadow-sm border border-slate-100">
        <h2 className="text-2xl font-black text-slate-900 uppercase">Tesorería y Gestión de Pagos</h2>
        <button 
          onClick={() => {
            if (role === Role.PARTIAL_ADMIN || role === Role.SUPER_ADMIN) setIsPayOpen(true);
            else setFeedback({ isOpen: true, title: "Permisos Insuficientes", message: "No tiene privilegios para registrar desembolsos.", type: "error" });
          }} 
          className="px-8 py-4 bg-emerald-600 text-white font-black rounded-2xl shadow-lg hover:bg-emerald-700 transition-all uppercase text-[10px] tracking-widest"
        >
          Nuevo Pago / Novedad
        </button>
      </div>

      <div className="bg-white rounded-[2rem] shadow-sm border overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest">
            <tr>
              <th className="px-8 py-4">Fecha / Mes</th>
              <th className="px-8 py-4">Empleado</th>
              <th className="px-8 py-4">Monto</th>
              <th className="px-8 py-4">Tipo</th>
              <th className="px-8 py-4">Estado</th>
              <th className="px-8 py-4 text-right">Acción</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {payments.map(p => {
              const emp = employees.find(e => e.id === p.employeeId);
              return (
                <tr key={p.id} className="text-xs hover:bg-slate-50/50">
                  <td className="px-8 py-4">
                    <p className="font-bold">{new Date(p.date).toLocaleDateString()}</p>
                    <p className="text-[9px] uppercase font-black text-slate-400">{p.month}</p>
                  </td>
                  <td className="px-8 py-4 font-black uppercase text-slate-700">
                    {emp?.surname} {emp?.name}
                    <span className="block text-[8px] font-normal text-slate-400 lowercase">{p.concept}</span>
                  </td>
                  <td className="px-8 py-4 font-black text-slate-900 text-sm">${p.amount.toFixed(2)}</td>
                  <td className="px-8 py-4">
                    <span className={`px-2 py-0.5 rounded text-[8px] font-black uppercase ${p.type === 'ExtraHours' ? 'bg-blue-100 text-blue-700' : p.type === 'BackPay' ? 'bg-amber-100 text-amber-700' : 'bg-slate-100 text-slate-600'}`}>{p.type === 'BackPay' ? 'Pago Atrasado' : p.type}</span>
                  </td>
                  <td className="px-8 py-4">
                    <span className={`px-2 py-0.5 rounded text-[8px] font-black uppercase ${p.status === 'paid' ? 'bg-emerald-500 text-white' : 'bg-red-500 text-white'}`}>{p.status === 'paid' ? 'Pagado' : 'Anulado'}</span>
                  </td>
                  <td className="px-8 py-4 text-right">
                    {p.status === 'paid' && role === Role.SUPER_ADMIN && <button onClick={() => handleVoid(p.id)} className="text-red-500 font-black text-[10px] uppercase hover:underline">Anular</button>}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      <Modal isOpen={isPayOpen} onClose={() => setIsPayOpen(false)} title="Registro de Pago / Haber">
        <div className="space-y-4">
          <div>
            <label className="text-[9px] font-black uppercase text-slate-400">Colaborador Beneficiario</label>
            <select className="w-full border-2 p-3 rounded-xl bg-slate-50" onChange={e => setPayForm({...payForm, employeeId: e.target.value})}>
              <option value="">Seleccionar...</option>
              {employees.filter(e => e.status === 'active').map(e => <option key={e.id} value={e.id}>{e.surname} {e.name}</option>)}
            </select>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="text-[9px] font-black uppercase text-slate-400">Concepto</label>
              <select className="w-full border-2 p-3 rounded-xl bg-slate-50" value={payForm.type} onChange={e => setPayForm({...payForm, type: e.target.value as any})}>
                <option value="Salary">Sueldo / Abono</option>
                <option value="BackPay">Pago Atrasado / Saldo Pendiente</option>
                <option value="ExtraHours">Horas Extras/Supl.</option>
                <option value="Bonus">Bono / Comisiones</option>
                <option value="Loan">Préstamo</option>
                <option value="Settlement">Liquidación</option>
              </select>
            </div>
            <div>
              <label className="text-[9px] font-black uppercase text-slate-400">Mes Aplicable</label>
              <select className="w-full border-2 p-3 rounded-xl bg-slate-50" value={payForm.month} onChange={e => setPayForm({...payForm, month: e.target.value})}>
                {['ENERO','FEBRERO','MARZO','ABRIL','MAYO','JUNIO','JULIO','AGOSTO','SEPTIEMBRE','OCTUBRE','NOVIEMBRE','DICIEMBRE'].map(m => <option key={m} value={m}>{m}</option>)}
              </select>
            </div>
          </div>
          <div>
            <label className="text-[9px] font-black uppercase text-slate-400">Monto ($)</label>
            <input type="number" step="0.01" className="w-full border-2 p-3 rounded-xl bg-slate-50 font-black text-xl" onChange={e => setPayForm({...payForm, amount: Number(e.target.value)})} />
          </div>
          <div>
            <label className="text-[9px] font-black uppercase text-slate-400">Observación</label>
            <textarea className="w-full border-2 p-3 rounded-xl bg-slate-50 h-20" placeholder="Ej: Saldo pendiente de Noviembre 2025" onChange={e => setPayForm({...payForm, concept: e.target.value})}></textarea>
          </div>
          <button onClick={handleCreate} className="w-full py-4 bg-emerald-600 text-white font-black rounded-xl uppercase text-xs shadow-xl active:scale-95 transition-all">Sincronizar Pago</button>
        </div>
      </Modal>

      <Modal isOpen={feedback.isOpen} onClose={() => setFeedback({...feedback, isOpen: false})} title={feedback.title} type={feedback.type}>
          <div className="text-center space-y-6">
              <p className="text-slate-600 font-bold uppercase text-[12px]">{feedback.message}</p>
              <button onClick={() => setFeedback({...feedback, isOpen: false})} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] tracking-widest">Aceptar</button>
          </div>
      </Modal>
    </div>
  );
};

export default PaymentsModule;

import React, { useState } from 'react';
import { Employee, Payment, CompanyConfig, GlobalSettings, Role } from '../../types.ts';
import Modal from '../../components/Modal.tsx';

interface PayrollModuleProps {
  employees: Employee[];
  payments: Payment[];
  company: CompanyConfig | null;
  settings: GlobalSettings;
  role: Role;
}

const PayrollModule: React.FC<PayrollModuleProps> = ({ employees, payments, company, settings, role }) => {
  const [selectedMonth, setSelectedMonth] = useState(new Date().toLocaleString('es-EC', {month: 'long'}).toUpperCase());
  const [individualPayroll, setIndividualPayroll] = useState<Employee | null>(null);

  const calculatePayrollData = (emp: Employee, index: number) => {
    const baseSalary = emp.salary;
    const monthlyPayments = payments.filter(p => p.employeeId === emp.id && p.month === selectedMonth && p.status === 'paid');

    const bonuses = monthlyPayments.filter(p => p.type === 'Bonus').reduce((sum, p) => sum + p.amount, 0);
    const extraHours = monthlyPayments.filter(p => p.type === 'ExtraHours').reduce((sum, p) => sum + p.amount, 0);
    const thirteenth = monthlyPayments.filter(p => p.type === 'Thirteenth').reduce((sum, p) => sum + p.amount, 0);
    const fourteenth = monthlyPayments.filter(p => p.type === 'Fourteenth').reduce((sum, p) => sum + p.amount, 0);
    const vacation = monthlyPayments.filter(p => p.type === 'Vacation').reduce((sum, p) => sum + p.amount, 0);
    const backPay = monthlyPayments.filter(p => p.type === 'BackPay').reduce((sum, p) => sum + p.amount, 0);

    const reserveFund = (emp.isAffiliated && emp.overSalaryType === 'monthly') ? ((baseSalary + extraHours) * settings.reserveRate) : 0;

    const totalIncomes = baseSalary + reserveFund + bonuses + extraHours + thirteenth + fourteenth + vacation + backPay;

    const taxableIncome = baseSalary + extraHours + bonuses;
    const iessContribution = emp.isAffiliated ? (taxableIncome * settings.iessRate) : 0;
    const loans = monthlyPayments.filter(p => p.type === 'Loan' || p.type === 'Emergency').reduce((sum, p) => sum + p.amount, 0);

    const totalExpenses = iessContribution + loans;

    // Código PN-XXXXXXXX estrictamente 8 dígitos secuenciales (Solo para el Rol Individual)
    const voucherCode = `PN-${(index + 1).toString().padStart(8, '0')}`;

    return { 
      baseSalary, reserveFund, bonuses, extraHours, thirteenth, fourteenth, vacation, backPay,
      iessContribution, loans,
      totalIncomes, totalExpenses, netToReceive: totalIncomes - totalExpenses,
      voucherCode
    };
  };

  const exportGeneralExcel = () => {
    const headers = "Identificación,Empleado,Sueldo Base,H. Extras,Ingresos (+),Egresos (-),Neto a Recibir\n";
    const rows = employees.map((emp, idx) => {
      const d = calculatePayrollData(emp, idx);
      return `${emp.identification},${emp.surname} ${emp.name},${d.baseSalary.toFixed(2)},${d.extraHours.toFixed(2)},${d.totalIncomes.toFixed(2)},${d.totalExpenses.toFixed(2)},${d.netToReceive.toFixed(2)}`;
    }).join("\n");
    const blob = new Blob([headers + rows], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `Nomina_${selectedMonth}_2026.csv`;
    link.click();
  };

  const exportIndividualExcel = (emp: Employee) => {
    const empIdx = employees.findIndex(e => e.id === emp.id);
    const d = calculatePayrollData(emp, empIdx);

    let csv = `ROL INDIVIDUAL DE PAGOS - ${company?.name || 'ASIST UP'}\n`;
    csv += `Periodo: ${selectedMonth} 2026\n`;
    csv += `Voucher: ${d.voucherCode}\n\n`;
    csv += `Empleado: ${emp.surname} ${emp.name}\n`;
    csv += `Identificación: ${emp.identification}\n`;
    csv += `Cargo: ${emp.role}\n\n`;
    csv += `INGRESOS,VALOR,EGRESOS,VALOR\n`;
    csv += `Sueldo Base,${d.baseSalary.toFixed(2)},Aporte IESS (9.45%),${d.iessContribution.toFixed(2)}\n`;
    csv += `Horas Extras,${d.extraHours.toFixed(2)},Préstamos/Anticipos,${d.loans.toFixed(2)}\n`;
    csv += `Bonificaciones,${d.bonuses.toFixed(2)},,\n`;
    csv += `Saldos Atrasados,${d.backPay.toFixed(2)},,\n`;
    csv += `Fondos Reserva,${d.reserveFund.toFixed(2)},,\n`;
    csv += `TOTAL INGRESOS,${d.totalIncomes.toFixed(2)},TOTAL EGRESOS,${d.totalExpenses.toFixed(2)}\n\n`;
    csv += `NETO A RECIBIR,${d.netToReceive.toFixed(2)}\n`;
    csv += `Método de Pago,${emp.bankInfo?.ifi === 'NO APLICA' ? 'EFECTIVO' : emp.bankInfo?.ifi}\n`;

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `Rol_${emp.surname}_${selectedMonth}.csv`;
    link.click();
  };

  return (
    <div className="space-y-8 fade-in">
      <div className="flex justify-between items-center bg-white p-8 rounded-[2rem] shadow-sm border border-slate-100 no-print">
        <div>
          <h2 className="text-2xl font-[950] text-slate-900 uppercase tracking-tighter">Liquidación de Nómina Analítica</h2>
          <div className="flex items-center gap-3 mt-2">
             <p className="text-[10px] font-black text-slate-400 uppercase">Periodo Fiscal:</p>
             <select className="p-2 border rounded-lg text-[10px] font-black uppercase" value={selectedMonth} onChange={e => setSelectedMonth(e.target.value)}>
                {['ENERO','FEBRERO','MARZO','ABRIL','MAYO','JUNIO','JULIO','AGOSTO','SEPTIEMBRE','OCTUBRE','NOVIEMBRE','DICIEMBRE'].map(m => <option key={m} value={m}>{m}</option>)}
             </select>
          </div>
        </div>
        <div className="flex gap-3">
           <button onClick={exportGeneralExcel} className="px-6 py-4 bg-emerald-50 text-emerald-600 font-black rounded-2xl border border-emerald-100 uppercase text-[9px] tracking-widest">Exportar Excel</button>
           <button onClick={() => window.print()} className="px-6 py-4 bg-slate-900 text-white font-black rounded-2xl uppercase text-[9px] tracking-widest shadow-lg">Imprimir Todo</button>
        </div>
      </div>

      <div className="bg-white p-10 rounded-[3rem] shadow-sm overflow-x-auto border">
        <table className="w-full text-left border-collapse">
          <thead className="bg-slate-900 text-white text-[9px] font-black uppercase">
            <tr>
              <th className="p-4 rounded-tl-2xl">Identificación</th>
              <th className="p-4">Colaborador</th>
              <th className="p-4">Base</th>
              <th className="p-4">H. Extras</th>
              <th className="p-4">Total Ingresos (+)</th>
              <th className="p-4">Total Egresos (-)</th>
              <th className="p-4">Neto Recibir</th>
              <th className="p-4 no-print text-center rounded-tr-2xl">Acción</th>
            </tr>
          </thead>
          <tbody className="text-[10px] uppercase font-bold text-slate-700">
            {employees.filter(e => e.status === 'active').map((emp, idx) => {
              const d = calculatePayrollData(emp, idx);
              return (
                <tr key={emp.id} className="border-b hover:bg-slate-50 transition-colors">
                  <td className="p-4 font-mono font-black text-blue-600">{emp.identification}</td>
                  <td className="p-4 font-black text-slate-900">{emp.surname} {emp.name}</td>
                  <td className="p-4">${d.baseSalary.toFixed(2)}</td>
                  <td className="p-4 text-blue-600 font-black">${d.extraHours.toFixed(2)}</td>
                  <td className="p-4 text-emerald-600 font-bold">+${d.totalIncomes.toFixed(2)}</td>
