      <Modal isOpen={!!viewingEmp} onClose={() => setViewingEmp(null)} title="Ficha Técnica Institucional">
         {viewingEmp && (
            <div className="space-y-8 max-h-[85vh] overflow-y-auto px-4 custom-scroll">
