};

export default EmployeeModule;

import React, { useState } from 'react';
import { Employee, Payment, Role } from '../../types.ts';
import Modal from '../../components/Modal.tsx';
import { db, doc, deleteDoc } from '../../firebase.ts';

interface PaymentsModuleProps {
  employees: Employee[];
  payments: Payment[];
  onUpdate: (payments: Payment[]) => void;
  role: Role;
}

const PaymentsModule: React.FC<PaymentsModuleProps> = ({ employees, payments, onUpdate, role }) => {
  const [isPayOpen, setIsPayOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [feedback, setFeedback] = useState<{isOpen: boolean, title: string, message: string, type: 'success' | 'error' | 'info'}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  const [payForm, setPayForm] = useState<Partial<Payment>>({
    type: 'Salary', 
    amount: 0, 
    method: 'Efectivo', 
    concept: '', 
    month: new Date().toLocaleString('es-EC', {month: 'long'}).toUpperCase(), 
    year: '2026', 
    status: 'paid'
  });

  const getPendingBalance = (empId: string, month: string) => {
    const emp = employees.find(e => e.id === empId);
    if (!emp) return 0;

    const totalPaid = payments
      .filter(p => p.employeeId === empId && p.month === month && p.status === 'paid' && p.type === 'Salary')
      .reduce((sum, p) => sum + p.amount, 0);

    return Math.max(0, emp.salary - totalPaid);
  };

  const handleCreate = () => {
    if (!payForm.employeeId || !payForm.amount) {
        setFeedback({ isOpen: true, title: "Falta Información", message: "Seleccione empleado y monto para el pago.", type: "error" });
        return;
    }

    const balanceBefore = getPendingBalance(payForm.employeeId, payForm.month!);
    const remaining = payForm.type === 'Salary' ? balanceBefore - payForm.amount! : 0;

    const newPay: Payment = {
      ...payForm,
      id: Math.random().toString(36).substr(2, 15),
      date: new Date().toISOString(),
      balanceAfter: remaining,
      isPartial: remaining > 0
    } as Payment;

    onUpdate([newPay, ...payments]);
    setIsPayOpen(false);
    setFeedback({ isOpen: true, title: "Operación Exitosa", message: "Haber registrado y sincronizado con tesorería.", type: "success" });
  };

  const handleVoid = (id: string) => {
    const reason = prompt("Justificación obligatoria de anulación:");
    if (!reason) {
        setFeedback({ isOpen: true, title: "Cancelado", message: "La anulación requiere una justificación válida.", type: "error" });
        return;
    }
    onUpdate(payments.map(p => p.id === id ? { ...p, status: 'void', voidJustification: reason } : p));
    setFeedback({ isOpen: true, title: "Anulado", message: "El registro ha sido invalidado.", type: "info" });
  };

  const handleDeletePayment = async (id: string) => {
    if (confirm("¿Está seguro de eliminar este registro de pago de forma permanente?")) {
      try {
        await deleteDoc(doc(db, "payments", id));
        onUpdate(payments.filter(p => p.id !== id));
        setFeedback({ isOpen: true, title: "Registro Eliminado", message: "El pago ha sido borrado del sistema.", type: "success" });
      } catch (e) {
        setFeedback({ isOpen: true, title: "Error", message: "No se pudo eliminar el registro.", type: "error" });
      }
    }
  };

  const filteredPayments = payments.filter(p => {
    const emp = employees.find(e => e.id === p.employeeId);
    const searchStr = ((emp?.name || "") + " " + (emp?.surname || "") + " " + (emp?.identification || "") + " " + p.concept + " " + p.type).toLowerCase();
    return searchStr.includes(searchTerm.toLowerCase());
  });

  return (
    <div className="space-y-6 fade-in">
      <div className="flex flex-col md:flex-row justify-between items-center bg-white p-8 rounded-[2rem] shadow-sm border border-slate-100 gap-6">
        <h2 className="text-2xl font-black text-slate-900 uppercase">Tesorería y Gestión de Pagos</h2>
        <div className="flex gap-4 w-full md:w-auto">
          <input 
            type="text" 
            placeholder="Filtrar por Empleado o Concepto..." 
            className="flex-1 md:w-64 p-3 border rounded-xl text-[10px] font-bold uppercase" 
            value={searchTerm} 
            onChange={e => setSearchTerm(e.target.value)}
          />
          <button 
            onClick={() => {
              if (role === Role.PARTIAL_ADMIN || role === Role.SUPER_ADMIN) setIsPayOpen(true);
              else setFeedback({ isOpen: true, title: "Permisos Insuficientes", message: "No tiene privilegios para registrar desembolsos.", type: "error" });
            }} 
            className="px-8 py-4 bg-emerald-600 text-white font-black rounded-2xl shadow-lg hover:bg-emerald-700 transition-all uppercase text-[10px] tracking-widest"
          >
            Nuevo Pago
          </button>
        </div>
      </div>

      <div className="bg-white rounded-[2rem] shadow-sm border overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest">
            <tr>
              <th className="px-8 py-4">Fecha / Mes</th>
              <th className="px-8 py-4">Empleado</th>
              <th className="px-8 py-4">Monto</th>
              <th className="px-8 py-4">Tipo</th>
              <th className="px-8 py-4">Estado</th>
              <th className="px-8 py-4 text-right">Acción</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {filteredPayments.map(p => {
              const emp = employees.find(e => e.id === p.employeeId);
              return (
                <tr key={p.id} className="text-xs hover:bg-slate-50/50 transition-all">
                  <td className="px-8 py-4">
                    <p className="font-bold">{new Date(p.date).toLocaleDateString()}</p>
                    <p className="text-[9px] uppercase font-black text-slate-400">{p.month}</p>
                  </td>
                  <td className="px-8 py-4 font-black uppercase text-slate-700">
                    {emp?.surname} {emp?.name}
                    <span className="block text-[8px] font-normal text-slate-400 lowercase">{p.concept}</span>
                  </td>
                  <td className="px-8 py-4 font-black text-slate-900 text-sm">${p.amount.toFixed(2)}</td>
                  <td className="px-8 py-4">
                    <span className={`px-2 py-0.5 rounded text-[8px] font-black uppercase ${p.type === 'ExtraHours' ? 'bg-blue-100 text-blue-700' : p.type === 'BackPay' ? 'bg-amber-100 text-amber-700' : 'bg-slate-100 text-slate-600'}`}>{p.type === 'BackPay' ? 'Pago Atrasado' : p.type}</span>
                  </td>
                  <td className="px-8 py-4">
                    <span className={`px-2 py-0.5 rounded text-[8px] font-black uppercase ${p.status === 'paid' ? 'bg-emerald-500 text-white' : 'bg-red-500 text-white'}`}>{p.status === 'paid' ? 'Pagado' : 'Anulado'}</span>
                  </td>
                  <td className="px-8 py-4 text-right">
                    <div className="flex justify-end gap-3">
                      {p.status === 'paid' && role === Role.SUPER_ADMIN && (
                        <button onClick={() => handleVoid(p.id)} className="text-amber-600 font-black text-[9px] uppercase hover:underline">Anular</button>
                      )}
                      {role === Role.SUPER_ADMIN && (
                        <button onClick={() => handleDeletePayment(p.id)} className="text-red-600 font-black text-[9px] uppercase hover:underline">Eliminar</button>
                      )}
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      <Modal isOpen={isPayOpen} onClose={() => setIsPayOpen(false)} title="Registro de Pago / Haber">
        <div className="space-y-4">
          <div>
            <label className="text-[9px] font-black uppercase text-slate-400">Colaborador Beneficiario</label>
            <select className="w-full border-2 p-3 rounded-xl bg-slate-50" onChange={e => setPayForm({...payForm, employeeId: e.target.value})}>
              <option value="">Seleccionar...</option>
              {employees.filter(e => e.status === 'active').map(e => <option key={e.id} value={e.id}>{e.surname} {e.name}</option>)}
            </select>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="text-[9px] font-black uppercase text-slate-400">Concepto</label>
              <select className="w-full border-2 p-3 rounded-xl bg-slate-50" value={payForm.type} onChange={e => setPayForm({...payForm, type: e.target.value as any})}>
                <option value="Salary">Sueldo / Abono</option>
                <option value="BackPay">Pago Atrasado / Saldo Pendiente</option>
                <option value="ExtraHours">Horas Extras/Supl.</option>
                <option value="Bonus">Bono / Comisiones</option>
                <option value="Loan">Préstamo</option>
                <option value="Settlement">Liquidación</option>
              </select>
            </div>
            <div>
              <label className="text-[9px] font-black uppercase text-slate-400">Mes Aplicable</label>
              <select className="w-full border-2 p-3 rounded-xl bg-slate-50" value={payForm.month} onChange={e => setPayForm({...payForm, month: e.target.value})}>
                {['ENERO','FEBRERO','MARZO','ABRIL','MAYO','JUNIO','JULIO','AGOSTO','SEPTIEMBRE','OCTUBRE','NOVIEMBRE','DICIEMBRE'].map(m => <option key={m} value={m}>{m}</option>)}
              </select>
            </div>
          </div>
          <div>
            <label className="text-[9px] font-black uppercase text-slate-400">Monto ($)</label>
            <input type="number" step="0.01" className="w-full border-2 p-3 rounded-xl bg-slate-50 font-black text-xl" onChange={e => setPayForm({...payForm, amount: Number(e.target.value)})} />
          </div>
          <div>
            <label className="text-[9px] font-black uppercase text-slate-400">Observación</label>
            <textarea className="w-full border-2 p-3 rounded-xl bg-slate-50 h-20" placeholder="Ej: Saldo pendiente de Noviembre 2025" onChange={e => setPayForm({...payForm, concept: e.target.value})}></textarea>
          </div>
          <button onClick={handleCreate} className="w-full py-4 bg-emerald-600 text-white font-black rounded-xl uppercase text-xs shadow-xl active:scale-95 transition-all">Sincronizar Pago</button>
        </div>
      </Modal>

      <Modal isOpen={feedback.isOpen} onClose={() => setFeedback({...feedback, isOpen: false})} title={feedback.title} type={feedback.type}>
          <div className="text-center space-y-6">
              <p className="text-slate-600 font-bold uppercase text-[12px]">{feedback.message}</p>
              <button onClick={() => setFeedback({...feedback, isOpen: false})} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] tracking-widest">Aceptar</button>
          </div>
      </Modal>
    </div>
  );
};

export default PaymentsModule;

import React, { useState } from 'react';
import { Employee, Payment, AttendanceRecord, CompanyConfig, GlobalSettings, Role } from '../../types.ts';
import { db, doc, setDoc, deleteDoc, compressData } from '../../firebase.ts';
import Modal from '../../components/Modal.tsx';

interface ReportsModuleProps {
  employees: Employee[];
  payments: Payment[];
  attendance: AttendanceRecord[];
  company: CompanyConfig | null;
  settings: GlobalSettings;
  role: Role;
}

const ReportsModule: React.FC<ReportsModuleProps> = ({ employees, payments, attendance, company, settings, role }) => {
  const [reportType, setReportType] = useState<'attendance' | 'payments' | 'validation'>('attendance');
  const [filterYear, setFilterYear] = useState('2026');
  const [filterEmp, setFilterEmp] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [feedback, setFeedback] = useState({ isOpen: false, title: '', message: '', type: 'success' as any });

  const pendingAttendance = attendance.filter(a => a.status === 'pending_approval');

  const handleValidate = async (record: AttendanceRecord, newStatus: 'confirmed' | 'rejected') => {
    const updatedRecord = { 
      ...record, 
      status: newStatus,
      validatedAt: new Date().toISOString()
    };

    await setDoc(doc(db, "attendance", record.id), { payload: compressData(updatedRecord), timestamp: record.timestamp });
    setFeedback({ isOpen: true, title: "Registro Actualizado", message: `El marcaje ha sido ${newStatus === 'confirmed' ? 'aprobado' : 'rechazado'} y sincronizado.`, type: 'success' });
  };

  const handleDeleteAttendance = async (id: string) => {
    if (confirm("¿Desea eliminar este registro de asistencia permanentemente?")) {
      try {
        await deleteDoc(doc(db, "attendance", id));
        setFeedback({ isOpen: true, title: "Eliminado", message: "Registro borrado correctamente.", type: 'success' });
      } catch (e) {
        setFeedback({ isOpen: true, title: "Error", message: "No se pudo eliminar el registro.", type: 'error' });
      }
    }
  };

  const filteredPending = pendingAttendance.filter(req => {
    const emp = employees.find(e => e.id === req.employeeId);
    const searchStr = (emp?.name + " " + emp?.surname + " " + emp?.identification + " " + (req.justification || "")).toLowerCase();
    return searchStr.includes(searchTerm.toLowerCase());
  });

  const filteredPaymentsReport = payments.filter(p => {
    const emp = employees.find(e => e.id === p.employeeId);
    const searchStr = (emp?.name + " " + emp?.surname + " " + emp?.identification + " " + p.concept + " " + p.type).toLowerCase();
    return searchStr.includes(searchTerm.toLowerCase()) && p.status === 'paid';
  });

  const exportAttendanceExcel = () => {
    let csv = "Fecha,Hora,Empleado,Cédula,Tipo,Estado,Atraso\n";
    attendance.sort((a, b) => b.timestamp.localeCompare(a.timestamp)).forEach(rec => {
      const emp = employees.find(e => e.id === rec.employeeId);
      const date = new Date(rec.timestamp);
      csv += `${date.toLocaleDateString()},${date.toLocaleTimeString()},${emp?.surname} ${emp?.name},${emp?.identification},${rec.type === 'in' ? 'Entrada' : 'Salida'},${rec.status},${rec.isLate ? 'SI' : 'NO'}\n`;
    });

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `Reporte_Asistencia_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  };

  const exportPaymentsExcel = () => {
    let csv = "Fecha,Empleado,Identificación,Monto,Tipo,Estado,Concepto\n";
    filteredPaymentsReport.forEach(p => {
      const emp = employees.find(e => e.id === p.employeeId);
      csv += `${new Date(p.date).toLocaleDateString()},${emp?.surname} ${emp?.name},${emp?.identification},${p.amount.toFixed(2)},${p.type},${p.status},${p.concept}\n`;
    });

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `Reporte_Pagos_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  };

  return (
    <div className="space-y-8 fade-in">
      <div className="flex flex-col md:flex-row justify-between items-center bg-white p-8 rounded-[2rem] shadow-sm border border-slate-100 gap-6">
        <div className="w-full">
          <h2 className="text-2xl font-black text-slate-900 uppercase tracking-tighter">Centro de Reportes Analíticos</h2>
          <div className="flex flex-col md:flex-row gap-4 mt-4 items-center">
            <div className="flex gap-2">
              <button onClick={() => setReportType('attendance')} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest ${reportType === 'attendance' ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-100 text-slate-400'}`}>Asistencia</button>
              <button onClick={() => setReportType('payments')} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest ${reportType === 'payments' ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-100 text-slate-400'}`}>Pagos</button>
              <button onClick={() => setReportType('validation')} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest relative ${reportType === 'validation' ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-100 text-slate-400'}`}>
                Validaciones
                {pendingAttendance.length > 0 && <span className="absolute -top-1 -right-1 w-4 h-4 bg-red-500 text-white text-[8px] rounded-full flex items-center justify-center font-black">{pendingAttendance.length}</span>}
              </button>
            </div>
            <input 
              type="text" 
              placeholder="Filtro rápido (Empleado, CI, Motivo)..." 
              className="flex-1 p-2 border rounded-xl text-[10px] font-bold uppercase min-w-[200px]" 
              value={searchTerm} 
              onChange={e => setSearchTerm(e.target.value)}
            />
          </div>
        </div>
        <div className="flex gap-3 w-full md:w-auto">
          <button onClick={() => {
            if (reportType === 'attendance') exportAttendanceExcel();
            else if (reportType === 'payments') exportPaymentsExcel();
          }} className="flex-1 md:flex-none px-6 py-4 bg-emerald-600 text-white font-black rounded-2xl shadow-xl uppercase text-[10px] tracking-widest no-print">Exportar Excel</button>
          <button onClick={() => window.print()} className="flex-1 md:flex-none px-8 py-4 bg-slate-900 text-white font-black rounded-2xl shadow-xl uppercase text-[10px] tracking-widest no-print">Imprimir</button>
        </div>
      </div>

      <div className="bg-white rounded-[2rem] shadow-sm border overflow-hidden">
         <div className="p-10">
            {reportType === 'validation' ? (
              <div className="space-y-6">
                <h3 className="text-xl font-black text-slate-900 uppercase">Solicitudes Pendientes</h3>
                {filteredPending.length === 0 ? (
                  <div className="py-20 text-center bg-slate-50 rounded-3xl border-2 border-dashed">
                    <p className="text-slate-400 font-black uppercase text-xs">Sin registros que coincidan.</p>
                  </div>
                ) : (
                  <div className="space-y-4">
                    {filteredPending.map(req => {
                      const emp = employees.find(e => e.id === req.employeeId);
                      return (
                        <div key={req.id} className="bg-white border rounded-3xl p-6 flex justify-between items-center group">
                          <div className="flex gap-6 items-center">
                            <div>
                              <p className="font-black text-slate-900 uppercase text-sm">{emp?.surname} {emp?.name}</p>
                              <p className="text-slate-400 font-black text-[9px] uppercase mt-1">{new Date(req.timestamp).toLocaleString()}</p>
                              <p className="mt-3 text-[11px] text-slate-500 italic bg-slate-50 p-3 rounded-xl border">Motivo: {req.justification}</p>
                            </div>
                          </div>
                          <div className="flex gap-2">
                             <button onClick={() => handleValidate(req, 'rejected')} className="px-4 py-2 bg-red-50 text-red-600 font-black text-[9px] uppercase rounded-xl">Rechazar</button>
                             <button onClick={() => handleValidate(req, 'confirmed')} className="px-4 py-2 bg-emerald-600 text-white font-black text-[9px] uppercase rounded-xl shadow-lg">Aprobar</button>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                )}
              </div>
            ) : reportType === 'attendance' ? (
               <div className="space-y-6">
                  <div className="mb-10 text-center border-b-2 pb-8">
                    <h1 className="text-3xl font-black text-slate-900 uppercase tracking-tighter">REGISTRO DE ASISTENCIA</h1>
                  </div>
                  <div className="overflow-x-auto">
                    <table className="w-full text-left">
                      <thead className="bg-slate-50 text-[9px] font-black uppercase">
                        <tr>
                          <th className="p-4">Fecha</th>
                          <th className="p-4">Empleado</th>
                          <th className="p-4">Tipo</th>
                          <th className="p-4">Estado</th>
                          <th className="p-4 text-right no-print">Acción</th>
                        </tr>
                      </thead>
                      <tbody className="text-[10px] font-bold uppercase">
                        {attendance.filter(a => {
                          const emp = employees.find(e => e.id === a.employeeId);
                          return (emp?.surname + " " + emp?.name).toLowerCase().includes(searchTerm.toLowerCase());
                        }).sort((a,b) => b.timestamp.localeCompare(a.timestamp)).map(rec => {
                          const emp = employees.find(e => e.id === rec.employeeId);
                          return (
                            <tr key={rec.id} className="border-b">
                              <td className="p-4">{new Date(rec.timestamp).toLocaleString()}</td>
                              <td className="p-4">{emp?.surname} {emp?.name}</td>
                              <td className="p-4">{rec.type === 'in' ? 'Entrada' : 'Salida'}</td>
                              <td className="p-4">{rec.status}</td>
                              <td className="p-4 text-right no-print">
                                {role === Role.SUPER_ADMIN && (
                                  <button onClick={() => handleDeleteAttendance(rec.id)} className="text-red-600 text-[9px] uppercase hover:underline">Eliminar</button>
                                )}
                              </td>
                            </tr>
                          );
                        })}
                      </tbody>
                    </table>
                  </div>
               </div>
            ) : (
               <div>
                  <div className="mb-10 text-center border-b-2 pb-8">
                    <h1 className="text-3xl font-black text-slate-900 uppercase tracking-tighter">INFORME INSTITUCIONAL - {reportType.toUpperCase()}</h1>
                  </div>
                  {/* Si es pagos, mostramos la lista filtrada */}
                  {reportType === 'payments' && (
                    <div className="space-y-4">
                      {filteredPaymentsReport.map(p => {
                        const emp = employees.find(e => e.id === p.employeeId);
                        return (
                          <div key={p.id} className="flex justify-between items-center p-4 border-b">
                            <div>
                              <p className="font-black text-slate-900 uppercase text-xs">{emp?.surname} {emp?.name}</p>
                              <p className="text-[9px] text-slate-400">{p.concept}</p>
                            </div>
                            <p className="font-black text-blue-700">${p.amount.toFixed(2)}</p>
                          </div>
                        );
                      })}
                    </div>
                  )}
                  <div className="py-10 text-center opacity-30 font-black uppercase tracking-widest text-xs">Información generada por ASIST UP Enterprise Hub</div>
               </div>
            )}
         </div>
      </div>

      <Modal isOpen={feedback.isOpen} onClose={() => setFeedback({...feedback, isOpen: false})} title={feedback.title} type={feedback.type}>
          <div className="text-center space-y-6">
              <p className="text-slate-600 font-bold uppercase text-[12px]">{feedback.message}</p>
              <button onClick={() => setFeedback({...feedback, isOpen: false})} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] tracking-widest">Aceptar</button>
          </div>
      </Modal>
    </div>
  );
};

export default ReportsModule;

import React, { useState, useEffect } from 'react';
import { Employee, Role, BloodType, TerminationReason, Gender, CivilStatus, AbsenceRecord } from '../../types.ts';
import Modal from '../../components/Modal.tsx';

interface EmployeeModuleProps {
  employees: Employee[];
  onUpdate: (employees: Employee[]) => void;
  role: Role;
  attendance: any[];
  payments: any[];
  company: any;
}

const EmployeeModule: React.FC<EmployeeModuleProps> = ({ employees, onUpdate, role, payments }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingEmp, setEditingEmp] = useState<Employee | null>(null);
  const [viewingEmp, setViewingEmp] = useState<Employee | null>(null);
  const [isTermModalOpen, setIsTermModalOpen] = useState(false);
  const [isAbsenceModalOpen, setIsAbsenceModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [showArchived, setShowArchived] = useState(false);
  const [feedback, setFeedback] = useState<{isOpen: boolean, title: string, message: string, type: 'success' | 'error' | 'info'}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  const [hasBankInfo, setHasBankInfo] = useState(true);

  const initialForm: Partial<Employee> = {
    name: '', surname: '', identification: '', birthDate: '', phone: '', email: '', 
    gender: Gender.MASCULINO, civilStatus: CivilStatus.SOLTERO,
    origin: 'ECUATORIANA', address: '', 
    bloodType: BloodType.O_POS, startDate: new Date().toISOString().split('T')[0],
    role: Role.EMPLOYEE, salary: 482.00, status: 'active', photo: '', pin: '',
    emergencyContact: { name: '', phone: '' },
    isFixed: true, isAffiliated: true, overSalaryType: 'monthly',
    bankInfo: { ifi: '', type: 'Ahorros', account: '' },
    absences: [],
    observations: []
  };

  const [form, setForm] = useState<Partial<Employee>>(initialForm);
  const [termForm, setTermForm] = useState({ reason: TerminationReason.VOLUNTARY, date: new Date().toISOString().split('T')[0], details: '' });
  const [absenceForm, setAbsenceForm] = useState<Partial<AbsenceRecord>>({ type: 'Falta', date: new Date().toISOString().split('T')[0], reason: '', justified: false });

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setForm(prev => ({ ...prev, photo: reader.result as string }));
      reader.readAsDataURL(file);
    }
  };

  const handleSave = () => {
    if (!form.name || !form.surname || !form.identification) {
      setFeedback({ isOpen: true, title: "Error de Validación", message: "Nombres, apellidos y cédula son obligatorios.", type: "error" });
      return;
    }

    const finalForm = { ...form };
    if (!hasBankInfo) {
      finalForm.bankInfo = { ifi: 'NO APLICA', type: 'Ahorros', account: 'N/A' };
    }

    let updatedList;
    if (editingEmp) {
      updatedList = employees.map(e => e.id === editingEmp.id ? { ...e, ...finalForm } as Employee : e);
      setFeedback({ isOpen: true, title: "Éxito", message: "Expediente actualizado correctamente.", type: "success" });
    } else {
      const autoPin = Math.floor(100000 + Math.random() * 900000).toString();
      const newEmp = { 
        ...finalForm, 
        id: Math.random().toString(36).substr(2, 9), 
        pin: autoPin,
        pinChanged: false,
        pinNeedsReset: false,
        absences: [],
        observations: [],
        totalHoursWorked: 0
      } as Employee;
      updatedList = [...employees, newEmp];
      setFeedback({ isOpen: true, title: "Registro Exitoso", message: `Colaborador registrado. PIN Temporal: ${autoPin}`, type: "success" });
    }
    onUpdate(updatedList);
    setIsModalOpen(false);
  };

  const handleTerminate = () => {
    if (!viewingEmp) return;
    const updated = employees.map(e => e.id === viewingEmp.id ? { 
      ...e, 
      status: 'terminated', 
      terminationDate: termForm.date,
      terminationReason: termForm.reason,
      terminationDetails: termForm.details
    } as Employee : e);
    onUpdate(updated);
    setIsTermModalOpen(false);
    setViewingEmp(null);
    setFeedback({ isOpen: true, title: "Aviso", message: "El colaborador ha sido desvinculado.", type: "success" });
  };

  const handleDeleteEmployee = (empId: string) => {
    if (confirm("¿Está seguro de eliminar este registro? El expediente se conservará en el archivo histórico.")) {
      const updated = employees.map(e => e.id === empId ? { ...e, status: 'archived' } as Employee : e);
      onUpdate(updated);
      setFeedback({ isOpen: true, title: "Registro Archivado", message: "El colaborador ha sido movido al historial de archivo.", type: "info" });
      if (viewingEmp?.id === empId) setViewingEmp(null);
    }
  };

  const handleAddAbsence = () => {
    if (!viewingEmp || !absenceForm.reason) return;
    const newAbsence: AbsenceRecord = {
      id: Math.random().toString(36).substr(2, 9),
      ...absenceForm
    } as AbsenceRecord;

    const updated = employees.map(e => e.id === viewingEmp.id ? { 
      ...e, 
      absences: [...(e.absences || []), newAbsence]
    } : e);

    onUpdate(updated);
    setIsAbsenceModalOpen(false);
    setAbsenceForm({ type: 'Falta', date: new Date().toISOString().split('T')[0], reason: '', justified: false });
    setFeedback({ isOpen: true, title: "Confirmación", message: "Novedad registrada en el historial.", type: "success" });
  };

  const filteredEmployees = employees.filter(e => {
    const matchesSearch = (e.name + " " + e.surname + " " + e.identification).toLowerCase().includes(searchTerm.toLowerCase());
    if (showArchived) return matchesSearch && e.status === 'archived';
    return matchesSearch && e.status !== 'archived';
  });

  return (
    <div className="space-y-4 fade-in">
      <div className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-100 flex flex-col md:flex-row justify-between items-center no-print gap-4">
        <div>
          <h2 className="text-xl font-[950] text-slate-900 tracking-tighter uppercase leading-none">Gestión de Talento Humano</h2>
          <div className="flex gap-4 mt-2">
            <button onClick={() => setShowArchived(false)} className={`text-[9px] font-black uppercase tracking-widest ${!showArchived ? 'text-blue-600 border-b-2 border-blue-600' : 'text-slate-400'}`}>Activos</button>
            <button onClick={() => setShowArchived(true)} className={`text-[9px] font-black uppercase tracking-widest ${showArchived ? 'text-blue-600 border-b-2 border-blue-600' : 'text-slate-400'}`}>Archivados</button>
          </div>
        </div>
        <div className="flex gap-3 w-full md:w-auto">
          <input 
            type="text" 
            placeholder="Buscar por Nombre, Apellido o CI..." 
            className="flex-1 p-3 border rounded-xl text-xs uppercase font-bold min-w-[250px]" 
            value={searchTerm} 
            onChange={e => setSearchTerm(e.target.value)}
          />
          <button onClick={() => { setForm(initialForm); setEditingEmp(null); setHasBankInfo(true); setIsModalOpen(true); }} className="px-8 py-4 bg-blue-700 text-white font-black rounded-2xl shadow-lg uppercase text-[10px] tracking-widest active:scale-95 transition-all">Nuevo Registro</button>
        </div>
      </div>

      <div className="bg-white rounded-[2.5rem] shadow-sm border overflow-hidden no-print">
        <table className="w-full text-left">
          <thead className="bg-slate-50 text-[8px] font-black text-slate-400 uppercase tracking-widest">
            <tr>
              <th className="px-6 py-4">Colaborador</th>
              <th className="px-6 py-4">Cédula</th>
              <th className="px-6 py-4">Cargo</th>
              <th className="px-6 py-4 text-center">Estatus</th>
              <th className="px-6 py-4 text-right">Acciones</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50 text-[11px] font-black uppercase">
            {filteredEmployees.map(emp => (
              <tr key={emp.id} className="hover:bg-blue-50/40 transition-colors">
                <td className="px-6 py-3 font-black text-slate-900">
                  <div className="flex items-center gap-3">
                    <div className="w-8 h-8 rounded-lg overflow-hidden border">
                      {emp.photo ? <img src={emp.photo} className="w-full h-full object-cover" /> : <div className="bg-slate-100 w-full h-full flex items-center justify-center text-[10px]">👤</div>}
                    </div>
                    <span>{emp.surname} {emp.name}</span>
                  </div>
                </td>
                <td className="px-6 py-3 text-[10px] font-mono">{emp.identification}</td>
                <td className="px-6 py-3 text-blue-600 text-[9px] uppercase">{emp.role}</td>
                <td className="px-6 py-3 text-center">
                  <span className={`px-3 py-1 rounded-full text-[8px] font-black uppercase ${emp.status === 'active' ? 'bg-emerald-50 text-emerald-600' : emp.status === 'terminated' ? 'bg-red-50 text-red-600' : 'bg-slate-100 text-slate-400'}`}>
                    {emp.status === 'active' ? 'Activo' : emp.status === 'terminated' ? 'Salida' : 'Archivado'}
                  </span>
                </td>
                <td className="px-6 py-3 text-right flex gap-2 justify-end">
                   <button onClick={() => setViewingEmp(emp)} className="px-3 py-1.5 bg-blue-50 text-blue-700 rounded-lg text-[8px] font-black uppercase">Ver Ficha</button>
                   {role === Role.SUPER_ADMIN && emp.status !== 'archived' && (
                     <>
                        <button onClick={() => { setEditingEmp(emp); setForm(emp); setHasBankInfo(emp.bankInfo?.ifi !== 'NO APLICA'); setIsModalOpen(true); }} className="px-3 py-1.5 bg-slate-100 text-slate-600 rounded-lg text-[8px] font-black uppercase">Editar</button>
                        <button onClick={() => handleDeleteEmployee(emp.id)} className="px-3 py-1.5 bg-red-50 text-red-600 rounded-lg text-[8px] font-black uppercase">Eliminar</button>
                     </>
                   )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title={editingEmp ? "Actualizar Expediente" : "Nuevo Registro Personal"}>
         <div className="space-y-6 max-h-[75vh] overflow-y-auto px-2 custom-scroll">
            <div className="border-b pb-4">
               <h4 className="text-[10px] font-black text-blue-600 uppercase tracking-widest mb-4">I. Datos de Identidad</h4>
               <div className="grid grid-cols-2 gap-4">
                  <div>
                     <label className="text-[9px] font-black text-slate-400 uppercase">Nombres*</label>
                     <input className="w-full border-2 p-3 rounded-xl text-xs font-black uppercase" value={form.name} onChange={e => setForm({...form, name: e.target.value.toUpperCase()})} />
                  </div>
                  <div>
                     <label className="text-[9px] font-black text-slate-400 uppercase">Apellidos*</label>
                     <input className="w-full border-2 p-3 rounded-xl text-xs font-black uppercase" value={form.surname} onChange={e => setForm({...form, surname: e.target.value.toUpperCase()})} />
                  </div>
                  <div>
                     <label className="text-[9px] font-black text-slate-400 uppercase">Cédula*</label>
                     <input maxLength={10} className="w-full border-2 p-3 rounded-xl text-xs font-black" value={form.identification} onChange={e => setForm({...form, identification: e.target.value.replace(/\D/g,'')})} />
                  </div>
                  <div>
                     <label className="text-[9px] font-black text-slate-400 uppercase">Fecha Nacimiento</label>
                     <input type="date" className="w-full border-2 p-3 rounded-xl text-xs font-black" value={form.birthDate} onChange={e => setForm({...form, birthDate: e.target.value})} />
