  activeTab: string;
  setActiveTab: (tab: any) => void;
  onLogout: () => void;
  companyName?: string;
}

const Sidebar: React.FC<SidebarProps> = ({ role, activeTab, setActiveTab, onLogout, companyName }) => {
  const [isOpen, setIsOpen] = useState(false);
