               <div className="bg-slate-900 p-6 rounded-3xl text-white flex justify-between items-center shadow-2xl">
                  <div><p className="text-[8px] font-black uppercase tracking-[0.4em] opacity-60">Valor Neto a Recibir</p><p className="text-[9px] mt-1 font-bold opacity-40 italic">Certificamos el cumplimiento de haberes.</p></div>
                  <p className="text-3xl font-[950] tracking-tighter">${d.netToReceive.toFixed(2)}</p>
               </div>
               <div className="grid grid-cols-2 gap-20 pt-16 text-center no-print-section">
                  <div className="border-t pt-2"><p className="text-[8px] font-black uppercase">Recibí Conforme</p><p className="text-[7px] text-slate-400 mt-1">{individualPayroll.name}</p></div>
                  <div className="border-t pt-2"><p className="text-[8px] font-black uppercase">Autorizado Por</p><p className="text-[7px] text-slate-400 mt-1">Talento Humano</p></div>
