import React, { useState } from 'react';
import { Employee, Payment, Role } from '../../types.ts';
import Modal from '../../components/Modal.tsx';
import { db, doc, deleteDoc } from '../../firebase.ts';

interface PaymentsModuleProps {
  employees: Employee[];
  payments: Payment[];
  onUpdate: (payments: Payment[]) => void;
  role: Role;
}

const PaymentsModule: React.FC<PaymentsModuleProps> = ({ employees, payments, onUpdate, role }) => {
  const [isPayOpen, setIsPayOpen] = useState(false);
  const [selectedPayForPrint, setSelectedPayForPrint] = useState<Payment | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [feedback, setFeedback] = useState<{isOpen: boolean, title: string, message: string, type: 'success' | 'error' | 'info'}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  const [payForm, setPayForm] = useState<Partial<Payment>>({ type: 'Salary', amount: 0, method: 'Efectivo', concept: '', month: new Date().toLocaleString('es-EC', {month: 'long'}).toUpperCase(), year: '2026', status: 'paid' });

  const handleCreate = () => {
    if (!payForm.employeeId || !payForm.amount) {
        setFeedback({ isOpen: true, title: "Error", message: "Seleccione colaborador y monto.", type: "error" });
        return;
    }
    const newPay: Payment = { ...payForm, id: Math.random().toString(36).substr(2, 15), date: new Date().toISOString(), status: 'paid' } as Payment;
    onUpdate([newPay, ...payments]);
    setIsPayOpen(false);
    setFeedback({ isOpen: true, title: "Éxito", message: "Pago registrado en tesorería.", type: "success" });
  };

  const filteredPayments = payments.filter(p => {
    const emp = employees.find(e => e.id === p.employeeId);
    const searchStr = ((emp?.name || "") + " " + (emp?.surname || "") + " " + (emp?.identification || "") + " " + p.concept + " " + p.type).toLowerCase();
    return searchStr.includes(searchTerm.toLowerCase());
  });

  return (
    <div className="space-y-6 fade-in">
      <div className="flex flex-col md:flex-row justify-between items-center bg-white p-8 rounded-[2rem] shadow-sm border border-slate-100 gap-6 no-print">
        <h2 className="text-xl font-black text-slate-900 uppercase">Tesorería de Talento Humano</h2>
        <div className="flex gap-4 w-full md:w-auto">
          <input type="text" placeholder="Filtrar..." className="flex-1 md:w-64 p-3 border rounded-xl text-[10px] font-bold uppercase" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
          <button onClick={() => setIsPayOpen(true)} className="px-8 py-4 bg-emerald-600 text-white font-black rounded-2xl shadow-lg uppercase text-[10px] tracking-widest">Nuevo Pago</button>
        </div>
      </div>

      <div className="bg-white rounded-[2rem] shadow-sm border overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest">
            <tr><th className="px-8 py-4">Fecha</th><th className="px-8 py-4">Empleado</th><th className="px-8 py-4">Monto</th><th className="px-8 py-4">Concepto</th><th className="px-8 py-4 text-right">Acción</th></tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {filteredPayments.map(p => {
              const emp = employees.find(e => e.id === p.employeeId);
              return (
                <tr key={p.id} className="text-xs hover:bg-slate-50 transition-all">
                  <td className="px-8 py-4 font-bold">{new Date(p.date).toLocaleDateString()}</td>
                  <td className="px-8 py-4 font-black uppercase">{emp?.surname} {emp?.name}</td>
                  <td className="px-8 py-4 font-black text-slate-900">${p.amount.toFixed(2)}</td>
                  <td className="px-8 py-4 font-black text-[10px] uppercase text-slate-400">{p.type}</td>
                  <td className="px-8 py-4 text-right">
                    <button onClick={() => setSelectedPayForPrint(p)} className="text-blue-600 font-black text-[9px] uppercase hover:underline">Imprimir Comprobante</button>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {/* MODAL COMPROBANTE IMPRIMIBLE */}
      <Modal isOpen={!!selectedPayForPrint} onClose={() => setSelectedPayForPrint(null)} title="Comprobante de Egreso / Tesorería">
        {selectedPayForPrint && (() => {
           const emp = employees.find(e => e.id === selectedPayForPrint.employeeId);
           return (
             <div className="p-8 space-y-10 bg-white">
                <div className="text-center border-b pb-6"><h3 className="text-2xl font-black text-slate-900 uppercase tracking-tighter">Comprobante de Pago</h3><p className="text-[10px] font-bold text-slate-400 mt-2 uppercase tracking-widest">Tesorería Institucional - ASIST UP</p></div>
                <div className="grid grid-cols-2 gap-10 text-[10px] font-bold uppercase">
                   <div className="space-y-4">
                      <div><p className="text-slate-400 text-[8px] font-black mb-1">Beneficiario</p><p className="text-slate-900 text-lg font-black">{emp?.surname} {emp?.name}</p><p className="text-slate-500">CI: {emp?.identification}</p></div>
                      <div><p className="text-slate-400 text-[8px] font-black mb-1">Concepto de Pago</p><p className="text-slate-900">{selectedPayForPrint.type} - {selectedPayForPrint.month}</p><p className="text-slate-500 text-[9px] lowercase italic">{selectedPayForPrint.concept}</p></div>
                   </div>
                   <div className="text-right space-y-4">
                      <div><p className="text-slate-400 text-[8px] font-black mb-1">Valor Desembolsado</p><p className="text-4xl font-[950] text-slate-900">${selectedPayForPrint.amount.toFixed(2)}</p></div>
                      <div><p className="text-slate-400 text-[8px] font-black mb-1">Fecha Valor</p><p className="text-slate-900">{new Date(selectedPayForPrint.date).toLocaleString()}</p></div>
                   </div>
                </div>
                <div className="bg-slate-50 p-6 rounded-3xl border border-dashed border-slate-300 grid grid-cols-2 gap-20 text-center pt-14 pb-10">
                   <div className="border-t pt-4 text-[9px] font-black uppercase text-slate-400">Firma Colaborador</div>
                   <div className="border-t pt-4 text-[9px] font-black uppercase text-slate-400">Autorización Tesorería</div>
                </div>
                <button onClick={() => window.print()} className="w-full py-4 bg-slate-900 text-white font-black rounded-2xl uppercase text-[10px] tracking-widest no-print">Imprimir Documento</button>
             </div>
           );
        })()}
      </Modal>

      <Modal isOpen={isPayOpen} onClose={() => setIsPayOpen(false)} title="Registrar Pago">
        <div className="space-y-4">
          <select className="w-full border-2 p-3 rounded-xl bg-slate-50" onChange={e => setPayForm({...payForm, employeeId: e.target.value})}><option value="">Seleccionar Colaborador...</option>{employees.filter(e => e.status === 'active').map(e => <option key={e.id} value={e.id}>{e.surname} {e.name}</option>)}</select>
          <div className="grid grid-cols-2 gap-4">
            <select className="w-full border-2 p-3 rounded-xl bg-slate-50" value={payForm.type} onChange={e => setPayForm({...payForm, type: e.target.value as any})}><option value="Salary">Sueldo</option><option value="ExtraHours">Horas Extras</option><option value="Bonus">Bono</option><option value="Loan">Préstamo</option></select>
            <select className="w-full border-2 p-3 rounded-xl bg-slate-50" value={payForm.month} onChange={e => setPayForm({...payForm, month: e.target.value})}>{['ENERO','FEBRERO','MARZO','ABRIL','MAYO','JUNIO','JULIO','AGOSTO','SEPTIEMBRE','OCTUBRE','NOVIEMBRE','DICIEMBRE'].map(m => <option key={m} value={m}>{m}</option>)}</select>
          </div>
          <input type="number" step="0.01" className="w-full border-2 p-4 rounded-xl font-black text-2xl" placeholder="0.00" onChange={e => setPayForm({...payForm, amount: Number(e.target.value)})} />
          <textarea className="w-full border-2 p-3 rounded-xl h-20 text-xs font-bold" placeholder="Observaciones..." onChange={e => setPayForm({...payForm, concept: e.target.value})}></textarea>
          <button onClick={handleCreate} className="w-full py-4 bg-emerald-600 text-white font-black rounded-xl uppercase text-xs shadow-xl active:scale-95 transition-all">Registrar Desembolso</button>
        </div>
      </Modal>
    </div>
  );
};

export default PaymentsModule;

import React, { useState, useEffect } from 'react';
import { Employee, Role, BloodType, Gender, CivilStatus, AbsenceRecord, TerminationReason } from '../../types.ts';
import Modal from '../../components/Modal.tsx';

interface EmployeeModuleProps {
  employees: Employee[];
  onUpdate: (employees: Employee[]) => void;
  role: Role;
  attendance: any[];
  payments: any[];
  company: any;
}

const EmployeeModule: React.FC<EmployeeModuleProps> = ({ employees, onUpdate, role }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingEmp, setEditingEmp] = useState<Employee | null>(null);
  const [viewingEmp, setViewingEmp] = useState<Employee | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [showArchived, setShowArchived] = useState(false);
  const [hasBankInfo, setHasBankInfo] = useState(true);

  const [isAbsenceModalOpen, setIsAbsenceModalOpen] = useState(false);
  const [isTermModalOpen, setIsTermModalOpen] = useState(false);
  const [newAbsence, setNewAbsence] = useState<Partial<AbsenceRecord>>({ type: 'Falta', justified: false, date: new Date().toISOString().split('T')[0], reason: '' });
  const [termData, setTermData] = useState({ reason: TerminationReason.VOLUNTARY, details: '', date: new Date().toISOString().split('T')[0] });

  const [feedback, setFeedback] = useState<{isOpen: boolean, title: string, message: string, type: 'success' | 'error' | 'info'}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  const initialForm: Partial<Employee> = {
    name: '', surname: '', identification: '', birthDate: '', phone: '', email: '', 
    gender: Gender.MASCULINO, civilStatus: CivilStatus.SOLTERO,
    origin: 'ECUATORIANA', address: '', 
    bloodType: BloodType.O_POS, startDate: new Date().toISOString().split('T')[0],
    role: Role.EMPLOYEE, salary: 482.00, status: 'active', photo: '', pin: '',
    emergencyContact: { name: '', phone: '' },
    isFixed: true, isAffiliated: true, overSalaryType: 'monthly',
    bankInfo: { ifi: '', type: 'Ahorros', account: '' },
    absences: [],
    observations: []
  };

  const [form, setForm] = useState<Partial<Employee>>(initialForm);

  useEffect(() => {
    if (!form.isAffiliated && form.overSalaryType !== 'none') {
      setForm(prev => ({ ...prev, overSalaryType: 'none' }));
    }
  }, [form.isAffiliated]);

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setForm(prev => ({ ...prev, photo: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSave = () => {
    if (!form.name || !form.surname || !form.identification || !form.salary) {
      setFeedback({ isOpen: true, title: "Error", message: "Nombres, apellidos, cédula y sueldo son obligatorios.", type: "error" });
      return;
    }
    const finalForm = { ...form };
    if (!hasBankInfo) finalForm.bankInfo = { ifi: 'NO APLICA', type: 'Ahorros', account: 'N/A' };

    let updatedList;
    if (editingEmp) {
      updatedList = employees.map(e => e.id === editingEmp.id ? { ...e, ...finalForm } as Employee : e);
      setFeedback({ isOpen: true, title: "Éxito", message: "Expediente actualizado.", type: "success" });
    } else {
      const autoPin = Math.floor(100000 + Math.random() * 900000).toString();
      const newEmp = { ...finalForm, id: Math.random().toString(36).substr(2, 9), pin: autoPin, pinChanged: false, pinNeedsReset: false, absences: [], observations: [], totalHoursWorked: 0, status: 'active' } as Employee;
      updatedList = [...employees, newEmp];
      setFeedback({ isOpen: true, title: "Éxito", message: `Colaborador registrado. PIN: ${autoPin}`, type: "success" });
    }
    onUpdate(updatedList);
    setIsModalOpen(false);
  };

  const handleAddAbsence = () => {
    if (!viewingEmp) return;
    const record: AbsenceRecord = { ...newAbsence, id: Math.random().toString(36).substr(2, 9) } as AbsenceRecord;
    const updated = employees.map(e => e.id === viewingEmp.id ? { ...e, absences: [...(e.absences || []), record] } : e);
    onUpdate(updated);
    setViewingEmp({ ...viewingEmp, absences: [...(viewingEmp.absences || []), record] });
    setIsAbsenceModalOpen(false);
  };

  const handleTerminate = () => {
    if (!viewingEmp) return;
    const updated = employees.map(e => e.id === viewingEmp.id ? { ...e, status: 'terminated', terminationDate: termData.date, terminationReason: termData.reason, terminationDetails: termData.details } : e);
    onUpdate(updated);
    setViewingEmp(null);
    setIsTermModalOpen(false);
    setFeedback({ isOpen: true, title: "Éxito", message: "Colaborador desvinculado.", type: "success" });
  };

  const filteredEmployees = employees.filter(e => {
    const matchesSearch = (e.name + " " + e.surname + " " + e.identification).toLowerCase().includes(searchTerm.toLowerCase());
    return showArchived ? matchesSearch && e.status === 'archived' : matchesSearch && e.status !== 'archived';
  });

  return (
    <div className="space-y-4 fade-in">
      <div className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-100 flex flex-col md:flex-row justify-between items-center no-print gap-4">
        <div>
          <h2 className="text-xl font-[950] text-slate-900 tracking-tighter uppercase leading-none">Gestión Humana</h2>
          <div className="flex gap-4 mt-2">
            <button onClick={() => setShowArchived(false)} className={`text-[9px] font-black uppercase tracking-widest ${!showArchived ? 'text-blue-600 border-b-2 border-blue-600' : 'text-slate-400'}`}>Activos/Salidas</button>
            <button onClick={() => setShowArchived(true)} className={`text-[9px] font-black uppercase tracking-widest ${showArchived ? 'text-blue-600 border-b-2 border-blue-600' : 'text-slate-400'}`}>Archivo</button>
          </div>
        </div>
        <div className="flex gap-3 w-full md:w-auto">
          <input type="text" placeholder="Buscar..." className="flex-1 p-3 border rounded-xl text-xs uppercase font-bold" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
          <button onClick={() => { setForm(initialForm); setEditingEmp(null); setHasBankInfo(true); setIsModalOpen(true); }} className="px-8 py-4 bg-blue-700 text-white font-black rounded-2xl shadow-lg uppercase text-[10px] tracking-widest active:scale-95 transition-all">Nuevo Registro</button>
        </div>
      </div>

      <div className="bg-white rounded-[2.5rem] shadow-sm border overflow-hidden no-print">
        <table className="w-full text-left">
          <thead className="bg-slate-50 text-[8px] font-black text-slate-400 uppercase tracking-widest">
            <tr>
              <th className="px-6 py-4">Colaborador</th>
              <th className="px-6 py-4">Cédula</th>
              <th className="px-6 py-4">Cargo</th>
              <th className="px-6 py-4 text-center">Estatus</th>
              <th className="px-6 py-4 text-right">Acciones</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50 text-[11px] font-black uppercase">
            {filteredEmployees.map(emp => (
              <tr key={emp.id} className="hover:bg-blue-50/40 transition-colors">
                <td className="px-6 py-3 font-black text-slate-900 flex items-center gap-3">
                  <div className="w-8 h-8 rounded-lg overflow-hidden border bg-slate-100 flex items-center justify-center">
                    {emp.photo ? <img src={emp.photo} className="w-full h-full object-cover" /> : <span>👤</span>}
                  </div>
                  {emp.surname} {emp.name}
                </td>
                <td className="px-6 py-3 text-[10px] font-mono">{emp.identification}</td>
                <td className="px-6 py-3 text-blue-600 text-[9px] uppercase">{emp.role}</td>
                <td className="px-6 py-3 text-center">
                  <span className={`px-3 py-1 rounded-full text-[8px] font-black uppercase ${emp.status === 'active' ? 'bg-emerald-50 text-emerald-600' : 'bg-red-50 text-red-600'}`}>
                    {emp.status === 'active' ? 'Activo' : 'Salida'}
                  </span>
                </td>
                <td className="px-6 py-3 text-right flex gap-2 justify-end">
                   <button onClick={() => setViewingEmp(emp)} className="px-3 py-1.5 bg-blue-50 text-blue-700 rounded-lg text-[8px] font-black uppercase">Expediente</button>
                   {role === Role.SUPER_ADMIN && (
                     <button onClick={() => { setEditingEmp(emp); setForm(emp); setHasBankInfo(emp.bankInfo?.ifi !== 'NO APLICA'); setIsModalOpen(true); }} className="px-3 py-1.5 bg-slate-100 text-slate-600 rounded-lg text-[8px] font-black uppercase">Editar</button>
                   )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <Modal isOpen={!!viewingEmp} onClose={() => setViewingEmp(null)} title="Expediente Integral">
        {viewingEmp && (
          <div className="space-y-6">
            <div className="flex gap-6 items-center border-b pb-4">
               <div className="w-20 h-20 rounded-2xl overflow-hidden border bg-slate-100 flex items-center justify-center shadow-md">
                  {viewingEmp.photo ? <img src={viewingEmp.photo} className="w-full h-full object-cover" /> : <span className="text-3xl">👤</span>}
               </div>
               <div>
                  <h3 className="text-xl font-[950] text-slate-900 uppercase tracking-tighter">{viewingEmp.surname} {viewingEmp.name}</h3>
                  <p className="text-[9px] font-black text-blue-600 uppercase tracking-widest">{viewingEmp.role} | {viewingEmp.identification}</p>
                  <p className="text-[8px] font-bold text-slate-400 mt-1 uppercase tracking-widest">Ingreso: {viewingEmp.startDate}</p>
               </div>
            </div>
            <section>
               <div className="flex justify-between items-center mb-4">
                  <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Historial de Novedades (Faltas/Atrasos/Permisos)</h4>
                  {viewingEmp.status === 'active' && <button onClick={() => setIsAbsenceModalOpen(true)} className="px-3 py-1.5 bg-blue-50 text-blue-600 rounded-lg text-[8px] font-black uppercase">Nueva Novedad</button>}
               </div>
               <div className="bg-slate-50 rounded-2xl overflow-hidden border max-h-48 overflow-y-auto custom-scroll">
                  <table className="w-full text-left">
                     <thead className="bg-slate-100 text-[8px] font-black uppercase text-slate-400 sticky top-0">
                        <tr><th className="p-3">Fecha</th><th className="p-3">Tipo</th><th className="p-3">Motivo</th><th className="p-3">Justificado</th></tr>
                     </thead>
                     <tbody className="text-[9px] font-bold uppercase divide-y">
                        {viewingEmp.absences?.map(a => (
                           <tr key={a.id}><td className="p-3">{a.date}</td><td className="p-3">{a.type}</td><td className="p-3">{a.reason}</td><td className="p-3 text-center">{a.justified ? 'S' : 'N'}</td></tr>
                        )) || <tr><td colSpan={4} className="p-10 text-center text-slate-300">Sin registros</td></tr>}
                     </tbody>
                  </table>
               </div>
            </section>
            {viewingEmp.status === 'active' && role === Role.SUPER_ADMIN && (
              <div className="pt-4 border-t flex justify-end">
                 <button onClick={() => setIsTermModalOpen(true)} className="px-4 py-2 bg-red-50 text-red-600 rounded-xl text-[9px] font-black uppercase border border-red-200">Desvincular Empleado</button>
              </div>
            )}
          </div>
        )}
      </Modal>

      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title={editingEmp ? "Actualizar Expediente" : "Nuevo Registro"}>
         <div className="space-y-6 max-h-[75vh] overflow-y-auto px-2 custom-scroll">
            <section className="border-b pb-4">
               <h4 className="text-[10px] font-black text-blue-600 uppercase tracking-widest mb-4">I. Identidad y Fotografía</h4>
               <div className="grid grid-cols-2 gap-4">
                  <div className="col-span-2">
                     <label className="text-[9px] font-black text-slate-400 uppercase">Cargar Foto desde Dispositivo</label>
                     <div className="flex gap-4 items-center mt-2">
                        <div className="w-20 h-20 bg-slate-50 rounded-2xl border-2 border-dashed flex items-center justify-center overflow-hidden">
