          <button onClick={() => setIsPayOpen(true)} className="px-8 py-4 bg-emerald-600 text-white font-black rounded-2xl shadow-lg uppercase text-[10px] tracking-widest active:scale-95 transition-all">Nuevo Pago</button>
        </div>
      </div>

      <div className="bg-white rounded-[2rem] shadow-sm border overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest">
            <tr><th className="px-8 py-4">Fecha Valor</th><th className="px-8 py-4">Empleado</th><th className="px-8 py-4">Desembolso</th><th className="px-8 py-4">Tipo</th><th className="px-8 py-4 text-right">Acciones</th></tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {filteredPayments.map(p => {
              const emp = employees.find(e => e.id === p.employeeId);
              return (
                <tr key={p.id} className="text-xs hover:bg-slate-50 transition-all">
                  <td className="px-8 py-4 font-bold">{new Date(p.date).toLocaleDateString()}</td>
                  <td className="px-8 py-4 font-black uppercase text-slate-900">{emp?.surname} {emp?.name}</td>
                  <td className="px-8 py-4 font-black text-blue-700">${p.amount.toFixed(2)}</td>
                  <td className="px-8 py-4 font-black text-[10px] uppercase text-slate-400">{p.type}</td>
                  <td className="px-8 py-4 text-right flex gap-3 justify-end">
                    <button onClick={() => exportPayExcel(p)} className="text-emerald-600 font-black text-[9px] uppercase hover:underline">Excel</button>
                    <button onClick={() => setSelectedPayForPrint(p)} className="text-blue-600 font-black text-[9px] uppercase hover:underline">Ver/Imprimir/PDF</button>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      <Modal isOpen={!!selectedPayForPrint} onClose={() => setSelectedPayForPrint(null)} title="Comprobante de Egreso Institucional">
        {selectedPayForPrint && (() => {
           const emp = employees.find(e => e.id === selectedPayForPrint.employeeId);
           return (
             <div className="p-10 space-y-12 bg-white" id="payment-voucher-print">
                <div className="text-center border-b-4 border-slate-900 pb-8"><h3 className="text-3xl font-[950] text-slate-900 uppercase tracking-tighter italic">EGRESO DE TESORERÍA</h3><p className="text-[11px] font-black text-slate-400 mt-2 uppercase tracking-widest">ASIST UP Enterprise Suite - Comprobante de Pago</p></div>
                <div className="grid grid-cols-2 gap-10 text-[11px] font-bold uppercase">
                   <div className="space-y-6">
                      <div><p className="text-slate-400 text-[9px] font-black mb-1 tracking-widest">Beneficiario Titular</p><p className="text-slate-900 text-xl font-[950]">{emp?.surname} {emp?.name}</p><p className="text-slate-500 font-black">Cédula: {emp?.identification}</p></div>
                      <div><p className="text-slate-400 text-[9px] font-black mb-1 tracking-widest">Concepto de Desembolso</p><p className="text-slate-900 font-black">{selectedPayForPrint.type} - {selectedPayForPrint.month} {selectedPayForPrint.year}</p><p className="text-slate-500 text-[10px] lowercase italic">{selectedPayForPrint.concept}</p></div>
                   </div>
                   <div className="text-right space-y-6">
                      <div><p className="text-slate-400 text-[9px] font-black mb-1 tracking-widest">Valor Liquidado</p><p className="text-5xl font-[950] text-slate-900 tracking-tighter">${selectedPayForPrint.amount.toFixed(2)}</p></div>
                      <div><p className="text-slate-400 text-[9px] font-black mb-1 tracking-widest">Fecha de Pago</p><p className="text-slate-900 font-black">{new Date(selectedPayForPrint.date).toLocaleString()}</p></div>
                   </div>
                </div>
                <div className="bg-slate-50 p-10 rounded-[3rem] border-2 border-dashed border-slate-300 grid grid-cols-2 gap-20 text-center pt-24 pb-10">
                   <div className="border-t-2 border-slate-900 pt-4 text-[10px] font-black uppercase text-slate-900">Firma del Colaborador</div>
                   <div className="border-t-2 border-slate-900 pt-4 text-[10px] font-black uppercase text-slate-900">Autorización de Caja</div>
                </div>
                <div className="flex gap-4 no-print">
                   <button onClick={() => exportPayExcel(selectedPayForPrint)} className="flex-1 py-5 bg-emerald-600 text-white font-black rounded-3xl uppercase text-[10px] tracking-widest active:scale-95 transition-all">Excel del Pago</button>
                   <button onClick={() => window.print()} className="flex-1 py-5 bg-slate-900 text-white font-black rounded-3xl uppercase text-[10px] tracking-widest active:scale-95 transition-all">Imprimir / Guardar PDF</button>
                </div>
             </div>
           );
        })()}
      </Modal>

      <Modal isOpen={isPayOpen} onClose={() => setIsPayOpen(false)} title="Registrar Egreso">
        <div className="space-y-4">
          <select className="w-full border-2 p-3 rounded-xl bg-slate-50 text-[11px] font-black uppercase" onChange={e => setPayForm({...payForm, employeeId: e.target.value})}><option value="">Seleccionar Beneficiario...</option>{employees.filter(e => e.status === 'active').map(e => <option key={e.id} value={e.id}>{e.surname} {e.name}</option>)}</select>
          <div className="grid grid-cols-2 gap-4">
            <select className="w-full border-2 p-3 rounded-xl bg-slate-50 text-[11px] font-black uppercase" value={payForm.type} onChange={e => setPayForm({...payForm, type: e.target.value as any})}><option value="Salary">Sueldo</option><option value="ExtraHours">Horas Extras</option><option value="Bonus">Bono</option><option value="Loan">Préstamo</option><option value="Emergency">Emergencia</option></select>
            <select className="w-full border-2 p-3 rounded-xl bg-slate-50 text-[11px] font-black uppercase" value={payForm.month} onChange={e => setPayForm({...payForm, month: e.target.value})}>{['ENERO','FEBRERO','MARZO','ABRIL','MAYO','JUNIO','JULIO','AGOSTO','SEPTIEMBRE','OCTUBRE','NOVIEMBRE','DICIEMBRE'].map(m => <option key={m} value={m}>{m}</option>)}</select>
          </div>
          <input type="number" step="0.01" className="w-full border-2 p-5 rounded-2xl font-[950] text-4xl text-center focus:border-blue-600 outline-none" placeholder="0.00" onChange={e => setPayForm({...payForm, amount: Number(e.target.value)})} />
          <textarea className="w-full border-2 p-3 rounded-xl h-24 text-xs font-bold" placeholder="Concepto o motivo del desembolso..." onChange={e => setPayForm({...payForm, concept: e.target.value})}></textarea>
          <button onClick={handleCreate} className="w-full py-5 bg-emerald-600 text-white font-[950] rounded-[2rem] uppercase text-[11px] tracking-[0.2em] shadow-2xl active:scale-95 transition-all">Sincronizar Pago</button>
        </div>
      </Modal>

      <Modal isOpen={feedback.isOpen} onClose={() => setFeedback({...feedback, isOpen: false})} title={feedback.title} type={feedback.type}><div className="text-center p-4"><p className="text-xs font-bold uppercase">{feedback.message}</p><button onClick={() => setFeedback({...feedback, isOpen: false})} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] mt-4">Entendido</button></div></Modal>
    </div>
  );
};

