              <th className="px-6 py-4">Colaborador</th>
              <th className="px-6 py-4">Cédula</th>
              <th className="px-6 py-4">Cargo</th>
              <th className="px-6 py-4 text-center">Estatus</th>
              <th className="px-6 py-4 text-right">Acciones</th>
            </tr>
