                    <button onClick={() => setSelectedPayForPrint(p)} className="text-blue-600 font-black text-[9px] uppercase hover:underline">Ver/Imprimir/PDF</button>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      <Modal isOpen={!!selectedPayForPrint} onClose={() => setSelectedPayForPrint(null)} title="Comprobante de Egreso Institucional">
        {selectedPayForPrint && (() => {
           const emp = employees.find(e => e.id === selectedPayForPrint.employeeId);
           return (
