import React, { useState } from 'react';
import { Employee, Payment, Role } from '../../types.ts';
import Modal from '../../components/Modal.tsx';

interface PaymentsModuleProps {
  employees: Employee[];
  payments: Payment[];
  onUpdate: (payments: Payment[]) => void;
  role: Role;
}

const PaymentsModule: React.FC<PaymentsModuleProps> = ({ employees, payments, onUpdate, role }) => {
  const [isPayOpen, setIsPayOpen] = useState(false);
  const [selectedPayForPrint, setSelectedPayForPrint] = useState<Payment | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [feedback, setFeedback] = useState<{isOpen: boolean, title: string, message: string, type: 'success' | 'error' | 'info'}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  const [payForm, setPayForm] = useState<Partial<Payment>>({ type: 'Salary', amount: 0, method: 'Efectivo', concept: '', month: new Date().toLocaleString('es-EC', {month: 'long'}).toUpperCase(), year: '2026', status: 'paid' });

  const handleCreate = () => {
    if (!payForm.employeeId || !payForm.amount) {
        setFeedback({ isOpen: true, title: "Error", message: "Seleccione beneficiario y monto.", type: "error" });
        return;
    }
    const newPay: Payment = { ...payForm, id: Math.random().toString(36).substr(2, 15), date: new Date().toISOString(), status: 'paid' } as Payment;
    onUpdate([newPay, ...payments]);
    setIsPayOpen(false);
    setFeedback({ isOpen: true, title: "Éxito", message: "Desembolso registrado.", type: "success" });
  };

  const exportPayExcel = (p: Payment) => {
    const emp = employees.find(e => e.id === p.employeeId);
    let csv = "Fecha,Empleado,CI,Monto,Tipo,Concepto,Metodo\n";
    csv += `${new Date(p.date).toLocaleDateString()},${emp?.surname} ${emp?.name},${emp?.identification},${p.amount.toFixed(2)},${p.type},${p.concept},${p.method}\n`;
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `EGRESO_${emp?.surname || 'EMP'}_${p.id.substr(0,5)}.csv`;
    link.click();
  };

  const filteredPayments = payments.filter(p => {
    const emp = employees.find(e => e.id === p.employeeId);
    const searchStr = ((emp?.name || "") + " " + (emp?.surname || "") + " " + (emp?.identification || "") + " " + p.concept + " " + p.type).toLowerCase();
    return searchStr.includes(searchTerm.toLowerCase());
  });

  return (
    <div className="space-y-6 fade-in">
      <div className="flex flex-col md:flex-row justify-between items-center bg-white p-8 rounded-[2.5rem] shadow-sm border border-slate-100 gap-6 no-print">
        <h2 className="text-xl font-black text-slate-900 uppercase tracking-tighter">Tesorería Corporativa</h2>
        <div className="flex gap-4 w-full md:w-auto">
          <input type="text" placeholder="Buscar..." className="flex-1 md:w-80 p-3 border rounded-xl text-[10px] font-bold uppercase" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
          <button onClick={() => setIsPayOpen(true)} className="px-8 py-4 bg-emerald-600 text-white font-black rounded-2xl shadow-lg uppercase text-[10px] tracking-widest active:scale-95 transition-all">Nuevo Pago</button>
        </div>
      </div>

      <div className="bg-white rounded-[2rem] shadow-sm border overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest">
            <tr><th className="px-8 py-4">Fecha</th><th className="px-8 py-4">Empleado</th><th className="px-8 py-4">Monto</th><th className="px-8 py-4">Tipo</th><th className="px-8 py-4 text-right">Opciones</th></tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {filteredPayments.map(p => {
              const emp = employees.find(e => e.id === p.employeeId);
              return (
                <tr key={p.id} className="text-xs hover:bg-slate-50 transition-all">
                  <td className="px-8 py-4 font-bold">{new Date(p.date).toLocaleDateString()}</td>
                  <td className="px-8 py-4 font-black uppercase text-slate-900">{emp?.surname} {emp?.name}</td>
                  <td className="px-8 py-4 font-black text-blue-700">${p.amount.toFixed(2)}</td>
