                <div className="grid grid-cols-2 gap-10 text-[11px] font-bold uppercase">
                   <div className="space-y-6">
                      <div><p className="text-slate-400 text-[9px] font-black mb-1">Beneficiario Titular</p><p className="text-slate-900 text-xl font-[950]">{emp?.surname} {emp?.name}</p><p className="text-slate-500 font-black">CI: {emp?.identification}</p></div>
                      <div><p className="text-slate-400 text-[9px] font-black mb-1">Motivo</p><p className="text-slate-900 font-black">{selectedPayForPrint.type} - {selectedPayForPrint.month} {selectedPayForPrint.year}</p><p className="text-slate-500 text-[10px] lowercase italic">{selectedPayForPrint.concept}</p></div>
                   </div>
                   <div className="text-right space-y-6">
                      <div><p className="text-slate-400 text-[9px] font-black mb-1">Monto Pagado</p><p className="text-5xl font-[950] text-slate-900 tracking-tighter">${selectedPayForPrint.amount.toFixed(2)}</p></div>
                      <div><p className="text-slate-400 text-[9px] font-black mb-1">Fecha</p><p className="text-slate-900 font-black">{new Date(selectedPayForPrint.date).toLocaleString()}</p></div>
                   </div>
                </div>
                <div className="bg-slate-50 p-10 rounded-[3rem] border-2 border-dashed border-slate-300 grid grid-cols-2 gap-20 text-center pt-24 pb-10">
                   <div className="border-t-2 border-slate-900 pt-4 text-[10px] font-black uppercase text-slate-900">Firma Colaborador</div>
                   <div className="border-t-2 border-slate-900 pt-4 text-[10px] font-black uppercase text-slate-900">Autorizado Tesorería</div>
                </div>
                <div className="flex gap-4 no-print">
                   <button onClick={() => exportPayExcel(selectedPayForPrint)} className="flex-1 py-5 bg-emerald-600 text-white font-black rounded-3xl uppercase text-[10px] tracking-widest active:scale-95 transition-all">Exportar Excel</button>
                   <button onClick={() => window.print()} className="flex-1 py-5 bg-slate-900 text-white font-black rounded-3xl uppercase text-[10px] tracking-widest active:scale-95 transition-all">Imprimir / PDF</button>
                </div>
             </div>
           );
        })()}
      </Modal>

      <Modal isOpen={isPayOpen} onClose={() => setIsPayOpen(false)} title="Nuevo Desembolso">
        <div className="space-y-4">
          <select className="w-full border-2 p-3 rounded-xl bg-slate-50 text-[11px] font-black uppercase" onChange={e => setPayForm({...payForm, employeeId: e.target.value})}><option value="">Elegir Beneficiario...</option>{employees.filter(e => e.status === 'active').map(e => <option key={e.id} value={e.id}>{e.surname} {e.name}</option>)}</select>
          <div className="grid grid-cols-2 gap-4">
            <select className="w-full border-2 p-3 rounded-xl bg-slate-50 text-[11px] font-black uppercase" value={payForm.type} onChange={e => setPayForm({...payForm, type: e.target.value as any})}><option value="Salary">Sueldo</option><option value="ExtraHours">Horas Extras</option><option value="Bonus">Bono</option><option value="Loan">Préstamo</option><option value="Emergency">Emergencia</option></select>
            <select className="w-full border-2 p-3 rounded-xl bg-slate-50 text-[11px] font-black uppercase" value={payForm.month} onChange={e => setPayForm({...payForm, month: e.target.value})}>{['ENERO','FEBRERO','MARZO','ABRIL','MAYO','JUNIO','JULIO','AGOSTO','SEPTIEMBRE','OCTUBRE','NOVIEMBRE','DICIEMBRE'].map(m => <option key={m} value={m}>{m}</option>)}</select>
          </div>
          <input type="number" step="0.01" className="w-full border-2 p-5 rounded-2xl font-[950] text-4xl text-center focus:border-blue-600 outline-none" placeholder="0.00" onChange={e => setPayForm({...payForm, amount: Number(e.target.value)})} />
          <textarea className="w-full border-2 p-3 rounded-xl h-24 text-xs font-bold" placeholder="Observaciones del pago..." onChange={e => setPayForm({...payForm, concept: e.target.value})}></textarea>
          <button onClick={handleCreate} className="w-full py-5 bg-emerald-600 text-white font-[950] rounded-[2rem] uppercase text-[11px] tracking-widest shadow-2xl active:scale-95 transition-all">Confirmar Pago</button>
        </div>
      </Modal>

      <Modal isOpen={feedback.isOpen} onClose={() => setFeedback({...feedback, isOpen: false})} title={feedback.title} type={feedback.type}><div className="text-center p-4"><p className="text-xs font-bold uppercase">{feedback.message}</p><button onClick={() => setFeedback({...feedback, isOpen: false})} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] mt-4">Cerrar</button></div></Modal>
    </div>
  );
};

