                  <div><label className="text-[9px] font-black text-slate-400 uppercase">Identificación/CI*</label><input maxLength={10} className="w-full border-2 p-3 rounded-xl text-xs font-black" value={form.identification} onChange={e => setForm({...form, identification: e.target.value.replace(/\D/g,'')})} /></div>
