                  <div><label className="text-[9px] font-black text-slate-400 uppercase">Nombres*</label><input className="w-full border-2 p-3 rounded-xl text-xs font-black uppercase" value={form.name} onChange={e => setForm({...form, name: e.target.value.toUpperCase()})} /></div>
                  <div><label className="text-[9px] font-black text-slate-400 uppercase">Apellidos*</label><input className="w-full border-2 p-3 rounded-xl text-xs font-black uppercase" value={form.surname} onChange={e => setForm({...form, surname: e.target.value.toUpperCase()})} /></div>
                  <div><label className="text-[9px] font-black text-slate-400 uppercase">Identificación/CI*</label><input maxLength={10} className="w-full border-2 p-3 rounded-xl text-xs font-black" value={form.identification} onChange={e => setForm({...form, identification: e.target.value.replace(/\D/g,'')})} /></div>
                  <div><label className="text-[9px] font-black text-slate-400 uppercase">Fecha Nacimiento</label><input type="date" className="w-full border-2 p-3 rounded-xl text-xs font-black" value={form.birthDate} onChange={e => setForm({...form, birthDate: e.target.value})} /></div>
                  <div><label className="text-[9px] font-black text-slate-400 uppercase">Género</label><select className="w-full border-2 p-3 rounded-xl text-xs font-black" value={form.gender} onChange={e => setForm({...form, gender: e.target.value as Gender})}>{Object.values(Gender).map(g => <option key={g} value={g}>{g}</option>)}</select></div>
                  <div><label className="text-[9px] font-black text-slate-400 uppercase">Estado Civil</label><select className="w-full border-2 p-3 rounded-xl text-xs font-black" value={form.civilStatus} onChange={e => setForm({...form, civilStatus: e.target.value as CivilStatus})}>{Object.values(CivilStatus).map(s => <option key={s} value={s}>{s}</option>)}</select></div>
                  <div><label className="text-[9px] font-black text-slate-400 uppercase">Nacionalidad</label><input className="w-full border-2 p-3 rounded-xl text-xs font-black uppercase" value={form.origin} onChange={e => setForm({...form, origin: e.target.value.toUpperCase()})} /></div>
