    { id: 'employees', label: 'Talento Humano', icon: 'M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z', roles: [Role.SUPER_ADMIN, Role.PARTIAL_ADMIN] },
