import React, { useState, useMemo, useEffect } from 'react';
import { Role, CompanyConfig, Employee, AttendanceRecord, Payment, GlobalSettings, NotificationMessage } from '../types.ts';
import Sidebar from '../components/Sidebar.tsx';
import CompanyModule from './modules/CompanyModule.tsx';
import EmployeeModule from './modules/EmployeeModule.tsx';
import PayrollModule from './modules/PayrollModule.tsx';
import PaymentsModule from './modules/PaymentsModule.tsx';
import SettingsModule from './modules/SettingsModule.tsx';
import ReportsModule from './modules/ReportsModule.tsx';
import AiAssistant from './modules/AiAssistant.tsx';
import NotificationsModule from './modules/NotificationsModule.tsx';
import Modal from '../components/Modal.tsx';
import { DAILY_QUOTES, ACTIVE_BREAKS } from '../constants.tsx';

interface AdminDashboardProps {
  role: Role;
  isDbConnected?: boolean;
  onLogout: () => void;
  company: CompanyConfig | null;
  onUpdateCompany: (config: CompanyConfig) => void;
  employees: Employee[];
  onUpdateEmployees: (employees: Employee[]) => void;
  attendance: AttendanceRecord[];
  payments: Payment[];
  onUpdatePayments: (payments: Payment[]) => void;
  settings: GlobalSettings;
  onUpdateSettings: (settings: GlobalSettings) => void;
  onUpdateAppMode: (mode: 'full' | 'attendance') => void;
  appMode: 'full' | 'attendance';
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  role, isDbConnected, onLogout, company, onUpdateCompany, employees, onUpdateEmployees, attendance, payments, onUpdatePayments, settings, onUpdateSettings, onUpdateAppMode, appMode 
}) => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'company' | 'employees' | 'payroll' | 'payments' | 'settings' | 'reports' | 'ai' | 'notifications'>('dashboard');
  const [showInstallModal, setShowInstallModal] = useState(false);
  const [notifications, setNotifications] = useState<NotificationMessage[]>([]);

  const todayDateStr = useMemo(() => new Date().toISOString().split('T')[0], []);
  const today = useMemo(() => new Date(), []);

  const addNotification = (title: string, message: string, type: 'info' | 'alert' | 'critical') => {
    const id = Math.random().toString(36).substr(2, 9);
    setNotifications(prev => {
      if (prev.some(n => n.title === title && n.message === message && !n.isRead && !n.isProcessed)) return prev;
      return [{ id, title, message, timestamp: new Date().toISOString(), type, isRead: false, isProcessed: false }, ...prev];
    });
  };

  // Lógica para detectar eventos que generan notificaciones
  useEffect(() => {
    const activeEmployees = employees.filter(e => e.status === 'active');
    const markedTodayIds = new Set(attendance
      .filter(a => a.timestamp.includes(todayDateStr))
      .map(a => a.employeeId));

    // Alerta de ausencias
    const missingAttendanceCount = activeEmployees.filter(e => !markedTodayIds.has(e.id)).length;
    if (missingAttendanceCount > 0) {
      addNotification(
        "Pendiente de Ingreso", 
        `Hay ${missingAttendanceCount} colaboradores que aún no han registrado su marcación hoy.`, 
        'alert'
      );
    }

    // Alerta de atrasos críticos
    const todayLates = attendance.filter(a => a.timestamp.includes(todayDateStr) && a.isLate);
    if (todayLates.length > 0) {
      todayLates.forEach(late => {
        const emp = employees.find(e => e.id === late.employeeId);
        addNotification(
          "Retraso Crítico", 
          `El colaborador ${emp?.surname} marcó con más de 15 minutos de retraso.`, 
          'critical'
        );
      });
    }

    // Alerta de reseteo de PIN
    const pinResets = employees.filter(e => e.pinNeedsReset);
    if (pinResets.length > 0) {
      pinResets.forEach(emp => {
        addNotification(
          "Acceso Bloqueado", 
          `El colaborador ${emp.name} ${emp.surname} solicita un nuevo PIN de acceso.`, 
          'critical'
        );
      });
    }
  }, [employees, attendance, todayDateStr]);

  const unreadCount = notifications.filter(n => !n.isRead).length;

  const dayOfYear = useMemo(() => {
    const start = new Date(today.getFullYear(), 0, 0);
    const diff = today.getTime() - start.getTime();
    return Math.floor(diff / (1000 * 60 * 60 * 24));
  }, [today]);

  const birthdayPeeps = useMemo(() => {
    return employees.filter(e => {
      if (!e.birthDate || e.status !== 'active') return false;
      const b = new Date(e.birthDate);
      return b.getMonth() === today.getMonth() && b.getDate() === today.getDate();
    });
  }, [employees, today]);

  const dailyQuote = DAILY_QUOTES[dayOfYear % DAILY_QUOTES.length];
  const activeBreak = ACTIVE_BREAKS[dayOfYear % ACTIVE_BREAKS.length];

  const handlePurgeData = async () => {
    if (role !== Role.SUPER_ADMIN) return;
    onUpdateEmployees([]);
    onUpdatePayments([]);
  };

  const allAppData = {
    company,
    employees,
    attendance,
    payments,
    settings,
    exportDate: new Date().toISOString()
  };

  return (
    <div className="flex h-screen bg-[#fcfdfe] overflow-hidden flex-col md:flex-row">
      <Sidebar 
        role={role} 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        onLogout={onLogout} 
        companyName={company?.name} 
        unreadCount={unreadCount}
      />

      <main className="flex-1 overflow-y-auto px-6 py-8 md:px-10 md:py-10 scroll-smooth custom-scroll">
        <header className="flex flex-col md:flex-row justify-between items-start md:items-center mb-10 gap-6 no-print pt-10 md:pt-0">
          <div className="flex items-center gap-4">
            <h1 className="text-xl md:text-2xl font-[950] text-slate-900 tracking-tight uppercase">Dashboard Corporativo</h1>
            <div className="flex items-center gap-3 px-4 py-2 bg-white border rounded-2xl shadow-sm">
               <div className={`w-3 h-3 rounded-full ${isDbConnected ? 'bg-emerald-500 shadow-[0_0_12px_#10b981]' : 'bg-red-500 animate-pulse'}`}></div>
               <span className="text-[9px] font-black uppercase tracking-[0.2em] text-slate-500">
                 {isDbConnected ? 'Conectado' : 'Sin Red'}
               </span>
            </div>
          </div>
          <div className="flex gap-3">
             <button onClick={() => setActiveTab('ai')} className="px-4 py-2 bg-blue-50 text-blue-700 rounded-xl text-[9px] font-black uppercase border border-blue-100 flex items-center gap-2 hover:bg-blue-100 transition-all">
               <span className="animate-pulse">✨</span> IA Assistant
             </button>
             {role === Role.SUPER_ADMIN && (
               <button onClick={() => setShowInstallModal(true)} className="px-4 py-2 bg-slate-900 text-white rounded-xl text-[9px] font-black uppercase border border-slate-900 shadow-xl active:scale-95 transition-all">Estación Kiosco</button>
             )}
          </div>
        </header>

        <div className="animate-in fade-in duration-500">
          {activeTab === 'dashboard' && (
            <div className="space-y-12">
              {birthdayPeeps.length > 0 && role === Role.SUPER_ADMIN && (
                <div className="bg-emerald-600 p-8 rounded-[3rem] text-white shadow-[0_20px_50px_rgba(16,185,129,0.2)] flex flex-col md:flex-row items-center justify-between gap-6 animate-pulse">
                   <div className="flex items-center gap-6">
                      <span className="text-5xl">🎂</span>
                      <div>
                         <h3 className="text-xl font-black uppercase tracking-tighter">¡Hoy hay Cumpleaños!</h3>
                         <p className="text-[10px] font-bold uppercase tracking-widest opacity-80 mt-1">Recuérdales lo valiosos que son para el equipo</p>
                      </div>
                   </div>
                   <div className="flex -space-x-4">
                      {birthdayPeeps.map(e => (
                         <div key={e.id} className="w-12 h-12 rounded-full border-4 border-emerald-600 bg-white overflow-hidden" title={e.name}>
                            {e.photo ? <img src={e.photo} className="w-full h-full object-cover" /> : <div className="flex items-center justify-center h-full text-[10px] text-emerald-600 font-black">{e.name[0]}</div>}
                         </div>
                      ))}
                   </div>
                </div>
              )}

              <div className="relative overflow-hidden bg-slate-900 rounded-[3rem] p-12 text-white shadow-2xl min-h-[300px] flex flex-col justify-center bg-cover bg-center" style={{ backgroundImage: 'linear-gradient(rgba(15, 23, 42, 0.8), rgba(15, 23, 42, 0.8)), url(https://images.unsplash.com/photo-1499750310107-5fef28a66643?auto=format&fit=crop&q=80&w=2070)' }}>
                  <div className="relative z-10 max-w-2xl">
                    <p className="text-blue-400 font-black text-[10px] uppercase tracking-[0.5em] mb-4">Reflexión Estratégica</p>
                    <h2 className="text-3xl md:text-5xl font-[900] leading-tight tracking-tighter italic">"{dailyQuote}"</h2>
                  </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8 items-stretch">
                <div className="bg-white p-10 rounded-[3rem] shadow-sm border border-slate-100 space-y-6">
                  <div className="flex items-center gap-4">
                    <span className="text-5xl">{activeBreak.icon}</span>
                    <div>
                      <h3 className="text-xl font-black text-slate-900 uppercase">Pausa Saludable</h3>
                      <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest">Bienestar Laboral</p>
                    </div>
                  </div>
                  <div className="space-y-4">
                    <h4 className="text-lg font-extrabold text-slate-800">{activeBreak.title}</h4>
                    <p className="text-slate-500 leading-relaxed font-medium">{activeBreak.description}</p>
                  </div>
                </div>

                <div className="relative overflow-hidden bg-white rounded-[3rem] shadow-sm border border-slate-100 h-full">
                   <img 
                     src="https://images.unsplash.com/photo-1470770841072-f978cf4d019e?auto=format&fit=crop&q=80&w=2070" 
                     alt="Paisaje Relajante" 
                     className="w-full h-full object-cover transition-transform duration-700 hover:scale-105"
                   />
                   <div className="absolute bottom-6 left-6 right-6">
                      <p className="text-[8px] font-black text-white/50 uppercase tracking-[0.3em]">Ambiente de Paz</p>
                   </div>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'notifications' && (
            <NotificationsModule 
              notifications={notifications} 
              onToggleRead={(id) => setNotifications(prev => prev.map(n => n.id === id ? { ...n, isRead: !n.isRead } : n))}
              onToggleProcessed={(id) => setNotifications(prev => prev.map(n => n.id === id ? { ...n, isProcessed: !n.isProcessed } : n))}
              onClearAll={() => setNotifications([])}
            />
          )}

          {activeTab === 'company' && <CompanyModule company={company} onUpdate={onUpdateCompany} role={role} />}
          {activeTab === 'employees' && <EmployeeModule employees={employees} onUpdate={onUpdateEmployees} role={role} attendance={attendance} payments={payments} company={company} />}
          {activeTab === 'payroll' && <PayrollModule employees={employees} payments={payments} company={company} settings={settings} role={role} />}
          {activeTab === 'payments' && <PaymentsModule employees={employees} payments={payments} onUpdate={onUpdatePayments} role={role} />}
          {activeTab === 'settings' && <SettingsModule settings={settings} onUpdate={onUpdateSettings} role={role} onPurge={handlePurgeData} allData={allAppData} />}
          {activeTab === 'reports' && <ReportsModule employees={employees} payments={payments} attendance={attendance} company={company} settings={settings} role={role} />}
          {activeTab === 'ai' && <AiAssistant employees={employees} attendance={attendance} payments={payments} role={role} />}
        </div>
      </main>

      <Modal isOpen={showInstallModal} onClose={() => setShowInstallModal(false)} title="Modo de Estación" maxWidth="max-w-md">
         <div className="space-y-6">
            <p className="text-[11px] text-slate-500 text-center font-bold uppercase tracking-widest">Seleccione la interfaz para este dispositivo:</p>
            <div className="space-y-3">
               <button onClick={() => { onUpdateAppMode('full'); setShowInstallModal(false); }} className={`w-full p-6 rounded-2xl border-2 text-left flex items-center justify-between transition-all ${appMode === 'full' ? 'border-blue-600 bg-blue-50' : 'border-slate-100'}`}>
                  <div>
                    <p className="font-black text-sm text-slate-900 uppercase">Administrativa Full</p>
                    <p className="text-[10px] text-slate-400 font-bold uppercase mt-1">Acceso total a gestión.</p>
                  </div>
               </button>
               <button onClick={() => { onUpdateAppMode('attendance'); setShowInstallModal(false); }} className={`w-full p-6 rounded-2xl border-2 text-left flex items-center justify-between transition-all ${appMode === 'attendance' ? 'border-blue-600 bg-blue-50' : 'border-slate-100'}`}>
                  <div>
                    <p className="font-black text-sm text-slate-900 uppercase">Marcación Only</p>
                    <p className="text-[10px] text-slate-400 font-bold uppercase mt-1">Kiosco de asistencia.</p>
                  </div>
               </button>
            </div>
         </div>
      </Modal>
    </div>
  );
};

export default AdminDashboard;

import React from 'react';
import { NotificationMessage } from '../../types.ts';

interface NotificationsModuleProps {
  notifications: NotificationMessage[];
  onToggleRead: (id: string) => void;
  onToggleProcessed: (id: string) => void;
  onClearAll: () => void;
}

const NotificationsModule: React.FC<NotificationsModuleProps> = ({ notifications, onToggleRead, onToggleProcessed, onClearAll }) => {
  const sorted = [...notifications].sort((a, b) => b.timestamp.localeCompare(a.timestamp));

  return (
    <div className="max-w-4xl mx-auto fade-in pb-20">
      <div className="flex justify-between items-center mb-8 bg-white p-6 rounded-[2rem] shadow-sm border border-slate-100">
        <div>
          <h2 className="text-xl font-[950] text-slate-900 tracking-tighter uppercase leading-none">Buzón de Notificaciones</h2>
          <p className="text-[9px] font-black text-blue-600 uppercase tracking-widest mt-2">Alertas y Eventos del Sistema</p>
        </div>
        <button 
          onClick={onClearAll}
          className="px-4 py-2 bg-slate-100 text-slate-500 rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-red-50 hover:text-red-600 transition-all"
        >
          Limpiar Todo
        </button>
      </div>

      {sorted.length === 0 ? (
        <div className="bg-white p-20 rounded-[3rem] border-2 border-dashed border-slate-100 text-center">
          <span className="text-5xl opacity-20">📥</span>
          <p className="text-slate-400 font-black uppercase text-[10px] tracking-widest mt-6">No hay notificaciones recientes</p>
        </div>
      ) : (
        <div className="space-y-4">
          {sorted.map(notif => (
            <div 
              key={notif.id} 
              className={`p-6 rounded-[2.5rem] border transition-all flex flex-col gap-4 ${
                notif.isRead ? 'bg-white border-slate-100 opacity-70' : 'bg-white border-blue-200 shadow-md scale-[1.01]'
              } ${notif.isProcessed ? 'border-emerald-200 bg-emerald-50/20' : ''}`}
            >
              <div className="flex items-start gap-5">
                <div className={`w-3 h-3 rounded-full mt-2 shrink-0 ${
                  notif.type === 'critical' ? 'bg-red-500 shadow-[0_0_10px_red]' : 
                  notif.type === 'alert' ? 'bg-yellow-500 shadow-[0_0_10px_yellow]' : 
                  'bg-blue-500'
                }`}></div>
                <div className="flex-1">
                  <div className="flex justify-between items-start mb-1">
                    <div className="flex items-center gap-3">
                      <h4 className="font-black text-slate-900 text-sm uppercase tracking-tight">{notif.title}</h4>
                      {notif.isProcessed && (
                        <span className="px-2 py-0.5 bg-emerald-500 text-white text-[7px] font-black uppercase rounded-full">Completado</span>
                      )}
                    </div>
                    <span className="text-[8px] font-black text-slate-400 uppercase">{new Date(notif.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</span>
                  </div>
                  <p className="text-xs text-slate-600 font-medium leading-relaxed">{notif.message}</p>
                  <p className="text-[8px] font-black text-slate-400 uppercase mt-2">{new Date(notif.timestamp).toLocaleDateString()}</p>
                </div>
              </div>

              <div className="flex gap-2 pt-4 border-t border-slate-50">
                <button 
                  onClick={() => onToggleRead(notif.id)}
                  className={`flex-1 py-2 rounded-xl text-[8px] font-black uppercase tracking-widest transition-all ${
                    notif.isRead 
                      ? 'bg-slate-100 text-slate-500' 
                      : 'bg-blue-50 text-blue-600 border border-blue-200'
                  }`}
                >
                  {notif.isRead ? 'Marcar como No Leído' : 'Marcar como Leído'}
                </button>
                <button 
                  onClick={() => onToggleProcessed(notif.id)}
                  className={`flex-1 py-2 rounded-xl text-[8px] font-black uppercase tracking-widest transition-all ${
                    notif.isProcessed 
                      ? 'bg-emerald-600 text-white shadow-lg' 
                      : 'bg-slate-900 text-white'
                  }`}
                >
                  {notif.isProcessed ? 'Marcar como Pendiente' : 'Marcar como Procesado'}
                </button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default NotificationsModule;

import React, { useState, useEffect, useMemo } from 'react';
import { Employee, AttendanceRecord, GlobalSettings } from '../types.ts';
import Clock from '../components/Clock.tsx';
import Modal from '../components/Modal.tsx';

interface AttendanceSystemProps {
  employees: Employee[];
  attendance: AttendanceRecord[];
  onRegister: (record: AttendanceRecord) => void;
  onBack: () => void;
  onUpdateEmployees: (employees: Employee[]) => void;
  settings: GlobalSettings;
}

const AttendanceSystem: React.FC<AttendanceSystemProps> = ({ employees, attendance, onRegister, onBack, onUpdateEmployees, settings }) => {
  const [pin, setPin] = useState('');
  const [status, setStatus] = useState<'idle' | 'confirm' | 'forgotten_form' | 'success' | 'error' | 'change_pin' | 'justification_form'>('idle');
  const [isProcessing, setIsProcessing] = useState(false);
  const [currentEmp, setCurrentEmp] = useState<Employee | null>(null);
  const [pendingMarkData, setPendingMarkData] = useState<{ type: 'in' | 'out' | 'half_day', isLate: boolean } | null>(null);
  const [justificationText, setJustificationText] = useState('');
  const [newPin, setNewPin] = useState('');
  const [forgotCi, setForgotCi] = useState('');
  const [successMsg, setSuccessMsg] = useState('');
  const [feedback, setFeedback] = useState<{isOpen: boolean, title: string, message: string, type: 'success' | 'error' | 'info'}>({
    isOpen: false, title: '', message: '', type: 'success'
  });

  const isWithinRange = (now: Date, startStr: string, endStr: string) => {
    const [sh, sm] = startStr.split(':').map(Number);
    const [eh, em] = endStr.split(':').map(Number);
    const s = new Date(now); s.setHours(sh, sm, 0, 0);
    const e = new Date(now); e.setHours(eh, em, 0, 0);
    return now >= s && now <= e;
  };

  const handleMark = (type: 'in' | 'out' | 'half_day') => {
    if (!currentEmp || isProcessing) return;

    const now = new Date();
    const day = now.getDay();
    let isOffSchedule = false;
    let isCriticalLate = false;

    // Verificar si está dentro de algún bloque horario
    if (day >= 1 && day <= 5) { // Lun-Vie
      const in1 = isWithinRange(now, settings.schedule.monFri.in1, settings.schedule.monFri.out1);
      const in2 = isWithinRange(now, settings.schedule.monFri.in2, settings.schedule.monFri.out2);
      if (!in1 && !in2) isOffSchedule = true;

      // Lógica de atraso crítico para entrada principal
      if (type === 'in') {
        const [schedH, schedM] = settings.schedule.monFri.in1.split(':').map(Number);
        const schedDate = new Date(now);
        schedDate.setHours(schedH, schedM, 0, 0);
        const diffMins = (now.getTime() - schedDate.getTime()) / (1000 * 60);
        if (diffMins > 15) isCriticalLate = true;
      }
    } else if (day === 6) { // Sáb
      if (!isWithinRange(now, settings.schedule.sat.in, settings.schedule.sat.out)) isOffSchedule = true;
    } else {
      isOffSchedule = true; // Dom
    }

    if (isOffSchedule || isCriticalLate) {
      setPendingMarkData({ type, isLate: isCriticalLate });
      setStatus('justification_form');
      return;
    }

    processRegistration(type, isCriticalLate);
  };

  const processRegistration = (type: 'in' | 'out' | 'half_day', isLate: boolean, justification?: string) => {
    setIsProcessing(true);

    if (isLate && Notification.permission === "granted") {
      new Notification("ALERTA DE ASISTENCIA", {
        body: `El colaborador ${currentEmp?.name} ${currentEmp?.surname} ha marcado con más de 15 minutos de retraso.`,
        icon: "https://cdn-icons-png.flaticon.com/512/3844/3844724.png"
      });
    }

    const record: AttendanceRecord = {
      id: Math.random().toString(36).substr(2, 9),
      employeeId: currentEmp!.id,
      timestamp: new Date().toISOString(),
      type,
      status: 'confirmed',
      isLate,
      justification
    };

    onRegister(record);

    if (type === 'in') setSuccessMsg("INGRESO REGISTRADO CON ÉXITO");
    else if (type === 'out') setSuccessMsg("SALIDA REGISTRADA CON ÉXITO");
    else setSuccessMsg("MARCACIÓN REGISTRADA CON ÉXITO");

    setStatus('success');
    setPin('');
    setJustificationText('');
    setPendingMarkData(null);

    setTimeout(() => {
      setStatus('idle');
      setCurrentEmp(null);
      setIsProcessing(false);
    }, 4000);
  };

  const handleConfirmJustification = () => {
    if (!justificationText.trim()) {
      setFeedback({ isOpen: true, title: "Requerido", message: "Debe ingresar un motivo para continuar.", type: "error" });
      return;
    }
    if (pendingMarkData) {
      processRegistration(pendingMarkData.type, pendingMarkData.isLate, justificationText);
    }
  };

  const handlePinChange = () => {
    if (newPin.length !== 6 || newPin === currentEmp?.pin) {
      setFeedback({ isOpen: true, title: "Error de PIN", message: "Ingrese un PIN nuevo de 6 dígitos diferente al actual.", type: "error" });
      return;
    }

    const updated = employees.map(e => e.id === currentEmp?.id ? {
      ...e,
      pin: newPin,
      pinChanged: true,
      pinNeedsReset: false
    } : e);

    onUpdateEmployees(updated);

    setFeedback({ isOpen: true, title: "PIN Actualizado", message: "Su clave de acceso ha sido cambiada. Ahora puede marcar su asistencia.", type: "success" });
    setStatus('confirm');
    setNewPin('');
  };

  const handleRequestPinReset = () => {
    const emp = employees.find(e => e.identification === forgotCi && e.status === 'active');
    if (emp) {
      const updated = employees.map(e => e.id === emp.id ? { ...e, pinNeedsReset: true } : e);
      onUpdateEmployees(updated);

      if (Notification.permission === "granted") {
        new Notification("SOLICITUD DE ACCESO", {
          body: `El colaborador ${emp.name} solicita resetear su PIN de asistencia.`,
          icon: "https://cdn-icons-png.flaticon.com/512/3844/3844724.png"
        });
      }

      setFeedback({ 
        isOpen: true, 
        title: "Solicitud Recibida", 
        message: "Su solicitud ha sido enviada al administrador. RRHH autorizará su nuevo acceso a la brevedad.", 
        type: "info" 
      });
      setStatus('idle');
      setForgotCi('');
    } else {
      setFeedback({ 
        isOpen: true, 
        title: "Error", 
        message: "Identificación no encontrada en el sistema.", 
        type: "error" 
      });
    }
  };

  useEffect(() => {
    if (pin.length === 6 && status === 'idle' && !isProcessing) {
      const emp = employees.find(e => e.pin === pin && e.status === 'active');
      if (emp) {
        setCurrentEmp(emp);
        if (!emp.pinChanged || emp.pinNeedsReset) {
          setStatus('change_pin');
        } else {
          setStatus('confirm');
        }
      } else {
        setStatus('error');
        setTimeout(() => { setStatus('idle'); setPin(''); }, 1500);
      }
    }
  }, [pin, employees, status, isProcessing]);

  useEffect(() => {
    const handleKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onBack();
      if (status !== 'idle' || isProcessing) return;
      if (e.key >= '0' && e.key <= '9' && pin.length < 6) setPin(p => p + e.key);
      if (e.key === 'Backspace') setPin(p => p.slice(0, -1));
    };
    window.addEventListener('keydown', handleKey);
    return () => window.removeEventListener('keydown', handleKey);
  }, [pin, status, isProcessing]);

  return (
    <div className="min-h-screen gradient-blue flex flex-col items-center justify-center p-4">
      {status === 'success' && (
        <div className="fixed inset-0 z-[100] bg-slate-900/95 backdrop-blur-3xl flex flex-col items-center justify-center fade-in text-center p-8">
           <div className="w-24 h-24 bg-emerald-500 text-white rounded-[2.5rem] flex items-center justify-center text-5xl mb-10 shadow-[0_0_50px_rgba(16,185,129,0.4)] animate-bounce">✓</div>
           <p className="text-white font-[950] text-4xl uppercase tracking-tighter text-center max-w-2xl leading-tight">{successMsg}</p>
        </div>
      )}

      <div className={`w-full max-w-lg bg-white/95 backdrop-blur-3xl rounded-[3.5rem] shadow-2xl p-6 md:p-12 flex flex-col items-center relative overflow-hidden ${status === 'success' ? 'opacity-0' : 'fade-in'}`}>
        <div className="mb-8 transform scale-[0.6] md:scale-[0.8]"><Clock /></div>

        {status === 'idle' && (
          <div className="w-full text-center">
            <h2 className="text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] mb-6">Ingresar PIN de 6 dígitos</h2>
            <div className="flex gap-2 justify-center mb-10">
              {[...Array(6)].map((_, i) => (
                <div key={i} className={`w-10 h-16 border-b-4 flex items-center justify-center text-4xl font-black transition-all ${pin.length > i ? 'border-blue-600 text-slate-900' : 'border-slate-100'}`}>
                  {pin[i] ? '•' : ''}
                </div>
              ))}
            </div>
            <div className="grid grid-cols-3 gap-3 max-w-[340px] mx-auto mb-10">
              {[1, 2, 3, 4, 5, 6, 7, 8, 9, 'C', 0, '←'].map(btn => (
                <button 
                  key={btn} 
                  onClick={() => {
                    if (btn === 'C') setPin('');
                    else if (btn === '←') setPin(p => p.slice(0, -1));
                    else if (pin.length < 6) setPin(p => p + btn);
                  }} 
                  className="h-16 md:h-18 bg-white hover:bg-blue-700 hover:text-white rounded-2xl text-2xl font-black border border-slate-200 active:scale-90 transition-all shadow-sm flex items-center justify-center"
                >
                  {btn}
                </button>
              ))}
            </div>

            <button 
              onClick={() => setStatus('forgotten_form')}
              className="w-full py-4 bg-slate-50 border border-slate-100 rounded-2xl text-[10px] font-black text-blue-600 uppercase tracking-widest hover:bg-blue-50 transition-all"
            >
              ¿Olvidó su PIN? Solicitar Reseteo
            </button>
          </div>
        )}

        {status === 'justification_form' && (
          <div className="text-center w-full space-y-6 animate-in zoom-in">
             <div className="w-20 h-20 bg-blue-50 text-blue-600 rounded-3xl flex items-center justify-center text-3xl mx-auto mb-4 border border-blue-100 shadow-inner">📝</div>
             <h2 className="text-2xl font-[950] text-slate-900 uppercase tracking-tighter">Justificación Requerida</h2>
             <p className="text-[10px] text-slate-500 font-black uppercase tracking-widest leading-relaxed">Su marcación se encuentra fuera del horario laboral o presenta un retraso crítico.</p>
             <textarea 
               value={justificationText}
               onChange={e => setJustificationText(e.target.value)}
               className="w-full border-2 p-5 rounded-2xl text-xs font-black uppercase focus:border-blue-600 outline-none bg-slate-50 min-h-[120px]" 
               placeholder="Escriba el motivo detallado..." 
               autoFocus 
             />
             <div className="grid grid-cols-2 gap-3">
                <button onClick={() => setStatus('confirm')} className="w-full py-4 bg-slate-100 text-slate-600 font-black rounded-2xl uppercase text-[10px] tracking-widest active:scale-95 transition-all">Cancelar</button>
                <button onClick={handleConfirmJustification} className="w-full py-4 bg-blue-700 text-white font-black rounded-2xl uppercase text-[10px] tracking-widest shadow-xl active:scale-95 transition-all">Confirmar Marcación</button>
             </div>
          </div>
        )}

        {status === 'forgotten_form' && (
          <div className="text-center w-full space-y-6 animate-in zoom-in">
            <h2 className="text-2xl font-[950] text-slate-900 uppercase tracking-tighter">Solicitar Nuevo PIN</h2>
            <p className="text-xs text-slate-500 font-bold uppercase tracking-widest leading-relaxed">Ingrese su Cédula / Identificación para validar su identidad</p>
            <input 
              maxLength={10} 
              type="text" 
              inputMode="numeric"
              value={forgotCi} 
              onChange={e => setForgotCi(e.target.value.replace(/\D/g,''))} 
              className="w-full border-2 p-5 rounded-2xl text-center text-3xl font-black focus:border-blue-600 outline-none bg-slate-50" 
              placeholder="0000000000" 
              autoFocus 
            />
            <div className="grid grid-cols-2 gap-3">
              <button onClick={() => setStatus('idle')} className="w-full py-4 bg-slate-100 text-slate-600 font-black rounded-2xl uppercase text-[10px] tracking-widest active:scale-95 transition-all">Cancelar</button>
              <button onClick={handleRequestPinReset} className="w-full py-4 bg-blue-700 text-white font-black rounded-2xl uppercase text-[10px] tracking-widest shadow-xl active:scale-95 transition-all">Enviar</button>
            </div>
          </div>
        )}

        {status === 'change_pin' && currentEmp && (
          <div className="text-center w-full space-y-6">
            <h2 className="text-2xl font-[950] text-slate-900 uppercase">Seguridad Obligatoria</h2>
            <p className="text-xs text-slate-500 font-bold uppercase tracking-widest">Asigne su nuevo PIN personal de 6 dígitos</p>
            <input 
              maxLength={6} 
              type="password" 
              inputMode="numeric"
              value={newPin} 
              onChange={e => setNewPin(e.target.value.replace(/\D/g,''))} 
              className="w-full border-2 p-5 rounded-2xl text-center text-4xl font-black focus:border-blue-600 outline-none bg-slate-50" 
              placeholder="••••••" 
              autoFocus 
            />
            <button onClick={handlePinChange} className="w-full py-5 bg-blue-700 text-white font-black rounded-[2rem] uppercase text-[11px] tracking-widest shadow-2xl active:scale-95 transition-all">Establecer Nuevo PIN</button>
          </div>
        )}

        {status === 'confirm' && currentEmp && (
          <div className="text-center w-full animate-in zoom-in">
            <div className="w-28 h-28 bg-slate-100 rounded-[2.5rem] mx-auto flex items-center justify-center text-4xl font-black text-blue-700 uppercase border-4 border-white shadow-xl mb-6 overflow-hidden">
                 {currentEmp.photo ? <img src={currentEmp.photo} className="w-full h-full object-cover" /> : <span>{currentEmp.name[0]}</span>}
            </div>
            <h2 className="text-3xl font-[950] text-slate-900 mb-1 uppercase tracking-tighter leading-none">{currentEmp.name} {currentEmp.surname}</h2>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em] mb-10">{currentEmp.role}</p>
            <div className="grid grid-cols-1 gap-4">
              <button onClick={() => handleMark('in')} className="py-8 bg-blue-700 text-white rounded-[2rem] font-black text-xl uppercase shadow-2xl active:scale-95 transition-all border-b-4 border-blue-900">Registrar Ingreso</button>
              <button onClick={() => handleMark('out')} className="py-8 bg-slate-900 text-white rounded-[2rem] font-black text-xl uppercase shadow-2xl active:scale-95 transition-all border-b-4 border-black">Registrar Salida</button>
            </div>
          </div>
        )}

        {status === 'error' && (
          <div className="text-center text-red-600 py-10 animate-pulse">
            <div className="text-7xl mb-4">✕</div>
            <h2 className="text-2xl font-[950] uppercase tracking-tighter">Acceso Denegado</h2>
            <p className="text-[10px] font-bold uppercase mt-2">PIN Incorrecto</p>
          </div>
        )}
      </div>

      <button onClick={onBack} className="mt-10 text-white/30 hover:text-white font-black text-[11px] uppercase tracking-[0.6em] p-4 transition-all">Salir del Terminal</button>

      <Modal isOpen={feedback.isOpen} onClose={() => setFeedback({...feedback, isOpen: false})} title={feedback.title} type={feedback.type}>
          <div className="text-center space-y-6">
              <p className="text-slate-600 font-bold uppercase text-[12px] leading-relaxed">{feedback.message}</p>
              <button onClick={() => setFeedback({...feedback, isOpen: false})} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] tracking-widest active:scale-95">Entendido</button>
          </div>
      </Modal>
    </div>
  );
};

