                className="w-full flex items-center gap-4 px-6 py-4 bg-blue-600/20 text-blue-400 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-blue-600 hover:text-white transition-all border border-blue-500/30"
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1m-4-4l-4 4m0 0l-4-4m4 4V4"></path></svg>
                <span>Instalar Aplicación</span>
              </button>
            </div>
          )}
        </div>

        <div className="p-10 border-t border-white/5">
          <button 
            onClick={onLogout}
            className="w-full py-5 bg-red-500/10 text-red-400 hover:bg-red-600 hover:text-white rounded-[1.5rem] transition-all font-black border border-red-500/30 uppercase text-[11px] tracking-widest"
          >
            Cerrar Sesión
          </button>
        </div>
      </aside>

      <Modal isOpen={showModeSelection} onClose={() => setShowModeSelection(false)} title="Configuración de Instalación" maxWidth="max-w-sm">
         <div className="space-y-6">
            <p className="text-[10px] text-slate-500 font-black text-center uppercase tracking-widest leading-relaxed">Solo el Administrador puede instalar el sistema en este equipo móvil.</p>
            <div className="space-y-2">
               <button onClick={() => handleInstallProcess('full')} className="w-full py-5 bg-blue-700 text-white font-black rounded-2xl uppercase text-[10px] tracking-widest shadow-xl">Sistema Administrativo</button>
               <button onClick={() => handleInstallProcess('attendance')} className="w-full py-5 bg-slate-900 text-white font-black rounded-2xl uppercase text-[10px] tracking-widest">Kiosco de Asistencia</button>
            </div>
         </div>
      </Modal>

      {isOpen && <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md z-30 md:hidden" onClick={() => setIsOpen(false)}></div>}
    </>
  );
};

export default Sidebar;

import React, { useState, useMemo, useEffect } from 'react';
import { Role, CompanyConfig, Employee, AttendanceRecord, Payment, GlobalSettings, NotificationMessage } from '../types.ts';
import Sidebar from '../components/Sidebar.tsx';
import CompanyModule from './modules/CompanyModule.tsx';
import EmployeeModule from './modules/EmployeeModule.tsx';
import PayrollModule from './modules/PayrollModule.tsx';
import PaymentsModule from './modules/PaymentsModule.tsx';
import SettingsModule from './modules/SettingsModule.tsx';
import ReportsModule from './modules/ReportsModule.tsx';
import AiAssistant from './modules/AiAssistant.tsx';
import NotificationsModule from './modules/NotificationsModule.tsx';
import Modal from '../components/Modal.tsx';
import { DAILY_QUOTES, ACTIVE_BREAKS } from '../constants.tsx';

interface AdminDashboardProps {
  role: Role;
  isDbConnected?: boolean;
  onLogout: () => void;
  company: CompanyConfig | null;
  onUpdateCompany: (config: CompanyConfig) => void;
  employees: Employee[];
  onUpdateEmployees: (employees: Employee[]) => void;
  attendance: AttendanceRecord[];
  payments: Payment[];
  onUpdatePayments: (payments: Payment[]) => void;
  settings: GlobalSettings;
  onUpdateSettings: (settings: GlobalSettings) => void;
  onUpdateAppMode: (mode: 'full' | 'attendance') => void;
  appMode: 'full' | 'attendance';
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  role, isDbConnected, onLogout, company, onUpdateCompany, employees, onUpdateEmployees, attendance, payments, onUpdatePayments, settings, onUpdateSettings, onUpdateAppMode, appMode 
}) => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'company' | 'employees' | 'payroll' | 'payments' | 'settings' | 'reports' | 'ai' | 'notifications'>('dashboard');
  const [showInstallModal, setShowInstallModal] = useState(false);
  const [notifications, setNotifications] = useState<NotificationMessage[]>([]);

  const todayDateStr = useMemo(() => new Date().toISOString().split('T')[0], []);
  const today = useMemo(() => new Date(), []);

  const addNotification = (title: string, message: string, type: 'info' | 'alert' | 'critical') => {
    const id = Math.random().toString(36).substr(2, 9);
    setNotifications(prev => {
      if (prev.some(n => n.title === title && n.message === message && !n.isRead && !n.isProcessed)) return prev;
      return [{ id, title, message, timestamp: new Date().toISOString(), type, isRead: false, isProcessed: false }, ...prev];
    });
  };

  // Lógica para detectar eventos que generan notificaciones
  useEffect(() => {
    const activeEmployees = employees.filter(e => e.status === 'active');
    const markedTodayIds = new Set(attendance
      .filter(a => a.timestamp.includes(todayDateStr))
      .map(a => a.employeeId));

    // Alerta de ausencias
    const missingAttendanceCount = activeEmployees.filter(e => !markedTodayIds.has(e.id)).length;
    if (missingAttendanceCount > 0) {
      addNotification(
        "Pendiente de Ingreso", 
        `Hay ${missingAttendanceCount} colaboradores que aún no han registrado su marcación hoy.`, 
        'alert'
      );
    }

    // Alerta de atrasos críticos
    const todayLates = attendance.filter(a => a.timestamp.includes(todayDateStr) && a.isLate);
    if (todayLates.length > 0) {
      todayLates.forEach(late => {
        const emp = employees.find(e => e.id === late.employeeId);
        addNotification(
          "Retraso Crítico", 
          `El colaborador ${emp?.surname} marcó con más de 15 minutos de retraso.`, 
          'critical'
        );
      });
    }

    // Alerta de reseteo de PIN
    const pinResets = employees.filter(e => e.pinNeedsReset);
    if (pinResets.length > 0) {
      pinResets.forEach(emp => {
        addNotification(
          "Acceso Bloqueado", 
          `El colaborador ${emp.name} ${emp.surname} solicita un nuevo PIN de acceso.`, 
          'critical'
        );
      });
    }
  }, [employees, attendance, todayDateStr]);

  const unreadCount = notifications.filter(n => !n.isRead).length;

  const dayOfYear = useMemo(() => {
    const start = new Date(today.getFullYear(), 0, 0);
    const diff = today.getTime() - start.getTime();
    return Math.floor(diff / (1000 * 60 * 60 * 24));
  }, [today]);

  const birthdayPeeps = useMemo(() => {
    return employees.filter(e => {
      if (!e.birthDate || e.status !== 'active') return false;
      const b = new Date(e.birthDate);
      return b.getMonth() === today.getMonth() && b.getDate() === today.getDate();
    });
  }, [employees, today]);

  const dailyQuote = DAILY_QUOTES[dayOfYear % DAILY_QUOTES.length];
  const activeBreak = ACTIVE_BREAKS[dayOfYear % ACTIVE_BREAKS.length];

  const handlePurgeData = async () => {
    if (role !== Role.SUPER_ADMIN) return;
    onUpdateEmployees([]);
    onUpdatePayments([]);
  };

  const allAppData = {
    company,
    employees,
    attendance,
    payments,
    settings,
    exportDate: new Date().toISOString()
  };

  return (
    <div className="flex h-screen bg-[#fcfdfe] overflow-hidden flex-col md:flex-row">
      <Sidebar 
        role={role} 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        onLogout={onLogout} 
        companyName={company?.name} 
        unreadCount={unreadCount}
      />

      <main className="flex-1 overflow-y-auto px-6 py-8 md:px-10 md:py-10 scroll-smooth custom-scroll">
        <header className="flex flex-col md:flex-row justify-between items-start md:items-center mb-10 gap-6 no-print pt-10 md:pt-0">
          <div className="flex items-center gap-4">
            <h1 className="text-xl md:text-2xl font-[950] text-slate-900 tracking-tight uppercase">Dashboard Corporativo</h1>
            <div className="flex items-center gap-3 px-4 py-2 bg-white border rounded-2xl shadow-sm">
               <div className={`w-3 h-3 rounded-full ${isDbConnected ? 'bg-emerald-500 shadow-[0_0_12px_#10b981]' : 'bg-red-500 animate-pulse'}`}></div>
               <span className="text-[9px] font-black uppercase tracking-[0.2em] text-slate-500">
                 {isDbConnected ? 'Conectado' : 'Sin Red'}
               </span>
            </div>
          </div>
          <div className="flex gap-3">
             <button onClick={() => setActiveTab('ai')} className="px-4 py-2 bg-blue-50 text-blue-700 rounded-xl text-[9px] font-black uppercase border border-blue-100 flex items-center gap-2 hover:bg-blue-100 transition-all">
               <span className="animate-pulse">✨</span> IA Assistant
             </button>
             {(role === Role.SUPER_ADMIN || role === Role.PARTIAL_ADMIN) && (
               <button onClick={() => setShowInstallModal(true)} className="px-4 py-2 bg-slate-900 text-white rounded-xl text-[9px] font-black uppercase border border-slate-900 shadow-xl active:scale-95 transition-all">Estación Kiosco</button>
             )}
          </div>
        </header>

        <div className="animate-in fade-in duration-500">
          {activeTab === 'dashboard' && (
            <div className="space-y-12">
              {birthdayPeeps.length > 0 && role === Role.SUPER_ADMIN && (
                <div className="bg-emerald-600 p-8 rounded-[3rem] text-white shadow-[0_20px_50px_rgba(16,185,129,0.2)] flex flex-col md:flex-row items-center justify-between gap-6 animate-pulse">
                   <div className="flex items-center gap-6">
                      <span className="text-5xl">🎂</span>
                      <div>
                         <h3 className="text-xl font-black uppercase tracking-tighter">¡Hoy hay Cumpleaños!</h3>
                         <p className="text-[10px] font-bold uppercase tracking-widest opacity-80 mt-1">Recuérdales lo valiosos que son para el equipo</p>
                      </div>
                   </div>
                   <div className="flex -space-x-4">
                      {birthdayPeeps.map(e => (
                         <div key={e.id} className="w-12 h-12 rounded-full border-4 border-emerald-600 bg-white overflow-hidden" title={e.name}>
                            {e.photo ? <img src={e.photo} className="w-full h-full object-cover" /> : <div className="flex items-center justify-center h-full text-[10px] text-emerald-600 font-black">{e.name[0]}</div>}
                         </div>
                      ))}
                   </div>
                </div>
              )}

              <div className="relative overflow-hidden bg-slate-900 rounded-[3rem] p-12 text-white shadow-2xl min-h-[300px] flex flex-col justify-center bg-cover bg-center" style={{ backgroundImage: 'linear-gradient(rgba(15, 23, 42, 0.8), rgba(15, 23, 42, 0.8)), url(https://images.unsplash.com/photo-1499750310107-5fef28a66643?auto=format&fit=crop&q=80&w=2070)' }}>
                  <div className="relative z-10 max-w-2xl">
                    <p className="text-blue-400 font-black text-[10px] uppercase tracking-[0.5em] mb-4">Reflexión Estratégica</p>
                    <h2 className="text-3xl md:text-5xl font-[900] leading-tight tracking-tighter italic">"{dailyQuote}"</h2>
                  </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8 items-stretch">
                <div className="bg-white p-10 rounded-[3rem] shadow-sm border border-slate-100 space-y-6">
                  <div className="flex items-center gap-4">
                    <span className="text-5xl">{activeBreak.icon}</span>
                    <div>
                      <h3 className="text-xl font-black text-slate-900 uppercase">Pausa Saludable</h3>
                      <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest">Bienestar Laboral</p>
                    </div>
                  </div>
                  <div className="space-y-4">
                    <h4 className="text-lg font-extrabold text-slate-800">{activeBreak.title}</h4>
                    <p className="text-slate-500 leading-relaxed font-medium">{activeBreak.description}</p>
                  </div>
                </div>

                <div className="relative overflow-hidden bg-white rounded-[3rem] shadow-sm border border-slate-100 h-full">
                   <img 
                     src="https://images.unsplash.com/photo-1470770841072-f978cf4d019e?auto=format&fit=crop&q=80&w=2070" 
                     alt="Paisaje Relajante" 
                     className="w-full h-full object-cover transition-transform duration-700 hover:scale-105"
                   />
                   <div className="absolute bottom-6 left-6 right-6">
                      <p className="text-[8px] font-black text-white/50 uppercase tracking-[0.3em]">Ambiente de Paz</p>
                   </div>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'notifications' && (
            <NotificationsModule 
              notifications={notifications} 
              onToggleRead={(id) => setNotifications(prev => prev.map(n => n.id === id ? { ...n, isRead: !n.isRead } : n))}
              onToggleProcessed={(id) => setNotifications(prev => prev.map(n => n.id === id ? { ...n, isProcessed: !n.isProcessed } : n))}
              onClearAll={() => setNotifications([])}
            />
          )}

          {activeTab === 'company' && <CompanyModule company={company} onUpdate={onUpdateCompany} role={role} />}
          {activeTab === 'employees' && <EmployeeModule employees={employees} onUpdate={onUpdateEmployees} role={role} attendance={attendance} payments={payments} company={company} />}
          {activeTab === 'payroll' && <PayrollModule employees={employees} payments={payments} company={company} settings={settings} role={role} />}
          {activeTab === 'payments' && <PaymentsModule employees={employees} payments={payments} onUpdate={onUpdatePayments} role={role} />}
          {activeTab === 'settings' && <SettingsModule settings={settings} onUpdate={onUpdateSettings} role={role} onPurge={handlePurgeData} allData={allAppData} />}
          {activeTab === 'reports' && <ReportsModule employees={employees} payments={payments} attendance={attendance} company={company} settings={settings} role={role} />}
          {activeTab === 'ai' && <AiAssistant employees={employees} attendance={attendance} payments={payments} role={role} />}
        </div>
      </main>

      <Modal isOpen={showInstallModal} onClose={() => setShowInstallModal(false)} title="Modo de Estación" maxWidth="max-w-md">
         <div className="space-y-6">
            <p className="text-[11px] text-slate-500 text-center font-bold uppercase tracking-widest">Seleccione la interfaz para este dispositivo:</p>
            <div className="space-y-3">
               <button onClick={() => { onUpdateAppMode('full'); setShowInstallModal(false); }} className={`w-full p-6 rounded-2xl border-2 text-left flex items-center justify-between transition-all ${appMode === 'full' ? 'border-blue-600 bg-blue-50' : 'border-slate-100'}`}>
                  <div>
                    <p className="font-black text-sm text-slate-900 uppercase">Administrativa Full</p>
                    <p className="text-[10px] text-slate-400 font-bold uppercase mt-1">Acceso total a gestión.</p>
                  </div>
               </button>
               <button onClick={() => { onUpdateAppMode('attendance'); setShowInstallModal(false); }} className={`w-full p-6 rounded-2xl border-2 text-left flex items-center justify-between transition-all ${appMode === 'attendance' ? 'border-blue-600 bg-blue-50' : 'border-slate-100'}`}>
                  <div>
                    <p className="font-black text-sm text-slate-900 uppercase">Marcación Only</p>
                    <p className="text-[10px] text-slate-400 font-bold uppercase mt-1">Kiosco de asistencia.</p>
                  </div>
               </button>
            </div>
         </div>
      </Modal>
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useEffect } from 'react';
import { Employee, Role, BloodType, Gender, CivilStatus, AbsenceRecord, TerminationReason } from '../../types.ts';
import Modal from '../../components/Modal.tsx';

interface EmployeeModuleProps {
  employees: Employee[];
  onUpdate: (employees: Employee[]) => void;
  role: Role;
  attendance: any[];
  payments: any[];
  company: any;
}

const EmployeeModule: React.FC<EmployeeModuleProps> = ({ employees, onUpdate, role }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingEmp, setEditingEmp] = useState<Employee | null>(null);
  const [viewingEmp, setViewingEmp] = useState<Employee | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [showArchived, setShowArchived] = useState(false);
  const [hasBankInfo, setHasBankInfo] = useState(true);

  const [isAbsenceModalOpen, setIsAbsenceModalOpen] = useState(false);
  const [isTermModalOpen, setIsTermModalOpen] = useState(false);
  const [newAbsence, setNewAbsence] = useState<Partial<AbsenceRecord>>({ type: 'Falta', justified: false, date: new Date().toISOString().split('T')[0], reason: '' });
  const [termData, setTermData] = useState({ reason: TerminationReason.VOLUNTARY, details: '', date: new Date().toISOString().split('T')[0] });

  const [feedback, setFeedback] = useState<{isOpen: boolean, title: string, message: string, type: 'success' | 'error' | 'info'}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  const initialForm: Partial<Employee> = {
    name: '', surname: '', identification: '', birthDate: '', phone: '', email: '', 
    gender: Gender.MASCULINO, civilStatus: CivilStatus.SOLTERO,
    origin: 'ECUATORIANA', address: '', 
    bloodType: BloodType.O_POS, startDate: new Date().toISOString().split('T')[0],
    role: Role.EMPLOYEE, salary: 482.00, status: 'active' as const, photo: '', pin: '',
    emergencyContact: { name: '', phone: '' },
    isFixed: true, isAffiliated: true, overSalaryType: 'monthly',
    bankInfo: { ifi: '', type: 'Ahorros', account: '' },
    absences: [],
    observations: []
  };

  const [form, setForm] = useState<Partial<Employee>>(initialForm);

  useEffect(() => {
    if (!form.isAffiliated && form.overSalaryType !== 'none') {
      setForm(prev => ({ ...prev, overSalaryType: 'none' }));
    }
  }, [form.isAffiliated]);

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setForm(prev => ({ ...prev, photo: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSave = () => {
    if (!form.name || !form.surname || !form.identification || !form.salary || !form.role) {
      setFeedback({ isOpen: true, title: "Error", message: "Nombres, apellidos, cédula, cargo y sueldo son obligatorios.", type: "error" });
      return;
    }
    const finalForm = { ...form };
    if (!hasBankInfo) finalForm.bankInfo = { ifi: 'NO APLICA', type: 'Ahorros', account: 'N/A' };

    let updatedList: Employee[];
    if (editingEmp) {
      updatedList = employees.map(e => e.id === editingEmp.id ? { ...e, ...finalForm } as Employee : e);
      setFeedback({ isOpen: true, title: "Éxito", message: "Expediente actualizado correctamente.", type: "success" });
    } else {
      const autoPin = Math.floor(100000 + Math.random() * 900000).toString();
      const newEmp: Employee = { 
        ...finalForm, 
        id: Math.random().toString(36).substr(2, 9), 
        pin: autoPin, 
        pinChanged: false, 
        pinNeedsReset: false, 
        absences: [], 
        observations: [], 
        totalHoursWorked: 0, 
        status: 'active' as const 
      } as Employee;
      updatedList = [...employees, newEmp];
      setFeedback({ isOpen: true, title: "Éxito", message: `Colaborador registrado. PIN Inicial: ${autoPin}`, type: "success" });
    }
    onUpdate(updatedList);
    setIsModalOpen(false);
  };

  const handleAddAbsence = () => {
    if (!viewingEmp) return;
    const record: AbsenceRecord = { ...newAbsence, id: Math.random().toString(36).substr(2, 9) } as AbsenceRecord;
    const updated: Employee[] = employees.map(e => e.id === viewingEmp.id ? { ...e, absences: [...(e.absences || []), record] } : e);
    onUpdate(updated);
    setViewingEmp({ ...viewingEmp, absences: [...(viewingEmp.absences || []), record] });
    setIsAbsenceModalOpen(false);
  };

  const handleTerminate = () => {
    if (!viewingEmp) return;
    const updated: Employee[] = employees.map(e => e.id === viewingEmp.id ? { 
      ...e, 
      status: 'terminated' as const, 
      terminationDate: termData.date, 
      terminationReason: termData.reason, 
      terminationDetails: termData.details 
    } : e);
    onUpdate(updated);
    setViewingEmp(null);
    setIsTermModalOpen(false);
    setFeedback({ isOpen: true, title: "Desvinculación", message: "Estatus del colaborador actualizado a salida.", type: "success" });
  };

  const filteredEmployees = employees.filter(e => {
    const matchesSearch = (e.name + " " + e.surname + " " + e.identification).toLowerCase().includes(searchTerm.toLowerCase());
    return showArchived ? matchesSearch && e.status === 'archived' : matchesSearch && e.status !== 'archived';
  });

  return (
    <div className="space-y-4 fade-in">
      <div className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-100 flex flex-col md:flex-row justify-between items-center no-print gap-4">
        <div>
          <h2 className="text-xl font-[950] text-slate-900 tracking-tighter uppercase leading-none">Gestión Humana</h2>
          <div className="flex gap-4 mt-2">
            <button onClick={() => setShowArchived(false)} className={`text-[9px] font-black uppercase tracking-widest ${!showArchived ? 'text-blue-600 border-b-2 border-blue-600' : 'text-slate-400'}`}>Activos / Salidas</button>
            <button onClick={() => setShowArchived(true)} className={`text-[9px] font-black uppercase tracking-widest ${showArchived ? 'text-blue-600 border-b-2 border-blue-600' : 'text-slate-400'}`}>Archivados</button>
          </div>
        </div>
        <div className="flex gap-3 w-full md:w-auto">
          <input type="text" placeholder="Buscar por nombre o CI..." className="flex-1 p-3 border rounded-xl text-xs uppercase font-bold" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
          <button onClick={() => { setForm(initialForm); setEditingEmp(null); setHasBankInfo(true); setIsModalOpen(true); }} className="px-8 py-4 bg-blue-700 text-white font-black rounded-2xl shadow-lg uppercase text-[10px] tracking-widest active:scale-95 transition-all">Nuevo Colaborador</button>
        </div>
      </div>

      <div className="bg-white rounded-[2.5rem] shadow-sm border overflow-hidden no-print">
        <table className="w-full text-left">
          <thead className="bg-slate-50 text-[8px] font-black text-slate-400 uppercase tracking-widest">
            <tr>
              <th className="px-6 py-4">Colaborador</th>
              <th className="px-6 py-4">Identificación</th>
              <th className="px-6 py-4">Cargo</th>
              <th className="px-6 py-4 text-center">Estado</th>
              <th className="px-6 py-4 text-right">Acciones</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50 text-[11px] font-black uppercase">
            {filteredEmployees.map(emp => (
              <tr key={emp.id} className="hover:bg-blue-50/40 transition-colors">
                <td className="px-6 py-3 font-black text-slate-900 flex items-center gap-3">
                  <div className="w-8 h-8 rounded-lg overflow-hidden border bg-slate-100 flex items-center justify-center">
                    {emp.photo ? <img src={emp.photo} className="w-full h-full object-cover" /> : <span>👤</span>}
                  </div>
                  {emp.surname} {emp.name}
                </td>
                <td className="px-6 py-3 text-[10px] font-mono">{emp.identification}</td>
                <td className="px-6 py-3 text-blue-600 text-[9px] uppercase">{emp.role}</td>
                <td className="px-6 py-3 text-center">
                  <span className={`px-3 py-1 rounded-full text-[8px] font-black uppercase ${emp.status === 'active' ? 'bg-emerald-50 text-emerald-600' : 'bg-red-50 text-red-600'}`}>
                    {emp.status === 'active' ? 'Activo' : 'Salida'}
                  </span>
                </td>
                <td className="px-6 py-3 text-right flex gap-2 justify-end">
                   <button onClick={() => setViewingEmp(emp)} className="px-3 py-1.5 bg-blue-50 text-blue-700 rounded-lg text-[8px] font-black uppercase">Expediente</button>
                   {role === Role.SUPER_ADMIN && (
                     <button onClick={() => { setEditingEmp(emp); setForm(emp); setHasBankInfo(emp.bankInfo?.ifi !== 'NO APLICA'); setIsModalOpen(true); }} className="px-3 py-1.5 bg-slate-100 text-slate-600 rounded-lg text-[8px] font-black uppercase">Editar</button>
                   )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

