import React, { useState, useEffect } from 'react';
import { Role } from '../types.ts';
import Modal from './Modal.tsx';

interface SidebarProps {
  role: Role;
  activeTab: string;
  setActiveTab: (tab: any) => void;
  onLogout: () => void;
  companyName?: string;
  unreadCount?: number;
}

const Sidebar: React.FC<SidebarProps> = ({ role, activeTab, setActiveTab, onLogout, companyName, unreadCount = 0 }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [isStandalone, setIsStandalone] = useState(false);
  const [showModeSelection, setShowModeSelection] = useState(false);

  useEffect(() => {
    if (window.matchMedia('(display-mode: standalone)').matches || (window.navigator as any).standalone) {
      setIsStandalone(true);
    }
  }, []);

  const triggerPWAInstall = async () => {
    const deferredPrompt = (window as any).deferredPrompt;
    if (deferredPrompt) {
      deferredPrompt.prompt();
      const { outcome } = await deferredPrompt.userChoice;
      if (outcome === 'accepted') {
        (window as any).deferredPrompt = null;
      }
    } else {
      alert("Para instalar:\n1. Use Chrome/Edge en Android o PC.\n2. En iOS use Safari: 'Compartir' -> 'Añadir a pantalla de inicio'.");
    }
    setShowModeSelection(false);
  };

  const handleInstallClick = () => {
    if (role === Role.SUPER_ADMIN) {
      setShowModeSelection(true);
    } else if (role === Role.PARTIAL_ADMIN) {
      // Los administradores parciales solo instalan el sistema de asistencia
      localStorage.setItem('app_mode', 'attendance');
      triggerPWAInstall();
    }
  };

  const handleInstallProcess = (mode: 'full' | 'attendance') => {
