import React, { useState, useEffect, useMemo } from 'react';
import { Employee, AttendanceRecord, GlobalSettings } from '../types.ts';
import Clock from '../components/Clock.tsx';
import Modal from '../components/Modal.tsx';

interface AttendanceSystemProps {
  employees: Employee[];
  attendance: AttendanceRecord[];
  onRegister: (record: AttendanceRecord) => void;
  onBack: () => void;
  onUpdateEmployees: (employees: Employee[]) => void;
  settings: GlobalSettings;
}

const AttendanceSystem: React.FC<AttendanceSystemProps> = ({ employees, attendance, onRegister, onBack, onUpdateEmployees, settings }) => {
  const [pin, setPin] = useState('');
  const [status, setStatus] = useState<'idle' | 'confirm' | 'forgotten_form' | 'success' | 'error' | 'change_pin' | 'justification_form'>('idle');
  const [isProcessing, setIsProcessing] = useState(false);
  const [currentEmp, setCurrentEmp] = useState<Employee | null>(null);
  const [pendingMarkData, setPendingMarkData] = useState<{ type: 'in' | 'out' | 'half_day', isLate: boolean } | null>(null);
  const [justificationText, setJustificationText] = useState('');
  const [newPin, setNewPin] = useState('');
  const [forgotCi, setForgotCi] = useState('');
  const [successMsg, setSuccessMsg] = useState('');
  const [feedback, setFeedback] = useState<{isOpen: boolean, title: string, message: string, type: 'success' | 'error' | 'info'}>({
    isOpen: false, title: '', message: '', type: 'success'
  });

  const isWithinRange = (now: Date, startStr: string, endStr: string) => {
    const [sh, sm] = startStr.split(':').map(Number);
    const [eh, em] = endStr.split(':').map(Number);
    const s = new Date(now); s.setHours(sh, sm, 0, 0);
    const e = new Date(now); e.setHours(eh, em, 0, 0);
    return now >= s && now <= e;
  };

  const handleMark = (type: 'in' | 'out' | 'half_day') => {
    if (!currentEmp || isProcessing) return;

    const now = new Date();
    const day = now.getDay();
    let isOffSchedule = false;
    let isCriticalLate = false;

    // Verificar si está dentro de algún bloque horario
    if (day >= 1 && day <= 5) { // Lun-Vie
      const in1 = isWithinRange(now, settings.schedule.monFri.in1, settings.schedule.monFri.out1);
      const in2 = isWithinRange(now, settings.schedule.monFri.in2, settings.schedule.monFri.out2);
      if (!in1 && !in2) isOffSchedule = true;

      // Lógica de atraso crítico para entrada principal
      if (type === 'in') {
        const [schedH, schedM] = settings.schedule.monFri.in1.split(':').map(Number);
        const schedDate = new Date(now);
        schedDate.setHours(schedH, schedM, 0, 0);
        const diffMins = (now.getTime() - schedDate.getTime()) / (1000 * 60);
        if (diffMins > 15) isCriticalLate = true;
      }
    } else if (day === 6) { // Sáb
      if (!isWithinRange(now, settings.schedule.sat.in, settings.schedule.sat.out)) isOffSchedule = true;
    } else {
      isOffSchedule = true; // Dom
    }

    if (isOffSchedule || isCriticalLate) {
      setPendingMarkData({ type, isLate: isCriticalLate });
      setStatus('justification_form');
      return;
    }

    processRegistration(type, isCriticalLate);
  };

  const processRegistration = (type: 'in' | 'out' | 'half_day', isLate: boolean, justification?: string) => {
    setIsProcessing(true);

    if (isLate && Notification.permission === "granted") {
      new Notification("ALERTA DE ASISTENCIA", {
        body: `El colaborador ${currentEmp?.name} ${currentEmp?.surname} ha marcado con más de 15 minutos de retraso.`,
        icon: "https://cdn-icons-png.flaticon.com/512/3844/3844724.png"
      });
    }

    const record: AttendanceRecord = {
      id: Math.random().toString(36).substr(2, 9),
      employeeId: currentEmp!.id,
      timestamp: new Date().toISOString(),
      type,
      status: 'confirmed',
      isLate,
      justification
    };

    onRegister(record);

    if (type === 'in') setSuccessMsg("INGRESO REGISTRADO CON ÉXITO");
    else if (type === 'out') setSuccessMsg("SALIDA REGISTRADA CON ÉXITO");
    else setSuccessMsg("MARCACIÓN REGISTRADA CON ÉXITO");

    setStatus('success');
    setPin('');
    setJustificationText('');
    setPendingMarkData(null);

    setTimeout(() => {
      setStatus('idle');
      setCurrentEmp(null);
      setIsProcessing(false);
    }, 4000);
  };

  const handleConfirmJustification = () => {
    if (!justificationText.trim()) {
      setFeedback({ isOpen: true, title: "Requerido", message: "Debe ingresar un motivo para continuar.", type: "error" });
      return;
    }
    if (pendingMarkData) {
      processRegistration(pendingMarkData.type, pendingMarkData.isLate, justificationText);
    }
  };

  const handlePinChange = () => {
    if (newPin.length !== 6 || newPin === currentEmp?.pin) {
      setFeedback({ isOpen: true, title: "Error de PIN", message: "Ingrese un PIN nuevo de 6 dígitos diferente al actual.", type: "error" });
      return;
    }

    const updated = employees.map(e => e.id === currentEmp?.id ? {
      ...e,
      pin: newPin,
      pinChanged: true,
      pinNeedsReset: false,
      pinResetRequested: false
    } : e);

    onUpdateEmployees(updated);

    setFeedback({ isOpen: true, title: "PIN Actualizado", message: "Su clave de acceso ha sido cambiada. Ahora puede marcar su asistencia.", type: "success" });
    setStatus('confirm');
    setNewPin('');
  };

  const handleRequestPinReset = () => {
    const emp = employees.find(e => e.identification === forgotCi && e.status === 'active');
    if (emp) {
      const updated = employees.map(e => e.id === emp.id ? { ...e, pinResetRequested: true } : e);
      onUpdateEmployees(updated);

      if (Notification.permission === "granted") {
        new Notification("SOLICITUD DE ACCESO", {
          body: `El colaborador ${emp.name} solicita resetear su PIN de asistencia.`,
          icon: "https://cdn-icons-png.flaticon.com/512/3844/3844724.png"
        });
      }

      setFeedback({ 
        isOpen: true, 
        title: "Solicitud Recibida", 
        message: "Su solicitud ha sido enviada al administrador. RRHH autorizará su nuevo acceso a la brevedad.", 
        type: "info" 
      });
      setStatus('idle');
      setForgotCi('');
    } else {
      setFeedback({ 
        isOpen: true, 
        title: "Error", 
        message: "Identificación no encontrada en el sistema.", 
        type: "error" 
      });
    }
  };

  useEffect(() => {
    if (pin.length === 6 && status === 'idle' && !isProcessing) {
      const emp = employees.find(e => e.pin === pin && e.status === 'active');
      if (emp) {
        setCurrentEmp(emp);
        if (!emp.pinChanged || emp.pinNeedsReset) {
          setStatus('change_pin');
        } else {
          setStatus('confirm');
        }
      } else {
        setStatus('error');
        setTimeout(() => { setStatus('idle'); setPin(''); }, 1500);
      }
    }
  }, [pin, employees, status, isProcessing]);

  useEffect(() => {
    const handleKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onBack();
      if (status !== 'idle' || isProcessing) return;
      if (e.key >= '0' && e.key <= '9' && pin.length < 6) setPin(p => p + e.key);
      if (e.key === 'Backspace') setPin(p => p.slice(0, -1));
    };
    window.addEventListener('keydown', handleKey);
    return () => window.removeEventListener('keydown', handleKey);
  }, [pin, status, isProcessing]);

  return (
    <div className="min-h-screen gradient-blue flex flex-col items-center justify-center p-4">
      {status === 'success' && (
        <div className="fixed inset-0 z-[100] bg-slate-900/95 backdrop-blur-3xl flex flex-col items-center justify-center fade-in text-center p-8">
           <div className="w-24 h-24 bg-emerald-500 text-white rounded-[2.5rem] flex items-center justify-center text-5xl mb-10 shadow-[0_0_50px_rgba(16,185,129,0.4)] animate-bounce">✓</div>
           <p className="text-white font-[950] text-4xl uppercase tracking-tighter text-center max-w-2xl leading-tight">{successMsg}</p>
        </div>
      )}

      <div className={`w-full max-w-lg bg-white/95 backdrop-blur-3xl rounded-[3.5rem] shadow-2xl p-6 md:p-12 flex flex-col items-center relative overflow-hidden ${status === 'success' ? 'opacity-0' : 'fade-in'}`}>
        <div className="mb-8 transform scale-[0.6] md:scale-[0.8]"><Clock /></div>

        {status === 'idle' && (
          <div className="w-full text-center">
            <h2 className="text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] mb-6">Ingresar PIN de 6 dígitos</h2>
            <div className="flex gap-2 justify-center mb-10">
              {[...Array(6)].map((_, i) => (
                <div key={i} className={`w-10 h-16 border-b-4 flex items-center justify-center text-4xl font-black transition-all ${pin.length > i ? 'border-blue-600 text-slate-900' : 'border-slate-100'}`}>
                  {pin[i] ? '•' : ''}
                </div>
              ))}
            </div>
            <div className="grid grid-cols-3 gap-3 max-w-[340px] mx-auto mb-10">
              {[1, 2, 3, 4, 5, 6, 7, 8, 9, 'C', 0, '←'].map(btn => (
                <button 
                  key={btn} 
                  onClick={() => {
                    if (btn === 'C') setPin('');
                    else if (btn === '←') setPin(p => p.slice(0, -1));
                    else if (pin.length < 6) setPin(p => p + btn);
                  }} 
                  className="h-16 md:h-18 bg-white hover:bg-blue-700 hover:text-white rounded-2xl text-2xl font-black border border-slate-200 active:scale-90 transition-all shadow-sm flex items-center justify-center"
                >
                  {btn}
                </button>
              ))}
            </div>

            <button 
              onClick={() => setStatus('forgotten_form')}
              className="w-full py-4 bg-slate-50 border border-slate-100 rounded-2xl text-[10px] font-black text-blue-600 uppercase tracking-widest hover:bg-blue-50 transition-all"
            >
              ¿Olvidó su PIN? Solicitar Reseteo
            </button>
          </div>
        )}

        {status === 'justification_form' && (
          <div className="text-center w-full space-y-6 animate-in zoom-in">
             <div className="w-20 h-20 bg-blue-50 text-blue-600 rounded-3xl flex items-center justify-center text-3xl mx-auto mb-4 border border-blue-100 shadow-inner">📝</div>
             <h2 className="text-2xl font-[950] text-slate-900 uppercase tracking-tighter">Justificación Requerida</h2>
             <p className="text-[10px] text-slate-500 font-black uppercase tracking-widest leading-relaxed">Su marcación se encuentra fuera del horario laboral o presenta un retraso crítico.</p>
             <textarea 
               value={justificationText}
               onChange={e => setJustificationText(e.target.value)}
               className="w-full border-2 p-5 rounded-2xl text-xs font-black uppercase focus:border-blue-600 outline-none bg-slate-50 min-h-[120px]" 
               placeholder="Escriba el motivo detallado..." 
               autoFocus 
             />
             <div className="grid grid-cols-2 gap-3">
                <button onClick={() => setStatus('confirm')} className="w-full py-4 bg-slate-100 text-slate-600 font-black rounded-2xl uppercase text-[10px] tracking-widest active:scale-95 transition-all">Cancelar</button>
                <button onClick={handleConfirmJustification} className="w-full py-4 bg-blue-700 text-white font-black rounded-2xl uppercase text-[10px] tracking-widest shadow-xl active:scale-95 transition-all">Confirmar Marcación</button>
             </div>
          </div>
        )}

        {status === 'forgotten_form' && (
          <div className="text-center w-full space-y-6 animate-in zoom-in">
            <h2 className="text-2xl font-[950] text-slate-900 uppercase tracking-tighter">Solicitar Nuevo PIN</h2>
            <p className="text-xs text-slate-500 font-bold uppercase tracking-widest leading-relaxed">Ingrese su Cédula / Identificación para validar su identidad</p>
            <input 
              maxLength={10} 
              type="text" 
              inputMode="numeric"
              value={forgotCi} 
              onChange={e => setForgotCi(e.target.value.replace(/\D/g,''))} 
              className="w-full border-2 p-5 rounded-2xl text-center text-3xl font-black focus:border-blue-600 outline-none bg-slate-50" 
              placeholder="0000000000" 
              autoFocus 
            />
            <div className="grid grid-cols-2 gap-3">
              <button onClick={() => setStatus('idle')} className="w-full py-4 bg-slate-100 text-slate-600 font-black rounded-2xl uppercase text-[10px] tracking-widest active:scale-95 transition-all">Cancelar</button>
              <button onClick={handleRequestPinReset} className="w-full py-4 bg-blue-700 text-white font-black rounded-2xl uppercase text-[10px] tracking-widest shadow-xl active:scale-95 transition-all">Enviar</button>
            </div>
          </div>
        )}

        {status === 'change_pin' && currentEmp && (
          <div className="text-center w-full space-y-6">
            <h2 className="text-2xl font-[950] text-slate-900 uppercase">Seguridad Obligatoria</h2>
            <p className="text-xs text-slate-500 font-bold uppercase tracking-widest">Asigne su nuevo PIN personal de 6 dígitos</p>
            <input 
              maxLength={6} 
              type="password" 
              inputMode="numeric"
              value={newPin} 
              onChange={e => setNewPin(e.target.value.replace(/\D/g,''))} 
              className="w-full border-2 p-5 rounded-2xl text-center text-4xl font-black focus:border-blue-600 outline-none bg-slate-50" 
              placeholder="••••••" 
              autoFocus 
            />
            <button onClick={handlePinChange} className="w-full py-5 bg-blue-700 text-white font-black rounded-[2rem] uppercase text-[11px] tracking-widest shadow-2xl active:scale-95 transition-all">Establecer Nuevo PIN</button>
          </div>
        )}

        {status === 'confirm' && currentEmp && (
          <div className="text-center w-full animate-in zoom-in">
            <div className="w-28 h-28 bg-slate-100 rounded-[2.5rem] mx-auto flex items-center justify-center text-4xl font-black text-blue-700 uppercase border-4 border-white shadow-xl mb-6 overflow-hidden">
                 {currentEmp.photo ? <img src={currentEmp.photo} className="w-full h-full object-cover" /> : <span>{currentEmp.name[0]}</span>}
            </div>
            <h2 className="text-3xl font-[950] text-slate-900 mb-1 uppercase tracking-tighter leading-none">{currentEmp.name} {currentEmp.surname}</h2>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em] mb-10">{currentEmp.role}</p>
            <div className="grid grid-cols-1 gap-4">
              <button onClick={() => handleMark('in')} className="py-8 bg-blue-700 text-white rounded-[2rem] font-black text-xl uppercase shadow-2xl active:scale-95 transition-all border-b-4 border-blue-900">Registrar Ingreso</button>
              <button onClick={() => handleMark('out')} className="py-8 bg-slate-900 text-white rounded-[2rem] font-black text-xl uppercase shadow-2xl active:scale-95 transition-all border-b-4 border-black">Registrar Salida</button>
            </div>
          </div>
        )}

        {status === 'error' && (
          <div className="text-center text-red-600 py-10 animate-pulse">
            <div className="text-7xl mb-4">✕</div>
            <h2 className="text-2xl font-[950] uppercase tracking-tighter">Acceso Denegado</h2>
            <p className="text-[10px] font-bold uppercase mt-2">PIN Incorrecto</p>
          </div>
        )}
      </div>

      <button onClick={onBack} className="mt-10 text-white/30 hover:text-white font-black text-[11px] uppercase tracking-[0.6em] p-4 transition-all">Salir del Terminal</button>

      <Modal isOpen={feedback.isOpen} onClose={() => setFeedback({...feedback, isOpen: false})} title={feedback.title} type={feedback.type}>
          <div className="text-center space-y-6">
              <p className="text-slate-600 font-bold uppercase text-[12px] leading-relaxed">{feedback.message}</p>
              <button onClick={() => setFeedback({...feedback, isOpen: false})} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] tracking-widest active:scale-95">Entendido</button>
          </div>
      </Modal>
    </div>
  );
};

export default AttendanceSystem;

import React, { useState, useEffect } from 'react';
import { Employee, Role, BloodType, Gender, CivilStatus, AbsenceRecord, TerminationReason } from '../../types.ts';
import Modal from '../../components/Modal.tsx';

interface EmployeeModuleProps {
  employees: Employee[];
  onUpdate: (employees: Employee[]) => void;
  role: Role;
  attendance: any[];
  payments: any[];
  company: any;
}

const EmployeeModule: React.FC<EmployeeModuleProps> = ({ employees, onUpdate, role }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingEmp, setEditingEmp] = useState<Employee | null>(null);
  const [viewingEmp, setViewingEmp] = useState<Employee | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [showArchived, setShowArchived] = useState(false);
  const [hasBankInfo, setHasBankInfo] = useState(true);

  const [isAbsenceModalOpen, setIsAbsenceModalOpen] = useState(false);
  const [isTermModalOpen, setIsTermModalOpen] = useState(false);
  const [newAbsence, setNewAbsence] = useState<Partial<AbsenceRecord>>({ type: 'Falta', justified: false, date: new Date().toISOString().split('T')[0], reason: '' });
  const [termData, setTermData] = useState({ reason: TerminationReason.VOLUNTARY, details: '', date: new Date().toISOString().split('T')[0] });

  const [feedback, setFeedback] = useState<{isOpen: boolean, title: string, message: string, type: 'success' | 'error' | 'info'}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  const initialForm: Partial<Employee> = {
    name: '', surname: '', identification: '', birthDate: '', phone: '', email: '', 
    gender: Gender.MASCULINO, civilStatus: CivilStatus.SOLTERO,
    origin: 'ECUATORIANA', address: '', 
    bloodType: BloodType.O_POS, startDate: new Date().toISOString().split('T')[0],
    role: Role.EMPLOYEE, salary: 482.00, status: 'active' as const, photo: '', pin: '',
    emergencyContact: { name: '', phone: '' },
    isFixed: true, isAffiliated: true, overSalaryType: 'monthly',
    bankInfo: { ifi: '', type: 'Ahorros', account: '' },
    absences: [],
    observations: []
  };

  const [form, setForm] = useState<Partial<Employee>>(initialForm);

  useEffect(() => {
    if (!form.isAffiliated && form.overSalaryType !== 'none') {
      setForm(prev => ({ ...prev, overSalaryType: 'none' }));
    }
  }, [form.isAffiliated]);

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setForm(prev => ({ ...prev, photo: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSave = () => {
    if (!form.name || !form.surname || !form.identification || !form.salary || !form.role) {
      setFeedback({ isOpen: true, title: "Error", message: "Nombres, apellidos, cédula, cargo y sueldo son obligatorios.", type: "error" });
      return;
    }
    const finalForm = { ...form };
    if (!hasBankInfo) finalForm.bankInfo = { ifi: 'NO APLICA', type: 'Ahorros', account: 'N/A' };

    let updatedList: Employee[];
    if (editingEmp) {
      updatedList = employees.map(e => e.id === editingEmp.id ? { ...e, ...finalForm } as Employee : e);
      setFeedback({ isOpen: true, title: "Éxito", message: "Expediente actualizado correctamente.", type: "success" });
    } else {
      const autoPin = Math.floor(100000 + Math.random() * 900000).toString();
      const newEmp: Employee = { 
        ...finalForm, 
        id: Math.random().toString(36).substr(2, 9), 
        pin: autoPin, 
        pinChanged: false, 
        pinNeedsReset: false, 
        pinResetRequested: false,
        absences: [], 
        observations: [], 
        totalHoursWorked: 0, 
        status: 'active' as const 
      } as Employee;
      updatedList = [...employees, newEmp];
      setFeedback({ isOpen: true, title: "Éxito", message: `Colaborador registrado. PIN Inicial: ${autoPin}`, type: "success" });
    }
    onUpdate(updatedList);
    setIsModalOpen(false);
  };

  const handleApprovePinReset = (emp: Employee) => {
    const updated: Employee[] = employees.map(e => e.id === emp.id ? { 
      ...e, 
      pin: "000000", // PIN temporal por defecto
      pinNeedsReset: true, 
      pinResetRequested: false,
      pinChanged: false 
    } : e);
    onUpdate(updated);
    setViewingEmp({ ...emp, pinNeedsReset: true, pinResetRequested: false, pin: "000000" });
    setFeedback({ 
      isOpen: true, 
      title: "Reseteo Aprobado", 
      message: `Se ha habilitado el cambio de PIN para ${emp.name}. El empleado debe ingresar con '000000' en el kiosco y establecer su nueva clave.`, 
      type: "success" 
    });
  };

  const handleAddAbsence = () => {
    if (!viewingEmp) return;
    const record: AbsenceRecord = { ...newAbsence, id: Math.random().toString(36).substr(2, 9) } as AbsenceRecord;
    const updated: Employee[] = employees.map(e => e.id === viewingEmp.id ? { ...e, absences: [...(e.absences || []), record] } : e);
    onUpdate(updated);
    setViewingEmp({ ...viewingEmp, absences: [...(viewingEmp.absences || []), record] });
    setIsAbsenceModalOpen(false);
  };

  const handleTerminate = () => {
    if (!viewingEmp) return;
    const updated: Employee[] = employees.map(e => e.id === viewingEmp.id ? { 
      ...e, 
      status: 'terminated' as const, 
      terminationDate: termData.date, 
      terminationReason: termData.reason, 
      terminationDetails: termData.details 
    } : e);
    onUpdate(updated);
    setViewingEmp(null);
    setIsTermModalOpen(false);
    setFeedback({ isOpen: true, title: "Desvinculación", message: "Estatus del colaborador actualizado a salida.", type: "success" });
  };

  const filteredEmployees = employees.filter(e => {
    const matchesSearch = (e.name + " " + e.surname + " " + e.identification).toLowerCase().includes(searchTerm.toLowerCase());
    return showArchived ? matchesSearch && e.status === 'archived' : matchesSearch && e.status !== 'archived';
  });

  return (
    <div className="space-y-4 fade-in">
      <div className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-100 flex flex-col md:flex-row justify-between items-center no-print gap-4">
        <div>
          <h2 className="text-xl font-[950] text-slate-900 tracking-tighter uppercase leading-none">Gestión Humana</h2>
          <div className="flex gap-4 mt-2">
            <button onClick={() => setShowArchived(false)} className={`text-[9px] font-black uppercase tracking-widest ${!showArchived ? 'text-blue-600 border-b-2 border-blue-600' : 'text-slate-400'}`}>Activos / Salidas</button>
            <button onClick={() => setShowArchived(true)} className={`text-[9px] font-black uppercase tracking-widest ${showArchived ? 'text-blue-600 border-b-2 border-blue-600' : 'text-slate-400'}`}>Archivados</button>
          </div>
        </div>
        <div className="flex gap-3 w-full md:w-auto">
          <input type="text" placeholder="Buscar por nombre o CI..." className="flex-1 p-3 border rounded-xl text-xs uppercase font-bold" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
          <button onClick={() => { setForm(initialForm); setEditingEmp(null); setHasBankInfo(true); setIsModalOpen(true); }} className="px-8 py-4 bg-blue-700 text-white font-black rounded-2xl shadow-lg uppercase text-[10px] tracking-widest active:scale-95 transition-all">Nuevo Colaborador</button>
        </div>
      </div>

      <div className="bg-white rounded-[2.5rem] shadow-sm border overflow-hidden no-print">
        <table className="w-full text-left">
          <thead className="bg-slate-50 text-[8px] font-black text-slate-400 uppercase tracking-widest">
            <tr>
              <th className="px-6 py-4">Colaborador</th>
              <th className="px-6 py-4">Identificación</th>
              <th className="px-6 py-4">Cargo</th>
              <th className="px-6 py-4 text-center">Estado</th>
              <th className="px-6 py-4 text-right">Acciones</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50 text-[11px] font-black uppercase">
            {filteredEmployees.map(emp => (
              <tr key={emp.id} className="hover:bg-blue-50/40 transition-colors">
                <td className="px-6 py-3 font-black text-slate-900 flex items-center gap-3">
                  <div className="w-8 h-8 rounded-lg overflow-hidden border bg-slate-100 flex items-center justify-center">
                    {emp.photo ? <img src={emp.photo} className="w-full h-full object-cover" /> : <span>👤</span>}
                    {emp.pinResetRequested && <span className="absolute -top-1 -left-1 w-3 h-3 bg-red-500 rounded-full animate-ping"></span>}
                  </div>
                  {emp.surname} {emp.name}
                  {emp.pinResetRequested && <span className="text-[7px] bg-red-100 text-red-600 px-1.5 py-0.5 rounded-md font-black">SOLICITUD PIN</span>}
                </td>
                <td className="px-6 py-3 text-[10px] font-mono">{emp.identification}</td>
                <td className="px-6 py-3 text-blue-600 text-[9px] uppercase">{emp.role}</td>
                <td className="px-6 py-3 text-center">
                  <span className={`px-3 py-1 rounded-full text-[8px] font-black uppercase ${emp.status === 'active' ? 'bg-emerald-50 text-emerald-600' : 'bg-red-50 text-red-600'}`}>
                    {emp.status === 'active' ? 'Activo' : 'Salida'}
                  </span>
                </td>
                <td className="px-6 py-3 text-right flex gap-2 justify-end">
                   <button onClick={() => setViewingEmp(emp)} className="px-3 py-1.5 bg-blue-50 text-blue-700 rounded-lg text-[8px] font-black uppercase">Expediente</button>
                   {role === Role.SUPER_ADMIN && (
                     <button onClick={() => { setEditingEmp(emp); setForm(emp); setHasBankInfo(emp.bankInfo?.ifi !== 'NO APLICA'); setIsModalOpen(true); }} className="px-3 py-1.5 bg-slate-100 text-slate-600 rounded-lg text-[8px] font-black uppercase">Editar</button>
                   )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <Modal isOpen={!!viewingEmp} onClose={() => setViewingEmp(null)} title="Expediente de Personal">
        {viewingEmp && (
          <div className="space-y-6">
            <div className="flex gap-6 items-center border-b pb-4">
               <div className="w-24 h-24 rounded-2xl overflow-hidden border bg-slate-100 flex items-center justify-center shadow-lg">
                  {viewingEmp.photo ? <img src={viewingEmp.photo} className="w-full h-full object-cover" /> : <span className="text-4xl">👤</span>}
               </div>
               <div>
                  <h3 className="text-2xl font-[950] text-slate-900 uppercase tracking-tighter">{viewingEmp.surname} {viewingEmp.name}</h3>
                  <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest">{viewingEmp.role} | CI: {viewingEmp.identification}</p>
                  <p className="text-[9px] font-bold text-slate-400 mt-1 uppercase">Fecha Ingreso: {viewingEmp.startDate}</p>
                  {viewingEmp.pinResetRequested && (
                    <div className="mt-4 p-3 bg-red-50 border border-red-100 rounded-xl flex items-center justify-between gap-4">
                       <span className="text-[9px] font-black text-red-600 uppercase">Solicitud de Reseteo de PIN</span>
                       <button onClick={() => handleApprovePinReset(viewingEmp)} className="px-3 py-1.5 bg-red-600 text-white rounded-lg text-[8px] font-black uppercase shadow-lg active:scale-95 transition-all">Aprobar Reseteo</button>
                    </div>
                  )}
               </div>
            </div>

            <div className="grid grid-cols-2 gap-4 text-[10px] font-bold uppercase">
               <div className="p-4 bg-slate-50 rounded-xl">
                  <p className="text-slate-400 font-black text-[8px] mb-1">Información de Pago</p>
                  <p>Sueldo: ${viewingEmp.salary.toFixed(2)}</p>
                  <p>IESS: {viewingEmp.isAffiliated ? 'Afiliado' : 'No Afiliado'}</p>
                  <p>Beneficios: {viewingEmp.overSalaryType === 'monthly' ? 'Mensualizados' : viewingEmp.overSalaryType === 'accumulate' ? 'Acumulados' : 'N/A'}</p>
               </div>
               <div className="p-4 bg-slate-50 rounded-xl">
                  <p className="text-slate-400 font-black text-[8px] mb-1">Datos Bancarios</p>
                  <p>{viewingEmp.bankInfo?.ifi || 'N/A'}</p>
                  <p>{viewingEmp.bankInfo?.type} - {viewingEmp.bankInfo?.account}</p>
               </div>
            </div>

            <section>
               <div className="flex justify-between items-center mb-4">
                  <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Historial de Novedades</h4>
                  {viewingEmp.status === 'active' && <button onClick={() => setIsAbsenceModalOpen(true)} className="px-3 py-1.5 bg-blue-50 text-blue-600 rounded-lg text-[8px] font-black uppercase">Nueva Novedad</button>}
               </div>
               <div className="bg-slate-50 rounded-2xl overflow-hidden border max-h-48 overflow-y-auto custom-scroll">
                  <table className="w-full text-left">
                     <thead className="bg-slate-100 text-[8px] font-black uppercase text-slate-400 sticky top-0">
                        <tr><th className="p-3">Fecha</th><th className="p-3">Tipo</th><th className="p-3">Motivo</th><th className="p-3">Justificado</th></tr>
                     </thead>
                     <tbody className="text-[9px] font-bold uppercase divide-y">
                        {viewingEmp.absences?.map(a => (
                           <tr key={a.id}><td className="p-3">{a.date}</td><td className="p-3">{a.type}</td><td className="p-3">{a.reason}</td><td className="p-3 text-center">{a.justified ? 'SI' : 'NO'}</td></tr>
                        )) || <tr><td colSpan={4} className="p-10 text-center text-slate-300">Sin registros de novedades.</td></tr>}
                     </tbody>
                  </table>
               </div>
            </section>

            {viewingEmp.status === 'active' && role === Role.SUPER_ADMIN && (
              <div className="pt-4 border-t flex justify-end gap-3">
                 <button onClick={() => handleApprovePinReset(viewingEmp)} className="px-4 py-2 bg-slate-100 text-slate-600 rounded-xl text-[9px] font-black uppercase border border-slate-200">Resetear PIN</button>
                 <button onClick={() => setIsTermModalOpen(true)} className="px-4 py-2 bg-red-50 text-red-600 rounded-xl text-[9px] font-black uppercase border border-red-200">Procesar Salida</button>
              </div>
