      <Modal isOpen={feedback.isOpen} onClose={() => setFeedback({...feedback, isOpen: false})} title={feedback.title} type={feedback.type}><div className="text-center p-4"><p className="text-xs font-bold uppercase">{feedback.message}</p><button onClick={() => setFeedback({...feedback, isOpen: false})} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] mt-4">Aceptar</button></div></Modal>
    </div>
  );
};

