              <div className="relative overflow-hidden bg-slate-900 rounded-3xl md:rounded-[3rem] p-8 md:p-12 text-white shadow-2xl min-h-[220px] md:min-h-[300px] flex flex-col justify-center bg-cover bg-center" style={{ backgroundImage: 'linear-gradient(rgba(15, 23, 42, 0.85), rgba(15, 23, 42, 0.85)), url(https://images.unsplash.com/photo-1499750310107-5fef28a66643?auto=format&fit=crop&q=80&w=2070)' }}>
                  <div className="relative z-10 max-w-2xl">
                    <p className="text-blue-400 font-black text-[8px] md:text-[10px] uppercase tracking-[0.4em] md:tracking-[0.5em] mb-3 md:mb-4">Reflexión Estratégica</p>
                    <h2 className="text-2xl md:text-5xl font-[900] leading-tight tracking-tighter italic">"{dailyQuote}"</h2>
                  </div>
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 md:gap-8 items-stretch">
                <div className="bg-white p-6 md:p-10 rounded-3xl md:rounded-[3rem] shadow-sm border border-slate-100 space-y-4 md:space-y-6">
                  <div className="flex items-center gap-4">
                    <span className="text-4xl md:text-5xl">{activeBreak.icon}</span>
