                  <div><label className="text-[9px] font-black text-slate-400 uppercase">Apellidos*</label><input className="w-full border-2 p-3 rounded-xl text-[11px] font-black uppercase" value={form.surname} onChange={e => setForm({...form, surname: e.target.value.toUpperCase()})} /></div>
                  <div><label className="text-[9px] font-black text-slate-400 uppercase">Cédula*</label><input maxLength={10} className="w-full border-2 p-3 rounded-xl text-[11px] font-black" value={form.identification} onChange={e => setForm({...form, identification: e.target.value.replace(/\D/g,'')})} /></div>
                  <div><label className="text-[9px] font-black text-slate-400 uppercase">Nacimiento</label><input type="date" className="w-full border-2 p-3 rounded-xl text-[11px] font-black" value={form.birthDate} onChange={e => setForm({...form, birthDate: e.target.value})} /></div>
               </div>
            </section>
            <section className="border-b pb-6">
               <h4 className="text-[10px] font-black text-blue-600 uppercase tracking-widest mb-4">II. Laboral</h4>
               <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div className="sm:col-span-2">
                    <label className="text-[9px] font-black text-slate-400 uppercase">Cargo*</label>
                    <select className="w-full border-2 p-3 rounded-xl text-[11px] font-black" value={form.role} onChange={e => setForm({...form, role: e.target.value as Role})}>
                      {Object.values(Role).map(r => <option key={r} value={r}>{r}</option>)}
                    </select>
                  </div>
                  <div><label className="text-[9px] font-black text-slate-400 uppercase">Sueldo*</label><input type="number" step="0.01" className="w-full border-2 p-3 rounded-xl text-[11px] font-black" value={form.salary} onChange={e => setForm({...form, salary: Number(e.target.value)})} /></div>
