import React, { useState } from 'react';
import { Employee, Payment, AttendanceRecord, CompanyConfig, GlobalSettings, Role } from '../../types.ts';
import { db, doc, setDoc, deleteDoc, compressData } from '../../firebase.ts';
import Modal from '../../components/Modal.tsx';

interface ReportsModuleProps {
  employees: Employee[];
  payments: Payment[];
  attendance: AttendanceRecord[];
  company: CompanyConfig | null;
  settings: GlobalSettings;
  role: Role;
}

const ReportsModule: React.FC<ReportsModuleProps> = ({ employees, payments, attendance, company, settings, role }) => {
  const [reportType, setReportType] = useState<'attendance' | 'payments' | 'validation'>('attendance');
  const [searchTerm, setSearchTerm] = useState('');
  const [feedback, setFeedback] = useState({ isOpen: false, title: '', message: '', type: 'success' as any });

  const pendingAttendance = attendance.filter(a => a.status === 'pending_approval');

  const handleValidate = async (record: AttendanceRecord, newStatus: 'confirmed' | 'rejected') => {
    const updatedRecord = { 
      ...record, 
      status: newStatus,
      validatedAt: new Date().toISOString()
    };

    await setDoc(doc(db, "attendance", record.id), { payload: compressData(updatedRecord), timestamp: record.timestamp });
    setFeedback({ isOpen: true, title: "Actualizado", message: `El marcaje ha sido procesado.`, type: 'success' });
  };

  const handleDeleteAttendance = async (id: string) => {
    if (confirm("¿Eliminar registro permanentemente?")) {
      try {
        await deleteDoc(doc(db, "attendance", id));
        setFeedback({ isOpen: true, title: "Eliminado", message: "Registro borrado correctamente.", type: 'success' });
      } catch (e) {
        setFeedback({ isOpen: true, title: "Error", message: "No se pudo eliminar.", type: 'error' });
      }
    }
  };

  const filteredPending = pendingAttendance.filter(req => {
    const emp = employees.find(e => e.id === req.employeeId);
    const searchStr = (emp?.name + " " + emp?.surname + " " + emp?.identification + " " + (req.justification || "")).toLowerCase();
    return searchStr.includes(searchTerm.toLowerCase());
  });

  const exportAttendanceExcel = () => {
    let csv = "Fecha,Hora,Empleado,Tipo,Estado,Atraso\n";
    attendance.sort((a, b) => b.timestamp.localeCompare(a.timestamp)).forEach(rec => {
      const emp = employees.find(e => e.id === rec.employeeId);
      const date = new Date(rec.timestamp);
      csv += `${date.toLocaleDateString()},${date.toLocaleTimeString()},${emp?.surname} ${emp?.name},${rec.type === 'in' ? 'Entrada' : 'Salida'},${rec.status},${rec.isLate ? 'SI' : 'NO'}\n`;
    });
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `Reporte_Asistencia.csv`;
    link.click();
  };

  return (
    <div className="space-y-6 md:space-y-8 fade-in">
      <div className="flex flex-col md:flex-row justify-between items-center bg-white p-6 md:p-8 rounded-3xl md:rounded-[2rem] shadow-sm border border-slate-100 gap-6">
        <div className="w-full">
          <h2 className="text-xl md:text-2xl font-black text-slate-900 uppercase text-center md:text-left">Reportes</h2>
          <div className="flex flex-col sm:flex-row gap-4 mt-4">
            <div className="flex gap-2 overflow-x-auto pb-2 sm:pb-0 scroll-smooth no-scrollbar">
              <button onClick={() => setReportType('attendance')} className={`whitespace-nowrap px-4 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest ${reportType === 'attendance' ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-100 text-slate-400'}`}>Asistencia</button>
              <button onClick={() => setReportType('payments')} className={`whitespace-nowrap px-4 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest ${reportType === 'payments' ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-100 text-slate-400'}`}>Pagos</button>
              <button onClick={() => setReportType('validation')} className={`whitespace-nowrap px-4 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest relative ${reportType === 'validation' ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-100 text-slate-400'}`}>
                Validar
                {pendingAttendance.length > 0 && <span className="absolute -top-1 -right-1 w-4 h-4 bg-red-500 text-white text-[8px] rounded-full flex items-center justify-center font-black">{pendingAttendance.length}</span>}
              </button>
            </div>
            <input 
              type="text" 
              placeholder="Buscar..." 
              className="flex-1 p-2.5 border rounded-xl text-[10px] font-bold uppercase" 
              value={searchTerm} 
              onChange={e => setSearchTerm(e.target.value)}
            />
          </div>
        </div>
        <div className="flex gap-2 w-full md:w-auto">
          <button onClick={exportAttendanceExcel} className="flex-1 md:flex-none px-6 py-4 bg-emerald-600 text-white font-black rounded-xl shadow-lg uppercase text-[9px] active:scale-95">Excel</button>
          <button onClick={() => window.print()} className="flex-1 md:flex-none px-6 py-4 bg-slate-900 text-white font-black rounded-xl shadow-lg uppercase text-[9px] active:scale-95">Print</button>
        </div>
      </div>

      <div className="bg-white rounded-3xl md:rounded-[2rem] shadow-sm border overflow-hidden min-h-[400px]">
         <div className="p-6 md:p-10">
            {reportType === 'validation' ? (
              <div className="space-y-6">
                <h3 className="text-lg font-black text-slate-900 uppercase">Validaciones Pendientes</h3>
                {filteredPending.length === 0 ? (
                  <div className="py-20 text-center bg-slate-50 rounded-2xl border-2 border-dashed">
                    <p className="text-slate-400 font-black uppercase text-[10px]">Sin pendientes.</p>
                  </div>
                ) : (
                  <div className="space-y-4">
                    {filteredPending.map(req => {
                      const emp = employees.find(e => e.id === req.employeeId);
                      return (
                        <div key={req.id} className="bg-white border rounded-2xl p-5 flex flex-col gap-4">
                          <div className="flex justify-between items-start">
                            <div>
                              <p className="font-black text-slate-900 uppercase text-xs">{emp?.surname} {emp?.name}</p>
                              <p className="text-slate-400 font-black text-[8px] uppercase mt-1">{new Date(req.timestamp).toLocaleString()}</p>
                            </div>
                            <span className="px-2 py-1 bg-blue-50 text-blue-700 text-[8px] font-black rounded-lg uppercase">{req.type}</span>
                          </div>
                          <p className="text-[10px] text-slate-500 italic bg-slate-50 p-3 rounded-xl border leading-relaxed">Justifica: {req.justification}</p>
                          <div className="grid grid-cols-2 gap-2">
                             <button onClick={() => handleValidate(req, 'rejected')} className="py-3 bg-red-50 text-red-600 font-black text-[9px] uppercase rounded-xl active:scale-95">Rechazar</button>
                             <button onClick={() => handleValidate(req, 'confirmed')} className="py-3 bg-emerald-600 text-white font-black text-[9px] uppercase rounded-xl shadow active:scale-95">Aprobar</button>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                )}
              </div>
            ) : (
               <div className="table-responsive">
                  <table className="w-full text-left min-w-[700px]">
                    <thead className="bg-slate-50 text-[9px] font-black uppercase text-slate-400 border-b">
                      <tr>
                        <th className="p-4">Fecha/Hora</th>
                        <th className="p-4">Colaborador</th>
                        <th className="p-4">Tipo</th>
                        <th className="p-4">Estado</th>
                        <th className="p-4 text-right no-print">Acción</th>
                      </tr>
                    </thead>
                    <tbody className="text-[10px] font-bold uppercase divide-y">
                      {attendance.filter(a => {
                        const emp = employees.find(e => e.id === a.employeeId);
                        return (emp?.surname + " " + emp?.name).toLowerCase().includes(searchTerm.toLowerCase());
                      }).sort((a,b) => b.timestamp.localeCompare(a.timestamp)).map(rec => {
                        const emp = employees.find(e => e.id === rec.employeeId);
                        return (
                          <tr key={rec.id} className="hover:bg-slate-50 transition-colors">
                            <td className="p-4 whitespace-nowrap">{new Date(rec.timestamp).toLocaleString()}</td>
                            <td className="p-4 truncate max-w-[150px]">{emp?.surname} {emp?.name}</td>
                            <td className="p-4">{rec.type}</td>
                            <td className="p-4">
                              <span className={`px-2 py-0.5 rounded-lg text-[8px] font-black uppercase ${rec.status === 'confirmed' ? 'bg-emerald-50 text-emerald-600' : 'bg-red-50 text-red-600'}`}>{rec.status}</span>
                            </td>
                            <td className="p-4 text-right no-print">
                              {role === Role.SUPER_ADMIN && (
                                <button onClick={() => handleDeleteAttendance(rec.id)} className="text-red-600 text-[8px] font-black uppercase hover:underline">Eliminar</button>
                              )}
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
               </div>
            )}
         </div>
      </div>

      <Modal isOpen={feedback.isOpen} onClose={() => setFeedback({...feedback, isOpen: false})} title={feedback.title} type={feedback.type}>
          <div className="text-center p-4">
              <p className="text-slate-600 font-bold uppercase text-[11px] leading-relaxed">{feedback.message}</p>
              <button onClick={() => setFeedback({...feedback, isOpen: false})} className="w-full py-3.5 bg-slate-900 text-white font-black rounded-xl uppercase text-[9px] mt-6 active:scale-95">Aceptar</button>
          </div>
      </Modal>
    </div>
  );
};

export default ReportsModule;

import React, { useState, useMemo, useEffect } from 'react';
import { Role, CompanyConfig, Employee, AttendanceRecord, Payment, GlobalSettings, NotificationMessage } from '../types.ts';
import Sidebar from '../components/Sidebar.tsx';
import CompanyModule from './modules/CompanyModule.tsx';
import EmployeeModule from './modules/EmployeeModule.tsx';
import PayrollModule from './modules/PayrollModule.tsx';
import PaymentsModule from './modules/PaymentsModule.tsx';
import SettingsModule from './modules/SettingsModule.tsx';
import ReportsModule from './modules/ReportsModule.tsx';
import AiAssistant from './modules/AiAssistant.tsx';
import NotificationsModule from './modules/NotificationsModule.tsx';
import Modal from '../components/Modal.tsx';
import { DAILY_QUOTES, ACTIVE_BREAKS } from '../constants.tsx';

interface AdminDashboardProps {
  role: Role;
  isDbConnected?: boolean;
  onLogout: () => void;
  company: CompanyConfig | null;
  onUpdateCompany: (config: CompanyConfig) => void;
  employees: Employee[];
  onUpdateEmployees: (employees: Employee[]) => void;
  attendance: AttendanceRecord[];
  payments: Payment[];
  onUpdatePayments: (payments: Payment[]) => void;
  settings: GlobalSettings;
  onUpdateSettings: (settings: GlobalSettings) => void;
  onUpdateAppMode: (mode: 'full' | 'attendance') => void;
  appMode: 'full' | 'attendance';
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  role, isDbConnected, onLogout, company, onUpdateCompany, employees, onUpdateEmployees, attendance, payments, onUpdatePayments, settings, onUpdateSettings, onUpdateAppMode, appMode 
}) => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'company' | 'employees' | 'payroll' | 'payments' | 'settings' | 'reports' | 'ai' | 'notifications'>('dashboard');
  const [showInstallModal, setShowInstallModal] = useState(false);
  const [notifications, setNotifications] = useState<NotificationMessage[]>([]);

  const todayDateStr = useMemo(() => new Date().toISOString().split('T')[0], []);
  const today = useMemo(() => new Date(), []);
  const currentMonth = useMemo(() => today.toLocaleString('es-EC', { month: 'long' }).toUpperCase(), [today]);

  const stats = useMemo(() => {
    const activeEmps = employees.filter(e => e.status === 'active');
    const todayMarks = attendance.filter(a => a.timestamp.includes(todayDateStr));
    const todayLates = todayMarks.filter(a => a.isLate);
    const monthlyTotal = payments
      .filter(p => p.month === currentMonth && p.status === 'paid')
      .reduce((acc, p) => acc + p.amount, 0);

    return {
      activeCount: activeEmps.length,
      todayMarksCount: todayMarks.length,
      todayLatesCount: todayLates.length,
      payrollTotal: monthlyTotal
    };
  }, [employees, attendance, payments, todayDateStr, currentMonth]);

  const addNotification = (title: string, message: string, type: 'info' | 'alert' | 'critical') => {
    const id = Math.random().toString(36).substr(2, 9);
    setNotifications(prev => {
      if (prev.some(n => n.title === title && n.message === message && !n.isRead && !n.isProcessed)) return prev;
      return [{ id, title, message, timestamp: new Date().toISOString(), type, isRead: false, isProcessed: false }, ...prev];
    });
  };

  useEffect(() => {
    const activeEmployees = employees.filter(e => e.status === 'active');
    const markedTodayIds = new Set(attendance
      .filter(a => a.timestamp.includes(todayDateStr))
      .map(a => a.employeeId));

    const missingAttendanceCount = activeEmployees.filter(e => !markedTodayIds.has(e.id)).length;
    if (missingAttendanceCount > 0 && activeTab === 'dashboard') {
      addNotification(
        "Pendiente de Ingreso", 
        `Hay ${missingAttendanceCount} colaboradores que aún no han registrado su marcación hoy.`, 
        'alert'
      );
    }
  }, [employees, attendance, todayDateStr]);

  const unreadCount = notifications.filter(n => !n.isRead).length;

  const dayOfYear = useMemo(() => {
    const start = new Date(today.getFullYear(), 0, 0);
    const diff = today.getTime() - start.getTime();
    return Math.floor(diff / (1000 * 60 * 60 * 24));
  }, [today]);

  const birthdayPeeps = useMemo(() => {
    return employees.filter(e => {
      if (!e.birthDate || e.status !== 'active') return false;
      const b = new Date(e.birthDate);
      return b.getMonth() === today.getMonth() && b.getDate() === today.getDate();
    });
  }, [employees, today]);

  const dailyQuote = DAILY_QUOTES[dayOfYear % DAILY_QUOTES.length];
  const activeBreak = ACTIVE_BREAKS[dayOfYear % ACTIVE_BREAKS.length];

  const handlePurgeData = async () => {
    if (role !== Role.SUPER_ADMIN) return;
    onUpdateEmployees([]);
    onUpdatePayments([]);
  };

  return (
    <div className="flex h-screen bg-[#fcfdfe] overflow-hidden flex-col md:flex-row">
      <Sidebar 
        role={role} 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        onLogout={onLogout} 
        companyName={company?.name} 
        unreadCount={unreadCount}
      />

      <main className="flex-1 overflow-y-auto px-4 md:px-10 py-6 md:py-10 scroll-smooth custom-scroll">
        <header className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 md:mb-10 gap-4 md:gap-6 no-print pt-14 md:pt-0">
          <div className="flex flex-col sm:flex-row items-start sm:items-center gap-3 sm:gap-4 w-full md:w-auto">
            <h1 className="text-xl md:text-2xl font-[950] text-slate-900 tracking-tight uppercase">Dashboard</h1>
            <div className="flex items-center gap-3 px-3 py-1.5 md:px-4 md:py-2 bg-white border rounded-xl md:rounded-2xl shadow-sm w-fit">
               <div className={`w-2.5 h-2.5 rounded-full ${isDbConnected ? 'bg-emerald-500 shadow-[0_0_12px_#10b981]' : 'bg-red-500 animate-pulse'}`}></div>
               <span className="text-[8px] md:text-[9px] font-black uppercase tracking-[0.2em] text-slate-500">
                 {isDbConnected ? 'Conectado' : 'Sin Red'}
               </span>
            </div>
          </div>
          <div className="flex gap-2 w-full sm:w-auto overflow-x-auto pb-2 sm:pb-0 no-scrollbar">
             <button onClick={() => setActiveTab('ai')} className="whitespace-nowrap px-4 py-2 bg-blue-50 text-blue-700 rounded-xl text-[9px] font-black uppercase border border-blue-100 flex items-center gap-2 hover:bg-blue-100 transition-all">
               <span className="animate-pulse">✨</span> IA Assistant
             </button>
             {(role === Role.SUPER_ADMIN || role === Role.PARTIAL_ADMIN) && (
               <button onClick={() => setShowInstallModal(true)} className="whitespace-nowrap px-4 py-2 bg-slate-900 text-white rounded-xl text-[9px] font-black uppercase border border-slate-900 shadow-xl active:scale-95 transition-all">Estación Kiosco</button>
             )}
          </div>
        </header>

        <div className="animate-in fade-in duration-500 pb-20 md:pb-0">
          {activeTab === 'dashboard' && (
            <div className="space-y-8 md:space-y-12">
              {/* Grid de Métricas Estratégicas */}
              <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6">
                <div className="bg-white p-5 md:p-8 rounded-3xl md:rounded-[2.5rem] border border-slate-100 shadow-sm flex flex-col justify-between group hover:border-blue-500/30 transition-all">
                  <div className="flex justify-between items-start">
                    <span className="text-2xl md:text-3xl">👥</span>
                    <span className="text-[8px] font-black text-emerald-500 uppercase bg-emerald-50 px-2 py-0.5 rounded-lg">Staff</span>
                  </div>
                  <div className="mt-4">
                    <p className="text-2xl md:text-4xl font-[950] text-slate-900 tracking-tighter">{stats.activeCount}</p>
                    <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Colaboradores Activos</p>
                  </div>
                </div>

                <div className="bg-white p-5 md:p-8 rounded-3xl md:rounded-[2.5rem] border border-slate-100 shadow-sm flex flex-col justify-between group hover:border-blue-500/30 transition-all">
                  <div className="flex justify-between items-start">
                    <span className="text-2xl md:text-3xl">⏱️</span>
                    <span className="text-[8px] font-black text-blue-500 uppercase bg-blue-50 px-2 py-0.5 rounded-lg">Hoy</span>
                  </div>
                  <div className="mt-4">
                    <p className="text-2xl md:text-4xl font-[950] text-slate-900 tracking-tighter">{stats.todayMarksCount}</p>
                    <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Marcaciones Ingresadas</p>
                  </div>
                </div>

                <div className="bg-white p-5 md:p-8 rounded-3xl md:rounded-[2.5rem] border border-slate-100 shadow-sm flex flex-col justify-between group hover:border-red-500/30 transition-all">
                  <div className="flex justify-between items-start">
                    <span className="text-2xl md:text-3xl">⚠️</span>
                    <span className="text-[8px] font-black text-red-500 uppercase bg-red-50 px-2 py-0.5 rounded-lg">Alerta</span>
                  </div>
                  <div className="mt-4">
                    <p className="text-2xl md:text-4xl font-[950] text-slate-900 tracking-tighter">{stats.todayLatesCount}</p>
                    <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Retrasos Detectados</p>
                  </div>
                </div>

                <div className="bg-white p-5 md:p-8 rounded-3xl md:rounded-[2.5rem] border border-slate-100 shadow-sm flex flex-col justify-between group hover:border-emerald-500/30 transition-all">
                  <div className="flex justify-between items-start">
                    <span className="text-2xl md:text-3xl">💰</span>
                    <span className="text-[8px] font-black text-slate-500 uppercase bg-slate-100 px-2 py-0.5 rounded-lg">{currentMonth}</span>
                  </div>
                  <div className="mt-4">
                    <p className="text-2xl md:text-4xl font-[950] text-slate-900 tracking-tighter">${stats.payrollTotal.toFixed(2)}</p>
                    <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Total Egresos Mensuales</p>
                  </div>
                </div>
              </div>

              {birthdayPeeps.length > 0 && role === Role.SUPER_ADMIN && (
                <div className="bg-emerald-600 p-6 md:p-8 rounded-3xl md:rounded-[3rem] text-white shadow-xl flex flex-col md:flex-row items-center justify-between gap-6">
                   <div className="flex items-center gap-4 md:gap-6 text-center md:text-left">
                      <span className="text-4xl md:text-5xl">🎂</span>
                      <div>
                         <h3 className="text-lg md:text-xl font-black uppercase tracking-tighter">¡Hoy hay Cumpleaños!</h3>
                         <p className="text-[9px] md:text-[10px] font-bold uppercase tracking-widest opacity-80 mt-1 italic">Celebra el talento de tu equipo</p>
                      </div>
                   </div>
                   <div className="flex -space-x-3 md:-space-x-4">
                      {birthdayPeeps.map(e => (
                         <div key={e.id} className="w-10 h-10 md:w-12 md:h-12 rounded-full border-4 border-emerald-600 bg-white overflow-hidden shadow-md" title={e.name}>
                            {e.photo ? <img src={e.photo} className="w-full h-full object-cover" /> : <div className="flex items-center justify-center h-full text-[10px] text-emerald-600 font-black">{e.name[0]}</div>}
                         </div>
                      ))}
                   </div>
                </div>
              )}

              <div className="relative overflow-hidden bg-slate-900 rounded-3xl md:rounded-[3rem] p-8 md:p-12 text-white shadow-2xl min-h-[220px] md:min-h-[300px] flex flex-col justify-center bg-cover bg-center" style={{ backgroundImage: 'linear-gradient(rgba(15, 23, 42, 0.85), rgba(15, 23, 42, 0.85)), url(https://images.unsplash.com/photo-1499750310107-5fef28a66643?auto=format&fit=crop&q=80&w=2070)' }}>
                  <div className="relative z-10 max-w-2xl text-center md:text-left">
                    <p className="text-blue-400 font-black text-[8px] md:text-[10px] uppercase tracking-[0.4em] md:tracking-[0.5em] mb-3 md:mb-4">Reflexión Estratégica</p>
                    <h2 className="text-xl md:text-5xl font-[900] leading-tight tracking-tighter italic">"{dailyQuote}"</h2>
                  </div>
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 md:gap-8 items-stretch">
                <div className="bg-white p-6 md:p-10 rounded-3xl md:rounded-[3rem] shadow-sm border border-slate-100 space-y-4 md:space-y-6">
                  <div className="flex items-center gap-4">
                    <span className="text-4xl md:text-5xl">{activeBreak.icon}</span>
                    <div>
                      <h3 className="text-lg md:text-xl font-black text-slate-900 uppercase">Pausa Saludable</h3>
                      <p className="text-[9px] md:text-[10px] font-black text-blue-600 uppercase tracking-widest">Bienestar Laboral</p>
                    </div>
                  </div>
                  <div className="space-y-3 md:space-y-4">
                    <h4 className="text-base md:text-lg font-extrabold text-slate-800">{activeBreak.title}</h4>
                    <p className="text-slate-500 text-sm md:text-base leading-relaxed font-medium">{activeBreak.description}</p>
                  </div>
                </div>

                <div className="relative overflow-hidden bg-white rounded-3xl md:rounded-[3rem] shadow-sm border border-slate-100 h-[200px] md:h-auto hidden sm:block">
                   <img 
                     src="https://images.unsplash.com/photo-1470770841072-f978cf4d019e?auto=format&fit=crop&q=80&w=2070" 
                     alt="Paisaje Relajante" 
                     className="w-full h-full object-cover transition-transform duration-700 hover:scale-105"
                   />
                </div>
              </div>
            </div>
          )}

          {activeTab === 'notifications' && (
            <NotificationsModule 
              notifications={notifications} 
              onToggleRead={(id) => setNotifications(prev => prev.map(n => n.id === id ? { ...n, isRead: !n.isRead } : n))}
              onToggleProcessed={(id) => setNotifications(prev => prev.map(n => n.id === id ? { ...n, isProcessed: !n.isProcessed } : n))}
              onClearAll={() => setNotifications([])}
            />
          )}

          {activeTab === 'company' && <CompanyModule company={company} onUpdate={onUpdateCompany} role={role} />}
          {activeTab === 'employees' && <EmployeeModule employees={employees} onUpdate={onUpdateEmployees} role={role} attendance={attendance} payments={payments} company={company} />}
          {activeTab === 'payroll' && <PayrollModule employees={employees} payments={payments} company={company} settings={settings} role={role} />}
          {activeTab === 'payments' && <PaymentsModule employees={employees} payments={payments} onUpdate={onUpdatePayments} role={role} />}
          {activeTab === 'settings' && <SettingsModule settings={settings} onUpdate={onUpdateSettings} role={role} onPurge={handlePurgeData} allData={{ company, employees, attendance, payments, settings }} />}
          {activeTab === 'reports' && <ReportsModule employees={employees} payments={payments} attendance={attendance} company={company} settings={settings} role={role} />}
          {activeTab === 'ai' && <AiAssistant employees={employees} attendance={attendance} payments={payments} role={role} />}
        </div>
      </main>

      <Modal isOpen={showInstallModal} onClose={() => setShowInstallModal(false)} title="Modo de Estación" maxWidth="max-w-md">
         <div className="space-y-6">
            <p className="text-[11px] text-slate-500 text-center font-bold uppercase tracking-widest">Seleccione la interfaz para este dispositivo:</p>
            <div className="space-y-3">
               <button onClick={() => { onUpdateAppMode('full'); setShowInstallModal(false); }} className={`w-full p-6 rounded-2xl border-2 text-left flex items-center justify-between transition-all ${appMode === 'full' ? 'border-blue-600 bg-blue-50' : 'border-slate-100'}`}>
                  <div>
                    <p className="font-black text-sm text-slate-900 uppercase">Administrativa Full</p>
                    <p className="text-[10px] text-slate-400 font-bold uppercase mt-1">Acceso total a gestión.</p>
                  </div>
               </button>
               <button onClick={() => { onUpdateAppMode('attendance'); setShowInstallModal(false); }} className={`w-full p-6 rounded-2xl border-2 text-left flex items-center justify-between transition-all ${appMode === 'attendance' ? 'border-blue-600 bg-blue-50' : 'border-slate-100'}`}>
                  <div>
                    <p className="font-black text-sm text-slate-900 uppercase">Marcación Only</p>
                    <p className="text-[10px] text-slate-400 font-bold uppercase mt-1">Kiosco de asistencia.</p>
                  </div>
               </button>
            </div>
         </div>
      </Modal>
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useMemo, useEffect } from 'react';
import { Role, CompanyConfig, Employee, AttendanceRecord, Payment, GlobalSettings, NotificationMessage } from '../types.ts';
import Sidebar from '../components/Sidebar.tsx';
import CompanyModule from './modules/CompanyModule.tsx';
import EmployeeModule from './modules/EmployeeModule.tsx';
import PayrollModule from './modules/PayrollModule.tsx';
import PaymentsModule from './modules/PaymentsModule.tsx';
import SettingsModule from './modules/SettingsModule.tsx';
import ReportsModule from './modules/ReportsModule.tsx';
import AiAssistant from './modules/AiAssistant.tsx';
import NotificationsModule from './modules/NotificationsModule.tsx';
import Modal from '../components/Modal.tsx';
import { DAILY_QUOTES, ACTIVE_BREAKS, ECUADOR_HOLIDAYS } from '../constants.tsx';

interface AdminDashboardProps {
  role: Role;
  isDbConnected?: boolean;
  onLogout: () => void;
  company: CompanyConfig | null;
  onUpdateCompany: (config: CompanyConfig) => void;
  employees: Employee[];
  onUpdateEmployees: (employees: Employee[]) => void;
  attendance: AttendanceRecord[];
  payments: Payment[];
  onUpdatePayments: (payments: Payment[]) => void;
  settings: GlobalSettings;
  onUpdateSettings: (settings: GlobalSettings) => void;
  onUpdateAppMode: (mode: 'full' | 'attendance') => void;
  appMode: 'full' | 'attendance';
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  role, isDbConnected, onLogout, company, onUpdateCompany, employees, onUpdateEmployees, attendance, payments, onUpdatePayments, settings, onUpdateSettings, onUpdateAppMode, appMode 
}) => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'company' | 'employees' | 'payroll' | 'payments' | 'settings' | 'reports' | 'ai' | 'notifications'>('dashboard');
  const [showInstallModal, setShowInstallModal] = useState(false);
  const [notifications, setNotifications] = useState<NotificationMessage[]>([]);

  const today = useMemo(() => new Date(), []);
  const todayDateStr = useMemo(() => today.toISOString().split('T')[0], [today]);
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();

  const addNotification = (title: string, message: string, type: 'info' | 'alert' | 'critical') => {
    const id = Math.random().toString(36).substr(2, 9);
    setNotifications(prev => {
      if (prev.some(n => n.title === title && n.message === message && !n.isRead && !n.isProcessed)) return prev;
      return [{ id, title, message, timestamp: new Date().toISOString(), type, isRead: false, isProcessed: false }, ...prev];
    });
  };

  useEffect(() => {
    const activeEmployees = employees.filter(e => e.status === 'active');
    const markedTodayIds = new Set(attendance
      .filter(a => a.timestamp.includes(todayDateStr))
      .map(a => a.employeeId));

    const missingAttendanceCount = activeEmployees.filter(e => !markedTodayIds.has(e.id)).length;
    if (missingAttendanceCount > 0 && activeTab === 'dashboard') {
      addNotification(
        "Pendiente de Ingreso", 
        `Hay ${missingAttendanceCount} colaboradores que aún no han registrado su marcación hoy.`, 
        'alert'
      );
    }
  }, [employees, attendance, todayDateStr, activeTab]);

  const unreadCount = notifications.filter(n => !n.isRead).length;

  const dayOfYear = useMemo(() => {
    const start = new Date(today.getFullYear(), 0, 0);
    const diff = today.getTime() - start.getTime();
    return Math.floor(diff / (1000 * 60 * 60 * 24));
  }, [today]);

  const dailyQuote = DAILY_QUOTES[dayOfYear % DAILY_QUOTES.length];
  const activeBreak = ACTIVE_BREAKS[dayOfYear % ACTIVE_BREAKS.length];

  // Imágenes relajantes (Paisajes y Arte)
  const relaxingImages = [
    "https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&q=80&w=2070",
    "https://images.unsplash.com/photo-1441974231531-c6227db76b6e?auto=format&fit=crop&q=80&w=2071",
    "https://images.unsplash.com/photo-1579783902614-a3fb3927b6a5?auto=format&fit=crop&q=80&w=2070",
    "https://images.unsplash.com/photo-1541450805268-4822a3a774ce?auto=format&fit=crop&q=80&w=2070"
  ];
  const currentRelaxingImage = relaxingImages[dayOfYear % relaxingImages.length];

  // Lógica del Calendario
  const calendarDays = useMemo(() => {
    const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
    const firstDay = new Date(currentYear, currentMonth, 1).getDay();
    const days = [];
    for (let i = 0; i < firstDay; i++) days.push(null);
    for (let i = 1; i <= daysInMonth; i++) days.push(i);
    return days;
  }, [currentMonth, currentYear]);

  const monthHolidays = ECUADOR_HOLIDAYS.filter(h => h.month === currentMonth);
  const monthBirthdays = employees.filter(e => {
    if (!e.birthDate || e.status !== 'active') return false;
    return new Date(e.birthDate).getMonth() === currentMonth;
  });

  const handlePurgeData = async () => {
    if (role !== Role.SUPER_ADMIN) return;
    onUpdateEmployees([]);
    onUpdatePayments([]);
  };

  return (
    <div className="flex h-screen bg-[#fcfdfe] overflow-hidden flex-col md:flex-row">
      <Sidebar 
        role={role} 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        onLogout={onLogout} 
        companyName={company?.name} 
        unreadCount={unreadCount}
      />

      <main className="flex-1 overflow-y-auto px-4 md:px-10 py-6 md:py-10 scroll-smooth custom-scroll">
        <header className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 md:mb-8 gap-4 md:gap-6 no-print pt-14 md:pt-0">
          <div className="flex flex-col sm:flex-row items-start sm:items-center gap-3 sm:gap-4 w-full md:w-auto">
            <h1 className="text-xl md:text-2xl font-[950] text-slate-900 tracking-tight uppercase">Bienvenido</h1>
            <div className="flex items-center gap-3 px-3 py-1.5 md:px-4 md:py-2 bg-white border rounded-xl shadow-sm w-fit">
               <div className={`w-2 h-2 rounded-full ${isDbConnected ? 'bg-emerald-500' : 'bg-red-500'}`}></div>
               <span className="text-[8px] font-black uppercase tracking-[0.2em] text-slate-500">Sistema Activo</span>
            </div>
          </div>
        </header>

        <div className="animate-in fade-in duration-500 pb-20 md:pb-0">
          {activeTab === 'dashboard' && (
            <div className="space-y-6 md:space-y-10">

              {/* Tarjeta de Frase Motivacional Reducida */}
              <div className="relative overflow-hidden bg-slate-900 rounded-3xl md:rounded-[2.5rem] p-6 md:p-8 text-white shadow-xl min-h-[100px] md:min-h-[140px] flex items-center bg-cover bg-center" style={{ backgroundImage: `linear-gradient(rgba(15, 23, 42, 0.7), rgba(15, 23, 42, 0.7)), url(${currentRelaxingImage})` }}>
                  <div className="relative z-10 w-full text-center md:text-left">
                    <p className="text-blue-400 font-black text-[7px] md:text-[8px] uppercase tracking-[0.4em] mb-2">Mensaje del día</p>
                    <h2 className="text-lg md:text-2xl font-[800] leading-tight tracking-tight italic">"{dailyQuote}"</h2>
                  </div>
              </div>

              {/* Calendario y Eventos del Mes */}
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                <div className="lg:col-span-2 bg-white p-6 md:p-8 rounded-3xl border border-slate-100 shadow-sm">
                   <div className="flex justify-between items-center mb-6">
                      <h3 className="text-xs font-black text-slate-900 uppercase tracking-widest">Calendario Institucional - {today.toLocaleString('es-EC', { month: 'long' }).toUpperCase()}</h3>
                      <div className="flex gap-2">
                         <span className="flex items-center gap-1.5 text-[7px] font-black text-blue-600 uppercase"><div className="w-1.5 h-1.5 bg-blue-600 rounded-full"></div> Festivo</span>
                         <span className="flex items-center gap-1.5 text-[7px] font-black text-emerald-600 uppercase"><div className="w-1.5 h-1.5 bg-emerald-600 rounded-full"></div> Cumpleaños</span>
                      </div>
                   </div>
                   <div className="grid grid-cols-7 gap-1 md:gap-2 text-center">
                      {['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'].map(d => (
                        <div key={d} className="text-[8px] font-black text-slate-400 uppercase py-2">{d}</div>
                      ))}
                      {calendarDays.map((day, i) => {
                        const isHoliday = day && monthHolidays.some(h => h.day === day);
                        const isBirthday = day && monthBirthdays.some(e => new Date(e.birthDate).getDate() === day);
                        const isToday = day === today.getDate();

                        return (
                          <div key={i} className={`
                            relative aspect-square flex items-center justify-center text-[10px] md:text-xs font-bold rounded-xl md:rounded-2xl transition-all
                            ${!day ? 'opacity-0' : 'hover:bg-slate-50 cursor-default'}
                            ${isToday ? 'bg-slate-900 text-white shadow-lg z-10' : 'text-slate-600'}
                            ${isHoliday ? 'border-2 border-blue-500 text-blue-600' : ''}
                            ${isBirthday ? 'border-2 border-emerald-500 text-emerald-600' : ''}
                          `}>
                            {day}
                            {(isHoliday || isBirthday) && (
                               <div className={`absolute -bottom-1 w-1 h-1 rounded-full ${isHoliday ? 'bg-blue-500' : 'bg-emerald-500'}`}></div>
                            )}
                          </div>
                        );
                      })}
                   </div>
                </div>

                <div className="bg-slate-50 p-6 md:p-8 rounded-3xl border border-slate-100 space-y-6">
                   <h3 className="text-[9px] font-black text-slate-400 uppercase tracking-[0.2em] border-b pb-3">Eventos del Mes</h3>
                   <div className="space-y-4 max-h-[300px] overflow-y-auto custom-scroll pr-2">
                      {monthHolidays.map((h, i) => (
                         <div key={i} className="flex gap-3 items-center bg-white p-3 rounded-2xl shadow-sm border border-blue-50">
                            <span className="text-xl">📅</span>
                            <div>
                               <p className="text-[9px] font-black text-slate-900 uppercase leading-none">{h.name}</p>
                               <p className="text-[7px] font-bold text-blue-500 uppercase mt-1">Día {h.day}</p>
                            </div>
                         </div>
                      ))}
                      {monthBirthdays.map((e, i) => (
                         <div key={i} className="flex gap-3 items-center bg-white p-3 rounded-2xl shadow-sm border border-emerald-50">
                            <div className="w-8 h-8 rounded-full overflow-hidden border bg-slate-50 flex items-center justify-center text-[10px]">
                               {e.photo ? <img src={e.photo} className="w-full h-full object-cover" /> : <span>👤</span>}
                            </div>
                            <div>
                               <p className="text-[9px] font-black text-slate-900 uppercase leading-none truncate max-w-[120px]">{e.name} {e.surname}</p>
                               <p className="text-[7px] font-bold text-emerald-500 uppercase mt-1">Cumpleaños: {new Date(e.birthDate).getDate()}</p>
                            </div>
                         </div>
                      ))}
                      {monthHolidays.length === 0 && monthBirthdays.length === 0 && (
                        <p className="text-[8px] text-slate-400 font-bold uppercase text-center py-10">Sin eventos próximos registrados</p>
                      )}
                   </div>
                </div>
              </div>

              {/* Pausas Activas e Imagen Relajante */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 items-stretch">
                <div className="bg-white p-6 md:p-10 rounded-3xl border border-slate-100 flex flex-col justify-center">
                  <div className="flex items-center gap-5 mb-6">
                    <span className="text-4xl md:text-5xl">{activeBreak.icon}</span>
                    <div>
                      <h3 className="text-base md:text-lg font-black text-slate-900 uppercase">Pausa Saludable</h3>
                      <p className="text-[8px] font-black text-blue-600 uppercase tracking-widest">Recomendación de Salud Ocupacional</p>
                    </div>
                  </div>
                  <div className="space-y-3">
                    <h4 className="text-sm md:text-base font-[900] text-slate-800 uppercase tracking-tight">{activeBreak.title}</h4>
                    <p className="text-slate-500 text-xs md:text-sm leading-relaxed font-medium">{activeBreak.description}</p>
                  </div>
                </div>

                <div className="relative overflow-hidden bg-white rounded-3xl shadow-lg border border-slate-100 min-h-[200px]">
                   <img 
                     src={currentRelaxingImage} 
                     alt="Inspiración Visual" 
                     className="w-full h-full object-cover transition-transform duration-[20s] hover:scale-125"
                   />
                   <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent flex items-end p-6">
                      <p className="text-[8px] font-black text-white/50 uppercase tracking-[0.5em]">Ambiente Zen Corporativo</p>
                   </div>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'notifications' && (
            <NotificationsModule 
              notifications={notifications} 
              onToggleRead={(id) => setNotifications(prev => prev.map(n => n.id === id ? { ...n, isRead: !n.isRead } : n))}
              onToggleProcessed={(id) => setNotifications(prev => prev.map(n => n.id === id ? { ...n, isProcessed: !n.isProcessed } : n))}
              onClearAll={() => setNotifications([])}
            />
          )}

          {activeTab === 'company' && <CompanyModule company={company} onUpdate={onUpdateCompany} role={role} />}
          {activeTab === 'employees' && <EmployeeModule employees={employees} onUpdate={onUpdateEmployees} role={role} attendance={attendance} payments={payments} company={company} />}
          {activeTab === 'payroll' && <PayrollModule employees={employees} payments={payments} company={company} settings={settings} role={role} />}
          {activeTab === 'payments' && <PaymentsModule employees={employees} payments={payments} onUpdate={onUpdatePayments} role={role} />}
          {activeTab === 'settings' && <SettingsModule settings={settings} onUpdate={onUpdateSettings} role={role} onPurge={handlePurgeData} allData={{ company, employees, attendance, payments, settings }} />}
          {activeTab === 'reports' && <ReportsModule employees={employees} payments={payments} attendance={attendance} company={company} settings={settings} role={role} />}
          {activeTab === 'ai' && <AiAssistant employees={employees} attendance={attendance} payments={payments} role={role} />}
        </div>
      </main>

      <Modal isOpen={showInstallModal} onClose={() => setShowInstallModal(false)} title="Modo de Estación" maxWidth="max-w-md">
         <div className="space-y-6">
            <p className="text-[11px] text-slate-500 text-center font-bold uppercase tracking-widest">Seleccione la interfaz para este dispositivo:</p>
            <div className="space-y-3">
               <button onClick={() => { onUpdateAppMode('full'); setShowInstallModal(false); }} className={`w-full p-6 rounded-2xl border-2 text-left flex items-center justify-between transition-all ${appMode === 'full' ? 'border-blue-600 bg-blue-50' : 'border-slate-100'}`}>
                  <div>
                    <p className="font-black text-sm text-slate-900 uppercase">Administrativa Full</p>
                    <p className="text-[10px] text-slate-400 font-bold uppercase mt-1">Acceso total a gestión.</p>
                  </div>
               </button>
               <button onClick={() => { onUpdateAppMode('attendance'); setShowInstallModal(false); }} className={`w-full p-6 rounded-2xl border-2 text-left flex items-center justify-between transition-all ${appMode === 'attendance' ? 'border-blue-600 bg-blue-50' : 'border-slate-100'}`}>
                  <div>
                    <p className="font-black text-sm text-slate-900 uppercase">Marcación Only</p>
                    <p className="text-[10px] text-slate-400 font-bold uppercase mt-1">Kiosco de asistencia.</p>
                  </div>
               </button>
            </div>
         </div>
      </Modal>
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useEffect } from 'react';
import { Employee, Role, BloodType, Gender, CivilStatus, AbsenceRecord, TerminationReason } from '../../types.ts';
import Modal from '../../components/Modal.tsx';

interface EmployeeModuleProps {
  employees: Employee[];
  onUpdate: (employees: Employee[]) => void;
  role: Role;
  attendance: any[];
  payments: any[];
  company: any;
}

const EmployeeModule: React.FC<EmployeeModuleProps> = ({ employees, onUpdate, role }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingEmp, setEditingEmp] = useState<Employee | null>(null);
  const [viewingEmp, setViewingEmp] = useState<Employee | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [showArchived, setShowArchived] = useState(false);
  const [hasBankInfo, setHasBankInfo] = useState(true);

  const [isAbsenceModalOpen, setIsAbsenceModalOpen] = useState(false);
  const [isTermModalOpen, setIsTermModalOpen] = useState(false);
  const [newAbsence, setNewAbsence] = useState<Partial<AbsenceRecord>>({ type: 'Falta', justified: false, date: new Date().toISOString().split('T')[0], reason: '' });
  const [termData, setTermData] = useState({ reason: TerminationReason.VOLUNTARY, details: '', date: new Date().toISOString().split('T')[0] });

  const [feedback, setFeedback] = useState<{isOpen: boolean, title: string, message: string, type: 'success' | 'error' | 'info'}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  const initialForm: Partial<Employee> = {
    name: '', surname: '', identification: '', birthDate: '', phone: '', email: '', 
    gender: Gender.MASCULINO, civilStatus: CivilStatus.SOLTERO,
    origin: 'ECUATORIANA', address: '', 
    bloodType: BloodType.O_POS, startDate: new Date().toISOString().split('T')[0],
    role: Role.EMPLOYEE, salary: 482.00, status: 'active' as const, photo: '', pin: '',
    emergencyContact: { name: '', phone: '' },
    isFixed: true, isAffiliated: true, overSalaryType: 'monthly',
    bankInfo: { ifi: '', type: 'Ahorros', account: '' },
    absences: [],
    observations: []
  };

  const [form, setForm] = useState<Partial<Employee>>(initialForm);

  useEffect(() => {
    if (!form.isAffiliated && form.overSalaryType !== 'none') {
      setForm(prev => ({ ...prev, overSalaryType: 'none' }));
    }
  }, [form.isAffiliated]);

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setForm(prev => ({ ...prev, photo: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSave = () => {
    if (!form.name || !form.surname || !form.identification || !form.salary || !form.role) {
      setFeedback({ isOpen: true, title: "Error", message: "Nombres, apellidos, cédula, cargo y sueldo son obligatorios.", type: "error" });
      return;
    }
    const finalForm = { ...form };
    if (!hasBankInfo) finalForm.bankInfo = { ifi: 'NO APLICA', type: 'Ahorros', account: 'N/A' };

    let updatedList: Employee[];
    if (editingEmp) {
      updatedList = employees.map(e => e.id === editingEmp.id ? { ...e, ...finalForm } as Employee : e);
      setFeedback({ isOpen: true, title: "Éxito", message: "Expediente actualizado correctamente.", type: "success" });
    } else {
      const autoPin = Math.floor(100000 + Math.random() * 900000).toString();
      const newEmp: Employee = { 
        ...finalForm, 
        id: Math.random().toString(36).substr(2, 9), 
        pin: autoPin, 
        pinChanged: false, 
        pinNeedsReset: false, 
        pinResetRequested: false,
        absences: [], 
        observations: [], 
        totalHoursWorked: 0, 
        status: 'active' as const 
      } as Employee;
      updatedList = [...employees, newEmp];
      setFeedback({ isOpen: true, title: "Éxito", message: `Colaborador registrado. PIN Inicial: ${autoPin}`, type: "success" });
    }
    onUpdate(updatedList);
    setIsModalOpen(false);
  };

  const handleApprovePinReset = (emp: Employee) => {
    const updated: Employee[] = employees.map(e => e.id === emp.id ? { 
      ...e, 
      pin: "000000", 
      pinNeedsReset: true, 
      pinResetRequested: false,
      pinChanged: false 
    } : e);
    onUpdate(updated);
    setViewingEmp({ ...emp, pinNeedsReset: true, pinResetRequested: false, pin: "000000" });
    setFeedback({ 
      isOpen: true, 
      title: "Reseteo Aprobado", 
      message: `PIN reseteado para ${emp.name}. El empleado debe establecer su clave en el terminal.`, 
      type: "success" 
    });
  };

  const handleAddAbsence = () => {
    if (!viewingEmp) return;
    const record: AbsenceRecord = { ...newAbsence, id: Math.random().toString(36).substr(2, 9) } as AbsenceRecord;
    const updated: Employee[] = employees.map(e => e.id === viewingEmp.id ? { ...e, absences: [...(e.absences || []), record] } : e);
    onUpdate(updated);
    setViewingEmp({ ...viewingEmp, absences: [...(viewingEmp.absences || []), record] });
    setIsAbsenceModalOpen(false);
  };

  const handleTerminate = () => {
    if (!viewingEmp) return;
    const updated: Employee[] = employees.map(e => e.id === viewingEmp.id ? { 
      ...e, 
      status: 'terminated' as const, 
      terminationDate: termData.date, 
      terminationReason: termData.reason, 
      terminationDetails: termData.details 
    } : e);
    onUpdate(updated);
    setViewingEmp(null);
    setIsTermModalOpen(false);
    setFeedback({ isOpen: true, title: "Desvinculación", message: "Estatus del colaborador actualizado.", type: "success" });
  };

  const filteredEmployees = employees.filter(e => {
    const searchString = `${e.name} ${e.surname} ${e.identification} ${e.role} ${e.email} ${e.phone}`.toLowerCase();
    const matchesSearch = searchString.includes(searchTerm.toLowerCase());
    return showArchived ? matchesSearch && e.status === 'archived' : matchesSearch && e.status !== 'archived';
  });

  return (
    <div className="space-y-6 fade-in">
      <div className="bg-white p-6 rounded-3xl md:rounded-[2.5rem] shadow-sm border border-slate-100 flex flex-col md:flex-row justify-between items-center no-print gap-4">
        <div className="w-full md:w-auto text-center md:text-left">
          <h2 className="text-xl font-[950] text-slate-900 tracking-tighter uppercase leading-none">Gestión Humana</h2>
          <div className="flex gap-4 mt-2 justify-center md:justify-start">
            <button onClick={() => setShowArchived(false)} className={`text-[9px] font-black uppercase tracking-widest ${!showArchived ? 'text-blue-600 border-b-2 border-blue-600' : 'text-slate-400'}`}>Activos</button>
            <button onClick={() => setShowArchived(true)} className={`text-[9px] font-black uppercase tracking-widest ${showArchived ? 'text-blue-600 border-b-2 border-blue-600' : 'text-slate-400'}`}>Archivados</button>
          </div>
        </div>
        <div className="flex flex-col sm:flex-row gap-3 w-full md:w-auto">
          <input type="text" placeholder="Buscar por nombre, CI, cargo..." className="w-full sm:w-64 p-3 border rounded-xl text-[11px] uppercase font-bold focus:border-blue-500 outline-none" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
          <button onClick={() => { setForm(initialForm); setEditingEmp(null); setHasBankInfo(true); setIsModalOpen(true); }} className="w-full sm:w-auto px-6 py-3.5 bg-blue-700 text-white font-black rounded-xl shadow-lg uppercase text-[9px] tracking-widest active:scale-95 transition-all">Nuevo Registro</button>
        </div>
      </div>

      <div className="bg-white rounded-3xl md:rounded-[2.5rem] shadow-sm border overflow-hidden no-print">
        <div className="table-responsive">
          <table className="w-full text-left min-w-[600px] md:min-w-full">
            <thead className="bg-slate-50 text-[8px] font-black text-slate-400 uppercase tracking-widest">
              <tr>
                <th className="px-6 py-4">Colaborador</th>
                <th className="px-6 py-4">Identificación</th>
                <th className="px-6 py-4">Cargo</th>
                <th className="px-6 py-4 text-center">Estado</th>
                <th className="px-6 py-4 text-right">Acciones</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50 text-[10px] md:text-[11px] font-black uppercase">
              {filteredEmployees.map(emp => (
                <tr key={emp.id} className="hover:bg-blue-50/40 transition-colors">
                  <td className="px-6 py-3 font-black text-slate-900 flex items-center gap-3">
                    <div className="w-8 h-8 rounded-lg overflow-hidden border bg-slate-100 flex items-center justify-center shrink-0">
                      {emp.photo ? <img src={emp.photo} className="w-full h-full object-cover" /> : <span>👤</span>}
                    </div>
                    <span className="truncate max-w-[120px] md:max-w-none">{emp.surname} {emp.name}</span>
                  </td>
                  <td className="px-6 py-3 font-mono">{emp.identification}</td>
                  <td className="px-6 py-3 text-blue-600 text-[9px]">{emp.role}</td>
                  <td className="px-6 py-3 text-center">
                    <span className={`px-3 py-1 rounded-full text-[8px] font-black uppercase ${emp.status === 'active' ? 'bg-emerald-50 text-emerald-600' : 'bg-red-50 text-red-600'}`}>
                      {emp.status === 'active' ? 'Activo' : 'Salida'}
                    </span>
                  </td>
                  <td className="px-6 py-3 text-right flex gap-2 justify-end">
                     <button onClick={() => setViewingEmp(emp)} className="px-3 py-1.5 bg-blue-50 text-blue-700 rounded-lg text-[8px] font-black uppercase active:scale-95">Expediente</button>
                     {role === Role.SUPER_ADMIN && (
                       <button onClick={() => { setEditingEmp(emp); setForm(emp); setHasBankInfo(emp.bankInfo?.ifi !== 'NO APLICA'); setIsModalOpen(true); }} className="px-3 py-1.5 bg-slate-100 text-slate-600 rounded-lg text-[8px] font-black uppercase active:scale-95">Editar</button>
                     )}
                  </td>
                </tr>
              ))}
              {filteredEmployees.length === 0 && (
                <tr><td colSpan={5} className="p-10 text-center text-[10px] font-black text-slate-400 uppercase">No se encontraron resultados</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      <Modal isOpen={!!viewingEmp} onClose={() => setViewingEmp(null)} title="Expediente de Personal">
        {viewingEmp && (
          <div className="space-y-6">
            <div className="flex flex-col sm:flex-row gap-6 items-center border-b pb-6 text-center sm:text-left">
               <div className="w-24 h-24 rounded-2xl overflow-hidden border bg-slate-100 flex items-center justify-center shadow-lg shrink-0">
                  {viewingEmp.photo ? <img src={viewingEmp.photo} className="w-full h-full object-cover" /> : <span className="text-4xl">👤</span>}
               </div>
               <div className="flex-1">
                  <h3 className="text-xl md:text-2xl font-[950] text-slate-900 uppercase tracking-tighter leading-tight">{viewingEmp.surname} {viewingEmp.name}</h3>
                  <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest mt-1">{viewingEmp.role} | CI: {viewingEmp.identification}</p>
                  <p className="text-[9px] font-bold text-slate-400 mt-1 uppercase">Fecha de Ingreso: {viewingEmp.startDate}</p>
                  {viewingEmp.pinResetRequested && (
                    <div className="mt-4 p-3 bg-red-50 border border-red-100 rounded-xl flex flex-col sm:flex-row items-center justify-between gap-3">
                       <span className="text-[9px] font-black text-red-600 uppercase">Solicitud de Reseteo</span>
                       <button onClick={() => handleApprovePinReset(viewingEmp)} className="w-full sm:w-auto px-4 py-2 bg-red-600 text-white rounded-lg text-[8px] font-black uppercase shadow active:scale-95">Aprobar</button>
                    </div>
                  )}
               </div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 text-[10px] font-bold uppercase">
               <div className="p-4 bg-slate-50 rounded-2xl">
                  <p className="text-slate-400 font-black text-[8px] mb-2">Información de Pago</p>
                  <p className="mb-1">Sueldo: ${viewingEmp.salary.toFixed(2)}</p>
                  <p className="mb-1">Modalidad: {viewingEmp.isFixed ? 'Tiempo Completo' : 'Eventual'}</p>
                  <p className="mb-1">IESS: {viewingEmp.isAffiliated ? 'Afiliado' : 'No Afiliado'}</p>
                  <p>Beneficios: {viewingEmp.overSalaryType === 'monthly' ? 'Mensualizados' : viewingEmp.overSalaryType === 'accumulate' ? 'Acumulados' : 'No Aplica'}</p>
               </div>
               <div className="p-4 bg-slate-50 rounded-2xl">
                  <p className="text-slate-400 font-black text-[8px] mb-2">Contacto de Emergencia</p>
                  <p className="mb-1">{viewingEmp.emergencyContact?.name || 'N/A'}</p>
                  <p>{viewingEmp.emergencyContact?.phone || 'N/A'}</p>
               </div>
            </div>

            <section>
               <div className="flex justify-between items-center mb-4">
                  <h4 className="text-[9px] md:text-[10px] font-black text-slate-400 uppercase tracking-widest">Historial de Novedades</h4>
                  {viewingEmp.status === 'active' && <button onClick={() => setIsAbsenceModalOpen(true)} className="px-3 py-1.5 bg-blue-50 text-blue-600 rounded-lg text-[8px] font-black uppercase">Registrar</button>}
               </div>
               <div className="bg-slate-50 rounded-2xl overflow-hidden border max-h-48 table-responsive custom-scroll">
                  <table className="w-full text-left min-w-[400px]">
                     <thead className="bg-slate-100 text-[8px] font-black uppercase text-slate-400 sticky top-0">
                        <tr><th className="p-3">Fecha</th><th className="p-3">Tipo</th><th className="p-3">Motivo</th><th className="p-3">Just.</th></tr>
                     </thead>
                     <tbody className="text-[9px] font-bold uppercase divide-y">
                        {viewingEmp.absences?.map(a => (
                           <tr key={a.id}><td className="p-3 whitespace-nowrap">{a.date}</td><td className="p-3">{a.type}</td><td className="p-3 truncate max-w-[100px]">{a.reason}</td><td className="p-3 text-center">{a.justified ? 'SI' : 'NO'}</td></tr>
