  const handleVoid = () => {
    if (!voidPay || !voidJustification) return;
    const updated = payments.map(p => p.id === voidPay.id ? { ...p, status: 'void' as const, voidJustification } : p);
    onUpdate(updated);
    setIsVoidModalOpen(false);
