import React, { useState, useEffect, useRef } from 'react';
import { CompanyConfig, Employee, Role, AttendanceRecord, Payment, GlobalSettings } from './types.ts';
import AdminDashboard from './views/AdminDashboard.tsx';
import AttendanceSystem from './views/AttendanceSystem.tsx';
import Modal from './components/Modal.tsx';
import { db, collection, doc, onSnapshot, setDoc, addDoc, deleteDoc, compressData, decompressData } from './firebase.ts';

const App: React.FC = () => {
  const [currentUserRole, setCurrentUserRole] = useState<Role | null>(null);
  const [view, setView] = useState<'selection' | 'admin' | 'attendance'>('selection');
  const [isLoadingData, setIsLoadingData] = useState(true);
  const [isDbConnected, setIsDbConnected] = useState(false);
  const [isAdminLoginModalOpen, setIsAdminLoginModalOpen] = useState(false);
  const [adminPassInput, setAdminPassInput] = useState('');

  const unsubscribesRef = useRef<(() => void)[]>([]);

  const [appMode, setAppMode] = useState<'full' | 'attendance'>(
    (localStorage.getItem('app_mode') as 'full' | 'attendance') || 'full'
  );

  const [showWelcome, setShowWelcome] = useState(false);
  const [showLogoutFeedback, setShowLogoutFeedback] = useState(false);
  const [modalAlert, setModalAlert] = useState<{isOpen: boolean, title: string, message: string, type: 'info' | 'success' | 'error'}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  const [company, setCompany] = useState<CompanyConfig | null>(null);
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);
  const [payments, setPayments] = useState<Payment[]>([]);
  const [settings, setSettings] = useState<GlobalSettings>({
    sbu: 482.00,
    iessRate: 0.0945,
    reserveRate: 0.0833,
    schedule: {
      monFri: { in1: '08:30', out1: '13:00', in2: '15:00', out2: '18:00' },
      sat: { in: '08:30', out: '13:00' },
      halfDayOff: 'Miércoles tarde'
    }
  });

  const showAlert = (title: string, message: string, type: 'info' | 'success' | 'error' = 'info') => {
    setModalAlert({ isOpen: true, title, message, type });
  };

  const cleanListeners = () => {
    unsubscribesRef.current.forEach(unsub => unsub());
    unsubscribesRef.current = [];
  };

  useEffect(() => {
    if ("Notification" in window) {
      Notification.requestPermission();
    }

    const handleEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        setIsAdminLoginModalOpen(false);
        setShowWelcome(false);
        setModalAlert(prev => ({ ...prev, isOpen: false }));
      }
    };
    window.addEventListener('keydown', handleEsc);

    cleanListeners();

    try {
      const unsubCompany = onSnapshot(doc(db, "config", "company"), (docSnap) => {
        if (docSnap.exists()) {
          const data = docSnap.data();
          // Fix: Ensure payload is processed safely. decompressData now handles unknown/any input.
          setCompany(data.payload ? decompressData(data.payload) : data as any);
        }
        setIsDbConnected(true);
        setIsLoadingData(false);
      }, () => setIsDbConnected(false));
      unsubscribesRef.current.push(unsubCompany);

      const unsubEmployees = onSnapshot(collection(db, "employees"), (snapshot) => {
        setEmployees(snapshot.docs.map(d => {
          const raw = d.data();
          // Fix: Removed unnecessary cast. decompressData handles the property access safely.
          return raw.payload ? { ...decompressData(raw.payload), id: d.id } : { ...raw, id: d.id };
        }) as Employee[]);
      });
      unsubscribesRef.current.push(unsubEmployees);

      const unsubAttendance = onSnapshot(collection(db, "attendance"), (snapshot) => {
        setAttendance(snapshot.docs.map(d => {
          const raw = d.data();
          // Fix: Removed unnecessary cast for attendance records processing.
          return raw.payload ? { ...decompressData(raw.payload), id: d.id } : { ...raw, id: d.id };
        }) as AttendanceRecord[]);
      });
      unsubscribesRef.current.push(unsubAttendance);

      const unsubPayments = onSnapshot(collection(db, "payments"), (snapshot) => {
        setPayments(snapshot.docs.map(d => {
          const raw = d.data();
          // Fix: Removed unnecessary cast for payments processing.
          return raw.payload ? { ...decompressData(raw.payload), id: d.id } : { ...raw, id: d.id };
        }) as Payment[]);
      });
      unsubscribesRef.current.push(unsubPayments);

    } catch (e) {
      setIsLoadingData(false);
    }

    return () => {
      window.removeEventListener('keydown', handleEsc);
      cleanListeners();
    };
  }, []);

  const handleAdminLogin = () => {
    let role: Role | null = null;
    if (adminPassInput === 'admin123') role = Role.SUPER_ADMIN;
    else {
      const foundAdmin = employees.find(e => e.pin === adminPassInput && (e.role === Role.SUPER_ADMIN || e.role === Role.PARTIAL_ADMIN));
      if (foundAdmin) role = foundAdmin.role;
    }

    if (role) {
      setCurrentUserRole(role);
      localStorage.setItem('admin_logged_in', 'true');
      setShowWelcome(true);
      setView('admin');
      setIsAdminLoginModalOpen(false);
    } else {
      showAlert("Error de Acceso", "Credencial no válida o sin privilegios.", "error");
    }
    setAdminPassInput('');
  };

  const finalizeLogout = () => {
    setCurrentUserRole(null);
    localStorage.removeItem('admin_logged_in');
    setView('selection');
    setShowLogoutFeedback(false);
  };

  const handleUpdateEmployees = async (emps: Employee[]) => {
    const currentIds = new Set(emps.map(e => e.id));
    const previousIds = new Set(employees.map(e => e.id));

    // Deletions
    for (const id of previousIds) {
      if (!currentIds.has(id)) {
        await deleteDoc(doc(db, "employees", id));
      }
    }

    // Updates/Creations
    for (const e of emps) {
      await setDoc(doc(db, "employees", e.id), { payload: compressData(e) });
    }
  };

  const handleUpdatePayments = async (pys: Payment[]) => {
    const currentIds = new Set(pys.map(p => p.id));
    const previousIds = new Set(payments.map(p => p.id));

    // Deletions
    for (const id of previousIds) {
      if (!currentIds.has(id)) {
        await deleteDoc(doc(db, "payments", id));
      }
    }

    // Updates/Creations
    for (const p of pys) {
      if (p.id.length > 15) {
        await addDoc(collection(db, "payments"), { payload: compressData(p) });
      } else {
        await setDoc(doc(db, "payments", p.id), { payload: compressData(p) });
      }
    }
  };

  if (isLoadingData) return null;

  return (
    <div className="min-h-screen bg-[#f8fafc]">
      {view === 'selection' && (
        <div className="min-h-screen gradient-blue flex flex-col items-center justify-center p-6">
          <div className="w-full max-w-lg bg-white/95 backdrop-blur-3xl p-10 md:p-16 rounded-[4.5rem] shadow-2xl text-center border border-white/20">
            <h1 className="text-4xl md:text-5xl font-[950] text-slate-900 mb-2 tracking-tighter uppercase leading-none">ASIST UP</h1>
            <p className="text-blue-600 font-black uppercase tracking-[0.6em] text-[10px] mb-14">Management Suite</p>

            <div className="space-y-4">
              <button onClick={() => setView('attendance')} className="w-full py-6 bg-blue-700 text-white font-black rounded-[2.5rem] shadow-2xl hover:bg-blue-800 transition-all uppercase text-[11px] tracking-widest active:scale-95">Panel de Asistencia</button>
              <button onClick={() => setIsAdminLoginModalOpen(true)} className="w-full py-5 text-slate-400 font-black hover:text-slate-900 transition-all uppercase text-[10px] tracking-widest">Consola Administrativa</button>
            </div>
          </div>

          <Modal isOpen={isAdminLoginModalOpen} onClose={() => setIsAdminLoginModalOpen(false)} title="Autorización" maxWidth="max-w-[280px]">
            <div className="space-y-6 p-2 text-center">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Contraseña o PIN</p>
              <input 
                type="password"
                value={adminPassInput} 
                onChange={e => setAdminPassInput(e.target.value)} 
                onKeyDown={e => e.key === 'Enter' && handleAdminLogin()} 
                className="w-full border-2 border-slate-100 rounded-2xl p-4 text-center text-2xl font-black focus:border-blue-600 outline-none bg-slate-50" 
                placeholder="••••••" 
                autoFocus 
              />
              <button onClick={handleAdminLogin} className="w-full py-4 bg-blue-700 text-white font-black rounded-xl uppercase text-[11px] tracking-widest shadow-2xl active:scale-95 transition-all">Ingresar</button>
            </div>
          </Modal>
        </div>
      )}

      {view === 'attendance' && (
        <AttendanceSystem 
          employees={employees} 
          attendance={attendance} 
          onBack={() => setView('selection')} 
          settings={settings} 
          onRegister={async (r) => { await addDoc(collection(db, "attendance"), { payload: compressData(r), timestamp: r.timestamp }); }} 
          onUpdateEmployees={handleUpdateEmployees} 
        />
      )}

      {view === 'admin' && currentUserRole && (
        <AdminDashboard 
          role={currentUserRole} 
          isDbConnected={isDbConnected}
          onLogout={() => setShowLogoutFeedback(true)} 
          company={company}
          onUpdateCompany={async (c) => await setDoc(doc(db, "config", "company"), { payload: compressData(c) })}
          employees={employees}
          onUpdateEmployees={handleUpdateEmployees}
          attendance={attendance}
          payments={payments}
          onUpdatePayments={handleUpdatePayments}
          settings={settings}
          onUpdateSettings={async (s) => await setDoc(doc(db, "config", "settings"), { payload: compressData(s) })}
          onUpdateAppMode={(mode) => { setAppMode(mode); localStorage.setItem('app_mode', mode); }}
          appMode={appMode}
        />
      )}

      <Modal isOpen={showWelcome} onClose={() => setShowWelcome(false)} title="Autorizado" type="success" maxWidth="max-w-[280px]">
         <div className="text-center space-y-6 p-2">
            <h2 className="text-xl font-[950] text-slate-900 uppercase tracking-tight leading-none">Bienvenido</h2>
            <button onClick={() => setShowWelcome(false)} className="w-full py-4 bg-blue-700 text-white font-black rounded-2xl uppercase text-[10px] tracking-widest active:scale-95 transition-all">Acceder</button>
         </div>
      </Modal>

      <Modal isOpen={showLogoutFeedback} onClose={finalizeLogout} title="Salida" type="success" maxWidth="max-w-[280px]">
         <div className="text-center space-y-6 p-2">
            <h3 className="text-xl font-[950] text-slate-900 uppercase tracking-tighter leading-none">Sincronizado</h3>
            <button onClick={finalizeLogout} className="w-full py-4 bg-slate-900 text-white font-black rounded-2xl uppercase text-[10px] tracking-widest active:scale-95 transition-all">Finalizar</button>
         </div>
      </Modal>

      <Modal isOpen={modalAlert.isOpen} onClose={() => setModalAlert({...modalAlert, isOpen: false})} title={modalAlert.title} type={modalAlert.type} maxWidth="max-w-[280px]">
           <div className="text-center p-4">
              <p className="text-slate-800 font-bold uppercase text-[11px]">{modalAlert.message}</p>
              <button onClick={() => setModalAlert({...modalAlert, isOpen: false})} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase mt-6 active:scale-95 transition-all">Ok</button>
           </div>
      </Modal>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { GoogleGenAI } from "@google/genai";
import { Employee, AttendanceRecord, Payment, Role } from '../../types.ts';

interface AiAssistantProps {
  employees: Employee[];
  attendance: AttendanceRecord[];
  payments: Payment[];
  role: Role;
}

const AiAssistant: React.FC<AiAssistantProps> = ({ employees, attendance, payments, role }) => {
  const [prompt, setPrompt] = useState('');
  const [response, setResponse] = useState('');
  const [isTyping, setIsTyping] = useState(false);

  const handleAskAi = async () => {
    if (!prompt.trim()) return;
    setIsTyping(true);
    setResponse('');

    try {
      // Fix: Initialize GoogleGenAI with named parameter apiKey as per guidelines
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const activeEmps = employees.filter(e => e.status === 'active').length;
      const totalPayments = payments.reduce((acc, p) => acc + (p.status === 'paid' ? p.amount : 0), 0);

      const context = `
        Eres un consultor experto en Talento Humano y legislación laboral ecuatoriana. 
        Contexto de la empresa actual:
        - Colaboradores activos: ${activeEmps}
        - Total nómina procesada este mes: $${totalPayments.toFixed(2)}
        - Registros de asistencia totales: ${attendance.length}

        Pregunta del administrador: ${prompt}
      `;

      // Fix: Using gemini-3-pro-preview for complex reasoning tasks as per guidelines
      const result = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: context,
        config: {
          systemInstruction: "Proporciona respuestas profesionales, concisas y basadas en mejores prácticas de RRHH en Ecuador. Si la pregunta es sobre leyes ecuatorianas, menciona que es una guía general.",
          temperature: 0.7,
        }
      });

      // Fix: Access .text property instead of calling .text() as per guidelines
      setResponse(result.text || "No pude generar una respuesta en este momento.");
    } catch (error) {
      console.error("Gemini Error:", error);
      setResponse("Error al conectar con la inteligencia artificial. Verifique su conexión y configuración de API.");
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="space-y-6 fade-in max-w-4xl mx-auto pb-20">
      <div className="bg-slate-900 p-10 rounded-[3rem] text-white shadow-2xl relative overflow-hidden">
        <div className="relative z-10">
          <div className="flex items-center gap-4 mb-6">
            <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center text-2xl animate-pulse">✨</div>
            <div>
              <h2 className="text-2xl font-[950] uppercase tracking-tighter italic">Asistente IA Estratégico</h2>
              <p className="text-[10px] font-bold text-blue-400 uppercase tracking-[0.4em]">Powered by Gemini 3 Pro</p>
            </div>
          </div>
          <p className="text-slate-400 text-sm font-medium leading-relaxed mb-8">
            Analiza patrones de asistencia, solicita recomendaciones para mejorar el clima laboral o resuelve dudas sobre el Código de Trabajo.
          </p>

          <div className="flex gap-4">
            <input 
              type="text" 
              value={prompt}
              onChange={(e) => setPrompt(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleAskAi()}
              placeholder="Ej: ¿Cómo puedo reducir el ausentismo este mes?"
              className="flex-1 bg-white/10 border border-white/20 rounded-2xl p-4 text-sm text-white focus:outline-none focus:border-blue-500 placeholder:text-white/30"
            />
            <button 
              onClick={handleAskAi}
              disabled={isTyping}
              className="px-8 py-4 bg-blue-600 hover:bg-blue-700 text-white font-black rounded-2xl uppercase text-[10px] tracking-widest transition-all active:scale-95 disabled:opacity-50"
            >
              {isTyping ? 'Analizando...' : 'Consultar'}
            </button>
          </div>
        </div>
      </div>

      {response && (
        <div className="bg-white p-10 rounded-[3rem] shadow-sm border border-slate-100 animate-in slide-in-from-bottom-4">
          <div className="flex items-center gap-3 mb-6">
            <div className="w-2 h-8 bg-blue-600 rounded-full"></div>
            <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest">Análisis de Estrategia</h3>
          </div>
          <div className="prose prose-slate max-w-none">
            <p className="text-slate-700 text-sm leading-8 font-medium whitespace-pre-wrap">
              {response}
            </p>
          </div>
        </div>
      )}

      {!response && !isTyping && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
           {[
             "¿Qué beneficios de ley son obligatorios en Ecuador?",
             "Analiza la productividad según la nómina actual",
             "Estrategias para retención de talento humano"
           ].map((q, i) => (
             <button 
               key={i}
               onClick={() => { setPrompt(q); }}
               className="p-6 bg-white border border-slate-100 rounded-3xl text-left hover:border-blue-500 transition-all group"
             >
                <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-2 group-hover:text-blue-600">Sugerencia</p>
                <p className="text-[11px] font-bold text-slate-700 leading-tight">{q}</p>
             </button>
           ))}
        </div>
      )}
    </div>
  );
};

export default AiAssistant;

import React, { useState } from 'react';
import { Employee, Payment, CompanyConfig, GlobalSettings, Role } from '../../types.ts';
import Modal from '../../components/Modal.tsx';

interface PayrollModuleProps {
  employees: Employee[];
  payments: Payment[];
  attendance: any[];
  company: CompanyConfig | null;
  settings: GlobalSettings;
  role: Role;
}

const PayrollModule: React.FC<PayrollModuleProps> = ({ employees, payments, attendance, company, settings, role }) => {
  const [selectedMonth, setSelectedMonth] = useState(new Date().toLocaleString('es-EC', {month: 'long'}).toUpperCase());
  const [individualPayroll, setIndividualPayroll] = useState<Employee | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  const monthMap: { [key: string]: number } = {
    'ENERO': 0, 'FEBRERO': 1, 'MARZO': 2, 'ABRIL': 3, 'MAYO': 4, 'JUNIO': 5,
    'JULIO': 6, 'AGOSTO': 7, 'SEPTIEMBRE': 8, 'OCTUBRE': 9, 'NOVIEMBRE': 10, 'DICIEMBRE': 11
  };

  const calculatePayrollData = (emp: Employee, index: number) => {
    const monthIndex = monthMap[selectedMonth] ?? 0;
    const year = 2026; // Año de contexto del sistema

    // 1. Días Laborables Esperados (Lunes a Sábado según calendario)
    let expectedDays = 0;
    const daysInMonth = new Date(year, monthIndex + 1, 0).getDate();
    for (let d = 1; d <= daysInMonth; d++) {
      const date = new Date(year, monthIndex, d);
      const dayOfWeek = date.getDay(); // 0: Dom, 1: Lun ... 6: Sáb
      if (dayOfWeek >= 1 && dayOfWeek <= 6) expectedDays++;
    }

    // 2. Días Efectivamente Trabajados (Basado en marcaciones de asistencia)
    const empAttendance = attendance.filter(a => {
      const d = new Date(a.timestamp);
      return a.employeeId === emp.id && 
             d.getMonth() === monthIndex && 
             d.getFullYear() === year && 
             a.status === 'confirmed';
    });

    const attendanceByDate: { [key: string]: { ins: number, half: number } } = {};
    empAttendance.forEach(a => {
      const dateStr = a.timestamp.split('T')[0];
      if (!attendanceByDate[dateStr]) attendanceByDate[dateStr] = { ins: 0, half: 0 };
      if (a.type === 'in') attendanceByDate[dateStr].ins++;
      if (a.type === 'half_day') attendanceByDate[dateStr].half++;
    });

    let workedDays = 0;
    Object.values(attendanceByDate).forEach(day => {
      // Si tiene 2 o más ingresos (jornada completa) cuenta como 1 día
      if (day.ins >= 2) workedDays += 1.0;
      // Si tiene solo 1 ingreso o marcó media jornada, cuenta como 0.5 día
      else if (day.ins === 1 || day.half > 0) workedDays += 0.5;
    });

    // 3. Incluir Faltas Justificadas como tiempo trabajado (Remunerado)
    const justifiedAbsences = (emp.absences || []).filter(a => {
      const d = new Date(a.date);
      return d.getMonth() === monthIndex && d.getFullYear() === year && a.type === 'Falta' && a.justified;
    }).length;

    workedDays = Math.min(expectedDays, workedDays + justifiedAbsences);

    // 4. Cálculo Proporcional (Base 30 días comerciales)
    // Si trabajó todos los días esperados, recibe el sueldo completo (30 días).
    // Si faltó, se descuentan los días proporcionales de los 30 días base.
    const missingDays = Math.max(0, expectedDays - workedDays);
    const earnedBase = emp.salary * (Math.max(0, 30 - missingDays) / 30);
    const attendanceProportion = expectedDays > 0 ? workedDays / expectedDays : 0;

    // 5. Pagos Adicionales y Deducciones de Tesorería
    const monthlyPayments = payments.filter(p => p.employeeId === emp.id && p.month === selectedMonth && p.status === 'paid');
    const bonuses = monthlyPayments.filter(p => p.type === 'Bonus').reduce((sum, p) => sum + p.amount, 0);
    const extraHours = monthlyPayments.filter(p => p.type === 'ExtraHours').reduce((sum, p) => sum + p.amount, 0);
    const vacation = monthlyPayments.filter(p => p.type === 'Vacation').reduce((sum, p) => sum + p.amount, 0);

    const isMonthly = emp.overSalaryType === 'monthly';
    const isAffiliated = emp.isAffiliated;

    // Ingresos Gravables para IESS y Beneficios
    const taxableIncome = earnedBase + extraHours + bonuses;

    // Beneficios Proporcionales
    const monthly13th = (isAffiliated && isMonthly) ? (taxableIncome) / 12 : 0;
    const monthly14th = (isAffiliated && isMonthly) ? (settings.sbu / 12) * attendanceProportion : 0;
    const reserveFund = (isAffiliated && isMonthly) ? (taxableIncome * settings.reserveRate) : 0;

    const totalOverSalaries = monthly13th + monthly14th + reserveFund;
    const totalIncomes = earnedBase + totalOverSalaries + bonuses + extraHours + vacation;

    // Egresos
    const iessContribution = isAffiliated ? (taxableIncome * settings.iessRate) : 0;
    const loans = monthlyPayments.filter(p => p.type === 'Loan' || p.type === 'Emergency').reduce((sum, p) => sum + p.amount, 0);

    const totalExpenses = iessContribution + loans;
    const netToReceive = totalIncomes - totalExpenses;
    const voucherCode = `PN-${(index + 1).toString().padStart(8, '0')}`;

    return { 
      baseSalary: earnedBase,
      reserveFund, bonuses, extraHours, vacation,
      monthly13th, monthly14th, totalOverSalaries,
      iessContribution, loans,
      totalIncomes, totalExpenses, netToReceive,
      voucherCode,
      workedDays,
      expectedDays
    };
  };

  const exportGeneralExcel = () => {
    let csv = "\uFEFF"; // BOM para UTF-8
    csv += "Colaborador,Identificación,Días Trabajados,Sueldo Ganado,Extra/Bono,13ero Mensual,14to Mensual,Reserva,IESS 9.45%,Préstamos,Total Ingresos,Total Egresos,Neto Recibir\n";
    employees.filter(e => e.status === 'active').forEach((emp, idx) => {
      const d = calculatePayrollData(emp, idx);
      csv += `"${emp.surname} ${emp.name}","${emp.identification}",${d.workedDays},${d.baseSalary.toFixed(2)},${(d.extraHours+d.bonuses).toFixed(2)},${d.monthly13th.toFixed(2)},${d.monthly14th.toFixed(2)},${d.reserveFund.toFixed(2)},${d.iessContribution.toFixed(2)},${d.loans.toFixed(2)},${d.totalIncomes.toFixed(2)},${d.totalExpenses.toFixed(2)},${d.netToReceive.toFixed(2)}\n`;
    });
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `ROL_GENERAL_PROPORCIONAL_${selectedMonth}_2026.csv`;
    link.click();
  };

  const exportIndividualExcel = (emp: Employee) => {
    const d = calculatePayrollData(emp, 0);
    let csv = "\uFEFFDetalle,Ingresos,Egresos\n";
    csv += `Sueldo Ganado (Proporcional),${d.baseSalary.toFixed(2)},0\n`;
    csv += `Horas Extras/Bonos,${(d.extraHours+d.bonuses).toFixed(2)},0\n`;
    csv += `Décimo Tercero Mensual,${d.monthly13th.toFixed(2)},0\n`;
    csv += `Décimo Cuarto Mensual,${d.monthly14th.toFixed(2)},0\n`;
    csv += `Fondos de Reserva,${d.reserveFund.toFixed(2)},0\n`;
    csv += `Aporte IESS Personal (9.45%),0,${d.iessContribution.toFixed(2)}\n`;
    csv += `Préstamos/Anticipos/Otros,0,${d.loans.toFixed(2)}\n`;
    csv += `---,---,---\n`;
    csv += `TOTALES,${d.totalIncomes.toFixed(2)},${d.totalExpenses.toFixed(2)}\n`;
    csv += `NETO A RECIBIR,${d.netToReceive.toFixed(2)},0\n`;

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `ROL_INDIVIDUAL_${emp.surname}_${selectedMonth}_2026.csv`;
    link.click();
  };

  const filteredEmployees = employees.filter(e => {
    const searchStr = `${e.name} ${e.surname} ${e.identification} ${e.role}`.toLowerCase();
    return searchStr.includes(searchTerm.toLowerCase());
  });

  return (
    <div className="space-y-6 md:space-y-8 fade-in">
      <div className="flex flex-col md:flex-row justify-between items-center bg-white p-6 rounded-3xl md:rounded-[2rem] shadow-sm border border-slate-100 no-print gap-6">
        <div className="w-full">
          <h2 className="text-lg md:text-xl font-black text-slate-900 uppercase text-center md:text-left">Nómina Proporcional</h2>
          <p className="text-[9px] font-black text-blue-600 uppercase tracking-widest mt-1">Cálculo basado en Asistencia Efectiva</p>
          <div className="flex flex-col sm:flex-row gap-3 mt-4">
             <select className="w-full sm:w-auto p-2.5 border rounded-xl text-[10px] font-black uppercase outline-none focus:border-blue-500" value={selectedMonth} onChange={e => setSelectedMonth(e.target.value)}>
                {['ENERO','FEBRERO','MARZO','ABRIL','MAYO','JUNIO','JULIO','AGOSTO','SEPTIEMBRE','OCTUBRE','NOVIEMBRE','DICIEMBRE'].map(m => <option key={m} value={m}>{m}</option>)}
             </select>
             <input type="text" placeholder="Filtrar por nombre, CI..." className="w-full sm:w-auto flex-1 p-2.5 border rounded-xl text-[10px] font-bold uppercase outline-none focus:border-blue-500" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
          </div>
        </div>
        <div className="flex gap-2 w-full md:w-auto">
           <button onClick={exportGeneralExcel} className="flex-1 px-4 py-3.5 bg-emerald-600 text-white font-black rounded-xl uppercase text-[8px] tracking-widest shadow active:scale-95 transition-all">Excel General</button>
           <button onClick={() => window.print()} className="flex-1 px-4 py-3.5 bg-slate-900 text-white font-black rounded-xl uppercase text-[8px] tracking-widest shadow active:scale-95 transition-all">PDF General</button>
        </div>
      </div>

      <div className="bg-white p-4 md:p-10 rounded-3xl md:rounded-[3rem] shadow-sm border overflow-hidden">
        <div className="table-responsive">
          <table className="w-full text-left border-collapse min-w-[800px]">
            <thead className="bg-slate-900 text-white text-[8px] font-black uppercase tracking-widest">
              <tr>
                <th className="p-4 rounded-tl-2xl">Empleado</th>
                <th className="p-4 text-center">Días Trab.</th>
                <th className="p-4 text-center">Sueldo Ganado</th>
                <th className="p-4 text-center">Beneficios</th>
                <th className="p-4 text-center">IESS/Desc.</th>
                <th className="p-4 text-center bg-blue-800 rounded-tr-2xl">Neto a Recibir</th>
                <th className="p-4 text-center no-print">Acción</th>
              </tr>
            </thead>
            <tbody className="text-[9px] md:text-[10px] uppercase font-bold text-slate-700 divide-y">
              {filteredEmployees.filter(e => e.status === 'active').map((emp, idx) => {
                const d = calculatePayrollData(emp, idx);
                return (
                  <tr key={emp.id} className="hover:bg-slate-50 transition-colors">
                    <td className="p-4 font-black text-slate-900 truncate max-w-[150px]">{emp.surname} {emp.name}</td>
                    <td className="p-4 text-center font-black text-blue-600">{d.workedDays} / {d.expectedDays}</td>
                    <td className="p-4 text-center">${d.baseSalary.toFixed(2)}</td>
                    <td className="p-4 text-center text-emerald-600">${(d.totalOverSalaries).toFixed(2)}</td>
                    <td className="p-4 text-center text-red-500">${d.totalExpenses.toFixed(2)}</td>
                    <td className="p-4 text-center font-[950] text-blue-700 bg-blue-50/20">${d.netToReceive.toFixed(2)}</td>
                    <td className="p-4 text-center no-print">
                       <button onClick={() => setIndividualPayroll(emp)} className="px-3 py-1.5 bg-blue-700 text-white rounded-lg text-[7px] font-black uppercase active:scale-95 transition-all shadow-md">Ver Rol</button>
                    </td>
                  </tr>
                );
              })}
              {filteredEmployees.length === 0 && (
                <tr><td colSpan={7} className="p-10 text-center text-slate-300 font-black uppercase">Sin resultados filtrados</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      <Modal isOpen={!!individualPayroll} onClose={() => setIndividualPayroll(null)} title="Rol de Pagos Individual">
        {individualPayroll && (() => {
           const d = calculatePayrollData(individualPayroll, 0);
           return (
