               <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-3">
                     <h4 className="text-[9px] font-black uppercase text-emerald-600 border-b pb-1">Ingresos y Beneficios Ganados</h4>
