                    <td className="p-3 text-center font-black text-red-700">${d.totalExpenses.toFixed(2)}</td>
                    <td className="p-3 text-center font-[950] text-blue-700 bg-blue-50/20 print:bg-transparent">${d.netToReceive.toFixed(2)}</td>
                    <td className="p-3 text-center no-print">
