        </div>
      </div>

      <Modal isOpen={!!selectedPayForPrint} onClose={() => setSelectedPayForPrint(null)} title="Comprobante Institucional de Egreso">
        {selectedPayForPrint && (() => {
           const emp = employees.find(e => e.id === selectedPayForPrint.employeeId);
           return (
             <div className="p-10 space-y-10 bg-white" id="payment-voucher-print">
                <div className="text-center border-b-4 border-slate-900 pb-8">
                   <h3 className="text-3xl font-[950] text-slate-900 uppercase tracking-tighter italic leading-none">{company?.name || 'EMPRESA INSTITUCIONAL'}</h3>
                   <p className="text-[11px] font-black text-slate-400 mt-2 uppercase tracking-widest">COMPROBANTE DE CAJA / TESORERÍA - 2026</p>
                   <div className="grid grid-cols-2 gap-6 mt-4 max-w-xl mx-auto text-[10px] font-bold uppercase text-slate-700">
                     <p className="text-left border-l-4 border-slate-900 pl-3">RUC: {company?.ruc || '0000000000001'}</p>
                     <p className="text-right border-r-4 border-slate-900 pr-3">Representante: {company?.legalRep || 'GERENCIA'}</p>
                   </div>
                   <p className="text-[8px] text-slate-400 mt-2 uppercase font-bold italic text-right">Referencia ID: {selectedPayForPrint.id.substr(0,12).toUpperCase()}</p>
                </div>
                <div className="grid grid-cols-2 gap-10 text-[11px] font-bold uppercase">
                   <div className="space-y-6">
                      <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100"><p className="text-slate-400 text-[9px] font-black mb-1">Beneficiario del Desembolso</p><p className="text-slate-900 text-2xl font-[950] leading-none">{emp?.surname} {emp?.name}</p><p className="text-slate-500 font-black mt-1">Cédula: {emp?.identification}</p></div>
                      <div><p className="text-slate-400 text-[9px] font-black mb-1">Concepto de Egreso</p><p className="text-slate-900 font-[950] text-sm">{selectedPayForPrint.type} - {selectedPayForPrint.month} {selectedPayForPrint.year}</p><p className="text-slate-500 text-[10px] lowercase italic border-l-2 pl-3 mt-2 leading-relaxed">{selectedPayForPrint.concept}</p></div>
