                   <button onClick={() => exportSingleExcel(selectedPayForPrint)} className="flex-1 py-5 bg-emerald-600 text-white font-black rounded-3xl uppercase text-[10px] tracking-widest active:scale-95 transition-all shadow-lg">Descargar Excel</button>
