      <Modal isOpen={isVoidModalOpen} onClose={() => setIsVoidModalOpen(false)} title="Anular Comprobante de Caja" maxWidth="max-w-sm">
         <div className="space-y-4 text-center">
            <p className="text-xs text-slate-500 font-bold uppercase">Debe ingresar la causa obligatoria para anular:</p>
