import React, { useState } from 'react';
import { Employee, Payment, AttendanceRecord, CompanyConfig, GlobalSettings, Role } from '../../types.ts';
import { db, doc, setDoc, deleteDoc, compressData } from '../../firebase.ts';
import Modal from '../../components/Modal.tsx';

interface ReportsModuleProps {
  employees: Employee[];
  payments: Payment[];
  attendance: AttendanceRecord[];
  company: CompanyConfig | null;
  settings: GlobalSettings;
  role: Role;
}

const ReportsModule: React.FC<ReportsModuleProps> = ({ employees, payments, attendance = [], company, settings, role }) => {
  const [reportType, setReportType] = useState<'attendance' | 'payments' | 'validation'>('attendance');
  const [searchTerm, setSearchTerm] = useState('');
  const [feedback, setFeedback] = useState({ isOpen: false, title: '', message: '', type: 'success' as any });

  const pendingAttendance = (attendance || []).filter(a => a.status === 'pending_approval');

  const handleValidate = async (record: AttendanceRecord, newStatus: 'confirmed' | 'rejected') => {
    const updatedRecord = { 
      ...record, 
      status: newStatus,
      validatedAt: new Date().toISOString()
    };

    await setDoc(doc(db, "attendance", record.id), { payload: compressData(updatedRecord), timestamp: record.timestamp });
    setFeedback({ isOpen: true, title: "Actualización Exitosa", message: `La marcación ha sido validada como: ${newStatus.toUpperCase()}`, type: 'success' });
  };

  const handleDeleteAttendance = async (id: string) => {
    if (confirm("¿Está seguro de eliminar este registro permanentemente? Esta acción es irreversible.")) {
      try {
        await deleteDoc(doc(db, "attendance", id));
        setFeedback({ isOpen: true, title: "Registro Eliminado", message: "La marcación ha sido borrada del sistema.", type: 'success' });
      } catch (e) {
        setFeedback({ isOpen: true, title: "Error Crítico", message: "No se pudo eliminar el registro en la base de datos.", type: 'error' });
      }
    }
  };

  const filteredPending = pendingAttendance.filter(req => {
    const emp = employees.find(e => e.id === req.employeeId);
    const searchStr = `${emp?.name} ${emp?.surname} ${emp?.identification} ${req.justification || ""}`.toLowerCase();
    return searchStr.includes(searchTerm.toLowerCase());
  });

  const exportAttendanceExcel = () => {
    let csv = "\uFEFFFecha,Hora,Colaborador,Identificación,Cargo,Tipo Marcación,Estado,Atraso,Justificación\n";
    (attendance || []).sort((a, b) => b.timestamp.localeCompare(a.timestamp)).forEach(rec => {
      const emp = employees.find(e => e.id === rec.employeeId);
      const date = new Date(rec.timestamp);
      csv += `"${date.toLocaleDateString()}","${date.toLocaleTimeString()}","${emp?.surname} ${emp?.name}","${emp?.identification}","${emp?.role}","${rec.type === 'in' ? 'Entrada' : 'Salida'}","${rec.status}","${rec.isLate ? 'SI' : 'NO'}","${rec.justification || ''}"\n`;
    });
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `REPORTE_ASISTENCIA_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  };

  const attendanceToDisplay = (attendance || []).filter(a => {
    const emp = employees.find(e => e.id === a.employeeId);
    const searchStr = `${emp?.surname} ${emp?.name} ${emp?.identification} ${a.justification || ""} ${a.status} ${a.type}`.toLowerCase();
    return searchStr.includes(searchTerm.toLowerCase());
  }).sort((a,b) => b.timestamp.localeCompare(a.timestamp));

  return (
    <div className="space-y-6 md:space-y-8 fade-in">
      <div className="flex flex-col md:flex-row justify-between items-center bg-white p-6 md:p-8 rounded-3xl md:rounded-[2rem] shadow-sm border border-slate-100 gap-6 no-print">
        <div className="w-full">
          <h2 className="text-xl md:text-2xl font-[950] text-slate-900 uppercase tracking-tighter">Reportes Institucionales</h2>
          <div className="flex flex-col sm:flex-row gap-4 mt-4">
            <div className="flex gap-2 overflow-x-auto pb-2 sm:pb-0 scroll-smooth no-scrollbar">
              <button onClick={() => {setReportType('attendance'); setSearchTerm('');}} className={`whitespace-nowrap px-4 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${reportType === 'attendance' ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-100 text-slate-400 hover:bg-slate-200'}`}>Registros de Asistencia</button>
              <button onClick={() => {setReportType('validation'); setSearchTerm('');}} className={`whitespace-nowrap px-4 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest relative transition-all ${reportType === 'validation' ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-100 text-slate-400 hover:bg-slate-200'}`}>
                Validaciones
                {pendingAttendance.length > 0 && <span className="absolute -top-1 -right-1 w-4 h-4 bg-red-500 text-white text-[8px] rounded-full flex items-center justify-center font-black animate-pulse shadow-md">{pendingAttendance.length}</span>}
              </button>
            </div>
            <input 
              type="text" 
              placeholder="Filtrar registros..." 
              className="flex-1 p-2.5 border rounded-xl text-[10px] font-bold uppercase outline-none focus:border-blue-500 shadow-sm" 
              value={searchTerm} 
              onChange={e => setSearchTerm(e.target.value)}
            />
          </div>
        </div>
        <div className="flex gap-2 w-full md:w-auto">
          <button onClick={exportAttendanceExcel} className="flex-1 md:flex-none px-6 py-4 bg-emerald-600 text-white font-black rounded-xl shadow-lg uppercase text-[9px] active:scale-95 transition-all">Excel Completo</button>
          <button onClick={() => window.print()} className="flex-1 md:flex-none px-6 py-4 bg-slate-900 text-white font-black rounded-xl shadow-lg uppercase text-[9px] active:scale-95 transition-all">Imprimir PDF</button>
        </div>
      </div>

      <div className="bg-white rounded-3xl md:rounded-[2rem] shadow-sm border overflow-hidden min-h-[450px]" id="reports-printable-area">
         <div className="hidden print:block text-center border-b-2 border-slate-900 pb-6 mb-8 px-10 pt-10">
           <h1 className="text-2xl font-[950] text-slate-900 uppercase italic leading-none">{company?.name || 'ASIST UP - HR ENTERPRISE'}</h1>
           <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mt-2">Reporte de {reportType === 'attendance' ? 'Asistencia Diaria' : 'Validaciones Pendientes'} - 2026</p>
           <div className="grid grid-cols-2 gap-4 mt-3 max-w-xl mx-auto text-[9px] font-bold uppercase text-slate-600">
             <p className="text-left border-l-4 border-slate-900 pl-3">RUC: {company?.ruc || '0000000000001'}</p>
             <p className="text-right border-r-4 border-slate-900 pr-3">Representante: {company?.legalRep || 'ADMINISTRACIÓN'}</p>
           </div>
           <p className="text-[7px] text-slate-400 mt-2 uppercase font-bold italic text-right">Generado: {new Date().toLocaleString()}</p>
         </div>

         <div className="p-6 md:p-10">
            {reportType === 'validation' ? (
              <div className="space-y-6">
                <h3 className="text-lg font-[950] text-slate-900 uppercase tracking-tighter border-b pb-4 no-print">Validaciones Pendientes por Revisar</h3>
                {filteredPending.length === 0 ? (
                  <div className="py-24 text-center bg-slate-50 rounded-3xl border-2 border-dashed border-slate-200">
                    <span className="text-5xl opacity-20">✅</span>
                    <p className="text-slate-400 font-black uppercase text-[10px] tracking-widest mt-6">No existen justificaciones pendientes</p>
                  </div>
                ) : (
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    {filteredPending.map(req => {
                      const emp = employees.find(e => e.id === req.employeeId);
                      return (
                        <div key={req.id} className="bg-white border rounded-3xl p-6 flex flex-col gap-5 hover:border-blue-500 transition-all shadow-sm">
                          <div className="flex justify-between items-start">
                            <div>
                              <p className="font-[950] text-slate-900 uppercase text-sm tracking-tight">{emp?.surname} {emp?.name}</p>
                              <p className="text-slate-400 font-black text-[8px] uppercase mt-1">CI: {emp?.identification} | {new Date(req.timestamp).toLocaleString()}</p>
                            </div>
                            <span className={`px-2 py-1 text-[8px] font-black rounded-lg uppercase ${req.type === 'in' ? 'bg-blue-50 text-blue-700' : 'bg-slate-100 text-slate-700'}`}>{req.type === 'in' ? 'Ingreso' : 'Salida'}</span>
                          </div>
                          <div className="space-y-2">
                             <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest">Justificación del Colaborador</p>
                             <p className="text-[11px] text-slate-600 font-bold bg-slate-50 p-4 rounded-2xl border leading-relaxed shadow-inner italic">"{req.justification}"</p>
                          </div>
                          <div className="grid grid-cols-2 gap-3 pt-2 no-print">
                             <button onClick={() => handleValidate(req, 'rejected')} className="py-3 bg-red-50 text-red-600 font-black text-[9px] uppercase rounded-xl hover:bg-red-100 transition-all active:scale-95">Rechazar</button>
                             <button onClick={() => handleValidate(req, 'confirmed')} className="py-3 bg-emerald-600 text-white font-black text-[9px] uppercase rounded-xl shadow-lg hover:bg-emerald-700 transition-all active:scale-95">Validar</button>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                )}
              </div>
            ) : (
               <div className="table-responsive">
                  <table className="w-full text-left min-w-[750px] print:min-w-0 print:table-auto">
                    <thead className="bg-slate-50 text-[9px] font-black uppercase text-slate-400 border-b tracking-widest print:bg-slate-900 print:text-white">
                      <tr>
                        <th className="p-4">Fecha / Hora</th>
                        <th className="p-4">Colaborador / Identificación</th>
                        <th className="p-4">Marcación</th>
                        <th className="p-4 text-center">Atraso</th>
                        <th className="p-4">Estado Sistema</th>
                        <th className="p-4 text-right no-print">Acción</th>
                      </tr>
                    </thead>
                    <tbody className="text-[9px] md:text-[10px] font-bold uppercase divide-y text-slate-600 print:text-slate-950">
                      {attendanceToDisplay.map(rec => {
                        const emp = employees.find(e => e.id === rec.employeeId);
                        return (
                          <tr key={rec.id} className="hover:bg-slate-50 transition-colors">
                            <td className="p-4 whitespace-nowrap">{new Date(rec.timestamp).toLocaleString()}</td>
                            <td className="p-4">
                               <p className="font-black text-slate-900">{emp?.surname} {emp?.name}</p>
                               <p className="text-[8px] font-bold text-slate-400">{emp?.identification}</p>
                            </td>
                            <td className="p-4 font-black">{rec.type === 'in' ? 'Ingreso' : rec.type === 'out' ? 'Salida' : 'Media Jornada'}</td>
                            <td className="p-4 text-center">
                               {rec.isLate ? <span className="text-red-600 font-black">SÍ (Crítico)</span> : <span className="text-emerald-600">NO</span>}
                            </td>
                            <td className="p-4">
                              <span className={`px-2 py-0.5 rounded-lg text-[8px] font-black uppercase shadow-sm ${rec.status === 'confirmed' ? 'bg-emerald-50 text-emerald-600' : rec.status === 'pending_approval' ? 'bg-blue-50 text-blue-600' : 'bg-red-50 text-red-600'}`}>{rec.status}</span>
                            </td>
                            <td className="p-4 text-right no-print">
                              {role === Role.SUPER_ADMIN && (
                                <button onClick={() => handleDeleteAttendance(rec.id)} className="px-2 py-1.5 bg-red-50 text-red-600 text-[8px] font-black uppercase rounded-lg hover:bg-red-600 hover:text-white transition-all">Borrar</button>
                              )}
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
               </div>
            )}
         </div>

         <div className="hidden print:grid grid-cols-2 gap-10 mt-20 p-10 pt-20 border-t-2 border-slate-100">
           <div className="text-center">
              <div className="border-t-2 border-slate-900 pt-3 text-[10px] font-black uppercase">Firma RRHH / Supervisión</div>
              <p className="text-[7px] text-slate-400 mt-1 uppercase font-bold">Responsable de Auditoría</p>
           </div>
           <div className="text-center">
              <div className="border-t-2 border-slate-900 pt-3 text-[10px] font-black uppercase">Sello de Recepción</div>
           </div>
        </div>
      </div>

      <Modal isOpen={feedback.isOpen} onClose={() => setFeedback({...feedback, isOpen: false})} title={feedback.title} type={feedback.type}>
          <div className="text-center p-4">
              <p className="text-slate-600 font-bold uppercase text-[11px] leading-relaxed mb-6">{feedback.message}</p>
              <button onClick={() => setFeedback({...feedback, isOpen: false})} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[9px] shadow-lg active:scale-95 transition-all">Aceptar</button>
          </div>
      </Modal>
    </div>
  );
};

export default ReportsModule;

import React, { useState, useEffect, useMemo } from 'react';
import { Employee, AttendanceRecord, GlobalSettings } from '../types.ts';
import Clock from '../components/Clock.tsx';
import Modal from '../components/Modal.tsx';

const APP_ICON_SVG = "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'%3E%3Cdefs%3E%3ClinearGradient id='g' x1='0%25' y1='0%25' x2='100%25' y2='100%25'%3E%3Cstop offset='0%25' style='stop-color:%233b82f6;'/%3E%3Cstop offset='100%25' style='stop-color:%231e3a8a;'/%3E%3C/linearGradient%3E%3C/defs%3E%3Ccircle cx='50' cy='50' r='45' fill='none' stroke='url(%23g)' stroke-width='6' stroke-dasharray='15 5'/%3E%3Ccircle cx='50' cy='50' r='32' fill='none' stroke='url(%23g)' stroke-width='5' stroke-dasharray='10 4' opacity='0.7'/%3E%3Ccircle cx='50' cy='50' r='18' fill='none' stroke='url(%23g)' stroke-width='4' opacity='0.4'/%3E%3Ccircle cx='50' cy='50' r='6' fill='%233b82f6'/%3E%3C/svg%3E";

interface AttendanceSystemProps {
  employees: Employee[];
  attendance: AttendanceRecord[];
  onRegister: (record: AttendanceRecord) => void;
  onBack: () => void;
  onUpdateEmployees: (employees: Employee[]) => void;
  settings: GlobalSettings;
}

const AttendanceSystem: React.FC<AttendanceSystemProps> = ({ employees, attendance, onRegister, onBack, onUpdateEmployees, settings }) => {
  const [pin, setPin] = useState('');
  const [status, setStatus] = useState<'idle' | 'confirm' | 'forgotten_form' | 'success' | 'error' | 'change_pin' | 'justification_form'>('idle');
  const [isProcessing, setIsProcessing] = useState(false);
  const [currentEmp, setCurrentEmp] = useState<Employee | null>(null);
  const [pendingMarkData, setPendingMarkData] = useState<{ type: 'in' | 'out' | 'half_day', isLate: boolean } | null>(null);
  const [justificationText, setJustificationText] = useState('');
  const [newPin, setNewPin] = useState('');
  const [forgotCi, setForgotCi] = useState('');
  const [successMsg, setSuccessMsg] = useState('');
  const [feedback, setFeedback] = useState<{isOpen: boolean, title: string, message: string, type: 'success' | 'error' | 'info'}>({
    isOpen: false, title: '', message: '', type: 'success'
  });

  const isWithinRange = (now: Date, startStr: string, endStr: string) => {
    const [sh, sm] = startStr.split(':').map(Number);
    const [eh, em] = endStr.split(':').map(Number);
    const s = new Date(now); s.setHours(sh, sm, 0, 0);
    const e = new Date(now); e.setHours(eh, em, 0, 0);
    return now >= s && now <= e;
  };

  const handleMark = (type: 'in' | 'out' | 'half_day') => {
    if (!currentEmp || isProcessing) return;

    const now = new Date();
    const day = now.getDay();
    let isOffSchedule = false;
    let isCriticalLate = false;

    if (type !== 'half_day') {
      if (day >= 1 && day <= 5) {
        const in1 = isWithinRange(now, settings.schedule.monFri.in1, settings.schedule.monFri.out1);
        const in2 = isWithinRange(now, settings.schedule.monFri.in2, settings.schedule.monFri.out2);
        if (!in1 && !in2) isOffSchedule = true;

        if (type === 'in') {
          const [schedH, schedM] = settings.schedule.monFri.in1.split(':').map(Number);
          const schedDate = new Date(now);
          schedDate.setHours(schedH, schedM, 0, 0);
          const diffMins = (now.getTime() - schedDate.getTime()) / (1000 * 60);
          if (diffMins > 15) isCriticalLate = true;
        }
      } else if (day === 6) {
        if (!isWithinRange(now, settings.schedule.sat.in, settings.schedule.sat.out)) isOffSchedule = true;
      } else {
        isOffSchedule = true;
      }
    }

    if (isOffSchedule || isCriticalLate) {
      setPendingMarkData({ type, isLate: isCriticalLate });
      setStatus('justification_form');
      return;
    }

    processRegistration(type, isCriticalLate);
  };

  const processRegistration = (type: 'in' | 'out' | 'half_day', isLate: boolean, justification?: string) => {
    setIsProcessing(true);

    if (isLate && Notification.permission === "granted") {
      new Notification("ALERTA DE ASISTENCIA", {
        body: `El colaborador ${currentEmp?.name} ${currentEmp?.surname} ha marcado con más de 15 minutos de retraso.`,
        icon: APP_ICON_SVG
      });
    }

    const record: AttendanceRecord = {
      id: Math.random().toString(36).substr(2, 9),
      employeeId: currentEmp!.id,
      timestamp: new Date().toISOString(),
      type,
      status: 'confirmed',
      isLate,
      justification
    };

    onRegister(record);

    if (type === 'in') setSuccessMsg("INGRESO REGISTRADO");
    else if (type === 'out') setSuccessMsg("SALIDA REGISTRADA");
    else setSuccessMsg("MEDIA JORNADA REGISTRADA");

    setStatus('success');
    setPin('');
    setJustificationText('');
    setPendingMarkData(null);

    setTimeout(() => {
      setStatus('idle');
      setCurrentEmp(null);
      setIsProcessing(false);
    }, 3000);
  };

  const handleConfirmJustification = () => {
    if (!justificationText.trim()) {
      setFeedback({ isOpen: true, title: "Requerido", message: "Debe ingresar un motivo para continuar.", type: "error" });
      return;
    }
    if (pendingMarkData) {
      processRegistration(pendingMarkData.type, pendingMarkData.isLate, justificationText);
    }
  };

  const handlePinChange = () => {
    if (newPin.length !== 6 || newPin === currentEmp?.pin) {
      setFeedback({ isOpen: true, title: "Error de PIN", message: "Ingrese un PIN nuevo de 6 dígitos diferente al actual.", type: "error" });
      return;
    }

    const updated = employees.map(e => e.id === currentEmp?.id ? {
      ...e,
      pin: newPin,
      pinChanged: true,
      pinNeedsReset: false,
      pinResetRequested: false
    } : e);

    onUpdateEmployees(updated);

    setFeedback({ isOpen: true, title: "PIN Actualizado", message: "Su clave de acceso ha sido cambiada. Ahora puede marcar su asistencia.", type: "success" });
    setStatus('confirm');
    setNewPin('');
  };

  const handleRequestPinReset = () => {
    const emp = employees.find(e => e.identification === forgotCi && e.status === 'active');
    if (emp) {
      const updated = employees.map(e => e.id === emp.id ? { ...e, pinResetRequested: true } : e);
      onUpdateEmployees(updated);

      if (Notification.permission === "granted") {
        new Notification("SOLICITUD DE ACCESO", {
          body: `El colaborador ${emp.name} solicita resetear su PIN de asistencia.`,
          icon: APP_ICON_SVG
        });
      }

      setFeedback({ 
        isOpen: true, 
        title: "Solicitud Recibida", 
        message: "Su solicitud ha sido enviada al administrador. RRHH autorizará su nuevo acceso a la brevedad.", 
        type: "info" 
      });
      setStatus('idle');
      setForgotCi('');
    } else {
      setFeedback({ 
        isOpen: true, 
        title: "Error", 
        message: "Identificación no encontrada en el sistema.", 
        type: "error" 
      });
    }
  };

  useEffect(() => {
    if (pin.length === 6 && status === 'idle' && !isProcessing) {
      const emp = employees.find(e => e.pin === pin && e.status === 'active');
      if (emp) {
        setCurrentEmp(emp);
        if (!emp.pinChanged || emp.pinNeedsReset) {
          setStatus('change_pin');
        } else {
          setStatus('confirm');
        }
      } else {
        setStatus('error');
        setTimeout(() => { setStatus('idle'); setPin(''); }, 1500);
      }
    }
  }, [pin, employees, status, isProcessing]);

  useEffect(() => {
    const handleKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onBack();
      if (status !== 'idle' || isProcessing) return;
      if (e.key >= '0' && e.key <= '9' && pin.length < 6) setPin(p => p + e.key);
      if (e.key === 'Backspace') setPin(p => p.slice(0, -1));
    };
    window.addEventListener('keydown', handleKey);
    return () => window.removeEventListener('keydown', handleKey);
  }, [pin, status, isProcessing]);

  return (
    <div className="min-h-screen gradient-blue flex flex-col items-center justify-center p-4">
      {status === 'success' && (
        <div className="fixed inset-0 z-[100] bg-slate-900/80 backdrop-blur-md flex flex-col items-center justify-center fade-in p-6">
           <div className="bg-white p-10 rounded-[2.5rem] shadow-2xl flex flex-col items-center text-center animate-in zoom-in max-w-sm">
              <div className="w-16 h-16 bg-emerald-500 text-white rounded-full flex items-center justify-center text-3xl mb-4 shadow-lg animate-bounce">✓</div>
              <h2 className="text-slate-900 font-[950] text-xl uppercase tracking-tighter leading-none">{successMsg}</h2>
              <p className="text-slate-400 font-bold text-[9px] uppercase tracking-widest mt-2 italic">Sincronizado con RRHH</p>
           </div>
        </div>
      )}

      <div className={`w-full max-w-lg bg-white/95 backdrop-blur-3xl rounded-3xl md:rounded-[3.5rem] shadow-2xl p-6 md:p-12 flex flex-col items-center relative overflow-hidden ${status === 'success' ? 'opacity-0' : 'fade-in'}`}>
        <div className="mb-6 md:mb-8 transform scale-[0.6] sm:scale-[0.8]"><Clock /></div>

        {status === 'idle' && (
          <div className="w-full text-center">
            <h2 className="text-[10px] md:text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4 md:mb-6">Ingresar PIN de 6 dígitos</h2>
            <div className="flex gap-1.5 md:gap-2 justify-center mb-8 md:mb-10">
              {[...Array(6)].map((_, i) => (
                <div key={i} className={`w-8 h-12 md:w-10 md:h-16 border-b-4 flex items-center justify-center text-2xl md:text-4xl font-black transition-all ${pin.length > i ? 'border-blue-600 text-slate-900' : 'border-slate-100'}`}>
                  {pin[i] ? '•' : ''}
                </div>
              ))}
            </div>
            <div className="grid grid-cols-3 gap-2 md:gap-3 max-w-[280px] md:max-w-[340px] mx-auto mb-8 md:mb-10">
              {[1, 2, 3, 4, 5, 6, 7, 8, 9, 'C', 0, '←'].map(btn => (
                <button 
                  key={btn} 
                  onClick={() => {
                    if (btn === 'C') setPin('');
                    else if (btn === '←') setPin(p => p.slice(0, -1));
                    else if (pin.length < 6) setPin(p => p + btn);
                  }} 
                  className="h-14 md:h-18 bg-white hover:bg-blue-700 hover:text-white rounded-xl md:rounded-2xl text-xl md:text-2xl font-black border border-slate-200 active:scale-90 transition-all shadow-sm flex items-center justify-center"
                >
                  {btn}
                </button>
              ))}
            </div>

            <button 
              onClick={() => setStatus('forgotten_form')}
              className="w-full py-3 md:py-4 bg-slate-50 border border-slate-100 rounded-xl md:rounded-2xl text-[9px] md:text-[10px] font-black text-blue-600 uppercase tracking-widest hover:bg-blue-50 transition-all active:scale-95"
            >
              ¿Olvidó su PIN? Solicitar Reseteo
            </button>
          </div>
        )}

        {status === 'justification_form' && (
          <div className="text-center w-full space-y-4 md:space-y-6 animate-in zoom-in">
             <div className="w-16 h-16 md:w-20 md:h-20 bg-blue-50 text-blue-600 rounded-2xl md:rounded-3xl flex items-center justify-center text-3xl mx-auto mb-2 border border-blue-100 shadow-inner">📝</div>
             <h2 className="text-xl md:text-2xl font-[950] text-slate-900 uppercase tracking-tighter">Justificación Requerida</h2>
             <p className="text-[9px] md:text-[10px] text-slate-500 font-black uppercase tracking-widest leading-relaxed">Su marcación presenta una excepción horaria.</p>
             <textarea 
               value={justificationText}
               onChange={e => setJustificationText(e.target.value)}
               className="w-full border-2 p-4 md:p-5 rounded-xl md:rounded-2xl text-[11px] font-black uppercase focus:border-blue-600 outline-none bg-slate-50 min-h-[100px] md:min-h-[120px]" 
               placeholder="Escriba el motivo..." 
               autoFocus 
             />
             <div className="grid grid-cols-2 gap-2 md:gap-3">
                <button onClick={() => setStatus('confirm')} className="w-full py-3 md:py-4 bg-slate-100 text-slate-600 font-black rounded-xl md:rounded-2xl uppercase text-[9px] md:text-[10px] tracking-widest active:scale-95">Cancelar</button>
                <button onClick={handleConfirmJustification} className="w-full py-3 md:py-4 bg-blue-700 text-white font-black rounded-xl md:rounded-2xl uppercase text-[9px] md:text-[10px] tracking-widest shadow-xl active:scale-95">Confirmar</button>
             </div>
          </div>
        )}

        {status === 'forgotten_form' && (
          <div className="text-center w-full space-y-4 md:space-y-6 animate-in zoom-in">
            <h2 className="text-xl md:text-2xl font-[950] text-slate-900 uppercase tracking-tighter">Solicitar Nuevo PIN</h2>
            <p className="text-[10px] md:text-xs text-slate-500 font-bold uppercase tracking-widest">Ingrese su Identificación</p>
            <input 
              maxLength={10} 
              type="text" 
              inputMode="numeric"
              value={forgotCi} 
              onChange={e => setForgotCi(e.target.value.replace(/\D/g,''))} 
              className="w-full border-2 p-4 md:p-5 rounded-xl md:rounded-2xl text-center text-2xl md:text-3xl font-black focus:border-blue-600 outline-none bg-slate-50" 
              placeholder="0000000000" 
              autoFocus 
            />
            <div className="grid grid-cols-2 gap-2 md:gap-3">
              <button onClick={() => setStatus('idle')} className="w-full py-3 md:py-4 bg-slate-100 text-slate-600 font-black rounded-xl md:rounded-2xl uppercase text-[9px] md:text-[10px] tracking-widest active:scale-95">Cancelar</button>
              <button onClick={handleRequestPinReset} className="w-full py-3 md:py-4 bg-blue-700 text-white font-black rounded-xl uppercase text-[9px] md:text-[10px] tracking-widest shadow-xl active:scale-95">Enviar</button>
            </div>
          </div>
        )}

        {status === 'change_pin' && currentEmp && (
          <div className="text-center w-full space-y-4 md:space-y-6">
            <h2 className="text-xl md:text-2xl font-[950] text-slate-900 uppercase">Seguridad Obligatoria</h2>
            <p className="text-[10px] md:text-xs text-slate-500 font-bold uppercase tracking-widest">Establezca su PIN de 6 dígitos</p>
            <input 
              maxLength={6} 
              type="password" 
              inputMode="numeric"
              value={newPin} 
              onChange={e => setNewPin(e.target.value.replace(/\D/g,''))} 
              className="w-full border-2 p-4 md:p-5 rounded-xl md:rounded-2xl text-center text-3xl md:text-4xl font-black focus:border-blue-600 outline-none bg-slate-50" 
              placeholder="••••••" 
              autoFocus 
            />
            <button onClick={handlePinChange} className="w-full py-4 md:py-5 bg-blue-700 text-white font-black rounded-xl md:rounded-[2rem] uppercase text-[10px] md:text-[11px] tracking-widest shadow-2xl active:scale-95 transition-all">Guardar PIN</button>
          </div>
        )}

        {status === 'confirm' && currentEmp && (
          <div className="text-center w-full animate-in zoom-in">
            <div className="w-20 h-20 md:w-24 md:h-24 bg-slate-100 rounded-2xl md:rounded-[2rem] mx-auto flex items-center justify-center text-3xl md:text-4xl font-black text-blue-700 uppercase border-4 border-white shadow-xl mb-3 md:mb-4 overflow-hidden">
                 {currentEmp.photo ? <img src={currentEmp.photo} className="w-full h-full object-cover" /> : <span>{currentEmp.name[0]}</span>}
            </div>
            <h2 className="text-xl md:text-2xl font-[950] text-slate-900 mb-1 uppercase tracking-tighter leading-none">{currentEmp.name} {currentEmp.surname}</h2>
            <p className="text-[8px] md:text-[9px] font-black text-slate-400 uppercase tracking-[0.4em] mb-6 md:mb-8">{currentEmp.role}</p>

            <div className="space-y-4">
              <section className="space-y-2">
                <p className="text-[7px] font-black text-slate-300 uppercase tracking-widest text-left">Primera Jornada (Mañana)</p>
                <div className="grid grid-cols-2 gap-2">
                  <button onClick={() => handleMark('in')} className="py-4 bg-blue-700 text-white rounded-xl font-black text-xs uppercase shadow-lg active:scale-95 transition-all border-b-2 border-blue-900">Ingreso</button>
                  <button onClick={() => handleMark('out')} className="py-4 bg-slate-800 text-white rounded-xl font-black text-xs uppercase shadow-lg active:scale-95 transition-all border-b-2 border-slate-950">Salida</button>
                </div>
              </section>

              <section className="space-y-2">
                <p className="text-[7px] font-black text-slate-300 uppercase tracking-widest text-left">Segunda Jornada (Tarde)</p>
                <div className="grid grid-cols-2 gap-2">
                  <button onClick={() => handleMark('in')} className="py-4 bg-blue-600 text-white rounded-xl font-black text-xs uppercase shadow-lg active:scale-95 transition-all border-b-2 border-blue-800">Ingreso</button>
                  <button onClick={() => handleMark('out')} className="py-4 bg-slate-700 text-white rounded-xl font-black text-xs uppercase shadow-lg active:scale-95 transition-all border-b-2 border-slate-900">Salida</button>
                </div>
              </section>

              <button 
                onClick={() => handleMark('half_day')} 
                className="w-full py-4 bg-emerald-600 text-white rounded-xl font-black text-xs uppercase shadow-lg active:scale-95 transition-all border-b-2 border-emerald-800 flex items-center justify-center gap-2"
              >
                <span>📅</span> Media Jornada Libre
              </button>
            </div>
          </div>
        )}

        {status === 'error' && (
          <div className="text-center text-red-600 py-6 md:py-10 animate-pulse">
            <div className="text-6xl md:text-7xl mb-4">✕</div>
            <h2 className="text-xl md:text-2xl font-[950] uppercase tracking-tighter">Denegado</h2>
            <p className="text-[9px] md:text-[10px] font-bold uppercase mt-2">PIN Incorrecto</p>
          </div>
        )}
      </div>

      <button onClick={onBack} className="mt-8 md:mt-10 text-white/30 hover:text-white font-black text-[10px] md:text-[11px] uppercase tracking-[0.4em] md:tracking-[0.6em] p-4 transition-all active:scale-95">Salir del Terminal</button>

      <Modal isOpen={feedback.isOpen} onClose={() => setFeedback({...feedback, isOpen: false})} title={feedback.title} type={feedback.type}>
          <div className="text-center space-y-4 md:space-y-6">
              <p className="text-slate-600 font-bold uppercase text-[11px] md:text-[12px] leading-relaxed">{feedback.message}</p>
              <button onClick={() => setFeedback({...feedback, isOpen: false})} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] tracking-widest">Aceptar</button>
          </div>
      </Modal>
    </div>
  );
};

export default AttendanceSystem;

import React, { useState, useMemo, useEffect } from 'react';
import { Role, CompanyConfig, Employee, AttendanceRecord, Payment, GlobalSettings, NotificationMessage } from '../types.ts';
import Sidebar from '../components/Sidebar.tsx';
import CompanyModule from './modules/CompanyModule.tsx';
import EmployeeModule from './modules/EmployeeModule.tsx';
import PayrollModule from './modules/PayrollModule.tsx';
import PaymentsModule from './modules/PaymentsModule.tsx';
import SettingsModule from './modules/SettingsModule.tsx';
import ReportsModule from './modules/ReportsModule.tsx';
import AiAssistant from './modules/AiAssistant.tsx';
import NotificationsModule from './modules/NotificationsModule.tsx';
import Modal from '../components/Modal.tsx';
import { DAILY_QUOTES, ACTIVE_BREAKS, ECUADOR_HOLIDAYS } from '../constants.tsx';

interface AdminDashboardProps {
  role: Role;
  isDbConnected?: boolean;
  onLogout: () => void;
  company: CompanyConfig | null;
  onUpdateCompany: (config: CompanyConfig) => void;
  employees: Employee[];
  onUpdateEmployees: (employees: Employee[]) => void;
  attendance: AttendanceRecord[];
  payments: Payment[];
  onUpdatePayments: (payments: Payment[]) => void;
  settings: GlobalSettings;
  onUpdateSettings: (settings: GlobalSettings) => void;
  onUpdateAppMode: (mode: 'full' | 'attendance') => void;
  appMode: 'full' | 'attendance';
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  role, isDbConnected, onLogout, company, onUpdateCompany, employees, onUpdateEmployees, attendance, payments, onUpdatePayments, settings, onUpdateSettings, onUpdateAppMode, appMode 
}) => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'company' | 'employees' | 'payroll' | 'payments' | 'settings' | 'reports' | 'ai' | 'notifications'>('dashboard');
  const [showInstallModal, setShowInstallModal] = useState(false);
  const [notifications, setNotifications] = useState<NotificationMessage[]>([]);
  const [dismissedNotificationIds, setDismissedNotificationIds] = useState<Set<string>>(new Set());

  const today = useMemo(() => new Date(), []);
  const todayDateStr = useMemo(() => today.toISOString().split('T')[0], [today]);
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();

  const addNotification = (title: string, message: string, type: 'info' | 'alert' | 'critical') => {
    const contentId = `notif-${title}-${message}`.replace(/\s/g, '-');

    if (dismissedNotificationIds.has(contentId)) return;

    setNotifications(prev => {
      if (prev.some(n => n.id === contentId)) return prev;
      return [{ id: contentId, title, message, timestamp: new Date().toISOString(), type, isRead: false, isProcessed: false }, ...prev];
    });
  };

  useEffect(() => {
    const activeEmployees = employees.filter(e => e.status === 'active');
    const markedTodayIds = new Set((attendance || [])
      .filter(a => a.timestamp.includes(todayDateStr))
      .map(a => a.employeeId));

    const missingAttendanceCount = activeEmployees.filter(e => !markedTodayIds.has(e.id)).length;
    if (missingAttendanceCount > 0 && activeTab === 'dashboard') {
      addNotification(
        "Pendiente de Ingreso", 
        `Hay ${missingAttendanceCount} colaboradores que aún no han registrado su marcación hoy.`, 
        'alert'
      );
    }
  }, [employees, attendance, todayDateStr, activeTab, dismissedNotificationIds]);

  const unreadCount = notifications.filter(n => !n.isRead).length;

  const dayOfYear = useMemo(() => {
    const start = new Date(today.getFullYear(), 0, 0);
    const diff = today.getTime() - start.getTime();
    return Math.floor(diff / (1000 * 60 * 60 * 24));
  }, [today]);

  const dailyQuote = DAILY_QUOTES[dayOfYear % DAILY_QUOTES.length];
  const activeBreak = ACTIVE_BREAKS[dayOfYear % ACTIVE_BREAKS.length];

  const relaxingImages = [
    "https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&q=80&w=2070",
    "https://images.unsplash.com/photo-1441974231531-c6227db76b6e?auto=format&fit=crop&q=80&w=2071",
    "https://images.unsplash.com/photo-1579783902614-a3fb3927b6a5?auto=format&fit=crop&q=80&w=2070",
    "https://images.unsplash.com/photo-1541450805268-4822a3a774ce?auto=format&fit=crop&q=80&w=2070"
  ];
  const currentRelaxingImage = relaxingImages[dayOfYear % relaxingImages.length];

  const calendarDays = useMemo(() => {
    const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
    const firstDay = new Date(currentYear, currentMonth, 1).getDay();
    const days = [];
    for (let i = 0; i < firstDay; i++) days.push(null);
    for (let i = 1; i <= daysInMonth; i++) days.push(i);
    return days;
  }, [currentMonth, currentYear]);

  const monthHolidays = ECUADOR_HOLIDAYS.filter(h => h.month === currentMonth);
  const monthBirthdays = employees.filter(e => {
    if (!e.birthDate || e.status !== 'active') return false;
    return new Date(e.birthDate).getMonth() === currentMonth;
  });

  const handleDismissNotification = (id: string) => {
    setDismissedNotificationIds(prev => new Set([...prev, id]));
    setNotifications(prev => prev.filter(n => n.id !== id));
  };

  const handlePurgeData = async () => {
    if (role !== Role.SUPER_ADMIN) return;
    onUpdateEmployees([]);
    onUpdatePayments([]);
  };

  return (
    <div className="flex h-screen bg-[#fcfdfe] overflow-hidden flex-col md:flex-row">
      <Sidebar 
        role={role} 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        onLogout={onLogout} 
        companyName={company?.name} 
        unreadCount={unreadCount}
      />

      <main className="flex-1 overflow-y-auto px-4 md:px-10 py-6 md:py-8 scroll-smooth custom-scroll">
        <header className="flex flex-col md:flex-row justify-between items-start md:items-center mb-4 md:mb-6 gap-4 md:gap-6 no-print pt-14 md:pt-0">
          <div className="flex flex-col sm:flex-row items-start sm:items-center gap-3 sm:gap-4 w-full md:w-auto">
            <h1 className="text-lg md:text-xl font-[950] text-slate-900 tracking-tight uppercase leading-none">Management Console</h1>
            <div className="flex items-center gap-3 px-3 py-1.5 bg-white border rounded-xl shadow-sm w-fit">
               <div className={`w-1.5 h-1.5 rounded-full ${isDbConnected ? 'bg-emerald-500' : 'bg-red-500'}`}></div>
               <span className="text-[7px] font-black uppercase tracking-[0.2em] text-slate-500">{isDbConnected ? 'Sincronizado' : 'Sin Conexión'}</span>
            </div>
          </div>
        </header>

        <div className="animate-in fade-in duration-500 pb-20 md:pb-0">
          {activeTab === 'dashboard' && (
            <div className="space-y-4 md:space-y-6">

              <div className="relative overflow-hidden bg-slate-900 rounded-3xl p-5 md:p-6 text-white shadow-xl min-h-[90px] flex items-center bg-cover bg-center" style={{ backgroundImage: `linear-gradient(rgba(15, 23, 42, 0.7), rgba(15, 23, 42, 0.7)), url(${currentRelaxingImage})` }}>
                  <div className="relative z-10 w-full text-center md:text-left">
                    <p className="text-blue-400 font-black text-[7px] uppercase tracking-[0.4em] mb-2">Mensaje del día</p>
                    <h2 className="text-base md:text-lg font-[800] leading-tight tracking-tight italic">"{dailyQuote}"</h2>
                  </div>
              </div>

              <div className="grid grid-cols-1 lg:grid-cols-4 gap-4 md:gap-6">
                <div className="lg:col-span-2 bg-white p-4 md:p-5 rounded-3xl border border-slate-100 shadow-sm">
                   <div className="flex justify-between items-center mb-3">
                      <h3 className="text-[9px] font-black text-slate-900 uppercase tracking-widest leading-none">Calendario Corporativo</h3>
                      <div className="flex gap-2">
                         <span className="flex items-center gap-1 text-[6px] font-black text-blue-600 uppercase">Festivo</span>
                         <span className="flex items-center gap-1 text-[6px] font-black text-emerald-600 uppercase">Natalicio</span>
                      </div>
                   </div>
                   <div className="grid grid-cols-7 gap-1 text-center max-w-[340px] mx-auto">
                      {['D', 'L', 'M', 'M', 'J', 'V', 'S'].map(d => (
                        <div key={d} className="text-[7px] font-black text-slate-300 uppercase py-0.5">{d}</div>
                      ))}
                      {calendarDays.map((day, i) => {
                        const isHoliday = day && monthHolidays.some(h => h.day === day);
                        const isBirthday = day && monthBirthdays.some(e => new Date(e.birthDate).getDate() === day);
                        const isToday = day === today.getDate();

                        return (
                          <div key={i} className={`
                            relative aspect-square flex items-center justify-center text-[8px] font-bold rounded-lg transition-all
                            ${!day ? 'opacity-0' : 'hover:bg-slate-50 cursor-default'}
                            ${isToday ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-600'}
                            ${isHoliday ? 'border border-blue-500/30 text-blue-600 bg-blue-50/50' : ''}
                            ${isBirthday ? 'border border-emerald-500/30 text-emerald-600 bg-emerald-50/50' : ''}
                          `}>
                            {day}
                          </div>
                        );
                      })}
                   </div>
                </div>

                <div className="lg:col-span-2 bg-slate-50 p-4 md:p-5 rounded-3xl border border-slate-100 space-y-3">
                   <h3 className="text-[8px] font-black text-slate-400 uppercase tracking-[0.2em] border-b pb-1.5">Próximos Eventos del Mes</h3>
                   <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-1 gap-2 max-h-[160px] overflow-y-auto custom-scroll pr-1">
                      {monthHolidays.map((h, i) => (
                         <div key={i} className="flex gap-3 items-center bg-white p-2 rounded-xl border border-slate-100 shadow-sm">
                            <span className="text-sm">📅</span>
                            <div>
                               <p className="text-[8px] font-black text-slate-900 uppercase leading-none truncate max-w-[120px]">{h.name}</p>
                               <p className="text-[6px] font-bold text-blue-500 uppercase mt-1">Día {h.day}</p>
                            </div>
                         </div>
                      ))}
                      {monthBirthdays.map((e, i) => (
                         <div key={i} className="flex gap-3 items-center bg-white p-2 rounded-xl border border-slate-100 shadow-sm">
                            <div className="w-6 h-6 rounded-lg overflow-hidden border bg-slate-100 flex items-center justify-center text-[8px] font-black uppercase text-slate-300">
                               {e.photo ? <img src={e.photo} className="w-full h-full object-cover" /> : <span>{e.name[0]}</span>}
                            </div>
                            <div>
                               <p className="text-[8px] font-black text-slate-900 uppercase leading-none truncate max-w-[120px]">{e.surname} {e.name}</p>
                               <p className="text-[6px] font-bold text-emerald-500 uppercase mt-1">Día {new Date(e.birthDate).getDate()}</p>
                            </div>
                         </div>
                      ))}
                      {monthHolidays.length === 0 && monthBirthdays.length === 0 && (
                        <p className="text-[7px] text-slate-300 font-black uppercase text-center py-6 col-span-full">Sin registros cercanos</p>
                      )}
                   </div>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-4 md:gap-6 items-stretch">
                <div className="md:col-span-2 bg-white p-6 md:p-8 rounded-3xl border border-slate-100 flex flex-col justify-center shadow-sm">
                  <div className="flex items-center gap-5 mb-4">
                    <span className="text-3xl p-3 bg-blue-50 rounded-2xl">{activeBreak.icon}</span>
                    <div>
                      <h3 className="text-[11px] font-black text-slate-900 uppercase leading-none">Salud Ocupacional</h3>
                      <p className="text-[8px] font-black text-blue-600 uppercase tracking-widest mt-1">Sugerencia de Bienestar</p>
                    </div>
                  </div>
                  <div className="space-y-2">
                    <h4 className="text-xs font-[900] text-slate-800 uppercase tracking-tight">{activeBreak.title}</h4>
                    <p className="text-slate-500 text-[10px] md:text-[11px] leading-relaxed font-medium">{activeBreak.description}</p>
                  </div>
                </div>

                <div className="relative overflow-hidden bg-white rounded-3xl shadow-lg border border-slate-100 min-h-[100px] md:min-h-full">
                   <img 
                     src={currentRelaxingImage} 
                     alt="Relajación" 
                     className="w-full h-full object-cover"
                   />
                   <div className="absolute inset-0 bg-gradient-to-t from-black/50 to-transparent flex items-end p-4">
                      <p className="text-[7px] font-black text-white/50 uppercase tracking-[0.5em]">Ambiente Zen</p>
                   </div>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'notifications' && (
            <NotificationsModule 
              notifications={notifications} 
              onToggleRead={handleDismissNotification}
              onToggleProcessed={handleDismissNotification}
              onClearAll={() => {
                const allIds = notifications.map(n => n.id);
                setDismissedNotificationIds(prev => new Set([...prev, ...allIds]));
                setNotifications([]);
              }}
            />
          )}

          {activeTab === 'company' && <CompanyModule company={company} onUpdate={onUpdateCompany} role={role} />}
          {activeTab === 'employees' && <EmployeeModule employees={employees} onUpdate={onUpdateEmployees} role={role} attendance={attendance} payments={payments} company={company} />}
          {activeTab === 'payroll' && <PayrollModule employees={employees} payments={payments} attendance={attendance} company={company} settings={settings} role={role} />}
          {activeTab === 'payments' && <PaymentsModule employees={employees} payments={payments} onUpdate={onUpdatePayments} role={role} company={company} />}
          {activeTab === 'settings' && <SettingsModule settings={settings} onUpdate={onUpdateSettings} role={role} onPurge={handlePurgeData} allData={{ company, employees, attendance, payments, settings }} />}
          {activeTab === 'reports' && <ReportsModule employees={employees} payments={payments} attendance={attendance} company={company} settings={settings} role={role} />}
          {activeTab === 'ai' && <AiAssistant employees={employees} attendance={attendance} payments={payments} role={role} />}
        </div>
      </main>

      <Modal isOpen={showInstallModal} onClose={() => setShowInstallModal(false)} title="Modo de Estación" maxWidth="max-w-md">
         <div className="space-y-6">
            <p className="text-[11px] text-slate-500 text-center font-bold uppercase tracking-widest">Seleccione la interfaz para este dispositivo:</p>
            <div className="space-y-3">
               <button onClick={() => { onUpdateAppMode('full'); setShowInstallModal(false); }} className={`w-full p-6 rounded-2xl border-2 text-left flex items-center justify-between transition-all ${appMode === 'full' ? 'border-blue-600 bg-blue-50' : 'border-slate-100'}`}>
                  <div>
                    <p className="font-black text-sm text-slate-900 uppercase">Administrativa Full</p>
                    <p className="text-[10px] text-slate-400 font-bold uppercase mt-1">Acceso total a gestión.</p>
                  </div>
               </button>
               <button onClick={() => { onUpdateAppMode('attendance'); setShowInstallModal(false); }} className={`w-full p-6 rounded-2xl border-2 text-left flex items-center justify-between transition-all ${appMode === 'attendance' ? 'border-blue-600 bg-blue-50' : 'border-slate-100'}`}>
                  <div>
                    <p className="font-black text-sm text-slate-900 uppercase">Marcación Only</p>
                    <p className="text-[10px] text-slate-400 font-bold uppercase mt-1">Kiosco de asistencia.</p>
                  </div>
               </button>
            </div>
         </div>
      </Modal>
    </div>
  );
};

export default AdminDashboard;

import React, { useState } from 'react';
import { Employee, Payment, AttendanceRecord, CompanyConfig, GlobalSettings, Role } from '../../types.ts';
import { db, doc, setDoc, deleteDoc, compressData } from '../../firebase.ts';
import Modal from '../../components/Modal.tsx';

interface ReportsModuleProps {
  employees: Employee[];
  payments: Payment[];
  attendance: AttendanceRecord[];
  company: CompanyConfig | null;
  settings: GlobalSettings;
  role: Role;
}

const ReportsModule: React.FC<ReportsModuleProps> = ({ employees, payments, attendance = [], company, settings, role }) => {
  const [reportType, setReportType] = useState<'attendance' | 'payments' | 'validation'>('attendance');
  const [searchTerm, setSearchTerm] = useState('');
  const [feedback, setFeedback] = useState({ isOpen: false, title: '', message: '', type: 'success' as any });
  const [deleteConfirm, setDeleteConfirm] = useState<{isOpen: boolean, id: string | null}>({ isOpen: false, id: null });

  const pendingAttendance = (attendance || []).filter(a => a.status === 'pending_approval');

  const handleValidate = async (record: AttendanceRecord, newStatus: 'confirmed' | 'rejected') => {
    const updatedRecord = { 
      ...record, 
      status: newStatus,
      validatedAt: new Date().toISOString()
    };

    await setDoc(doc(db, "attendance", record.id), { payload: compressData(updatedRecord), timestamp: record.timestamp });
    setFeedback({ isOpen: true, title: "Actualización Exitosa", message: `La marcación ha sido validada como: ${newStatus.toUpperCase()}`, type: 'success' });
  };

  const confirmDeleteAttendance = async () => {
    if (!deleteConfirm.id) return;
    try {
      await deleteDoc(doc(db, "attendance", deleteConfirm.id));
      setDeleteConfirm({ isOpen: false, id: null });
      setFeedback({ isOpen: true, title: "Registro Eliminado", message: "La marcación ha sido borrada del sistema definitivamente.", type: 'success' });
    } catch (e) {
      setDeleteConfirm({ isOpen: false, id: null });
      setFeedback({ isOpen: true, title: "Error Crítico", message: "No se pudo eliminar el registro en la base de datos.", type: 'error' });
    }
  };

  const filteredPending = pendingAttendance.filter(req => {
    const emp = employees.find(e => e.id === req.employeeId);
    const searchStr = `${emp?.name} ${emp?.surname} ${emp?.identification} ${req.justification || ""}`.toLowerCase();
    return searchStr.includes(searchTerm.toLowerCase());
  });

  const exportAttendanceExcel = () => {
    let csv = "\uFEFFFecha,Hora,Colaborador,Identificación,Cargo,Tipo Marcación,Estado,Atraso,Justificación\n";
    (attendance || []).sort((a, b) => b.timestamp.localeCompare(a.timestamp)).forEach(rec => {
      const emp = employees.find(e => e.id === rec.employeeId);
      const date = new Date(rec.timestamp);
      csv += `"${date.toLocaleDateString()}","${date.toLocaleTimeString()}","${emp?.surname} ${emp?.name}","${emp?.identification}","${emp?.role}","${rec.type === 'in' ? 'Entrada' : 'Salida'}","${rec.status}","${rec.isLate ? 'SI' : 'NO'}","${rec.justification || ''}"\n`;
    });
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `REPORTE_ASISTENCIA_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  };

  const attendanceToDisplay = (attendance || []).filter(a => {
    const emp = employees.find(e => e.id === a.employeeId);
    const searchStr = `${emp?.surname} ${emp?.name} ${emp?.identification} ${a.justification || ""} ${a.status} ${a.type}`.toLowerCase();
    return searchStr.includes(searchTerm.toLowerCase());
  }).sort((a,b) => b.timestamp.localeCompare(a.timestamp));

  return (
    <div className="space-y-6 md:space-y-8 fade-in">
      <div className="flex flex-col md:flex-row justify-between items-center bg-white p-6 md:p-8 rounded-3xl md:rounded-[2rem] shadow-sm border border-slate-100 gap-6 no-print">
        <div className="w-full">
          <h2 className="text-xl md:text-2xl font-[950] text-slate-900 uppercase tracking-tighter">Reportes Institucionales</h2>
          <div className="flex flex-col sm:flex-row gap-4 mt-4">
            <div className="flex gap-2 overflow-x-auto pb-2 sm:pb-0 scroll-smooth no-scrollbar">
              <button onClick={() => {setReportType('attendance'); setSearchTerm('');}} className={`whitespace-nowrap px-4 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${reportType === 'attendance' ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-100 text-slate-400 hover:bg-slate-200'}`}>Registros de Asistencia</button>
              <button onClick={() => {setReportType('validation'); setSearchTerm('');}} className={`whitespace-nowrap px-4 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest relative transition-all ${reportType === 'validation' ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-100 text-slate-400 hover:bg-slate-200'}`}>
                Validaciones
                {pendingAttendance.length > 0 && <span className="absolute -top-1 -right-1 w-4 h-4 bg-red-500 text-white text-[8px] rounded-full flex items-center justify-center font-black animate-pulse shadow-md">{pendingAttendance.length}</span>}
              </button>
            </div>
            <input 
              type="text" 
              placeholder="Filtrar registros..." 
              className="flex-1 p-2.5 border rounded-xl text-[10px] font-bold uppercase outline-none focus:border-blue-500 shadow-sm" 
              value={searchTerm} 
              onChange={e => setSearchTerm(e.target.value)}
            />
          </div>
        </div>
        <div className="flex gap-2 w-full md:w-auto">
          <button onClick={exportAttendanceExcel} className="flex-1 md:flex-none px-6 py-4 bg-emerald-600 text-white font-black rounded-xl shadow-lg uppercase text-[9px] active:scale-95 transition-all">Excel Completo</button>
          <button onClick={() => window.print()} className="flex-1 md:flex-none px-6 py-4 bg-slate-900 text-white font-black rounded-xl shadow-lg uppercase text-[9px] active:scale-95 transition-all">Imprimir PDF</button>
        </div>
      </div>

      <div className="bg-white rounded-3xl md:rounded-[2rem] shadow-sm border overflow-hidden min-h-[450px]" id="reports-printable-area">
         <div className="hidden print:block text-center border-b-2 border-slate-900 pb-6 mb-8 px-10 pt-10">
           <h1 className="text-2xl font-[950] text-slate-900 uppercase italic leading-none">{company?.name || 'ASIST UP - HR ENTERPRISE'}</h1>
           <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mt-2">Reporte de {reportType === 'attendance' ? 'Asistencia Diaria' : 'Validaciones Pendientes'} - 2026</p>
           <div className="grid grid-cols-2 gap-4 mt-3 max-w-xl mx-auto text-[9px] font-bold uppercase text-slate-600">
             <p className="text-left border-l-4 border-slate-900 pl-3">RUC: {company?.ruc || '0000000000001'}</p>
             <p className="text-right border-r-4 border-slate-900 pr-3">Representante: {company?.legalRep || 'ADMINISTRACIÓN'}</p>
           </div>
           <p className="text-[7px] text-slate-400 mt-2 uppercase font-bold italic text-right">Generado: {new Date().toLocaleString()}</p>
         </div>

         <div className="p-6 md:p-10">
            {reportType === 'validation' ? (
              <div className="space-y-6">
                <h3 className="text-lg font-[950] text-slate-900 uppercase tracking-tighter border-b pb-4 no-print">Validaciones Pendientes por Revisar</h3>
                {filteredPending.length === 0 ? (
                  <div className="py-24 text-center bg-slate-50 rounded-3xl border-2 border-dashed border-slate-200">
                    <span className="text-5xl opacity-20">✅</span>
                    <p className="text-slate-400 font-black uppercase text-[10px] tracking-widest mt-6">No existen justificaciones pendientes</p>
                  </div>
                ) : (
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    {filteredPending.map(req => {
                      const emp = employees.find(e => e.id === req.employeeId);
                      return (
                        <div key={req.id} className="bg-white border rounded-3xl p-6 flex flex-col gap-5 hover:border-blue-500 transition-all shadow-sm">
                          <div className="flex justify-between items-start">
                            <div>
                              <p className="font-[950] text-slate-900 uppercase text-sm tracking-tight">{emp?.surname} {emp?.name}</p>
                              <p className="text-slate-400 font-black text-[8px] uppercase mt-1">CI: {emp?.identification} | {new Date(req.timestamp).toLocaleString()}</p>
                            </div>
                            <span className={`px-2 py-1 text-[8px] font-black rounded-lg uppercase ${req.type === 'in' ? 'bg-blue-50 text-blue-700' : 'bg-slate-100 text-slate-700'}`}>{req.type === 'in' ? 'Ingreso' : 'Salida'}</span>
                          </div>
                          <div className="space-y-2">
                             <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest">Justificación del Colaborador</p>
                             <p className="text-[11px] text-slate-600 font-bold bg-slate-50 p-4 rounded-2xl border leading-relaxed shadow-inner italic">"{req.justification}"</p>
                          </div>
                          <div className="grid grid-cols-2 gap-3 pt-2 no-print">
                             <button onClick={() => handleValidate(req, 'rejected')} className="py-3 bg-red-50 text-red-600 font-black text-[9px] uppercase rounded-xl hover:bg-red-100 transition-all active:scale-95">Rechazar</button>
                             <button onClick={() => handleValidate(req, 'confirmed')} className="py-3 bg-emerald-600 text-white font-black text-[9px] uppercase rounded-xl shadow-lg hover:bg-emerald-700 transition-all active:scale-95">Validar</button>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                )}
              </div>
            ) : (
               <div className="table-responsive">
                  <table className="w-full text-left min-w-[750px] print:min-w-0 print:table-auto">
                    <thead className="bg-slate-50 text-[9px] font-black uppercase text-slate-400 border-b tracking-widest print:bg-slate-900 print:text-white">
                      <tr>
                        <th className="p-4">Fecha / Hora</th>
                        <th className="p-4">Colaborador / Identificación</th>
                        <th className="p-4">Marcación</th>
                        <th className="p-4 text-center">Atraso</th>
                        <th className="p-4">Estado Sistema</th>
                        <th className="p-4 text-right no-print">Acción</th>
                      </tr>
                    </thead>
                    <tbody className="text-[9px] md:text-[10px] font-bold uppercase divide-y text-slate-600 print:text-slate-950">
                      {attendanceToDisplay.map(rec => {
                        const emp = employees.find(e => e.id === rec.employeeId);
                        return (
                          <tr key={rec.id} className="hover:bg-slate-50 transition-colors">
                            <td className="p-4 whitespace-nowrap">{new Date(rec.timestamp).toLocaleString()}</td>
                            <td className="p-4">
                               <p className="font-black text-slate-900">{emp?.surname} {emp?.name}</p>
                               <p className="text-[8px] font-bold text-slate-400">{emp?.identification}</p>
                            </td>
                            <td className="p-4 font-black">{rec.type === 'in' ? 'Ingreso' : rec.type === 'out' ? 'Salida' : 'Media Jornada'}</td>
                            <td className="p-4 text-center">
                               {rec.isLate ? <span className="text-red-600 font-black">SÍ (Crítico)</span> : <span className="text-emerald-600">NO</span>}
                            </td>
                            <td className="p-4">
                              <span className={`px-2 py-0.5 rounded-lg text-[8px] font-black uppercase shadow-sm ${rec.status === 'confirmed' ? 'bg-emerald-50 text-emerald-600' : rec.status === 'pending_approval' ? 'bg-blue-50 text-blue-600' : 'bg-red-50 text-red-600'}`}>{rec.status}</span>
                            </td>
                            <td className="p-4 text-right no-print">
                              {role === Role.SUPER_ADMIN && (
                                <button onClick={() => setDeleteConfirm({ isOpen: true, id: rec.id })} className="px-2 py-1.5 bg-red-50 text-red-600 text-[8px] font-black uppercase rounded-lg hover:bg-red-600 hover:text-white transition-all">Borrar</button>
                              )}
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
               </div>
            )}
         </div>

         <div className="hidden print:grid grid-cols-2 gap-10 mt-20 p-10 pt-20 border-t-2 border-slate-100">
           <div className="text-center">
              <div className="border-t-2 border-slate-900 pt-3 text-[10px] font-black uppercase">Firma RRHH / Supervisión</div>
              <p className="text-[7px] text-slate-400 mt-1 uppercase font-bold">Responsable de Auditoría</p>
           </div>
           <div className="text-center">
              <div className="border-t-2 border-slate-900 pt-3 text-[10px] font-black uppercase">Sello de Recepción</div>
           </div>
        </div>
      </div>

      {/* Modal de Confirmación de Borrado */}
      <Modal isOpen={deleteConfirm.isOpen} onClose={() => setDeleteConfirm({ isOpen: false, id: null })} title="Confirmar Eliminación" type="error" maxWidth="max-w-sm">
        <div className="space-y-6 text-center">
          <p className="text-xs font-black text-red-600 uppercase italic">Atención: Acción Irreversible</p>
          <p className="text-[11px] text-slate-500 font-medium">¿Está seguro de eliminar esta marcación permanentemente del servidor?</p>
          <div className="flex gap-3">
            <button onClick={() => setDeleteConfirm({ isOpen: false, id: null })} className="flex-1 py-4 bg-slate-100 text-slate-600 font-black rounded-xl uppercase text-[9px]">Cancelar</button>
            <button onClick={confirmDeleteAttendance} className="flex-1 py-4 bg-red-600 text-white font-black rounded-xl uppercase text-[9px] shadow-lg active:scale-95 transition-all">Borrar Registro</button>
          </div>
        </div>
      </Modal>

      <Modal isOpen={feedback.isOpen} onClose={() => setFeedback({...feedback, isOpen: false})} title={feedback.title} type={feedback.type}>
          <div className="text-center p-4">
              <p className="text-slate-600 font-bold uppercase text-[11px] leading-relaxed mb-6">{feedback.message}</p>
              <button onClick={() => setFeedback({...feedback, isOpen: false})} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] shadow-lg active:scale-95 transition-all">Aceptar</button>
          </div>
      </Modal>
    </div>
  );
};

export default ReportsModule;

import React, { useState, useEffect } from 'react';
import { Employee, Role, BloodType, Gender, CivilStatus, AbsenceRecord, TerminationReason } from '../../types.ts';
import Modal from '../../components/Modal.tsx';

interface EmployeeModuleProps {
  employees: Employee[];
  onUpdate: (employees: Employee[]) => void;
  role: Role;
  attendance: any[];
  payments: any[];
  company: any;
}

const EmployeeModule: React.FC<EmployeeModuleProps> = ({ employees, onUpdate, role }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingEmp, setEditingEmp] = useState<Employee | null>(null);
  const [viewingEmp, setViewingEmp] = useState<Employee | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [showArchived, setShowArchived] = useState(false);
  const [hasBankInfo, setHasBankInfo] = useState(true);

  const [isAbsenceModalOpen, setIsAbsenceModalOpen] = useState(false);
  const [isTermModalOpen, setIsTermModalOpen] = useState(false);
  const [isDeleteConfirmModalOpen, setIsDeleteConfirmModalOpen] = useState(false);

  const [newAbsence, setNewAbsence] = useState<Partial<AbsenceRecord>>({ type: 'Falta', justified: false, date: new Date().toISOString().split('T')[0], reason: '' });
  const [termData, setTermData] = useState({ reason: TerminationReason.VOLUNTARY, details: '', date: new Date().toISOString().split('T')[0] });

  const [feedback, setFeedback] = useState<{isOpen: boolean, title: string, message: string, type: 'success' | 'error' | 'info'}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  const initialForm: Partial<Employee> = {
    name: '', surname: '', identification: '', birthDate: '', phone: '', email: '', 
    gender: Gender.MASCULINO, civilStatus: CivilStatus.SOLTERO,
    origin: 'ECUATORIANA', address: '', 
    bloodType: BloodType.O_POS, startDate: new Date().toISOString().split('T')[0],
    role: Role.EMPLOYEE, salary: 482.00, status: 'active' as const, photo: '', pin: '',
    emergencyContact: { name: '', phone: '' },
    isFixed: true, isAffiliated: true, overSalaryType: 'monthly',
    bankInfo: { ifi: '', type: 'Ahorros', account: string = '' },
    absences: [],
    observations: []
  };

  const [form, setForm] = useState<Partial<Employee>>(initialForm);

  useEffect(() => {
    if (!form.isAffiliated && form.overSalaryType !== 'none') {
      setForm(prev => ({ ...prev, overSalaryType: 'none' }));
    }
  }, [form.isAffiliated]);

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setForm(prev => ({ ...prev, photo: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSave = () => {
    if (!form.name || !form.surname || !form.identification || !form.salary || !form.role) {
      setFeedback({ isOpen: true, title: "Error", message: "Nombres, apellidos, cédula, cargo y sueldo son obligatorios.", type: "error" });
      return;
    }
    const finalForm = { ...form };
    if (!hasBankInfo) finalForm.bankInfo = { ifi: 'NO APLICA', type: 'Ahorros', account: 'N/A' };

    let updatedList: Employee[];
    if (editingEmp) {
      updatedList = employees.map(e => e.id === editingEmp.id ? { ...e, ...finalForm } as Employee : e);
      setFeedback({ isOpen: true, title: "Éxito", message: "Expediente actualizado correctamente.", type: "success" });
    } else {
      const autoPin = Math.floor(100000 + Math.random() * 900000).toString();
      const newEmp: Employee = { 
        ...finalForm, 
        id: Math.random().toString(36).substr(2, 9), 
        pin: autoPin, 
        pinChanged: false, 
        pinNeedsReset: false, 
        pinResetRequested: false,
        absences: [], 
        observations: [], 
        totalHoursWorked: 0, 
        status: 'active' as const 
      } as Employee;
      updatedList = [...employees, newEmp];
      setFeedback({ isOpen: true, title: "Registro Exitoso", message: `Colaborador registrado. PIN PROVISIONAL: ${autoPin}.`, type: "success" });
    }
    onUpdate(updatedList);
    setIsModalOpen(false);
  };

  const handleApprovePinReset = (emp: Employee) => {
    const updated: Employee[] = employees.map(e => e.id === emp.id ? { 
      ...e, 
      pin: "000000", 
      pinNeedsReset: true, 
      pinResetRequested: false,
      pinChanged: false 
    } : e);
    onUpdate(updated);
    if (viewingEmp && viewingEmp.id === emp.id) {
       setViewingEmp({ ...viewingEmp, pinNeedsReset: true, pinResetRequested: false, pin: "000000", pinChanged: false });
    }
    setFeedback({ 
      isOpen: true, 
      title: "Reseteo Aprobado", 
      message: `PIN reseteado. El empleado debe establecer su clave en el terminal (PIN: 000000).`, 
      type: "success" 
    });
  };

  const handleAddAbsence = () => {
    if (!viewingEmp) return;
    const record: AbsenceRecord = { ...newAbsence, id: Math.random().toString(36).substr(2, 9) } as AbsenceRecord;
    const updated: Employee[] = employees.map(e => e.id === viewingEmp.id ? { ...e, absences: [...(e.absences || []), record] } : e);
    onUpdate(updated);
    setViewingEmp({ ...viewingEmp, absences: [...(viewingEmp.absences || []), record] });
    setIsAbsenceModalOpen(false);
  };

  const handleTerminate = () => {
    if (!viewingEmp) return;
    const updated: Employee[] = employees.map(e => e.id === viewingEmp.id ? { 
      ...e, 
      status: 'terminated' as const, 
      terminationDate: termData.date, 
      terminationReason: termData.reason, 
      terminationDetails: termData.details 
    } : e);
    onUpdate(updated);
    setViewingEmp(null);
    setIsTermModalOpen(false);
    setFeedback({ isOpen: true, title: "Desvinculación", message: "Colaborador desvinculado con éxito.", type: "success" });
  };

  const handleDeletePermanent = () => {
    if (!viewingEmp) return;
    const updated: Employee[] = employees.filter(e => e.id !== viewingEmp.id);
    onUpdate(updated);
    setViewingEmp(null);
    setIsDeleteConfirmModalOpen(false);
    setFeedback({ isOpen: true, title: "Registro Eliminado", message: "El colaborador ha sido borrado definitivamente.", type: "success" });
  };

  const filteredEmployees = employees.filter(e => {
    const searchString = `${e.name} ${e.surname} ${e.identification} ${e.role}`.toLowerCase();
    const matchesSearch = searchString.includes(searchTerm.toLowerCase());
    return showArchived 
      ? matchesSearch && (e.status === 'archived' || e.status === 'terminated') 
      : matchesSearch && e.status === 'active';
  });

  return (
    <div className="space-y-6 fade-in">
      <div className="bg-white p-6 rounded-3xl md:rounded-[2.5rem] shadow-sm border border-slate-100 flex flex-col md:flex-row justify-between items-center no-print gap-4">
        <div className="w-full md:w-auto text-center md:text-left">
          <h2 className="text-xl font-[950] text-slate-900 tracking-tighter uppercase leading-none">Gestión Humana</h2>
          <div className="flex gap-4 mt-2 justify-center md:justify-start">
            <button onClick={() => setShowArchived(false)} className={`text-[9px] font-black uppercase tracking-widest ${!showArchived ? 'text-blue-600 border-b-2 border-blue-600' : 'text-slate-400'}`}>Activos</button>
            <button onClick={() => setShowArchived(true)} className={`text-[9px] font-black uppercase tracking-widest ${showArchived ? 'text-blue-600 border-b-2 border-blue-600' : 'text-slate-400'}`}>Historial / Bajas</button>
          </div>
        </div>
        <div className="flex flex-col sm:flex-row gap-3 w-full md:w-auto">
          <input type="text" placeholder="Filtrar por nombre, CI..." className="w-full sm:w-64 p-3 border rounded-xl text-[11px] uppercase font-bold focus:border-blue-500 outline-none" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
          <button onClick={() => { setForm(initialForm); setEditingEmp(null); setIsModalOpen(true); }} className="w-full sm:w-auto px-6 py-3.5 bg-blue-700 text-white font-black rounded-xl shadow-lg uppercase text-[9px] tracking-widest active:scale-95 transition-all">Nuevo Registro</button>
        </div>
      </div>

      <div className="bg-white rounded-3xl md:rounded-[2.5rem] shadow-sm border overflow-hidden no-print">
        <div className="table-responsive">
          <table className="w-full text-left min-w-[600px] md:min-w-full">
            <thead className="bg-slate-50 text-[8px] font-black text-slate-400 uppercase tracking-widest">
              <tr>
                <th className="px-6 py-4">Colaborador</th>
                <th className="px-6 py-4">Identificación</th>
                <th className="px-6 py-4">Cargo</th>
                <th className="px-6 py-4 text-center">Estado</th>
                <th className="px-6 py-4 text-right">Acciones</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50 text-[10px] md:text-[11px] font-black uppercase">
              {filteredEmployees.map(emp => (
                <tr key={emp.id} className="hover:bg-blue-50/40 transition-colors">
                  <td className="px-6 py-3 font-black text-slate-900 flex items-center gap-3">
                    <div className="w-8 h-8 rounded-lg overflow-hidden border bg-slate-100 flex items-center justify-center shrink-0">
                      {emp.photo ? <img src={emp.photo} className="w-full h-full object-cover" /> : <span>👤</span>}
                    </div>
                    <span className="truncate">{emp.surname} {emp.name}</span>
                  </td>
                  <td className="px-6 py-3 font-mono">{emp.identification}</td>
                  <td className="px-6 py-3 text-blue-600 text-[9px]">{emp.role}</td>
                  <td className="px-6 py-3 text-center">
                    <span className={`px-3 py-1 rounded-full text-[8px] font-black uppercase ${emp.status === 'active' ? 'bg-emerald-50 text-emerald-600' : 'bg-red-50 text-red-600'}`}>
                      {emp.status === 'active' ? 'Activo' : 'Desvinculado'}
                    </span>
                  </td>
                  <td className="px-6 py-3 text-right flex gap-2 justify-end">
                     <button onClick={() => setViewingEmp(emp)} className="px-3 py-1.5 bg-blue-50 text-blue-700 rounded-lg text-[8px] font-black uppercase active:scale-95">Expediente</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <Modal isOpen={!!viewingEmp} onClose={() => setViewingEmp(null)} title="Expediente de Personal">
        {viewingEmp && (
          <div className="space-y-6">
            <div className="flex flex-col sm:flex-row gap-6 items-center border-b pb-6 text-center sm:text-left">
               <div className="w-24 h-24 rounded-2xl overflow-hidden border bg-slate-100 flex items-center justify-center shadow-lg shrink-0">
                  {viewingEmp.photo ? <img src={viewingEmp.photo} className="w-full h-full object-cover" /> : <span className="text-4xl">👤</span>}
               </div>
               <div className="flex-1">
                  <h3 className="text-xl md:text-2xl font-[950] text-slate-900 uppercase tracking-tighter leading-tight">{viewingEmp.surname} {viewingEmp.name}</h3>
                  <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest mt-1">{viewingEmp.role} | CI: {viewingEmp.identification}</p>
               </div>
            </div>
            {role === Role.SUPER_ADMIN && (
              <div className="pt-4 border-t space-y-3">
                 <div className="grid grid-cols-2 gap-3">
                   {viewingEmp.status === 'active' && (
                     <button onClick={() => setIsTermModalOpen(true)} className="w-full py-3 bg-red-50 text-red-600 rounded-xl text-[9px] font-black uppercase">Desvincular</button>
                   )}
                   <button onClick={() => setIsDeleteConfirmModalOpen(true)} className="w-full py-3 bg-red-700 text-white rounded-xl text-[9px] font-black uppercase shadow-lg">Eliminar</button>
                 </div>
              </div>
            )}
          </div>
        )}
      </Modal>

      <Modal isOpen={isDeleteConfirmModalOpen} onClose={() => setIsDeleteConfirmModalOpen(false)} title="CONFIRMAR ELIMINACIÓN" type="error" maxWidth="max-w-sm">
        <div className="space-y-6 text-center">
          <p className="text-xs font-black text-red-600 uppercase italic">Registro Maestro de Personal</p>
          <p className="text-[11px] text-slate-500 font-medium">¿Está seguro de eliminar permanentemente este expediente? No se puede deshacer.</p>
          <div className="flex gap-3">
            <button onClick={() => setIsDeleteConfirmModalOpen(false)} className="flex-1 py-4 bg-slate-100 text-slate-600 font-black rounded-xl uppercase text-[9px]">Cancelar</button>
            <button onClick={handleDeletePermanent} className="flex-1 py-4 bg-red-600 text-white font-black rounded-xl uppercase text-[9px] shadow-lg">Confirmar Borrado</button>
          </div>
        </div>
      </Modal>

      {/* Reutilización de modal feedback */}
      <Modal isOpen={feedback.isOpen} onClose={() => setFeedback({...feedback, isOpen: false})} title={feedback.title} type={feedback.type}>
        <div className="text-center p-4">
          <p className="text-[11px] font-bold uppercase leading-relaxed text-slate-600">{feedback.message}</p>
          <button onClick={() => setFeedback({...feedback, isOpen: false})} className="w-full py-3.5 bg-slate-900 text-white font-black rounded-xl uppercase text-[9px] mt-6 active:scale-95 transition-all">Aceptar</button>
        </div>
      </Modal>

      <Modal isOpen={isAbsenceModalOpen} onClose={() => setIsAbsenceModalOpen(false)} title="Registrar Novedad" maxWidth="max-w-sm">
         <div className="space-y-4">
            <select className="w-full border-2 p-3 rounded-xl text-[11px] font-bold" value={newAbsence.type} onChange={e => setNewAbsence({...newAbsence, type: e.target.value as any})}><option value="Falta">Falta</option><option value="Permiso">Permiso</option><option value="Atraso">Atraso</option></select>
            <input type="date" className="w-full border-2 p-3 rounded-xl text-[11px] font-bold" value={newAbsence.date} onChange={e => setNewAbsence({...newAbsence, date: e.target.value})} />
            <textarea className="w-full border-2 p-3 rounded-xl text-[11px] font-bold h-20" placeholder="Motivo..." value={newAbsence.reason} onChange={e => setNewAbsence({...newAbsence, reason: e.target.value})} />
            <button onClick={handleAddAbsence} className="w-full py-4 bg-blue-600 text-white font-black rounded-xl uppercase text-[10px]">Guardar Novedad</button>
         </div>
      </Modal>

      <Modal isOpen={isTermModalOpen} onClose={() => setIsTermModalOpen(false)} title="Salida de Personal" maxWidth="max-w-sm">
         <div className="space-y-4">
            <label className="text-[9px] font-black text-slate-400 uppercase">Motivo</label>
            <select className="w-full border-2 p-3 rounded-xl text-[11px] font-bold" value={termData.reason} onChange={e => setTermData({...termData, reason: e.target.value as TerminationReason})}>{Object.values(TerminationReason).map(r => <option key={r} value={r}>{r}</option>)}</select>
            <label className="text-[9px] font-black text-slate-400 uppercase">Fecha</label>
            <input type="date" className="w-full border-2 p-3 rounded-xl text-[11px] font-bold" value={termData.date} onChange={e => setTermData({...termData, date: e.target.value})} />
            <button onClick={handleTerminate} className="w-full py-4 bg-red-600 text-white font-black rounded-xl uppercase text-[10px] shadow-lg">Confirmar Salida</button>
         </div>
      </Modal>
    </div>
  );
};

