import React, { useState } from 'react';
import { Employee, Payment, Role, CompanyConfig } from '../../types.ts';
import Modal from '../../components/Modal.tsx';

interface PaymentsModuleProps {
  employees: Employee[];
  payments: Payment[];
  onUpdate: (payments: Payment[]) => void;
  role: Role;
  company: CompanyConfig | null;
}

const PaymentsModule: React.FC<PaymentsModuleProps> = ({ employees, payments, onUpdate, role, company }) => {
  const [isPayOpen, setIsPayOpen] = useState(false);
  const [selectedPayForPrint, setSelectedPayForPrint] = useState<Payment | null>(null);
  const [isVoidModalOpen, setIsVoidModalOpen] = useState(false);
  const [isDeleteConfirmModalOpen, setIsDeleteConfirmModalOpen] = useState(false);
  const [payToDeleteId, setPayToDeleteId] = useState<string | null>(null);
  const [voidPay, setVoidPay] = useState<Payment | null>(null);
  const [voidJustification, setVoidJustification] = useState('');
  const [searchTerm, setSearchTerm] = useState('');

  const [payForm, setPayForm] = useState<Partial<Payment>>({ 
    type: 'Salary', 
    amount: 0, 
    method: 'Efectivo', 
    concept: '', 
    month: new Date().toLocaleString('es-EC', {month: 'long'}).toUpperCase(), 
    year: '2026', 
    status: 'paid' 
  });

  const [feedback, setFeedback] = useState<{isOpen: boolean, title: string, message: string, type: 'success' | 'error' | 'info'}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  const handleCreate = () => {
    if (!payForm.employeeId || !payForm.amount) {
        setFeedback({ isOpen: true, title: "Error", message: "Seleccione colaborador y monto.", type: "error" });
        return;
    }
    const newPay: Payment = { ...payForm, id: Math.random().toString(36).substr(2, 15), date: new Date().toISOString(), status: 'paid' } as Payment;
    onUpdate([newPay, ...payments]);
    setIsPayOpen(false);
    setFeedback({ isOpen: true, title: "Éxito", message: "Pago registrado en tesorería.", type: "success" });
  };

  const handleVoid = () => {
    if (!voidPay || !voidJustification) return;
    const updated = payments.map(p => p.id === voidPay.id ? { ...p, status: 'void' as const, voidJustification } : p);
    onUpdate(updated);
    setIsVoidModalOpen(false);
    setVoidPay(null);
    setVoidJustification('');
    setFeedback({ isOpen: true, title: "Pago Anulado", message: "El comprobante ha sido invalidado.", type: "success" });
  };

  const confirmDeletePermanent = () => {
    if (!payToDeleteId) return;
    const updated = payments.filter(p => p.id !== payToDeleteId);
    onUpdate(updated);
    setPayToDeleteId(null);
    setIsDeleteConfirmModalOpen(false);
    setFeedback({ isOpen: true, title: "Eliminado", message: "Registro borrado permanentemente de tesorería.", type: "success" });
  };

  const exportAllExcel = () => {
    let csv = "\uFEFFFecha,Empleado,CI,Monto,Tipo,Concepto,Estado\n";
    payments.forEach(p => {
      const emp = employees.find(e => e.id === p.employeeId);
      csv += `"${new Date(p.date).toLocaleDateString()}","${emp?.surname} ${emp?.name}","${emp?.identification}",${p.amount.toFixed(2)},"${p.type}","${p.concept}","${p.status}"\n`;
    });
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `TESORERIA_GLOBAL_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  };

  const exportSingleExcel = (p: Payment) => {
    const emp = employees.find(e => e.id === p.employeeId);
    let csv = "\uFEFFCAMPO,VALOR\n";
    csv += `ID TRANSACCION,${p.id}\n`;
    csv += `FECHA EMISION,${new Date(p.date).toLocaleString()}\n`;
    csv += `VALOR TOTAL,${p.amount.toFixed(2)}\n`;
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `COMPROBANTE_${p.id.substr(0,8)}.csv`;
    link.click();
  };

  const filteredPayments = payments.filter(p => {
    const emp = employees.find(e => e.id === p.employeeId);
    const searchStr = `${emp?.name} ${emp?.surname} ${emp?.identification} ${p.concept} ${p.type} ${p.month}`.toLowerCase();
    return searchStr.includes(searchTerm.toLowerCase());
  });

  return (
    <div className="space-y-6 fade-in">
      <div className="flex flex-col md:flex-row justify-between items-center bg-white p-8 rounded-[2.5rem] shadow-sm border border-slate-100 gap-6 no-print">
        <div>
           <h2 className="text-xl font-[950] text-slate-900 uppercase tracking-tighter">Caja y Tesorería</h2>
           <p className="text-[9px] font-black text-blue-600 uppercase tracking-widest mt-1">Control de Egresos Institucionales</p>
        </div>
        <div className="flex gap-4 w-full md:w-auto">
          <input type="text" placeholder="Buscar beneficiario, CI..." className="flex-1 md:w-80 p-3 border rounded-xl text-[10px] font-bold uppercase outline-none focus:border-blue-500" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
          <button onClick={exportAllExcel} className="px-6 py-4 bg-slate-100 text-slate-600 font-black rounded-2xl uppercase text-[10px] tracking-widest active:scale-95 transition-all">Excel Global</button>
          <button onClick={() => window.print()} className="px-6 py-4 bg-slate-900 text-white font-black rounded-2xl uppercase text-[10px] tracking-widest active:scale-95 transition-all shadow-lg">Imprimir PDF</button>
          <button onClick={() => setIsPayOpen(true)} className="px-8 py-4 bg-emerald-600 text-white font-black rounded-2xl shadow-lg uppercase text-[10px] tracking-widest active:scale-95 transition-all">Nuevo Egreso</button>
        </div>
      </div>

      <div className="bg-white rounded-[2rem] shadow-sm border overflow-hidden">
        <div className="table-responsive">
          <table className="w-full text-left min-w-[700px]">
            <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest">
              <tr><th className="px-8 py-4">Fecha Emisión</th><th className="px-8 py-4">Beneficiario / CI</th><th className="px-8 py-4 text-center">Detalle Egreso</th><th className="px-8 py-4">Valor Pagado</th><th className="px-8 py-4">Estado</th><th className="px-8 py-4 text-right no-print">Acciones</th></tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredPayments.map(p => {
                const emp = employees.find(e => e.id === p.employeeId);
                return (
                  <tr key={p.id} className={`text-xs hover:bg-slate-50 transition-all ${p.status === 'void' ? 'opacity-40 grayscale bg-slate-50' : ''}`}>
                    <td className="px-8 py-4 font-bold">{new Date(p.date).toLocaleDateString()}</td>
                    <td className="px-8 py-4 whitespace-nowrap"><p className="font-black uppercase text-slate-900">{emp?.surname} {emp?.name}</p><p className="text-[9px] text-slate-400 font-bold">{emp?.identification}</p></td>
                    <td className="px-8 py-4 text-center"><p className="text-[10px] font-black uppercase text-slate-500">{p.type}</p><p className="text-[8px] font-bold text-slate-400 truncate max-w-[150px]">{p.concept}</p></td>
                    <td className="px-8 py-4 font-black text-blue-700">${p.amount.toFixed(2)}</td>
                    <td className="px-8 py-4"><span className={`px-2 py-1 rounded-full text-[8px] font-black uppercase ${p.status === 'paid' ? 'bg-emerald-50 text-emerald-600' : 'bg-red-50 text-red-600'}`}>{p.status === 'paid' ? 'Efectivo' : 'Anulado'}</span></td>
                    <td className="px-8 py-4 text-right flex gap-2 justify-end no-print">
                      <button onClick={() => setSelectedPayForPrint(p)} className="px-2 py-1.5 bg-blue-50 text-blue-600 font-black rounded-lg text-[8px] uppercase active:scale-95 shadow-sm">Comprobante</button>
                      {role === Role.SUPER_ADMIN && (
                        <button onClick={() => { setPayToDeleteId(p.id); setIsDeleteConfirmModalOpen(true); }} className="px-2 py-1.5 bg-red-700 text-white font-black rounded-lg text-[8px] uppercase active:scale-95 shadow-sm">Borrar</button>
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      <Modal isOpen={isDeleteConfirmModalOpen} onClose={() => setIsDeleteConfirmModalOpen(false)} title="ELIMINAR TRANSACCIÓN" type="error" maxWidth="max-w-sm">
        <div className="space-y-6 text-center">
          <p className="text-xs font-black text-red-600 uppercase italic">Auditoría de Tesorería</p>
          <p className="text-[11px] text-slate-500 font-medium">¿Desea borrar este registro permanentemente del historial de caja?</p>
          <div className="flex gap-3">
            <button onClick={() => setIsDeleteConfirmModalOpen(false)} className="flex-1 py-4 bg-slate-100 text-slate-600 font-black rounded-xl uppercase text-[9px]">Cancelar</button>
            <button onClick={confirmDeletePermanent} className="flex-1 py-4 bg-red-600 text-white font-black rounded-xl uppercase text-[9px] shadow-lg">Confirmar Borrado</button>
          </div>
        </div>
      </Modal>

      {/* Resto de modales existentes se mantienen iguales */}
      <Modal isOpen={!!selectedPayForPrint} onClose={() => setSelectedPayForPrint(null)} title="Comprobante Institucional de Egreso">
        {selectedPayForPrint && (() => {
           const emp = employees.find(e => e.id === selectedPayForPrint.employeeId);
           return (
             <div className="p-10 space-y-10 bg-white" id="payment-voucher-print">
                <div className="text-center border-b-4 border-slate-900 pb-8">
                   <h3 className="text-3xl font-[950] text-slate-900 uppercase tracking-tighter italic leading-none">{company?.name || 'EMPRESA INSTITUCIONAL'}</h3>
                   <p className="text-[11px] font-black text-slate-400 mt-2 uppercase tracking-widest">COMPROBANTE DE CAJA / TESORERÍA - 2026</p>
                   <div className="grid grid-cols-2 gap-6 mt-4 max-w-xl mx-auto text-[10px] font-bold uppercase text-slate-700">
                     <p className="text-left border-l-4 border-slate-900 pl-3">RUC: {company?.ruc || '0000000000001'}</p>
                     <p className="text-right border-r-4 border-slate-900 pr-3">Representante: {company?.legalRep || 'GERENCIA'}</p>
                   </div>
                   <p className="text-[8px] text-slate-400 mt-2 uppercase font-bold italic text-right">Referencia ID: {selectedPayForPrint.id.substr(0,12).toUpperCase()}</p>
                </div>
                <div className="grid grid-cols-2 gap-10 text-[11px] font-bold uppercase">
                   <div className="space-y-6">
                      <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100"><p className="text-slate-400 text-[9px] font-black mb-1">Beneficiario del Desembolso</p><p className="text-slate-900 text-2xl font-[950] leading-none">{emp?.surname} {emp?.name}</p><p className="text-slate-500 font-black mt-1">Cédula: {emp?.identification}</p></div>
                   </div>
                   <div className="text-right space-y-6">
                      <div className="bg-slate-900 p-6 rounded-[2.5rem] text-white shadow-xl"><p className="text-white/60 text-[9px] font-black mb-1">Valor Neto Pagado</p><p className="text-5xl font-[950] tracking-tighter leading-none">${selectedPayForPrint.amount.toFixed(2)}</p></div>
                   </div>
                </div>
                <div className="mt-20 pt-16 grid grid-cols-2 gap-20 text-center">
                   <div className="border-t-2 border-slate-900 pt-4">
                      <p className="text-[11px] font-black uppercase text-slate-900">Firma del Beneficiario</p>
                      <p className="text-[8px] text-slate-400 mt-1 uppercase font-bold">Recibí Conforme</p>
                   </div>
                   <div className="border-t-2 border-slate-900 pt-4">
                      <p className="text-[11px] font-black uppercase text-slate-900">Firma Autorizada Caja</p>
                      <p className="text-[8px] text-slate-400 mt-1 uppercase font-bold">Entrega y Sello</p>
                   </div>
                </div>
                <div className="flex gap-4 no-print pt-10">
                   <button onClick={() => exportSingleExcel(selectedPayForPrint)} className="flex-1 py-5 bg-emerald-600 text-white font-black rounded-3xl uppercase text-[10px] tracking-widest active:scale-95 transition-all shadow-lg">Excel</button>
                   <button onClick={() => window.print()} className="flex-1 py-5 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] tracking-widest active:scale-95 transition-all shadow-lg">Imprimir</button>
                </div>
             </div>
           );
        })()}
      </Modal>

      <Modal isOpen={isPayOpen} onClose={() => setIsPayOpen(false)} title="Registrar Egreso Institucional">
        <div className="space-y-4 px-1">
          <label className="text-[9px] font-black text-slate-400 uppercase">Beneficiario del Pago</label>
          <select className="w-full border-2 p-3 rounded-xl bg-slate-50 text-[11px] font-black uppercase outline-none focus:border-blue-500" onChange={e => setPayForm({...payForm, employeeId: e.target.value})}><option value="">Seleccione...</option>{employees.filter(e => e.status === 'active').map(e => <option key={e.id} value={e.id}>{e.surname} {e.name}</option>)}</select>
          <label className="text-[9px] font-black text-slate-400 uppercase">Monto</label>
          <input type="number" step="0.01" className="w-full border-2 p-5 rounded-2xl font-[950] text-4xl text-center focus:border-emerald-500 outline-none" placeholder="0.00" onChange={e => setPayForm({...payForm, amount: Number(e.target.value)})} />
          <button onClick={handleCreate} className="w-full py-5 bg-emerald-600 text-white font-[950] rounded-[2rem] uppercase text-[11px] tracking-widest shadow-2xl active:scale-95 transition-all mt-4">Registrar Egreso</button>
        </div>
      </Modal>

      <Modal isOpen={feedback.isOpen} onClose={() => setFeedback({...feedback, isOpen: false})} title={feedback.title} type={feedback.type}><div className="text-center p-4"><p className="text-[11px] font-bold uppercase text-slate-600">{feedback.message}</p><button onClick={() => setFeedback({...feedback, isOpen: false})} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] mt-6 shadow-lg active:scale-95 transition-all">Aceptar</button></div></Modal>
    </div>
  );
};

