               <div className="space-y-4">
                  <h4 className="text-[10px] font-black text-red-600 uppercase border-b pb-1">Ajustes de Egresos</h4>
                  <div className="space-y-3">
                     <div className="flex items-center gap-3 p-3 bg-red-50 rounded-xl border border-red-100">
                        <input type="checkbox" className="w-5 h-5 accent-red-600" checked={editingEmployee.isAffiliated} onChange={e => setEditingEmployee({...editingEmployee, isAffiliated: e.target.checked})} />
                        <label className="text-[9px] font-black text-red-700 uppercase">Habilitar Aporte IESS</label>
