                     <div><label className="text-[8px] font-black text-slate-400 uppercase">Multas / Descuentos Varios ($)</label><div className="flex gap-2"><input type="number" step="0.01" className="w-24 border p-2 rounded-lg text-xs font-bold" value={adjustments.expense} onChange={e => setAdjustments({...adjustments, expense: Number(e.target.value)})} /><input type="text" placeholder="Concepto..." className="flex-1 border p-2 rounded-lg text-[9px] uppercase" value={adjustments.expenseConcept} onChange={e => setAdjustments({...adjustments, expenseConcept: e.target.value})} /></div></div>
