            </div>
          </div>
        )}
      </Modal>

      {/* Modal de Advertencia y Confirmación Final */}
      <Modal isOpen={showConfirmPayrollEdit} onClose={() => setShowConfirmPayrollEdit(false)} title="Confirmar Modificación" type="warning" maxWidth="max-w-sm">
        <div className="space-y-6 text-center">
          <p className="text-xs font-black text-yellow-600 uppercase italic leading-relaxed">Advertencia de Sistema</p>
          <p className="text-[11px] text-slate-600 font-bold leading-relaxed">¿Está seguro de modificar los valores de este rol de pagos? Esta acción alterará el neto a recibir del colaborador para el período seleccionado.</p>
          <div className="flex gap-3">
            <button onClick={() => setShowConfirmPayrollEdit(false)} className="flex-1 py-4 bg-slate-100 text-slate-500 font-black rounded-xl uppercase text-[9px]">Cancelar</button>
            <button onClick={handleUpdatePayrollValues} className="flex-1 py-4 bg-blue-600 text-white font-black rounded-xl uppercase text-[9px] shadow-lg active:scale-95 transition-all">Confirmar Cambios</button>
          </div>
        </div>
      </Modal>

      <Modal isOpen={!!individualPayroll} onClose={() => setIndividualPayroll(null)} title="Rol de Pagos Individual">
        {individualPayroll && (() => {
           const d = calculatePayrollData(individualPayroll, 0);
           return (
             <div className="space-y-6 bg-white" id="individual-role-print">
