                    <linearGradient id="logoGradient" x1="0%" y1="0%" x2="100%" y2="100%">
                      <stop offset="0%" style={{stopColor: '#3b82f6'}} />
                      <stop offset="100%" style={{stopColor: '#1e3a8a'}} />
                    </linearGradient>
                  </defs>
                  <circle cx="50" cy="50" r="45" fill="none" stroke="url(#logoGradient)" strokeWidth="6" strokeDasharray="15 5" />
                  <circle cx="50" cy="50" r="32" fill="none" stroke="url(#logoGradient)" strokeWidth="5" strokeDasharray="10 4" opacity="0.7" />
                  <circle cx="50" cy="50" r="18" fill="none" stroke="url(#logoGradient)" strokeWidth="4" opacity="0.4" />
                  <circle cx="50" cy="50" r="6" fill="#3b82f6" />
                </svg>
            </div>
            <div>
              <h2 className="text-lg md:text-xl font-[950] tracking-tighter leading-none uppercase">ASIST UP</h2>
              <p className="text-[7px] md:text-[8px] text-blue-500 font-black tracking-[0.4em] mt-1.5">Enterprise</p>
            </div>
          </div>

          <nav className="space-y-1.5 md:space-y-2">
            {menuItems.filter(item => item.roles.includes(role)).map((item) => (
              <button
                key={item.id}
                onClick={() => { setActiveTab(item.id); setIsOpen(false); }}
                className={`w-full flex items-center justify-between gap-3 px-4 py-3.5 md:px-5 md:py-4 rounded-xl md:rounded-2xl transition-all duration-300 font-black group ${activeTab === item.id ? 'bg-white text-slate-950 shadow-lg' : 'hover:bg-white/10 text-slate-400 hover:text-white'}`}
              >
                <div className="flex items-center gap-3 md:gap-4">
                  <svg className="w-4 h-4 md:w-5 md:h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d={item.icon}></path></svg>
                  <span className="text-[9px] md:text-[10px] uppercase tracking-widest text-left">{item.label}</span>
                </div>
                {item.badge ? (
                  <span className="bg-blue-600 text-white text-[7px] px-1.5 py-0.5 rounded-full shadow-[0_0_8px_#3b82f6]">{item.badge}</span>
                ) : null}
              </button>
            ))}
          </nav>

          {!isStandalone && (role === Role.SUPER_ADMIN || role === Role.PARTIAL_ADMIN) && (
            <div className="mt-6 border-t border-white/10 pt-6">
              <button 
                onClick={handleInstallClick}
                className="w-full flex items-center gap-3 px-5 py-3.5 bg-blue-600/20 text-blue-400 rounded-xl font-black text-[9px] uppercase tracking-widest hover:bg-blue-600 hover:text-white transition-all border border-blue-500/30 active:scale-95"
              >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1m-4-4l-4 4m0 0l-4-4m4 4V4"></path></svg>
                <span>Instalar</span>
              </button>
            </div>
          )}
        </div>

        <div className="p-6 md:p-8 border-t border-white/5">
          <button 
            onClick={onLogout}
            className="w-full py-3.5 md:py-4 bg-red-500/10 text-red-400 hover:bg-red-600 hover:text-white rounded-xl md:rounded-2xl transition-all font-black border border-red-500/30 uppercase text-[9px] md:text-[10px] tracking-widest active:scale-95"
          >
            Cerrar Sesión
          </button>
        </div>
      </aside>

      <Modal isOpen={showModeSelection} onClose={() => setShowModeSelection(false)} title="Instalación" maxWidth="max-w-sm">
         <div className="space-y-4">
            <p className="text-[9px] text-slate-500 font-black text-center uppercase tracking-widest">
              Seleccione modo de acceso
            </p>
            <div className="space-y-2">
               {role === Role.SUPER_ADMIN && (
                 <button onClick={() => handleInstallProcess('full')} className="w-full py-4 bg-blue-700 text-white font-black rounded-xl uppercase text-[9px] tracking-widest shadow-lg active:scale-95">Sistema Completo</button>
               )}
               <button onClick={() => handleInstallProcess('attendance')} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[9px] tracking-widest active:scale-95">Marcación Kiosco</button>
            </div>
         </div>
      </Modal>

      {isOpen && <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md z-30 md:hidden" onClick={() => setIsOpen(false)}></div>}
    </>
  );
};

export default Sidebar;

import React, { useState, useMemo, useEffect } from 'react';
import { Role, CompanyConfig, Employee, AttendanceRecord, Payment, GlobalSettings, NotificationMessage } from '../types.ts';
import Sidebar from '../components/Sidebar.tsx';
import CompanyModule from './modules/CompanyModule.tsx';
import EmployeeModule from './modules/EmployeeModule.tsx';
import PayrollModule from './modules/PayrollModule.tsx';
import PaymentsModule from './modules/PaymentsModule.tsx';
import SettingsModule from './modules/SettingsModule.tsx';
import ReportsModule from './modules/ReportsModule.tsx';
import AiAssistant from './modules/AiAssistant.tsx';
import NotificationsModule from './modules/NotificationsModule.tsx';
import Modal from '../components/Modal.tsx';
import { DAILY_QUOTES, ACTIVE_BREAKS, ECUADOR_HOLIDAYS } from '../constants.tsx';

interface AdminDashboardProps {
  role: Role;
  isDbConnected?: boolean;
  onLogout: () => void;
  company: CompanyConfig | null;
  onUpdateCompany: (config: CompanyConfig) => void;
  employees: Employee[];
  onUpdateEmployees: (employees: Employee[]) => void;
  attendance: AttendanceRecord[];
  payments: Payment[];
  onUpdatePayments: (payments: Payment[]) => void;
  settings: GlobalSettings;
  onUpdateSettings: (settings: GlobalSettings) => void;
  onUpdateAppMode: (mode: 'full' | 'attendance') => void;
  appMode: 'full' | 'attendance';
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  role, isDbConnected, onLogout, company, onUpdateCompany, employees, onUpdateEmployees, attendance, payments, onUpdatePayments, settings, onUpdateSettings, onUpdateAppMode, appMode 
}) => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'company' | 'employees' | 'payroll' | 'payments' | 'settings' | 'reports' | 'ai' | 'notifications'>('dashboard');
  const [showInstallModal, setShowInstallModal] = useState(false);
  const [notifications, setNotifications] = useState<NotificationMessage[]>([]);
  const [dismissedNotificationIds, setDismissedNotificationIds] = useState<Set<string>>(new Set());

  const today = useMemo(() => new Date(), []);
  const todayDateStr = useMemo(() => today.toISOString().split('T')[0], [today]);
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();

  const addNotification = (title: string, message: string, type: 'info' | 'alert' | 'critical') => {
    const contentId = `notif-${title}-${message}`.replace(/\s/g, '-');

    if (dismissedNotificationIds.has(contentId)) return;

    setNotifications(prev => {
      if (prev.some(n => n.id === contentId)) return prev;
      return [{ id: contentId, title, message, timestamp: new Date().toISOString(), type, isRead: false, isProcessed: false }, ...prev];
    });
  };

  useEffect(() => {
    const activeEmployees = employees.filter(e => e.status === 'active');
    const markedTodayIds = new Set((attendance || [])
      .filter(a => a.timestamp.includes(todayDateStr))
      .map(a => a.employeeId));

    const missingAttendanceCount = activeEmployees.filter(e => !markedTodayIds.has(e.id)).length;
    if (missingAttendanceCount > 0 && activeTab === 'dashboard') {
      addNotification(
        "Pendiente de Ingreso", 
        `Hay ${missingAttendanceCount} colaboradores que aún no han registrado su marcación hoy.`, 
        'alert'
      );
    }
  }, [employees, attendance, todayDateStr, activeTab, dismissedNotificationIds]);

  const unreadCount = notifications.filter(n => !n.isRead).length;

  const dayOfYear = useMemo(() => {
    const start = new Date(today.getFullYear(), 0, 0);
    const diff = today.getTime() - start.getTime();
    return Math.floor(diff / (1000 * 60 * 60 * 24));
  }, [today]);

  const dailyQuote = DAILY_QUOTES[dayOfYear % DAILY_QUOTES.length];
  const activeBreak = ACTIVE_BREAKS[dayOfYear % ACTIVE_BREAKS.length];

  const relaxingImages = [
    "https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&q=80&w=2070",
    "https://images.unsplash.com/photo-1441974231531-c6227db76b6e?auto=format&fit=crop&q=80&w=2071",
    "https://images.unsplash.com/photo-1579783902614-a3fb3927b6a5?auto=format&fit=crop&q=80&w=2070",
    "https://images.unsplash.com/photo-1541450805268-4822a3a774ce?auto=format&fit=crop&q=80&w=2070"
  ];
  const currentRelaxingImage = relaxingImages[dayOfYear % relaxingImages.length];

  const calendarDays = useMemo(() => {
    const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
    const firstDay = new Date(currentYear, currentMonth, 1).getDay();
    const days = [];
    for (let i = 0; i < firstDay; i++) days.push(null);
    for (let i = 1; i <= daysInMonth; i++) days.push(i);
    return days;
  }, [currentMonth, currentYear]);

  const monthHolidays = ECUADOR_HOLIDAYS.filter(h => h.month === currentMonth);
  const monthBirthdays = employees.filter(e => {
    if (!e.birthDate || e.status !== 'active') return false;
    return new Date(e.birthDate).getMonth() === currentMonth;
  });

  const handleDismissNotification = (id: string) => {
    setDismissedNotificationIds(prev => new Set([...prev, id]));
    setNotifications(prev => prev.filter(n => n.id !== id));
  };

  const handlePurgeData = async () => {
    if (role !== Role.SUPER_ADMIN) return;
    onUpdateEmployees([]);
    onUpdatePayments([]);
  };

  return (
    <div className="flex h-screen bg-[#fcfdfe] overflow-hidden flex-col md:flex-row">
      <Sidebar 
        role={role} 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        onLogout={onLogout} 
        companyName={company?.name} 
        unreadCount={unreadCount}
      />

      <main className="flex-1 overflow-y-auto px-4 md:px-8 py-6 md:py-8 scroll-smooth custom-scroll">
        <header className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4 no-print pt-14 md:pt-0">
          <div className="flex flex-col sm:flex-row items-start sm:items-center gap-3 w-full md:w-auto">
            <h1 className="text-lg md:text-xl font-[950] text-slate-900 tracking-tight uppercase leading-none">Management Hub</h1>
            <div className="flex items-center gap-2 px-3 py-1 bg-white border rounded-lg shadow-sm w-fit">
               <div className={`w-1.5 h-1.5 rounded-full ${isDbConnected ? 'bg-emerald-500 shadow-[0_0_5px_emerald]' : 'bg-red-500 shadow-[0_0_5px_red]'}`}></div>
               <span className="text-[7px] font-black uppercase tracking-widest text-slate-500">{isDbConnected ? 'Live' : 'Offline'}</span>
            </div>
          </div>
        </header>

        <div className="animate-in fade-in duration-500 pb-20 md:pb-0">
          {activeTab === 'dashboard' && (
            <div className="grid grid-cols-1 md:grid-cols-12 gap-5 md:gap-6">

              <div className="md:col-span-12 relative overflow-hidden bg-slate-900 rounded-[2.5rem] p-6 md:p-8 text-white shadow-xl min-h-[140px] flex items-center bg-cover bg-center" style={{ backgroundImage: `linear-gradient(rgba(15, 23, 42, 0.7), rgba(15, 23, 42, 0.7)), url(${currentRelaxingImage})` }}>
                  <div className="relative z-10 w-full text-center md:text-left">
                    <p className="text-blue-400 font-black text-[8px] uppercase tracking-[0.4em] mb-3">Daily Inspiration</p>
                    <h2 className="text-lg md:text-2xl font-[800] leading-tight tracking-tight italic">"{dailyQuote}"</h2>
                  </div>
              </div>

              <div className="md:col-span-12 lg:col-span-7 bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm">
                 <div className="flex justify-between items-center mb-6">
                    <h3 className="text-[10px] font-black text-slate-900 uppercase tracking-widest leading-none">Calendario Mensual</h3>
                    <div className="flex gap-4">
                       <span className="flex items-center gap-1.5 text-[7px] font-black text-blue-600 uppercase"><div className="w-1.5 h-1.5 bg-blue-500 rounded-full"></div> Festivo</span>
                       <span className="flex items-center gap-1.5 text-[7px] font-black text-emerald-600 uppercase"><div className="w-1.5 h-1.5 bg-emerald-500 rounded-full"></div> Natalicio</span>
                    </div>
                 </div>
                 <div className="grid grid-cols-7 gap-2 text-center max-w-[420px] mx-auto">
                    {['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'].map(d => (
                      <div key={d} className="text-[8px] font-black text-slate-300 uppercase py-1">{d}</div>
                    ))}
                    {calendarDays.map((day, i) => {
                      const isHoliday = day && monthHolidays.some(h => h.day === day);
                      const isBirthday = day && monthBirthdays.some(e => new Date(e.birthDate).getDate() === day);
                      const isToday = day === today.getDate();

                      return (
                        <div key={i} className={`
                          relative aspect-square flex items-center justify-center text-[10px] font-bold rounded-xl transition-all
                          ${!day ? 'opacity-0' : 'hover:bg-slate-50 cursor-default'}
                          ${isToday ? 'bg-slate-900 text-white shadow-lg ring-4 ring-slate-100' : 'text-slate-600'}
                          ${isHoliday ? 'border border-blue-500/40 text-blue-600 bg-blue-50' : ''}
                          ${isBirthday ? 'border border-emerald-500/40 text-emerald-600 bg-emerald-50' : ''}
                        `}>
                          {day}
                        </div>
                      );
                    })}
                 </div>
              </div>

              <div className="md:col-span-12 lg:col-span-5 bg-slate-50 p-6 rounded-[2.5rem] border border-slate-100 space-y-4">
                 <h3 className="text-[9px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-200 pb-3">Agenda de Eventos</h3>
                 <div className="space-y-3 max-h-[300px] overflow-y-auto custom-scroll pr-2">
                    {monthHolidays.map((h, i) => (
                       <div key={i} className="flex gap-4 items-center bg-white p-3.5 rounded-2xl border border-slate-200/60 shadow-sm hover:translate-x-1 transition-transform">
                          <span className="text-xl">📅</span>
                          <div>
                             <p className="text-[9px] font-black text-slate-900 uppercase leading-none">{h.name}</p>
                             <p className="text-[7px] font-bold text-blue-500 uppercase mt-1.5">Día {h.day} del mes</p>
                          </div>
                       </div>
                    ))}
                    {monthBirthdays.map((e, i) => (
                       <div key={i} className="flex gap-4 items-center bg-white p-3.5 rounded-2xl border border-slate-200/60 shadow-sm hover:translate-x-1 transition-transform">
                          <div className="w-8 h-8 rounded-xl overflow-hidden border bg-slate-100 flex items-center justify-center text-[9px] font-black uppercase text-slate-300">
                             {e.photo ? <img src={e.photo} className="w-full h-full object-cover" /> : <span>{e.name[0]}</span>}
                          </div>
                          <div>
                             <p className="text-[9px] font-black text-slate-900 uppercase leading-none">{e.surname} {e.name}</p>
                             <p className="text-[7px] font-bold text-emerald-500 uppercase mt-1.5">Día {new Date(e.birthDate).getDate()} - Cumpleaños</p>
                          </div>
                       </div>
                    ))}
                    {monthHolidays.length === 0 && monthBirthdays.length === 0 && (
                      <div className="py-20 text-center space-y-3">
                        <span className="text-3xl opacity-20">📭</span>
                        <p className="text-[8px] text-slate-300 font-black uppercase tracking-widest">Sin eventos próximos</p>
                      </div>
                    )}
                 </div>
              </div>

              <div className="md:col-span-12 grid grid-cols-1 md:grid-cols-2 gap-6 items-stretch">
                <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 flex flex-col justify-center shadow-sm">
                  <div className="flex items-center gap-6 mb-6">
                    <span className="text-4xl p-4 bg-blue-50 rounded-[1.5rem] shadow-inner">{activeBreak.icon}</span>
                    <div>
                      <h3 className="text-xs font-black text-slate-900 uppercase leading-none tracking-wider">Health & Wellness</h3>
                      <p className="text-[8px] font-black text-blue-600 uppercase tracking-[0.3em] mt-2">Active Pause Recommendation</p>
                    </div>
                  </div>
                  <div className="space-y-3 bg-slate-50 p-6 rounded-[2rem] border border-slate-100">
                    <h4 className="text-[11px] font-[900] text-slate-800 uppercase tracking-tight">{activeBreak.title}</h4>
                    <p className="text-slate-500 text-[10px] md:text-xs leading-relaxed font-medium">{activeBreak.description}</p>
                  </div>
                </div>

                <div className="relative overflow-hidden bg-slate-200 rounded-[2.5rem] shadow-lg border border-slate-100 min-h-[220px]">
                   <img 
                     src={currentRelaxingImage} 
                     alt="Relajación" 
                     className="w-full h-full object-cover transition-transform duration-10000 hover:scale-110"
                   />
                   <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent flex items-end p-8">
                      <div>
                        <p className="text-[8px] font-black text-white/60 uppercase tracking-[0.6em] mb-2">Workspace Vibe</p>
                        <p className="text-white text-xs font-bold uppercase tracking-widest">Ambiente para la concentración estratégica</p>
                      </div>
                   </div>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'notifications' && (
            <NotificationsModule 
              notifications={notifications} 
              onToggleRead={handleDismissNotification}
              onToggleProcessed={handleDismissNotification}
              onClearAll={() => {
                const allIds = notifications.map(n => n.id);
                setDismissedNotificationIds(prev => new Set([...prev, ...allIds]));
                setNotifications([]);
              }}
            />
          )}

          {activeTab === 'company' && <CompanyModule company={company} onUpdate={onUpdateCompany} role={role} />}
          {activeTab === 'employees' && <EmployeeModule employees={employees} onUpdate={onUpdateEmployees} role={role} attendance={attendance} payments={payments} company={company} />}
          {activeTab === 'payroll' && <PayrollModule employees={employees} payments={payments} onUpdatePayments={onUpdatePayments} onUpdateEmployees={onUpdateEmployees} attendance={attendance} company={company} settings={settings} role={role} />}
          {activeTab === 'payments' && <PaymentsModule employees={employees} payments={payments} onUpdate={onUpdatePayments} role={role} company={company} />}
          {activeTab === 'settings' && <SettingsModule settings={settings} onUpdate={onUpdateSettings} role={role} onPurge={handlePurgeData} allData={{ company, employees, attendance, payments, settings }} />}
          {activeTab === 'reports' && <ReportsModule employees={employees} payments={payments} attendance={attendance} company={company} settings={settings} role={role} />}
          {activeTab === 'ai' && <AiAssistant employees={employees} attendance={attendance} payments={payments} role={role} />}
        </div>
      </main>

      <Modal isOpen={showInstallModal} onClose={() => setShowInstallModal(false)} title="Estación de Trabajo" maxWidth="max-w-md">
         <div className="space-y-4">
            <p className="text-[10px] text-slate-500 text-center font-bold uppercase tracking-widest leading-none">Seleccione modo de funcionamiento</p>
            <div className="grid grid-cols-1 gap-3">
               <button onClick={() => { onUpdateAppMode('full'); setShowInstallModal(false); }} className={`p-5 rounded-2xl border-2 text-left transition-all ${appMode === 'full' ? 'border-blue-600 bg-blue-50' : 'border-slate-100'}`}>
                  <p className="font-black text-xs text-slate-900 uppercase">Administrativo Full</p>
                  <p className="text-[9px] text-slate-400 font-bold uppercase mt-1">Gestión completa del sistema.</p>
               </button>
               <button onClick={() => { onUpdateAppMode('attendance'); setShowInstallModal(false); }} className={`p-5 rounded-2xl border-2 text-left transition-all ${appMode === 'attendance' ? 'border-blue-600 bg-blue-50' : 'border-slate-100'}`}>
                  <p className="font-black text-xs text-slate-900 uppercase">Kiosco de Asistencia</p>
                  <p className="text-[9px] text-slate-400 font-bold uppercase mt-1">Solo marcación para personal.</p>
               </button>
            </div>
         </div>
      </Modal>
    </div>
  );
};

