                     <span className={`px-3 py-1 rounded-full text-[9px] font-black uppercase ${viewingEmp.status === 'active' ? 'bg-emerald-50 text-emerald-600 border border-emerald-100' : 'bg-red-50 text-red-600 border border-red-100'}`}>{viewingEmp.status === 'active' ? 'Activo' : 'Desvinculado'}</span>
                     <span className="px-3 py-1 bg-slate-100 text-slate-500 text-[9px] font-black uppercase rounded-full border">Ingreso: {new Date(viewingEmp.startDate).toLocaleDateString()}</span>
                     {viewingEmp.pinResetRequested && <span className="px-3 py-1 bg-yellow-400 text-yellow-900 text-[9px] font-black uppercase rounded-full animate-pulse shadow-sm">Reset PIN Pendiente</span>}
                  </div>
               </div>
            </div>

            <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-3 no-print">
               <button onClick={() => { setForm(viewingEmp); setEditingEmp(viewingEmp); setIsModalOpen(true); }} className="p-4 bg-blue-50 text-blue-700 rounded-2xl flex flex-col items-center gap-2 hover:bg-blue-600 hover:text-white transition-all border border-blue-100 shadow-sm active:scale-95 group">
                  <span className="text-2xl group-hover:scale-110 transition-transform">📝</span>
                  <span className="text-[8px] font-black uppercase">Editar Datos</span>
               </button>
               <button onClick={() => setIsAbsenceModalOpen(true)} className="p-4 bg-slate-50 text-slate-700 rounded-2xl flex flex-col items-center gap-2 hover:bg-slate-900 hover:text-white transition-all border border-slate-100 shadow-sm active:scale-95 group">
                  <span className="text-2xl group-hover:scale-110 transition-transform">📌</span>
                  <span className="text-[8px] font-black uppercase">Nueva Novedad</span>
               </button>
               {viewingEmp.status === 'active' && (
                  <button onClick={() => setIsResetConfirmModalOpen(true)} className="p-4 bg-yellow-50 text-yellow-700 rounded-2xl flex flex-col items-center gap-2 border border-yellow-200 shadow-sm hover:bg-yellow-500 hover:text-white transition-all active:scale-95 group">
                    <span className="text-2xl group-hover:scale-110 transition-transform">🔑</span>
                    <span className="text-[8px] font-black uppercase">{viewingEmp.pinResetRequested ? 'Aprobar PIN' : 'Resetear PIN'}</span>
                  </button>
               )}
               {viewingEmp.status === 'active' && (
                  <button onClick={() => setIsTermModalOpen(true)} className="p-4 bg-red-50 text-red-700 rounded-2xl flex flex-col items-center gap-2 border border-red-100 shadow-sm hover:bg-red-600 hover:text-white transition-all active:scale-95 group">
                    <span className="text-2xl group-hover:scale-110 transition-transform">🚪</span>
                    <span className="text-[8px] font-black uppercase">Dar de Baja</span>
                  </button>
               )}
               {role === Role.SUPER_ADMIN && (
                 <button onClick={() => setIsDeleteConfirmModalOpen(true)} className="p-4 bg-red-700 text-white rounded-2xl flex flex-col items-center gap-2 shadow-lg active:scale-95 group">
                    <span className="text-2xl group-hover:scale-110 transition-transform">🗑️</span>
                    <span className="text-[8px] font-black uppercase">Eliminar Def.</span>
                 </button>
               )}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pt-4">
              <div className="space-y-4">
                <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest border-b pb-1">Perfil Financiero</h4>
                <div className="grid grid-cols-2 gap-3">
                  <div className="p-3 bg-slate-50 rounded-xl border border-slate-100">
                    <p className="text-[8px] font-black text-slate-400 uppercase">Sueldo Base</p>
                    <p className="text-lg font-black text-slate-900">${viewingEmp.salary.toFixed(2)}</p>
                  </div>
                  <div className="p-3 bg-slate-50 rounded-xl border border-slate-100">
                    <p className="text-[8px] font-black text-slate-400 uppercase">Seguro IESS</p>
                    <p className="text-[10px] font-black text-blue-600 uppercase">{viewingEmp.isAffiliated ? 'Afiliado' : 'No Afiliado'}</p>
                  </div>
                  <div className="p-3 bg-slate-50 rounded-xl border border-slate-100 col-span-2">
                    <p className="text-[8px] font-black text-slate-400 uppercase">Información Bancaria</p>
                    <p className="text-[10px] font-black text-slate-700 uppercase">{viewingEmp.bankInfo?.ifi} | {viewingEmp.bankInfo?.type} | {viewingEmp.bankInfo?.account}</p>
                  </div>
                </div>
              </div>
              <div className="space-y-4">
                <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest border-b pb-1">Historial de Novedades (Últimas 5)</h4>
                <div className="space-y-2 max-h-48 overflow-y-auto custom-scroll pr-2">
                    {viewingEmp.absences?.length ? [...viewingEmp.absences].reverse().slice(0, 5).map(abs => (
                       <div key={abs.id} className="p-3 bg-white rounded-xl border border-slate-100 flex justify-between items-center shadow-sm">
                          <div>
                             <p className="text-[9px] font-black text-slate-900 uppercase">{abs.type} - {new Date(abs.date).toLocaleDateString()}</p>
                             <p className="text-[8px] font-bold text-slate-500 italic max-w-[150px] truncate">"{abs.reason}"</p>
                          </div>
                          {abs.justified && <span className="text-[8px] font-black text-emerald-600 bg-emerald-50 px-2 py-0.5 rounded-lg border border-emerald-100">VALIDADO</span>}
                       </div>
                    )) : <p className="text-center py-10 text-[9px] text-slate-300 font-black uppercase">Sin registros</p>}
                </div>
              </div>
            </div>
          </div>
        )}
      </Modal>

      {/* MODAL PARA NOVEDADES */}
      <Modal isOpen={isAbsenceModalOpen} onClose={() => setIsAbsenceModalOpen(false)} title="Registrar Novedad" maxWidth="max-w-sm">
         <div className="space-y-4">
            <div className="space-y-1">
              <label className="text-[9px] font-black text-slate-400 uppercase">Tipo de Registro</label>
              <select className="w-full border-2 p-3 rounded-xl text-[11px] font-bold uppercase" value={newAbsence.type} onChange={e => setNewAbsence({...newAbsence, type: e.target.value as any})}><option value="Falta">Falta Injustificada</option><option value="Permiso">Permiso Autorizado</option><option value="Atraso">Atraso Crítico</option></select>
            </div>
            <div className="space-y-1">
              <label className="text-[9px] font-black text-slate-400 uppercase">Fecha del Evento</label>
              <input type="date" className="w-full border-2 p-3 rounded-xl text-[11px] font-bold" value={newAbsence.date} onChange={e => setNewAbsence({...newAbsence, date: e.target.value})} />
            </div>
            <div className="space-y-1">
              <label className="text-[9px] font-black text-slate-400 uppercase">Justificación / Motivo</label>
              <textarea className="w-full border-2 p-3 rounded-xl text-[11px] font-bold h-24 uppercase" placeholder="Describa la novedad..." value={newAbsence.reason} onChange={e => setNewAbsence({...newAbsence, reason: e.target.value.toUpperCase()})} />
            </div>
            <div className="flex items-center gap-3 py-2 bg-slate-50 p-4 rounded-xl">
               <input type="checkbox" id="just-check" className="w-5 h-5 accent-emerald-600" checked={newAbsence.justified} onChange={e => setNewAbsence({...newAbsence, justified: e.target.checked})} />
               <label htmlFor="just-check" className="text-[10px] font-black uppercase text-slate-600">Considerar como Justificado</label>
            </div>
            <button onClick={handleAddAbsence} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] shadow-lg active:scale-95 transition-all">Guardar Novedad en Expediente</button>
         </div>
      </Modal>

      {/* MODAL CONFIRMACIÓN RESETEO PIN */}
      <Modal isOpen={isResetConfirmModalOpen} onClose={() => setIsResetConfirmModalOpen(false)} title="Seguridad de Acceso" type="warning" maxWidth="max-w-sm">
        <div className="space-y-6 text-center">
          <div className="w-16 h-16 bg-yellow-100 text-yellow-600 rounded-full flex items-center justify-center text-3xl mx-auto">🔑</div>
          <p className="text-xs font-black text-yellow-600 uppercase italic">Confirmar Reseteo de PIN</p>
          <p className="text-[11px] text-slate-500 font-medium leading-relaxed">¿Confirma que desea restablecer el PIN de este colaborador? Se generará un nuevo PIN provisional aleatorio y el sistema obligará al cambio en la próxima marcación.</p>
          <div className="flex gap-3">
            <button onClick={() => setIsResetConfirmModalOpen(false)} className="flex-1 py-4 bg-slate-100 text-slate-600 font-black rounded-xl uppercase text-[9px]">Cancelar</button>
            <button onClick={() => viewingEmp && handleApprovePinReset(viewingEmp)} className="flex-1 py-4 bg-yellow-600 text-white font-black rounded-xl uppercase text-[9px] shadow-lg active:scale-95 transition-all">Confirmar Reseteo</button>
          </div>
        </div>
      </Modal>

      {/* MODAL PARA BAJA */}
      <Modal isOpen={isTermModalOpen} onClose={() => setIsTermModalOpen(false)} title="Salida de Personal / Desvinculación" maxWidth="max-w-sm">
         <div className="space-y-4">
            <div className="space-y-1">
              <label className="text-[9px] font-black text-slate-400 uppercase">Motivo Legal de Salida</label>
              <select className="w-full border-2 p-3 rounded-xl text-[11px] font-bold uppercase" value={termData.reason} onChange={e => setTermData({...termData, reason: e.target.value as TerminationReason})}>{Object.values(TerminationReason).map(r => <option key={r} value={r}>{r}</option>)}</select>
            </div>
            <div className="space-y-1">
              <label className="text-[9px] font-black text-slate-400 uppercase">Fecha de Cese de Funciones</label>
              <input type="date" className="w-full border-2 p-3 rounded-xl text-[11px] font-bold" value={termData.date} onChange={e => setTermData({...termData, date: e.target.value})} />
            </div>
            <div className="space-y-1">
              <label className="text-[9px] font-black text-slate-400 uppercase">Observaciones Finales</label>
              <textarea className="w-full border-2 p-3 rounded-xl text-[11px] font-bold h-24 uppercase" placeholder="Detalles de la liquidación o motivo..." value={termData.details} onChange={e => setTermData({...termData, details: e.target.value.toUpperCase()})} />
            </div>
            <div className="bg-red-50 p-4 rounded-xl border border-red-100 text-center">
               <p className="text-[10px] font-black text-red-600 uppercase">Advertencia</p>
               <p className="text-[8px] font-bold text-red-400 uppercase mt-1">El colaborador pasará al historial de bajas y no podrá marcar asistencia.</p>
            </div>
            <button onClick={handleTerminate} className="w-full py-4 bg-red-600 text-white font-black rounded-xl uppercase text-[10px] shadow-lg active:scale-95 transition-all">Ejecutar Baja Definitiva</button>
         </div>
      </Modal>

      {/* MODAL PARA ELIMINACIÓN PERMANENTE */}
      <Modal isOpen={isDeleteConfirmModalOpen} onClose={() => setIsDeleteConfirmModalOpen(false)} title="ELIMINACIÓN DE REGISTRO MAESTRO" type="error" maxWidth="max-w-sm">
        <div className="space-y-6 text-center">
          <div className="w-16 h-16 bg-red-100 text-red-600 rounded-full flex items-center justify-center text-3xl mx-auto animate-pulse">🗑️</div>
          <p className="text-xs font-black text-red-600 uppercase italic">Acción Crítica e Irreversible</p>
          <p className="text-[11px] text-slate-500 font-medium leading-relaxed">¿Desea borrar permanentemente este expediente? Se perderán todos los históricos bancarios, novedades y registros personales asociados.</p>
          <div className="flex gap-3">
            <button onClick={() => setIsDeleteConfirmModalOpen(false)} className="flex-1 py-4 bg-slate-100 text-slate-600 font-black rounded-xl uppercase text-[9px]">Cancelar</button>
            <button onClick={handleDeletePermanent} className="flex-1 py-4 bg-red-600 text-white font-black rounded-xl uppercase text-[9px] shadow-lg active:scale-95 transition-all">Confirmar Borrado</button>
          </div>
        </div>
      </Modal>

      <Modal isOpen={feedback.isOpen} onClose={() => setFeedback({...feedback, isOpen: false})} title={feedback.title} type={feedback.type}>
        <div className="text-center p-4">
          <p className="text-[11px] font-bold uppercase leading-relaxed text-slate-600">{feedback.message}</p>
          <button onClick={() => setFeedback({...feedback, isOpen: false})} className="w-full py-3.5 bg-slate-900 text-white font-black rounded-xl uppercase text-[9px] mt-6 active:scale-95 transition-all">Aceptar</button>
        </div>
      </Modal>
    </div>
  );
};

export default EmployeeModule;

import React, { useState } from 'react';
import { Employee, Payment, AttendanceRecord, CompanyConfig, GlobalSettings, Role } from '../../types.ts';
import { db, doc, setDoc, deleteDoc, compressData } from '../../firebase.ts';
import Modal from '../../components/Modal.tsx';

interface ReportsModuleProps {
  employees: Employee[];
  payments: Payment[];
  attendance: AttendanceRecord[];
  company: CompanyConfig | null;
  settings: GlobalSettings;
  role: Role;
}

const ReportsModule: React.FC<ReportsModuleProps> = ({ employees, payments = [], attendance = [], company, settings, role }) => {
  const [reportType, setReportType] = useState<'attendance' | 'payments' | 'validation' | 'history'>('attendance');
  const [searchTerm, setSearchTerm] = useState('');
  const [feedback, setFeedback] = useState({ isOpen: false, title: '', message: '', type: 'success' as any });
  const [deleteConfirm, setDeleteConfirm] = useState<{isOpen: boolean, id: string | null}>({ isOpen: false, id: null });
  const [editingAttendance, setEditingAttendance] = useState<AttendanceRecord | null>(null);
  const [showConfirmEdit, setShowConfirmEdit] = useState(false);

  const pendingAttendance = (attendance || []).filter(a => a.status === 'pending_approval');

  const handleValidate = async (record: AttendanceRecord, newStatus: 'confirmed' | 'rejected') => {
    const updatedRecord = { 
      ...record, 
      status: newStatus,
      validatedAt: new Date().toISOString()
    };

    await setDoc(doc(db, "attendance", record.id), { payload: compressData(updatedRecord), timestamp: record.timestamp });
    setFeedback({ isOpen: true, title: "Actualización Exitosa", message: `La marcación ha sido validada como: ${newStatus.toUpperCase()}`, type: 'success' });
  };

  const confirmDeleteAttendance = async () => {
    if (!deleteConfirm.id) return;
    try {
      await deleteDoc(doc(db, "attendance", deleteConfirm.id));
      setDeleteConfirm({ isOpen: false, id: null });
      setFeedback({ isOpen: true, title: "Registro Eliminado", message: "La marcación ha sido borrada del sistema definitivamente.", type: 'success' });
    } catch (e) {
      setDeleteConfirm({ isOpen: false, id: null });
      setFeedback({ isOpen: true, title: "Error Crítico", message: "No se pudo eliminar el registro en la base de datos.", type: 'error' });
    }
  };

  const handleUpdateAttendance = async () => {
    if (!editingAttendance) return;
    try {
      await setDoc(doc(db, "attendance", editingAttendance.id), { 
        payload: compressData(editingAttendance), 
        timestamp: editingAttendance.timestamp 
      });
      setEditingAttendance(null);
      setShowConfirmEdit(false);
      setFeedback({ isOpen: true, title: "Cambios Guardados", message: "La marcación ha sido actualizada correctamente.", type: 'success' });
    } catch (e) {
      setFeedback({ isOpen: true, title: "Error", message: "No se pudieron guardar los cambios.", type: 'error' });
    }
  };

  const filteredPending = pendingAttendance.filter(req => {
    const emp = employees.find(e => e.id === req.employeeId);
    const searchStr = `${emp?.name} ${emp?.surname} ${emp?.identification} ${req.justification || ""}`.toLowerCase();
    return searchStr.includes(searchTerm.toLowerCase());
  });

  const exportExcel = () => {
    let csv = "";
    if (reportType === 'payments') {
        csv = "\uFEFFCódigo,Fecha,Beneficiario,Identificación,Concepto,Detalle,Método,Monto\n";
        paymentsToDisplay.forEach(p => {
          const emp = employees.find(e => e.id === p.employeeId);
          csv += `"${p.voucherCode}","${new Date(p.date).toLocaleDateString()}","${emp?.surname} ${emp?.name}","${emp?.identification}","${p.type}","${p.concept}","${p.method}","${p.amount.toFixed(2)}"\n`;
        });
    } else if (reportType === 'history') {
        csv = "\uFEFFColaborador,Identificación,Cargo,F. Ingreso,F. Salida,Motivo,Novedades,Estado\n";
        historyToDisplay.forEach(emp => {
          csv += `"${emp.surname} ${emp.name}","${emp.identification}","${emp.role}","${emp.startDate}","${emp.terminationDate || 'N/A'}","${emp.terminationReason || 'N/A'}","${emp.absences?.length || 0}","${emp.status}"\n`;
        });
    } else {
        csv = "\uFEFFFecha,Hora,Colaborador,Identificación,Cargo,Tipo Marcación,Estado,Atraso,Justificación\n";
        attendanceToDisplay.forEach(rec => {
          const emp = employees.find(e => e.id === rec.employeeId);
          const date = new Date(rec.timestamp);
          csv += `"${date.toLocaleDateString()}","${date.toLocaleTimeString()}","${emp?.surname} ${emp?.name}","${emp?.identification}","${emp?.role}","${rec.type === 'in' ? 'Entrada' : 'Salida'}","${rec.status}","${rec.isLate ? 'SI' : 'NO'}","${rec.justification || ''}"\n`;
        });
    }
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `REPORTE_${reportType.toUpperCase()}_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  };

  const attendanceToDisplay = (attendance || []).filter(a => {
    const emp = employees.find(e => e.id === a.employeeId);
    const searchStr = `${emp?.surname} ${emp?.name} ${emp?.identification} ${a.justification || ""} ${a.status} ${a.type}`.toLowerCase();
    return searchStr.includes(searchTerm.toLowerCase());
  }).sort((a,b) => b.timestamp.localeCompare(a.timestamp));

  const paymentsToDisplay = (payments || []).filter(p => {
    const emp = employees.find(e => e.id === p.employeeId);
    const searchStr = `${emp?.surname} ${emp?.name} ${emp?.identification} ${p.concept} ${p.type} ${p.voucherCode} ${p.method}`.toLowerCase();
    return searchStr.includes(searchTerm.toLowerCase());
  }).sort((a,b) => b.date.localeCompare(a.date));

  const historyToDisplay = employees.filter(e => {
    const searchStr = `${e.name} ${e.surname} ${e.identification} ${e.role} ${e.status}`.toLowerCase();
    return searchStr.includes(searchTerm.toLowerCase());
  }).sort((a,b) => b.startDate.localeCompare(a.startDate));

  return (
    <div className="space-y-6 md:space-y-8 fade-in">
      <div className="flex flex-col md:flex-row justify-between items-center bg-white p-6 md:p-8 rounded-3xl md:rounded-[2rem] shadow-sm border border-slate-100 gap-6 no-print">
        <div className="w-full">
          <h2 className="text-xl md:text-2xl font-[950] text-slate-900 uppercase tracking-tighter">Reportes Institucionales</h2>
          <div className="flex flex-col sm:flex-row gap-4 mt-4">
            <div className="flex gap-2 overflow-x-auto pb-2 sm:pb-0 scroll-smooth no-scrollbar">
              <button onClick={() => {setReportType('attendance'); setSearchTerm('');}} className={`whitespace-nowrap px-4 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${reportType === 'attendance' ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-100 text-slate-400 hover:bg-slate-200'}`}>Registros de Asistencia</button>
              <button onClick={() => {setReportType('payments'); setSearchTerm('');}} className={`whitespace-nowrap px-4 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${reportType === 'payments' ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-100 text-slate-400 hover:bg-slate-200'}`}>Reporte de Egresos</button>
              <button onClick={() => {setReportType('history'); setSearchTerm('');}} className={`whitespace-nowrap px-4 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${reportType === 'history' ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-100 text-slate-400 hover:bg-slate-200'}`}>Historial Laboral</button>
              <button onClick={() => {setReportType('validation'); setSearchTerm('');}} className={`whitespace-nowrap px-4 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest relative transition-all ${reportType === 'validation' ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-100 text-slate-400 hover:bg-slate-200'}`}>
                Validaciones
                {pendingAttendance.length > 0 && <span className="absolute -top-1 -right-1 w-4 h-4 bg-red-500 text-white text-[8px] rounded-full flex items-center justify-center font-black animate-pulse shadow-md">{pendingAttendance.length}</span>}
              </button>
            </div>
            <input 
              type="text" 
              placeholder="Filtrar registros..." 
              className="flex-1 p-2.5 border rounded-xl text-[10px] font-bold uppercase outline-none focus:border-blue-500 shadow-sm" 
              value={searchTerm} 
              onChange={e => setSearchTerm(e.target.value)}
            />
          </div>
        </div>
        <div className="flex gap-2 w-full md:w-auto">
          <button onClick={exportExcel} className="flex-1 md:flex-none px-6 py-4 bg-emerald-600 text-white font-black rounded-xl shadow-lg uppercase text-[9px] active:scale-95 transition-all">Excel Completo</button>
          <button onClick={() => window.print()} className="flex-1 md:flex-none px-6 py-4 bg-slate-900 text-white font-black rounded-xl shadow-lg uppercase text-[9px] active:scale-95 transition-all">Imprimir PDF</button>
        </div>
      </div>

      <div className="bg-white rounded-3xl md:rounded-[2rem] shadow-sm border overflow-hidden min-h-[450px]" id="reports-printable-area">
         <div className="hidden print:block text-center border-b-2 border-slate-900 pb-6 mb-8 px-10 pt-10">
           <h1 className="text-2xl font-[950] text-slate-900 uppercase italic leading-none">{company?.name || 'ASIST UP - HR ENTERPRISE'}</h1>
           <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mt-2">Reporte de {reportType === 'attendance' ? 'Asistencia Diaria' : reportType === 'payments' ? 'Egresos y Pagos Detallados' : reportType === 'history' ? 'Historial Laboral del Personal' : 'Validaciones Pendientes'} - 2026</p>
           <div className="grid grid-cols-2 gap-4 mt-3 max-w-xl mx-auto text-[9px] font-bold uppercase text-slate-600">
             <p className="text-left border-l-4 border-slate-900 pl-3">RUC: {company?.ruc || '0000000000001'}</p>
             <p className="text-right border-r-4 border-slate-900 pr-3">Representante: {company?.legalRep || 'ADMINISTRACIÓN'}</p>
           </div>
           <p className="text-[7px] text-slate-400 mt-2 uppercase font-bold italic text-right">Generado: {new Date().toLocaleString()}</p>
         </div>

         <div className="p-6 md:p-10">
            {reportType === 'validation' ? (
              <div className="space-y-6">
                <h3 className="text-lg font-[950] text-slate-900 uppercase tracking-tighter border-b pb-4 no-print">Validaciones Pendientes por Revisar</h3>
                {filteredPending.length === 0 ? (
                  <div className="py-24 text-center bg-slate-50 rounded-3xl border-2 border-dashed border-slate-200">
                    <span className="text-5xl opacity-20">✅</span>
                    <p className="text-slate-400 font-black uppercase text-[10px] tracking-widest mt-6">No existen justificaciones pendientes</p>
                  </div>
                ) : (
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    {filteredPending.map(req => {
                      const emp = employees.find(e => e.id === req.employeeId);
                      return (
                        <div key={req.id} className="bg-white border rounded-3xl p-6 flex flex-col gap-5 hover:border-blue-500 transition-all shadow-sm">
                          <div className="flex justify-between items-start">
                            <div>
                              <p className="font-[950] text-slate-900 uppercase text-sm tracking-tight">{emp?.surname} {emp?.name}</p>
                              <p className="text-slate-400 font-black text-[8px] uppercase mt-1">CI: {emp?.identification} | {new Date(req.timestamp).toLocaleString()}</p>
                            </div>
                            <span className={`px-2 py-1 text-[8px] font-black rounded-lg uppercase ${req.type === 'in' ? 'bg-blue-50 text-blue-700' : 'bg-slate-100 text-slate-700'}`}>{req.type === 'in' ? 'Ingreso' : 'Salida'}</span>
                          </div>
                          <div className="space-y-2">
                             <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest">Justificación del Colaborador</p>
                             <p className="text-[11px] text-slate-600 font-bold bg-slate-50 p-4 rounded-2xl border leading-relaxed shadow-inner italic">"{req.justification}"</p>
                          </div>
                          <div className="grid grid-cols-2 gap-3 pt-2 no-print">
                             <button onClick={() => handleValidate(req, 'rejected')} className="py-3 bg-red-50 text-red-600 font-black text-[9px] uppercase rounded-xl hover:bg-red-100 transition-all active:scale-95">Rechazar</button>
                             <button onClick={() => handleValidate(req, 'confirmed')} className="py-3 bg-emerald-600 text-white font-black text-[9px] uppercase rounded-xl shadow-lg hover:bg-emerald-700 transition-all active:scale-95">Validar</button>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                )}
              </div>
            ) : reportType === 'payments' ? (
                <div className="table-responsive">
                    <table className="w-full text-left min-w-[900px] print:min-w-0 print:table-auto">
                        <thead className="bg-slate-50 text-[9px] font-black uppercase text-slate-400 border-b tracking-widest print:bg-slate-900 print:text-white">
                            <tr>
                                <th className="p-4">Código / Fecha</th>
                                <th className="p-4">Beneficiario / CI</th>
                                <th className="p-4">Tipo de Pago</th>
                                <th className="p-4">Concepto Detallado</th>
                                <th className="p-4">Forma de Pago</th>
                                <th className="p-4 text-right">Monto</th>
                            </tr>
                        </thead>
                        <tbody className="text-[9px] md:text-[10px] font-bold uppercase divide-y text-slate-600 print:text-slate-950">
                            {paymentsToDisplay.map(p => {
                                const emp = employees.find(e => e.id === p.employeeId);
                                return (
                                    <tr key={p.id} className="hover:bg-slate-50 transition-colors">
                                        <td className="p-4">
                                            <p className="text-blue-600 font-black">{p.voucherCode}</p>
                                            <p className="text-[8px] font-bold text-slate-400">{new Date(p.date).toLocaleDateString()}</p>
                                        </td>
                                        <td className="p-4">
                                            <p className="font-black text-slate-900">{emp?.surname} {emp?.name}</p>
                                            <p className="text-[8px] font-bold text-slate-400">{emp?.identification}</p>
                                        </td>
                                        <td className="p-4">{p.type}</td>
                                        <td className="p-4 max-w-[200px] truncate">{p.concept}</td>
                                        <td className="p-4">
                                            <span className="text-[8px] bg-slate-100 px-2 py-0.5 rounded-lg border">{p.method}</span>
                                            {p.bankSource && <p className="text-[7px] text-slate-400 mt-1">{p.bankSource}</p>}
                                        </td>
                                        <td className="p-4 text-right font-black text-slate-900">${p.amount.toFixed(2)}</td>
                                    </tr>
                                );
                            })}
                        </tbody>
                    </table>
                </div>
            ) : reportType === 'history' ? (
                <div className="table-responsive">
                    <table className="w-full text-left min-w-[950px] print:min-w-0 print:table-auto">
                        <thead className="bg-slate-50 text-[9px] font-black uppercase text-slate-400 border-b tracking-widest print:bg-slate-900 print:text-white">
                            <tr>
                                <th className="p-4">Colaborador / CI</th>
                                <th className="p-4">Cargo</th>
                                <th className="p-4">F. Ingreso</th>
                                <th className="p-4">F. Salida</th>
                                <th className="p-4">Motivo Cese</th>
                                <th className="p-4 text-center">Novedades</th>
                                <th className="p-4 text-right">Estado</th>
                            </tr>
                        </thead>
                        <tbody className="text-[9px] md:text-[10px] font-bold uppercase divide-y text-slate-600 print:text-slate-950">
                            {historyToDisplay.map(emp => (
                                <tr key={emp.id} className="hover:bg-slate-50 transition-colors">
                                    <td className="p-4">
                                        <p className="font-black text-slate-900">{emp.surname} {emp.name}</p>
                                        <p className="text-[8px] font-bold text-slate-400">{emp.identification}</p>
                                    </td>
                                    <td className="p-4">{emp.role}</td>
                                    <td className="p-4">{new Date(emp.startDate).toLocaleDateString()}</td>
                                    <td className="p-4">{emp.terminationDate ? new Date(emp.terminationDate).toLocaleDateString() : '—'}</td>
                                    <td className="p-4 text-[8px] max-w-[150px] truncate">{emp.terminationReason || '—'}</td>
                                    <td className="p-4 text-center">
                                       <span className="bg-slate-100 px-2 py-1 rounded-lg border">{emp.absences?.length || 0}</span>
                                    </td>
                                    <td className="p-4 text-right">
                                        <span className={`px-2 py-0.5 rounded-lg text-[8px] font-black uppercase ${emp.status === 'active' ? 'bg-emerald-50 text-emerald-600' : 'bg-red-50 text-red-600'}`}>{emp.status}</span>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            ) : (
               <div className="table-responsive">
                  <table className="w-full text-left min-w-[750px] print:min-w-0 print:table-auto">
                    <thead className="bg-slate-50 text-[9px] font-black uppercase text-slate-400 border-b tracking-widest print:bg-slate-900 print:text-white">
                      <tr>
                        <th className="p-4">Fecha / Hora</th>
                        <th className="p-4">Colaborador / Identificación</th>
                        <th className="p-4">Marcación</th>
                        <th className="p-4 text-center">Atraso</th>
                        <th className="p-4">Estado Sistema</th>
                        <th className="p-4 text-right no-print">Acción</th>
                      </tr>
                    </thead>
                    <tbody className="text-[9px] md:text-[10px] font-bold uppercase divide-y text-slate-600 print:text-slate-950">
                      {attendanceToDisplay.map(rec => {
                        const emp = employees.find(e => e.id === rec.employeeId);
                        return (
                          <tr key={rec.id} className="hover:bg-slate-50 transition-colors">
                            <td className="p-4 whitespace-nowrap">{new Date(rec.timestamp).toLocaleString()}</td>
                            <td className="p-4">
                               <p className="font-black text-slate-900">{emp?.surname} {emp?.name}</p>
                               <p className="text-[8px] font-bold text-slate-400">{emp?.identification}</p>
                            </td>
                            <td className="p-4 font-black">{rec.type === 'in' ? 'Ingreso' : rec.type === 'out' ? 'Salida' : 'Media Jornada'}</td>
                            <td className="p-4 text-center">
                               {rec.isLate ? <span className="text-red-600 font-black">SÍ (Crítico)</span> : <span className="text-emerald-600">NO</span>}
                            </td>
                            <td className="p-4">
                              <span className={`px-2 py-0.5 rounded-lg text-[8px] font-black uppercase shadow-sm ${rec.status === 'confirmed' ? 'bg-emerald-50 text-emerald-600' : rec.status === 'pending_approval' ? 'bg-blue-50 text-blue-600' : 'bg-red-50 text-red-600'}`}>{rec.status}</span>
                            </td>
                            <td className="p-4 text-right no-print flex gap-2 justify-end">
                              {role === Role.SUPER_ADMIN && (
                                <>
                                  <button onClick={() => setEditingAttendance(rec)} className="px-2 py-1.5 bg-blue-50 text-blue-600 text-[8px] font-black uppercase rounded-lg hover:bg-blue-600 hover:text-white transition-all">Editar</button>
                                  <button onClick={() => setDeleteConfirm({ isOpen: true, id: rec.id })} className="px-2 py-1.5 bg-red-50 text-red-600 text-[8px] font-black uppercase rounded-lg hover:bg-red-600 hover:text-white transition-all">Borrar</button>
                                </>
                              )}
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
               </div>
            )}
         </div>

         <div className="hidden print:grid grid-cols-2 gap-10 mt-20 p-10 pt-20 border-t-2 border-slate-100">
           <div className="text-center">
              <div className="border-t-2 border-slate-900 pt-3 text-[10px] font-black uppercase">Firma RRHH / Supervisión</div>
              <p className="text-[7px] text-slate-400 mt-1 uppercase font-bold">Responsable de Auditoría</p>
           </div>
           <div className="text-center">
              <div className="border-t-2 border-slate-900 pt-3 text-[10px] font-black uppercase">Sello de Recepción</div>
           </div>
        </div>
      </div>

      {/* Modales de soporte permanecen iguales */}
      <Modal isOpen={!!editingAttendance} onClose={() => setEditingAttendance(null)} title="Editar Marcación de Asistencia" maxWidth="max-w-md">
        {editingAttendance && (
          <div className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-[9px] font-black text-slate-400 uppercase">Fecha y Hora</label>
                <input 
                  type="datetime-local" 
                  className="w-full border-2 p-3 rounded-xl text-xs font-bold"
                  value={editingAttendance.timestamp.slice(0, 16)} 
                  onChange={e => setEditingAttendance({...editingAttendance, timestamp: new Date(e.target.value).toISOString()})}
                />
              </div>
              <div>
                <label className="text-[9px] font-black text-slate-400 uppercase">Tipo Marcación</label>
                <select 
                  className="w-full border-2 p-3 rounded-xl text-xs font-bold uppercase"
                  value={editingAttendance.type}
                  onChange={e => setEditingAttendance({...editingAttendance, type: e.target.value as any})}
                >
                  <option value="in">Ingreso</option>
                  <option value="out">Salida</option>
                  <option value="half_day">Media Jornada</option>
                </select>
              </div>
            </div>
            <div>
              <label className="text-[9px] font-black text-slate-400 uppercase">Estado</label>
              <select 
                className="w-full border-2 p-3 rounded-xl text-xs font-bold uppercase"
                value={editingAttendance.status}
                onChange={e => setEditingAttendance({...editingAttendance, status: e.target.value as any})}
              >
                <option value="confirmed">Confirmado</option>
                <option value="pending_approval">Pendiente</option>
                <option value="rejected">Rechazado</option>
              </select>
            </div>
            <div>
              <label className="text-[9px] font-black text-slate-400 uppercase">Justificación / Nota</label>
              <textarea 
                className="w-full border-2 p-3 rounded-xl text-xs font-bold h-24"
                placeholder="Motivo del cambio..."
                value={editingAttendance.justification || ''}
                onChange={e => setEditingAttendance({...editingAttendance, justification: e.target.value})}
              />
            </div>
            <button onClick={() => setShowConfirmEdit(true)} className="w-full py-4 bg-blue-700 text-white font-black rounded-xl uppercase text-[10px] tracking-widest shadow-lg active:scale-95 transition-all">Guardar Cambios</button>
          </div>
        )}
      </Modal>

      <Modal isOpen={showConfirmEdit} onClose={() => setShowConfirmEdit(false)} title="Confirmar Modificación" type="warning" maxWidth="max-w-sm">
        <div className="space-y-6 text-center">
          <p className="text-xs font-black text-yellow-600 uppercase italic">Advertencia de Seguridad</p>
          <p className="text-[11px] text-slate-500 font-medium leading-relaxed">¿Confirma la modificación de este registro de asistencia? Los cambios afectarán directamente al cálculo de nómina mensual.</p>
          <div className="flex gap-3">
            <button onClick={() => setShowConfirmEdit(false)} className="flex-1 py-4 bg-slate-100 text-slate-600 font-black rounded-xl uppercase text-[9px]">Cancelar</button>
            <button onClick={handleUpdateAttendance} className="flex-1 py-4 bg-blue-600 text-white font-black rounded-xl uppercase text-[9px] shadow-lg active:scale-95">Confirmar Cambios</button>
          </div>
        </div>
      </Modal>

      <Modal isOpen={deleteConfirm.isOpen} onClose={() => setDeleteConfirm({ isOpen: false, id: null })} title="Confirmar Eliminación" type="error" maxWidth="max-w-sm">
        <div className="space-y-6 text-center">
          <p className="text-xs font-black text-red-600 uppercase italic">Atención: Acción Irreversible</p>
          <p className="text-[11px] text-slate-500 font-medium">¿Está seguro de eliminar esta marcación permanentemente del servidor?</p>
          <div className="flex gap-3">
            <button onClick={() => setDeleteConfirm({ isOpen: false, id: null })} className="flex-1 py-4 bg-slate-100 text-slate-600 font-black rounded-xl uppercase text-[9px]">Cancelar</button>
            <button onClick={confirmDeleteAttendance} className="flex-1 py-4 bg-red-600 text-white font-black rounded-xl uppercase text-[9px] shadow-lg active:scale-95 transition-all">Borrar Registro</button>
          </div>
        </div>
      </Modal>

      <Modal isOpen={feedback.isOpen} onClose={() => setFeedback({...feedback, isOpen: false})} title={feedback.title} type={feedback.type}>
          <div className="text-center p-4">
              <p className="text-slate-600 font-bold uppercase text-[11px] leading-relaxed mb-6">{feedback.message}</p>
              <button onClick={() => setFeedback({...feedback, isOpen: false})} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] shadow-lg active:scale-95 transition-all">Aceptar</button>
          </div>
      </Modal>
    </div>
  );
};

export default ReportsModule;

import React, { useState, useEffect } from 'react';
import { Employee, Role, BloodType, Gender, CivilStatus, AbsenceRecord, TerminationReason } from '../../types.ts';
import Modal from '../../components/Modal.tsx';

interface EmployeeModuleProps {
  employees: Employee[];
  onUpdate: (employees: Employee[]) => void;
  role: Role;
  attendance: any[];
  payments: any[];
  company: any;
}

const EmployeeModule: React.FC<EmployeeModuleProps> = ({ employees, onUpdate, role, company }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingEmp, setEditingEmp] = useState<Employee | null>(null);
  const [viewingEmp, setViewingEmp] = useState<Employee | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [showArchived, setShowArchived] = useState(false);
  const [hasBankInfo, setHasBankInfo] = useState(true);

  const [isAbsenceModalOpen, setIsAbsenceModalOpen] = useState(false);
  const [isTermModalOpen, setIsTermModalOpen] = useState(false);
  const [isDeleteConfirmModalOpen, setIsDeleteConfirmModalOpen] = useState(false);
  const [isResetConfirmModalOpen, setIsResetConfirmModalOpen] = useState(false);

  const [newAbsence, setNewAbsence] = useState<Partial<AbsenceRecord>>({ type: 'Falta', justified: false, date: new Date().toISOString().split('T')[0], reason: '' });
  const [termData, setTermData] = useState({ reason: TerminationReason.VOLUNTARY, details: '', date: new Date().toISOString().split('T')[0] });

  const [feedback, setFeedback] = useState<{isOpen: boolean, title: string, message: string, type: 'success' | 'error' | 'info'}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  const initialForm: Partial<Employee> = {
    name: '', surname: '', identification: '', birthDate: '', phone: '', email: '', 
    gender: Gender.MASCULINO, civilStatus: CivilStatus.SOLTERO,
    origin: 'ECUATORIANA', address: '', 
    bloodType: BloodType.O_POS, startDate: new Date().toISOString().split('T')[0],
    role: Role.EMPLOYEE, salary: 482.00, status: 'active' as const, photo: '', pin: '',
    emergencyContact: { name: '', phone: '' },
    isFixed: true, isAffiliated: true, overSalaryType: 'monthly',
    bankInfo: { ifi: '', type: 'Ahorros', account: '' },
    absences: [],
    observations: []
  };

  const [form, setForm] = useState<Partial<Employee>>(initialForm);

  useEffect(() => {
    if (!form.isAffiliated && form.overSalaryType !== 'none') {
      setForm(prev => ({ ...prev, overSalaryType: 'none' }));
    }
  }, [form.isAffiliated]);

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setForm(prev => ({ ...prev, photo: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSave = () => {
    if (!form.name || !form.surname || !form.identification || !form.salary || !form.role) {
      setFeedback({ isOpen: true, title: "Error", message: "Nombres, apellidos, cédula, cargo y sueldo son obligatorios.", type: "error" });
      return;
    }
    const finalForm = { ...form };
    if (!hasBankInfo) finalForm.bankInfo = { ifi: 'NO APLICA', type: 'Ahorros', account: 'N/A' };

    let updatedList: Employee[];
    if (editingEmp) {
      updatedList = employees.map(e => e.id === editingEmp.id ? { ...e, ...finalForm } as Employee : e);
      setFeedback({ isOpen: true, title: "Éxito", message: "Expediente actualizado correctamente.", type: "success" });
    } else {
      const autoPin = Math.floor(100000 + Math.random() * 900000).toString();
      const newEmp: Employee = { 
        ...finalForm, 
        id: Math.random().toString(36).substr(2, 9), 
        pin: autoPin, 
        pinChanged: false, 
        pinNeedsReset: false, 
        pinResetRequested: false,
        absences: [], 
        observations: [], 
        totalHoursWorked: 0, 
        status: 'active' as const 
      } as Employee;
      updatedList = [...employees, newEmp];
      setFeedback({ isOpen: true, title: "Registro Exitoso", message: `Colaborador registrado. PIN PROVISIONAL: ${autoPin}.`, type: "success" });
    }
    onUpdate(updatedList);
    setIsModalOpen(false);
  };

  const handleApprovePinReset = (emp: Employee) => {
    const randomPin = Math.floor(100000 + Math.random() * 900000).toString();
    const updated: Employee[] = employees.map(e => e.id === emp.id ? { 
      ...e, 
      pin: randomPin, 
      pinNeedsReset: true, 
      pinResetRequested: false,
      pinChanged: false 
    } : e);
    onUpdate(updated);
    if (viewingEmp && viewingEmp.id === emp.id) {
       setViewingEmp({ ...viewingEmp, pinNeedsReset: true, pinResetRequested: false, pin: randomPin, pinChanged: false });
    }
    setFeedback({ 
      isOpen: true, 
      title: "Reseteo Aplicado", 
      message: `PIN restablecido exitosamente. El nuevo PIN PROVISIONAL es: ${randomPin}. El empleado deberá cambiarlo obligatoriamente en su próxima marcación.`, 
      type: "success" 
    });
    setIsResetConfirmModalOpen(false);
  };

  const handleAddAbsence = () => {
    if (!viewingEmp) return;
    const record: AbsenceRecord = { ...newAbsence, id: Math.random().toString(36).substr(2, 9) } as AbsenceRecord;
    const updated: Employee[] = employees.map(e => e.id === viewingEmp.id ? { ...e, absences: [...(e.absences || []), record] } : e);
    onUpdate(updated);
    setViewingEmp({ ...viewingEmp, absences: [...(viewingEmp.absences || []), record] });
    setIsAbsenceModalOpen(false);
  };

  const handleTerminate = () => {
    if (!viewingEmp) return;
    const updated: Employee[] = employees.map(e => e.id === viewingEmp.id ? { 
      ...e, 
      status: 'terminated' as const, 
      terminationDate: termData.date, 
      terminationReason: termData.reason, 
      terminationDetails: termData.details 
    } : e);
    onUpdate(updated);
    setViewingEmp(null);
    setIsTermModalOpen(false);
    setFeedback({ isOpen: true, title: "Desvinculación", message: "Colaborador desvinculado con éxito.", type: "success" });
  };

  const handleDeletePermanent = () => {
    if (!viewingEmp) return;
    const updated = employees.filter(e => e.id !== viewingEmp.id);
    onUpdate(updated);
    setViewingEmp(null);
    setIsDeleteConfirmModalOpen(false);
    setFeedback({ isOpen: true, title: "Registro Eliminado", message: "El colaborador ha sido borrado definitivamente.", type: "success" });
  };

  const filteredEmployees = employees.filter(e => {
    const searchString = `${e.name} ${e.surname} ${e.identification} ${e.role}`.toLowerCase();
    const matchesSearch = searchString.includes(searchTerm.toLowerCase());
    return showArchived 
      ? matchesSearch && (e.status === 'archived' || e.status === 'terminated') 
      : matchesSearch && e.status === 'active';
  });

  return (
    <div className="space-y-6 fade-in">
      <div className="bg-white p-6 rounded-3xl md:rounded-[2.5rem] shadow-sm border border-slate-100 flex flex-col md:flex-row justify-between items-center no-print gap-4">
        <div className="w-full md:w-auto text-center md:text-left">
          <h2 className="text-xl font-[950] text-slate-900 tracking-tighter uppercase leading-none">Gestión Humana</h2>
          <div className="flex gap-4 mt-2 justify-center md:justify-start">
            <button onClick={() => setShowArchived(false)} className={`text-[9px] font-black uppercase tracking-widest ${!showArchived ? 'text-blue-600 border-b-2 border-blue-600' : 'text-slate-400'}`}>Activos</button>
            <button onClick={() => setShowArchived(true)} className={`text-[9px] font-black uppercase tracking-widest ${showArchived ? 'text-blue-600 border-b-2 border-blue-600' : 'text-slate-400'}`}>Historial / Bajas</button>
          </div>
        </div>
        <div className="flex flex-col sm:flex-row gap-3 w-full md:w-auto">
          <input type="text" placeholder="Filtrar por nombre, CI..." className="w-full sm:w-64 p-3 border rounded-xl text-[11px] uppercase font-bold focus:border-blue-500 outline-none" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
          <button onClick={() => { setForm(initialForm); setEditingEmp(null); setIsModalOpen(true); }} className="w-full sm:w-auto px-6 py-3.5 bg-blue-700 text-white font-black rounded-xl shadow-lg uppercase text-[9px] tracking-widest active:scale-95 transition-all">Nuevo Registro</button>
        </div>
      </div>

      <div className="bg-white rounded-3xl md:rounded-[2.5rem] shadow-sm border overflow-hidden no-print">
        <div className="table-responsive">
          <table className="w-full text-left min-w-[600px] md:min-w-full">
            <thead className="bg-slate-50 text-[8px] font-black text-slate-400 uppercase tracking-widest">
              <tr>
                <th className="px-6 py-4">Colaborador</th>
                <th className="px-6 py-4">Identificación</th>
                <th className="px-6 py-4">Cargo</th>
                <th className="px-6 py-4 text-center">Estado</th>
                <th className="px-6 py-4 text-right">Acciones</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50 text-[10px] md:text-[11px] font-black uppercase">
              {filteredEmployees.map(emp => (
                <tr key={emp.id} className="hover:bg-blue-50/40 transition-colors">
                  <td className="px-6 py-3 font-black text-slate-900 flex items-center gap-3">
                    <div className="w-8 h-8 rounded-lg overflow-hidden border bg-slate-100 flex items-center justify-center shrink-0">
                      {emp.photo ? <img src={emp.photo} className="w-full h-full object-cover" /> : <span>👤</span>}
                    </div>
                    <span className="truncate">{emp.surname} {emp.name}</span>
                  </td>
                  <td className="px-6 py-3 font-mono">{emp.identification}</td>
                  <td className="px-6 py-3 text-blue-600 text-[9px]">{emp.role}</td>
                  <td className="px-6 py-3 text-center">
