import React, { useState } from 'react';
import { Employee, Payment, AttendanceRecord, CompanyConfig, GlobalSettings, Role } from '../../types.ts';
import { db, doc, setDoc, deleteDoc, compressData } from '../../firebase.ts';
import Modal from '../../components/Modal.tsx';

interface ReportsModuleProps {
  employees: Employee[];
  payments: Payment[];
  attendance: AttendanceRecord[];
  company: CompanyConfig | null;
  settings: GlobalSettings;
  role: Role;
}

const ReportsModule: React.FC<ReportsModuleProps> = ({ employees, payments = [], attendance = [], company, settings, role }) => {
  const [reportType, setReportType] = useState<'attendance' | 'payments' | 'validation' | 'history'>('attendance');
  const [searchTerm, setSearchTerm] = useState('');
  const [feedback, setFeedback] = useState({ isOpen: false, title: '', message: '', type: 'success' as any });
  const [deleteConfirm, setDeleteConfirm] = useState<{isOpen: boolean, id: string | null}>({ isOpen: false, id: null });
  const [editingAttendance, setEditingAttendance] = useState<AttendanceRecord | null>(null);
  const [showConfirmEdit, setShowConfirmEdit] = useState(false);

  const pendingAttendance = (attendance || []).filter(a => a.status === 'pending_approval');

  const handleValidate = async (record: AttendanceRecord, newStatus: 'confirmed' | 'rejected') => {
    const updatedRecord = { ...record, status: newStatus, validatedAt: new Date().toISOString() };
    await setDoc(doc(db, "attendance", record.id), { payload: compressData(updatedRecord), timestamp: record.timestamp });
    setFeedback({ isOpen: true, title: "Actualización", message: `Marcación validada como: ${newStatus.toUpperCase()}`, type: 'success' });
  };

  const confirmDeleteAttendance = async () => {
    if (!deleteConfirm.id) return;
    try {
      await deleteDoc(doc(db, "attendance", deleteConfirm.id));
      setDeleteConfirm({ isOpen: false, id: null });
      setFeedback({ isOpen: true, title: "Eliminado", message: "Registro borrado definitivamente.", type: 'success' });
    } catch (e) {
      setDeleteConfirm({ isOpen: false, id: null });
      setFeedback({ isOpen: true, title: "Error", message: "No se pudo eliminar el registro.", type: 'error' });
    }
  };

  const exportExcel = () => {
    let csv = "";
    if (reportType === 'payments') {
        csv = "\uFEFFCódigo,Fecha,Beneficiario,Identificación,Concepto,Detalle,Método,Monto\n";
        paymentsToDisplay.forEach(p => {
          const emp = employees.find(e => e.id === p.employeeId);
          csv += `"${p.voucherCode}","${new Date(p.date).toLocaleDateString()}","${emp?.surname} ${emp?.name}","${emp?.identification}","${p.type}","${p.concept}","${p.method}","${p.amount.toFixed(2)}"\n`;
        });
    } else if (reportType === 'history') {
        csv = "\uFEFFColaborador,Identificación,Cargo,F. Ingreso,F. Salida,Motivo,Novedades,Estado\n";
        historyToDisplay.forEach(emp => {
          csv += `"${emp.surname} ${emp.name}","${emp.identification}","${emp.role}","${emp.startDate}","${emp.terminationDate || 'N/A'}","${emp.terminationReason || 'N/A'}","${emp.absences?.length || 0}","${emp.status}"\n`;
        });
    } else {
        csv = "\uFEFFFecha,Hora,Colaborador,Identificación,Cargo,Tipo Marcación,Estado,Atraso,Justificación\n";
        attendanceToDisplay.forEach(rec => {
          const emp = employees.find(e => e.id === rec.employeeId);
          const date = new Date(rec.timestamp);
          csv += `"${date.toLocaleDateString()}","${date.toLocaleTimeString()}","${emp?.surname} ${emp?.name}","${emp?.identification}","${emp?.role}","${rec.type === 'in' ? 'Entrada' : 'Salida'}","${rec.status}","${rec.isLate ? 'SI' : 'NO'}","${rec.justification || ''}"\n`;
        });
    }
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `ASISTUP_${reportType.toUpperCase()}_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  };

  const attendanceToDisplay = (attendance || []).filter(a => {
    const emp = employees.find(e => e.id === a.employeeId);
    const searchStr = `${emp?.surname} ${emp?.name} ${emp?.identification} ${a.justification || ""} ${a.status} ${a.type}`.toLowerCase();
    return searchStr.includes(searchTerm.toLowerCase());
  }).sort((a,b) => b.timestamp.localeCompare(a.timestamp));

  const paymentsToDisplay = (payments || []).filter(p => {
    const emp = employees.find(e => e.id === p.employeeId);
    const searchStr = `${emp?.surname} ${emp?.name} ${emp?.identification} ${p.concept} ${p.type} ${p.voucherCode} ${p.method}`.toLowerCase();
    return searchStr.includes(searchTerm.toLowerCase());
  }).sort((a,b) => b.date.localeCompare(a.date));

  const historyToDisplay = employees.filter(e => {
    const searchStr = `${e.name} ${e.surname} ${e.identification} ${e.role} ${e.status}`.toLowerCase();
    return searchStr.includes(searchTerm.toLowerCase());
  }).sort((a,b) => b.startDate.localeCompare(a.startDate));

  return (
    <div className="space-y-6 md:space-y-8 fade-in">
      <div className="flex flex-col md:flex-row justify-between items-center bg-white p-8 rounded-[2.5rem] shadow-sm border border-slate-100 gap-6 no-print">
        <div className="w-full">
          <h2 className="text-2xl font-[950] text-slate-900 uppercase tracking-tighter">Reportes Institucionales</h2>
          <div className="flex flex-col sm:flex-row gap-4 mt-4">
            <div className="flex gap-2 overflow-x-auto pb-2 sm:pb-0 no-scrollbar">
              <button onClick={() => {setReportType('attendance'); setSearchTerm('');}} className={`whitespace-nowrap px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${reportType === 'attendance' ? 'bg-blue-600 text-white' : 'bg-slate-100 text-slate-400'}`}>Asistencia</button>
              <button onClick={() => {setReportType('payments'); setSearchTerm('');}} className={`whitespace-nowrap px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${reportType === 'payments' ? 'bg-blue-600 text-white' : 'bg-slate-100 text-slate-400'}`}>Egresos</button>
              <button onClick={() => {setReportType('history'); setSearchTerm('');}} className={`whitespace-nowrap px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${reportType === 'history' ? 'bg-blue-600 text-white' : 'bg-slate-100 text-slate-400'}`}>Historial</button>
            </div>
            <input type="text" placeholder="Filtrar datos..." className="flex-1 p-3 border rounded-xl text-[11px] font-bold uppercase outline-none focus:border-blue-500" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
          </div>
        </div>
        <div className="flex gap-3">
          <button onClick={exportExcel} className="px-6 py-4 bg-emerald-600 text-white font-black rounded-xl shadow-lg uppercase text-[10px] active:scale-95 transition-all">Exportar Excel</button>
          <button onClick={() => window.print()} className="px-6 py-4 bg-slate-900 text-white font-black rounded-xl shadow-lg uppercase text-[10px] active:scale-95 transition-all">PDF (A4 / B&N)</button>
        </div>
      </div>

      <div className="bg-white rounded-3xl md:rounded-[2.5rem] shadow-sm border overflow-hidden" id="reports-printable-area">
         <div className="hidden print:block text-center border-b-2 border-black pb-4 mb-6 px-8 pt-8">
           <h1 className="text-xl font-black uppercase leading-none">{company?.name || 'ASIST UP'}</h1>
           <p className="text-[10px] font-bold uppercase mt-1">REPORTE OFICIAL: {reportType.toUpperCase()}</p>
           <p className="text-[9px] font-bold text-right mt-2 uppercase">FECHA: {new Date().toLocaleString()}</p>
         </div>

         <div className="p-8">
            <div className="table-responsive">
                <table className="w-full text-left print:table-auto">
                    <thead className="bg-slate-50 text-[10px] font-black uppercase text-slate-400 print:bg-white print:text-black">
                        {reportType === 'attendance' ? (
                            <tr><th className="p-4">FECHA/HORA</th><th className="p-4">COLABORADOR</th><th className="p-4">MARCACIÓN</th><th className="p-4 text-center">ESTADO</th></tr>
                        ) : reportType === 'payments' ? (
                            <tr><th className="p-4">CÓDIGO</th><th className="p-4">BENEFICIARIO</th><th className="p-4">DETALLE</th><th className="p-4 text-right">MONTO</th></tr>
                        ) : (
                            <tr><th className="p-4">COLABORADOR</th><th className="p-4">CARGO</th><th className="p-4">INGRESO</th><th className="p-4 text-right">ESTADO</th></tr>
                        )}
                    </thead>
                    <tbody className="text-[11px] font-bold uppercase divide-y print:text-black">
                        {reportType === 'attendance' && attendanceToDisplay.map(rec => (
                            <tr key={rec.id}><td className="p-4">{new Date(rec.timestamp).toLocaleString()}</td><td className="p-4">{employees.find(e => e.id === rec.employeeId)?.surname}</td><td className="p-4">{rec.type}</td><td className="p-4 text-center">{rec.status}</td></tr>
                        ))}
                        {reportType === 'payments' && paymentsToDisplay.map(p => (
                            <tr key={p.id}><td className="p-4">{p.voucherCode}</td><td className="p-4">{employees.find(e => e.id === p.employeeId)?.surname}</td><td className="p-4">{p.concept}</td><td className="p-4 text-right">${p.amount.toFixed(2)}</td></tr>
                        ))}
                        {reportType === 'history' && historyToDisplay.map(emp => (
                            <tr key={emp.id}><td className="p-4">{emp.surname} {emp.name}</td><td className="p-4">{emp.role}</td><td className="p-4">{emp.startDate}</td><td className="p-4 text-right">{emp.status}</td></tr>
                        ))}
                    </tbody>
                </table>
            </div>
         </div>
      </div>
    </div>
  );
};

export default ReportsModule;

import React, { useState } from 'react';
import { Employee, Payment, CompanyConfig, GlobalSettings, Role } from '../../types.ts';
import Modal from '../../components/Modal.tsx';

interface PayrollModuleProps {
  employees: Employee[];
  payments: Payment[];
  onUpdatePayments?: (payments: Payment[]) => void;
  onUpdateEmployees?: (employees: Employee[]) => void;
  attendance: any[];
  company: CompanyConfig | null;
  settings: GlobalSettings;
  role: Role;
}

const PayrollModule: React.FC<PayrollModuleProps> = ({ employees, payments, onUpdatePayments, onUpdateEmployees, attendance = [], company, settings, role }) => {
  const [selectedMonth, setSelectedMonth] = useState('FEBRERO');
  const [individualPayroll, setIndividualPayroll] = useState<Employee | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [editingEmployee, setEditingEmployee] = useState<Employee | null>(null);
  const [feedback, setFeedback] = useState({ isOpen: false, title: '', message: '', type: 'success' as any });
  const [showConfirmPayrollEdit, setShowConfirmPayrollEdit] = useState(false);

  const [adjustments, setAdjustments] = useState({
    extraHours: 0, bonuses: 0, vacation: 0, incomeConcept: '',
    loans: 0, backPay: 0, expenseConcept: '',
    thirteenth: 0, fourteenth: 0, reserve: 0
  });

  const monthMap: { [key: string]: number } = {
    'ENERO': 0, 'FEBRERO': 1, 'MARZO': 2, 'ABRIL': 3, 'MAYO': 4, 'JUNIO': 5,
    'JULIO': 6, 'AGOSTO': 7, 'SEPTIEMBRE': 8, 'OCTUBRE': 9, 'NOVIEMBRE': 10, 'DICIEMBRE': 11
  };

  const isJanuary2026 = selectedMonth === 'ENERO';

  const calculatePayrollData = (emp: Employee, index: number) => {
    if (isJanuary2026) return {
      baseSalary: 0, holidaySurcharge: 0, reserveFund: 0, bonuses: 0, extraHours: 0, vacation: 0,
      monthly13th: 0, monthly14th: 0, totalOverSalaries: 0, iessContribution: 0, loans: 0, backPay: 0,
      totalIncomes: 0, totalExpenses: 0, netToReceive: 0, workedDays: 0, expectedDays: 0
    };

    const monthIndex = monthMap[selectedMonth] ?? 0;
    const year = 2026;

    let expectedDays = 0;
    const daysInMonth = new Date(year, monthIndex + 1, 0).getDate();
    for (let d = 1; d <= daysInMonth; d++) {
      const date = new Date(year, monthIndex, d);
      const dayOfWeek = date.getDay();
      if (dayOfWeek >= 1 && dayOfWeek <= 6) expectedDays++;
    }

    const empAttendance = (attendance || []).filter(a => {
      const d = new Date(a.timestamp);
      return a.employeeId === emp.id && d.getMonth() === monthIndex && d.getFullYear() === year && a.status === 'confirmed';
    });

    const attendanceByDate: { [key: string]: { ins: number, half: number, isHoliday: boolean } } = {};
    empAttendance.forEach(a => {
      const dateStr = a.timestamp.split('T')[0];
      if (!attendanceByDate[dateStr]) {
        attendanceByDate[dateStr] = { ins: 0, half: 0, isHoliday: (settings.holidays || []).includes(dateStr) };
      }
      if (a.type === 'in') attendanceByDate[dateStr].ins++;
      if (a.type === 'half_day') attendanceByDate[dateStr].half++;
    });

    let workedDays = 0;
    let holidayDaysWorked = 0;
    Object.entries(attendanceByDate).forEach(([dateStr, day]) => {
      let dayVal = 0;
      if (day.ins >= 2) dayVal = 1.0;
      else if (day.ins === 1 || day.half > 0) dayVal = 0.5;
      workedDays += dayVal;
      if (day.isHoliday) holidayDaysWorked += dayVal;
    });

    const justifiedAbsences = (emp.absences || []).filter(a => {
      const d = new Date(a.date);
      return d.getMonth() === monthIndex && d.getFullYear() === year && a.type === 'Falta' && a.justified;
    }).length;

    workedDays = Math.min(expectedDays, workedDays + justifiedAbsences);
    const attendanceProportion = expectedDays > 0 ? workedDays / expectedDays : 0;
    const earnedBase = emp.salary * attendanceProportion;
    const holidaySurcharge = (emp.salary / 30) * holidayDaysWorked;

    const monthlyPayments = payments.filter(p => p.employeeId === emp.id && p.month === selectedMonth && p.status === 'paid');
    const bonuses = monthlyPayments.filter(p => p.type === 'Bonus').reduce((sum, p) => sum + p.amount, 0);
    const extraHours = monthlyPayments.filter(p => p.type === 'ExtraHours').reduce((sum, p) => sum + p.amount, 0);
    const vacation = monthlyPayments.filter(p => p.type === 'Vacation').reduce((sum, p) => sum + p.amount, 0);
    const adj13 = monthlyPayments.filter(p => p.type === 'Thirteenth').reduce((sum, p) => sum + p.amount, 0);
    const adj14 = monthlyPayments.filter(p => p.type === 'Fourteenth').reduce((sum, p) => sum + p.amount, 0);
    const adjRes = monthlyPayments.filter(p => p.type === 'Salary' && p.concept.includes('RESERVA')).reduce((sum, p) => sum + p.amount, 0);

    const isMonthly = emp.overSalaryType === 'monthly';
    const isAffiliated = emp.isAffiliated;
    const taxableIncome = earnedBase + extraHours + bonuses + holidaySurcharge;
    const monthly13th = ((isAffiliated && isMonthly) ? (taxableIncome) / 12 : 0) + adj13;
    const monthly14th = ((isAffiliated && isMonthly) ? (settings.sbu / 12) * attendanceProportion : 0) + adj14;
    const reserveFund = ((isAffiliated && isMonthly) ? (taxableIncome * settings.reserveRate) : 0) + adjRes;
    const totalOverSalaries = monthly13th + monthly14th + reserveFund;
    const totalIncomes = earnedBase + totalOverSalaries + bonuses + extraHours + vacation + holidaySurcharge;
    const iessContribution = isAffiliated ? (taxableIncome * settings.iessRate) : 0;
    const loans = monthlyPayments.filter(p => p.type === 'Loan' || p.type === 'Emergency').reduce((sum, p) => sum + p.amount, 0);
    const backPay = monthlyPayments.filter(p => p.type === 'BackPay').reduce((sum, p) => sum + p.amount, 0);
    const totalExpenses = iessContribution + loans + backPay;
    const netToReceive = totalIncomes - totalExpenses;

    return { 
      baseSalary: earnedBase, holidaySurcharge, reserveFund, bonuses, extraHours, vacation,
      monthly13th, monthly14th, totalOverSalaries, iessContribution, loans, backPay,
      totalIncomes, totalExpenses, netToReceive, workedDays, expectedDays
    };
  };

  const exportGeneralExcel = () => {
    let csv = "\uFEFFColaborador,Identificación,Días Trabajados,Sueldo Ganado,Recargo Feriado,Extras y Bonos,Dec. Tercero,Dec. Cuarto,Fondos Reserva,Total Ingresos,IESS 9.45%,Egresos Otros,Neto Recibir\n";
    filteredEmployees.filter(e => e.status === 'active').forEach((emp, idx) => {
      const d = calculatePayrollData(emp, idx);
      csv += `"${emp.surname} ${emp.name}","${emp.identification}","${d.workedDays}","${d.baseSalary.toFixed(2)}","${d.holidaySurcharge.toFixed(2)}","${(d.extraHours + d.bonuses + d.vacation).toFixed(2)}","${d.monthly13th.toFixed(2)}","${d.monthly14th.toFixed(2)}","${d.reserveFund.toFixed(2)}","${d.totalIncomes.toFixed(2)}","${d.iessContribution.toFixed(2)}","${(d.loans + d.backPay).toFixed(2)}","${d.netToReceive.toFixed(2)}"\n`;
    });
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `ROL_GENERAL_${selectedMonth}_2026.csv`;
    link.click();
  };

  const exportIndividualExcel = (emp: Employee) => {
    const d = calculatePayrollData(emp, 0);
    let csv = "\uFEFFROL DE PAGOS INDIVIDUAL - 2026\n";
    csv += `"COLABORADOR","${emp.surname} ${emp.name}"\n`;
    csv += `"CEDULA","${emp.identification}"\n`;
    csv += `"PERIODO","${selectedMonth}"\n`;
    csv += `"\n`;
    csv += `"DETALLE DE INGRESOS","VALOR"\n`;
    csv += `"Sueldo Ganado","${d.baseSalary.toFixed(2)}"\n`;
    csv += `"Recargo Feriado (100%)","${d.holidaySurcharge.toFixed(2)}"\n`;
    csv += `"Bonos y Extras","${(d.extraHours + d.bonuses + d.vacation).toFixed(2)}"\n`;
    csv += `"Decimo Tercero","${d.monthly13th.toFixed(2)}"\n`;
    csv += `"Decimo Cuarto","${d.monthly14th.toFixed(2)}"\n`;
    csv += `"Fondos Reserva","${d.reserveFund.toFixed(2)}"\n`;
    csv += `"TOTAL INGRESOS","${d.totalIncomes.toFixed(2)}"\n`;
    csv += `"\n`;
    csv += `"DETALLE DE EGRESOS","VALOR"\n`;
    csv += `"Aporte IESS 9.45%","${d.iessContribution.toFixed(2)}"\n`;
    csv += `"Otros Egresos","${(d.loans + d.backPay).toFixed(2)}"\n`;
    csv += `"TOTAL EGRESOS","${d.totalExpenses.toFixed(2)}"\n`;
    csv += `"\n`;
    csv += `"NETO A RECIBIR","${d.netToReceive.toFixed(2)}"\n`;

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `ROL_${emp.identification}_${selectedMonth}.csv`;
    link.click();
  };

  const handleUpdatePayrollValues = () => {
    if (!editingEmployee || !onUpdateEmployees) return;
    const updatedEmployees = employees.map(e => e.id === editingEmployee.id ? editingEmployee : e);
    onUpdateEmployees(updatedEmployees);
    if (onUpdatePayments) {
      const newPayments: Payment[] = [];
      const commonData = { employeeId: editingEmployee.id, date: new Date().toISOString(), month: selectedMonth, year: "2026", method: 'Efectivo' as const, status: 'paid' as const };
      if (adjustments.extraHours !== 0) newPayments.push({ ...commonData, id: Math.random().toString(36).substr(2, 12), amount: adjustments.extraHours, type: 'ExtraHours', concept: 'AJUSTE HORAS EXTRAS' });
      if (adjustments.bonuses !== 0) newPayments.push({ ...commonData, id: Math.random().toString(36).substr(2, 12), amount: adjustments.bonuses, type: 'Bonus', concept: adjustments.incomeConcept || 'BONO ADICIONAL' });
      if (newPayments.length > 0) onUpdatePayments([...payments, ...newPayments]);
    }
    setEditingEmployee(null);
    setShowConfirmPayrollEdit(false);
    setFeedback({ isOpen: true, title: "Sincronizado", message: "Nómina actualizada exitosamente.", type: 'success' });
  };

  const filteredEmployees = employees.filter(e => {
    const searchStr = `${e.name} ${e.surname} ${e.identification} ${e.role}`.toLowerCase();
    return searchStr.includes(searchTerm.toLowerCase());
  });

  return (
    <div className="space-y-6 md:space-y-8 fade-in">
      <div className="flex flex-col md:flex-row justify-between items-center bg-white p-6 rounded-3xl md:rounded-[2rem] shadow-sm border border-slate-100 no-print gap-6">
        <div className="w-full">
          <h2 className="text-xl font-black text-slate-900 uppercase">Control Detallado de Nómina</h2>
          <div className="flex flex-col sm:flex-row gap-4 mt-4">
             <select className="p-3 border rounded-xl text-[11px] font-black uppercase outline-none focus:border-blue-500" value={selectedMonth} onChange={e => setSelectedMonth(e.target.value)}>
                {['ENERO','FEBRERO','MARZO','ABRIL','MAYO','JUNIO','JULIO','AGOSTO','SEPTIEMBRE','OCTUBRE','NOVIEMBRE','DICIEMBRE'].map(m => <option key={m} value={m}>{m}</option>)}
             </select>
             <input type="text" placeholder="Buscar colaborador..." className="flex-1 p-3 border rounded-xl text-[11px] font-bold uppercase outline-none focus:border-blue-500" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
          </div>
        </div>
        <div className="flex flex-wrap gap-2 justify-center md:justify-end">
           <button onClick={exportGeneralExcel} className="px-6 py-4 bg-emerald-600 text-white font-black rounded-xl uppercase text-[10px] tracking-widest active:scale-95 shadow-lg">Excel General</button>
           <button onClick={() => window.print()} className="px-6 py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] tracking-widest active:scale-95 shadow-lg">PDF General</button>
        </div>
      </div>

      {isJanuary2026 ? (
        <div className="bg-white p-24 rounded-[3rem] border-2 border-dashed border-slate-200 text-center">
          <span className="text-6xl opacity-30">⏳</span>
          <h3 className="text-xl font-black text-slate-900 uppercase tracking-tighter mt-8">Periodo No Operativo</h3>
          <p className="text-[12px] text-slate-500 font-bold uppercase tracking-widest mt-4">Nómina disponible desde Febrero 2026.</p>
        </div>
      ) : (
        <div className="bg-white p-4 md:p-8 rounded-3xl md:rounded-[2.5rem] shadow-sm border overflow-hidden">
          <div className="table-responsive overflow-x-auto">
            <table className="w-full text-left border-collapse min-w-[1400px] print:min-w-0 print:table-auto">
              <thead className="bg-slate-900 text-white text-[10px] font-black uppercase tracking-widest">
                <tr>
                  <th className="p-4">Colaborador / CI</th>
                  <th className="p-4 text-center">Días</th>
                  <th className="p-4 text-center">Ganado</th>
                  <th className="p-4 text-center">Feriado</th>
                  <th className="p-4 text-center">13ero</th>
                  <th className="p-4 text-center">14to</th>
                  <th className="p-4 text-center">Tot. Ingresos</th>
                  <th className="p-4 text-center">IESS</th>
                  <th className="p-4 text-center">Egresos</th>
                  <th className="p-4 text-center bg-blue-800">Neto a Recibir</th>
                  <th className="p-4 text-center no-print">Acción</th>
                </tr>
              </thead>
              <tbody className="text-[11px] uppercase font-bold text-slate-700 divide-y">
                {filteredEmployees.filter(e => e.status === 'active').map((emp, idx) => {
                  const d = calculatePayrollData(emp, idx);
                  return (
                    <tr key={emp.id} className="hover:bg-slate-50">
                      <td className="p-4"><p className="font-black text-slate-900">{emp.surname} {emp.name}</p><p className="text-[9px] text-slate-400">{emp.identification}</p></td>
                      <td className="p-4 text-center">{d.workedDays}</td>
                      <td className="p-4 text-center">${d.baseSalary.toFixed(2)}</td>
                      <td className="p-4 text-center text-red-600">${d.holidaySurcharge.toFixed(2)}</td>
                      <td className="p-4 text-center">${d.monthly13th.toFixed(2)}</td>
                      <td className="p-4 text-center">${d.monthly14th.toFixed(2)}</td>
                      <td className="p-4 text-center font-black">${d.totalIncomes.toFixed(2)}</td>
                      <td className="p-4 text-center text-red-500">${d.iessContribution.toFixed(2)}</td>
                      <td className="p-4 text-center">${d.totalExpenses.toFixed(2)}</td>
                      <td className="p-4 text-center font-[950] text-blue-700 bg-blue-50/20">${d.netToReceive.toFixed(2)}</td>
                      <td className="p-4 text-center no-print space-x-2">
                         <button onClick={() => setIndividualPayroll(emp)} className="px-3 py-1.5 bg-blue-700 text-white rounded-lg text-[9px] font-black uppercase shadow-md active:scale-95">Ver Rol</button>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}

      <Modal isOpen={!!individualPayroll} onClose={() => setIndividualPayroll(null)} title="Rol de Pagos Institucional">
        {individualPayroll && (() => {
           const d = calculatePayrollData(individualPayroll, 0);
           return (
             <div className="space-y-8 bg-white p-2" id="individual-role-print">
               <div className="flex justify-between items-start border-b-2 border-black pb-4">
                  <div><h3 className="text-xl font-black uppercase leading-none">{company?.name || 'ASIST UP'}</h3><p className="text-[10px] font-bold mt-1">RUC: {company?.ruc || '—'}</p></div>
                  <div className="text-right font-black uppercase text-[10px]">ROL DE PAGOS 2026</div>
               </div>
               <div className="grid grid-cols-2 gap-4 text-[11px] font-bold uppercase">
                  <div className="p-4 border border-black"><p className="text-[9px] text-slate-500 uppercase">Colaborador</p><p className="text-black font-black">{individualPayroll.surname} {individualPayroll.name}</p><p className="text-[9px]">{individualPayroll.role}</p></div>
                  <div className="p-4 border border-black text-right"><p className="text-[9px] text-slate-500 uppercase">Período / Cédula</p><p className="text-black font-black">{selectedMonth} 2026</p><p className="text-[9px]">{individualPayroll.identification}</p></div>
               </div>

               <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-4">
                     <h4 className="text-[10px] font-black uppercase border-b border-black pb-1">INGRESOS</h4>
                     <div className="space-y-1.5 text-[11px] uppercase">
                        <div className="flex justify-between"><span>Sueldo Ganado</span><span>${d.baseSalary.toFixed(2)}</span></div>
                        <div className="flex justify-between"><span>Recargo Feriado (100%)</span><span>${d.holidaySurcharge.toFixed(2)}</span></div>
                        <div className="flex justify-between"><span>Décimo Tercero Mens.</span><span>${d.monthly13th.toFixed(2)}</span></div>
                        <div className="flex justify-between font-black border-t border-black pt-1"><span>TOTAL INGRESOS</span><span>${d.totalIncomes.toFixed(2)}</span></div>
                     </div>
                  </div>
                  <div className="space-y-4">
                     <h4 className="text-[10px] font-black uppercase border-b border-black pb-1">EGRESOS</h4>
                     <div className="space-y-1.5 text-[11px] uppercase">
                        <div className="flex justify-between"><span>Aporte Personal IESS</span><span>${d.iessContribution.toFixed(2)}</span></div>
                        <div className="flex justify-between"><span>Otros Egresos/Préstamos</span><span>${d.totalExpenses.toFixed(2)}</span></div>
                        <div className="flex justify-between font-black border-t border-black pt-1"><span>TOTAL EGRESOS</span><span>${d.totalExpenses.toFixed(2)}</span></div>
                     </div>
                  </div>
               </div>

               <div className="border-2 border-black p-6 flex justify-between items-center">
                  <p className="text-[11px] font-black uppercase tracking-widest">NETO A RECIBIR</p>
                  <p className="text-4xl font-black">${d.netToReceive.toFixed(2)}</p>
               </div>

               <div className="mt-20 grid grid-cols-2 gap-20 text-center text-[10px] font-black uppercase">
                  <div className="border-t border-black pt-2">Firma Colaborador</div>
                  <div className="border-t border-black pt-2">Firma Pagador</div>
               </div>

               <div className="flex flex-col sm:flex-row gap-3 no-print mt-10">
                 <button onClick={() => exportIndividualExcel(individualPayroll)} className="flex-1 py-4 bg-emerald-600 text-white font-black rounded-xl uppercase text-[10px] active:scale-95 shadow-md">Descargar Excel</button>
                 <button onClick={() => window.print()} className="flex-1 py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] active:scale-95 shadow-md">Descargar PDF (A4)</button>
               </div>
             </div>
           );
        })()}
      </Modal>

      <Modal isOpen={feedback.isOpen} onClose={() => setFeedback({...feedback, isOpen: false})} title={feedback.title} type={feedback.type}>
          <div className="text-center p-4">
              <p className="text-slate-600 font-bold uppercase text-[11px] mb-6">{feedback.message}</p>
              <button onClick={() => setFeedback({...feedback, isOpen: false})} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px]">Aceptar</button>
          </div>
      </Modal>
    </div>
  );
};

export default PayrollModule;

import React, { useState, useMemo, useEffect } from 'react';
import { Role, CompanyConfig, Employee, AttendanceRecord, Payment, GlobalSettings, NotificationMessage } from '../types.ts';
import Sidebar from '../components/Sidebar.tsx';
import CompanyModule from './modules/CompanyModule.tsx';
import EmployeeModule from './modules/EmployeeModule.tsx';
import PayrollModule from './modules/PayrollModule.tsx';
import PaymentsModule from './modules/PaymentsModule.tsx';
import SettingsModule from './modules/SettingsModule.tsx';
import ReportsModule from './modules/ReportsModule.tsx';
import AiAssistant from './modules/AiAssistant.tsx';
import NotificationsModule from './modules/NotificationsModule.tsx';
import Modal from '../components/Modal.tsx';
import { DAILY_QUOTES, ACTIVE_BREAKS, ECUADOR_HOLIDAYS } from '../constants.tsx';

interface AdminDashboardProps {
  role: Role;
  isDbConnected?: boolean;
  onLogout: () => void;
  company: CompanyConfig | null;
  onUpdateCompany: (config: CompanyConfig) => void;
  employees: Employee[];
  onUpdateEmployees: (employees: Employee[]) => void;
  attendance: AttendanceRecord[];
  payments: Payment[];
  onUpdatePayments: (payments: Payment[]) => void;
  settings: GlobalSettings;
  onUpdateSettings: (settings: GlobalSettings) => void;
  onUpdateAppMode: (mode: 'full' | 'attendance') => void;
  appMode: 'full' | 'attendance';
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  role, isDbConnected, onLogout, company, onUpdateCompany, employees, onUpdateEmployees, attendance, payments, onUpdatePayments, settings, onUpdateSettings, onUpdateAppMode, appMode 
}) => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'company' | 'employees' | 'payroll' | 'payments' | 'settings' | 'reports' | 'ai' | 'notifications'>('dashboard');
  const [showInstallModal, setShowInstallModal] = useState(false);
  const [notifications, setNotifications] = useState<NotificationMessage[]>([]);
  const [dismissedNotificationIds, setDismissedNotificationIds] = useState<Set<string>>(new Set());

  const today = useMemo(() => new Date(), []);
  const todayDateStr = useMemo(() => today.toISOString().split('T')[0], [today]);
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();

  const addNotification = (id: string, title: string, message: string, type: 'info' | 'alert' | 'critical') => {
    if (dismissedNotificationIds.has(id)) return;

    setNotifications(prev => {
      if (prev.some(n => n.id === id)) return prev;
      return [{ id, title, message, timestamp: new Date().toISOString(), type, isRead: false, isProcessed: false }, ...prev];
    });
  };

  useEffect(() => {
    if (currentYear < 2026 || (currentYear === 2026 && currentMonth < 1)) return;

    const activeEmployees = employees.filter(e => e.status === 'active');

    const markedTodayIds = new Set((attendance || [])
      .filter(a => a.timestamp.includes(todayDateStr))
      .map(a => a.employeeId));

    const missingAttendanceCount = activeEmployees.filter(e => !markedTodayIds.has(e.id)).length;
    if (missingAttendanceCount > 0 && activeTab === 'dashboard') {
      addNotification(
        `missing-attendance-${todayDateStr}`,
        "Marcaciones Pendientes", 
        `Hoy faltan ${missingAttendanceCount} registros de ingreso por completar.`, 
        'alert'
      );
    }

    activeEmployees.forEach(emp => {
      if (emp.birthDate) {
        const bDate = new Date(emp.birthDate);
        if (bDate.getMonth() === currentMonth) {
          addNotification(
            `birthday-remind-${emp.id}-${currentMonth}`,
            `Cumpleañero del Mes 🎂🎈`,
            `${emp.name} ${emp.surname} cumple años el ${bDate.getDate() + 1} de ${new Intl.DateTimeFormat('es-EC', {month: 'long'}).format(bDate)}.`,
            'info'
          );
        }
      }
    });
  }, [employees, attendance, todayDateStr, activeTab, dismissedNotificationIds, currentMonth, currentYear]);

  const unreadCount = notifications.filter(n => !n.isRead).length;

  const dayOfYear = useMemo(() => {
    const start = new Date(today.getFullYear(), 0, 0);
    const diff = today.getTime() - start.getTime();
    return Math.floor(diff / (1000 * 60 * 60 * 24));
  }, [today]);

  const dailyQuote = DAILY_QUOTES[dayOfYear % DAILY_QUOTES.length];
  const activeBreak = ACTIVE_BREAKS[dayOfYear % ACTIVE_BREAKS.length];

  const relaxingImages = [
    "https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&q=80&w=2070",
    "https://images.unsplash.com/photo-1441974231531-c6227db76b6e?auto=format&fit=crop&q=80&w=2071",
    "https://images.unsplash.com/photo-1579783902614-a3fb3927b6a5?auto=format&fit=crop&q=80&w=2070",
    "https://images.unsplash.com/photo-1541450805268-4822a3a774ce?auto=format&fit=crop&q=80&w=2070"
  ];
  const currentRelaxingImage = relaxingImages[dayOfYear % relaxingImages.length];

  const calendarDays = useMemo(() => {
    const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
    const firstDay = new Date(currentYear, currentMonth, 1).getDay();
    const days = [];
    for (let i = 0; i < firstDay; i++) days.push(null);
    for (let i = 1; i <= daysInMonth; i++) days.push(i);
    return days;
  }, [currentMonth, currentYear]);

  const monthHolidays = useMemo(() => {
    const standard = ECUADOR_HOLIDAYS.filter(h => h.month === currentMonth).map(h => ({ day: h.day, name: h.name }));
    const custom = (settings.holidays || [])
      .filter(dateStr => {
        const d = new Date(dateStr + 'T00:00:00');
        return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
      })
      .map(dateStr => ({
        day: new Date(dateStr + 'T00:00:00').getDate(),
        name: "Feriado Institucional"
      }));
    return [...standard, ...custom].sort((a, b) => a.day - b.day);
  }, [currentMonth, currentYear, settings.holidays]);

  const monthBirthdays = employees.filter(e => {
    if (!e.birthDate || e.status !== 'active') return false;
    return new Date(e.birthDate).getMonth() === currentMonth;
  });

  const handlePurgeData = async () => {
    if (role !== Role.SUPER_ADMIN) return;
    onUpdateEmployees([]);
    onUpdatePayments([]);
  };

  return (
    <div className="flex h-screen bg-[#fcfdfe] overflow-hidden flex-col md:flex-row">
      <Sidebar 
        role={role} 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        onLogout={onLogout} 
        companyName={company?.name} 
        unreadCount={unreadCount}
      />

      <main className="flex-1 overflow-y-auto px-4 md:px-8 py-4 md:py-8 scroll-smooth custom-scroll">
        <header className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4 no-print pt-14 md:pt-0">
          <div className="flex flex-col sm:flex-row items-start sm:items-center gap-3 w-full md:w-auto">
            <h1 className="text-3xl md:text-4xl font-[950] text-slate-900 tracking-tight uppercase leading-none italic">Management Hub</h1>
            <div className="flex items-center gap-2 px-4 py-2 bg-white border-2 border-slate-100 rounded-full shadow-sm w-fit">
               <div className={`w-3 h-3 rounded-full ${isDbConnected ? 'bg-emerald-500 animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.5)]' : 'bg-red-500 shadow-[0_0_8px_rgba(239,68,68,0.5)]'}`}></div>
               <span className="text-[12px] font-black uppercase tracking-[0.2em] text-slate-500">{isDbConnected ? 'Sincronizado' : 'Modo Offline'}</span>
            </div>
          </div>
        </header>

        <div className="animate-in fade-in duration-500 pb-20 md:pb-0">
          {activeTab === 'dashboard' && (
            <div className="space-y-8">
              <div className="relative overflow-hidden bg-slate-900 rounded-[3.5rem] p-12 md:p-16 text-white shadow-xl min-h-[250px] flex items-center bg-cover bg-center" style={{ backgroundImage: `linear-gradient(rgba(15, 23, 42, 0.7), rgba(15, 23, 42, 0.7)), url(${currentRelaxingImage})` }}>
                  <div className="relative z-10 w-full">
                    <p className="text-blue-400 font-black text-[14px] md:text-[16px] uppercase tracking-[0.5em] mb-6 md:mb-8">Estrategia & Visión Diaria</p>
                    <h2 className="text-2xl md:text-5xl font-[900] leading-tight tracking-tighter italic max-w-5xl">"{dailyQuote}"</h2>
                  </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-10">

                <div className="bg-white p-10 rounded-[3.5rem] border border-slate-100 shadow-sm flex flex-col min-h-[480px]">
                   <div className="flex justify-between items-center mb-10">
                      <div>
                        <h3 className="text-[14px] font-black text-slate-900 uppercase tracking-widest leading-none mb-3">Calendario Corporativo</h3>
                        <p className="text-[13px] text-slate-400 font-bold uppercase tracking-widest">{new Intl.DateTimeFormat('es-EC', { month: 'long', year: 'numeric' }).format(today)}</p>
                      </div>
                      <div className="flex gap-6">
                         <span className="flex items-center gap-2 text-[12px] font-black text-blue-600 uppercase"><div className="w-2.5 h-2.5 bg-blue-500 rounded-full"></div> Feriado</span>
                         <span className="flex items-center gap-2 text-[12px] font-black text-emerald-600 uppercase"><div className="w-2.5 h-2.5 bg-emerald-500 rounded-full"></div> Cumple</span>
                      </div>
                   </div>
                   <div className="grid grid-cols-7 gap-3 text-center flex-1 items-center">
                      {['D', 'L', 'M', 'M', 'J', 'V', 'S'].map(d => (
                        <div key={d} className="text-[13px] font-black text-slate-300 uppercase py-3">{d}</div>
                      ))}
                      {calendarDays.map((day, i) => {
                        const isHoliday = day && monthHolidays.some(h => h.day === day);
                        const isBirthday = day && monthBirthdays.some(e => new Date(e.birthDate).getDate() + 1 === day);
                        const isToday = day === today.getDate();

                        return (
                          <div key={i} className={`
                            relative aspect-square flex items-center justify-center text-[14px] font-black rounded-3xl transition-all
                            ${!day ? 'opacity-0' : 'hover:bg-slate-50 cursor-pointer'}
                            ${isToday ? 'bg-slate-900 text-white shadow-xl scale-110' : 'text-slate-600'}
                            ${isHoliday ? 'text-blue-600 bg-blue-50/50' : ''}
                            ${isBirthday ? 'text-emerald-600 bg-emerald-50/50' : ''}
                          `}>
                            {day}
                            {(isHoliday || isBirthday) && <div className={`absolute bottom-2 w-2 h-2 rounded-full ${isHoliday ? 'bg-blue-600' : 'bg-emerald-600'}`}></div>}
                          </div>
                        );
                      })}
                   </div>
                </div>

                <div className="bg-slate-50 p-10 rounded-[3.5rem] border border-slate-100 flex flex-col min-h-[480px]">
                   <h3 className="text-[14px] font-black text-slate-400 uppercase tracking-widest border-b-2 border-slate-200 pb-5 mb-8">Agenda de Novedades</h3>
                   <div className="space-y-4 overflow-y-auto custom-scroll flex-1 pr-3">
                      {monthHolidays.map((h, i) => (
                         <div key={i} className="flex gap-5 items-center bg-white p-6 rounded-3xl border border-slate-200/50 shadow-sm">
                            <div className="w-12 h-12 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center text-2xl">📅</div>
                            <div>
                               <p className="text-[13px] font-black text-slate-900 uppercase leading-none">{h.name}</p>
                               <p className="text-[11px] font-black text-blue-500 uppercase mt-3">Día {h.day}</p>
                            </div>
                         </div>
                      ))}
                      {monthBirthdays.map((e, i) => (
                         <div key={i} className="flex gap-5 items-center bg-white p-6 rounded-3xl border border-slate-200/50 shadow-sm">
                            <div className="w-12 h-12 rounded-2xl overflow-hidden border bg-slate-100 flex items-center justify-center text-[14px] font-black uppercase">
                               {e.photo ? <img src={e.photo} className="w-full h-full object-cover" /> : <span className="text-slate-400">{e.name[0]}</span>}
                            </div>
                            <div>
                               <p className="text-[13px] font-black text-slate-900 uppercase leading-none">{e.surname} {e.name}</p>
                               <p className="text-[11px] font-black text-emerald-500 uppercase mt-3">Natalicio • Día {new Date(e.birthDate).getDate() + 1}</p>
                            </div>
                         </div>
                      ))}
                      {monthHolidays.length === 0 && monthBirthdays.length === 0 && (
                        <div className="h-full flex flex-col items-center justify-center py-20 opacity-30">
                          <span className="text-6xl mb-6">🍃</span>
                          <p className="text-[13px] text-slate-400 font-black uppercase tracking-widest">Sin eventos próximos</p>
                        </div>
                      )}
                   </div>
                </div>

                <div className="bg-white p-10 rounded-[3.5rem] border border-slate-100 flex flex-col justify-between shadow-sm min-h-[250px]">
                  <div className="flex items-center gap-6 mb-6">
                    <div className="w-16 h-16 bg-blue-50 text-blue-600 rounded-3xl flex items-center justify-center text-4xl shadow-inner">
                      {activeBreak.icon}
                    </div>
                    <div>
                      <h3 className="text-[14px] font-black text-slate-900 uppercase tracking-widest leading-none">Cultura & Bienestar</h3>
                      <p className="text-[12px] font-black text-blue-600 uppercase tracking-widest mt-3">Pausa Activa Sugerida</p>
                    </div>
                  </div>
                  <div className="bg-slate-50 p-8 rounded-[2.5rem] border border-slate-100/50 flex-1 flex flex-col justify-center">
                    <h4 className="text-[13px] font-black text-slate-800 uppercase mb-3 flex items-center gap-3">
                      <span className="w-2.5 h-2.5 bg-blue-500 rounded-full animate-pulse"></span>
                      {activeBreak.title}
                    </h4>
                    <p className="text-slate-500 text-[15px] leading-relaxed font-medium italic">"{activeBreak.description}"</p>
                  </div>
                </div>

                <div className="relative overflow-hidden bg-slate-200 rounded-[3.5rem] shadow-sm border border-slate-100 min-h-[250px]">
                   <img 
                     src={currentRelaxingImage} 
                     alt="Workspace" 
                     className="w-full h-full object-cover transition-transform duration-[20s] hover:scale-110"
                   />
                   <div className="absolute inset-0 bg-gradient-to-t from-slate-950/80 via-slate-900/10 to-transparent flex items-end p-10">
                      <div>
                        <p className="text-[12px] font-black text-blue-400 uppercase tracking-[0.4em] mb-3">Visión Institucional</p>
                        <p className="text-white text-[16px] font-bold uppercase tracking-widest leading-tight italic">Excelencia en la gestión del capital humano ecuatoriano</p>
                      </div>
                   </div>
                </div>

              </div>
            </div>
          )}

          {activeTab === 'notifications' && (
            <NotificationsModule 
              notifications={notifications} 
              onToggleRead={(id) => setNotifications(prev => prev.map(n => n.id === id ? {...n, isRead: !n.isRead} : n))}
              onToggleProcessed={(id) => setNotifications(prev => prev.map(n => n.id === id ? {...n, isProcessed: !n.isProcessed} : n))}
              onClearAll={() => {
                const allIds = notifications.map(n => n.id);
                setDismissedNotificationIds(prev => new Set([...prev, ...allIds]));
                setNotifications([]);
              }}
            />
          )}

          {activeTab === 'company' && <CompanyModule company={company} onUpdate={onUpdateCompany} role={role} />}
          {activeTab === 'employees' && <EmployeeModule employees={employees} onUpdate={onUpdateEmployees} role={role} attendance={attendance} payments={payments} company={company} />}
          {activeTab === 'payroll' && <PayrollModule employees={employees} payments={payments} onUpdatePayments={onUpdatePayments} onUpdateEmployees={onUpdateEmployees} attendance={attendance} company={company} settings={settings} role={role} />}
          {activeTab === 'payments' && <PaymentsModule employees={employees} payments={payments} onUpdate={onUpdatePayments} role={role} company={company} />}
          {activeTab === 'settings' && <SettingsModule settings={settings} onUpdate={onUpdateSettings} role={role} onPurge={handlePurgeData} allData={{ company, employees, attendance, payments, settings }} />}
          {activeTab === 'reports' && <ReportsModule employees={employees} payments={payments} attendance={attendance} company={company} settings={settings} role={role} />}
          {activeTab === 'ai' && <AiAssistant employees={employees} attendance={attendance} payments={payments} role={role} />}
        </div>
      </main>

      <Modal isOpen={showInstallModal} onClose={() => setShowInstallModal(false)} title="Estación de Trabajo" maxWidth="max-w-md">
         <div className="space-y-4">
            <p className="text-[13px] text-slate-500 text-center font-bold uppercase tracking-widest leading-none">Seleccione modo de funcionamiento</p>
            <div className="grid grid-cols-1 gap-3">
               <button onClick={() => { onUpdateAppMode('full'); setShowInstallModal(false); }} className={`p-8 rounded-2xl border-2 text-left transition-all ${appMode === 'full' ? 'border-blue-600 bg-blue-50' : 'border-slate-100'}`}>
                  <p className="font-black text-base text-slate-900 uppercase">Administrativo Full</p>
                  <p className="text-[13px] text-slate-400 font-bold uppercase mt-3">Gestión completa del sistema institucional.</p>
               </button>
               <button onClick={() => { onUpdateAppMode('attendance'); setShowInstallModal(false); }} className={`p-8 rounded-2xl border-2 text-left transition-all ${appMode === 'attendance' ? 'border-blue-600 bg-blue-50' : 'border-slate-100'}`}>
                  <p className="font-black text-base text-slate-900 uppercase">Kiosco de Asistencia</p>
                  <p className="text-[13px] text-slate-400 font-bold uppercase mt-3">Solo marcación para personal operativo.</p>
               </button>
            </div>
         </div>
      </Modal>
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useEffect, useRef } from 'react';
import { CompanyConfig, Employee, Role, AttendanceRecord, Payment, GlobalSettings } from './types.ts';
import AdminDashboard from './views/AdminDashboard.tsx';
import AttendanceSystem from './views/AttendanceSystem.tsx';
import Modal from './components/Modal.tsx';
import { db, collection, doc, onSnapshot, setDoc, addDoc, deleteDoc, compressData, decompressData } from './firebase.ts';

const App: React.FC = () => {
  const [currentUserRole, setCurrentUserRole] = useState<Role | null>(null);
  const [view, setView] = useState<'selection' | 'admin' | 'attendance' | 'setup'>('selection');
  const [isLoadingData, setIsLoadingData] = useState(true);
  const [isDbConnected, setIsDbConnected] = useState(false);
  const [isAdminLoginModalOpen, setIsAdminLoginModalOpen] = useState(false);
  const [adminPassInput, setAdminPassInput] = useState('');

  // Estados para recuperación de emergencia
  const [isRecoveryMode, setIsRecoveryMode] = useState(false);
  const [recoveryRuc, setRecoveryRuc] = useState('');
  const [recoveryKey, setRecoveryKey] = useState('');

  const unsubscribesRef = useRef<(() => void)[]>([]);

  const [appMode, setAppMode] = useState<'full' | 'attendance' | null>(
    (localStorage.getItem('app_mode') as 'full' | 'attendance') || null
  );

  const [showLogoutFeedback, setShowLogoutFeedback] = useState(false);
  const [modalAlert, setModalAlert] = useState<{isOpen: boolean, title: string, message: string, type: 'info' | 'success' | 'error'}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  const [company, setCompany] = useState<CompanyConfig | null>(null);
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);
  const [payments, setPayments] = useState<Payment[]>([]);

  const defaultSettings: GlobalSettings = {
    sbu: 482.00,
    iessRate: 0.0945,
    reserveRate: 0.0833,
    holidays: [],
    schedule: {
      monFri: { in1: '08:30', out1: '13:00', in2: '15:00', out2: '18:00' },
      sat: { in: '08:30', out: '13:00' },
      halfDayOff: 'Miércoles tarde'
    }
  };

  const [settings, setSettings] = useState<GlobalSettings>(defaultSettings);

  useEffect(() => {
    if (!appMode) {
      setView('setup');
    }
  }, [appMode]);

  const handleSetDeviceMode = (mode: 'full' | 'attendance') => {
    localStorage.setItem('app_mode', mode);
    setAppMode(mode);
    setView('selection');
  };

  const showAlert = (title: string, message: string, type: 'info' | 'success' | 'error' = 'info') => {
    setModalAlert({ isOpen: true, title, message, type });
  };

  const cleanListeners = () => {
    unsubscribesRef.current.forEach(unsub => unsub());
    unsubscribesRef.current = [];
  };

  useEffect(() => {
    if ("Notification" in window) {
      Notification.requestPermission();
    }

    const handleEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        setIsAdminLoginModalOpen(false);
        setIsRecoveryMode(false);
        setModalAlert(prev => ({ ...prev, isOpen: false }));
      }
    };
    window.addEventListener('keydown', handleEsc);

    cleanListeners();

    try {
      const unsubCompany = onSnapshot(doc(db, "config", "company"), (docSnap) => {
        if (docSnap.exists()) {
          const data = docSnap.data();
          setCompany(data.payload ? decompressData(data.payload as string) : data as any);
        }
        setIsDbConnected(true);
        setIsLoadingData(false);
      }, () => setIsDbConnected(false));
      unsubscribesRef.current.push(unsubCompany);

      const unsubSettings = onSnapshot(doc(db, "config", "settings"), (docSnap) => {
        if (docSnap.exists()) {
          const data = docSnap.data();
          const dbSettings = data.payload ? decompressData(data.payload as string) : data as any;
          setSettings({
            ...defaultSettings,
            ...dbSettings,
            schedule: {
              ...defaultSettings.schedule,
              ...(dbSettings.schedule || {}),
              monFri: {
                ...defaultSettings.schedule.monFri,
                ...(dbSettings.schedule?.monFri || {})
              },
              sat: {
                ...defaultSettings.schedule.sat,
                ...(dbSettings.schedule?.sat || {})
              }
            }
          });
        }
      });
      unsubscribesRef.current.push(unsubSettings);

      const unsubEmployees = onSnapshot(collection(db, "employees"), (snapshot) => {
        setEmployees(snapshot.docs.map(d => {
          const raw = d.data();
          return raw.payload ? { ...decompressData(raw.payload as string), id: d.id } : { ...raw, id: d.id };
        }) as Employee[]);
      });
      unsubscribesRef.current.push(unsubEmployees);

      const unsubAttendance = onSnapshot(collection(db, "attendance"), (snapshot) => {
        setAttendance(snapshot.docs.map(d => {
          const raw = d.data();
          return raw.payload ? { ...decompressData(raw.payload as string), id: d.id } : { ...raw, id: d.id };
        }) as AttendanceRecord[]);
      });
      unsubscribesRef.current.push(unsubAttendance);

      const unsubPayments = onSnapshot(collection(db, "payments"), (snapshot) => {
        setPayments(snapshot.docs.map(d => {
          const raw = d.data();
          return raw.payload ? { ...decompressData(raw.payload as string), id: d.id } : { ...raw, id: d.id };
        }) as Payment[]);
      });
      unsubscribesRef.current.push(unsubPayments);

    } catch (e) {
      setIsLoadingData(false);
    }

    return () => {
      window.removeEventListener('keydown', handleEsc);
      cleanListeners();
    };
  }, []);

  const handleAdminLogin = () => {
    let role: Role | null = null;
    if (adminPassInput === 'admin123') role = Role.SUPER_ADMIN;
    else {
      const foundAdmin = employees.find(e => e.pin === adminPassInput && (e.role === Role.SUPER_ADMIN || e.role === Role.PARTIAL_ADMIN));
      if (foundAdmin) role = foundAdmin.role;
    }

    if (role) {
      setCurrentUserRole(role);
      localStorage.setItem('admin_logged_in', 'true');
      setView('admin');
      setIsAdminLoginModalOpen(false);
    } else {
      showAlert("Error de Acceso", "Credencial no válida o sin privilegios.", "error");
    }
    setAdminPassInput('');
  };

  const handleEmergencyRecovery = () => {
    const MASTER_RECOVERY_KEY = "ASISTUP-MASTER-ACCESS-2026";
    if (recoveryRuc === company?.ruc && recoveryKey === MASTER_RECOVERY_KEY) {
      setCurrentUserRole(Role.SUPER_ADMIN);
      localStorage.setItem('admin_logged_in', 'true');
      setView('admin');
      setIsAdminLoginModalOpen(false);
      setIsRecoveryMode(false);
      setRecoveryRuc('');
      setRecoveryKey('');
    } else {
      showAlert("Fallo de Autenticación", "Los datos de recuperación de emergencia son incorrectos.", "error");
    }
  };

  const finalizeLogout = () => {
    setCurrentUserRole(null);
    localStorage.removeItem('admin_logged_in');
    setView('selection');
    setShowLogoutFeedback(false);
  };

  useEffect(() => {
    if (showLogoutFeedback) {
      const timer = setTimeout(() => {
        finalizeLogout();
      }, 1500);
      return () => clearTimeout(timer);
    }
  }, [showLogoutFeedback]);

  const handleUpdateEmployees = async (emps: Employee[]) => {
    const currentIds = new Set<string>(emps.map(e => e.id));
    const previousIds = new Set<string>(employees.map(e => e.id));
    for (const id of previousIds) {
      if (!currentIds.has(id)) {
        await deleteDoc(doc(db, "employees", id));
      }
    }
    for (const e of emps) {
      await setDoc(doc(db, "employees", e.id), { payload: compressData(e) });
    }
  };

  const handleUpdatePayments = async (pys: Payment[]) => {
    const currentIds = new Set<string>(pys.map(p => p.id));
    const previousIds = new Set<string>(payments.map(p => p.id));
    for (const id of previousIds) {
      if (!currentIds.has(id)) {
        await deleteDoc(doc(db, "payments", id));
      }
    }
    for (const p of pys) {
      if (p.id.length > 15) {
        await addDoc(collection(db, "payments"), { payload: compressData(p) });
      } else {
        await setDoc(doc(db, "payments", p.id), { payload: compressData(p) });
      }
    }
  };

  if (isLoadingData) return null;

  return (
    <div className="min-h-screen bg-[#f8fafc]">
      {view === 'setup' && (
        <div className="min-h-screen gradient-blue flex flex-col items-center justify-center p-6">
          <div className="w-full max-w-lg bg-white/95 backdrop-blur-3xl p-10 md:p-16 rounded-[4rem] shadow-2xl text-center border border-white/20 fade-in">
            <h2 className="text-3xl font-[950] text-slate-900 mb-2 tracking-tighter uppercase leading-none">CONFIGURACIÓN INICIAL</h2>
            <p className="text-blue-600 font-black uppercase tracking-[0.4em] text-[9px] mb-12">Defina el tipo de instalación para este equipo</p>

            <div className="space-y-4">
              <button 
                onClick={() => handleSetDeviceMode('full')}
                className="w-full group p-6 border-2 border-slate-100 hover:border-blue-600 rounded-[2.5rem] bg-slate-50 transition-all text-left flex items-center gap-5 active:scale-95"
              >
                <div className="w-12 h-12 bg-blue-600 text-white rounded-2xl flex items-center justify-center text-xl shrink-0 group-hover:scale-110 transition-transform">🖥️</div>
                <div>
                   <p className="font-black text-slate-900 text-xs uppercase tracking-tight">Administración Completa</p>
                   <p className="text-[9px] text-slate-400 font-bold uppercase mt-1">Acceso a todos los módulos y reportes.</p>
                </div>
              </button>

              <button 
                onClick={() => handleSetDeviceMode('attendance')}
                className="w-full group p-6 border-2 border-slate-100 hover:border-emerald-600 rounded-[2.5rem] bg-slate-50 transition-all text-left flex items-center gap-5 active:scale-95"
              >
                <div className="w-12 h-12 bg-emerald-600 text-white rounded-2xl flex items-center justify-center text-xl shrink-0 group-hover:scale-110 transition-transform">🕒</div>
                <div>
                   <p className="font-black text-slate-900 text-xs uppercase tracking-tight">Terminal de Asistencia (Kiosco)</p>
