import React, { useState } from 'react';
import { Employee, Payment, CompanyConfig, GlobalSettings, Role } from '../../types.ts';
import Modal from '../../components/Modal.tsx';

interface PayrollModuleProps {
  employees: Employee[];
  payments: Payment[];
  onUpdatePayments?: (payments: Payment[]) => void;
  onUpdateEmployees?: (employees: Employee[]) => void;
  attendance: any[];
  company: CompanyConfig | null;
  settings: GlobalSettings;
  role: Role;
}

const PayrollModule: React.FC<PayrollModuleProps> = ({ employees, payments, onUpdatePayments, onUpdateEmployees, attendance = [], company, settings, role }) => {
  const [selectedMonth, setSelectedMonth] = useState('FEBRERO');
  const [individualPayroll, setIndividualPayroll] = useState<Employee | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [editingEmployee, setEditingEmployee] = useState<Employee | null>(null);
  const [feedback, setFeedback] = useState({ isOpen: false, title: '', message: '', type: 'success' as any });
  const [showConfirmPayrollEdit, setShowConfirmPayrollEdit] = useState(false);

  const [adjustments, setAdjustments] = useState({
    extraHours: 0, bonuses: 0, vacation: 0, incomeConcept: '',
    loans: 0, backPay: 0, expenseConcept: '',
    thirteenth: 0, fourteenth: 0, reserve: 0
  });

  const monthMap: { [key: string]: number } = {
    'ENERO': 0, 'FEBRERO': 1, 'MARZO': 2, 'ABRIL': 3, 'MAYO': 4, 'JUNIO': 5,
    'JULIO': 6, 'AGOSTO': 7, 'SEPTIEMBRE': 8, 'OCTUBRE': 9, 'NOVIEMBRE': 10, 'DICIEMBRE': 11
  };

  const isJanuary2026 = selectedMonth === 'ENERO';

  const calculatePayrollData = (emp: Employee, index: number) => {
    if (isJanuary2026) return {
      baseSalary: 0, extraHours: 0, reserveFund: 0, monthly13th: 0, monthly14th: 0, otherIncomes: 0,
      iessContribution: 0, multas: 0, advances: 0, otherDiscounts: 0, netToReceive: 0, workedDays: 0, expectedDays: 0
    };

    const monthIndex = monthMap[selectedMonth] ?? 0;
    const year = 2026;

    let expectedDays = 0;
    const daysInMonth = new Date(year, monthIndex + 1, 0).getDate();
    for (let d = 1; d <= daysInMonth; d++) {
      const date = new Date(year, monthIndex, d);
      const dayOfWeek = date.getDay();
      if (dayOfWeek >= 1 && dayOfWeek <= 6) expectedDays++;
    }

    const empAttendance = (attendance || []).filter(a => {
      const d = new Date(a.timestamp);
      return a.employeeId === emp.id && d.getMonth() === monthIndex && d.getFullYear() === year && a.status === 'confirmed';
    });

    const attendanceByDate: { [key: string]: { ins: number, half: number, isHoliday: boolean } } = {};
    empAttendance.forEach(a => {
      const dateStr = a.timestamp.split('T')[0];
      if (!attendanceByDate[dateStr]) {
        attendanceByDate[dateStr] = { ins: 0, half: 0, isHoliday: (settings.holidays || []).includes(dateStr) };
      }
      if (a.type === 'in') attendanceByDate[dateStr].ins++;
      if (a.type === 'half_day') attendanceByDate[dateStr].half++;
    });

    let workedDays = 0;
    let holidayDaysWorked = 0;
    Object.entries(attendanceByDate).forEach(([dateStr, day]) => {
      let dayVal = 0;
      if (day.ins >= 2) dayVal = 1.0;
      else if (day.ins === 1 || day.half > 0) dayVal = 0.5;
      workedDays += dayVal;
      if (day.isHoliday) holidayDaysWorked += dayVal;
    });

    const justifiedAbsences = (emp.absences || []).filter(a => {
      const d = new Date(a.date);
      return d.getMonth() === monthIndex && d.getFullYear() === year && a.type === 'Falta' && a.justified;
    }).length;

    workedDays = Math.min(expectedDays, workedDays + justifiedAbsences);
    const attendanceProportion = expectedDays > 0 ? workedDays / expectedDays : 0;
    const earnedBase = emp.salary * attendanceProportion;
    const holidaySurcharge = (emp.salary / 30) * holidayDaysWorked;

    const monthlyPayments = payments.filter(p => p.employeeId === emp.id && p.month === selectedMonth && p.status === 'paid');
    const bonuses = monthlyPayments.filter(p => p.type === 'Bonus').reduce((sum, p) => sum + p.amount, 0);
    const extraHours = monthlyPayments.filter(p => p.type === 'ExtraHours').reduce((sum, p) => sum + p.amount, 0);
    const vacation = monthlyPayments.filter(p => p.type === 'Vacation').reduce((sum, p) => sum + p.amount, 0);
    const adj13 = monthlyPayments.filter(p => p.type === 'Thirteenth').reduce((sum, p) => sum + p.amount, 0);
    const adj14 = monthlyPayments.filter(p => p.type === 'Fourteenth').reduce((sum, p) => sum + p.amount, 0);
    const adjRes = monthlyPayments.filter(p => p.type === 'Salary' && p.concept.includes('RESERVA')).reduce((sum, p) => sum + p.amount, 0);

    const isMonthly = emp.overSalaryType === 'monthly';
    const isAffiliated = emp.isAffiliated;
    const taxableIncome = earnedBase + extraHours + bonuses + holidaySurcharge;
    const monthly13th = ((isAffiliated && isMonthly) ? (taxableIncome) / 12 : 0) + adj13;
    const monthly14th = ((isAffiliated && isMonthly) ? (settings.sbu / 12) * attendanceProportion : 0) + adj14;
    const reserveFund = ((isAffiliated && isMonthly) ? (taxableIncome * settings.reserveRate) : 0) + adjRes;

    const iessContribution = isAffiliated ? (taxableIncome * settings.iessRate) : 0;
    const advances = monthlyPayments.filter(p => p.type === 'Advance' || p.type === 'Loan' || p.type === 'Emergency').reduce((sum, p) => sum + p.amount, 0);
    const backPay = monthlyPayments.filter(p => p.type === 'BackPay').reduce((sum, p) => sum + p.amount, 0);

    const otherIncomes = bonuses + holidaySurcharge + vacation;
    const totalIncomes = earnedBase + extraHours + reserveFund + monthly13th + monthly14th + otherIncomes;
    const totalExpenses = iessContribution + advances + backPay; // multas = 0
    const netToReceive = totalIncomes - totalExpenses;

    return { 
      baseSalary: earnedBase, // Total Ganado
      extraHours, // Horas Suplementarias/Extras
      reserveFund, // Fondos de Reserva
      monthly13th, // Décimo Tercero Mensualizado
      monthly14th, // Décimo Cuarto Mensualizado
      otherIncomes, // Otros Ingresos
      iessContribution, // Aporte Personal IESS 9.45%
      multas: 0, // Multas (Concepto informativo)
      advances, // Anticipos
      otherDiscounts: backPay, // Otros Descuentos
      netToReceive, // Neto a Recibir
      workedDays, 
      expectedDays
    };
  };

  const exportGeneralExcel = () => {
    let csv = "\uFEFFColaborador,Identificación,Días Trabajados,Total Ganado,Horas Suplementarias/Extras,Fondos de Reserva,Décimo Tercero Mens.,Décimo Cuarto Mens.,Otros Ingresos,IESS 9.45%,Multas,Anticipos,Otros Descuentos,Neto Recibir\n";
    filteredEmployees.filter(e => e.status === 'active').forEach((emp, idx) => {
      const d = calculatePayrollData(emp, idx);
      csv += `"${emp.surname} ${emp.name}","${emp.identification}","${d.workedDays}","${d.baseSalary.toFixed(2)}","${d.extraHours.toFixed(2)}","${d.reserveFund.toFixed(2)}","${d.monthly13th.toFixed(2)}","${d.monthly14th.toFixed(2)}","${d.otherIncomes.toFixed(2)}","${d.iessContribution.toFixed(2)}","${d.multas.toFixed(2)}","${d.advances.toFixed(2)}","${d.otherDiscounts.toFixed(2)}","${d.netToReceive.toFixed(2)}"\n`;
    });
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `ROL_GENERAL_${selectedMonth}_2026.csv`;
    link.click();
  };

  const exportIndividualExcel = (emp: Employee) => {
    const d = calculatePayrollData(emp, 0);
    let csv = "\uFEFFROL DE PAGOS INDIVIDUAL - 2026\n";
    csv += `"COLABORADOR","${emp.surname} ${emp.name}"\n`;
    csv += `"CEDULA","${emp.identification}"\n`;
    csv += `"PERIODO","${selectedMonth}"\n`;
    csv += `"\n`;
    csv += `"DETALLE DE INGRESOS","VALOR"\n`;
    csv += `"Total Ganado","${d.baseSalary.toFixed(2)}"\n`;
    csv += `"Horas Suplementarias/Extras","${d.extraHours.toFixed(2)}"\n`;
    csv += `"Fondos de Reserva","${d.reserveFund.toFixed(2)}"\n`;
    csv += `"Décimo Tercero Mens.","${d.monthly13th.toFixed(2)}"\n`;
    csv += `"Décimo Cuarto Mens.","${d.monthly14th.toFixed(2)}"\n`;
    csv += `"Otros Ingresos","${d.otherIncomes.toFixed(2)}"\n`;
    csv += `"TOTAL INGRESOS","${(d.baseSalary + d.extraHours + d.reserveFund + d.monthly13th + d.monthly14th + d.otherIncomes).toFixed(2)}"\n`;
    csv += `"\n`;
    csv += `"DETALLE DE EGRESOS","VALOR"\n`;
    csv += `"IESS 9.45%","${d.iessContribution.toFixed(2)}"\n`;
    csv += `"Multas","${d.multas.toFixed(2)}"\n`;
    csv += `"Anticipos","${d.advances.toFixed(2)}"\n`;
    csv += `"Otros Descuentos","${d.otherDiscounts.toFixed(2)}"\n`;
    csv += `"TOTAL EGRESOS","${(d.iessContribution + d.multas + d.advances + d.otherDiscounts).toFixed(2)}"\n`;
    csv += `"\n`;
    csv += `"NETO A RECIBIR","${d.netToReceive.toFixed(2)}"\n`;

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `ROL_${emp.identification}_${selectedMonth}.csv`;
    link.click();
  };

  const filteredEmployees = employees.filter(e => {
    const searchStr = `${e.name} ${e.surname} ${e.identification} ${e.role}`.toLowerCase();
    return searchStr.includes(searchTerm.toLowerCase());
  });

  return (
    <div className="space-y-6 md:space-y-8 fade-in">
      <div className="flex flex-col md:flex-row justify-between items-center bg-white p-6 rounded-3xl md:rounded-[2rem] shadow-sm border border-slate-100 no-print gap-6">
        <div className="w-full">
          <h2 className="text-xl font-black text-slate-900 uppercase">Control Detallado de Nómina</h2>
          <div className="flex flex-col sm:flex-row gap-4 mt-4">
             <select className="p-3 border rounded-xl text-[11px] font-black uppercase outline-none focus:border-blue-500" value={selectedMonth} onChange={e => setSelectedMonth(e.target.value)}>
                {['ENERO','FEBRERO','MARZO','ABRIL','MAYO','JUNIO','JULIO','AGOSTO','SEPTIEMBRE','OCTUBRE','NOVIEMBRE','DICIEMBRE'].map(m => <option key={m} value={m}>{m}</option>)}
             </select>
             <input type="text" placeholder="Buscar colaborador..." className="flex-1 p-3 border rounded-xl text-[11px] font-bold uppercase outline-none focus:border-blue-500" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
          </div>
        </div>
        <div className="flex flex-wrap gap-2 justify-center md:justify-end">
           <button onClick={exportGeneralExcel} className="px-6 py-4 bg-emerald-600 text-white font-black rounded-xl uppercase text-[10px] tracking-widest active:scale-95 shadow-lg">Excel General</button>
           <button onClick={() => window.print()} className="px-6 py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] tracking-widest active:scale-95 shadow-lg">PDF General</button>
        </div>
      </div>

      {isJanuary2026 ? (
        <div className="bg-white p-24 rounded-[3rem] border-2 border-dashed border-slate-200 text-center">
          <span className="text-6xl opacity-30">⏳</span>
          <h3 className="text-xl font-black text-slate-900 uppercase tracking-tighter mt-8">Periodo No Operativo</h3>
          <p className="text-[12px] text-slate-500 font-bold uppercase tracking-widest mt-4">Nómina disponible desde Febrero 2026.</p>
