import React, { useState } from 'react';
import { Employee, Payment, AttendanceRecord, CompanyConfig, GlobalSettings, Role } from '../../types.ts';
import { db, doc, setDoc, deleteDoc, compressData } from '../../firebase.ts';
import Modal from '../../components/Modal.tsx';

interface ReportsModuleProps {
  employees: Employee[];
  payments: Payment[];
  attendance: AttendanceRecord[];
  company: CompanyConfig | null;
  settings: GlobalSettings;
  role: Role;
}

const ReportsModule: React.FC<ReportsModuleProps> = ({ employees, payments = [], attendance = [], company, settings, role }) => {
  const [reportType, setReportType] = useState<'attendance' | 'payments' | 'validation' | 'history'>('attendance');
  const [searchTerm, setSearchTerm] = useState('');
  const [feedback, setFeedback] = useState({ isOpen: false, title: '', message: '', type: 'success' as any });

  const exportMasterFile = () => {
    // Generamos un "Archivo Maestro" consolidado que actúa como base de datos cronológica
    let csv = "\uFEFFARCHIVO MAESTRO INSTITUCIONAL - " + new Date().getFullYear() + "\n";
    csv += `ENTIDAD,"${company?.name || 'ASIST UP'}"\n`;
    csv += `RUC,"${company?.ruc || '—'}"\n`;
    csv += `GENERADO,"${new Date().toLocaleString()}"\n\n`;

    csv += `--- REGISTRO MAESTRO DE COLABORADORES ---\n`;
    csv += `IDENTIFICACION,APELLIDOS Y NOMBRES,CARGO,FECHA INGRESO,ESTADO,SALARIO\n`;
    employees.forEach(e => {
       csv += `"${e.identification}","${e.surname} ${e.name}","${e.role}","${e.startDate}","${e.status}","${e.salary.toFixed(2)}"\n`;
    });
    csv += `\n`;

    csv += `--- BITACORA DE ASISTENCIA Y NOVEDADES ---\n`;
    csv += `FECHA,ID COLABORADOR,NOMBRE,TIPO,ESTADO,ATRASO,JUSTIFICACION\n`;
    attendance.forEach(a => {
       const emp = employees.find(e => e.id === a.employeeId);
       csv += `"${new Date(a.timestamp).toLocaleString()}","${emp?.identification}","${emp?.surname} ${emp?.name}","${a.type}","${a.status}","${a.isLate ? 'SI' : 'NO'}","${a.justification || ''}"\n`;
    });
    csv += `\n`;

    csv += `--- HISTORIAL DE EGRESOS Y NOMINA ---\n`;
    csv += `CODIGO,FECHA,BENEFICIARIO,CONCEPTO,METODO,MONTO\n`;
    payments.forEach(p => {
       const emp = employees.find(e => e.id === p.employeeId);
       csv += `"${p.voucherCode}","${new Date(p.date).toLocaleDateString()}","${emp?.surname} ${emp?.name}","${p.type}","${p.method}","${p.amount.toFixed(2)}"\n`;
    });

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `ARCHIVO_MAESTRO_ASISTUP_${new Date().getMonth() + 1}_${new Date().getFullYear()}.csv`;
    link.click();

    setFeedback({ 
      isOpen: true, 
      title: "Archivo Maestro Generado", 
      message: "El consolidado institucional mensual ha sido archivado y descargado. Guarde este archivo en la carpeta cronológica correspondiente.", 
      type: "success" 
    });
  };

  const exportExcel = () => {
    let csv = "";
    if (reportType === 'payments') {
        csv = "\uFEFFCódigo,Fecha,Beneficiario,Identificación,Concepto,Detalle,Método,Monto\n";
        paymentsToDisplay.forEach(p => {
          const emp = employees.find(e => e.id === p.employeeId);
          csv += `"${p.voucherCode}","${new Date(p.date).toLocaleDateString()}","${emp?.surname} ${emp?.name}","${emp?.identification}","${p.type}","${p.concept}","${p.method}","${p.amount.toFixed(2)}"\n`;
        });
    } else if (reportType === 'history') {
        csv = "\uFEFFColaborador,Identificación,Cargo,F. Ingreso,F. Salida,Motivo,Novedades,Estado\n";
        historyToDisplay.forEach(emp => {
          csv += `"${emp.surname} ${emp.name}","${emp.identification}","${emp.role}","${emp.startDate}","${emp.terminationDate || 'N/A'}","${emp.terminationReason || 'N/A'}","${emp.absences?.length || 0}","${emp.status}"\n`;
        });
    } else {
        csv = "\uFEFFFecha,Hora,Colaborador,Identificación,Cargo,Tipo Marcación,Estado,Atraso,Justificación\n";
        attendanceToDisplay.forEach(rec => {
          const emp = employees.find(e => e.id === rec.employeeId);
          const date = new Date(rec.timestamp);
          csv += `"${date.toLocaleDateString()}","${date.toLocaleTimeString()}","${emp?.surname} ${emp?.name}","${emp?.identification}","${emp?.role}","${rec.type === 'in' ? 'Entrada' : 'Salida'}","${rec.status}","${rec.isLate ? 'SI' : 'NO'}","${rec.justification || ''}"\n`;
        });
    }
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `ASISTUP_${reportType.toUpperCase()}_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  };

  const attendanceToDisplay = (attendance || []).filter(a => {
    const emp = employees.find(e => e.id === a.employeeId);
    const searchStr = `${emp?.surname} ${emp?.name} ${emp?.identification} ${a.justification || ""} ${a.status} ${a.type}`.toLowerCase();
    return searchStr.includes(searchTerm.toLowerCase());
  }).sort((a,b) => b.timestamp.localeCompare(a.timestamp));

  const paymentsToDisplay = (payments || []).filter(p => {
    const emp = employees.find(e => e.id === p.employeeId);
    const searchStr = `${emp?.surname} ${emp?.name} ${emp?.identification} ${p.concept} ${p.type} ${p.voucherCode} ${p.method}`.toLowerCase();
    return searchStr.includes(searchTerm.toLowerCase());
  }).sort((a,b) => b.date.localeCompare(a.date));

  const historyToDisplay = employees.filter(e => {
    const searchStr = `${e.name} ${e.surname} ${e.identification} ${e.role} ${e.status}`.toLowerCase();
    return searchStr.includes(searchTerm.toLowerCase());
  }).sort((a,b) => b.startDate.localeCompare(a.startDate));

  return (
    <div className="space-y-6 md:space-y-8 fade-in">
      <div className="flex flex-col md:flex-row justify-between items-center bg-white p-6 md:p-10 rounded-[2.5rem] shadow-sm border border-slate-100 gap-6 no-print">
        <div className="w-full">
          <h2 className="text-2xl font-[950] text-slate-900 uppercase tracking-tighter italic">Central de Inteligencia Corporativa</h2>
          <div className="flex flex-col sm:flex-row gap-4 mt-6">
            <div className="flex gap-2 overflow-x-auto pb-2 sm:pb-0 no-scrollbar">
              <button onClick={() => {setReportType('attendance'); setSearchTerm('');}} className={`whitespace-nowrap px-6 py-3.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all shadow-sm ${reportType === 'attendance' ? 'bg-blue-600 text-white' : 'bg-slate-50 text-slate-400 border'}`}>Asistencia</button>
              <button onClick={() => {setReportType('payments'); setSearchTerm('');}} className={`whitespace-nowrap px-6 py-3.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all shadow-sm ${reportType === 'payments' ? 'bg-blue-600 text-white' : 'bg-slate-50 text-slate-400 border'}`}>Pagos / Egresos</button>
              <button onClick={() => {setReportType('history'); setSearchTerm('');}} className={`whitespace-nowrap px-6 py-3.5 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all shadow-sm ${reportType === 'history' ? 'bg-blue-600 text-white' : 'bg-slate-50 text-slate-400 border'}`}>Historial Bajas</button>
            </div>
            <input type="text" placeholder="Filtrar bitácora..." className="flex-1 p-3 border rounded-xl text-[11px] font-bold uppercase outline-none focus:border-blue-500" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
          </div>
        </div>
        <div className="flex flex-col gap-2 shrink-0">
           <button onClick={exportMasterFile} className="px-8 py-4 bg-slate-900 text-white font-[900] rounded-xl shadow-xl uppercase text-[10px] tracking-[0.2em] active:scale-95 transition-all">Generar Archivo Maestro</button>
           <div className="flex gap-2">
              <button onClick={exportExcel} className="flex-1 px-4 py-4 bg-emerald-600 text-white font-black rounded-xl shadow-lg uppercase text-[10px] active:scale-95">Excel</button>
              <button onClick={() => window.print()} className="flex-1 px-4 py-4 bg-blue-700 text-white font-black rounded-xl shadow-lg uppercase text-[10px] active:scale-95">PDF</button>
           </div>
        </div>
      </div>

      <div className="bg-white rounded-[2.5rem] shadow-sm border overflow-hidden" id="reports-printable-area">
         <div className="hidden print:block text-center border-b-2 border-black pb-4 mb-6 px-10 pt-10">
           <h1 className="text-2xl font-black uppercase leading-none italic">{company?.name || 'ASIST UP'}</h1>
           <p className="text-[10px] font-bold uppercase mt-2 tracking-widest">REPORTE OFICIAL: {reportType.toUpperCase()} - 2026</p>
           <div className="flex justify-between mt-6 text-[9px] font-black uppercase border-t pt-2 border-black">
              <span>Sede Matriz: {company?.address}</span>
              <span>Generado: {new Date().toLocaleString()}</span>
           </div>
         </div>

         <div className="p-4 md:p-10">
            <div className="table-responsive">
                <table className="w-full text-left print:table-auto border-collapse">
                    <thead className="bg-slate-50 text-[10px] font-[900] uppercase text-slate-400 print:bg-white print:text-black">
                        {reportType === 'attendance' ? (
                            <tr><th className="p-5 border-b-2">MARCACION CRONOLOGICA</th><th className="p-5 border-b-2">COLABORADOR / CI</th><th className="p-5 border-b-2">MOVIMIENTO</th><th className="p-5 border-b-2 text-center">ESTADO</th></tr>
                        ) : reportType === 'payments' ? (
                            <tr><th className="p-5 border-b-2">COMPROBANTE</th><th className="p-5 border-b-2">BENEFICIARIO</th><th className="p-5 border-b-2">CONCEPTO</th><th className="p-5 border-b-2 text-right">MONTO</th></tr>
                        ) : (
                            <tr><th className="p-5 border-b-2">NOMBRE COMPLETO</th><th className="p-5 border-b-2">CARGO ESTRUCTURAL</th><th className="p-5 border-b-2">ALTA / INGRESO</th><th className="p-5 border-b-2 text-right">SITUACION</th></tr>
                        )}
                    </thead>
                    <tbody className="text-[11px] font-bold uppercase divide-y print:text-black">
                        {reportType === 'attendance' && attendanceToDisplay.map(rec => {
                            const emp = employees.find(e => e.id === rec.employeeId);
                            return (
                              <tr key={rec.id} className="hover:bg-slate-50/50">
                                <td className="p-5">{new Date(rec.timestamp).toLocaleString()}</td>
                                <td className="p-5"><p className="font-black">{emp?.surname} {emp?.name}</p><p className="text-[9px] text-slate-400">{emp?.identification}</p></td>
                                <td className="p-5">{rec.type === 'in' ? 'INGRESO' : rec.type === 'out' ? 'SALIDA' : 'MEDIA JORNADA'}</td>
                                <td className={`p-5 text-center font-black ${rec.status === 'confirmed' ? 'text-emerald-600' : 'text-red-500'}`}>{rec.status}</td>
                              </tr>
                            );
                        })}
                        {reportType === 'payments' && paymentsToDisplay.map(p => {
                            const emp = employees.find(e => e.id === p.employeeId);
                            return (
                              <tr key={p.id} className="hover:bg-slate-50/50">
                                <td className="p-5"><p className="text-blue-600 font-[950]">{p.voucherCode}</p><p className="text-[9px] text-slate-400">{new Date(p.date).toLocaleDateString()}</p></td>
                                <td className="p-5"><p className="font-black">{emp?.surname} {emp?.name}</p><p className="text-[9px] text-slate-400">{p.method}</p></td>
                                <td className="p-5">{p.concept}</td>
                                <td className="p-5 text-right font-black text-slate-900">${p.amount.toFixed(2)}</td>
                              </tr>
                            );
                        })}
                        {reportType === 'history' && historyToDisplay.map(emp => (
                            <tr key={emp.id} className="hover:bg-slate-50/50">
                              <td className="p-5">{emp.surname} {emp.name}</td>
                              <td className="p-5">{emp.role}</td>
                              <td className="p-5">{emp.startDate}</td>
                              <td className={`p-5 text-right font-[950] ${emp.status === 'active' ? 'text-emerald-600' : 'text-red-500'}`}>{emp.status}</td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
         </div>
      </div>

      <Modal isOpen={feedback.isOpen} onClose={() => setFeedback({...feedback, isOpen: false})} title={feedback.title} type={feedback.type}>
          <div className="text-center p-6 space-y-6">
              <div className="w-16 h-16 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center text-3xl mx-auto shadow-inner">📜</div>
              <p className="text-slate-700 font-bold uppercase text-[11px] leading-relaxed italic">{feedback.message}</p>
              <button onClick={() => setFeedback({...feedback, isOpen: false})} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] tracking-widest active:scale-95">Entendido</button>
          </div>
      </Modal>
    </div>
  );
};

export default ReportsModule;

import React, { useState } from 'react';
import { GlobalSettings, Role } from '../../types.ts';
import Modal from '../../components/Modal.tsx';
import LZString from 'lz-string';

interface SettingsModuleProps {
  settings: GlobalSettings;
  onUpdate: (settings: GlobalSettings) => void;
  role: Role;
  onPurge?: () => void;
  allData?: any;
}

const SettingsModule: React.FC<SettingsModuleProps> = ({ settings, onUpdate, role, onPurge, allData }) => {
  const [local, setLocal] = useState<GlobalSettings>({ 
    ...settings, 
    sbuPrev: settings.sbuPrev || 460.00,
    holidays: settings.holidays || [],
    schedule: {
      ...(settings.schedule || {
        monFri: { in1: '08:30', out1: '13:00', in2: '15:00', out2: '18:00' },
        sat: { in: '08:30', out: '13:00' },
        halfDayOff: 'Miércoles tarde'
      })
    }
  });

  const [showPurgeConfirm, setShowPurgeConfirm] = useState(false);
  const [purgePassword, setPurgePassword] = useState('');
  const [newHolidayDate, setNewHolidayDate] = useState('');
  const [feedback, setFeedback] = useState<{isOpen: boolean, title: string, message: string, type: 'success' | 'error' | 'info' | 'warning'}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  const handleBackup = () => {
    try {
      if (!allData) {
         setFeedback({ isOpen: true, title: "Falta de Datos", message: "No se encontró información para respaldar.", type: "error" });
         return;
      }
      const dataStr = JSON.stringify(allData);
      const compressed = LZString.compressToEncodedURIComponent(dataStr);
      const blob = new Blob([compressed], { type: 'application/octet-stream' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `RESPALDO_ASISTUP_${new Date().toISOString().split('T')[0]}.bin`;
      link.click();
      setFeedback({ isOpen: true, title: "Respaldo Generado", message: "El archivo binario de seguridad ha sido descargado exitosamente.", type: "success" });
    } catch (e) {
      setFeedback({ isOpen: true, title: "Error", message: "Fallo crítico al generar el paquete de datos.", type: "error" });
    }
  };

  const handleResetDeviceConfig = () => {
    setFeedback({ 
      isOpen: true, 
      title: "Confirmación de Reset", 
      message: "¿Desea restablecer la configuración local de este equipo? Deberá seleccionar el modo de funcionamiento nuevamente.", 
      type: "warning" 
    });
    localStorage.removeItem('app_mode');
    setTimeout(() => window.location.reload(), 2000);
  };

  const handlePurgeExecution = () => {
    // Verificación de contraseña administrativa obligatoria
    if (purgePassword === 'admin123') {
      onPurge?.();
      setShowPurgeConfirm(false);
      setPurgePassword('');
      setFeedback({ 
        isOpen: true, 
        title: "Sistema Depurado", 
        message: "Toda la información ha sido eliminada permanentemente bajo autorización.", 
        type: "success" 
      });
    } else {
      setFeedback({ 
        isOpen: true, 
        title: "Acceso Denegado", 
        message: "La contraseña ingresada es incorrecta. Acción bloqueada por seguridad.", 
        type: "error" 
      });
    }
  };

  const handleAddHoliday = () => {
    if (!newHolidayDate) return;
    if (local.holidays.includes(newHolidayDate)) {
      setFeedback({ isOpen: true, title: "Fecha Duplicada", message: "Este día ya está marcado como feriado institucional.", type: "error" });
      return;
    }
    const updatedHolidays = [...local.holidays, newHolidayDate].sort();
    setLocal({ ...local, holidays: updatedHolidays });
    setNewHolidayDate('');
  };

  const handleRemoveHoliday = (date: string) => {
    setLocal({ ...local, holidays: local.holidays.filter(d => d !== date) });
  };

  const handleSave = () => {
    if (role !== Role.SUPER_ADMIN) {
        setFeedback({ isOpen: true, title: "Acceso Restringido", message: "Solo el Super Administrador tiene autorización para estos cambios.", type: "error" });
        return;
    }
    onUpdate(local);
    setFeedback({ isOpen: true, title: "Sincronizado", message: "Parámetros globales actualizados correctamente.", type: "success" });
  };

  return (
    <div className="max-w-4xl mx-auto space-y-10 fade-in pb-20">
      <div className="bg-white p-8 md:p-12 rounded-[2.5rem] md:rounded-[3.5rem] shadow-sm border space-y-10 md:space-y-12">
        <header className="border-b pb-6 flex items-center gap-4">
          <div className="w-10 h-10">
             <svg viewBox="0 0 100 100" className="w-full h-full drop-shadow-[0_0_8px_rgba(59,130,246,0.5)]">
               <defs>
                 <linearGradient id="setLogo" x1="0%" y1="0%" x2="100%" y2="100%">
                   <stop offset="0%" style={{stopColor: '#3b82f6'}} />
                   <stop offset="100%" style={{stopColor: '#1e3a8a'}} />
                 </linearGradient>
               </defs>
               <circle cx="50" cy="50" r="45" fill="none" stroke="url(#setLogo)" strokeWidth="6" strokeDasharray="15 5" />
               <circle cx="50" cy="50" r="6" fill="#3b82f6" />
             </svg>
          </div>
          <h2 className="text-2xl md:text-3xl font-[900] text-slate-900 tracking-tighter uppercase italic leading-none">Configuración Superior</h2>
        </header>

        {/* PARÁMETROS MAESTROS */}
        <section className="grid grid-cols-1 md:grid-cols-2 gap-8 md:gap-10">
           <div className="space-y-3">
              <label className="text-[10px] font-black text-blue-700 uppercase tracking-widest">SBU Año Vigente</label>
              <input type="number" step="0.01" className="w-full p-4 md:p-6 border-2 rounded-2xl md:rounded-3xl font-[950] text-2xl md:text-3xl focus:border-blue-500 outline-none transition-all" value={local.sbu} onChange={e => setLocal({...local, sbu: Number(e.target.value)})} />
           </div>
           <div className="space-y-3">
              <label className="text-[10px] font-black text-blue-700 uppercase tracking-widest">SBU Año Anterior</label>
              <input type="number" step="0.01" className="w-full p-4 md:p-6 border-2 rounded-2xl md:rounded-3xl font-[950] text-2xl md:text-3xl focus:border-blue-500 outline-none transition-all" value={local.sbuPrev} onChange={e => setLocal({...local, sbuPrev: Number(e.target.value)})} />
           </div>
        </section>

        {/* GESTIÓN DE SEGURIDAD Y DATOS */}
        <section className="bg-slate-50 p-6 md:p-10 rounded-[2rem] md:rounded-[3rem] border border-slate-100 space-y-6">
           <h3 className="text-[11px] font-black text-slate-400 uppercase tracking-[0.3em] border-b pb-4 mb-6">Mantenimiento de Datos</h3>
           <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <button onClick={handleBackup} className="p-6 bg-white border border-slate-200 rounded-2xl hover:border-blue-500 transition-all text-left flex items-center gap-4 group">
                 <div className="w-12 h-12 bg-blue-50 text-blue-600 rounded-xl flex items-center justify-center text-xl group-hover:scale-110 transition-transform">💾</div>
                 <div>
                    <p className="text-[11px] font-black text-slate-900 uppercase">Respaldo Local</p>
                    <p className="text-[9px] text-slate-400 font-bold uppercase mt-1">Exportar Base Institucional</p>
                 </div>
              </button>
              <button onClick={handleResetDeviceConfig} className="p-6 bg-white border border-slate-200 rounded-2xl hover:border-orange-500 transition-all text-left flex items-center gap-4 group">
                 <div className="w-12 h-12 bg-orange-50 text-orange-600 rounded-xl flex items-center justify-center text-xl group-hover:scale-110 transition-transform">🔄</div>
                 <div>
                    <p className="text-[11px] font-black text-slate-900 uppercase">Recalibrar Equipo</p>
                    <p className="text-[9px] text-slate-400 font-bold uppercase mt-1">Resetear Modo de Acceso</p>
                 </div>
              </button>
           </div>
           <div className="pt-4">
              <button onClick={() => setShowPurgeConfirm(true)} className="w-full p-6 bg-red-50 text-red-600 border border-red-100 rounded-2xl hover:bg-red-600 hover:text-white transition-all text-left flex items-center gap-4 group">
                 <div className="w-12 h-12 bg-white/50 rounded-xl flex items-center justify-center text-xl group-hover:animate-shake">🗑️</div>
                 <div>
                    <p className="text-[11px] font-black uppercase">Depuración de Sistema</p>
                    <p className="text-[9px] font-bold uppercase mt-1 opacity-70 italic">Eliminación crítica de registros</p>
                 </div>
              </button>
           </div>
        </section>

        <button onClick={handleSave} className="w-full py-6 md:py-8 bg-slate-900 text-white font-[950] rounded-[2rem] md:rounded-[2.5rem] shadow-2xl uppercase text-[10px] md:text-xs tracking-[0.4em] hover:scale-[1.02] transition-all active:scale-95">Sincronizar Parámetros</button>
      </div>

      {/* Modal Purge con Contraseña */}
      <Modal isOpen={showPurgeConfirm} onClose={() => setShowPurgeConfirm(false)} title="VERIFICACIÓN ADMINISTRATIVA" type="error">
         <div className="space-y-8 text-center p-4">
            <div className="w-20 h-20 bg-red-100 text-red-600 rounded-full flex items-center justify-center text-4xl mx-auto shadow-inner">🔒</div>
            <div>
               <h3 className="text-xl font-black text-slate-900 uppercase tracking-tighter italic">Acción de Alta Seguridad</h3>
               <p className="text-[11px] text-slate-500 font-bold uppercase tracking-widest leading-relaxed mt-4">Ingrese su contraseña de administrador para proceder con la eliminación masiva de datos.</p>
            </div>
            <div className="space-y-4">
               <input 
                 type="password" 
                 value={purgePassword}
                 onChange={e => setPurgePassword(e.target.value)}
                 className="w-full p-4 border-2 rounded-xl text-center text-2xl font-black focus:border-red-600 outline-none uppercase"
                 placeholder="••••••••"
                 autoFocus
               />
               <div className="flex flex-col sm:flex-row gap-3">
                  <button onClick={() => { setShowPurgeConfirm(false); setPurgePassword(''); }} className="flex-1 py-4 bg-slate-100 text-slate-600 font-black rounded-xl uppercase text-[10px] tracking-widest active:scale-95">Cancelar</button>
                  <button onClick={handlePurgeExecution} className="flex-1 py-4 bg-red-600 text-white font-black rounded-xl uppercase text-[10px] tracking-widest shadow-xl active:scale-95">Autorizar Purgado</button>
               </div>
            </div>
         </div>
      </Modal>

      <Modal isOpen={feedback.isOpen} onClose={() => setFeedback({...feedback, isOpen: false})} title={feedback.title} type={feedback.type as any}>
          <div className="text-center space-y-6 p-4">
              <p className="text-slate-600 font-bold uppercase text-[12px] leading-relaxed">{feedback.message}</p>
              <button onClick={() => setFeedback({...feedback, isOpen: false})} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] tracking-widest active:scale-95 transition-all">Aceptar</button>
          </div>
      </Modal>
    </div>
  );
};

export default SettingsModule;

import React, { useState } from 'react';
import { Employee, Payment, AttendanceRecord, CompanyConfig, GlobalSettings, Role } from '../../types.ts';
import Modal from '../../components/Modal.tsx';

interface ReportsModuleProps {
  employees: Employee[];
  payments: Payment[];
  attendance: AttendanceRecord[];
  company: CompanyConfig | null;
  settings: GlobalSettings;
  role: Role;
}

const ReportsModule: React.FC<ReportsModuleProps> = ({ employees, payments = [], attendance = [], company, settings, role }) => {
  const [reportType, setReportType] = useState<'attendance' | 'payments' | 'history' | 'master'>('attendance');
  const [searchTerm, setSearchTerm] = useState('');
  const [feedback, setFeedback] = useState({ isOpen: false, title: '', message: '', type: 'success' as any });

  const generateMasterExcel = (type: 'employees' | 'payroll' | 'attendance') => {
    let csv = "\uFEFF";
    let filename = "";

    if (type === 'employees') {
      csv += "IDENTIFICACION,APELLIDOS Y NOMBRES,CARGO,FECHA INGRESO,ESTADO,SALARIO,AFILIADO IESS,MODO SOBRESUELDO\n";
      employees.forEach(e => {
        csv += `"${e.identification}","${e.surname} ${e.name}","${e.role}","${e.startDate}","${e.status}","${e.salary.toFixed(2)}","${e.isAffiliated ? 'SI' : 'NO'}","${e.overSalaryType}"\n`;
      });
      filename = "MAESTRO_PERSONAL";
    } else if (type === 'payroll') {
      csv += "CODIGO,FECHA,BENEFICIARIO,CONCEPTO,METODO,MONTO,STATUS\n";
      payments.forEach(p => {
        const emp = employees.find(e => e.id === p.employeeId);
        csv += `"${p.voucherCode}","${new Date(p.date).toLocaleDateString()}","${emp?.surname} ${emp?.name}","${p.type}","${p.method}","${p.amount.toFixed(2)}","${p.status}"\n`;
      });
      filename = "MAESTRO_NOMINA";
    } else {
      csv += "FECHA,ID COLABORADOR,NOMBRE,TIPO,ESTADO,ATRASO,JUSTIFICACION\n";
      attendance.forEach(a => {
        const emp = employees.find(e => e.id === a.employeeId);
        csv += `"${new Date(a.timestamp).toLocaleString()}","${emp?.identification}","${emp?.surname} ${emp?.name}","${a.type}","${a.status}","${a.isLate ? 'SI' : 'NO'}","${a.justification || ''}"\n`;
      });
      filename = "MAESTRO_ASISTENCIA";
    }

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `${filename}_${new Date().getFullYear()}.csv`;
    link.click();
    setFeedback({ isOpen: true, title: "Excel Generado", message: "Archivo de datos exportado correctamente.", type: "success" });
  };

  const generateMasterPDF = (type: 'employees' | 'payroll' | 'attendance') => {
    setReportType(type as any); // Cambiar vista para impresión
    setTimeout(() => {
      window.print();
      setFeedback({ isOpen: true, title: "Generador de PDF", message: "Use la función de guardado de su navegador para archivar el PDF.", type: "info" });
    }, 500);
  };

  const attendanceToDisplay = (attendance || []).filter(a => {
    const emp = employees.find(e => e.id === a.employeeId);
    const searchStr = `${emp?.surname} ${emp?.name} ${emp?.identification} ${a.justification || ""} ${a.status} ${a.type}`.toLowerCase();
    return searchStr.includes(searchTerm.toLowerCase());
  }).sort((a,b) => b.timestamp.localeCompare(a.timestamp));

  const paymentsToDisplay = (payments || []).filter(p => {
    const emp = employees.find(e => e.id === p.employeeId);
    const searchStr = `${emp?.surname} ${emp?.name} ${emp?.identification} ${p.concept} ${p.type} ${p.voucherCode} ${p.method}`.toLowerCase();
    return searchStr.includes(searchTerm.toLowerCase());
  }).sort((a,b) => b.date.localeCompare(a.date));

  const historyToDisplay = employees.filter(e => {
    const searchStr = `${e.name} ${e.surname} ${e.identification} ${e.role} ${e.status}`.toLowerCase();
    return searchStr.includes(searchTerm.toLowerCase());
  }).sort((a,b) => b.startDate.localeCompare(a.startDate));

  return (
    <div className="space-y-6 md:space-y-8 fade-in">
      <div className="flex flex-col md:flex-row justify-between items-center bg-white p-6 md:p-10 rounded-[2.5rem] shadow-sm border border-slate-100 gap-6 no-print">
        <div className="w-full">
          <h2 className="text-2xl font-[950] text-slate-900 uppercase tracking-tighter italic leading-none">Inteligencia Corporativa</h2>
          <div className="flex flex-col sm:flex-row gap-4 mt-8">
            <div className="flex gap-2 overflow-x-auto pb-2 sm:pb-0 no-scrollbar">
              <button onClick={() => {setReportType('attendance'); setSearchTerm('');}} className={`whitespace-nowrap px-6 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${reportType === 'attendance' ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-50 text-slate-400 border'}`}>Asistencia</button>
              <button onClick={() => {setReportType('payments'); setSearchTerm('');}} className={`whitespace-nowrap px-6 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${reportType === 'payments' ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-50 text-slate-400 border'}`}>Nómina</button>
              <button onClick={() => {setReportType('history'); setSearchTerm('');}} className={`whitespace-nowrap px-6 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${reportType === 'history' ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-50 text-slate-400 border'}`}>Pasivo Laboral</button>
              <button onClick={() => {setReportType('master'); setSearchTerm('');}} className={`whitespace-nowrap px-6 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${reportType === 'master' ? 'bg-slate-900 text-white shadow-lg' : 'bg-slate-50 text-slate-400 border'}`}>Archivo Maestro</button>
            </div>
            {reportType !== 'master' && (
              <input type="text" placeholder="Filtrar registros..." className="flex-1 p-4 border-2 rounded-2xl text-[11px] font-bold uppercase outline-none focus:border-blue-500" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
            )}
          </div>
        </div>
      </div>

      <div className="bg-white rounded-[2.5rem] shadow-sm border overflow-hidden" id="reports-printable-area">
         {reportType === 'master' ? (
           <div className="p-10 md:p-16 space-y-12 no-print">
              <header className="border-b pb-6">
                <h3 className="text-xl font-black text-slate-900 uppercase tracking-widest">Gestión de Archivo Maestro Mensual</h3>
                <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest mt-2">Exportación segmentada para archivo cronológico</p>
              </header>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                 {/* SEGMENTO PERSONAL */}
                 <div className="bg-slate-50 p-8 rounded-[2.5rem] border border-slate-100 flex flex-col justify-between">
                    <div className="mb-6">
                       <div className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center text-2xl shadow-sm mb-4">👥</div>
                       <h4 className="text-[12px] font-black uppercase tracking-widest">Fichas de Personal</h4>
                       <p className="text-[9px] text-slate-400 font-bold uppercase mt-2">Expedientes maestros de todos los colaboradores.</p>
                    </div>
                    <div className="grid grid-cols-2 gap-2">
                       <button onClick={() => generateMasterExcel('employees')} className="py-3 bg-emerald-600 text-white text-[9px] font-black rounded-xl uppercase active:scale-95 transition-all">Excel</button>
                       <button onClick={() => generateMasterPDF('employees' as any)} className="py-3 bg-blue-700 text-white text-[9px] font-black rounded-xl uppercase active:scale-95 transition-all">PDF</button>
                    </div>
                 </div>

                 {/* SEGMENTO NOMINA */}
                 <div className="bg-slate-50 p-8 rounded-[2.5rem] border border-slate-100 flex flex-col justify-between">
                    <div className="mb-6">
                       <div className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center text-2xl shadow-sm mb-4">💰</div>
                       <h4 className="text-[12px] font-black uppercase tracking-widest">Registros de Nómina</h4>
                       <p className="text-[9px] text-slate-400 font-bold uppercase mt-2">Historial consolidado de pagos y beneficios.</p>
                    </div>
                    <div className="grid grid-cols-2 gap-2">
                       <button onClick={() => generateMasterExcel('payroll')} className="py-3 bg-emerald-600 text-white text-[9px] font-black rounded-xl uppercase active:scale-95 transition-all">Excel</button>
                       <button onClick={() => generateMasterPDF('payments' as any)} className="py-3 bg-blue-700 text-white text-[9px] font-black rounded-xl uppercase active:scale-95 transition-all">PDF</button>
                    </div>
                 </div>

                 {/* SEGMENTO ASISTENCIA */}
                 <div className="bg-slate-50 p-8 rounded-[2.5rem] border border-slate-100 flex flex-col justify-between">
                    <div className="mb-6">
                       <div className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center text-2xl shadow-sm mb-4">🕒</div>
                       <h4 className="text-[12px] font-black uppercase tracking-widest">Bitácora de Asistencia</h4>
                       <p className="text-[9px] text-slate-400 font-bold uppercase mt-2">Movimientos cronológicos de marcación diaria.</p>
                    </div>
                    <div className="grid grid-cols-2 gap-2">
                       <button onClick={() => generateMasterExcel('attendance')} className="py-3 bg-emerald-600 text-white text-[9px] font-black rounded-xl uppercase active:scale-95 transition-all">Excel</button>
                       <button onClick={() => generateMasterPDF('attendance' as any)} className="py-3 bg-blue-700 text-white text-[9px] font-black rounded-xl uppercase active:scale-95 transition-all">PDF</button>
                    </div>
                 </div>
              </div>

              <div className="p-8 bg-blue-900 rounded-[2.5rem] text-white flex items-center gap-6">
                 <span className="text-4xl">📚</span>
                 <div>
                    <p className="text-[11px] font-[900] uppercase tracking-widest">Protocolo de Archivística</p>
                    <p className="text-[10px] font-medium leading-relaxed opacity-70 italic mt-1">Se recomienda descargar mensualmente todos los segmentos en ambos formatos para el cumplimiento legal y auditorías externas.</p>
                 </div>
              </div>
           </div>
         ) : (
           <div className="p-4 md:p-10">
              <div className="hidden print:block text-center border-b-2 border-black pb-4 mb-6">
                <h1 className="text-2xl font-black uppercase leading-none italic">{company?.name || 'ASIST UP'}</h1>
                <p className="text-[10px] font-bold uppercase mt-2 tracking-widest">REPORTE OFICIAL: {reportType.toUpperCase()}</p>
                <div className="flex justify-between mt-6 text-[9px] font-black uppercase border-t pt-2 border-black">
                   <span>Sede: {company?.address}</span>
                   <span>Generado: {new Date().toLocaleString()}</span>
                </div>
              </div>
              <div className="table-responsive">
                  <table className="w-full text-left print:table-auto border-collapse">
                      <thead className="bg-slate-50 text-[10px] font-[900] uppercase text-slate-400 print:bg-white print:text-black">
                          {reportType === 'attendance' ? (
                              <tr><th className="p-5 border-b-2">MARCACION</th><th className="p-5 border-b-2">COLABORADOR</th><th className="p-5 border-b-2">MOVIMIENTO</th><th className="p-5 border-b-2 text-center">ESTADO</th></tr>
                          ) : reportType === 'payments' ? (
                              <tr><th className="p-5 border-b-2">COMPROBANTE</th><th className="p-5 border-b-2">BENEFICIARIO</th><th className="p-5 border-b-2">CONCEPTO</th><th className="p-5 border-b-2 text-right">MONTO</th></tr>
                          ) : (
                              <tr><th className="p-5 border-b-2">NOMBRE COMPLETO</th><th className="p-5 border-b-2">CARGO</th><th className="p-5 border-b-2">ALTA</th><th className="p-5 border-b-2 text-right">SITUACION</th></tr>
                          )}
                      </thead>
                      <tbody className="text-[11px] font-bold uppercase divide-y print:text-black">
                          {reportType === 'attendance' && attendanceToDisplay.map(rec => {
                              const emp = employees.find(e => e.id === rec.employeeId);
                              return (
                                <tr key={rec.id}>
                                  <td className="p-5">{new Date(rec.timestamp).toLocaleString()}</td>
                                  <td className="p-5 font-black">{emp?.surname} {emp?.name}</td>
                                  <td className="p-5">{rec.type}</td>
                                  <td className={`p-5 text-center font-black ${rec.status === 'confirmed' ? 'text-emerald-600' : 'text-red-500'}`}>{rec.status}</td>
                                </tr>
                              );
                          })}
                          {reportType === 'payments' && paymentsToDisplay.map(p => {
                              const emp = employees.find(e => e.id === p.employeeId);
                              return (
                                <tr key={p.id}>
                                  <td className="p-5 font-[950] text-blue-600">{p.voucherCode}</td>
                                  <td className="p-5 font-black">{emp?.surname} {emp?.name}</td>
                                  <td className="p-5">{p.concept}</td>
                                  <td className="p-5 text-right font-black">${p.amount.toFixed(2)}</td>
                                </tr>
                              );
                          })}
                          {reportType === 'history' && historyToDisplay.map(emp => (
                              <tr key={emp.id}>
                                <td className="p-5">{emp.surname} {emp.name}</td>
                                <td className="p-5">{emp.role}</td>
                                <td className="p-5">{emp.startDate}</td>
                                <td className={`p-5 text-right font-[950] ${emp.status === 'active' ? 'text-emerald-600' : 'text-red-500'}`}>{emp.status}</td>
                              </tr>
                          ))}
                      </tbody>
                  </table>
              </div>
           </div>
         )}
      </div>

      <Modal isOpen={feedback.isOpen} onClose={() => setFeedback({...feedback, isOpen: false})} title={feedback.title} type={feedback.type}>
          <div className="text-center p-6 space-y-6">
              <p className="text-slate-700 font-bold uppercase text-[11px] leading-relaxed italic">{feedback.message}</p>
              <button onClick={() => setFeedback({...feedback, isOpen: false})} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] tracking-widest">Entendido</button>
          </div>
      </Modal>
    </div>
  );
};

export default ReportsModule;

import React, { useState, useEffect } from 'react';
import { Employee, Role, BloodType, Gender, CivilStatus, AbsenceRecord, TerminationReason } from '../../types.ts';
import Modal from '../../components/Modal.tsx';

interface EmployeeModuleProps {
  employees: Employee[];
  onUpdate: (employees: Employee[]) => void;
  role: Role;
  attendance: any[];
  payments: any[];
  company: any;
}

const EmployeeModule: React.FC<EmployeeModuleProps> = ({ employees, onUpdate, role, company }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingEmp, setEditingEmp] = useState<Employee | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [showArchived, setShowArchived] = useState(false);

  // Estados para Novedades y Desvinculación
  const [selectedEmpAction, setSelectedEmpAction] = useState<Employee | null>(null);
  const [isNovedadModalOpen, setIsNovedadModalOpen] = useState(false);
  const [isDesvinculacionModalOpen, setIsDesvinculacionModalOpen] = useState(false);

  const [novedadText, setNovedadText] = useState('');
  const [desvinculacionData, setDesvinculacionData] = useState({
    date: new Date().toISOString().split('T')[0],
    reason: TerminationReason.VOLUNTARY,
    details: ''
  });

  const [feedback, setFeedback] = useState<{isOpen: boolean, title: string, message: string, type: 'success' | 'error' | 'info'}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  const initialForm: Partial<Employee> = {
    name: '', surname: '', identification: '', birthDate: '', phone: '', email: '', 
    gender: Gender.MASCULINO, civilStatus: CivilStatus.SOLTERO,
    origin: 'ECUATORIANA', address: '', 
    bloodType: BloodType.O_POS, startDate: new Date().toISOString().split('T')[0],
    role: Role.EMPLOYEE, salary: 482.00, status: 'active' as const, photo: '', pin: '',
    emergencyContact: { name: '', phone: '' },
    isFixed: true, isAffiliated: true, 
    overSalaryType: 'monthly', // Para Décimos
    reserveFundType: 'monthly', // Específico para Fondos de Reserva
    bankInfo: { ifi: '', type: 'Ahorros', account: '' },
    absences: [],
    observations: []
  };

  const [form, setForm] = useState<Partial<Employee>>(initialForm);

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 2 * 1024 * 1024) {
        setFeedback({ isOpen: true, title: "Archivo Grande", message: "La imagen excede los 2MB. Use una foto más pequeña.", type: "error" });
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setForm(prev => ({ ...prev, photo: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSave = () => {
    if (!form.name || !form.surname || !form.identification || !form.salary || !form.role) {
      setFeedback({ isOpen: true, title: "Faltan Datos", message: "Nombre, apellido, cédula, cargo y sueldo son obligatorios.", type: "error" });
      return;
    }

    let updatedList: Employee[];
    if (editingEmp) {
      updatedList = employees.map(e => e.id === editingEmp.id ? { ...e, ...form } as Employee : e);
      setFeedback({ isOpen: true, title: "Sincronizado", message: "Expediente maestro actualizado correctamente.", type: "success" });
    } else {
      const autoPin = Math.floor(100000 + Math.random() * 900000).toString();
      const newEmp: Employee = { 
        ...form, 
        id: Math.random().toString(36).substr(2, 9), 
        pin: autoPin, 
        pinChanged: false, 
        pinNeedsReset: false, 
        status: 'active' as const 
      } as Employee;
      updatedList = [...employees, newEmp];
      setFeedback({ isOpen: true, title: "Ingreso Exitoso", message: `Colaborador registrado. PIN de Marcación: ${autoPin}.`, type: "success" });
    }
    onUpdate(updatedList);
    setIsModalOpen(false);
  };

  const handleAddNovedad = () => {
    if (!novedadText.trim() || !selectedEmpAction) return;
    const newNovedad = { date: new Date().toISOString(), text: novedadText.toUpperCase() };
    const updated = employees.map(e => e.id === selectedEmpAction.id ? {
      ...e,
      observations: [newNovedad, ...(e.observations || [])]
    } : e);
    onUpdate(updated);
    setNovedadText('');
    setIsNovedadModalOpen(false);
    setFeedback({ isOpen: true, title: "Novedad Registrada", message: "La novedad ha sido añadida al historial del empleado.", type: "success" });
  };

  const handleProcessDesvinculacion = () => {
    if (!selectedEmpAction) return;
    const updated = employees.map(e => e.id === selectedEmpAction.id ? {
      ...e,
      status: 'terminated' as const,
      terminationDate: desvinculacionData.date,
      terminationReason: desvinculacionData.reason,
      terminationDetails: desvinculacionData.details.toUpperCase()
    } : e);
    onUpdate(updated);
    setIsDesvinculacionModalOpen(false);
    setFeedback({ isOpen: true, title: "Baja Procesada", message: "El empleado ha sido desvinculado del sistema correctamente.", type: "success" });
  };

  const filteredEmployees = employees.filter(e => {
    const searchString = `${e.name} ${e.surname} ${e.identification}`.toLowerCase();
    const matchesSearch = searchString.includes(searchTerm.toLowerCase());
    return showArchived 
      ? matchesSearch && (e.status === 'archived' || e.status === 'terminated') 
      : matchesSearch && e.status === 'active';
  });

  return (
    <div className="space-y-6 fade-in">
      <div className="bg-white p-6 rounded-3xl md:rounded-[2.5rem] shadow-sm border border-slate-100 flex flex-col md:flex-row justify-between items-center no-print gap-4">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10">
             <svg viewBox="0 0 100 100" className="w-full h-full drop-shadow-[0_0_8px_rgba(59,130,246,0.3)]">
               <circle cx="50" cy="50" r="45" fill="none" stroke="#3b82f6" strokeWidth="6" strokeDasharray="12 4" />
               <path d="M50 30 V70 M30 50 H70" stroke="#3b82f6" strokeWidth="8" strokeLinecap="round" />
             </svg>
          </div>
          <div>
            <h2 className="text-xl font-[950] text-slate-900 uppercase">Gestión de Personal</h2>
            <div className="flex gap-4 mt-1">
              <button onClick={() => setShowArchived(false)} className={`text-[9px] font-black uppercase tracking-widest ${!showArchived ? 'text-blue-600 border-b-2 border-blue-600' : 'text-slate-400'}`}>Activos</button>
              <button onClick={() => setShowArchived(true)} className={`text-[9px] font-black uppercase tracking-widest ${showArchived ? 'text-blue-600 border-b-2 border-blue-600' : 'text-slate-400'}`}>Bajas</button>
            </div>
          </div>
        </div>
        <div className="flex flex-col sm:flex-row gap-3 w-full md:w-auto">
          <input type="text" placeholder="Filtrar identificación..." className="w-full sm:w-64 p-3 border rounded-xl text-[11px] uppercase font-bold focus:border-blue-500 outline-none" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
          <button onClick={() => { setForm(initialForm); setEditingEmp(null); setIsModalOpen(true); }} className="px-6 py-3.5 bg-blue-700 text-white font-black rounded-xl shadow-lg uppercase text-[9px] tracking-widest active:scale-95 transition-all">Registrar Nuevo</button>
        </div>
      </div>

      <div className="bg-white rounded-[2.5rem] shadow-sm border overflow-hidden no-print">
        <div className="table-responsive">
          <table className="w-full text-left">
            <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest">
              <tr>
                <th className="px-6 py-4">Empleado</th>
                <th className="px-6 py-4">Cargo / ID</th>
                <th className="px-6 py-4 text-center">Estado</th>
                <th className="px-6 py-4 text-right">Acciones de Gestión</th>
              </tr>
            </thead>
            <tbody className="divide-y text-[11px] font-black uppercase">
              {filteredEmployees.map(emp => (
                <tr key={emp.id} className="hover:bg-blue-50/30 transition-colors">
                  <td className="px-6 py-3 text-slate-900">{emp.surname} {emp.name}</td>
                  <td className="px-6 py-3"><p className="text-blue-600">{emp.role}</p><p className="text-[9px] text-slate-400 font-mono">{emp.identification}</p></td>
                  <td className="px-6 py-3 text-center">
                    <span className={`px-3 py-1 rounded-full text-[8px] font-black uppercase ${emp.status === 'active' ? 'bg-emerald-50 text-emerald-600' : 'bg-red-50 text-red-600'}`}>
                      {emp.status === 'active' ? 'Activo' : 'Baja'}
                    </span>
                  </td>
                  <td className="px-6 py-3 text-right">
                     <div className="flex justify-end gap-2">
                        <button onClick={() => { setEditingEmp(emp); setForm(emp); setIsModalOpen(true); }} className="p-2 bg-slate-100 text-slate-600 rounded-lg text-[10px]" title="Editar">✏️</button>
                        <button onClick={() => { setSelectedEmpAction(emp); setIsNovedadModalOpen(true); }} className="p-2 bg-blue-50 text-blue-600 rounded-lg text-[10px]" title="Novedades">📝</button>
                        {emp.status === 'active' && (
                           <button onClick={() => { setSelectedEmpAction(emp); setIsDesvinculacionModalOpen(true); }} className="p-2 bg-red-50 text-red-600 rounded-lg text-[10px]" title="Desvincular">🚪</button>
                        )}
                     </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* MODAL FORMULARIO COMPLETO */}
      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title={editingEmp ? "Editar Colaborador" : "Nuevo Ingreso Personal"} maxWidth="max-w-4xl">
        <div className="space-y-6 max-h-[75vh] overflow-y-auto pr-2 custom-scroll">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
               <div className="space-y-1">
                 <label className="text-[9px] font-black text-slate-400 uppercase">Nombres</label>
                 <input className="w-full p-3 border rounded-xl text-xs font-bold uppercase focus:border-blue-500 outline-none" value={form.name} onChange={e => setForm({...form, name: e.target.value.toUpperCase()})} />
               </div>
               <div className="space-y-1">
                 <label className="text-[9px] font-black text-slate-400 uppercase">Apellidos</label>
                 <input className="w-full p-3 border rounded-xl text-xs font-bold uppercase focus:border-blue-500 outline-none" value={form.surname} onChange={e => setForm({...form, surname: e.target.value.toUpperCase()})} />
               </div>
               <div className="space-y-1">
                 <label className="text-[9px] font-black text-slate-400 uppercase">Identificación</label>
                 <input className="w-full p-3 border rounded-xl text-xs font-mono font-bold focus:border-blue-500 outline-none" value={form.identification} onChange={e => setForm({...form, identification: e.target.value.replace(/\D/g,'')})} />
               </div>
               <div className="space-y-1">
                 <label className="text-[9px] font-black text-slate-400 uppercase">Sueldo Base ($)</label>
                 <input type="number" className="w-full p-3 border rounded-xl text-xs font-black focus:border-blue-500 outline-none" value={form.salary} onChange={e => setForm({...form, salary: Number(e.target.value)})} />
               </div>
          </div>

          <section className="space-y-4 pt-4 border-t">
             <h4 className="text-[10px] font-black text-blue-700 uppercase tracking-widest border-b pb-1">Seguridad Social y Beneficios</h4>
             <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div className="space-y-1 flex flex-col justify-end">
                   <label className="text-[9px] font-black text-slate-400 uppercase mb-2">Afiliación IESS</label>
                   <div className="flex items-center gap-3 bg-slate-50 p-3 rounded-xl border">
                      <span className="text-[9px] font-black uppercase text-slate-400">{form.isAffiliated ? 'SÍ' : 'NO'}</span>
                      <button 
                        type="button"
                        onClick={() => setForm({...form, isAffiliated: !form.isAffiliated})}
                        className={`relative inline-flex h-5 w-10 items-center rounded-full transition-colors ${form.isAffiliated ? 'bg-blue-600' : 'bg-slate-300'}`}
                      >
                        <span className={`inline-block h-3 w-3 transform rounded-full bg-white transition-transform ${form.isAffiliated ? 'translate-x-6' : 'translate-x-1'}`} />
                      </button>
                   </div>
                </div>

                {/* FONDOS DE RESERVA SEPARADO: Solo si está afiliado */}
                {form.isAffiliated && (
                   <div className="space-y-1">
                     <label className="text-[9px] font-black text-slate-400 uppercase">Fondos de Reserva (8.33%)</label>
                     <select className="w-full p-3 border-2 border-emerald-100 bg-emerald-50/20 rounded-xl text-xs font-bold uppercase focus:border-emerald-500 outline-none" value={form.reserveFundType || 'monthly'} onChange={e => setForm({...form, reserveFundType: e.target.value as any})}>
                       <option value="monthly">Mensualizar (Recibir Pago)</option>
                       <option value="accumulate">Acumular (IESS)</option>
                     </select>
                   </div>
                )}

                <div className="space-y-1">
                  <label className="text-[9px] font-black text-slate-400 uppercase">Décimos Sueldos</label>
                  <select className="w-full p-3 border rounded-xl text-xs font-bold uppercase focus:border-blue-500 outline-none" value={form.overSalaryType} onChange={e => setForm({...form, overSalaryType: e.target.value as any})}>
                    <option value="monthly">Mensualizar Décimos</option>
                    <option value="accumulate">Acumular Décimos</option>
                    <option value="none">No Aplica</option>
                  </select>
                </div>
             </div>
          </section>

          <div className="pt-6 flex gap-4">
             <button onClick={() => setIsModalOpen(false)} className="flex-1 py-3 bg-slate-100 text-slate-500 font-black rounded-xl uppercase text-[9px]">Cancelar</button>
             <button onClick={handleSave} className="flex-[2] py-3 bg-blue-700 text-white font-black rounded-xl uppercase text-[9px] tracking-widest shadow-lg">Guardar Colaborador</button>
          </div>
        </div>
      </Modal>

      {/* MODAL NOVEDADES */}
      <Modal isOpen={isNovedadModalOpen} onClose={() => setIsNovedadModalOpen(false)} title="Registro de Novedades">
         <div className="space-y-6">
            <div className="p-4 bg-blue-50 rounded-2xl border border-blue-100">
               <p className="text-[11px] font-black text-blue-900 uppercase">{selectedEmpAction?.surname} {selectedEmpAction?.name}</p>
               <p className="text-[9px] font-bold text-blue-400 uppercase">Historial de incidencias administrativas</p>
            </div>
            <textarea 
              className="w-full border-2 p-4 rounded-xl text-xs font-bold uppercase focus:border-blue-500 outline-none min-h-[100px]" 
              placeholder="Describa la novedad, amonestación o mérito..."
              value={novedadText}
              onChange={e => setNovedadText(e.target.value)}
            />
            <button onClick={handleAddNovedad} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] tracking-widest shadow-xl">Guardar Novedad en Bitácora</button>

            <div className="space-y-2 mt-4">
               <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest border-b pb-1">Historial Reciente</p>
               {selectedEmpAction?.observations?.length ? selectedEmpAction.observations.map((obs, i) => (
                  <div key={i} className="p-3 bg-slate-50 rounded-xl border text-[10px]">
                     <p className="font-black text-slate-400">{new Date(obs.date).toLocaleString()}</p>
                     <p className="font-bold text-slate-700 mt-1">{obs.text}</p>
                  </div>
               )) : <p className="text-center py-4 text-[10px] text-slate-400 italic font-bold">Sin novedades registradas.</p>}
            </div>
         </div>
      </Modal>

      {/* MODAL DESVINCULACION */}
      <Modal isOpen={isDesvinculacionModalOpen} onClose={() => setIsDesvinculacionModalOpen(false)} title="Desvinculación Laboral" type="error">
         <div className="space-y-6">
            <div className="p-5 bg-red-50 rounded-2xl border border-red-100 text-center">
               <p className="text-[12px] font-black text-red-700 uppercase">¡ADVERTENCIA DE BAJA LABORAL!</p>
               <p className="text-[10px] font-bold text-red-400 uppercase mt-1">Está procesando la salida de {selectedEmpAction?.name}</p>
            </div>
            <div className="grid grid-cols-1 gap-4">
               <div className="space-y-1">
                  <label className="text-[9px] font-black text-slate-400 uppercase">Fecha de Salida Efectiva</label>
                  <input type="date" className="w-full border-2 p-3 rounded-xl text-xs font-bold" value={desvinculacionData.date} onChange={e => setDesvinculacionData({...desvinculacionData, date: e.target.value})} />
               </div>
               <div className="space-y-1">
                  <label className="text-[9px] font-black text-slate-400 uppercase">Motivo Legal (Código de Trabajo)</label>
                  <select className="w-full border-2 p-3 rounded-xl text-xs font-bold uppercase" value={desvinculacionData.reason} onChange={e => setDesvinculacionData({...desvinculacionData, reason: e.target.value as any})}>
                     {Object.values(TerminationReason).map(v => <option key={v} value={v}>{v}</option>)}
                  </select>
               </div>
               <div className="space-y-1">
                  <label className="text-[9px] font-black text-slate-400 uppercase">Detalles de la Desvinculación</label>
                  <textarea className="w-full border-2 p-3 rounded-xl text-xs font-bold uppercase h-20" value={desvinculacionData.details} onChange={e => setDesvinculacionData({...desvinculacionData, details: e.target.value})} />
               </div>
            </div>
            <div className="flex gap-3">
               <button onClick={() => setIsDesvinculacionModalOpen(false)} className="flex-1 py-4 bg-slate-100 text-slate-500 font-black rounded-xl uppercase text-[10px]">Cancelar</button>
               <button onClick={handleProcessDesvinculacion} className="flex-1 py-4 bg-red-600 text-white font-black rounded-xl uppercase text-[10px] shadow-xl">Confirmar Baja</button>
            </div>
         </div>
      </Modal>

      <Modal isOpen={feedback.isOpen} onClose={() => setFeedback({...feedback, isOpen: false})} title={feedback.title} type={feedback.type}>
        <div className="text-center p-4">
          <p className="text-[11px] font-bold uppercase text-slate-600">{feedback.message}</p>
          <button onClick={() => setFeedback({...feedback, isOpen: false})} className="w-full py-3 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] mt-6">Aceptar</button>
        </div>
      </Modal>
    </div>
  );
};

export default EmployeeModule;

import React, { useState } from 'react';
import { Employee, Payment, AttendanceRecord, CompanyConfig, GlobalSettings, Role } from '../../types.ts';
import Modal from '../../components/Modal.tsx';

interface ReportsModuleProps {
  employees: Employee[];
  payments: Payment[];
  attendance: AttendanceRecord[];
  company: CompanyConfig | null;
  settings: GlobalSettings;
  role: Role;
}

const ReportsModule: React.FC<ReportsModuleProps> = ({ employees, payments = [], attendance = [], company, settings, role }) => {
  const [reportType, setReportType] = useState<'attendance' | 'payments' | 'history' | 'master'>('attendance');
  const [searchTerm, setSearchTerm] = useState('');
  const [feedback, setFeedback] = useState({ isOpen: false, title: '', message: '', type: 'success' as any });

  const generateMasterExcel = () => {
    let csv = "\uFEFF";
    csv += `ARCHIVO MAESTRO INSTITUCIONAL - ${new Date().getFullYear()}\n`;
    csv += `ENTIDAD: ${company?.name || 'ASIST UP'}\n`;
    csv += `FECHA DE REPORTE: ${new Date().toLocaleString()}\n\n`;

    // SECCION 1: PERSONAL ACTIVO
    csv += "--- SECCION 1: REGISTRO MAESTRO DE PERSONAL ---\n";
    csv += "ID,COLABORADOR,CARGO,INGRESO,AFILIADO IESS,MODO RESERVA,DECIMOS,SUELDO,STATUS\n";
    employees.forEach(e => {
      csv += `"${e.identification}","${e.surname} ${e.name}","${e.role}","${e.startDate}","${e.isAffiliated ? 'SI' : 'NO'}","${e.reserveFundType || 'N/A'}","${e.overSalaryType}","${e.salary.toFixed(2)}","${e.status}"\n`;
    });
    csv += "\n";

    // SECCION 2: REPORTE DE PAGOS REALIZADOS
    csv += "--- SECCION 2: REPORTE INTEGRAL DE PAGOS ---\n";
    csv += "VOUCHER,FECHA,BENEFICIARIO,IDENTIFICACION,CONCEPTO,METODO,MONTO,ESTADO\n";
    payments.forEach(p => {
      const emp = employees.find(e => e.id === p.employeeId);
      csv += `"${p.voucherCode}","${new Date(p.date).toLocaleDateString()}","${emp?.surname} ${emp?.name}","${emp?.identification}","${p.type}","${p.method}","${p.amount.toFixed(2)}","${p.status}"\n`;
    });
    csv += "\n";

    // SECCION 3: BITACORA DE NOVEDADES Y OBSERVACIONES
    csv += "--- SECCION 3: BITACORA DE NOVEDADES ADMINISTRATIVAS ---\n";
    csv += "FECHA NOVEDAD,EMPLEADO,DESCRIPCION DE LA NOVEDAD\n";
    employees.forEach(e => {
       if (e.observations && e.observations.length > 0) {
          e.observations.forEach(obs => {
             csv += `"${new Date(obs.date).toLocaleString()}","${e.surname} ${e.name}","${obs.text}"\n`;
          });
       }
    });
    csv += "\n";

    // SECCION 4: HISTORIAL DE DESVINCULACIONES
    csv += "--- SECCION 4: HISTORIAL DE DESVINCULACIONES LABORALES ---\n";
    csv += "EMPLEADO,IDENTIFICACION,CARGO,FECHA INGRESO,FECHA SALIDA,MOTIVO LEGAL,DETALLES\n";
    employees.filter(e => e.status === 'terminated').forEach(e => {
       csv += `"${e.surname} ${e.name}","${e.identification}","${e.role}","${e.startDate}","${e.terminationDate || 'N/A'}","${e.terminationReason || 'N/A'}","${e.terminationDetails || 'N/A'}"\n`;
    });

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `ARCHIVO_MAESTRO_ASISTUP_${new Date().getMonth() + 1}_${new Date().getFullYear()}.csv`;
    link.click();
    setFeedback({ isOpen: true, title: "Archivo Maestro", message: "Consolidado integral descargado correctamente para archivo.", type: "success" });
  };

  const generatePDF = () => {
    window.print();
  };

  const attendanceToDisplay = (attendance || []).filter(a => {
    const emp = employees.find(e => e.id === a.employeeId);
    const searchStr = `${emp?.surname} ${emp?.name} ${emp?.identification} ${a.justification || ""} ${a.status} ${a.type}`.toLowerCase();
    return searchStr.includes(searchTerm.toLowerCase());
  }).sort((a,b) => b.timestamp.localeCompare(a.timestamp));

  const paymentsToDisplay = (payments || []).filter(p => {
    const emp = employees.find(e => e.id === p.employeeId);
    const searchStr = `${emp?.surname} ${emp?.name} ${emp?.identification} ${p.concept} ${p.type} ${p.voucherCode} ${p.method}`.toLowerCase();
    return searchStr.includes(searchTerm.toLowerCase());
  }).sort((a,b) => b.date.localeCompare(a.date));

  const historyToDisplay = employees.filter(e => {
    const searchStr = `${e.name} ${e.surname} ${e.identification} ${e.role} ${e.status}`.toLowerCase();
    return searchStr.includes(searchTerm.toLowerCase());
  }).sort((a,b) => b.startDate.localeCompare(a.startDate));

  return (
    <div className="space-y-6 md:space-y-8 fade-in">
      <div className="flex flex-col md:flex-row justify-between items-center bg-white p-6 md:p-10 rounded-[2.5rem] shadow-sm border border-slate-100 gap-6 no-print">
        <div className="w-full">
          <h2 className="text-2xl font-[950] text-slate-900 uppercase tracking-tighter italic leading-none">Inteligencia de Reportes</h2>
          <div className="flex flex-col sm:flex-row gap-4 mt-8">
            <div className="flex gap-2 overflow-x-auto pb-2 sm:pb-0 no-scrollbar">
              <button onClick={() => {setReportType('attendance'); setSearchTerm('');}} className={`whitespace-nowrap px-6 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${reportType === 'attendance' ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-50 text-slate-400 border'}`}>Asistencia</button>
              <button onClick={() => {setReportType('payments'); setSearchTerm('');}} className={`whitespace-nowrap px-6 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${reportType === 'payments' ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-50 text-slate-400 border'}`}>Nómina</button>
              <button onClick={() => {setReportType('history'); setSearchTerm('');}} className={`whitespace-nowrap px-6 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${reportType === 'history' ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-50 text-slate-400 border'}`}>Historial</button>
              <button onClick={() => {setReportType('master'); setSearchTerm('');}} className={`whitespace-nowrap px-6 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${reportType === 'master' ? 'bg-slate-900 text-white shadow-lg' : 'bg-slate-50 text-slate-400 border'}`}>Maestro</button>
            </div>
            {reportType !== 'master' && (
              <input type="text" placeholder="Filtrar registros..." className="flex-1 p-4 border-2 rounded-2xl text-[11px] font-bold uppercase outline-none focus:border-blue-500" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
            )}
          </div>
        </div>
      </div>

      <div className="bg-white rounded-[2.5rem] shadow-sm border overflow-hidden" id="reports-printable-area">
         {reportType === 'master' ? (
           <div className="p-10 md:p-16 space-y-12 no-print text-center">
              <header className="border-b pb-8">
                <h3 className="text-2xl font-black text-slate-900 uppercase tracking-widest">Generación de Archivo Maestro</h3>
                <p className="text-[11px] font-black text-blue-600 uppercase tracking-widest mt-2 italic">Consolidado mensual de personal, nómina, novedades y desvinculaciones</p>
              </header>

              <div className="max-w-md mx-auto space-y-6">
                 <div className="w-24 h-24 bg-blue-50 text-blue-600 rounded-full flex items-center justify-center text-4xl mx-auto shadow-inner">📦</div>
                 <p className="text-slate-500 font-bold text-[11px] uppercase leading-relaxed">Este reporte exporta toda la base de datos institucional organizada cronológicamente para auditoría y archivo físico.</p>
                 <div className="grid grid-cols-1 gap-3">
                    <button onClick={generateMasterExcel} className="py-5 bg-slate-900 text-white text-[11px] font-black rounded-2xl uppercase tracking-widest shadow-2xl active:scale-95 transition-all">Exportar Master Excel</button>
                    <button onClick={generatePDF} className="py-4 bg-slate-100 text-slate-600 text-[10px] font-black rounded-xl uppercase active:scale-95 transition-all">Vista Previa PDF</button>
                 </div>
              </div>
           </div>
         ) : (
           <div className="p-4 md:p-10">
              <div className="hidden print:block text-center border-b-2 border-black pb-4 mb-6">
                <h1 className="text-2xl font-black uppercase leading-none italic">{company?.name || 'ASIST UP'}</h1>
                <p className="text-[10px] font-bold uppercase mt-2 tracking-widest">REPORTE OFICIAL: {reportType.toUpperCase()}</p>
              </div>
              <div className="table-responsive">
                  <table className="w-full text-left print:table-auto border-collapse">
                      <thead className="bg-slate-50 text-[10px] font-[900] uppercase text-slate-400 print:bg-white print:text-black">
                          {reportType === 'attendance' ? (
                              <tr><th className="p-5 border-b-2">MARCACION</th><th className="p-5 border-b-2">COLABORADOR</th><th className="p-5 border-b-2">MOVIMIENTO</th><th className="p-5 border-b-2 text-center">ESTADO</th></tr>
                          ) : reportType === 'payments' ? (
                              <tr><th className="p-5 border-b-2">COMPROBANTE</th><th className="p-5 border-b-2">BENEFICIARIO</th><th className="p-5 border-b-2">CONCEPTO</th><th className="p-5 border-b-2 text-right">MONTO</th></tr>
                          ) : (
                              <tr><th className="p-5 border-b-2">NOMBRE COMPLETO</th><th className="p-5 border-b-2">CARGO</th><th className="p-5 border-b-2">SITUACION</th><th className="p-5 border-b-2 text-right">ESTADO</th></tr>
                          )}
                      </thead>
                      <tbody className="text-[11px] font-bold uppercase divide-y print:text-black">
                          {reportType === 'attendance' && attendanceToDisplay.map(rec => {
                              const emp = employees.find(e => e.id === rec.employeeId);
                              return (
                                <tr key={rec.id}>
                                  <td className="p-5">{new Date(rec.timestamp).toLocaleString()}</td>
                                  <td className="p-5 font-black">{emp?.surname} {emp?.name}</td>
                                  <td className="p-5">{rec.type}</td>
                                  <td className={`p-5 text-center font-black ${rec.status === 'confirmed' ? 'text-emerald-600' : 'text-red-500'}`}>{rec.status}</td>
                                </tr>
                              );
                          })}
                          {reportType === 'payments' && paymentsToDisplay.map(p => {
                              const emp = employees.find(e => e.id === p.employeeId);
                              return (
                                <tr key={p.id}>
                                  <td className="p-5 font-[950] text-blue-600">{p.voucherCode}</td>
                                  <td className="p-5 font-black">{emp?.surname} {emp?.name}</td>
                                  <td className="p-5">{p.concept}</td>
                                  <td className="p-5 text-right font-black">${p.amount.toFixed(2)}</td>
                                </tr>
                              );
                          })}
                          {reportType === 'history' && historyToDisplay.map(emp => (
                              <tr key={emp.id}>
                                <td className="p-5">{emp.surname} {emp.name}</td>
                                <td className="p-5">{emp.role}</td>
                                <td className="p-5">{emp.status === 'terminated' ? emp.terminationReason : 'ACTIVO'}</td>
                                <td className={`p-5 text-right font-[950] ${emp.status === 'active' ? 'text-emerald-600' : 'text-red-500'}`}>{emp.status}</td>
                              </tr>
                          ))}
                      </tbody>
                  </table>
              </div>
           </div>
         )}
      </div>

      <Modal isOpen={feedback.isOpen} onClose={() => setFeedback({...feedback, isOpen: false})} title={feedback.title} type={feedback.type}>
          <div className="text-center p-6 space-y-6">
              <p className="text-slate-700 font-bold uppercase text-[11px] leading-relaxed italic">{feedback.message}</p>
              <button onClick={() => setFeedback({...feedback, isOpen: false})} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] tracking-widest">Entendido</button>
          </div>
      </Modal>
    </div>
  );
};

export default ReportsModule;

import React, { useState } from 'react';
import { GlobalSettings, Role } from '../../types.ts';
import Modal from '../../components/Modal.tsx';
import LZString from 'lz-string';

interface SettingsModuleProps {
  settings: GlobalSettings;
  onUpdate: (settings: GlobalSettings) => void;
  role: Role;
  onPurge?: () => void;
  allData?: any;
}

const SettingsModule: React.FC<SettingsModuleProps> = ({ settings, onUpdate, role, onPurge, allData }) => {
  const [local, setLocal] = useState<GlobalSettings>({ 
    ...settings, 
    sbuPrev: settings.sbuPrev || 460.00,
    holidays: settings.holidays || [],
    schedule: {
      ...(settings.schedule || {
        monFri: { in1: '08:30', out1: '13:00', in2: '15:00', out2: '18:00' },
        sat: { in: '08:30', out: '13:00' },
        halfDayOff: 'Miércoles tarde'
      })
    }
  });

  const [showPurgeConfirm, setShowPurgeConfirm] = useState(false);
  const [purgePassword, setPurgePassword] = useState('');
  const [feedback, setFeedback] = useState<{isOpen: boolean, title: string, message: string, type: 'success' | 'error' | 'info' | 'warning'}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  const handleBackup = () => {
    try {
      if (!allData) {
         setFeedback({ isOpen: true, title: "Falta de Datos", message: "No hay información para respaldar.", type: "error" });
         return;
      }
      const dataStr = JSON.stringify(allData);
      const compressed = LZString.compressToEncodedURIComponent(dataStr);
      const blob = new Blob([compressed], { type: 'application/octet-stream' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `RESPALDO_ASISTUP_${new Date().toISOString().split('T')[0]}.bin`;
      link.click();
      setFeedback({ isOpen: true, title: "Respaldo Generado", message: "El archivo binario de seguridad ha sido descargado exitosamente.", type: "success" });
    } catch (e) {
      setFeedback({ isOpen: true, title: "Error", message: "Fallo al generar el paquete de datos.", type: "error" });
    }
  };

  const handleResetDeviceConfig = () => {
    setFeedback({ 
      isOpen: true, 
      title: "Confirmación de Reset", 
      message: "¿Desea restablecer la configuración local de este equipo? Deberá seleccionar el modo de acceso nuevamente.", 
      type: "warning" 
    });
    localStorage.removeItem('app_mode');
    setTimeout(() => window.location.reload(), 2000);
  };

  const handlePurgeExecution = () => {
    if (purgePassword === 'admin123') {
      onPurge?.();
      setShowPurgeConfirm(false);
      setPurgePassword('');
      setFeedback({ 
        isOpen: true, 
        title: "Sistema Limpio", 
        message: "Toda la información ha sido eliminada permanentemente.", 
        type: "success" 
      });
    } else {
      setFeedback({ 
        isOpen: true, 
        title: "Acceso Denegado", 
        message: "Contraseña incorrecta. Acción bloqueada por seguridad institucional.", 
        type: "error" 
      });
    }
  };

  const handleSave = () => {
    if (role !== Role.SUPER_ADMIN) return;
    onUpdate(local);
    setFeedback({ isOpen: true, title: "Sincronizado", message: "Parámetros globales institucionales actualizados correctamente.", type: "success" });
  };

  return (
    <div className="max-w-4xl mx-auto space-y-10 fade-in pb-20">
      <div className="bg-white p-8 md:p-12 rounded-[2.5rem] md:rounded-[3.5rem] shadow-sm border space-y-10">
        <header className="border-b pb-6 flex items-center gap-4">
          <div className="w-10 h-10">
             <svg viewBox="0 0 100 100" className="w-full h-full drop-shadow-[0_0_8px_rgba(59,130,246,0.5)]">
               <circle cx="50" cy="50" r="45" fill="none" stroke="#3b82f6" strokeWidth="6" strokeDasharray="15 5" />
               <circle cx="50" cy="50" r="6" fill="#3b82f6" />
             </svg>
          </div>
          <h2 className="text-2xl font-[900] text-slate-900 uppercase italic">Parámetros del Sistema</h2>
        </header>

        <section className="grid grid-cols-1 md:grid-cols-2 gap-8">
           <div className="space-y-3">
              <label className="text-[10px] font-black text-blue-700 uppercase tracking-widest">SBU Año Vigente</label>
              <input type="number" step="0.01" className="w-full p-4 border-2 rounded-2xl font-[950] text-2xl focus:border-blue-500 outline-none" value={local.sbu} onChange={e => setLocal({...local, sbu: Number(e.target.value)})} />
           </div>
           <div className="space-y-3">
              <label className="text-[10px] font-black text-blue-700 uppercase tracking-widest">Tasa IESS Personal (%)</label>
              <input type="number" step="0.0001" className="w-full p-4 border-2 rounded-2xl font-[950] text-2xl focus:border-blue-500 outline-none" value={local.iessRate * 100} onChange={e => setLocal({...local, iessRate: Number(e.target.value) / 100})} />
           </div>
        </section>

        <section className="bg-slate-50 p-8 rounded-[2rem] border border-slate-100 space-y-6">
           <h3 className="text-[11px] font-black text-slate-400 uppercase tracking-widest border-b pb-4">Herramientas Administrativas</h3>
           <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <button onClick={handleBackup} className="p-6 bg-white border border-slate-200 rounded-2xl hover:border-blue-500 transition-all text-left flex items-center gap-4 group">
                 <div className="w-12 h-12 bg-blue-50 text-blue-600 rounded-xl flex items-center justify-center text-xl">💾</div>
                 <div>
                    <p className="text-[11px] font-black text-slate-900 uppercase leading-none">Generar Respaldo</p>
                    <p className="text-[9px] text-slate-400 font-bold uppercase mt-2">Exportación de Datos (.bin)</p>
                 </div>
              </button>
              <button onClick={handleResetDeviceConfig} className="p-6 bg-white border border-slate-200 rounded-2xl hover:border-orange-500 transition-all text-left flex items-center gap-4 group">
                 <div className="w-12 h-12 bg-orange-50 text-orange-600 rounded-xl flex items-center justify-center text-xl">🔄</div>
                 <div>
                    <p className="text-[11px] font-black text-slate-900 uppercase leading-none">Resetear Terminal</p>
                    <p className="text-[9px] text-slate-400 font-bold uppercase mt-2">Configuración de Acceso Local</p>
                 </div>
              </button>
           </div>
           <div className="pt-4">
              <button onClick={() => setShowPurgeConfirm(true)} className="w-full p-6 bg-red-50 text-red-600 border border-red-100 rounded-2xl hover:bg-red-600 hover:text-white transition-all text-left flex items-center gap-4 group">
                 <div className="w-12 h-12 bg-white/50 rounded-xl flex items-center justify-center text-xl">🗑️</div>
                 <div>
                    <p className="text-[11px] font-black uppercase leading-none">Limpiar Sistema</p>
                    <p className="text-[9px] font-bold uppercase mt-2 opacity-70">Eliminación completa y permanente de datos</p>
                 </div>
              </button>
           </div>
        </section>

        <button onClick={handleSave} className="w-full py-6 bg-slate-900 text-white font-[950] rounded-[2rem] shadow-2xl uppercase text-[11px] tracking-widest active:scale-95 transition-all">Sincronizar Parámetros Globales</button>
      </div>

      <Modal isOpen={showPurgeConfirm} onClose={() => setShowPurgeConfirm(false)} title="ALERTA DE SEGURIDAD" type="error">
         <div className="space-y-8 text-center p-4">
            <div className="w-20 h-20 bg-red-100 text-red-600 rounded-full flex items-center justify-center text-4xl mx-auto shadow-inner">🔒</div>
            <div>
               <h3 className="text-xl font-black text-slate-900 uppercase italic leading-none">Confirmación Crítica</h3>
               <p className="text-[11px] text-slate-500 font-bold uppercase mt-4">Ingrese la contraseña para eliminar permanentemente los registros.</p>
            </div>
            <div className="space-y-4">
               <input 
                 type="password" 
                 value={purgePassword}
                 onChange={e => setPurgePassword(e.target.value)}
                 className="w-full p-4 border-2 rounded-xl text-center text-2xl font-black focus:border-red-600 outline-none uppercase"
                 placeholder="••••••••"
                 autoFocus
               />
               <div className="flex gap-3">
                  <button onClick={() => { setShowPurgeConfirm(false); setPurgePassword(''); }} className="flex-1 py-4 bg-slate-100 text-slate-600 font-black rounded-xl uppercase text-[10px]">Cancelar</button>
                  <button onClick={handlePurgeExecution} className="flex-1 py-4 bg-red-600 text-white font-black rounded-xl uppercase text-[10px] shadow-xl">Autorizar Borrado</button>
               </div>
            </div>
         </div>
      </Modal>

      <Modal isOpen={feedback.isOpen} onClose={() => setFeedback({...feedback, isOpen: false})} title={feedback.title} type={feedback.type as any}>
          <div className="text-center space-y-6 p-4">
              <p className="text-slate-600 font-bold uppercase text-[11px] leading-relaxed">{feedback.message}</p>
              <button onClick={() => setFeedback({...feedback, isOpen: false})} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] tracking-widest active:scale-95">Aceptar</button>
          </div>
      </Modal>
    </div>
  );
};

