import React, { useState } from 'react';
import { Employee, Payment, AttendanceRecord, CompanyConfig, GlobalSettings, Role } from '../../types.ts';
import Modal from '../../components/Modal.tsx';
import JSZip from 'jszip';

interface ReportsModuleProps {
  employees: Employee[];
  payments: Payment[];
  attendance: AttendanceRecord[];
  company: CompanyConfig | null;
  settings: GlobalSettings;
  role: Role;
}

const ReportsModule: React.FC<ReportsModuleProps> = ({ employees, payments = [], attendance = [], company, settings, role }) => {
  const [reportType, setReportType] = useState<'attendance' | 'payments' | 'history' | 'master'>('attendance');
  const [searchTerm, setSearchTerm] = useState('');
  const [isZipping, setIsZipping] = useState(false);
  const [feedback, setFeedback] = useState({ isOpen: false, title: '', message: '', type: 'success' as any });

  const getCSVData = (type: 'employees' | 'payroll' | 'attendance' | 'novedades' | 'bajas') => {
    let csv = "\uFEFF";
    if (type === 'employees') {
      csv += "IDENTIFICACION,APELLIDOS Y NOMBRES,CARGO,FECHA INGRESO,ESTADO,SALARIO,AFILIADO IESS,MODO RESERVA,DECIMOS\n";
      employees.forEach(e => {
        csv += `"${e.identification}","${e.surname} ${e.name}","${e.role}","${e.startDate}","${e.status}","${e.salary.toFixed(2)}","${e.isAffiliated ? 'SI' : 'NO'}","${e.reserveFundType || 'N/A'}","${e.overSalaryType}"\n`;
      });
    } else if (type === 'payroll') {
      csv += "VOUCHER,FECHA,BENEFICIARIO,IDENTIFICACION,CONCEPTO,METODO,MONTO,ESTADO\n";
      payments.forEach(p => {
        const emp = employees.find(e => e.id === p.employeeId);
        csv += `"${p.voucherCode}","${new Date(p.date).toLocaleDateString()}","${emp?.surname} ${emp?.name}","${emp?.identification}","${p.type}","${p.method}","${p.amount.toFixed(2)}","${p.status}"\n`;
      });
    } else if (type === 'attendance') {
      csv += "FECHA,ID COLABORADOR,NOMBRE,TIPO,ESTADO,ATRASO,JUSTIFICACION\n";
      attendance.forEach(a => {
        const emp = employees.find(e => e.id === a.employeeId);
        csv += `"${new Date(a.timestamp).toLocaleString()}","${emp?.identification}","${emp?.surname} ${emp?.name}","${a.type}","${a.status}","${a.isLate ? 'SI' : 'NO'}","${a.justification || ''}"\n`;
      });
    } else if (type === 'novedades') {
      csv += "FECHA NOVEDAD,EMPLEADO,DESCRIPCION DE LA NOVEDAD\n";
      employees.forEach(e => {
        if (e.observations) e.observations.forEach(obs => {
          csv += `"${new Date(obs.date).toLocaleString()}","${e.surname} ${e.name}","${obs.text}"\n`;
        });
      });
    } else if (type === 'bajas') {
      csv += "EMPLEADO,IDENTIFICACION,CARGO,FECHA INGRESO,FECHA SALIDA,MOTIVO LEGAL,DETALLES\n";
      employees.filter(e => e.status === 'terminated').forEach(e => {
        csv += `"${e.surname} ${e.name}","${e.identification}","${e.role}","${e.startDate}","${e.terminationDate || 'N/A'}","${e.terminationReason || 'N/A'}","${e.terminationDetails || 'N/A'}"\n`;
      });
    }
    return csv;
  };

  const handleDownloadMasterZip = async () => {
    setIsZipping(true);
    try {
      const zip = new JSZip();
      const folder = zip.folder(`ARCHIVO_MAESTRO_${new Date().getFullYear()}_${new Date().getMonth() + 1}`);

      folder?.file("1_REGISTRO_PERSONAL.csv", getCSVData('employees'));
      folder?.file("2_REPORTE_PAGOS.csv", getCSVData('payroll'));
      folder?.file("3_BITACORA_ASISTENCIA.csv", getCSVData('attendance'));
      folder?.file("4_NOVEDADES_PERSONAL.csv", getCSVData('novedades'));
      folder?.file("5_HISTORIAL_BAJAS.csv", getCSVData('bajas'));

      const blob = await zip.generateAsync({ type: "blob" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = `MAESTRO_ASISTUP_PACK_${new Date().toISOString().split('T')[0]}.zip`;
      link.click();

      setFeedback({ 
        isOpen: true, 
        title: "Paquete ZIP Generado", 
        message: "Se ha descargado el contenedor comprimido con todos los reportes institucionales obligatorios.", 
        type: "success" 
      });
    } catch (e) {
      setFeedback({ isOpen: true, title: "Error", message: "No se pudo generar el archivo comprimido.", type: "error" });
    } finally {
      setIsZipping(false);
    }
  };

  const generateReportExcel = (type: any) => {
    const csv = getCSVData(type);
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `REPORTE_${type.toUpperCase()}_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  };

  const generateReportPDF = (type: any) => {
    setReportType(type);
    setTimeout(() => window.print(), 500);
  };

  const attendanceToDisplay = (attendance || []).filter(a => {
    const emp = employees.find(e => e.id === a.employeeId);
    const searchStr = `${emp?.surname} ${emp?.name} ${emp?.identification} ${a.justification || ""} ${a.status} ${a.type}`.toLowerCase();
    return searchStr.includes(searchTerm.toLowerCase());
  }).sort((a,b) => b.timestamp.localeCompare(a.timestamp));

  const paymentsToDisplay = (payments || []).filter(p => {
    const emp = employees.find(e => e.id === p.employeeId);
    const searchStr = `${emp?.surname} ${emp?.name} ${emp?.identification} ${p.concept} ${p.type} ${p.voucherCode} ${p.method}`.toLowerCase();
    return searchStr.includes(searchTerm.toLowerCase());
  }).sort((a,b) => b.date.localeCompare(a.date));

  const historyToDisplay = employees.filter(e => {
    const searchStr = `${e.name} ${e.surname} ${e.identification} ${e.role} ${e.status}`.toLowerCase();
    return searchStr.includes(searchTerm.toLowerCase());
  }).sort((a,b) => b.startDate.localeCompare(a.startDate));

  return (
    <div className="space-y-6 md:space-y-8 fade-in">
      <div className="flex flex-col md:flex-row justify-between items-center bg-white p-6 md:p-10 rounded-[2.5rem] shadow-sm border border-slate-100 gap-6 no-print">
        <div className="w-full">
          <h2 className="text-2xl font-[950] text-slate-900 uppercase tracking-tighter italic leading-none">Inteligencia de Reportes</h2>
          <div className="flex flex-col sm:flex-row gap-4 mt-8">
            <div className="flex gap-2 overflow-x-auto pb-2 sm:pb-0 no-scrollbar">
              <button onClick={() => {setReportType('attendance'); setSearchTerm('');}} className={`whitespace-nowrap px-6 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${reportType === 'attendance' ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-50 text-slate-400 border'}`}>Asistencia</button>
              <button onClick={() => {setReportType('payments'); setSearchTerm('');}} className={`whitespace-nowrap px-6 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${reportType === 'payments' ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-50 text-slate-400 border'}`}>Nómina</button>
              <button onClick={() => {setReportType('history'); setSearchTerm('');}} className={`whitespace-nowrap px-6 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${reportType === 'history' ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-50 text-slate-400 border'}`}>Historial</button>
              <button onClick={() => {setReportType('master'); setSearchTerm('');}} className={`whitespace-nowrap px-6 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${reportType === 'master' ? 'bg-slate-900 text-white shadow-lg' : 'bg-slate-50 text-slate-400 border'}`}>Maestro</button>
            </div>
            {reportType !== 'master' && (
              <input type="text" placeholder="Filtrar registros..." className="flex-1 p-4 border-2 rounded-2xl text-[11px] font-bold uppercase outline-none focus:border-blue-500" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
            )}
          </div>
        </div>
      </div>

      <div className="bg-white rounded-[2.5rem] shadow-sm border overflow-hidden" id="reports-printable-area">
         {reportType === 'master' ? (
           <div className="p-10 md:p-16 space-y-12 no-print">
              <header className="border-b pb-8 text-center">
                <h3 className="text-2xl font-black text-slate-900 uppercase tracking-widest">Generación de Archivo Maestro</h3>
                <p className="text-[11px] font-black text-blue-600 uppercase tracking-widest mt-2 italic">Consolidado integral de gestión administrativa</p>
              </header>

              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                 {[
                   { id: 'employees', title: 'Fichas de Personal', icon: '👥', desc: 'Identidad, sueldos y beneficios.' },
                   { id: 'payroll', title: 'Reporte de Pagos', icon: '💰', desc: 'Egresos, vouchers y transferencias.' },
                   { id: 'attendance', title: 'Bitácora Asistencia', icon: '🕒', desc: 'Marcaciones, atrasos y media jornada.' },
                   { id: 'novedades', title: 'Historial Novedades', icon: '📝', desc: 'Amonestaciones y observaciones.' },
                   { id: 'bajas', title: 'Desvinculaciones', icon: '🚪', desc: 'Registro de bajas y motivos legales.' }
                 ].map(seg => (
                   <div key={seg.id} className="bg-slate-50 p-6 rounded-[2rem] border border-slate-100 flex flex-col justify-between">
                      <div className="mb-4">
                        <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-xl shadow-sm mb-3">{seg.icon}</div>
                        <h4 className="text-[11px] font-black uppercase tracking-widest text-slate-900">{seg.title}</h4>
                        <p className="text-[9px] text-slate-400 font-bold uppercase mt-1 leading-tight">{seg.desc}</p>
                      </div>
                      <div className="flex gap-2">
                        <button onClick={() => generateReportExcel(seg.id)} className="flex-1 py-2.5 bg-emerald-600 text-white text-[9px] font-black rounded-lg uppercase shadow-md active:scale-95">Excel</button>
                        <button onClick={() => generateReportPDF(seg.id as any)} className="flex-1 py-2.5 bg-blue-700 text-white text-[9px] font-black rounded-lg uppercase shadow-md active:scale-95">PDF</button>
                      </div>
                   </div>
                 ))}
              </div>

              <div className="pt-10 border-t flex flex-col items-center gap-6">
                 <button 
                  onClick={handleDownloadMasterZip} 
                  disabled={isZipping}
                  className="w-full max-w-md py-6 bg-slate-900 text-white font-black rounded-[2rem] uppercase text-[11px] tracking-[0.3em] shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-4 group"
                 >
                   <span className="text-xl group-hover:animate-bounce">{isZipping ? '⌛' : '📦'}</span>
                   {isZipping ? 'GENERANDO PAQUETE...' : 'Descargar Todo en .ZIP'}
                 </button>
                 <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest text-center italic">Este contenedor incluye todos los archivos mencionados arriba en formato Excel para respaldo institucional.</p>
              </div>
           </div>
         ) : (
           <div className="p-4 md:p-10">
              <div className="hidden print:block text-center border-b-2 border-black pb-4 mb-6">
                <h1 className="text-2xl font-black uppercase leading-none italic">{company?.name || 'ASIST UP'}</h1>
                <p className="text-[10px] font-bold uppercase mt-2 tracking-widest">REPORTE OFICIAL: {reportType.toUpperCase()}</p>
              </div>
              <div className="table-responsive">
                  <table className="w-full text-left print:table-auto border-collapse">
                      <thead className="bg-slate-50 text-[10px] font-[900] uppercase text-slate-400 print:bg-white print:text-black">
                          {reportType === 'attendance' ? (
                              <tr><th className="p-5 border-b-2">MARCACION</th><th className="p-5 border-b-2">COLABORADOR</th><th className="p-5 border-b-2">MOVIMIENTO</th><th className="p-5 border-b-2 text-center">ESTADO</th></tr>
                          ) : reportType === 'payments' ? (
                              <tr><th className="p-5 border-b-2">COMPROBANTE</th><th className="p-5 border-b-2">BENEFICIARIO</th><th className="p-5 border-b-2">CONCEPTO</th><th className="p-5 border-b-2 text-right">MONTO</th></tr>
                          ) : (
                              <tr><th className="p-5 border-b-2">NOMBRE COMPLETO</th><th className="p-5 border-b-2">CARGO</th><th className="p-5 border-b-2 text-center">SITUACION</th><th className="p-5 border-b-2 text-right">ESTADO</th></tr>
                          )}
                      </thead>
                      <tbody className="text-[11px] font-bold uppercase divide-y print:text-black">
                          {reportType === 'attendance' && attendanceToDisplay.map(rec => {
                              const emp = employees.find(e => e.id === rec.employeeId);
                              return (
                                <tr key={rec.id}>
                                  <td className="p-5">{new Date(rec.timestamp).toLocaleString()}</td>
                                  <td className="p-5 font-black">{emp?.surname} {emp?.name}</td>
                                  <td className="p-5">{rec.type}</td>
                                  <td className={`p-5 text-center font-black ${rec.status === 'confirmed' ? 'text-emerald-600' : 'text-red-500'}`}>{rec.status}</td>
                                </tr>
                              );
                          })}
                          {reportType === 'payments' && paymentsToDisplay.map(p => {
                              const emp = employees.find(e => e.id === p.employeeId);
                              return (
                                <tr key={p.id}>
                                  <td className="p-5 font-[950] text-blue-600">{p.voucherCode}</td>
                                  <td className="p-5 font-black">{emp?.surname} {emp?.name}</td>
                                  <td className="p-5">{p.concept}</td>
                                  <td className="p-5 text-right font-black">${p.amount.toFixed(2)}</td>
                                </tr>
                              );
                          })}
                          {reportType === 'history' && historyToDisplay.map(emp => (
                              <tr key={emp.id}>
                                <td className="p-5">{emp.surname} {emp.name}</td>
                                <td className="p-5">{emp.role}</td>
                                <td className="p-5 text-center">{emp.status === 'terminated' ? emp.terminationReason : 'ACTIVO'}</td>
                                <td className={`p-5 text-right font-[950] ${emp.status === 'active' ? 'text-emerald-600' : 'text-red-500'}`}>{emp.status}</td>
                              </tr>
                          ))}
                      </tbody>
                  </table>
              </div>
           </div>
         )}
      </div>

      <Modal isOpen={feedback.isOpen} onClose={() => setFeedback({...feedback, isOpen: false})} title={feedback.title} type={feedback.type}>
          <div className="text-center p-6 space-y-6">
              <p className="text-slate-700 font-bold uppercase text-[11px] leading-relaxed italic">{feedback.message}</p>
              <button onClick={() => setFeedback({...feedback, isOpen: false})} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] tracking-widest">Entendido</button>
          </div>
      </Modal>
    </div>
  );
};

export default ReportsModule;

import React, { useState, useEffect } from 'react';
import { Employee, Role, BloodType, Gender, CivilStatus, AbsenceRecord, TerminationReason } from '../../types.ts';
import Modal from '../../components/Modal.tsx';

interface EmployeeModuleProps {
  employees: Employee[];
  onUpdate: (employees: Employee[]) => void;
  role: Role;
  attendance: any[];
  payments: any[];
  company: any;
}

const EmployeeModule: React.FC<EmployeeModuleProps> = ({ employees, onUpdate, role, company }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingEmp, setEditingEmp] = useState<Employee | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [showArchived, setShowArchived] = useState(false);

  // Estados para Novedades y Desvinculación
  const [selectedEmpAction, setSelectedEmpAction] = useState<Employee | null>(null);
  const [isNovedadModalOpen, setIsNovedadModalOpen] = useState(false);
  const [isDesvinculacionModalOpen, setIsDesvinculacionModalOpen] = useState(false);

  const [novedadText, setNovedadText] = useState('');
  const [desvinculacionData, setDesvinculacionData] = useState({
    date: new Date().toISOString().split('T')[0],
    reason: TerminationReason.VOLUNTARY,
    details: ''
  });

  const [feedback, setFeedback] = useState<{isOpen: boolean, title: string, message: string, type: 'success' | 'error' | 'info'}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  const initialForm: Partial<Employee> = {
    name: '', surname: '', identification: '', birthDate: '', phone: '', email: '', 
    gender: Gender.MASCULINO, civilStatus: CivilStatus.SOLTERO,
    origin: 'ECUATORIANA', address: '', 
    bloodType: BloodType.O_POS, startDate: new Date().toISOString().split('T')[0],
    role: Role.EMPLOYEE, salary: 482.00, status: 'active' as const, photo: '', pin: '',
    emergencyContact: { name: '', phone: '' },
    isFixed: true, isAffiliated: true, 
    overSalaryType: 'monthly', 
    reserveFundType: 'monthly', 
    bankInfo: { ifi: '', type: 'Ahorros', account: '' },
    absences: [],
    observations: []
  };

  const [form, setForm] = useState<Partial<Employee>>(initialForm);

  const handleSave = () => {
    if (!form.name || !form.surname || !form.identification || !form.salary || !form.role) {
      setFeedback({ isOpen: true, title: "Faltan Datos", message: "Nombre, apellido, cédula, cargo y sueldo son obligatorios.", type: "error" });
      return;
    }

    let updatedList: Employee[];
    if (editingEmp) {
      updatedList = employees.map(e => e.id === editingEmp.id ? { ...e, ...form } as Employee : e);
      setFeedback({ isOpen: true, title: "Sincronizado", message: "Expediente maestro actualizado correctamente.", type: "success" });
    } else {
      const autoPin = Math.floor(100000 + Math.random() * 900000).toString();
      const newEmp: Employee = { 
        ...form, 
        id: Math.random().toString(36).substr(2, 9), 
        pin: autoPin, 
        pinChanged: false, 
        pinNeedsReset: false, 
        status: 'active' as const 
      } as Employee;
      updatedList = [...employees, newEmp];
      setFeedback({ isOpen: true, title: "Ingreso Exitoso", message: `Colaborador registrado. PIN de Marcación: ${autoPin}.`, type: "success" });
    }
    onUpdate(updatedList);
    setIsModalOpen(false);
  };

  const handleAddNovedad = () => {
    if (!novedadText.trim() || !selectedEmpAction) return;
    const newNovedad = { date: new Date().toISOString(), text: novedadText.toUpperCase() };
    const updated = employees.map(e => e.id === selectedEmpAction.id ? {
      ...e,
      observations: [newNovedad, ...(e.observations || [])]
    } : e);
    onUpdate(updated);
    setNovedadText('');
    setIsNovedadModalOpen(false);
    setFeedback({ isOpen: true, title: "Novedad Registrada", message: "La novedad ha sido añadida al historial del empleado.", type: "success" });
  };

  const handleProcessDesvinculacion = () => {
    if (!selectedEmpAction) return;
    const updated = employees.map(e => e.id === selectedEmpAction.id ? {
      ...e,
      status: 'terminated' as const,
      terminationDate: desvinculacionData.date,
      terminationReason: desvinculacionData.reason,
      terminationDetails: desvinculacionData.details.toUpperCase()
    } : e);
    onUpdate(updated);
    setIsDesvinculacionModalOpen(false);
    setFeedback({ isOpen: true, title: "Baja Procesada", message: "El empleado ha sido desvinculado del sistema correctamente.", type: "success" });
  };

  const filteredEmployees = employees.filter(e => {
    const searchString = `${e.name} ${e.surname} ${e.identification}`.toLowerCase();
    const matchesSearch = searchString.includes(searchTerm.toLowerCase());
    return showArchived 
      ? matchesSearch && (e.status === 'archived' || e.status === 'terminated') 
      : matchesSearch && e.status === 'active';
  });

  return (
    <div className="space-y-6 fade-in">
      <div className="bg-white p-6 rounded-3xl md:rounded-[2.5rem] shadow-sm border border-slate-100 flex flex-col md:flex-row justify-between items-center no-print gap-4">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10">
             <svg viewBox="0 0 100 100" className="w-full h-full drop-shadow-[0_0_8px_rgba(59,130,246,0.3)]">
               <circle cx="50" cy="50" r="45" fill="none" stroke="#3b82f6" strokeWidth="6" strokeDasharray="12 4" />
               <path d="M50 30 V70 M30 50 H70" stroke="#3b82f6" strokeWidth="8" strokeLinecap="round" />
             </svg>
          </div>
          <div>
            <h2 className="text-xl font-[950] text-slate-900 uppercase">Gestión de Personal</h2>
            <div className="flex gap-4 mt-1">
