import React, { useState } from 'react';
import { GlobalSettings, Role } from '../../types.ts';
import Modal from '../../components/Modal.tsx';
import LZString from 'lz-string';

interface SettingsModuleProps {
  settings: GlobalSettings;
  onUpdate: (settings: GlobalSettings) => void;
  role: Role;
  onPurge?: () => void;
  allData?: any;
}

const SettingsModule: React.FC<SettingsModuleProps> = ({ settings, onUpdate, role, onPurge, allData }) => {
  const [local, setLocal] = useState<GlobalSettings>({ 
    ...settings, 
    sbuPrev: settings.sbuPrev || 460.00,
    holidays: settings.holidays || [],
    schedule: {
      ...(settings.schedule || {
        monFri: { in1: '08:30', out1: '13:00', in2: '15:00', out2: '18:00' },
        sat: { in: '08:30', out: '13:00' },
        halfDayOff: 'Miércoles tarde'
      })
    }
  });

  const [showPurgeConfirm, setShowPurgeConfirm] = useState(false);
  const [purgePassword, setPurgePassword] = useState('');
  const [feedback, setFeedback] = useState<{isOpen: boolean, title: string, message: string, type: 'success' | 'error' | 'info' | 'warning'}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  const handleBackup = () => {
    try {
      if (!allData) {
         setFeedback({ isOpen: true, title: "Falta de Datos", message: "No hay información para respaldar.", type: "error" });
         return;
      }
      const dataStr = JSON.stringify(allData);
      const compressed = LZString.compressToEncodedURIComponent(dataStr);
      const blob = new Blob([compressed], { type: 'application/octet-stream' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `RESPALDO_ASISTUP_${new Date().toISOString().split('T')[0]}.bin`;
      link.click();
      setFeedback({ isOpen: true, title: "Respaldo Generado", message: "Descarga de seguridad binaria completada.", type: "success" });
    } catch (e) {
      setFeedback({ isOpen: true, title: "Error", message: "Fallo al generar el respaldo.", type: "error" });
    }
  };

  const handleResetDeviceConfig = () => {
    setFeedback({ 
      isOpen: true, 
      title: "Confirmación de Reset", 
      message: "¿Desea restablecer la configuración de acceso local? Deberá configurar el modo nuevamente.", 
      type: "warning" 
    });
    localStorage.removeItem('app_mode');
    setTimeout(() => window.location.reload(), 2000);
  };

  const handlePurgeExecution = () => {
    if (purgePassword === 'admin123') {
      onPurge?.();
      setShowPurgeConfirm(false);
      setPurgePassword('');
      setFeedback({ 
        isOpen: true, 
        title: "Limpieza Exitosa", 
        message: "Toda la información ha sido eliminada del sistema.", 
        type: "success" 
      });
    } else {
      setFeedback({ 
        isOpen: true, 
        title: "Clave Incorrecta", 
        message: "Autorización denegada por contraseña inválida.", 
        type: "error" 
      });
    }
  };

  const handleSave = () => {
    if (role !== Role.SUPER_ADMIN) return;
    onUpdate(local);
    setFeedback({ isOpen: true, title: "Actualizado", message: "Parámetros institucionales sincronizados.", type: "success" });
  };

  return (
    <div className="max-w-4xl mx-auto space-y-10 fade-in pb-20">
      <div className="bg-white p-8 md:p-12 rounded-[2.5rem] md:rounded-[3.5rem] shadow-sm border space-y-10">
        <header className="border-b pb-6 flex items-center gap-4">
          <div className="w-10 h-10">
             <svg viewBox="0 0 100 100" className="w-full h-full drop-shadow-[0_0_8px_rgba(59,130,246,0.5)]">
               <circle cx="50" cy="50" r="45" fill="none" stroke="#3b82f6" strokeWidth="6" strokeDasharray="15 5" />
               <circle cx="50" cy="50" r="6" fill="#3b82f6" />
             </svg>
          </div>
          <h2 className="text-2xl font-[900] text-slate-900 uppercase italic">Ajustes del Sistema</h2>
        </header>

        <section className="grid grid-cols-1 md:grid-cols-2 gap-8">
           <div className="space-y-3">
              <label className="text-[10px] font-black text-blue-700 uppercase tracking-widest">SBU Año Vigente</label>
              <input type="number" step="0.01" className="w-full p-4 border-2 rounded-2xl font-[950] text-2xl focus:border-blue-500 outline-none" value={local.sbu} onChange={e => setLocal({...local, sbu: Number(e.target.value)})} />
           </div>
           <div className="space-y-3">
              <label className="text-[10px] font-black text-blue-700 uppercase tracking-widest">Aporte IESS Personal (%)</label>
              <input type="number" step="0.0001" className="w-full p-4 border-2 rounded-2xl font-[950] text-2xl focus:border-blue-500 outline-none" value={local.iessRate * 100} onChange={e => setLocal({...local, iessRate: Number(e.target.value) / 100})} />
           </div>
        </section>

        <section className="bg-slate-50 p-8 rounded-[2rem] border border-slate-100 space-y-6">
           <h3 className="text-[11px] font-black text-slate-400 uppercase tracking-widest border-b pb-4">Herramientas de Mantenimiento</h3>
           <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <button onClick={handleBackup} className="p-6 bg-white border border-slate-200 rounded-2xl hover:border-blue-500 transition-all text-left flex items-center gap-4 group">
                 <div className="w-12 h-12 bg-blue-50 text-blue-600 rounded-xl flex items-center justify-center text-xl">💾</div>
                 <div>
                    <p className="text-[11px] font-black text-slate-900 uppercase leading-none">Respaldar Datos</p>
                    <p className="text-[9px] text-slate-400 font-bold uppercase mt-2">Exportación Global (.bin)</p>
                 </div>
              </button>
              <button onClick={handleResetDeviceConfig} className="p-6 bg-white border border-slate-200 rounded-2xl hover:border-orange-500 transition-all text-left flex items-center gap-4 group">
                 <div className="w-12 h-12 bg-orange-50 text-orange-600 rounded-xl flex items-center justify-center text-xl">🔄</div>
                 <div>
                    <p className="text-[11px] font-black text-slate-900 uppercase leading-none">Restaurar Equipo</p>
                    <p className="text-[9px] text-slate-400 font-bold uppercase mt-2">Configuración Inicial Local</p>
                 </div>
              </button>
           </div>
           <div className="pt-4">
              <button onClick={() => setShowPurgeConfirm(true)} className="w-full p-6 bg-red-50 text-red-600 border border-red-100 rounded-2xl hover:bg-red-600 hover:text-white transition-all text-left flex items-center gap-4 group">
                 <div className="w-12 h-12 bg-white/50 rounded-xl flex items-center justify-center text-xl">🗑️</div>
                 <div>
                    <p className="text-[11px] font-black uppercase leading-none">Vaciar Base de Datos</p>
                    <p className="text-[9px] font-bold uppercase mt-2 opacity-70">Acción crítica protegida por clave</p>
                 </div>
              </button>
           </div>
        </section>

        <button onClick={handleSave} className="w-full py-6 bg-slate-900 text-white font-[950] rounded-[2rem] shadow-2xl uppercase text-[11px] tracking-widest active:scale-95 transition-all">Sincronizar Maestro Administrativo</button>
      </div>

      <Modal isOpen={showPurgeConfirm} onClose={() => { setShowPurgeConfirm(false); setPurgePassword(''); }} title="AUTORIZACIÓN REQUERIDA" type="error">
         <div className="space-y-8 text-center p-4">
            <div className="w-20 h-20 bg-red-100 text-red-600 rounded-full flex items-center justify-center text-4xl mx-auto shadow-inner animate-pulse">🔒</div>
            <div>
               <h3 className="text-xl font-black text-slate-900 uppercase italic">Verificación Crítica</h3>
               <p className="text-[11px] text-slate-500 font-bold uppercase mt-4">Ingrese la contraseña administrativa para borrar todo el sistema.</p>
            </div>
            <div className="space-y-4">
               <input 
                 type="password" 
                 value={purgePassword}
                 onChange={e => setPurgePassword(e.target.value)}
                 className="w-full p-4 border-2 rounded-xl text-center text-2xl font-black focus:border-red-600 outline-none uppercase"
                 placeholder="••••••••"
                 autoFocus
               />
               <div className="flex gap-3">
                  <button onClick={() => { setShowPurgeConfirm(false); setPurgePassword(''); }} className="flex-1 py-4 bg-slate-100 text-slate-600 font-black rounded-xl uppercase text-[10px]">Cancelar</button>
                  <button onClick={handlePurgeExecution} className="flex-1 py-4 bg-red-600 text-white font-black rounded-xl uppercase text-[10px] shadow-xl">Autorizar Purga</button>
               </div>
            </div>
         </div>
      </Modal>

      <Modal isOpen={feedback.isOpen} onClose={() => setFeedback({...feedback, isOpen: false})} title={feedback.title} type={feedback.type as any}>
          <div className="text-center space-y-6 p-4">
              <p className="text-slate-600 font-bold uppercase text-[11px] leading-relaxed">{feedback.message}</p>
              <button onClick={() => setFeedback({...feedback, isOpen: false})} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] tracking-widest active:scale-95 transition-all">Aceptar</button>
          </div>
      </Modal>
    </div>
  );
};

