import React, { useState, useEffect } from 'react';
import { Employee, Role, BloodType, Gender, CivilStatus, AbsenceRecord, TerminationReason } from '../../types.ts';
import Modal from '../../components/Modal.tsx';

interface EmployeeModuleProps {
  employees: Employee[];
  onUpdate: (employees: Employee[]) => void;
  role: Role;
  attendance: any[];
  payments: any[];
  company: any;
}

const EmployeeModule: React.FC<EmployeeModuleProps> = ({ employees, onUpdate, role, company }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingEmp, setEditingEmp] = useState<Employee | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [showArchived, setShowArchived] = useState(false);

  const [selectedEmpAction, setSelectedEmpAction] = useState<Employee | null>(null);
  const [isNovedadModalOpen, setIsNovedadModalOpen] = useState(false);
  const [isDesvinculacionModalOpen, setIsDesvinculacionModalOpen] = useState(false);

  const [novedadText, setNovedadText] = useState('');
  const [desvinculacionData, setDesvinculacionData] = useState({
    date: new Date().toISOString().split('T')[0],
    reason: TerminationReason.VOLUNTARY,
    details: ''
  });

  const [feedback, setFeedback] = useState<{isOpen: boolean, title: string, message: string, type: 'success' | 'error' | 'info'}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  const initialForm: Partial<Employee> = {
    name: '', surname: '', identification: '', birthDate: '', phone: '', email: '', 
    gender: Gender.MASCULINO, civilStatus: CivilStatus.SOLTERO,
    origin: 'ECUATORIANA', address: '', 
    bloodType: BloodType.O_POS, startDate: new Date().toISOString().split('T')[0],
    role: Role.EMPLOYEE, salary: 482.00, status: 'active' as const, photo: '', pin: '',
    emergencyContact: { name: '', phone: '' },
    isFixed: true, isAffiliated: true, 
    overSalaryType: 'monthly', 
    reserveFundType: 'monthly', 
    bankInfo: { ifi: '', type: 'Ahorros', account: '' },
    absences: [],
    observations: []
  };

  const [form, setForm] = useState<Partial<Employee>>(initialForm);

  const handleSave = () => {
    if (!form.name || !form.surname || !form.identification || !form.salary) {
      setFeedback({ isOpen: true, title: "Faltan Datos", message: "Campos obligatorios requeridos.", type: "error" });
      return;
    }

    if (!form.isAffiliated) {
      form.reserveFundType = 'none';
    }

    let updatedList: Employee[];
    if (editingEmp) {
      updatedList = employees.map(e => e.id === editingEmp.id ? { ...e, ...form } as Employee : e);
      setFeedback({ isOpen: true, title: "Actualizado", message: "Expediente guardado.", type: "success" });
    } else {
      const autoPin = Math.floor(100000 + Math.random() * 900000).toString();
      const newEmp: Employee = { 
        ...form, 
        id: Math.random().toString(36).substr(2, 9), 
        pin: autoPin, 
        pinChanged: false, 
        pinNeedsReset: false, 
        status: 'active' as const 
      } as Employee;
      updatedList = [...employees, newEmp];
      setFeedback({ isOpen: true, title: "Registrado", message: `PIN: ${autoPin}`, type: "success" });
    }
    onUpdate(updatedList);
    setIsModalOpen(false);
  };

  const handleAddNovedad = () => {
    if (!novedadText.trim() || !selectedEmpAction) return;
    const newNovedad = { date: new Date().toISOString(), text: novedadText.toUpperCase() };
    const updated = employees.map(e => e.id === selectedEmpAction.id ? {
      ...e,
      observations: [newNovedad, ...(e.observations || [])]
    } : e);
    onUpdate(updated);
    setNovedadText('');
    setIsNovedadModalOpen(false);
    setFeedback({ isOpen: true, title: "Registrada", message: "Novedad añadida a bitácora.", type: "success" });
  };

  const handleProcessDesvinculacion = () => {
    if (!selectedEmpAction) return;
    const updated = employees.map(e => e.id === selectedEmpAction.id ? {
      ...e,
      status: 'terminated' as const,
      terminationDate: desvinculacionData.date,
      terminationReason: desvinculacionData.reason,
      terminationDetails: desvinculacionData.details.toUpperCase()
    } : e);
    onUpdate(updated);
    setIsDesvinculacionModalOpen(false);
    setFeedback({ isOpen: true, title: "Procesado", message: "Baja registrada exitosamente.", type: "success" });
  };

  const filteredEmployees = employees.filter(e => {
    const searchString = `${e.name} ${e.surname} ${e.identification}`.toLowerCase();
    const matchesSearch = searchString.includes(searchTerm.toLowerCase());
    return showArchived ? matchesSearch && e.status !== 'active' : matchesSearch && e.status === 'active';
  });

  return (
    <div className="space-y-6 fade-in">
      <div className="bg-white p-6 rounded-[2rem] shadow-sm border flex justify-between items-center no-print">
        <div>
          <h2 className="text-xl font-[950] text-slate-900 uppercase">Personal</h2>
          <div className="flex gap-4 mt-1">
            <button onClick={() => setShowArchived(false)} className={`text-[9px] font-black uppercase ${!showArchived ? 'text-blue-600 border-b-2' : 'text-slate-400'}`}>Activos</button>
            <button onClick={() => setShowArchived(true)} className={`text-[9px] font-black uppercase ${showArchived ? 'text-blue-600 border-b-2' : 'text-slate-400'}`}>Inactivos</button>
          </div>
        </div>
        <button onClick={() => { setForm(initialForm); setEditingEmp(null); setIsModalOpen(true); }} className="px-6 py-3 bg-blue-700 text-white font-black rounded-xl uppercase text-[9px]">Registrar</button>
      </div>

      <div className="bg-white rounded-[2rem] shadow-sm border overflow-hidden">
        <div className="table-responsive">
          <table className="w-full text-left">
            <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase">
              <tr>
                <th className="px-6 py-4">Colaborador</th>
                <th className="px-6 py-4">Cargo / ID</th>
                <th className="px-6 py-4 text-center">Estado</th>
                <th className="px-6 py-4 text-right">Gestión</th>
              </tr>
            </thead>
            <tbody className="divide-y text-[11px] font-black uppercase">
              {filteredEmployees.map(emp => (
                <tr key={emp.id} className="hover:bg-slate-50 transition-colors">
                  <td className="px-6 py-3">{emp.surname} {emp.name}</td>
                  <td className="px-6 py-3"><p className="text-blue-600">{emp.role}</p><p className="text-[9px] text-slate-400">{emp.identification}</p></td>
                  <td className="px-6 py-3 text-center">
                    <span className={`px-2 py-1 rounded-full text-[8px] ${emp.status === 'active' ? 'bg-emerald-50 text-emerald-600' : 'bg-red-50 text-red-600'}`}>
                      {emp.status}
                    </span>
                  </td>
                  <td className="px-6 py-3 text-right">
                    <div className="flex justify-end gap-2">
                      <button onClick={() => { setEditingEmp(emp); setForm(emp); setIsModalOpen(true); }} className="p-2 bg-slate-100 rounded-lg text-[10px]">✏️</button>
                      <button onClick={() => { setSelectedEmpAction(emp); setIsNovedadModalOpen(true); }} className="p-2 bg-blue-50 text-blue-600 rounded-lg text-[10px]">📝</button>
                      {emp.status === 'active' && <button onClick={() => { setSelectedEmpAction(emp); setIsDesvinculacionModalOpen(true); }} className="p-2 bg-red-50 text-red-600 rounded-lg text-[10px]">🚪</button>}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title="Expediente" maxWidth="max-w-4xl">
        <div className="space-y-6 max-h-[70vh] overflow-y-auto pr-2 custom-scroll">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
               <input className="p-3 border rounded-xl text-xs font-bold uppercase" placeholder="Nombres" value={form.name} onChange={e => setForm({...form, name: e.target.value.toUpperCase()})} />
               <input className="p-3 border rounded-xl text-xs font-bold uppercase" placeholder="Apellidos" value={form.surname} onChange={e => setForm({...form, surname: e.target.value.toUpperCase()})} />
               <input className="p-3 border rounded-xl text-xs font-bold" placeholder="Identificación" value={form.identification} onChange={e => setForm({...form, identification: e.target.value})} />
               <input type="number" className="p-3 border rounded-xl text-xs font-bold" placeholder="Sueldo Base ($)" value={form.salary} onChange={e => setForm({...form, salary: Number(e.target.value)})} />
               <select className="p-3 border rounded-xl text-xs font-bold uppercase" value={form.role} onChange={e => setForm({...form, role: e.target.value as any})}>
                  {Object.values(Role).map(r => <option key={r} value={r}>{r}</option>)}
               </select>
               <input type="date" className="p-3 border rounded-xl text-xs font-bold" value={form.startDate} onChange={e => setForm({...form, startDate: e.target.value})} />
          </div>

          <section className="space-y-4 pt-4 border-t">
             <h4 className="text-[10px] font-black text-blue-700 uppercase tracking-widest border-b pb-1">Seguridad Social y Beneficios Obligatorios</h4>
             <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div className="p-3 bg-slate-50 rounded-xl border flex items-center justify-between">
                   <label className="text-[9px] font-black uppercase">Afiliación IESS</label>
                   <button onClick={() => setForm({...form, isAffiliated: !form.isAffiliated})} className={`w-10 h-5 rounded-full transition-colors ${form.isAffiliated ? 'bg-blue-600' : 'bg-slate-300'}`}>
                      <div className={`w-3 h-3 bg-white rounded-full transition-transform ${form.isAffiliated ? 'translate-x-6' : 'translate-x-1'}`} />
                   </button>
                </div>
                {form.isAffiliated && (
                   <div className="space-y-1">
                     <label className="text-[8px] font-black text-slate-400 uppercase">Fondos de Reserva</label>
                     <select className="w-full p-2 border-2 border-emerald-100 rounded-xl text-xs font-bold uppercase" value={form.reserveFundType} onChange={e => setForm({...form, reserveFundType: e.target.value as any})}>
                        <option value="monthly">Mensualizar</option>
                        <option value="accumulate">Acumular</option>
                     </select>
                   </div>
                )}
                <div className="space-y-1">
                  <label className="text-[8px] font-black text-slate-400 uppercase">Décimos (Sobresueldos)</label>
                  <select className="w-full p-2 border rounded-xl text-xs font-bold uppercase" value={form.overSalaryType} onChange={e => setForm({...form, overSalaryType: e.target.value as any})}>
                    <option value="monthly">Mensualizar</option>
                    <option value="accumulate">Acumular</option>
                    <option value="none">No Aplica</option>
                  </select>
                </div>
             </div>
          </section>

          <button onClick={handleSave} className="w-full py-4 bg-blue-700 text-white font-black rounded-xl uppercase text-[10px] tracking-widest shadow-lg">Guardar Colaborador</button>
        </div>
      </Modal>

      <Modal isOpen={isNovedadModalOpen} onClose={() => setIsNovedadModalOpen(false)} title="Novedad Admin">
         <div className="space-y-4">
            <textarea className="w-full border-2 p-4 rounded-xl text-xs font-bold uppercase min-h-[100px]" placeholder="Detalle de novedad..." value={novedadText} onChange={e => setNovedadText(e.target.value)} />
            <button onClick={handleAddNovedad} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px]">Guardar Novedad</button>
         </div>
      </Modal>

      <Modal isOpen={isDesvinculacionModalOpen} onClose={() => setIsDesvinculacionModalOpen(false)} title="Baja Laboral" type="error">
         <div className="space-y-4">
            <input type="date" className="w-full border-2 p-3 rounded-xl text-xs font-bold" value={desvinculacionData.date} onChange={e => setDesvinculacionData({...desvinculacionData, date: e.target.value})} />
            <select className="w-full border-2 p-3 rounded-xl text-xs font-bold uppercase" value={desvinculacionData.reason} onChange={e => setDesvinculacionData({...desvinculacionData, reason: e.target.value as any})}>
               {Object.values(TerminationReason).map(v => <option key={v} value={v}>{v}</option>)}
            </select>
            <textarea className="w-full border-2 p-3 rounded-xl text-xs font-bold uppercase h-20" placeholder="Detalles de salida..." value={desvinculacionData.details} onChange={e => setDesvinculacionData({...desvinculacionData, details: e.target.value})} />
            <div className="flex gap-3">
               <button onClick={() => setIsDesvinculacionModalOpen(false)} className="flex-1 py-4 bg-slate-100 text-slate-500 font-black rounded-xl uppercase text-[10px]">Cerrar</button>
               <button onClick={handleProcessDesvinculacion} className="flex-1 py-4 bg-red-600 text-white font-black rounded-xl uppercase text-[10px]">Ejecutar Baja</button>
            </div>
         </div>
      </Modal>

      <Modal isOpen={feedback.isOpen} onClose={() => setFeedback({...feedback, isOpen: false})} title={feedback.title} type={feedback.type}>
        <div className="text-center p-4">
          <p className="text-[11px] font-bold uppercase text-slate-600">{feedback.message}</p>
          <button onClick={() => setFeedback({...feedback, isOpen: false})} className="w-full py-3 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] mt-6">Aceptar</button>
        </div>
      </Modal>
    </div>
  );
};

