import React, { useState } from 'react';
import { Employee, Payment, CompanyConfig, GlobalSettings, Role } from '../../types.ts';
import Modal from '../../components/Modal.tsx';

interface PayrollModuleProps {
  employees: Employee[];
  payments: Payment[];
  onUpdatePayments?: (payments: Payment[]) => void;
  onUpdateEmployees?: (employees: Employee[]) => void;
  attendance: any[];
  company: CompanyConfig | null;
  settings: GlobalSettings;
  role: Role;
}

const PayrollModule: React.FC<PayrollModuleProps> = ({ employees, payments, onUpdatePayments, onUpdateEmployees, attendance = [], company, settings, role }) => {
  const [selectedMonth, setSelectedMonth] = useState('FEBRERO');
  const [individualPayroll, setIndividualPayroll] = useState<Employee | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [feedback, setFeedback] = useState({ isOpen: false, title: '', message: '', type: 'success' as any });

  const monthMap: { [key: string]: number } = {
    'ENERO': 0, 'FEBRERO': 1, 'MARZO': 2, 'ABRIL': 3, 'MAYO': 4, 'JUNIO': 5,
    'JULIO': 6, 'AGOSTO': 7, 'SEPTIEMBRE': 8, 'OCTUBRE': 9, 'NOVIEMBRE': 10, 'DICIEMBRE': 11
  };

  const calculatePayrollData = (emp: Employee) => {
    const monthIndex = monthMap[selectedMonth] ?? 0;
    const year = 2026;

    const empAttendance = (attendance || []).filter(a => {
      const d = new Date(a.timestamp);
      return a.employeeId === emp.id && d.getMonth() === monthIndex && d.getFullYear() === year && a.status === 'confirmed';
    });

    const attendanceDates = new Set(empAttendance.map(a => a.timestamp.split('T')[0]));
    let workedDays = attendanceDates.size;
    if (workedDays >= 22) workedDays = 30; 

    const valuePerDay = emp.salary / 30;
    const baseSalaryEarned = valuePerDay * workedDays;
    const monthlyPayments = payments.filter(p => p.employeeId === emp.id && p.month === selectedMonth && p.status === 'paid');

    const suplementaryHoursAmount = monthlyPayments
      .filter(p => p.type === 'ExtraHours' && p.concept.includes('50%'))
      .reduce((sum, p) => sum + p.amount, 0);

    const extraHoursAmount = monthlyPayments
      .filter(p => p.type === 'ExtraHours' && p.concept.includes('100%'))
      .reduce((sum, p) => sum + p.amount, 0);

    const otherIncomes = monthlyPayments.filter(p => p.type === 'Bonus' || p.type === 'Vacation').reduce((sum, p) => sum + p.amount, 0);

    const ordinaryRemuneration = baseSalaryEarned + suplementaryHoursAmount + extraHoursAmount + otherIncomes;

    const monthly13th = (emp.overSalaryType === 'monthly') ? ordinaryRemuneration / 12 : 0;
    const sbuPrev = settings.sbuPrev || 460.00;
    const monthly14th = (emp.overSalaryType === 'monthly') ? (sbuPrev / 12) * (workedDays / 30) : 0;

    const reserveFund = (emp.isAffiliated) ? (ordinaryRemuneration * 0.0833) : 0;
    const reserveFundPaid = (emp.isAffiliated && emp.reserveFundType === 'monthly') ? reserveFund : 0;

    const iessContribution = emp.isAffiliated ? (ordinaryRemuneration * settings.iessRate) : 0;
    const fines = monthlyPayments.filter(p => p.type === 'Fine').reduce((sum, p) => sum + p.amount, 0);
    const advances = monthlyPayments.filter(p => p.type === 'Advance' || p.type === 'Loan' || p.type === 'Emergency').reduce((sum, p) => sum + p.amount, 0);
    const otherDiscounts = monthlyPayments.filter(p => p.type === 'BackPay').reduce((sum, p) => sum + p.amount, 0);

    const totalIncomes = baseSalaryEarned + suplementaryHoursAmount + extraHoursAmount + monthly13th + monthly14th + reserveFundPaid + otherIncomes;
    const totalExpenses = iessContribution + fines + advances + otherDiscounts;
    const netToReceive = totalIncomes - totalExpenses;

    return { 
      baseSalary: baseSalaryEarned,
      suplementary: suplementaryHoursAmount + extraHoursAmount,
      reserveFund,
      monthly13th,
      monthly14th,
      otherIncomes,
      iessContribution,
      fines,
      advances,
      otherDiscounts,
      netToReceive,
      workedDays
    };
  };

  const exportGeneralExcel = () => {
    let csv = "\uFEFFColaborador,Identificación,Días Trab.,Total Ganado,Extras/Suplem.,F. Reserva 8.33%,13ero Mens.,14to Mens.,Otros Ing.,IESS 9.45%,Multas,Anticipos,Otros Desc.,Neto Recibir\n";
    employees.filter(e => e.status === 'active').forEach((emp) => {
      const d = calculatePayrollData(emp);
      csv += `"${emp.surname} ${emp.name}","${emp.identification}","${d.workedDays}","${d.baseSalary.toFixed(2)}","${d.suplementary.toFixed(2)}","${d.reserveFund.toFixed(2)}","${d.monthly13th.toFixed(2)}","${d.monthly14th.toFixed(2)}","${d.otherIncomes.toFixed(2)}","${d.iessContribution.toFixed(2)}","${d.fines.toFixed(2)}","${d.advances.toFixed(2)}","${d.otherDiscounts.toFixed(2)}","${d.netToReceive.toFixed(2)}"\n`;
    });
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `ROL_GENERAL_${selectedMonth}_2026.csv`;
    link.click();
  };

  const filteredEmployees = employees.filter(e => {
    const searchStr = `${e.name} ${e.surname} ${e.identification}`.toLowerCase();
    return searchStr.includes(searchTerm.toLowerCase());
  });

  return (
    <div className="space-y-6 md:space-y-8 fade-in">
      <div className="flex flex-col md:flex-row justify-between items-center bg-white p-6 rounded-3xl shadow-sm border no-print gap-6">
        <h2 className="text-xl font-black text-slate-900 uppercase">Nómina Corporativa</h2>
        <div className="flex flex-col sm:flex-row gap-4 w-full md:w-auto">
             <select className="p-3 border rounded-xl text-[11px] font-black uppercase outline-none focus:border-blue-500" value={selectedMonth} onChange={e => setSelectedMonth(e.target.value)}>
                {['ENERO','FEBRERO','MARZO','ABRIL','MAYO','JUNIO','JULIO','AGOSTO','SEPTIEMBRE','OCTUBRE','NOVIEMBRE','DICIEMBRE'].map(m => <option key={m} value={m}>{m}</option>)}
             </select>
             <input type="text" placeholder="Filtrar por CI o Nombre..." className="flex-1 p-3 border rounded-xl text-[11px] font-bold uppercase" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
             <button onClick={exportGeneralExcel} className="px-6 py-4 bg-emerald-600 text-white font-black rounded-xl uppercase text-[10px] active:scale-95 shadow-lg">Descargar General</button>
        </div>
      </div>

      <div className="bg-white p-4 md:p-8 rounded-[2.5rem] shadow-sm border overflow-hidden">
        <div className="table-responsive overflow-x-auto">
          <table className="w-full text-left border-collapse min-w-[1500px] print:min-w-0">
            <thead className="bg-slate-900 text-white text-[10px] font-black uppercase tracking-widest">
              <tr>
                <th className="p-4 sticky left-0 bg-slate-900">Colaborador</th>
                <th className="p-4 text-center">Días</th>
                <th className="p-4 text-center">Base</th>
                <th className="p-4 text-center">Reserva</th>
                <th className="p-4 text-center">13ero</th>
                <th className="p-4 text-center">14to</th>
                <th className="p-4 text-center">IESS</th>
                <th className="p-4 text-center bg-blue-800 text-white">Neto Recibir</th>
                <th className="p-4 text-center no-print bg-slate-950">Acción</th>
              </tr>
            </thead>
            <tbody className="text-[11px] uppercase font-bold text-slate-700 divide-y">
              {filteredEmployees.filter(e => e.status === 'active').map((emp) => {
                const d = calculatePayrollData(emp);
                return (
                  <tr key={emp.id} className="hover:bg-slate-50 transition-colors">
                    <td className="p-4 sticky left-0 bg-white shadow-sm z-10">
                      <p className="font-black text-slate-900 leading-none">{emp.surname} {emp.name}</p>
                      <p className="text-[9px] text-slate-400 mt-1">{emp.identification}</p>
                    </td>
                    <td className="p-4 text-center">{d.workedDays}</td>
                    <td className="p-4 text-center">${d.baseSalary.toFixed(2)}</td>
                    <td className="p-4 text-center font-black text-emerald-700">${d.reserveFund.toFixed(2)}</td>
                    <td className="p-4 text-center">${d.monthly13th.toFixed(2)}</td>
                    <td className="p-4 text-center">${d.monthly14th.toFixed(2)}</td>
                    <td className="p-4 text-center text-red-500">${d.iessContribution.toFixed(2)}</td>
                    <td className="p-4 text-center font-black text-blue-700 bg-blue-50/20">${d.netToReceive.toFixed(2)}</td>
                    <td className="p-4 text-center no-print">
                       <button onClick={() => setIndividualPayroll(emp)} className="px-3 py-1.5 bg-blue-700 text-white rounded-lg text-[9px] font-black uppercase shadow-md">Ver Rol</button>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      <Modal isOpen={!!individualPayroll} onClose={() => setIndividualPayroll(null)} title="Rol de Pagos Institucional">
        {individualPayroll && (() => {
           const d = calculatePayrollData(individualPayroll);
           return (
             <div className="space-y-6 bg-white p-6" id="individual-role-print">
               <div className="flex justify-between items-center border-b-4 border-black pb-6">
                  <div className="flex items-center gap-6">
                    <div className="w-20 h-20 border-2 border-black flex items-center justify-center overflow-hidden">
                      {company?.logo ? <img src={company.logo} className="w-full h-full object-contain" /> : <span className="text-xl font-black">LOGO</span>}
                    </div>
                    <div>
                      <h3 className="text-2xl font-[950] uppercase italic leading-none">{company?.name || 'EMPRESA INSTITUCIONAL'}</h3>
                      <p className="text-sm font-black mt-1">RUC: {company?.ruc || '0000000000001'}</p>
                      <p className="text-[10px] font-bold uppercase">{company?.address || 'QUITO, ECUADOR'}</p>
                    </div>
                  </div>
                  <div className="text-right border-l-2 border-black/10 pl-6">
                     <p className="font-black uppercase text-[12px] tracking-widest">ROL INDIVIDUAL DE PAGOS</p>
                     <p className="font-bold uppercase text-[10px] mt-1">{selectedMonth} / 2026</p>
                  </div>
               </div>

               <div className="grid grid-cols-2 gap-4 text-[11px] font-bold uppercase">
                  <div className="p-4 border border-black/10 bg-slate-50/50">
                    <p className="text-[9px] text-slate-500">Beneficiario</p>
                    <p className="text-black font-black text-sm">{individualPayroll.surname} {individualPayroll.name}</p>
                    <p className="text-[9px] mt-1">{individualPayroll.role} | CI: {individualPayroll.identification}</p>
                  </div>
                  <div className="p-4 border border-black/10 bg-slate-50/50 text-right">
                    <p className="text-[9px] text-slate-500">Días Trabajados</p>
                    <p className="text-black font-black text-sm">{d.workedDays} DÍAS LIQUIDADOS</p>
                    <p className="text-[9px] mt-1">IESS: {individualPayroll.isAffiliated ? 'AFILIADO' : 'NO AFILIADO'}</p>
                  </div>
               </div>

               <div className="grid grid-cols-1 md:grid-cols-2 gap-8 pt-4">
                  <div className="space-y-4">
                     <h4 className="text-[10px] font-black uppercase border-b-2 border-black pb-1">Ingresos (Haberes)</h4>
                     <div className="space-y-1.5 text-[11px] font-bold">
                        <div className="flex justify-between"><span>Sueldo Base Ganado</span><span>${d.baseSalary.toFixed(2)}</span></div>
                        <div className="flex justify-between"><span>Horas Extras/Suplem.</span><span>${d.suplementary.toFixed(2)}</span></div>
                        <div className="flex justify-between text-emerald-700"><span>Fondo de Reserva (8.33%)</span><span>${d.reserveFund.toFixed(2)}</span></div>
                        <div className="flex justify-between"><span>Décimo Tercero (Provisión)</span><span>${d.monthly13th.toFixed(2)}</span></div>
                        <div className="flex justify-between"><span>Décimo Cuarto (Provisión)</span><span>${d.monthly14th.toFixed(2)}</span></div>
                        <div className="flex justify-between font-black border-t border-black/10 pt-1"><span>TOTAL INGRESOS</span><span>${(d.baseSalary + d.suplementary + d.reserveFund + d.monthly13th + d.monthly14th + d.otherIncomes).toFixed(2)}</span></div>
                     </div>
                  </div>
                  <div className="space-y-4">
                     <h4 className="text-[10px] font-black uppercase border-b-2 border-black pb-1">Egresos (Descuentos)</h4>
                     <div className="space-y-1.5 text-[11px] font-bold">
                        <div className="flex justify-between"><span>Aporte Personal IESS (9.45%)</span><span>${d.iessContribution.toFixed(2)}</span></div>
                        <div className="flex justify-between"><span>Anticipos de Sueldo</span><span>${d.advances.toFixed(2)}</span></div>
                        <div className="flex justify-between"><span>Sanciones / Multas</span><span>${d.fines.toFixed(2)}</span></div>
                        <div className="flex justify-between font-black border-t border-black/10 pt-1 text-red-600"><span>TOTAL DESCUENTOS</span><span>${(d.iessContribution + d.advances + d.fines + d.otherDiscounts).toFixed(2)}</span></div>
                     </div>
                  </div>
               </div>

               <div className="border-2 border-black p-6 flex justify-between items-center bg-slate-900 text-white rounded-xl shadow-xl mt-6">
                  <p className="text-[14px] font-[950] uppercase tracking-[0.3em]">NETO A RECIBIR</p>
                  <p className="text-4xl font-[950] tracking-tighter">${d.netToReceive.toFixed(2)}</p>
               </div>

               <div className="mt-20 grid grid-cols-2 gap-20 text-center text-[10px] font-black uppercase">
                  <div className="border-t-2 border-black pt-4">Recibí Conforme (Firma)</div>
                  <div className="border-t-2 border-black pt-4">Autorizado por Gerencia / Tesorería</div>
               </div>

               <div className="flex gap-3 mt-10 no-print">
                  <button onClick={() => window.print()} className="flex-1 py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] tracking-widest shadow-xl active:scale-95 transition-all">Imprimir Comprobante Oficial</button>
               </div>
             </div>
           );
        })()}
      </Modal>

      <Modal isOpen={feedback.isOpen} onClose={() => setFeedback({...feedback, isOpen: false})} title={feedback.title} type={feedback.type}>
          <div className="text-center p-4">
              <p className="text-slate-600 font-bold uppercase text-[11px] mb-6">{feedback.message}</p>
              <button onClick={() => setFeedback({...feedback, isOpen: false})} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px]">Aceptar</button>
          </div>
      </Modal>
    </div>
  );
};

