import React, { useState, useMemo } from 'react';
import { Employee, Payment, Role, CompanyConfig } from '../../types.ts';
import Modal from '../../components/Modal.tsx';

interface PaymentsModuleProps {
  employees: Employee[];
  payments: Payment[];
  onUpdate: (payments: Payment[]) => void;
  role: Role;
  company: CompanyConfig | null;
}

const PaymentsModule: React.FC<PaymentsModuleProps> = ({ employees, payments, onUpdate, role, company }) => {
  const [isPayOpen, setIsPayOpen] = useState(false);
  const [selectedPayForPrint, setSelectedPayForPrint] = useState<Payment | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  const [payForm, setPayForm] = useState<Partial<Payment>>({
    type: 'Salary',
    amount: 0,
    method: 'Efectivo',
    concept: '',
    date: new Date().toISOString().split('T')[0],
    month: 'FEBRERO',
    year: '2026',
    status: 'paid'
  });

  const [dualData, setDualData] = useState({
    method1: 'Efectivo' as const,
    value1: 0,
    method2: 'Transferencia' as const,
    value2: 0,
    bankSource: 'Banco del Austro' as any
  });

  const [checkData, setCheckData] = useState({
    client: '', bank: '', number: '', value: 0
  });

  const [feedback, setFeedback] = useState<{isOpen: boolean, title: string, message: string, type: 'success' | 'error' | 'info'}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  const generateSequentialCode = () => {
    const year = new Date().getFullYear();
    const count = payments.length + 1;
    return `VCH-${year}-${count.toString().padStart(5, '0')}`;
  };

  const handleCreate = () => {
    if (!payForm.employeeId || !payForm.amount || payForm.amount <= 0) {
        setFeedback({ isOpen: true, title: "Error", message: "Datos de pago incompletos.", type: "error" });
        return;
    }

    const newPay: Payment = { 
      ...payForm, 
      id: Math.random().toString(36).substr(2, 15), 
      date: new Date(payForm.date!).toISOString(),
      voucherCode: generateSequentialCode(),
      checkDetails: payForm.method === 'Cheque' ? checkData : undefined,
      dualDetails: payForm.method === 'Dual' ? { ...dualData } : undefined,
      status: 'paid' 
    } as Payment;

    onUpdate([newPay, ...payments]);
    setIsPayOpen(false);
    setFeedback({ isOpen: true, title: "Pago Sincronizado", message: `Voucher ${newPay.voucherCode} registrado en tesorería.`, type: "success" });

    setPayForm({
      type: 'Salary', amount: 0, method: 'Efectivo', concept: '', 
      date: new Date().toISOString().split('T')[0],
      month: 'FEBRERO', year: '2026', status: 'paid'
    });
  };

  const filteredPayments = payments.filter(p => {
    const emp = employees.find(e => e.id === p.employeeId);
    return `${emp?.surname} ${p.voucherCode}`.toLowerCase().includes(searchTerm.toLowerCase());
  });

  return (
    <div className="space-y-6 fade-in">
      <div className="flex flex-col md:flex-row justify-between items-center bg-white p-6 rounded-3xl shadow-sm border no-print gap-6">
        <h2 className="text-xl font-black text-slate-900 uppercase">Caja y Tesorería</h2>
        <div className="flex gap-3 w-full md:w-auto">
          <input type="text" placeholder="Filtrar registros..." className="flex-1 p-3 border rounded-xl text-[10px] font-bold uppercase outline-none focus:border-blue-500" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
          <button onClick={() => setIsPayOpen(true)} className="px-8 py-3.5 bg-blue-700 text-white font-black rounded-xl shadow-lg uppercase text-[9px] active:scale-95 transition-all">Nuevo Egreso</button>
        </div>
      </div>

      <div className="bg-white rounded-3xl shadow-sm border overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-slate-50 text-[9px] font-black text-slate-400 uppercase">
            <tr><th className="px-6 py-4">Voucher</th><th className="px-6 py-4">Beneficiario</th><th className="px-6 py-4">Concepto</th><th className="px-6 py-4">Monto</th><th className="px-6 py-4 text-right">Acción</th></tr>
          </thead>
          <tbody className="divide-y text-[10px] font-bold uppercase">
            {filteredPayments.map(p => (
              <tr key={p.id} className="hover:bg-slate-50 transition-all">
                <td className="px-6 py-4 font-black text-blue-600">{p.voucherCode}</td>
                <td className="px-6 py-4">{employees.find(e => e.id === p.employeeId)?.surname}</td>
                <td className="px-6 py-4">{p.type}</td>
                <td className="px-6 py-4 font-black">${p.amount.toFixed(2)}</td>
                <td className="px-6 py-4 text-right"><button onClick={() => setSelectedPayForPrint(p)} className="px-3 py-1.5 bg-slate-900 text-white rounded-lg text-[8px] uppercase">Comprobante</button></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <Modal isOpen={isPayOpen} onClose={() => setIsPayOpen(false)} title="Nuevo Pago Institucional">
        <div className="space-y-4">
           <select className="w-full border-2 p-3 rounded-xl text-xs font-bold uppercase" value={payForm.employeeId} onChange={e => setPayForm({...payForm, employeeId: e.target.value})}>
             <option value="">Beneficiario...</option>
             {employees.filter(e => e.status === 'active').map(e => <option key={e.id} value={e.id}>{e.surname} {e.name}</option>)}
           </select>
           <input type="number" step="0.01" className="w-full border-2 p-3 rounded-xl text-lg font-black" placeholder="Monto ($)" value={payForm.amount} onChange={e => setPayForm({...payForm, amount: Number(e.target.value)})} />
           <textarea className="w-full border-2 p-3 rounded-xl text-xs font-bold uppercase h-20" placeholder="Detalle concepto..." value={payForm.concept} onChange={e => setPayForm({...payForm, concept: e.target.value.toUpperCase()})} />
           <button onClick={handleCreate} className="w-full py-4 bg-blue-700 text-white font-black rounded-xl uppercase text-[10px]">Guardar y Pagar</button>
        </div>
      </Modal>

      <Modal isOpen={!!selectedPayForPrint} onClose={() => setSelectedPayForPrint(null)} title="Comprobante de Egreso">
        {selectedPayForPrint && (() => {
           const emp = employees.find(e => e.id === selectedPayForPrint.employeeId);
           return (
             <div className="p-8 space-y-8 bg-white" id="payment-voucher-print">
                <div className="flex justify-between items-center border-b-4 border-black pb-8">
                   <div className="flex items-center gap-6">
                      <div className="w-20 h-20 border-2 border-black flex items-center justify-center overflow-hidden">
                         {company?.logo ? <img src={company.logo} className="w-full h-full object-contain" /> : <span className="font-black text-xs">LOGO</span>}
                      </div>
                      <div className="text-left">
                         <h3 className="text-2xl font-[950] uppercase italic leading-none">{company?.name || 'EMPRESA INSTITUCIONAL'}</h3>
                         <p className="text-sm font-black mt-1">RUC: {company?.ruc || '0000000000001'}</p>
                         <p className="text-[10px] font-bold uppercase tracking-tighter">{company?.address || 'QUITO, ECUADOR'}</p>
                      </div>
                   </div>
                   <div className="text-right border-l-2 border-black/10 pl-6">
                      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">COMPROBANTE DE CAJA</p>
                      <p className="text-xl font-[950]">{selectedPayForPrint.voucherCode}</p>
                   </div>
                </div>

                <div className="grid grid-cols-2 gap-10 text-[11px] font-bold uppercase">
                   <div className="space-y-2 border p-4 bg-slate-50/50">
                      <p className="text-[9px] text-slate-400">BENEFICIARIO:</p>
                      <p className="text-black font-[950] text-sm">{emp?.surname} {emp?.name}</p>
                      <p className="text-slate-600">CI: {emp?.identification}</p>
                   </div>
                   <div className="text-right space-y-2 border p-4 bg-slate-50/50">
                      <p className="text-[9px] text-slate-400">DATOS DEL PAGO:</p>
                      <p className="text-black font-[950]">{new Date(selectedPayForPrint.date).toLocaleDateString()}</p>
                      <p className="text-blue-600">MODALIDAD: {selectedPayForPrint.method}</p>
                   </div>
                </div>

                <div className="p-6 bg-slate-50 rounded-xl border-l-8 border-slate-900">
                   <p className="text-[9px] font-black text-slate-400 uppercase mb-2">POR CONCEPTO DE:</p>
                   <p className="text-[12px] text-slate-800 font-black italic">"{selectedPayForPrint.concept}"</p>
                </div>

                <div className="bg-slate-900 p-8 rounded-2xl text-white flex justify-between items-center shadow-2xl">
                   <p className="text-[16px] font-[950] uppercase tracking-[0.4em]">VALOR PAGADO</p>
                   <p className="text-5xl font-[950] tracking-tighter">${selectedPayForPrint.amount.toFixed(2)}</p>
                </div>

                <div className="mt-24 grid grid-cols-2 gap-20 text-center">
                   <div className="border-t-2 border-black pt-4 text-[10px] font-black uppercase">Firma de Recibido</div>
                   <div className="border-t-2 border-black pt-4 text-[10px] font-black uppercase">Autorizado por Tesorería</div>
                </div>
                <button onClick={() => window.print()} className="w-full py-5 bg-slate-900 text-white font-black rounded-xl uppercase text-[11px] no-print mt-12 shadow-xl tracking-widest active:scale-95">Imprimir Egreso</button>
             </div>
           );
        })()}
      </Modal>

      <Modal isOpen={feedback.isOpen} onClose={() => setFeedback({...feedback, isOpen: false})} title={feedback.title} type={feedback.type}>
        <div className="text-center p-4">
          <p className="text-[11px] font-bold uppercase text-slate-600 leading-relaxed">{feedback.message}</p>
          <button onClick={() => setFeedback({...feedback, isOpen: false})} className="w-full py-3.5 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] mt-6">Aceptar</button>
        </div>
      </Modal>
    </div>
  );
};

export default PaymentsModule;

import React, { useState, useEffect } from 'react';
import { Employee, Role, BloodType, Gender, CivilStatus, AbsenceRecord, TerminationReason } from '../../types.ts';
import Modal from '../../components/Modal.tsx';

interface EmployeeModuleProps {
  employees: Employee[];
  onUpdate: (employees: Employee[]) => void;
  role: Role;
  attendance: any[];
  payments: any[];
  company: any;
}

const EmployeeModule: React.FC<EmployeeModuleProps> = ({ employees, onUpdate, role, company }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingEmp, setEditingEmp] = useState<Employee | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [showArchived, setShowArchived] = useState(false);

  // Gestión de Novedades y Desvinculación
  const [selectedEmpAction, setSelectedEmpAction] = useState<Employee | null>(null);
  const [isNovedadModalOpen, setIsNovedadModalOpen] = useState(false);
  const [isDesvinculacionModalOpen, setIsDesvinculacionModalOpen] = useState(false);

  const [novedadText, setNovedadText] = useState('');
  const [desvinculacionData, setDesvinculacionData] = useState({
    date: new Date().toISOString().split('T')[0],
    reason: TerminationReason.VOLUNTARY,
    details: ''
  });

  const [feedback, setFeedback] = useState<{isOpen: boolean, title: string, message: string, type: 'success' | 'error' | 'info'}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  const initialForm: Partial<Employee> = {
    name: '', surname: '', identification: '', birthDate: '', phone: '', email: '', 
    gender: Gender.MASCULINO, civilStatus: CivilStatus.SOLTERO,
    origin: 'ECUATORIANA', address: '', 
    bloodType: BloodType.O_POS, startDate: new Date().toISOString().split('T')[0],
    role: Role.EMPLOYEE, salary: 482.00, status: 'active' as const, photo: '', pin: '',
    emergencyContact: { name: '', phone: '' },
    isFixed: true, isAffiliated: true, 
    overSalaryType: 'monthly', 
    reserveFundType: 'monthly', 
    bankInfo: { ifi: '', type: 'Ahorros', account: '' },
    absences: [],
    observations: []
  };

  const [form, setForm] = useState<Partial<Employee>>(initialForm);

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 2 * 1024 * 1024) {
        setFeedback({ isOpen: true, title: "Archivo Grande", message: "La fotografía no debe exceder los 2MB.", type: "error" });
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setForm(prev => ({ ...prev, photo: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSave = () => {
    // Validación estricta de campos obligatorios solicitados
    if (
      !form.name || !form.surname || !form.identification || !form.salary || 
      !form.birthDate || !form.gender || !form.civilStatus || !form.address || 
      !form.email || !form.emergencyContact?.name || !form.emergencyContact?.phone || 
      !form.startDate || !form.role
    ) {
      setFeedback({ 
        isOpen: true, 
        title: "Campos Incompletos", 
        message: "Por favor complete todos los campos obligatorios: Nombres, Apellidos, Identificación, Sueldo, Fecha de Nacimiento, Sexo, Estado Civil, Dirección, Email, Contacto de Emergencia y Fecha de Ingreso.", 
        type: "error" 
      });
      return;
    }

    if (!form.isAffiliated) {
      form.reserveFundType = 'none';
    }

    let updatedList: Employee[];
    if (editingEmp) {
      updatedList = employees.map(e => e.id === editingEmp.id ? { ...e, ...form } as Employee : e);
      setFeedback({ isOpen: true, title: "Actualización Exitosa", message: "Los datos del colaborador han sido actualizados en el sistema maestro.", type: "success" });
    } else {
      const autoPin = Math.floor(100000 + Math.random() * 900000).toString();
      const newEmp: Employee = { 
        ...form, 
        id: Math.random().toString(36).substr(2, 9), 
        pin: autoPin, 
        pinChanged: false, 
        pinNeedsReset: false, 
        status: 'active' as const 
      } as Employee;
      updatedList = [...employees, newEmp];
      setFeedback({ isOpen: true, title: "Registro Exitoso", message: `El empleado ha sido registrado. PIN de marcación asignado: ${autoPin}`, type: "success" });
    }
    onUpdate(updatedList);
    setIsModalOpen(false);
  };

  const handleAddNovedad = () => {
    if (!novedadText.trim() || !selectedEmpAction) return;
    const newNovedad = { date: new Date().toISOString(), text: novedadText.toUpperCase() };
    const updated = employees.map(e => e.id === selectedEmpAction.id ? {
      ...e,
      observations: [newNovedad, ...(e.observations || [])]
    } : e);
    onUpdate(updated);
    setNovedadText('');
    setIsNovedadModalOpen(false);
    setFeedback({ isOpen: true, title: "Novedad Registrada", message: "La incidencia ha sido añadida al historial administrativo.", type: "success" });
  };

  const handleProcessDesvinculacion = () => {
    if (!selectedEmpAction) return;
    const updated = employees.map(e => e.id === selectedEmpAction.id ? {
      ...e,
      status: 'terminated' as const,
      terminationDate: desvinculacionData.date,
      terminationReason: desvinculacionData.reason,
      terminationDetails: desvinculacionData.details.toUpperCase()
    } : e);
    onUpdate(updated);
    setIsDesvinculacionModalOpen(false);
    setFeedback({ isOpen: true, title: "Baja Procesada", message: "Se ha registrado la terminación laboral del colaborador.", type: "success" });
  };

  const filteredEmployees = employees.filter(e => {
    const searchString = `${e.name} ${e.surname} ${e.identification}`.toLowerCase();
    const matchesSearch = searchString.includes(searchTerm.toLowerCase());
    return showArchived ? matchesSearch && e.status !== 'active' : matchesSearch && e.status === 'active';
  });

  return (
    <div className="space-y-6 fade-in">
      <div className="bg-white p-6 md:p-10 rounded-[2rem] md:rounded-[2.5rem] shadow-sm border border-slate-100 flex flex-col md:flex-row justify-between items-center no-print gap-6">
        <div>
          <h2 className="text-2xl font-[950] text-slate-900 uppercase italic leading-none">Gestión de Personal</h2>
          <div className="flex gap-6 mt-3">
            <button onClick={() => setShowArchived(false)} className={`text-[10px] font-black uppercase tracking-widest transition-all ${!showArchived ? 'text-blue-600 border-b-2 border-blue-600' : 'text-slate-400'}`}>Colaboradores Activos</button>
            <button onClick={() => setShowArchived(true)} className={`text-[10px] font-black uppercase tracking-widest transition-all ${showArchived ? 'text-blue-600 border-b-2 border-blue-600' : 'text-slate-400'}`}>Historial de Bajas</button>
          </div>
        </div>
        <div className="flex flex-col sm:flex-row gap-4 w-full md:w-auto">
          <input type="text" placeholder="Filtrar por identificación o nombre..." className="w-full sm:w-64 p-3 border-2 rounded-xl text-[11px] font-bold uppercase focus:border-blue-500 outline-none" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
          <button onClick={() => { setForm(initialForm); setEditingEmp(null); setIsModalOpen(true); }} className="px-8 py-4 bg-blue-700 text-white font-black rounded-xl shadow-lg uppercase text-[10px] tracking-widest active:scale-95 transition-all">Registrar Nuevo</button>
        </div>
      </div>

      <div className="bg-white rounded-[2.5rem] shadow-sm border overflow-hidden no-print">
        <div className="table-responsive">
          <table className="w-full text-left">
            <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest">
              <tr>
                <th className="px-6 py-5">Colaborador / Identidad</th>
                <th className="px-6 py-5">Cargo Institucional</th>
                <th className="px-6 py-5 text-center">Estado</th>
                <th className="px-6 py-5 text-right">Gestión Administrativa</th>
              </tr>
            </thead>
            <tbody className="divide-y text-[11px] font-black uppercase">
              {filteredEmployees.map(emp => (
                <tr key={emp.id} className="hover:bg-blue-50/30 transition-colors">
                  <td className="px-6 py-4">
                     <div className="flex items-center gap-3">
                        <div className="w-10 h-10 bg-slate-100 rounded-xl overflow-hidden border">
                           {emp.photo ? <img src={emp.photo} className="w-full h-full object-cover" /> : <span className="flex items-center justify-center h-full text-slate-400 text-xl">👤</span>}
                        </div>
                        <div>
                           <p className="text-slate-900 leading-none">{emp.surname} {emp.name}</p>
                           <p className="text-[9px] text-slate-400 font-mono mt-1">{emp.identification}</p>
                        </div>
                     </div>
                  </td>
                  <td className="px-6 py-4"><p className="text-blue-600">{emp.role}</p><p className="text-[9px] text-slate-400 mt-1">Ingreso: {emp.startDate}</p></td>
                  <td className="px-6 py-4 text-center">
                    <span className={`px-3 py-1 rounded-full text-[8px] font-black uppercase ${emp.status === 'active' ? 'bg-emerald-50 text-emerald-600' : 'bg-red-50 text-red-600'}`}>
                      {emp.status}
                    </span>
                  </td>
                  <td className="px-6 py-4 text-right">
                    <div className="flex justify-end gap-2">
                      <button onClick={() => { setEditingEmp(emp); setForm(emp); setIsModalOpen(true); }} className="p-2.5 bg-slate-100 text-slate-600 rounded-lg text-[11px]" title="Editar Expediente">✏️</button>
                      <button onClick={() => { setSelectedEmpAction(emp); setIsNovedadModalOpen(true); }} className="p-2.5 bg-blue-50 text-blue-600 rounded-lg text-[11px]" title="Registrar Novedad">📝</button>
                      {emp.status === 'active' && (
                        <button onClick={() => { setSelectedEmpAction(emp); setIsDesvinculacionModalOpen(true); }} className="p-2.5 bg-red-50 text-red-600 rounded-lg text-[11px]" title="Procesar Baja">🚪</button>
                      )}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* MODAL EXPEDIENTE MAESTRO */}
      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title={editingEmp ? "Actualizar Expediente" : "Ingreso de Nuevo Colaborador"} maxWidth="max-w-4xl">
        <div className="space-y-8 max-h-[75vh] overflow-y-auto pr-2 custom-scroll pb-6">

          <div className="flex flex-col md:flex-row gap-8 items-center bg-slate-50 p-6 rounded-[2rem] border">
             <div className="relative w-32 h-32 bg-white rounded-3xl border-2 border-dashed border-blue-200 flex items-center justify-center overflow-hidden shadow-inner group">
                {form.photo ? <img src={form.photo} className="w-full h-full object-cover" /> : <span className="text-3xl opacity-20">📸</span>}
                <input type="file" accept="image/*" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handlePhotoUpload} />
                <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center text-white text-[8px] font-black uppercase pointer-events-none text-center p-2">Click para subir fotografía</div>
             </div>
             <div className="flex-1 grid grid-cols-1 md:grid-cols-2 gap-4 w-full">
                <div className="space-y-1">
                   <label className="text-[9px] font-black text-slate-400 uppercase">Nombres</label>
                   <input className="w-full p-3 border-2 rounded-xl text-xs font-bold uppercase focus:border-blue-500 outline-none" placeholder="EJ: JUAN ALBERTO" value={form.name} onChange={e => setForm({...form, name: e.target.value.toUpperCase()})} />
                </div>
                <div className="space-y-1">
                   <label className="text-[9px] font-black text-slate-400 uppercase">Apellidos</label>
                   <input className="w-full p-3 border-2 rounded-xl text-xs font-bold uppercase focus:border-blue-500 outline-none" placeholder="EJ: PÉREZ GARCÍA" value={form.surname} onChange={e => setForm({...form, surname: e.target.value.toUpperCase()})} />
                </div>
                <div className="space-y-1">
                   <label className="text-[9px] font-black text-slate-400 uppercase">Identificación (CI/RUC)</label>
                   <input className="w-full p-3 border-2 rounded-xl text-xs font-mono font-black focus:border-blue-500 outline-none" placeholder="10 DÍGITOS" value={form.identification} onChange={e => setForm({...form, identification: e.target.value.replace(/\D/g,'')})} />
                </div>
                <div className="space-y-1">
                   <label className="text-[9px] font-black text-slate-400 uppercase">Sueldo Base ($)</label>
                   <input type="number" step="0.01" className="w-full p-3 border-2 rounded-xl text-lg font-black focus:border-blue-500 outline-none" value={form.salary} onChange={e => setForm({...form, salary: Number(e.target.value)})} />
                </div>
             </div>
          </div>

          <section className="space-y-4">
             <h4 className="text-[10px] font-black text-blue-700 uppercase tracking-widest border-b pb-1">Información Personal Obligatoria</h4>
             <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-slate-400 uppercase">Fecha de Nacimiento</label>
                  <input type="date" className="w-full p-3 border-2 rounded-xl text-xs font-bold" value={form.birthDate} onChange={e => setForm({...form, birthDate: e.target.value})} />
                </div>
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-slate-400 uppercase">Sexo</label>
                  <select className="w-full p-3 border-2 rounded-xl text-xs font-bold uppercase" value={form.gender} onChange={e => setForm({...form, gender: e.target.value as any})}>
                    {Object.values(Gender).map(g => <option key={g} value={g}>{g}</option>)}
                  </select>
                </div>
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-slate-400 uppercase">Estado Civil</label>
