import React, { useState, useEffect, useRef } from 'react';
import { CompanyConfig, Employee, Role, AttendanceRecord, Payment, GlobalSettings } from './types.ts';
import AdminDashboard from './views/AdminDashboard.tsx';
import AttendanceSystem from './views/AttendanceSystem.tsx';
import Modal from './components/Modal.tsx';
import { db, collection, doc, onSnapshot, setDoc, addDoc, deleteDoc, compressData, decompressData } from './firebase.ts';

const App: React.FC = () => {
  const [currentUserRole, setCurrentUserRole] = useState<Role | null>(null);
  const [view, setView] = useState<'selection' | 'admin' | 'attendance' | 'setup'>('selection');
  const [isLoadingData, setIsLoadingData] = useState(true);

  const [dbStatus, setDbStatus] = useState<'connecting' | 'connected' | 'offline' | 'permission-error'>('connecting');
  const [lastDbError, setLastDbError] = useState<string | null>(null);

  const [isAdminLoginModalOpen, setIsAdminLoginModalOpen] = useState(false);
  const [adminPassInput, setAdminPassInput] = useState('');

  const [isRecoveryMode, setIsRecoveryMode] = useState(false);
  const [recoveryRuc, setRecoveryRuc] = useState('');
  const [recoveryKey, setRecoveryKey] = useState('');

  const unsubscribesRef = useRef<(() => void)[]>([]);

  const [appMode, setAppMode] = useState<'full' | 'attendance' | null>(
    (localStorage.getItem('app_mode') as 'full' | 'attendance') || null
  );

  const [showLogoutFeedback, setShowLogoutFeedback] = useState(false);
  const [modalAlert, setModalAlert] = useState<{isOpen: boolean, title: string, message: string, type: 'info' | 'success' | 'error'}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  const [company, setCompany] = useState<CompanyConfig | null>(null);
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);
  const [payments, setPayments] = useState<Payment[]>([]);

  const defaultSettings: GlobalSettings = {
    sbu: 482.00,
    sbuPrev: 460.00,
    iessRate: 0.0945,
    reserveRate: 0.0833,
    holidays: [],
    schedule: {
      monFri: { in1: '08:30', out1: '13:00', in2: '15:00', out2: '18:00' },
      sat: { in: '08:30', out: '13:00' },
      halfDayOff: 'Miércoles tarde'
    }
  };

  const [settings, setSettings] = useState<GlobalSettings>(defaultSettings);

  useEffect(() => {
    if (!appMode) setView('setup');
  }, [appMode]);

  const handleSetDeviceMode = (mode: 'full' | 'attendance') => {
    localStorage.setItem('app_mode', mode);
    setAppMode(mode);
    setView('selection');
  };

  const showAlert = (title: string, message: string, type: 'info' | 'success' | 'error' = 'info') => {
    setModalAlert({ isOpen: true, title, message, type });
  };

  const cleanListeners = () => {
    unsubscribesRef.current.forEach(unsub => unsub());
    unsubscribesRef.current = [];
  };

  useEffect(() => {
    const handleEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        setIsAdminLoginModalOpen(false);
        setIsRecoveryMode(false);
        setModalAlert(prev => ({ ...prev, isOpen: false }));
      }
    };
    window.addEventListener('keydown', handleEsc);

    cleanListeners();

    const handleFirestoreError = (module: string, error: any) => {
      console.warn(`Firestore Error [${module}]:`, error.code);
      if (error.code === 'permission-denied') {
        setDbStatus('permission-error');
        setLastDbError("PERMISOS DENEGADOS: Configure las reglas en Firebase Console.");
      } else {
        setDbStatus('offline');
      }

      const cached = localStorage.getItem(`cache_${module.toLowerCase()}`);
      if (cached) {
        try {
          const data = JSON.parse(cached);
          if (module === 'Company') setCompany(data);
          if (module === 'Settings') setSettings(data);
          if (module === 'Employees') setEmployees(data);
          if (module === 'Attendance') setAttendance(data);
          if (module === 'Payments') setPayments(data);
        } catch(e) {}
      }
      setIsLoadingData(false);
    };

    try {
      const unsubCompany = onSnapshot(doc(db, "config", "company"), (docSnap) => {
        if (docSnap.exists()) {
          const data = docSnap.data();
          const decompressed = data.payload ? decompressData(data.payload as string) : data as any;
          setCompany(decompressed);
          localStorage.setItem('cache_company', JSON.stringify(decompressed));
        }
        if (!docSnap.metadata.fromCache) setDbStatus('connected');
        setIsLoadingData(false);
      }, (err) => handleFirestoreError('Company', err));
      unsubscribesRef.current.push(unsubCompany);

      const unsubSettings = onSnapshot(doc(db, "config", "settings"), (docSnap) => {
        if (docSnap.exists()) {
          const data = docSnap.data();
          const dbSettings = data.payload ? decompressData(data.payload as string) : data as any;
          setSettings({ ...defaultSettings, ...dbSettings });
          localStorage.setItem('cache_settings', JSON.stringify(dbSettings));
        }
      }, (err) => handleFirestoreError('Settings', err));
      unsubscribesRef.current.push(unsubSettings);

      const unsubEmployees = onSnapshot(collection(db, "employees"), (snapshot) => {
        const data = snapshot.docs.map(d => {
          const raw = d.data();
          return raw.payload ? { ...decompressData(raw.payload as string), id: d.id } : { ...raw, id: d.id };
        }) as Employee[];
        setEmployees(data);
        localStorage.setItem('cache_employees', JSON.stringify(data));
      }, (err) => handleFirestoreError('Employees', err));
      unsubscribesRef.current.push(unsubEmployees);

      const unsubAttendance = onSnapshot(collection(db, "attendance"), (snapshot) => {
        const data = snapshot.docs.map(d => {
          const raw = d.data();
          return raw.payload ? { ...decompressData(raw.payload as string), id: d.id } : { ...raw, id: d.id };
        }) as AttendanceRecord[];
        setAttendance(data);
        localStorage.setItem('cache_attendance', JSON.stringify(data));
      }, (err) => handleFirestoreError('Attendance', err));
      unsubscribesRef.current.push(unsubAttendance);

      const unsubPayments = onSnapshot(collection(db, "payments"), (snapshot) => {
        const data = snapshot.docs.map(d => {
          const raw = d.data();
          return raw.payload ? { ...decompressData(raw.payload as string), id: d.id } : { ...raw, id: d.id };
        }) as Payment[];
        setPayments(data);
        localStorage.setItem('cache_payments', JSON.stringify(data));
      }, (err) => handleFirestoreError('Payments', err));
      unsubscribesRef.current.push(unsubPayments);

    } catch (e) {
      setDbStatus('offline');
      setIsLoadingData(false);
    }

    return () => {
      window.removeEventListener('keydown', handleEsc);
      cleanListeners();
    };
  }, []);

  const handleAdminLogin = () => {
    // EL PIN MAESTRO ES 906090 - FUNCIONA SIEMPRE
    if (adminPassInput === '906090') {
      setCurrentUserRole(Role.SUPER_ADMIN);
      localStorage.setItem('admin_logged_in', 'true');
      setView('admin');
      setIsAdminLoginModalOpen(false);
      setAdminPassInput('');
      return;
    }

    const foundAdmin = employees.find(e => e.pin === adminPassInput && (e.role === Role.SUPER_ADMIN || e.role === Role.PARTIAL_ADMIN));
    if (foundAdmin) {
      setCurrentUserRole(foundAdmin.role);
      localStorage.setItem('admin_logged_in', 'true');
      setView('admin');
      setIsAdminLoginModalOpen(false);
    } else {
      showAlert("Acceso Denegado", "El PIN ingresado no es válido para administración.", "error");
    }
    setAdminPassInput('');
  };

  const handleEmergencyRecovery = () => {
    const MASTER_RECOVERY_KEY = "ASISTUP-MASTER-ACCESS-2026";
    if (recoveryRuc === company?.ruc && recoveryKey === MASTER_RECOVERY_KEY) {
      setCurrentUserRole(Role.SUPER_ADMIN);
      localStorage.setItem('admin_logged_in', 'true');
      setView('admin');
      setIsAdminLoginModalOpen(false);
      setIsRecoveryMode(false);
    } else {
      showAlert("Fallo", "Datos de recuperación incorrectos.", "error");
    }
  };

  // Add missing function to handle employee updates
  const handleUpdateEmployees = async (newEmployees: Employee[]) => {
    try {
      for (const emp of newEmployees) {
        const { id, ...rest } = emp;
        await setDoc(doc(db, "employees", id), { payload: compressData(rest) });
      }
    } catch (e) {
      console.error("Error updating employees:", e);
    }
  };

  // Add missing function to handle payment updates
  const handleUpdatePayments = async (newPayments: Payment[]) => {
    try {
      for (const p of newPayments) {
        const { id, ...rest } = p;
        await setDoc(doc(db, "payments", id), { payload: compressData(rest) });
      }
    } catch (e) {
      console.error("Error updating payments:", e);
    }
  };

  if (isLoadingData) return null;

  return (
    <div className="min-h-screen bg-[#f8fafc]">
      {view === 'setup' && (
        <div className="min-h-screen gradient-blue flex flex-col items-center justify-center p-6 text-center">
            <h2 className="text-white text-3xl font-black mb-12 uppercase tracking-widest">Configuración Inicial</h2>
            <div className="flex gap-4">
              <button onClick={() => handleSetDeviceMode('full')} className="bg-white p-10 rounded-3xl font-black uppercase text-xs shadow-2xl">🖥️ Administración</button>
              <button onClick={() => handleSetDeviceMode('attendance')} className="bg-white p-10 rounded-3xl font-black uppercase text-xs shadow-2xl">🕒 Solo Marcación</button>
            </div>
        </div>
      )}

      {view === 'selection' && (
        <div className="min-h-screen gradient-blue flex flex-col items-center justify-center p-6">
          <div className="w-full max-w-lg bg-white p-16 rounded-[4.5rem] shadow-2xl text-center border">
            <h1 className="text-5xl font-[950] text-slate-900 mb-2 italic">ASIST UP</h1>
            <p className="text-blue-600 font-black uppercase tracking-[0.6em] text-[10px] mb-14">Management Suite</p>
            <div className="space-y-4">
              <button onClick={() => setView('attendance')} className="w-full py-6 bg-blue-700 text-white font-black rounded-[2rem] shadow-2xl uppercase text-[11px] tracking-widest active:scale-95 transition-all">Panel de Asistencia</button>
              {appMode === 'full' && (
                <button onClick={() => setIsAdminLoginModalOpen(true)} className="w-full py-5 text-slate-400 font-black uppercase text-[10px] tracking-widest hover:text-slate-900">Consola Administrativa</button>
              )}
            </div>
          </div>

          <Modal isOpen={isAdminLoginModalOpen} onClose={() => setIsAdminLoginModalOpen(false)} title="Autorización">
            {!isRecoveryMode ? (
              <div className="space-y-6 text-center">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Ingrese su PIN Administrativo</p>
                <input type="password" value={adminPassInput} onChange={e => setAdminPassInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleAdminLogin()} className="w-full border-2 p-5 rounded-2xl text-center text-3xl font-black focus:border-blue-600 outline-none" placeholder="••••••" autoFocus />
                <button onClick={handleAdminLogin} className="w-full py-4 bg-blue-700 text-white font-black rounded-xl uppercase text-[11px]">Ingresar</button>
                <p className="text-[10px] font-black text-blue-600 mt-4">PIN MAESTRO: 906090</p>
              </div>
            ) : (
              <div className="space-y-4">
                <input type="text" placeholder="RUC" className="w-full p-4 border rounded-xl" value={recoveryRuc} onChange={e => setRecoveryRuc(e.target.value)} />
                <input type="password" placeholder="LLAVE MAESTRA" className="w-full p-4 border rounded-xl" value={recoveryKey} onChange={e => setRecoveryKey(e.target.value)} />
                <button onClick={handleEmergencyRecovery} className="w-full py-4 bg-red-600 text-white font-black rounded-xl">Recuperar</button>
              </div>
            )}
            <button onClick={() => setIsRecoveryMode(!isRecoveryMode)} className="w-full mt-4 text-[9px] font-black uppercase text-slate-300">Modo de Emergencia</button>
          </Modal>
        </div>
      )}

      {view === 'attendance' && (
        <AttendanceSystem 
          employees={employees} 
          attendance={attendance} 
          onBack={() => setView('selection')} 
          settings={settings} 
          onRegister={async (r) => { await addDoc(collection(db, "attendance"), { payload: compressData(r), timestamp: r.timestamp }).catch(e => console.warn(e)); }} 
          onUpdateEmployees={handleUpdateEmployees} 
          dbStatus={dbStatus}
        />
      )}

      {view === 'admin' && currentUserRole && (
        <AdminDashboard 
          role={currentUserRole} 
          dbStatus={dbStatus}
          onLogout={() => { setView('selection'); setCurrentUserRole(null); }} 
          company={company}
          onUpdateCompany={async (c) => await setDoc(doc(db, "config", "company"), { payload: compressData(c) })}
          employees={employees}
          onUpdateEmployees={handleUpdateEmployees}
          attendance={attendance}
          payments={payments}
          onUpdatePayments={handleUpdatePayments}
          settings={settings}
          onUpdateSettings={async (s) => await setDoc(doc(db, "config", "settings"), { payload: compressData(s) })}
          onUpdateAppMode={(mode) => setAppMode(mode)}
          appMode={appMode || 'full'}
        />
      )}

      <Modal isOpen={modalAlert.isOpen} onClose={() => setModalAlert({...modalAlert, isOpen: false})} title={modalAlert.title} type={modalAlert.type}>
          <div className="text-center p-6">
              <p className="font-bold uppercase text-xs">{modalAlert.message}</p>
              <button onClick={() => setModalAlert({...modalAlert, isOpen: false})} className="w-full mt-8 py-4 bg-black text-white rounded-xl uppercase font-black">Aceptar</button>
          </div>
      </Modal>
    </div>
  );
};

