import EmployeeModule from './modules/EmployeeModule.tsx';
import PayrollModule from './modules/PayrollModule.tsx';
import PaymentsModule from './modules/PaymentsModule.tsx';
import SettingsModule from './modules/SettingsModule.tsx';
import ReportsModule from './modules/ReportsModule.tsx';
import AiAssistant from './modules/AiAssistant.tsx';
import Modal from '../components/Modal.tsx';
import { DAILY_QUOTES, ECUADOR_HOLIDAYS } from '../constants.tsx';

interface AdminDashboardProps {
  role: Role;
  dbStatus: 'connecting' | 'connected' | 'offline' | 'permission-error';
  onLogout: () => void;
  company: CompanyConfig | null;
  onUpdateCompany: (config: CompanyConfig) => void;
  employees: Employee[];
  onUpdateEmployees: (employees: Employee[]) => void;
  attendance: AttendanceRecord[];
  payments: Payment[];
  onUpdatePayments: (payments: Payment[]) => void;
  settings: GlobalSettings;
  onUpdateSettings: (settings: GlobalSettings) => void;
  onUpdateAppMode: (mode: 'full' | 'attendance') => void;
  appMode: 'full' | 'attendance';
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  role, dbStatus, onLogout, company, onUpdateCompany, employees, onUpdateEmployees, attendance, payments, onUpdatePayments, settings, onUpdateSettings, onUpdateAppMode, appMode 
}) => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'company' | 'employees' | 'payroll' | 'payments' | 'settings' | 'reports' | 'ai' | 'notifications'>('dashboard');
  const [showFixDbModal, setShowFixDbModal] = useState(false);

  const today = useMemo(() => new Date(), []);
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();

  // Generación de días del calendario para el mes actual
  const calendarDays = useMemo(() => {
    const firstDay = new Date(currentYear, currentMonth, 1).getDay();
    const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
    const days = [];

    // Padding para el inicio del mes (ajuste de domingo a lunes si es necesario, aquí estándar)
    for (let i = 0; i < firstDay; i++) {
      days.push(null);
    }

    for (let d = 1; d <= daysInMonth; d++) {
      days.push(d);
    }
    return days;
  }, [currentMonth, currentYear]);

  const monthName = useMemo(() => {
    return new Intl.DateTimeFormat('es-EC', { month: 'long' }).format(today).toUpperCase();
  }, [today]);

  const dayOfYear = useMemo(() => {
    const start = new Date(today.getFullYear(), 0, 0);
    const diff = today.getTime() - start.getTime();
    return Math.floor(diff / (1000 * 60 * 60 * 24));
  }, [today]);

  const dailyQuote = DAILY_QUOTES[dayOfYear % DAILY_QUOTES.length];

  const getStatusConfig = () => {
    switch(dbStatus) {
      case 'connected': return { color: 'bg-emerald-500', text: 'Online / Sincronizado' };
      case 'permission-error': return { color: 'bg-red-600', text: 'Error de Permisos (Click aquí)', click: true };
      case 'offline': return { color: 'bg-yellow-500', text: 'Modo Offline / Caché' };
      default: return { color: 'bg-blue-400', text: 'Conectando...' };
    }
  };

  const statusCfg = getStatusConfig();

  // Helper para identificar eventos en un día específico
  const getDayEvents = (day: number) => {
    const events = [];
    const dateStr = `${currentYear}-${String(currentMonth + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;

    // Feriados Nacionales
    const nationalHoliday = ECUADOR_HOLIDAYS.find(h => h.month === currentMonth && h.day === day);
    if (nationalHoliday) events.push({ type: 'holiday', label: nationalHoliday.name });

    // Feriados Personalizados (Settings)
    if (settings.holidays.includes(dateStr)) events.push({ type: 'custom-holiday', label: 'Feriado Local' });

    // Cumpleaños
    const birthdayEmps = employees.filter(e => {
      if (!e.birthDate) return false;
      const bDate = new Date(e.birthDate);
      return bDate.getUTCMonth() === currentMonth && bDate.getUTCDate() === day;
    });
    birthdayEmps.forEach(e => events.push({ type: 'birthday', label: `Cumpleaños: ${e.name}` }));

    return events;
  };

  return (
    <div className="flex h-screen bg-[#fcfdfe] overflow-hidden flex-col md:flex-row">
      <Sidebar role={role} activeTab={activeTab} setActiveTab={setActiveTab} onLogout={onLogout} companyName={company?.name} />

      <main className="flex-1 overflow-y-auto px-8 py-8 custom-scroll">
        <header className="flex justify-between items-center mb-10 no-print">
          <div className="flex items-center gap-4">
            <h1 className="text-4xl font-[950] text-slate-900 tracking-tighter italic uppercase">Admin Hub</h1>
            <button 
              onClick={() => statusCfg.click && setShowFixDbModal(true)}
              className={`flex items-center gap-2 px-4 py-2 bg-white border-2 border-slate-100 rounded-full shadow-sm hover:border-blue-500 transition-all`}
            >
               <div className={`w-3 h-3 rounded-full ${statusCfg.color} animate-pulse`}></div>
               <span className="text-[10px] font-black uppercase tracking-widest text-slate-500">{statusCfg.text}</span>
            </button>
          </div>
        </header>

        {dbStatus === 'permission-error' && (
          <div onClick={() => setShowFixDbModal(true)} className="mb-10 p-6 bg-red-50 border-2 border-red-200 rounded-[2.5rem] cursor-pointer hover:bg-red-100 transition-all flex items-center justify-between group">
             <div className="flex items-center gap-6">
                <span className="text-4xl">🛠️</span>
                <div>
                   <p className="font-black text-red-600 uppercase text-xs tracking-widest">Atención: El sistema no puede leer los datos</p>
                   <p className="text-[10px] text-red-500 font-bold uppercase mt-1 italic">Click para ver cómo solucionar el error de permisos de Firebase.</p>
                </div>
             </div>
             <span className="text-red-300 group-hover:text-red-600 font-black">❯❯❯</span>
          </div>
        )}

        <div className="fade-in">
          {activeTab === 'dashboard' && (
            <div className="space-y-10">
               {/* Imagen e Inspiración Corporativa */}
               <div className="bg-slate-900 p-16 rounded-[4rem] text-white shadow-2xl relative overflow-hidden flex flex-col justify-center min-h-[300px]">
                  <div className="absolute top-0 right-0 w-96 h-96 bg-blue-600/20 rounded-full blur-[100px] -mr-48 -mt-48"></div>
                  <div className="absolute bottom-0 left-0 w-64 h-64 bg-indigo-600/10 rounded-full blur-[80px] -ml-32 -mb-32"></div>
                  <p className="text-blue-500 font-black text-xs uppercase tracking-[0.5em] mb-6 relative z-10">Visión Estratégica</p>
                  <h2 className="text-4xl md:text-5xl font-[950] italic tracking-tighter leading-tight relative z-10 max-w-4xl">
                    "{dailyQuote}"
                  </h2>
               </div>

               {/* Calendario Institucional */}
               <div className="bg-white p-10 rounded-[3.5rem] border shadow-sm">
                  <header className="flex justify-between items-center mb-10 border-b pb-6">
                    <div>
                      <h3 className="text-2xl font-[950] text-slate-900 uppercase italic leading-none">Calendario Institucional</h3>
                      <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest mt-2">{monthName} {currentYear}</p>
                    </div>
                    <div className="flex gap-4 text-[9px] font-black uppercase tracking-widest">
                       <div className="flex items-center gap-2"><span className="w-3 h-3 bg-red-500 rounded-full"></span> Feriados</div>
                       <div className="flex items-center gap-2"><span className="w-3 h-3 bg-blue-500 rounded-full"></span> Cumpleaños</div>
                    </div>
                  </header>

                  <div className="grid grid-cols-7 gap-px bg-slate-100 border border-slate-100 rounded-3xl overflow-hidden shadow-inner">
                    {['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'].map(d => (
                      <div key={d} className="bg-slate-50 p-4 text-center text-[10px] font-black text-slate-400 uppercase tracking-widest">{d}</div>
                    ))}
                    {calendarDays.map((day, idx) => {
                      const events = day ? getDayEvents(day) : [];
                      const isToday = day === today.getDate() && currentMonth === today.getMonth();

                      return (
                        <div key={idx} className={`bg-white min-h-[120px] p-3 transition-colors hover:bg-slate-50/50 ${!day ? 'bg-slate-50/20' : ''}`}>
                          {day && (
                            <>
                              <div className="flex justify-between items-start mb-2">
                                <span className={`text-sm font-black ${isToday ? 'w-7 h-7 bg-blue-600 text-white rounded-full flex items-center justify-center' : 'text-slate-400'}`}>
                                  {day}
                                </span>
                              </div>
                              <div className="space-y-1">
                                {events.map((ev, eIdx) => (
                                  <div key={eIdx} className={`p-1.5 rounded-lg text-[8px] font-black uppercase tracking-tighter leading-none truncate ${
                                    ev.type === 'birthday' ? 'bg-blue-50 text-blue-600 border border-blue-100' : 'bg-red-50 text-red-600 border border-red-100'
                                  }`}>
                                    {ev.type === 'birthday' ? '🎂 ' : '🗓️ '}{ev.label}
                                  </div>
                                ))}
                              </div>
                            </>
                          )}
                        </div>
                      );
                    })}
                  </div>
               </div>
            </div>
          )}

          {activeTab === 'company' && <CompanyModule company={company} onUpdate={onUpdateCompany} role={role} />}
          {activeTab === 'employees' && <EmployeeModule employees={employees} onUpdate={onUpdateEmployees} role={role} attendance={attendance} payments={payments} company={company} />}
          {activeTab === 'payroll' && <PayrollModule employees={employees} payments={payments} onUpdatePayments={onUpdatePayments} attendance={attendance} company={company} settings={settings} role={role} />}
          {activeTab === 'payments' && <PaymentsModule employees={employees} payments={payments} onUpdate={onUpdatePayments} role={role} company={company} />}
          {activeTab === 'settings' && <SettingsModule settings={settings} onUpdate={onUpdateSettings} role={role} allData={{ company, employees, attendance, payments, settings }} />}
          {activeTab === 'reports' && <ReportsModule employees={employees} payments={payments} attendance={attendance} company={company} settings={settings} role={role} />}
          {activeTab === 'ai' && <AiAssistant employees={employees} attendance={attendance} payments={payments} role={role} />}
        </div>
      </main>

      <Modal isOpen={showFixDbModal} onClose={() => setShowFixDbModal(false)} title="Solucionar Modo Offline">
         <div className="space-y-6">
            <p className="text-xs font-bold text-slate-600 leading-relaxed uppercase">
              Para que los PINs funcionen y el sistema esté Online, debe activar las reglas en su Consola de Firebase:
            </p>
            <ol className="list-decimal list-inside space-y-4 text-[10px] font-black uppercase text-slate-500">
               <li>Vaya a <a href="https://console.firebase.google.com" target="_blank" className="text-blue-600 underline">Firebase Console</a>.</li>
               <li>Seleccione su proyecto (asist-up-6ccd1).</li>
               <li>Vaya a <span className="text-slate-900">Firestore Database</span> &gt; <span className="text-slate-900">Rules</span>.</li>
               <li>Copie y pegue el siguiente código y presione <span className="text-blue-600 font-black">PUBLISH</span>:</li>
            </ol>
            <div className="bg-slate-900 p-6 rounded-2xl text-emerald-400 font-mono text-[10px] whitespace-pre overflow-x-auto border-2 border-emerald-900 shadow-2xl">
{`rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /{document=**} {
      allow read, write: if true;
    }
  }
}`}
            </div>
            <p className="text-[9px] text-red-500 font-black uppercase bg-red-50 p-4 rounded-xl text-center">
               UNA VEZ PUBLICADAS LAS REGLAS, RECARGUE ESTA PÁGINA Y EL SISTEMA RECONOCERÁ LOS PINS.
            </p>
            <button onClick={() => window.location.reload()} className="w-full py-4 bg-blue-700 text-white font-black rounded-xl uppercase text-xs tracking-widest shadow-xl active:scale-95 transition-all">Recargar App Ahora</button>
         </div>
      </Modal>
    </div>
  );
};

