                    </div>
                 </div>

                 <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 max-h-[400px] overflow-y-auto custom-scroll pr-2">
                    {todayMarkings.length === 0 ? (
                      <div className="col-span-full py-20 flex flex-col items-center justify-center opacity-40">
                         <span className="text-5xl mb-4">⌛</span>
                         <p className="text-[12px] font-black uppercase tracking-[0.2em] text-slate-400">Esperando marcaciones para el día de hoy...</p>
                      </div>
                    ) : (
                      todayMarkings.map((mark) => {
                        const emp = employees.find(e => e.id === mark.employeeId);

                        // Lógica para determinar el tipo exacto de jornada marcada
                        const empMarksToday = (attendance || [])
                          .filter(a => a.employeeId === mark.employeeId && a.timestamp.startsWith(todayDateStr))
                          .sort((a, b) => a.timestamp.localeCompare(b.timestamp));

                        let specificLabel = "";
                        let labelColor = "";

                        if (mark.type === 'half_day') {
                          specificLabel = "Media Jornada Libre";
                          labelColor = "bg-amber-500 text-white";
                        } else if (mark.type === 'in') {
                          const inIndex = empMarksToday.filter(m => m.type === 'in').findIndex(m => m.id === mark.id);
                          specificLabel = inIndex === 0 ? "Entrada Mañana" : "Entrada Tarde";
                          labelColor = inIndex === 0 ? "bg-emerald-600 text-white" : "bg-cyan-600 text-white";
                        } else if (mark.type === 'out') {
                          const outIndex = empMarksToday.filter(m => m.type === 'out').findIndex(m => m.id === mark.id);
                          specificLabel = outIndex === 0 ? "Salida Medio Día" : "Salida Fin Jornada";
                          labelColor = outIndex === 0 ? "bg-orange-600 text-white" : "bg-pink-600 text-white";
                        }

                        return (
                          <div key={mark.id} className="flex items-center gap-4 bg-slate-50 p-5 rounded-3xl border border-slate-100 transition-all hover:shadow-md hover:bg-white group">
                             <div className="w-12 h-12 bg-white rounded-2xl border flex items-center justify-center overflow-hidden shrink-0">
                                {emp?.photo ? <img src={emp.photo} className="w-full h-full object-cover" /> : <span className="text-[14px] font-black uppercase text-slate-300">{emp?.name[0]}</span>}
                             </div>
                             <div className="flex-1 min-w-0">
                                <p className="text-[11px] font-[950] text-slate-900 uppercase leading-none truncate">{emp?.surname} {emp?.name}</p>
                                <div className="flex items-center gap-2 mt-2">
                                   <span className={`text-[7px] font-black uppercase px-2 py-0.5 rounded-full ${labelColor}`}>
                                      {specificLabel}
                                   </span>
                                   {mark.isLate && <span className="text-[7px] font-black uppercase bg-red-100 text-red-600 px-1.5 py-0.5 rounded-full animate-pulse">Retraso</span>}
                                </div>
                             </div>
                             <div className="text-right">
                                <p className="text-[13px] font-[950] text-slate-900 tabular-nums">{new Date(mark.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit', second: '2-digit'})}</p>
                                <p className="text-[8px] font-black text-slate-400 uppercase tracking-tighter mt-1">{mark.status}</p>
                             </div>
                          </div>
                        );
                      })
                    )}
                 </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                <div className="bg-white p-10 rounded-[3.5rem] border border-slate-100 shadow-sm flex flex-col min-h-[480px]">
                   <div className="flex justify-between items-center mb-10">
                      <div>
                        <h3 className="text-[14px] font-black text-slate-900 uppercase tracking-widest leading-none mb-3">Calendario Corporativo</h3>
                        <p className="text-[13px] text-slate-400 font-bold uppercase tracking-widest">{new Intl.DateTimeFormat('es-EC', { month: 'long', year: 'numeric' }).format(today)}</p>
                      </div>
                      <div className="flex gap-6">
                         <span className="flex items-center gap-2 text-[12px] font-black text-blue-600 uppercase"><div className="w-2.5 h-2.5 bg-blue-500 rounded-full"></div> Feriado</span>
                         <span className="flex items-center gap-2 text-[12px] font-black text-emerald-600 uppercase"><div className="w-2.5 h-2.5 bg-emerald-500 rounded-full"></div> Cumple</span>
                      </div>
                   </div>
                   <div className="grid grid-cols-7 gap-3 text-center flex-1 items-center">
                      {['D', 'L', 'M', 'M', 'J', 'V', 'S'].map(d => (
                        <div key={d} className="text-[13px] font-black text-slate-300 uppercase py-3">{d}</div>
                      ))}
                      {calendarDays.map((day, i) => {
                        const isHoliday = day && monthHolidays.some(h => h.day === day);
                        const isBirthday = day && monthBirthdays.some(e => new Date(e.birthDate).getDate() + 1 === day);
                        const isToday = day === today.getDate();

                        return (
                          <div key={i} className={`
                            relative aspect-square flex items-center justify-center text-[14px] font-black rounded-3xl transition-all
                            ${!day ? 'opacity-0' : 'hover:bg-slate-50 cursor-pointer'}
                            ${isToday ? 'bg-slate-900 text-white shadow-xl scale-110' : 'text-slate-600'}
                            ${isHoliday ? 'text-blue-600 bg-blue-50/50' : ''}
                            ${isBirthday ? 'text-emerald-600 bg-emerald-50/50' : ''}
                          `}>
                            {day}
                            {(isHoliday || isBirthday) && <div className={`absolute bottom-2 w-2 h-2 rounded-full ${isHoliday ? 'bg-blue-600' : 'bg-emerald-600'}`}></div>}
                          </div>
                        );
                      })}
                   </div>
                </div>

                <div className="bg-slate-50 p-10 rounded-[3.5rem] border border-slate-100 flex flex-col min-h-[480px]">
                   <h3 className="text-[14px] font-black text-slate-400 uppercase tracking-widest border-b-2 border-slate-200 pb-5 mb-8">Agenda de Novedades</h3>
                   <div className="space-y-4 overflow-y-auto custom-scroll flex-1 pr-3">
                      {monthHolidays.map((h, i) => (
                         <div key={i} className="flex gap-5 items-center bg-white p-6 rounded-3xl border border-slate-200/50 shadow-sm">
                            <div className="w-12 h-12 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center text-2xl">📅</div>
                            <div>
                               <p className="text-[13px] font-black text-slate-900 uppercase leading-none">{h.name}</p>
                               <p className="text-[11px] font-black text-blue-500 uppercase mt-3">Día {h.day}</p>
                            </div>
                         </div>
                      ))}
                      {monthBirthdays.map((e, i) => (
                         <div key={i} className="flex gap-5 items-center bg-white p-6 rounded-3xl border border-slate-200/50 shadow-sm">
                            <div className="w-12 h-12 rounded-2xl overflow-hidden border bg-slate-100 flex items-center justify-center text-[14px] font-black uppercase">
                               {e.photo ? <img src={e.photo} className="w-full h-full object-cover" /> : <span className="text-slate-400">{e.name[0]}</span>}
                            </div>
                            <div>
                               <p className="text-[13px] font-black text-slate-900 uppercase leading-none">{e.surname} {e.name}</p>
                               <p className="text-[11px] font-black text-emerald-500 uppercase mt-3">Natalicio • Día {new Date(e.birthDate).getDate() + 1}</p>
                            </div>
                         </div>
                      ))}
                      {monthHolidays.length === 0 && monthBirthdays.length === 0 && (
                        <div className="h-full flex flex-col items-center justify-center py-20 opacity-30">
                          <span className="text-6xl mb-6">🍃</span>
                          <p className="text-[13px] text-slate-400 font-black uppercase tracking-widest">Sin eventos próximos</p>
                        </div>
                      )}
                   </div>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'notifications' && (
            <NotificationsModule 
              notifications={notifications} 
              onToggleRead={(id) => setNotifications(prev => prev.map(n => n.id === id ? {...n, isRead: !n.isRead} : n))}
              onToggleProcessed={(id) => setNotifications(prev => prev.map(n => n.id === id ? {...n, isProcessed: !n.isProcessed} : n))}
              onClearAll={() => {
                const allIds = notifications.map(n => n.id);
                setDismissedNotificationIds(prev => new Set([...prev, ...allIds]));
                setNotifications([]);
              }}
            />
          )}

          {activeTab === 'company' && <CompanyModule company={company} onUpdate={onUpdateCompany} role={role} />}
          {activeTab === 'employees' && <EmployeeModule employees={employees} onUpdate={onUpdateEmployees} role={role} attendance={attendance} payments={payments} company={company} />}
          {activeTab === 'payroll' && <PayrollModule employees={employees} payments={payments} onUpdatePayments={onUpdatePayments} onUpdateEmployees={onUpdateEmployees} attendance={attendance} company={company} settings={settings} role={role} />}
          {activeTab === 'payments' && <PaymentsModule employees={employees} payments={payments} onUpdate={onUpdatePayments} role={role} company={company} />}
          {activeTab === 'settings' && <SettingsModule settings={settings} onUpdate={onUpdateSettings} role={role} onPurge={handlePurgeData} allData={{ company, employees, attendance, payments, settings }} />}
          {activeTab === 'reports' && <ReportsModule employees={employees} payments={payments} attendance={attendance} company={company} settings={settings} role={role} />}
          {activeTab === 'ai' && <AiAssistant employees={employees} attendance={attendance} payments={payments} role={role} />}
        </div>
      </main>
    </div>
  );
};

export default AdminDashboard;

import React, { useState } from 'react';
import { Employee, Payment, AttendanceRecord, CompanyConfig, GlobalSettings, Role } from '../../types.ts';
import Modal from '../../components/Modal.tsx';
import JSZip from 'jszip';

interface ReportsModuleProps {
  employees: Employee[];
  payments: Payment[];
  attendance: AttendanceRecord[];
  company: CompanyConfig | null;
  settings: GlobalSettings;
  role: Role;
}

const ReportsModule: React.FC<ReportsModuleProps> = ({ employees, payments = [], attendance = [], company, settings, role }) => {
  const [reportType, setReportType] = useState<'attendance' | 'payments' | 'history' | 'master'>('attendance');
  const [searchTerm, setSearchTerm] = useState('');
  const [isZipping, setIsZipping] = useState(false);
  const [feedback, setFeedback] = useState({ isOpen: false, title: '', message: '', type: 'success' as any });

  const getCSVData = (type: 'employees' | 'payroll' | 'attendance' | 'novedades' | 'bajas') => {
    let csv = "\uFEFF";
    if (type === 'employees') {
      csv += "ID,COLABORADOR,CARGO,INGRESO,AFILIACION IESS,FONDOS RESERVA,DECIMOS,SUELDO,STATUS\n";
      employees.forEach(e => {
        csv += `"${e.identification}","${e.surname} ${e.name}","${e.role}","${e.startDate}","${e.isAffiliated ? 'SI' : 'NO'}","${e.reserveFundType || 'N/A'}","${e.overSalaryType}","${e.salary.toFixed(2)}","${e.status}"\n`;
      });
    } else if (type === 'payroll') {
      csv += "VOUCHER,FECHA,BENEFICIARIO,CONCEPTO,METODO,MONTO,STATUS\n";
      payments.forEach(p => {
        const emp = employees.find(e => e.id === p.employeeId);
        csv += `"${p.voucherCode}","${new Date(p.date).toLocaleDateString()}","${emp?.surname} ${emp?.name}","${p.type}","${p.method}","${p.amount.toFixed(2)}","${p.status}"\n`;
      });
    } else if (type === 'attendance') {
      csv += "FECHA,COLABORADOR,ID,TIPO,ESTADO,ATRASO,JUSTIFICACION\n";
      attendance.forEach(a => {
        const emp = employees.find(e => e.id === a.employeeId);
        csv += `"${new Date(a.timestamp).toLocaleString()}","${emp?.surname} ${emp?.name}","${emp?.identification}","${a.type}","${a.status}","${a.isLate ? 'SI' : 'NO'}","${a.justification || ''}"\n`;
      });
    } else if (type === 'novedades') {
      csv += "FECHA REGISTRO,COLABORADOR,EVENTO ADMINISTRATIVO\n";
      employees.forEach(e => {
        if (e.observations) e.observations.forEach(obs => {
          csv += `"${new Date(obs.date).toLocaleString()}","${e.surname} ${e.name}","${obs.text}"\n`;
        });
      });
    } else if (type === 'bajas') {
      csv += "COLABORADOR,IDENTIFICACION,SALIDA,MOTIVO LEGAL,DETALLES FINALES\n";
      employees.filter(e => e.status === 'terminated').forEach(e => {
        csv += `"${e.surname} ${e.name}","${e.identification}","${e.terminationDate}","${e.terminationReason}","${e.terminationDetails}"\n`;
      });
    }
    return csv;
  };

  const handleDownloadMasterZip = async () => {
    setIsZipping(true);
    try {
      const zip = new JSZip();
      const folder = zip.folder(`ARCHIVO_MAESTRO_ASISTUP_${new Date().getFullYear()}`);

      folder?.file("1_CENSO_PERSONAL_MAESTRO.csv", getCSVData('employees'));
      folder?.file("2_REGISTRO_PAGOS_NOMINA.csv", getCSVData('payroll'));
      folder?.file("3_BITACORA_ASISTENCIA.csv", getCSVData('attendance'));
      folder?.file("4_HISTORIAL_NOVEDADES.csv", getCSVData('novedades'));
      folder?.file("5_EXPEDIENTES_DESVINCULADOS.csv", getCSVData('bajas'));

      const blob = await zip.generateAsync({ type: "blob" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = `CONSOLIDADO_MASTER_ASISTUP_${new Date().toISOString().split('T')[0]}.zip`;
      link.click();
      setFeedback({ isOpen: true, title: "Éxito Corporativo", message: "Contenedor ZIP generado y descargado correctamente para archivo físico.", type: "success" });
    } catch (e) {
      setFeedback({ isOpen: true, title: "Fallo Crítico", message: "No se pudo consolidar el paquete comprimido.", type: "error" });
    } finally {
      setIsZipping(false);
    }
  };

  const generateReportExcel = (type: any) => {
    const csv = getCSVData(type);
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `REPORTE_MASTER_${type.toUpperCase()}.csv`;
    link.click();
  };

  const generateReportPDF = (type: any) => {
    setReportType(type);
    setTimeout(() => window.print(), 500);
  };

  const attendanceToDisplay = (attendance || []).filter(a => {
    const emp = employees.find(e => e.id === a.employeeId);
    return `${emp?.surname} ${emp?.name} ${emp?.identification}`.toLowerCase().includes(searchTerm.toLowerCase());
  }).sort((a, b) => {
    const empA = employees.find(e => e.id === a.employeeId);
    const empB = employees.find(e => e.id === b.employeeId);
    const nameA = `${empA?.surname || ''} ${empA?.name || ''}`;
    const nameB = `${empB?.surname || ''} ${empB?.name || ''}`;
    if (nameA !== nameB) return nameA.localeCompare(nameB);
    return a.timestamp.localeCompare(b.timestamp);
  });

  const paymentsToDisplay = payments.filter(p => {
    const emp = employees.find(e => e.id === p.employeeId);
    return `${emp?.surname} ${emp?.name} ${p.voucherCode}`.toLowerCase().includes(searchTerm.toLowerCase());
  }).sort((a,b) => b.date.localeCompare(a.date));

  const historyToDisplay = employees.filter(e => {
    const searchStr = `${e.name} ${e.surname} ${e.identification} ${e.status}`.toLowerCase();
    return searchStr.includes(searchTerm.toLowerCase());
  }).sort((a,b) => b.startDate.localeCompare(a.startDate));

  return (
    <div className="space-y-6 md:space-y-8 fade-in">
      <div className="bg-white p-6 md:p-10 rounded-[2.5rem] shadow-sm border no-print flex flex-col md:flex-row justify-between items-center gap-6">
        <div>
           <h2 className="text-2xl font-[950] text-slate-900 uppercase italic">Centro de Reportes Maestro</h2>
           <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest mt-2">Auditoría y Gestión de Datos Corporativos</p>
        </div>
        <div className="flex flex-col sm:flex-row gap-4 w-full md:w-auto">
          <div className="flex gap-2 overflow-x-auto pb-2 no-scrollbar">
            {['attendance', 'payments', 'history', 'master'].map(t => (
              <button key={t} onClick={() => {setReportType(t as any); setSearchTerm('');}} className={`whitespace-nowrap px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${reportType === t ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-50 text-slate-400 border'}`}>
                {t === 'attendance' ? 'Asistencia' : t === 'payments' ? 'Pagos' : t === 'history' ? 'Historial' : 'Archivo Maestro'}
              </button>
            ))}
          </div>
          {reportType !== 'master' && <input type="text" placeholder="Filtrar por nombre o CI..." className="flex-1 p-3 border-2 rounded-xl text-[11px] font-bold uppercase" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />}
        </div>
      </div>

      <div className="bg-white rounded-[2.5rem] shadow-sm border overflow-hidden" id="reports-printable-area">
         {/* CABECERA ESTRICTA PARA IMPRESIÓN */}
         <div className="hidden print:block p-10 border-b-4 border-black text-center space-y-4">
            <div className="flex items-center justify-center gap-6">
               <div className="w-20 h-20 border-2 border-black flex items-center justify-center overflow-hidden">
                  {company?.logo ? <img src={company.logo} className="w-full h-full object-contain" /> : <span className="text-2xl font-black">LOGO</span>}
               </div>
               <div className="text-left">
                  <h1 className="text-3xl font-[950] uppercase italic leading-none">{company?.name || 'EMPRESA INSTITUCIONAL'}</h1>
                  <p className="text-sm font-black uppercase mt-1">RUC: {company?.ruc || '0000000000001'}</p>
                  <p className="text-[10px] font-bold uppercase tracking-tighter">{company?.address || 'QUITO, ECUADOR'}</p>
               </div>
            </div>
            <div className="pt-4 border-t-2 border-black/10">
               <p className="text-[12px] font-[950] uppercase tracking-[0.3em]">Reporte de {reportType.toUpperCase()}</p>
               <p className="text-[8px] font-bold uppercase opacity-60">Documento Generado el {new Date().toLocaleString()}</p>
            </div>
         </div>

         {reportType === 'master' ? (
           <div className="p-10 md:p-16 space-y-12 no-print text-center">
              <header className="border-b pb-8">
                <h3 className="text-2xl font-black text-slate-900 uppercase tracking-widest">Gestión de Archivo Maestro</h3>
                <p className="text-[11px] font-black text-blue-600 uppercase mt-2 tracking-widest italic leading-relaxed">Consolidado integral para cumplimiento legal y auditorías externas de talento humano</p>
              </header>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 text-left">
                 {[
                   { id: 'employees', title: 'Censo Personal', icon: '👥', desc: 'Fichas, cargos y sueldos.' },
                   { id: 'payroll', title: 'Registro Pagos', icon: '💰', desc: 'Nómina, bonos y egresos.' },
                   { id: 'attendance', title: 'Asistencia', icon: '🕒', desc: 'Marcaciones y atrasos.' },
                   { id: 'novedades', title: 'Bitácora Novedades', icon: '📝', desc: 'Incidencias administrativas.' },
                   { id: 'bajas', title: 'Bajas Laborales', icon: '🚪', desc: 'Historial de desvinculaciones.' }
                 ].map(seg => (
                   <div key={seg.id} className="bg-slate-50 p-6 rounded-[2rem] border-2 border-slate-100 flex flex-col justify-between hover:border-blue-200 transition-colors">
                      <div className="mb-4 flex items-start gap-3">
                        <div className="w-10 h-10 bg-white rounded-xl shadow-inner flex items-center justify-center text-2xl">{seg.icon}</div>
                        <div>
                           <h4 className="text-[11px] font-[950] uppercase text-slate-900 leading-none mb-1">{seg.title}</h4>
                           <p className="text-[9px] text-slate-400 font-bold uppercase tracking-tighter leading-tight">{seg.desc}</p>
                        </div>
                      </div>
                      <div className="flex gap-2">
                        <button onClick={() => generateReportExcel(seg.id)} className="flex-1 py-2.5 bg-emerald-600 text-white text-[9px] font-black rounded-lg uppercase shadow-md active:scale-95 transition-all">Excel</button>
                        <button onClick={() => generateReportPDF(seg.id as any)} className="flex-1 py-2.5 bg-blue-700 text-white text-[9px] font-black rounded-lg uppercase shadow-md active:scale-95 transition-all">PDF</button>
                      </div>
                   </div>
                 ))}
              </div>
              <div className="pt-10 border-t flex flex-col items-center gap-6">
                 <button 
                   onClick={handleDownloadMasterZip} 
                   disabled={isZipping} 
                   className="w-full max-w-md py-6 bg-slate-900 text-white font-[950] rounded-[2rem] uppercase text-[12px] tracking-[0.4em] shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-4 group"
                 >
                   <span>{isZipping ? '⌛' : '📦'}</span>
                   {isZipping ? 'CONSOLIDANDO DATOS...' : 'Descargar Archivo Maestro .ZIP'}
                 </button>
                 <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest text-center italic opacity-60">Este paquete comprimido incluye todos los reportes superiores en formato CSV para respaldo institucional.</p>
              </div>
           </div>
         ) : (
           <div className="p-4 md:p-10">
              <div className="table-responsive">
                  <table className="w-full text-left print:table-auto border-collapse text-[11px] font-bold uppercase">
                      <thead className="bg-slate-50 text-[10px] font-black text-slate-400 print:bg-white print:text-black">
                        <tr>
                           <th className="p-5 border-b-2">Detalle de Registro</th>
                           <th className="p-5 border-b-2">Colaborador Principal</th>
                           <th className="p-5 border-b-2 text-right">Situación / Valor</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y print:text-black">
                          {reportType === 'attendance' && attendanceToDisplay.map(a => (
                            <tr key={a.id}>
                               <td className="p-5">{new Date(a.timestamp).toLocaleString()}</td>
                               <td className="p-5">{employees.find(e => e.id === a.employeeId)?.surname} {employees.find(e => e.id === a.employeeId)?.name}</td>
                               <td className="p-5 text-right font-black">{a.status} - {a.type}</td>
                            </tr>
                          ))}
                          {reportType === 'payments' && paymentsToDisplay.map(p => (
                            <tr key={p.id}>
                               <td className="p-5"><p className="text-blue-600">{p.voucherCode}</p><p className="text-[9px] text-slate-400">{new Date(p.date).toLocaleDateString()}</p></td>
                               <td className="p-5">{employees.find(e => e.id === p.employeeId)?.surname}</td>
                               <td className="p-5 text-right font-[950] text-emerald-700">${p.amount.toFixed(2)}</td>
                            </tr>
                          ))}
                          {reportType === 'history' && historyToDisplay.map(e => (
                            <tr key={e.id}>
                               <td className="p-5"><p className="text-slate-900">{e.surname} {e.name}</p><p className="text-[9px] text-slate-400">CI: {e.identification}</p></td>
                               <td className="p-5">{e.role}</td>
                               <td className={`p-5 text-right font-[950] ${e.status === 'active' ? 'text-emerald-600' : 'text-red-500'}`}>{e.status}</td>
                            </tr>
                          ))}
                      </tbody>
                  </table>
              </div>
           </div>
         )}
      </div>

      <Modal isOpen={feedback.isOpen} onClose={() => setFeedback({...feedback, isOpen: false})} title={feedback.title} type={feedback.type}>
          <div className="text-center p-6 space-y-6">
              <p className="text-slate-700 font-bold uppercase text-[11px] italic leading-relaxed">{feedback.message}</p>
              <button onClick={() => setFeedback({...feedback, isOpen: false})} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] tracking-widest shadow-xl active:scale-95 transition-all">Entendido</button>
          </div>
      </Modal>
    </div>
  );
};

export default ReportsModule;

import React, { useState, useEffect, useRef } from 'react';
import { CompanyConfig, Employee, Role, AttendanceRecord, Payment, GlobalSettings } from './types.ts';
import AdminDashboard from './views/AdminDashboard.tsx';
import AttendanceSystem from './views/AttendanceSystem.tsx';
import Modal from './components/Modal.tsx';
import { db, collection, doc, onSnapshot, setDoc, addDoc, deleteDoc, compressData, decompressData } from './firebase.ts';

const App: React.FC = () => {
  const [currentUserRole, setCurrentUserRole] = useState<Role | null>(null);
  const [view, setView] = useState<'selection' | 'admin' | 'attendance' | 'setup'>('selection');
  const [isLoadingData, setIsLoadingData] = useState(true);
  const [isDbConnected, setIsDbConnected] = useState(false);
  const [isAdminLoginModalOpen, setIsAdminLoginModalOpen] = useState(false);
  const [adminPassInput, setAdminPassInput] = useState('');

  const [isRecoveryMode, setIsRecoveryMode] = useState(false);
  const [recoveryRuc, setRecoveryRuc] = useState('');
  const [recoveryKey, setRecoveryKey] = useState('');

  const unsubscribesRef = useRef<(() => void)[]>([]);

  const [appMode, setAppMode] = useState<'full' | 'attendance' | null>(
    (localStorage.getItem('app_mode') as 'full' | 'attendance') || null
  );

  const [showLogoutFeedback, setShowLogoutFeedback] = useState(false);
  const [modalAlert, setModalAlert] = useState<{isOpen: boolean, title: string, message: string, type: 'info' | 'success' | 'error'}>({
    isOpen: false, title: '', message: '', type: 'info'
  });

  const [company, setCompany] = useState<CompanyConfig | null>(null);
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);
  const [payments, setPayments] = useState<Payment[]>([]);

  const defaultSettings: GlobalSettings = {
    sbu: 482.00,
    sbuPrev: 460.00,
    iessRate: 0.0945,
    reserveRate: 0.0833,
    holidays: [],
    schedule: {
      monFri: { in1: '08:30', out1: '13:00', in2: '15:00', out2: '18:00' },
      sat: { in: '08:30', out: '13:00' },
      halfDayOff: 'Miércoles tarde'
    }
  };

  const [settings, setSettings] = useState<GlobalSettings>(defaultSettings);

  useEffect(() => {
    if (!appMode) {
      setView('setup');
    }
  }, [appMode]);

  const handleSetDeviceMode = (mode: 'full' | 'attendance') => {
    localStorage.setItem('app_mode', mode);
    setAppMode(mode);
    setView('selection');
  };

  const showAlert = (title: string, message: string, type: 'info' | 'success' | 'error' = 'info') => {
    setModalAlert({ isOpen: true, title, message, type });
  };

  const cleanListeners = () => {
    unsubscribesRef.current.forEach(unsub => unsub());
    unsubscribesRef.current = [];
  };

  useEffect(() => {
    if ("Notification" in window) {
      Notification.requestPermission();
    }

    const handleEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        setIsAdminLoginModalOpen(false);
        setIsRecoveryMode(false);
        setModalAlert(prev => ({ ...prev, isOpen: false }));
      }
    };
    window.addEventListener('keydown', handleEsc);

    cleanListeners();

    const handleFirestoreError = (module: string, error: any) => {
      console.warn(`Firestore Error [${module}]:`, error.message || error);
      setIsDbConnected(false);

      const cached = localStorage.getItem(`cache_${module.toLowerCase()}`);
      if (cached) {
        const data = JSON.parse(cached);
        if (module === 'Company') setCompany(data);
        if (module === 'Settings') setSettings(data);
        if (module === 'Employees') setEmployees(data);
        if (module === 'Attendance') setAttendance(data);
        if (module === 'Payments') setPayments(data);
      }
      setIsLoadingData(false);
    };

    try {
      const unsubCompany = onSnapshot(doc(db, "config", "company"), (docSnap) => {
        if (docSnap.exists()) {
          const data = docSnap.data();
          const decompressed = data.payload ? decompressData(data.payload as string) : data as any;
          setCompany(decompressed);
          localStorage.setItem('cache_company', JSON.stringify(decompressed));
        }
        setIsDbConnected(true);
        setIsLoadingData(false);
      }, (err) => handleFirestoreError('Company', err));
      unsubscribesRef.current.push(unsubCompany);

      const unsubSettings = onSnapshot(doc(db, "config", "settings"), (docSnap) => {
        if (docSnap.exists()) {
          const data = docSnap.data();
          const dbSettings = data.payload ? decompressData(data.payload as string) : data as any;
          const mergedSettings = {
            ...defaultSettings,
            ...dbSettings,
            schedule: {
              ...defaultSettings.schedule,
              ...(dbSettings.schedule || {}),
              monFri: {
                ...defaultSettings.schedule.monFri,
                ...(dbSettings.schedule?.monFri || {})
              },
              sat: {
                ...defaultSettings.schedule.sat,
                ...(dbSettings.schedule?.sat || {})
              }
            }
          };
          setSettings(mergedSettings);
          localStorage.setItem('cache_settings', JSON.stringify(mergedSettings));
        }
      }, (err) => handleFirestoreError('Settings', err));
      unsubscribesRef.current.push(unsubSettings);

      const unsubEmployees = onSnapshot(collection(db, "employees"), (snapshot) => {
        const data = snapshot.docs.map(d => {
          const raw = d.data();
          return raw.payload ? { ...decompressData(raw.payload as string), id: d.id } : { ...raw, id: d.id };
        }) as Employee[];
        setEmployees(data);
        localStorage.setItem('cache_employees', JSON.stringify(data));
      }, (err) => handleFirestoreError('Employees', err));
      unsubscribesRef.current.push(unsubEmployees);

      const unsubAttendance = onSnapshot(collection(db, "attendance"), (snapshot) => {
        const data = snapshot.docs.map(d => {
          const raw = d.data();
          return raw.payload ? { ...decompressData(raw.payload as string), id: d.id } : { ...raw, id: d.id };
        }) as AttendanceRecord[];
        setAttendance(data);
        localStorage.setItem('cache_attendance', JSON.stringify(data));
      }, (err) => handleFirestoreError('Attendance', err));
      unsubscribesRef.current.push(unsubAttendance);

      const unsubPayments = onSnapshot(collection(db, "payments"), (snapshot) => {
        const data = snapshot.docs.map(d => {
          const raw = d.data();
          return raw.payload ? { ...decompressData(raw.payload as string), id: d.id } : { ...raw, id: d.id };
        }) as Payment[];
        setPayments(data);
        localStorage.setItem('cache_payments', JSON.stringify(data));
      }, (err) => handleFirestoreError('Payments', err));
      unsubscribesRef.current.push(unsubPayments);

    } catch (e) {
      console.error("Initial load failed:", e);
      setIsLoadingData(false);
    }

    return () => {
      window.removeEventListener('keydown', handleEsc);
      cleanListeners();
    };
  }, []);

  const handleAdminLogin = () => {
    let role: Role | null = null;
    if (adminPassInput === 'admin123') role = Role.SUPER_ADMIN;
    else {
      const foundAdmin = employees.find(e => e.pin === adminPassInput && (e.role === Role.SUPER_ADMIN || e.role === Role.PARTIAL_ADMIN));
      if (foundAdmin) role = foundAdmin.role;
    }

    if (role) {
      setCurrentUserRole(role);
      localStorage.setItem('admin_logged_in', 'true');
      setView('admin');
      setIsAdminLoginModalOpen(false);
    } else {
      showAlert("Error de Acceso", "Credencial no válida o sin privilegios.", "error");
    }
    setAdminPassInput('');
  };

  const handleEmergencyRecovery = () => {
    const MASTER_RECOVERY_KEY = "ASISTUP-MASTER-ACCESS-2026";
    if (recoveryRuc === company?.ruc && recoveryKey === MASTER_RECOVERY_KEY) {
      setCurrentUserRole(Role.SUPER_ADMIN);
      localStorage.setItem('admin_logged_in', 'true');
      setView('admin');
      setIsAdminLoginModalOpen(false);
      setIsRecoveryMode(false);
      setRecoveryRuc('');
      setRecoveryKey('');
    } else {
      showAlert("Fallo de Autenticación", "Los datos de recuperación de emergencia son incorrectos.", "error");
    }
  };

  const finalizeLogout = () => {
    setCurrentUserRole(null);
    localStorage.removeItem('admin_logged_in');
    setView('selection');
    setShowLogoutFeedback(false);
  };

  useEffect(() => {
    if (showLogoutFeedback) {
      const timer = setTimeout(() => {
        finalizeLogout();
      }, 1500);
      return () => clearTimeout(timer);
    }
  }, [showLogoutFeedback]);

  const handleUpdateEmployees = async (emps: Employee[]) => {
    const currentIds = new Set<string>(emps.map(e => e.id));
    const previousIds = new Set<string>(employees.map(e => e.id));
    for (const id of previousIds) {
      if (!currentIds.has(id)) {
        await deleteDoc(doc(db, "employees", id)).catch(e => console.warn("Delete employee failed:", e));
      }
    }
    for (const e of emps) {
      await setDoc(doc(db, "employees", e.id), { payload: compressData(e) }).catch(e => console.warn("Save employee failed:", e));
    }
  };

  const handleUpdatePayments = async (pys: Payment[]) => {
    const currentIds = new Set<string>(pys.map(p => p.id));
    const previousIds = new Set<string>(payments.map(p => p.id));
    for (const id of previousIds) {
      if (!currentIds.has(id)) {
        await deleteDoc(doc(db, "payments", id)).catch(e => console.warn("Delete payment failed:", e));
      }
    }
    for (const p of pys) {
      if (p.id.length > 15) {
        await addDoc(collection(db, "payments"), { payload: compressData(p) }).catch(e => console.warn("Add payment failed:", e));
      } else {
        await setDoc(doc(db, "payments", p.id), { payload: compressData(p) }).catch(e => console.warn("Update payment failed:", e));
      }
    }
  };

  // NUEVA FUNCIÓN PARA GESTIONAR ACTUALIZACIÓN DE ASISTENCIA (AUTORIZACIONES)
  const handleUpdateAttendance = async (recs: AttendanceRecord[]) => {
    for (const r of recs) {
       await setDoc(doc(db, "attendance", r.id), { payload: compressData(r), timestamp: r.timestamp }).catch(e => console.warn("Update attendance failed:", e));
    }
  };

  if (isLoadingData) return null;

  return (
    <div className="min-h-screen bg-[#f8fafc]">
      {view === 'setup' && (
        <div className="min-h-screen gradient-blue flex flex-col items-center justify-center p-6">
          <div className="w-full max-w-lg bg-white/95 backdrop-blur-3xl p-10 md:p-16 rounded-[4rem] shadow-2xl text-center border border-white/20 fade-in">
            <h2 className="text-3xl font-[950] text-slate-900 mb-2 tracking-tighter uppercase leading-none">CONFIGURACIÓN INICIAL</h2>
            <p className="text-blue-600 font-black uppercase tracking-[0.4em] text-[9px] mb-12">Defina el tipo de instalación para este equipo</p>

            <div className="space-y-4">
              <button 
                onClick={() => handleSetDeviceMode('full')}
                className="w-full group p-6 border-2 border-slate-100 hover:border-blue-600 rounded-[2.5rem] bg-slate-50 transition-all text-left flex items-center gap-5 active:scale-95"
              >
                <div className="w-12 h-12 bg-blue-600 text-white rounded-2xl flex items-center justify-center text-xl shrink-0 group-hover:scale-110 transition-transform">🖥️</div>
                <div>
                   <p className="font-black text-slate-900 text-xs uppercase tracking-tight">Administración Completa</p>
                   <p className="text-[9px] text-slate-400 font-bold uppercase mt-1">Acceso a todos los módulos y reportes.</p>
                </div>
              </button>

              <button 
                onClick={() => handleSetDeviceMode('attendance')}
                className="w-full group p-6 border-2 border-slate-100 hover:border-emerald-600 rounded-[2.5rem] bg-slate-50 transition-all text-left flex items-center gap-5 active:scale-95"
              >
                <div className="w-12 h-12 bg-emerald-600 text-white rounded-2xl flex items-center justify-center text-xl shrink-0 group-hover:scale-110 transition-transform">🕒</div>
                <div>
                   <p className="font-black text-slate-900 text-xs uppercase tracking-tight">Terminal de Asistencia (Kiosco)</p>
                   <p className="text-[9px] text-slate-400 font-bold uppercase mt-1">Solo marcación. Sin funciones administrativas.</p>
                </div>
              </button>
            </div>

            <p className="text-[8px] text-slate-300 font-black uppercase mt-12 tracking-widest italic">Esta configuración podrá ser reseteada por un Super Administrador.</p>
          </div>
        </div>
      )}

      {view === 'selection' && (
        <div className="min-h-screen gradient-blue flex flex-col items-center justify-center p-6">
          <div className="w-full max-w-lg bg-white/95 backdrop-blur-3xl p-10 md:p-16 rounded-[4.5rem] shadow-2xl text-center border border-white/20">
            <h1 className="text-4xl md:text-5xl font-[950] text-slate-900 mb-2 tracking-tighter uppercase leading-none">ASIST UP</h1>
            <p className="text-blue-600 font-black uppercase tracking-[0.6em] text-[10px] mb-14">Management Suite</p>

            <div className="space-y-4">
              <button onClick={() => setView('attendance')} className="w-full py-6 bg-blue-700 text-white font-black rounded-[2.5rem] shadow-2xl hover:bg-blue-800 transition-all uppercase text-[11px] tracking-widest active:scale-95">Panel de Asistencia</button>

              {appMode === 'full' && (
                <button onClick={() => setIsAdminLoginModalOpen(true)} className="w-full py-5 text-slate-400 font-black hover:text-slate-900 transition-all uppercase text-[10px] tracking-widest">Consola Administrativa</button>
              )}
            </div>
          </div>

          <Modal isOpen={isAdminLoginModalOpen} onClose={() => { setIsAdminLoginModalOpen(false); setIsRecoveryMode(false); }} title={isRecoveryMode ? "Acceso de Emergencia" : "Autorización"} maxWidth="max-w-[320px]">
            {!isRecoveryMode ? (
              <div className="space-y-6 p-2 text-center relative">
                <button 
                  onClick={() => setIsRecoveryMode(true)} 
                  className="absolute -top-4 -right-4 w-10 h-10 flex items-center justify-center text-slate-50 hover:text-red-200 transition-colors opacity-10 hover:opacity-100 z-10"
                  aria-label="Acceso Crítico"
                >
                  <span className="text-[10px]">🛡️</span>
                </button>

                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Contraseña o PIN</p>
                <input 
                  type="password"
                  value={adminPassInput} 
                  onChange={e => setAdminPassInput(e.target.value)} 
                  onKeyDown={e => e.key === 'Enter' && handleAdminLogin()} 
                  className="w-full border-2 border-slate-100 rounded-2xl p-4 text-center text-2xl font-black focus:border-blue-600 outline-none bg-slate-50" 
                  placeholder="••••••" 
                  autoFocus 
                />
                <button onClick={handleAdminLogin} className="w-full py-4 bg-blue-700 text-white font-black rounded-xl uppercase text-[11px] tracking-widest shadow-2xl active:scale-95 transition-all">Ingresar</button>
              </div>
            ) : (
              <div className="space-y-5 p-2 text-center">
                <p className="text-[10px] font-black text-red-600 uppercase tracking-widest">Protocolo de Emergencia</p>
                <div className="space-y-3">
                  <input 
                    type="text" 
                    placeholder="RUC INSTITUCIONAL" 
                    className="w-full p-4 border-2 rounded-xl text-[11px] font-black uppercase text-center focus:border-red-600 outline-none"
                    value={recoveryRuc}
                    onChange={e => setRecoveryRuc(e.target.value)}
                  />
                  <input 
                    type="password" 
                    placeholder="LLAVE MAESTRA DE SEGURIDAD" 
                    className="w-full p-4 border-2 rounded-xl text-[11px] font-black uppercase text-center focus:border-red-600 outline-none"
                    value={recoveryKey}
                    onChange={e => setRecoveryKey(e.target.value)}
                  />
                </div>
                <div className="flex flex-col gap-2">
                  <button onClick={handleEmergencyRecovery} className="w-full py-4 bg-red-600 text-white font-black rounded-xl uppercase text-[10px] tracking-widest shadow-xl active:scale-95 transition-all">Recuperar Acceso</button>
                  <button onClick={() => setIsRecoveryMode(false)} className="w-full py-3 bg-slate-100 text-slate-500 font-black rounded-xl uppercase text-[9px] tracking-widest">Volver</button>
                </div>
                <p className="text-[8px] text-slate-400 font-medium italic mt-2">Este acceso otorga privilegios de Super Administrador para restablecer credenciales perdidas.</p>
              </div>
            )}
          </Modal>
        </div>
      )}

      {view === 'attendance' && (
        <AttendanceSystem 
          employees={employees} 
          attendance={attendance} 
          onBack={() => setView('selection')} 
          settings={settings} 
          onRegister={async (r) => { await addDoc(collection(db, "attendance"), { payload: compressData(r), timestamp: r.timestamp }).catch(e => console.warn("Register attendance failed:", e)); }} 
          onUpdateEmployees={handleUpdateEmployees} 
        />
      )}

      {view === 'admin' && currentUserRole && appMode === 'full' && (
        <AdminDashboard 
          role={currentUserRole} 
          isDbConnected={isDbConnected}
          onLogout={() => setShowLogoutFeedback(true)} 
          company={company}
          onUpdateCompany={async (c) => await setDoc(doc(db, "config", "company"), { payload: compressData(c) }).catch(e => console.warn("Update company failed:", e))}
          employees={employees}
          onUpdateEmployees={handleUpdateEmployees}
          attendance={attendance}
          onUpdateAttendance={handleUpdateAttendance}
          payments={payments}
          onUpdatePayments={handleUpdatePayments}
          settings={settings}
          onUpdateSettings={async (s) => await setDoc(doc(db, "config", "settings"), { payload: compressData(s) }).catch(e => console.warn("Update settings failed:", e))}
          onUpdateAppMode={(mode) => { setAppMode(mode); localStorage.setItem('app_mode', mode); }}
          appMode={appMode}
        />
      )}

      <Modal isOpen={showLogoutFeedback} onClose={() => {}} title="Salida" type="success" maxWidth="max-w-[280px]">
         <div className="text-center space-y-6 p-2">
            <div className="w-16 h-16 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center text-3xl mx-auto animate-pulse">🔒</div>
            <h3 className="text-xl font-[950] text-slate-900 uppercase tracking-tighter leading-none">Cerrando Sesión</h3>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Sincronizando datos finales...</p>
         </div>
      </Modal>

      <Modal isOpen={modalAlert.isOpen} onClose={() => setModalAlert({...modalAlert, isOpen: false})} title={modalAlert.title} type={modalAlert.type} maxWidth="max-w-[280px]">
           <div className="text-center p-4">
              <p className="text-slate-800 font-bold uppercase text-[11px]">{modalAlert.message}</p>
              <button onClick={() => setModalAlert({...modalAlert, isOpen: false})} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase mt-6 active:scale-95 transition-all">Ok</button>
           </div>
      </Modal>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { Employee, AttendanceRecord, GlobalSettings } from '../types.ts';
import Clock from '../components/Clock.tsx';
import Modal from '../components/Modal.tsx';

const APP_ICON_SVG = "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'%3E%3Cdefs%3E%3ClinearGradient id='g' x1='0%25' y1='0%25' x2='100%25' y2='100%25'%3E%3Cstop offset='0%25' style='stop-color:%233b82f6;'/%3E%3Cstop offset='100%25' style='stop-color:%231e3a8a;'/%3E%3C/linearGradient%3E%3C/defs%3E%3Ccircle cx='50' cy='50' r='45' fill='none' stroke='url(%23g)' stroke-width='6' stroke-dasharray='15 5'/%3E%3Ccircle cx='50' cy='50' r='32' fill='none' stroke='url(%23g)' stroke-width='5' stroke-dasharray='10 4' opacity='0.7'/%3E%3Ccircle cx='50' cy='50' r='18' fill='none' stroke='url(%23g)' stroke-width='4' opacity='0.4'/%3E%3Ccircle cx='50' cy='50' r='6' fill='%233b82f6'/%3E%3C/svg%3E";

interface AttendanceSystemProps {
  employees: Employee[];
  attendance: AttendanceRecord[];
  onRegister: (record: AttendanceRecord) => void;
  onBack: () => void;
  onUpdateEmployees: (employees: Employee[]) => void;
  settings: GlobalSettings;
}

const AttendanceSystem: React.FC<AttendanceSystemProps> = ({ employees, attendance, onRegister, onBack, onUpdateEmployees, settings }) => {
  const [pin, setPin] = useState('');
  const [status, setStatus] = useState<'idle' | 'confirm' | 'forgotten_form' | 'success' | 'error' | 'change_pin' | 'regularize_form'>('idle');
  const [isProcessing, setIsProcessing] = useState(false);
  const [currentEmp, setCurrentEmp] = useState<Employee | null>(null);
  const [newPin, setNewPin] = useState('');
  const [forgotCi, setForgotCi] = useState('');
  const [successMsg, setSuccessMsg] = useState('');
  const [isBirthdaySuccess, setIsBirthdaySuccess] = useState(false);
  const [feedback, setFeedback] = useState<{isOpen: boolean, title: string, message: string, type: 'success' | 'error' | 'info'}>({
    isOpen: false, title: '', message: '', type: 'success'
  });

  const [regularizeData, setRegularizeData] = useState({
    date: new Date().toISOString().split('T')[0],
    time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }),
    type: 'in' as 'in' | 'out'
  });

  const today = useMemo(() => new Date(), []);
  const todayDateStr = today.toISOString().split('T')[0];
  const currentMonth = today.getMonth();
  const currentDay = today.getDate();

  const monthBirthdays = useMemo(() => {
    return employees.filter(e => {
      if (!e.birthDate || e.status !== 'active') return false;
      return new Date(e.birthDate).getMonth() === currentMonth;
    }).sort((a, b) => {
      const dayA = new Date(a.birthDate).getDate();
      const dayB = new Date(b.birthDate).getDate();
      return dayA - dayB;
    });
  }, [employees, currentMonth]);

  const empTodayRecords = useMemo(() => {
    if (!currentEmp) return [];
    return attendance.filter(a => a.employeeId === currentEmp.id && a.timestamp.startsWith(todayDateStr));
  }, [attendance, currentEmp, todayDateStr]);

  const halfDayDoneThisWeek = useMemo(() => {
    if (!currentEmp) return false;
    const now = new Date();
    const day = now.getDay();
    const diff = now.getDate() - day + (day === 0 ? -6 : 1);
    const startOfWeek = new Date(now.setDate(diff));
    startOfWeek.setHours(0, 0, 0, 0);

    return attendance.some(a => {
      const aDate = new Date(a.timestamp);
      return a.employeeId === currentEmp.id && a.type === 'half_day' && aDate >= startOfWeek;
    });
  }, [attendance, currentEmp]);

  const insCount = empTodayRecords.filter(r => r.type === 'in').length;
  const outsCount = empTodayRecords.filter(r => r.type === 'out').length;
  const halfDayDoneToday = empTodayRecords.some(r => r.type === 'half_day');

  const handleMark = (type: 'in' | 'out' | 'half_day') => {
    if (!currentEmp || isProcessing) return;
    const now = new Date();
    const day = now.getDay();
    let isCriticalLate = false;

    if (type !== 'half_day') {
      if (day >= 1 && day <= 5) {
        const [h1, m1] = settings.schedule.monFri.in1.split(':').map(Number);
        const schedIn1 = new Date(now); schedIn1.setHours(h1, m1, 0, 0);
        const [h2, m2] = settings.schedule.monFri.in2.split(':').map(Number);
        const schedIn2 = new Date(now); schedIn2.setHours(h2, m2, 0, 0);

        if (type === 'in') {
          const targetSched = (now > schedIn1 && now < schedIn2) ? schedIn2 : schedIn1;
          const diffMins = (now.getTime() - targetSched.getTime()) / (1000 * 60);
          if (diffMins > 15) isCriticalLate = true;
        }
      } else if (day === 6) {
        const [hs, ms] = settings.schedule.sat.in.split(':').map(Number);
        const schedSatIn = new Date(now); schedSatIn.setHours(hs, ms, 0, 0);

        if (type === 'in') {
          const diffMins = (now.getTime() - schedSatIn.getTime()) / (1000 * 60);
          if (diffMins > 15) isCriticalLate = true;
        }
      }
    }

    processRegistration(type, isCriticalLate);
  };

  const handleRegularize = () => {
    if (!currentEmp || isProcessing) return;
    setIsProcessing(true);

    const fullTimestamp = `${regularizeData.date}T${regularizeData.time}:00.000Z`;

    const record: AttendanceRecord = {
      id: Math.random().toString(36).substr(2, 9),
      employeeId: currentEmp.id,
      timestamp: fullTimestamp,
      type: regularizeData.type,
      status: 'pending_approval',
      justification: 'SIN ACCESO AL PANEL',
      isForgotten: true
    };

    onRegister(record);
    setSuccessMsg("SOLICITUD ENVIADA A RRHH");
    setStatus('success');
    setPin('');

    setTimeout(() => {
      setStatus('idle');
      setCurrentEmp(null);
      setIsProcessing(false);
    }, 3000);
  };

  const processRegistration = (type: 'in' | 'out' | 'half_day', isLate: boolean, justification?: string) => {
    setIsProcessing(true);

    if (isLate && Notification.permission === "granted") {
      new Notification("ALERTA DE ASISTENCIA", {
        body: `El colaborador ${currentEmp?.name} ${currentEmp?.surname} ha marcado con más de 15 minutos de retraso.`,
        icon: APP_ICON_SVG
      });
    }

    const record: AttendanceRecord = {
      id: Math.random().toString(36).substr(2, 9),
      employeeId: currentEmp!.id,
      timestamp: new Date().toISOString(),
      type,
      status: 'confirmed',
      isLate,
      justification
    };

    onRegister(record);

    let msg = "";
    const bDate = currentEmp?.birthDate ? new Date(currentEmp.birthDate) : null;
    const isTodayBirthday = bDate && (bDate.getMonth() === currentMonth && bDate.getDate() + 1 === currentDay);

    if (isTodayBirthday) {
       msg = "¡FELIZ CUMPLEAÑOS! 🎂🎈";
       setIsBirthdaySuccess(true);
    } else {
       if (type === 'in') msg = "INGRESO REGISTRADO";
       else if (type === 'out') msg = "SALIDA REGISTRADA";
       else msg = "MEDIA JORNADA REGISTRADA";
       setIsBirthdaySuccess(false);
    }

    setSuccessMsg(msg);
    setStatus('success');
    setPin('');

    setTimeout(() => {
      setStatus('idle');
      setCurrentEmp(null);
      setIsProcessing(false);
      setIsBirthdaySuccess(false);
    }, isTodayBirthday ? 5000 : 3000);
  };

  const handlePinChange = () => {
    if (newPin.length !== 6 || newPin === currentEmp?.pin) {
      setFeedback({ isOpen: true, title: "Error de PIN", message: "Ingrese un PIN nuevo de 6 dígitos diferente al actual.", type: "error" });
      return;
    }
    const updated = employees.map(e => e.id === currentEmp?.id ? { ...e, pin: newPin, pinChanged: true, pinNeedsReset: false, pinResetRequested: false } : e);
    onUpdateEmployees(updated);
    setFeedback({ isOpen: true, title: "PIN Actualizado", message: "Su clave de acceso ha sido cambiada. Ahora puede marcar su asistencia.", type: "success" });
    setStatus('confirm');
    setNewPin('');
  };

  const handleRequestPinReset = () => {
    const emp = employees.find(e => e.identification === forgotCi && e.status === 'active');
    if (emp) {
      const updated = employees.map(e => e.id === emp.id ? { ...e, pinResetRequested: true } : e);
      onUpdateEmployees(updated);
      if (Notification.permission === "granted") {
        new Notification("SOLICITUD DE ACCESO", { body: `El colaborador ${emp.name} solicita resetear su PIN de asistencia.`, icon: APP_ICON_SVG });
      }
      setFeedback({ isOpen: true, title: "Solicitud Recibida", message: "Su solicitud ha sido enviada al administrador. RRHH autorizará su nuevo acceso a la brevedad.", type: "info" });
      setStatus('idle');
      setForgotCi('');
    } else {
      setFeedback({ isOpen: true, title: "Error", message: "Identificación no encontrada en el sistema.", type: "error" });
    }
  };

  useEffect(() => {
    if (pin.length === 6 && status === 'idle' && !isProcessing) {
      const emp = employees.find(e => e.pin === pin && e.status === 'active');
      if (emp) {
        setCurrentEmp(emp);
        if (!emp.pinChanged || emp.pinNeedsReset) setStatus('change_pin');
        else setStatus('confirm');
      } else {
        setStatus('error');
        setTimeout(() => { setStatus('idle'); setPin(''); }, 1500);
      }
    }
  }, [pin, employees, status, isProcessing]);

  useEffect(() => {
    const handleKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onBack();
      if (status !== 'idle' || isProcessing) return;
      if (e.key >= '0' && e.key <= '9' && pin.length < 6) setPin(p => p + e.key);
      if (e.key === 'Backspace') setPin(p => p.slice(0, -1));
    };
    window.addEventListener('keydown', handleKey);
    return () => window.removeEventListener('keydown', handleKey);
  }, [pin, status, isProcessing]);

  return (
    <div className="min-h-screen gradient-blue flex flex-col items-center justify-center p-4">
      {status === 'success' && (
        <div className="fixed inset-0 z-[100] bg-slate-900/80 backdrop-blur-md flex flex-col items-center justify-center fade-in p-6">
           <div className={`p-10 rounded-[2.5rem] shadow-2xl flex flex-col items-center text-center animate-in zoom-in max-w-sm ${isBirthdaySuccess ? 'bg-gradient-to-br from-yellow-100 to-white' : 'bg-white'}`}>
              <div className={`w-20 h-20 rounded-full flex items-center justify-center text-4xl mb-4 shadow-lg animate-bounce ${isBirthdaySuccess ? 'bg-yellow-400 text-white' : 'bg-emerald-500 text-white'}`}>
                {isBirthdaySuccess ? '🎂' : '✓'}
              </div>
              <h2 className={`font-[950] text-xl uppercase tracking-tighter leading-none ${isBirthdaySuccess ? 'text-yellow-600 animate-pulse' : 'text-slate-900'}`}>{successMsg}</h2>
              {isBirthdaySuccess && <p className="text-xl mt-2 animate-bounce">🎈🎊🎁</p>}
              <p className="text-slate-400 font-bold text-[9px] uppercase tracking-widest mt-2 italic">Sincronizado con RRHH</p>
           </div>
        </div>
      )}

      <div className={`w-full max-w-lg bg-white/95 backdrop-blur-3xl rounded-3xl md:rounded-[3.5rem] shadow-2xl p-6 md:p-12 flex flex-col items-center relative overflow-hidden ${status === 'success' ? 'opacity-0' : 'fade-in'}`}>
        <div className="mb-4 md:mb-6 transform scale-[0.6] sm:scale-[0.8]"><Clock /></div>

        {status === 'idle' && (
          <div className="w-full text-center">
            {monthBirthdays.length > 0 && (
              <div className="mb-6 p-4 bg-yellow-50/50 border border-yellow-100 rounded-2xl animate-in slide-in-from-top-4 duration-1000">
                <p className="text-[8px] font-black text-yellow-600 uppercase tracking-widest mb-2 flex items-center justify-center gap-2">
                  <span>🎂</span> Celebramos a nuestros cumpleañeros <span>🎈</span>
                </p>
                <div className="flex flex-wrap justify-center gap-2">
                  {monthBirthdays.slice(0, 3).map(e => (
                    <div key={e.id} className="bg-white px-3 py-1 rounded-full shadow-sm border border-yellow-100 flex items-center gap-2">
                      <span className="text-[9px] font-black text-slate-700 uppercase">{e.name} {e.surname}</span>
                      <span className="text-[7px] font-bold text-yellow-600 bg-yellow-50 px-1.5 rounded-full">{new Date(e.birthDate).getDate() + 1}/{currentMonth + 1}</span>
                    </div>
                  ))}
                </div>
              </div>
            )}
            <h2 className="text-[10px] md:text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4 md:mb-6">Ingresar PIN de 6 dígitos</h2>
            <div className="flex gap-1.5 md:gap-2 justify-center mb-8 md:mb-10">
              {[...Array(6)].map((_, i) => (
                <div key={i} className={`w-8 h-12 md:w-10 md:h-16 border-b-4 flex items-center justify-center text-2xl md:text-4xl font-black transition-all ${pin.length > i ? 'border-blue-600 text-slate-900' : 'border-slate-100'}`}>
                  {pin[i] ? '•' : ''}
                </div>
              ))}
            </div>
            <div className="grid grid-cols-3 gap-2 md:gap-3 max-w-[280px] md:max-w-[340px] mx-auto mb-8 md:mb-10">
              {[1, 2, 3, 4, 5, 6, 7, 8, 9, 'C', 0, '←'].map(btn => (
                <button key={btn} onClick={() => { if (btn === 'C') setPin(''); else if (btn === '←') setPin(p => p.slice(0, -1)); else if (pin.length < 6) setPin(p => p + btn); }} className="h-14 md:h-18 bg-white hover:bg-blue-700 hover:text-white rounded-xl md:rounded-2xl text-xl md:text-2xl font-black border border-slate-200 active:scale-90 transition-all shadow-sm flex items-center justify-center">{btn}</button>
              ))}
            </div>
            <button onClick={() => setStatus('forgotten_form')} className="w-full py-3 md:py-4 bg-slate-50 border border-slate-100 rounded-xl md:rounded-2xl text-[9px] md:text-[10px] font-black text-blue-600 uppercase tracking-widest hover:bg-blue-50 transition-all active:scale-95">¿Olvidó su PIN? Solicitar Reseteo</button>
          </div>
        )}

        {status === 'regularize_form' && (
           <div className="text-center w-full space-y-6 animate-in zoom-in">
              <div className="p-6 bg-blue-50 border border-blue-100 rounded-3xl mb-4">
                  <p className="text-[11px] font-black text-blue-700 uppercase tracking-widest leading-relaxed italic">
                    "Tu integridad es el valor más grande de nuestra institución. Si por motivos de acceso no pudiste marcar, regulariza tu jornada con total honestidad. La transparencia nos fortalece."
                  </p>
              </div>
              <div className="space-y-4 text-left">
                  <div className="space-y-1">
                    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Fecha Olvidada</label>
                    <input type="date" value={regularizeData.date} onChange={e => setRegularizeData({...regularizeData, date: e.target.value})} className="w-full p-4 border-2 rounded-xl text-xs font-black" />
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                       <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Hora Aproximada</label>
                       <input type="time" value={regularizeData.time} onChange={e => setRegularizeData({...regularizeData, time: e.target.value})} className="w-full p-4 border-2 rounded-xl text-xs font-black" />
                    </div>
                    <div className="space-y-1">
                       <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Tipo</label>
                       <select value={regularizeData.type} onChange={e => setRegularizeData({...regularizeData, type: e.target.value as any})} className="w-full p-4 border-2 rounded-xl text-[10px] font-black uppercase">
                          <option value="in">Ingreso</option>
                          <option value="out">Salida</option>
                       </select>
                    </div>
                  </div>
                  <div className="space-y-1">
                    <label className="text-[9px] font-black text-blue-600 uppercase tracking-widest">Justificación Automática</label>
                    <input readOnly value="SIN ACCESO AL PANEL" className="w-full p-4 border-2 bg-slate-50 rounded-xl text-[10px] font-black text-slate-400" />
                  </div>
              </div>
              <div className="flex gap-3">
                 <button onClick={() => setStatus('confirm')} className="flex-1 py-4 bg-slate-100 text-slate-500 font-black rounded-xl uppercase text-[9px]">Volver</button>
                 <button onClick={handleRegularize} className="flex-1 py-4 bg-blue-700 text-white font-black rounded-xl uppercase text-[9px] shadow-xl active:scale-95">Solicitar Autorización</button>
              </div>
           </div>
        )}

        {status === 'confirm' && currentEmp && (
          <div className="text-center w-full animate-in zoom-in">
            <div className="w-20 h-20 md:w-24 md:h-24 bg-slate-100 rounded-2xl md:rounded-[2rem] mx-auto flex items-center justify-center text-3xl md:text-4xl font-black text-blue-700 uppercase border-4 border-white shadow-xl mb-3 md:mb-4 overflow-hidden">
                 {currentEmp.photo ? <img src={currentEmp.photo} className="w-full h-full object-cover" /> : <span>{currentEmp.name[0]}</span>}
            </div>
            <h2 className="text-xl md:text-2xl font-[950] text-slate-900 mb-1 uppercase tracking-tighter leading-none">{currentEmp.name} {currentEmp.surname}</h2>
            <p className="text-[8px] md:text-[9px] font-black text-slate-400 uppercase tracking-[0.4em] mb-6 md:mb-8">{currentEmp.role}</p>

            <div className="space-y-4">
              <section className="space-y-3">
                <p className="text-[8px] font-black text-slate-300 uppercase tracking-[0.3em] text-left border-l-2 border-emerald-500 pl-2">Primera Jornada (Mañana)</p>
                <div className="grid grid-cols-2 gap-3">
                  <button disabled={insCount >= 1 || halfDayDoneToday} onClick={() => handleMark('in')} className={`py-4 rounded-xl font-black text-xs uppercase shadow-lg active:scale-95 transition-all border-b-4 ${insCount >= 1 || halfDayDoneToday ? 'bg-slate-100 text-slate-300 border-slate-200 cursor-not-allowed' : 'bg-emerald-600 text-white border-emerald-800'}`}>Ingreso</button>
                  <button disabled={outsCount >= 1 || halfDayDoneToday} onClick={() => handleMark('out')} className={`py-4 rounded-xl font-black text-xs uppercase shadow-lg active:scale-95 transition-all border-b-4 ${outsCount >= 1 || halfDayDoneToday ? 'bg-slate-100 text-slate-300 border-slate-200 cursor-not-allowed' : 'bg-orange-600 text-white border-orange-800'}`}>Salida</button>
                </div>
              </section>

              <section className="space-y-3">
                <p className="text-[8px] font-black text-slate-300 uppercase tracking-[0.3em] text-left border-l-2 border-cyan-500 pl-2">Segunda Jornada (Tarde)</p>
                <div className="grid grid-cols-2 gap-3">
                  <button disabled={insCount >= 2 || halfDayDoneToday} onClick={() => handleMark('in')} className={`py-4 rounded-xl font-black text-xs uppercase shadow-lg active:scale-95 transition-all border-b-4 ${insCount >= 2 || halfDayDoneToday ? 'bg-slate-100 text-slate-300 border-slate-200 cursor-not-allowed' : 'bg-cyan-600 text-white border-cyan-800'}`}>Ingreso</button>
                  <button disabled={outsCount >= 2 || halfDayDoneToday} onClick={() => handleMark('out')} className={`py-4 rounded-xl font-black text-xs uppercase shadow-lg active:scale-95 transition-all border-b-4 ${outsCount >= 2 || halfDayDoneToday ? 'bg-slate-100 text-slate-300 border-slate-200 cursor-not-allowed' : 'bg-pink-600 text-white border-pink-800'}`}>Salida</button>
                </div>
              </section>

              <div className="grid grid-cols-1 gap-3">
                  <button disabled={halfDayDoneThisWeek} onClick={() => handleMark('half_day')} className={`w-full py-4 rounded-xl font-black text-xs uppercase shadow-lg active:scale-95 transition-all border-b-4 flex items-center justify-center gap-2 ${halfDayDoneThisWeek ? 'bg-slate-100 text-slate-300 border-slate-200 cursor-not-allowed' : 'bg-amber-500 text-white border-amber-700'}`}><span>📅</span> Media Jornada Libre</button>
                  <button onClick={() => setStatus('regularize_form')} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[9px] tracking-widest shadow-xl flex items-center justify-center gap-2 active:scale-95"><span>💡</span> Regularizar Marcación Olvidada</button>
              </div>
            </div>
          </div>
        )}

        {status === 'error' && (
          <div className="text-center text-red-600 py-6 md:py-10 animate-pulse">
            <div className="text-6xl md:text-7xl mb-4">✕</div>
            <h2 className="text-xl md:text-2xl font-[950] uppercase tracking-tighter">Denegado</h2>
            <p className="text-[9px] md:text-[10px] font-bold uppercase mt-2">PIN Incorrecto</p>
          </div>
        )}
      </div>
      <button onClick={onBack} className="mt-8 md:mt-10 text-white/30 hover:text-white font-black text-[10px] md:text-[11px] uppercase tracking-[0.4em] md:tracking-[0.6em] p-4 transition-all active:scale-95">Salir del Terminal</button>

      <Modal isOpen={feedback.isOpen} onClose={() => setFeedback({...feedback, isOpen: false})} title={feedback.title} type={feedback.type}>
          <div className="text-center space-y-4 md:space-y-6">
              <p className="text-slate-600 font-bold uppercase text-[11px] md:text-[12px] leading-relaxed">{feedback.message}</p>
              <button onClick={() => setFeedback({...feedback, isOpen: false})} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] tracking-widest">Aceptar</button>
          </div>
      </Modal>
    </div>
  );
};

export default AttendanceSystem;

import React, { useState, useMemo, useEffect } from 'react';
import { Role, CompanyConfig, Employee, AttendanceRecord, Payment, GlobalSettings, NotificationMessage } from '../types.ts';
import Sidebar from '../components/Sidebar.tsx';
import CompanyModule from './modules/CompanyModule.tsx';
import EmployeeModule from './modules/EmployeeModule.tsx';
import PayrollModule from './modules/PayrollModule.tsx';
import PaymentsModule from './modules/PaymentsModule.tsx';
import SettingsModule from './modules/SettingsModule.tsx';
import ReportsModule from './modules/ReportsModule.tsx';
import AiAssistant from './modules/AiAssistant.tsx';
import NotificationsModule from './modules/NotificationsModule.tsx';
import Modal from '../components/Modal.tsx';
import { DAILY_QUOTES, ACTIVE_BREAKS, ECUADOR_HOLIDAYS } from '../constants.tsx';

interface AdminDashboardProps {
  role: Role;
  isDbConnected?: boolean;
  onLogout: () => void;
  company: CompanyConfig | null;
  onUpdateCompany: (config: CompanyConfig) => void;
  employees: Employee[];
  onUpdateEmployees: (employees: Employee[]) => void;
  attendance: AttendanceRecord[];
  onUpdateAttendance?: (records: AttendanceRecord[]) => void;
  payments: Payment[];
  onUpdatePayments: (payments: Payment[]) => void;
  settings: GlobalSettings;
  onUpdateSettings: (settings: GlobalSettings) => void;
  onUpdateAppMode: (mode: 'full' | 'attendance') => void;
  appMode: 'full' | 'attendance';
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  role, isDbConnected, onLogout, company, onUpdateCompany, employees, onUpdateEmployees, attendance, onUpdateAttendance, payments, onUpdatePayments, settings, onUpdateSettings, onUpdateAppMode, appMode 
}) => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'company' | 'employees' | 'payroll' | 'payments' | 'settings' | 'reports' | 'ai' | 'notifications'>('dashboard');
  const [notifications, setNotifications] = useState<NotificationMessage[]>([]);
  const [dismissedNotificationIds, setDismissedNotificationIds] = useState<Set<string>>(new Set());

  const today = useMemo(() => new Date(), []);
  const todayDateStr = useMemo(() => today.toISOString().split('T')[0], [today]);
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();

  const addNotification = (id: string, title: string, message: string, type: 'info' | 'alert' | 'critical') => {
    if (dismissedNotificationIds.has(id)) return;
    setNotifications(prev => {
      if (prev.some(n => n.id === id)) return prev;
      return [{ id, title, message, timestamp: new Date().toISOString(), type, isRead: false, isProcessed: false }, ...prev];
    });
  };

  useEffect(() => {
    if (currentYear < 2026 || (currentYear === 2026 && currentMonth < 1)) return;
    const activeEmployees = employees.filter(e => e.status === 'active');
    const markedTodayIds = new Set((attendance || []).filter(a => a.timestamp.includes(todayDateStr)).map(a => a.employeeId));
    const missingAttendanceCount = activeEmployees.filter(e => !markedTodayIds.has(e.id)).length;
    if (missingAttendanceCount > 0 && activeTab === 'dashboard') {
      addNotification(`missing-attendance-${todayDateStr}`, "Marcaciones Pendientes", `Hoy faltan ${missingAttendanceCount} registros de ingreso por completar.`, 'alert');
    }
  }, [employees, attendance, todayDateStr, activeTab, dismissedNotificationIds, currentMonth, currentYear]);

  // FILTRO PARA SOLICITUDES PENDIENTES DE APROBACIÓN
  const pendingApprovals = useMemo(() => {
    return (attendance || []).filter(a => a.status === 'pending_approval').sort((a, b) => b.timestamp.localeCompare(a.timestamp));
  }, [attendance]);

  const handleProcessApproval = (id: string, newStatus: 'confirmed' | 'rejected') => {
    if (!onUpdateAttendance) return;
    const recordsToUpdate = attendance.map(a => a.id === id ? { ...a, status: newStatus, validatedAt: new Date().toISOString() } : a);
    onUpdateAttendance(recordsToUpdate.filter(a => a.id === id));
  };

  const todayMarkings = useMemo(() => {
    return (attendance || [])
      .filter(a => a.timestamp.includes(todayDateStr) && a.status === 'confirmed')
      .sort((a, b) => {
        const empA = employees.find(e => e.id === a.employeeId);
        const empB = employees.find(e => e.id === b.employeeId);
        const nameA = `${empA?.surname || ''} ${empA?.name || ''}`;
        const nameB = `${empB?.surname || ''} ${empB?.name || ''}`;
        if (nameA !== nameB) return nameA.localeCompare(nameB);
        return a.timestamp.localeCompare(b.timestamp);
      });
  }, [attendance, todayDateStr, employees]);

  const handlePurgeData = async () => {
    if (role !== Role.SUPER_ADMIN) return;
    onUpdateEmployees([]);
    onUpdatePayments([]);
  };

  return (
    <div className="flex h-screen bg-[#fcfdfe] overflow-hidden flex-col md:flex-row">
      <Sidebar role={role} activeTab={activeTab} setActiveTab={setActiveTab} onLogout={onLogout} companyName={company?.name} unreadCount={notifications.filter(n => !n.isRead).length} />
      <main className="flex-1 overflow-y-auto px-4 md:px-8 py-4 md:py-8 scroll-smooth custom-scroll">
        <header className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4 no-print pt-14 md:pt-0">
          <div className="flex flex-col sm:flex-row items-start sm:items-center gap-3 w-full md:w-auto">
            <h1 className="text-3xl md:text-4xl font-[950] text-slate-900 tracking-tight uppercase leading-none italic">Management Hub</h1>
            <div className="flex items-center gap-2 px-4 py-2 bg-white border-2 border-slate-100 rounded-full shadow-sm w-fit">
               <div className={`w-3 h-3 rounded-full ${isDbConnected ? 'bg-emerald-500 animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.5)]' : 'bg-red-500 shadow-[0_0_8px_rgba(239,68,68,0.5)]'}`}></div>
               <span className="text-[12px] font-black uppercase tracking-[0.2em] text-slate-500">{isDbConnected ? 'Sincronizado' : 'Modo Offline'}</span>
            </div>
          </div>
        </header>

        <div className="animate-in fade-in duration-500 pb-20 md:pb-0">
          {activeTab === 'dashboard' && (
            <div className="space-y-8">
              <div className="relative overflow-hidden bg-slate-900 rounded-[3.5rem] p-12 md:p-16 text-white shadow-xl min-h-[250px] flex items-center bg-cover bg-center" style={{ backgroundImage: `linear-gradient(rgba(15, 23, 42, 0.7), rgba(15, 23, 42, 0.7)), url(${relaxingImages[Math.floor(Math.random()*4)]})` }}>
                  <div className="relative z-10 w-full">
                    <p className="text-blue-400 font-black text-[14px] md:text-[16px] uppercase tracking-[0.5em] mb-6 md:mb-8">Estrategia & Visión Diaria</p>
                    <h2 className="text-2xl md:text-5xl font-[900] leading-tight tracking-tighter italic max-w-5xl">"{DAILY_QUOTES[Math.floor(Math.random()*DAILY_QUOTES.length)]}"</h2>
                  </div>
              </div>

              {/* NUEVA SECCIÓN: SOLICITUDES DE REGULARIZACIÓN PENDIENTES */}
              {role === Role.SUPER_ADMIN && pendingApprovals.length > 0 && (
                <div className="bg-white p-8 md:p-10 rounded-[3.5rem] border-4 border-blue-100 shadow-xl animate-bounce-subtle">
                   <div className="flex items-center gap-4 mb-8">
                      <div className="w-12 h-12 bg-blue-600 text-white rounded-2xl flex items-center justify-center text-2xl">⚖️</div>
                      <div>
                        <h3 className="text-[14px] font-black text-slate-900 uppercase tracking-widest leading-none mb-1">Autorizaciones de Asistencia</h3>
                        <p className="text-[10px] font-black text-blue-500 uppercase">Solicitudes por falta de acceso al panel</p>
                      </div>
                   </div>
                   <div className="space-y-4">
                      {pendingApprovals.map(req => {
                        const emp = employees.find(e => e.id === req.employeeId);
                        return (
                          <div key={req.id} className="flex flex-col md:flex-row items-center justify-between gap-6 p-6 bg-slate-50 rounded-[2rem] border border-blue-50">
                             <div className="flex items-center gap-4 flex-1">
                                <div className="w-12 h-12 bg-white rounded-2xl border flex items-center justify-center overflow-hidden shrink-0">
                                   {emp?.photo ? <img src={emp.photo} className="w-full h-full object-cover" /> : <span className="font-black">{emp?.name[0]}</span>}
                                </div>
                                <div>
                                   <p className="text-xs font-black text-slate-900 uppercase">{emp?.surname} {emp?.name}</p>
                                   <p className="text-[9px] font-bold text-slate-400 uppercase">{req.type === 'in' ? 'Ingreso' : 'Salida'} Olvidado • {new Date(req.timestamp).toLocaleString('es-EC')}</p>
                                   <p className="text-[9px] font-black text-blue-600 mt-1 italic">"{req.justification}"</p>
                                </div>
                             </div>
                             <div className="flex gap-3">
                                <button onClick={() => handleProcessApproval(req.id, 'rejected')} className="px-6 py-3 bg-white text-red-500 border-2 border-red-100 font-black rounded-xl uppercase text-[9px] hover:bg-red-50 transition-all">Rechazar</button>
                                <button onClick={() => handleProcessApproval(req.id, 'confirmed')} className="px-6 py-3 bg-emerald-600 text-white font-black rounded-xl uppercase text-[9px] shadow-lg hover:bg-emerald-700 transition-all">Aprobar Marcación</button>
                             </div>
                          </div>
                        );
                      })}
                   </div>
                </div>
              )}

              <div className="bg-white p-8 md:p-10 rounded-[3.5rem] border border-slate-100 shadow-sm">
                 <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-8 gap-4">
                    <div>
                      <h3 className="text-[14px] font-black text-slate-900 uppercase tracking-widest leading-none mb-2">Monitoreo de Jornada Diaria</h3>
                      <p className="text-[11px] font-black text-emerald-600 uppercase tracking-widest">Actividad Confirmada • {new Date().toLocaleDateString('es-EC', {day: 'numeric', month: 'long', year: 'numeric'})}</p>
                    </div>
                 </div>
                 <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 max-h-[400px] overflow-y-auto custom-scroll pr-2">
                    {todayMarkings.length === 0 ? (
                      <div className="col-span-full py-20 flex flex-col items-center justify-center opacity-40">
                         <span className="text-5xl mb-4">⌛</span>
                         <p className="text-[12px] font-black uppercase tracking-[0.2em] text-slate-400">Esperando marcaciones para el día de hoy...</p>
                      </div>
                    ) : (
                      todayMarkings.map((mark) => {
                        const emp = employees.find(e => e.id === mark.employeeId);
                        const empMarksToday = (attendance || []).filter(a => a.employeeId === mark.employeeId && a.timestamp.startsWith(todayDateStr) && a.status === 'confirmed').sort((a, b) => a.timestamp.localeCompare(b.timestamp));
                        let specificLabel = ""; let labelColor = "";
                        if (mark.type === 'half_day') { specificLabel = "Media Jornada Libre"; labelColor = "bg-amber-500 text-white"; }
                        else if (mark.type === 'in') { const inIndex = empMarksToday.filter(m => m.type === 'in').findIndex(m => m.id === mark.id); specificLabel = inIndex === 0 ? "Entrada Mañana" : "Entrada Tarde"; labelColor = inIndex === 0 ? "bg-emerald-600 text-white" : "bg-cyan-600 text-white"; }
                        else if (mark.type === 'out') { const outIndex = empMarksToday.filter(m => m.type === 'out').findIndex(m => m.id === mark.id); specificLabel = outIndex === 0 ? "Salida Medio Día" : "Salida Fin Jornada"; labelColor = outIndex === 0 ? "bg-orange-600 text-white" : "bg-pink-600 text-white"; }

                        return (
                          <div key={mark.id} className="flex items-center gap-4 bg-slate-50 p-5 rounded-3xl border border-slate-100 transition-all hover:shadow-md hover:bg-white group">
                             <div className="w-12 h-12 bg-white rounded-2xl border flex items-center justify-center overflow-hidden shrink-0">
                                {emp?.photo ? <img src={emp.photo} className="w-full h-full object-cover" /> : <span className="text-[14px] font-black uppercase text-slate-300">{emp?.name[0]}</span>}
                             </div>
                             <div className="flex-1 min-w-0">
                                <p className="text-[11px] font-[950] text-slate-900 uppercase leading-none truncate">{emp?.surname} {emp?.name}</p>
                                <div className="flex items-center gap-2 mt-2">
                                   <span className={`text-[7px] font-black uppercase px-2 py-0.5 rounded-full ${labelColor}`}>{specificLabel}</span>
                                   {mark.isLate && <span className="text-[7px] font-black uppercase bg-red-100 text-red-600 px-1.5 py-0.5 rounded-full animate-pulse">Retraso</span>}
                                   {mark.isForgotten && <span className="text-[7px] font-black uppercase bg-blue-100 text-blue-600 px-1.5 py-0.5 rounded-full">Regularizada</span>}
                                </div>
                             </div>
                             <div className="text-right">
                                <p className="text-[13px] font-[950] text-slate-900 tabular-nums">{new Date(mark.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit', second: '2-digit'})}</p>
                             </div>
                          </div>
                        );
                      })
                    )}
                 </div>
              </div>
            </div>
          )}
          {activeTab === 'notifications' && <NotificationsModule notifications={notifications} onToggleRead={(id) => setNotifications(prev => prev.map(n => n.id === id ? {...n, isRead: !n.isRead} : n))} onToggleProcessed={(id) => setNotifications(prev => prev.map(n => n.id === id ? {...n, isProcessed: !n.isProcessed} : n))} onClearAll={() => { setNotifications([]); }} />}
          {activeTab === 'company' && <CompanyModule company={company} onUpdate={onUpdateCompany} role={role} />}
          {activeTab === 'employees' && <EmployeeModule employees={employees} onUpdate={onUpdateEmployees} role={role} attendance={attendance} payments={payments} company={company} />}
          {activeTab === 'payroll' && <PayrollModule employees={employees} payments={payments} onUpdatePayments={onUpdatePayments} onUpdateEmployees={onUpdateEmployees} attendance={attendance} company={company} settings={settings} role={role} />}
          {activeTab === 'payments' && <PaymentsModule employees={employees} payments={payments} onUpdate={onUpdatePayments} role={role} company={company} />}
          {activeTab === 'settings' && <SettingsModule settings={settings} onUpdate={onUpdateSettings} role={role} onPurge={handlePurgeData} allData={{ company, employees, attendance, payments, settings }} />}
          {activeTab === 'reports' && <ReportsModule employees={employees} payments={payments} attendance={attendance} company={company} settings={settings} role={role} />}
          {activeTab === 'ai' && <AiAssistant employees={employees} attendance={attendance} payments={payments} role={role} />}
        </div>
      </main>
    </div>
  );
};

const relaxingImages = [
  "https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&q=80&w=2070",
  "https://images.unsplash.com/photo-1441974231531-c6227db76b6e?auto=format&fit=crop&q=80&w=2071",
  "https://images.unsplash.com/photo-1579783902614-a3fb3927b6a5?auto=format&fit=crop&q=80&w=2070",
  "https://images.unsplash.com/photo-1541450805268-4822a3a774ce?auto=format&fit=crop&q=80&w=2070"
];

export default AdminDashboard;

import React, { useState, useEffect, useMemo } from 'react';
import { Employee, AttendanceRecord, GlobalSettings } from '../types.ts';
import Clock from '../components/Clock.tsx';
import Modal from '../components/Modal.tsx';

const APP_ICON_SVG = "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'%3E%3Cdefs%3E%3ClinearGradient id='g' x1='0%25' y1='0%25' x2='100%25' y2='100%25'%3E%3Cstop offset='0%25' style='stop-color:%233b82f6;'/%3E%3Cstop offset='100%25' style='stop-color:%231e3a8a;'/%3E%3C/linearGradient%3E%3C/defs%3E%3Ccircle cx='50' cy='50' r='45' fill='none' stroke='url(%23g)' stroke-width='6' stroke-dasharray='15 5'/%3E%3Ccircle cx='50' cy='50' r='32' fill='none' stroke='url(%23g)' stroke-width='5' stroke-dasharray='10 4' opacity='0.7'/%3E%3Ccircle cx='50' cy='50' r='18' fill='none' stroke='url(%23g)' stroke-width='4' opacity='0.4'/%3E%3Ccircle cx='50' cy='50' r='6' fill='%233b82f6'/%3E%3C/svg%3E";

interface AttendanceSystemProps {
  employees: Employee[];
  attendance: AttendanceRecord[];
  onRegister: (record: AttendanceRecord) => void;
  onBack: () => void;
  onUpdateEmployees: (employees: Employee[]) => void;
  settings: GlobalSettings;
}

const AttendanceSystem: React.FC<AttendanceSystemProps> = ({ employees, attendance, onRegister, onBack, onUpdateEmployees, settings }) => {
  const [pin, setPin] = useState('');
  const [status, setStatus] = useState<'idle' | 'confirm' | 'forgotten_form' | 'success' | 'error' | 'change_pin' | 'regularize_form'>('idle');
  const [isProcessing, setIsProcessing] = useState(false);
  const [currentEmp, setCurrentEmp] = useState<Employee | null>(null);
  const [newPin, setNewPin] = useState('');
  const [forgotCi, setForgotCi] = useState('');
  const [successMsg, setSuccessMsg] = useState('');
  const [isBirthdaySuccess, setIsBirthdaySuccess] = useState(false);
  const [feedback, setFeedback] = useState<{isOpen: boolean, title: string, message: string, type: 'success' | 'error' | 'info'}>({
    isOpen: false, title: '', message: '', type: 'success'
  });

  const [regularizeData, setRegularizeData] = useState({
    date: new Date().toISOString().split('T')[0],
    time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }),
    type: 'in' as 'in' | 'out',
    justification: 'SIN ACCESO AL PANEL',
    otherDetails: ''
  });

  const today = useMemo(() => new Date(), []);
  const todayDateStr = today.toISOString().split('T')[0];
  const currentMonth = today.getMonth();
  const currentDay = today.getDate();

  const monthBirthdays = useMemo(() => {
    return employees.filter(e => {
      if (!e.birthDate || e.status !== 'active') return false;
      return new Date(e.birthDate).getMonth() === currentMonth;
    }).sort((a, b) => {
      const dayA = new Date(a.birthDate).getDate();
      const dayB = new Date(b.birthDate).getDate();
      return dayA - dayB;
    });
  }, [employees, currentMonth]);

  const empTodayRecords = useMemo(() => {
    if (!currentEmp) return [];
    return attendance.filter(a => a.employeeId === currentEmp.id && a.timestamp.startsWith(todayDateStr));
  }, [attendance, currentEmp, todayDateStr]);

  const halfDayDoneThisWeek = useMemo(() => {
    if (!currentEmp) return false;
    const now = new Date();
    const day = now.getDay();
    const diff = now.getDate() - day + (day === 0 ? -6 : 1);
    const startOfWeek = new Date(now.setDate(diff));
    startOfWeek.setHours(0, 0, 0, 0);

    return attendance.some(a => {
      const aDate = new Date(a.timestamp);
      return a.employeeId === currentEmp.id && a.type === 'half_day' && aDate >= startOfWeek;
    });
  }, [attendance, currentEmp]);

  const insCount = empTodayRecords.filter(r => r.type === 'in').length;
  const outsCount = empTodayRecords.filter(r => r.type === 'out').length;
  const halfDayDoneToday = empTodayRecords.some(r => r.type === 'half_day');

  const handleMark = (type: 'in' | 'out' | 'half_day') => {
    if (!currentEmp || isProcessing) return;
    const now = new Date();
    const day = now.getDay();
    let isCriticalLate = false;

    if (type !== 'half_day') {
      if (day >= 1 && day <= 5) {
        const [h1, m1] = settings.schedule.monFri.in1.split(':').map(Number);
        const schedIn1 = new Date(now); schedIn1.setHours(h1, m1, 0, 0);
        const [h2, m2] = settings.schedule.monFri.in2.split(':').map(Number);
        const schedIn2 = new Date(now); schedIn2.setHours(h2, m2, 0, 0);

        if (type === 'in') {
          const targetSched = (now > schedIn1 && now < schedIn2) ? schedIn2 : schedIn1;
          const diffMins = (now.getTime() - targetSched.getTime()) / (1000 * 60);
          if (diffMins > 15) isCriticalLate = true;
        }
      } else if (day === 6) {
        const [hs, ms] = settings.schedule.sat.in.split(':').map(Number);
        const schedSatIn = new Date(now); schedSatIn.setHours(hs, ms, 0, 0);

        if (type === 'in') {
          const diffMins = (now.getTime() - schedSatIn.getTime()) / (1000 * 60);
          if (diffMins > 15) isCriticalLate = true;
        }
      }
    }

    processRegistration(type, isCriticalLate);
  };

  const handleRegularize = () => {
    if (!currentEmp || isProcessing) return;
    setIsProcessing(true);

    const fullTimestamp = `${regularizeData.date}T${regularizeData.time}:00.000Z`;

    const finalJustification = regularizeData.justification === 'OTRO (DETALLAR)' 
      ? `OTRO: ${regularizeData.otherDetails.toUpperCase()}` 
      : regularizeData.justification;

    const record: AttendanceRecord = {
      id: Math.random().toString(36).substr(2, 9),
      employeeId: currentEmp.id,
      timestamp: fullTimestamp,
      type: regularizeData.type,
      status: 'pending_approval',
      justification: finalJustification,
      isForgotten: true
    };

    onRegister(record);
    setSuccessMsg("SOLICITUD ENVIADA A RRHH");
    setStatus('success');
    setPin('');

    setTimeout(() => {
      setStatus('idle');
      setCurrentEmp(null);
      setIsProcessing(false);
    }, 3000);
  };

  const processRegistration = (type: 'in' | 'out' | 'half_day', isLate: boolean, justification?: string) => {
    setIsProcessing(true);

    if (isLate && Notification.permission === "granted") {
      new Notification("ALERTA DE ASISTENCIA", {
        body: `El colaborador ${currentEmp?.name} ${currentEmp?.surname} ha marcado con más de 15 minutos de retraso.`,
        icon: APP_ICON_SVG
      });
    }

    const record: AttendanceRecord = {
      id: Math.random().toString(36).substr(2, 9),
      employeeId: currentEmp!.id,
      timestamp: new Date().toISOString(),
      type,
      status: 'confirmed',
      isLate,
      justification
    };

    onRegister(record);

    let msg = "";
    const bDate = currentEmp?.birthDate ? new Date(currentEmp.birthDate) : null;
    const isTodayBirthday = bDate && (bDate.getMonth() === currentMonth && bDate.getDate() + 1 === currentDay);

    if (isTodayBirthday) {
       msg = "¡FELIZ CUMPLEAÑOS! 🎂🎈";
       setIsBirthdaySuccess(true);
    } else {
       if (type === 'in') msg = "INGRESO REGISTRADO";
       else if (type === 'out') msg = "SALIDA REGISTRADA";
       else msg = "MEDIA JORNADA REGISTRADA";
       setIsBirthdaySuccess(false);
    }

    setSuccessMsg(msg);
    setStatus('success');
    setPin('');

    setTimeout(() => {
      setStatus('idle');
      setCurrentEmp(null);
      setIsProcessing(false);
      setIsBirthdaySuccess(false);
    }, isTodayBirthday ? 5000 : 3000);
  };

  const handlePinChange = () => {
    if (newPin.length !== 6 || newPin === currentEmp?.pin) {
      setFeedback({ isOpen: true, title: "Error de PIN", message: "Ingrese un PIN nuevo de 6 dígitos diferente al actual.", type: "error" });
      return;
    }
    const updated = employees.map(e => e.id === currentEmp?.id ? { ...e, pin: newPin, pinChanged: true, pinNeedsReset: false, pinResetRequested: false } : e);
    onUpdateEmployees(updated);
    setFeedback({ isOpen: true, title: "PIN Actualizado", message: "Su clave de acceso ha sido cambiada. Ahora puede marcar su asistencia.", type: "success" });
    setStatus('confirm');
    setNewPin('');
  };

  const handleRequestPinReset = () => {
    const emp = employees.find(e => e.identification === forgotCi && e.status === 'active');
    if (emp) {
      const updated = employees.map(e => e.id === emp.id ? { ...e, pinResetRequested: true } : e);
      onUpdateEmployees(updated);
      if (Notification.permission === "granted") {
        new Notification("SOLICITUD DE ACCESO", { body: `El colaborador ${emp.name} solicita resetear su PIN de asistencia.`, icon: APP_ICON_SVG });
      }
      setFeedback({ isOpen: true, title: "Solicitud Recibida", message: "Su solicitud ha sido enviada al administrador. RRHH autorizará su nuevo acceso a la brevedad.", type: "info" });
      setStatus('idle');
      setForgotCi('');
    } else {
      setFeedback({ isOpen: true, title: "Error", message: "Identificación no encontrada en el sistema.", type: "error" });
    }
  };

  useEffect(() => {
    if (pin.length === 6 && status === 'idle' && !isProcessing) {
      const emp = employees.find(e => e.pin === pin && e.status === 'active');
      if (emp) {
        setCurrentEmp(emp);
        if (!emp.pinChanged || emp.pinNeedsReset) setStatus('change_pin');
        else setStatus('confirm');
      } else {
        setStatus('error');
        setTimeout(() => { setStatus('idle'); setPin(''); }, 1500);
      }
    }
  }, [pin, employees, status, isProcessing]);

  useEffect(() => {
    const handleKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onBack();
      if (status !== 'idle' || isProcessing) return;
      if (e.key >= '0' && e.key <= '9' && pin.length < 6) setPin(p => p + e.key);
      if (e.key === 'Backspace') setPin(p => p.slice(0, -1));
    };
    window.addEventListener('keydown', handleKey);
    return () => window.removeEventListener('keydown', handleKey);
  }, [pin, status, isProcessing]);

  return (
    <div className="min-h-screen gradient-blue flex flex-col items-center justify-center p-4">
      {status === 'success' && (
        <div className="fixed inset-0 z-[100] bg-slate-900/80 backdrop-blur-md flex flex-col items-center justify-center fade-in p-6">
           <div className={`p-10 rounded-[2.5rem] shadow-2xl flex flex-col items-center text-center animate-in zoom-in max-w-sm ${isBirthdaySuccess ? 'bg-gradient-to-br from-yellow-100 to-white' : 'bg-white'}`}>
              <div className={`w-20 h-20 rounded-full flex items-center justify-center text-4xl mb-4 shadow-lg animate-bounce ${isBirthdaySuccess ? 'bg-yellow-400 text-white' : 'bg-emerald-500 text-white'}`}>
                {isBirthdaySuccess ? '🎂' : '✓'}
              </div>
              <h2 className={`font-[950] text-xl uppercase tracking-tighter leading-none ${isBirthdaySuccess ? 'text-yellow-600 animate-pulse' : 'text-slate-900'}`}>{successMsg}</h2>
              {isBirthdaySuccess && <p className="text-xl mt-2 animate-bounce">🎈🎊🎁</p>}
              <p className="text-slate-400 font-bold text-[9px] uppercase tracking-widest mt-2 italic">Sincronizado con RRHH</p>
           </div>
        </div>
      )}

      <div className={`w-full max-w-lg bg-white/95 backdrop-blur-3xl rounded-3xl md:rounded-[3.5rem] shadow-2xl p-6 md:p-12 flex flex-col items-center relative overflow-hidden ${status === 'success' ? 'opacity-0' : 'fade-in'}`}>
        <div className="mb-4 md:mb-6 transform scale-[0.6] sm:scale-[0.8]"><Clock /></div>

        {status === 'idle' && (
          <div className="w-full text-center">
            {monthBirthdays.length > 0 && (
              <div className="mb-6 p-4 bg-yellow-50/50 border border-yellow-100 rounded-2xl animate-in slide-in-from-top-4 duration-1000">
                <p className="text-[8px] font-black text-yellow-600 uppercase tracking-widest mb-2 flex items-center justify-center gap-2">
                  <span>🎂</span> Celebramos a nuestros cumpleañeros <span>🎈</span>
                </p>
                <div className="flex flex-wrap justify-center gap-2">
                  {monthBirthdays.slice(0, 3).map(e => (
                    <div key={e.id} className="bg-white px-3 py-1 rounded-full shadow-sm border border-yellow-100 flex items-center gap-2">
                      <span className="text-[9px] font-black text-slate-700 uppercase">{e.name} {e.surname}</span>
                      <span className="text-[7px] font-bold text-yellow-600 bg-yellow-50 px-1.5 rounded-full">{new Date(e.birthDate).getDate() + 1}/{currentMonth + 1}</span>
                    </div>
                  ))}
                </div>
              </div>
            )}
            <h2 className="text-[10px] md:text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4 md:mb-6">Ingresar PIN de 6 dígitos</h2>
            <div className="flex gap-1.5 md:gap-2 justify-center mb-8 md:mb-10">
              {[...Array(6)].map((_, i) => (
                <div key={i} className={`w-8 h-12 md:w-10 md:h-16 border-b-4 flex items-center justify-center text-2xl md:text-4xl font-black transition-all ${pin.length > i ? 'border-blue-600 text-slate-900' : 'border-slate-100'}`}>
                  {pin[i] ? '•' : ''}
                </div>
              ))}
            </div>
            <div className="grid grid-cols-3 gap-2 md:gap-3 max-w-[280px] md:max-w-[340px] mx-auto mb-8 md:mb-10">
              {[1, 2, 3, 4, 5, 6, 7, 8, 9, 'C', 0, '←'].map(btn => (
                <button key={btn} onClick={() => { if (btn === 'C') setPin(''); else if (btn === '←') setPin(p => p.slice(0, -1)); else if (pin.length < 6) setPin(p => p + btn); }} className="h-14 md:h-18 bg-white hover:bg-blue-700 hover:text-white rounded-xl md:rounded-2xl text-xl md:text-2xl font-black border border-slate-200 active:scale-90 transition-all shadow-sm flex items-center justify-center">{btn}</button>
              ))}
            </div>
            <button onClick={() => setStatus('forgotten_form')} className="w-full py-3 md:py-4 bg-slate-50 border border-slate-100 rounded-xl md:rounded-2xl text-[9px] md:text-[10px] font-black text-blue-600 uppercase tracking-widest hover:bg-blue-50 transition-all active:scale-95">¿Olvidó su PIN? Solicitar Reseteo</button>
          </div>
        )}

        {status === 'regularize_form' && (
           <div className="text-center w-full space-y-6 animate-in zoom-in">
              <div className="p-6 bg-blue-50 border border-blue-100 rounded-3xl mb-4">
                  <p className="text-[11px] font-black text-blue-700 uppercase tracking-widest leading-relaxed italic">
                    "Tu integridad es el valor más grande de nuestra institución. Si por motivos de acceso no pudiste marcar, regulariza tu jornada con total honestidad. La transparencia nos fortalece."
                  </p>
              </div>
              <div className="space-y-4 text-left">
                  <div className="space-y-1">
                    <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Fecha Olvidada</label>
                    <input type="date" value={regularizeData.date} onChange={e => setRegularizeData({...regularizeData, date: e.target.value})} className="w-full p-4 border-2 rounded-xl text-xs font-black" />
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                       <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Hora Aproximada</label>
                       <input type="time" value={regularizeData.time} onChange={e => setRegularizeData({...regularizeData, time: e.target.value})} className="w-full p-4 border-2 rounded-xl text-xs font-black" />
                    </div>
                    <div className="space-y-1">
                       <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Tipo</label>
                       <select value={regularizeData.type} onChange={e => setRegularizeData({...regularizeData, type: e.target.value as any})} className="w-full p-4 border-2 rounded-xl text-[10px] font-black uppercase">
                          <option value="in">Ingreso</option>
                          <option value="out">Salida</option>
                       </select>
                    </div>
                  </div>
                  <div className="space-y-1">
                    <label className="text-[9px] font-black text-blue-600 uppercase tracking-widest">Motivo de Justificación</label>
                    <select 
                      value={regularizeData.justification} 
                      onChange={e => setRegularizeData({...regularizeData, justification: e.target.value})} 
                      className="w-full p-4 border-2 rounded-xl text-[10px] font-black uppercase focus:border-blue-500 outline-none"
                    >
                      <option value="SIN ACCESO AL PANEL">SIN ACCESO AL PANEL</option>
                      <option value="OLVIDO">OLVIDO</option>
                      <option value="OTRO (DETALLAR)">OTRO (DETALLAR)</option>
                    </select>
                  </div>
                  {regularizeData.justification === 'OTRO (DETALLAR)' && (
                    <div className="space-y-1 animate-in slide-in-from-top-2">
                       <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Detalle del Motivo</label>
                       <input 
                         type="text" 
                         value={regularizeData.otherDetails} 
                         onChange={e => setRegularizeData({...regularizeData, otherDetails: e.target.value})} 
                         className="w-full p-4 border-2 rounded-xl text-[10px] font-black uppercase focus:border-blue-500 outline-none" 
                         placeholder="DESCRIBA AQUÍ..." 
                       />
                    </div>
                  )}
              </div>
              <div className="flex gap-3">
                 <button onClick={() => setStatus('confirm')} className="flex-1 py-4 bg-slate-100 text-slate-500 font-black rounded-xl uppercase text-[9px]">Volver</button>
                 <button onClick={handleRegularize} className="flex-1 py-4 bg-blue-700 text-white font-black rounded-xl uppercase text-[9px] shadow-xl active:scale-95">Solicitar Autorización</button>
              </div>
           </div>
        )}

        {status === 'confirm' && currentEmp && (
          <div className="text-center w-full animate-in zoom-in">
            <div className="w-20 h-20 md:w-24 md:h-24 bg-slate-100 rounded-2xl md:rounded-[2rem] mx-auto flex items-center justify-center text-3xl md:text-4xl font-black text-blue-700 uppercase border-4 border-white shadow-xl mb-3 md:mb-4 overflow-hidden">
                 {currentEmp.photo ? <img src={currentEmp.photo} className="w-full h-full object-cover" /> : <span>{currentEmp.name[0]}</span>}
            </div>
            <h2 className="text-xl md:text-2xl font-[950] text-slate-900 mb-1 uppercase tracking-tighter leading-none">{currentEmp.name} {currentEmp.surname}</h2>
            <p className="text-[8px] md:text-[9px] font-black text-slate-400 uppercase tracking-[0.4em] mb-6 md:mb-8">{currentEmp.role}</p>

            <div className="space-y-4">
              <section className="space-y-3">
                <p className="text-[8px] font-black text-slate-300 uppercase tracking-[0.3em] text-left border-l-2 border-emerald-500 pl-2">Primera Jornada (Mañana)</p>
                <div className="grid grid-cols-2 gap-3">
                  <button disabled={insCount >= 1 || halfDayDoneToday} onClick={() => handleMark('in')} className={`py-4 rounded-xl font-black text-xs uppercase shadow-lg active:scale-95 transition-all border-b-4 ${insCount >= 1 || halfDayDoneToday ? 'bg-slate-100 text-slate-300 border-slate-200 cursor-not-allowed' : 'bg-emerald-600 text-white border-emerald-800'}`}>Ingreso</button>
                  <button disabled={outsCount >= 1 || halfDayDoneToday} onClick={() => handleMark('out')} className={`py-4 rounded-xl font-black text-xs uppercase shadow-lg active:scale-95 transition-all border-b-4 ${outsCount >= 1 || halfDayDoneToday ? 'bg-slate-100 text-slate-300 border-slate-200 cursor-not-allowed' : 'bg-orange-600 text-white border-orange-800'}`}>Salida</button>
                </div>
              </section>

              <section className="space-y-3">
                <p className="text-[8px] font-black text-slate-300 uppercase tracking-[0.3em] text-left border-l-2 border-cyan-500 pl-2">Segunda Jornada (Tarde)</p>
                <div className="grid grid-cols-2 gap-3">
                  <button disabled={insCount >= 2 || halfDayDoneToday} onClick={() => handleMark('in')} className={`py-4 rounded-xl font-black text-xs uppercase shadow-lg active:scale-95 transition-all border-b-4 ${insCount >= 2 || halfDayDoneToday ? 'bg-slate-100 text-slate-300 border-slate-200 cursor-not-allowed' : 'bg-cyan-600 text-white border-cyan-800'}`}>Ingreso</button>
                  <button disabled={outsCount >= 2 || halfDayDoneToday} onClick={() => handleMark('out')} className={`py-4 rounded-xl font-black text-xs uppercase shadow-lg active:scale-95 transition-all border-b-4 ${outsCount >= 2 || halfDayDoneToday ? 'bg-slate-100 text-slate-300 border-slate-200 cursor-not-allowed' : 'bg-pink-600 text-white border-pink-800'}`}>Salida</button>
                </div>
              </section>

              <div className="grid grid-cols-1 gap-3">
                  <button disabled={halfDayDoneThisWeek} onClick={() => handleMark('half_day')} className={`w-full py-4 rounded-xl font-black text-xs uppercase shadow-lg active:scale-95 transition-all border-b-4 flex items-center justify-center gap-2 ${halfDayDoneThisWeek ? 'bg-slate-100 text-slate-300 border-slate-200 cursor-not-allowed' : 'bg-amber-500 text-white border-amber-700'}`}><span>📅</span> Media Jornada Libre</button>
                  <button onClick={() => setStatus('regularize_form')} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[9px] tracking-widest shadow-xl flex items-center justify-center gap-2 active:scale-95"><span>💡</span> Regularizar Marcación Olvidada</button>
              </div>
            </div>
          </div>
        )}

        {status === 'error' && (
          <div className="text-center text-red-600 py-6 md:py-10 animate-pulse">
            <div className="text-6xl md:text-7xl mb-4">✕</div>
            <h2 className="text-xl md:text-2xl font-[950] uppercase tracking-tighter">Denegado</h2>
            <p className="text-[9px] md:text-[10px] font-bold uppercase mt-2">PIN Incorrecto</p>
          </div>
        )}
      </div>
      <button onClick={onBack} className="mt-8 md:mt-10 text-white/30 hover:text-white font-black text-[10px] md:text-[11px] uppercase tracking-[0.4em] md:tracking-[0.6em] p-4 transition-all active:scale-95">Salir del Terminal</button>

      <Modal isOpen={feedback.isOpen} onClose={() => setFeedback({...feedback, isOpen: false})} title={feedback.title} type={feedback.type}>
          <div className="text-center space-y-4 md:space-y-6">
              <p className="text-slate-600 font-bold uppercase text-[11px] md:text-[12px] leading-relaxed">{feedback.message}</p>
              <button onClick={() => setFeedback({...feedback, isOpen: false})} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] tracking-widest">Aceptar</button>
          </div>
      </Modal>
    </div>
  );
};

export default AttendanceSystem;

import React, { useState, useMemo, useEffect } from 'react';
import { Role, CompanyConfig, Employee, AttendanceRecord, Payment, GlobalSettings, NotificationMessage } from '../types.ts';
import Sidebar from '../components/Sidebar.tsx';
import CompanyModule from './modules/CompanyModule.tsx';
import EmployeeModule from './modules/EmployeeModule.tsx';
import PayrollModule from './modules/PayrollModule.tsx';
import PaymentsModule from './modules/PaymentsModule.tsx';
import SettingsModule from './modules/SettingsModule.tsx';
import ReportsModule from './modules/ReportsModule.tsx';
import AiAssistant from './modules/AiAssistant.tsx';
import NotificationsModule from './modules/NotificationsModule.tsx';
import Modal from '../components/Modal.tsx';
import { DAILY_QUOTES, ACTIVE_BREAKS, ECUADOR_HOLIDAYS } from '../constants.tsx';

interface AdminDashboardProps {
  role: Role;
  isDbConnected?: boolean;
  onLogout: () => void;
  company: CompanyConfig | null;
  onUpdateCompany: (config: CompanyConfig) => void;
  employees: Employee[];
  onUpdateEmployees: (employees: Employee[]) => void;
  attendance: AttendanceRecord[];
  onUpdateAttendance?: (records: AttendanceRecord[]) => void;
  payments: Payment[];
  onUpdatePayments: (payments: Payment[]) => void;
  settings: GlobalSettings;
  onUpdateSettings: (settings: GlobalSettings) => void;
  onUpdateAppMode: (mode: 'full' | 'attendance') => void;
  appMode: 'full' | 'attendance';
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  role, isDbConnected, onLogout, company, onUpdateCompany, employees, onUpdateEmployees, attendance, onUpdateAttendance, payments, onUpdatePayments, settings, onUpdateSettings, onUpdateAppMode, appMode 
}) => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'company' | 'employees' | 'payroll' | 'payments' | 'settings' | 'reports' | 'ai' | 'notifications'>('dashboard');
  const [notifications, setNotifications] = useState<NotificationMessage[]>([]);
  const [dismissedNotificationIds, setDismissedNotificationIds] = useState<Set<string>>(new Set());

  const today = useMemo(() => new Date(), []);
  const todayDateStr = useMemo(() => today.toISOString().split('T')[0], [today]);
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();

  const addNotification = (id: string, title: string, message: string, type: 'info' | 'alert' | 'critical') => {
    if (dismissedNotificationIds.has(id)) return;
    setNotifications(prev => {
      if (prev.some(n => n.id === id)) return prev;
      return [{ id, title, message, timestamp: new Date().toISOString(), type, isRead: false, isProcessed: false }, ...prev];
    });
  };

  useEffect(() => {
    if (currentYear < 2026 || (currentYear === 2026 && currentMonth < 1)) return;
    const activeEmployees = employees.filter(e => e.status === 'active');
    const markedTodayIds = new Set((attendance || []).filter(a => a.timestamp.includes(todayDateStr)).map(a => a.employeeId));
    const missingAttendanceCount = activeEmployees.filter(e => !markedTodayIds.has(e.id)).length;
    if (missingAttendanceCount > 0 && activeTab === 'dashboard') {
      addNotification(`missing-attendance-${todayDateStr}`, "Marcaciones Pendientes", `Hoy faltan ${missingAttendanceCount} registros de ingreso por completar.`, 'alert');
    }
  }, [employees, attendance, todayDateStr, activeTab, dismissedNotificationIds, currentMonth, currentYear]);

  // FILTRO PARA SOLICITUDES PENDIENTES DE APROBACIÓN
  const pendingApprovals = useMemo(() => {
    return (attendance || []).filter(a => a.status === 'pending_approval').sort((a, b) => b.timestamp.localeCompare(a.timestamp));
  }, [attendance]);

  const handleProcessApproval = (id: string, newStatus: 'confirmed' | 'rejected') => {
    if (!onUpdateAttendance) return;
    const recordsToUpdate = attendance.map(a => a.id === id ? { ...a, status: newStatus, validatedAt: new Date().toISOString() } : a);
    onUpdateAttendance(recordsToUpdate.filter(a => a.id === id));
  };

  const todayMarkings = useMemo(() => {
    return (attendance || [])
      .filter(a => a.timestamp.includes(todayDateStr) && a.status === 'confirmed')
      .sort((a, b) => {
        const empA = employees.find(e => e.id === a.employeeId);
        const empB = employees.find(e => e.id === b.employeeId);
        const nameA = `${empA?.surname || ''} ${empA?.name || ''}`;
        const nameB = `${empB?.surname || ''} ${empB?.name || ''}`;
        if (nameA !== nameB) return nameA.localeCompare(nameB);
        return a.timestamp.localeCompare(b.timestamp);
      });
  }, [attendance, todayDateStr, employees]);

  const handlePurgeData = async () => {
    if (role !== Role.SUPER_ADMIN) return;
    onUpdateEmployees([]);
    onUpdatePayments([]);
  };

  return (
    <div className="flex h-screen bg-[#fcfdfe] overflow-hidden flex-col md:flex-row">
      <Sidebar role={role} activeTab={activeTab} setActiveTab={setActiveTab} onLogout={onLogout} companyName={company?.name} unreadCount={notifications.filter(n => !n.isRead).length} />
      <main className="flex-1 overflow-y-auto px-4 md:px-8 py-4 md:py-8 scroll-smooth custom-scroll">
        <header className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4 no-print pt-14 md:pt-0">
          <div className="flex flex-col sm:flex-row items-start sm:items-center gap-3 w-full md:w-auto">
            <h1 className="text-3xl md:text-4xl font-[950] text-slate-900 tracking-tight uppercase leading-none italic">Management Hub</h1>
            <div className="flex items-center gap-2 px-4 py-2 bg-white border-2 border-slate-100 rounded-full shadow-sm w-fit">
               <div className={`w-3 h-3 rounded-full ${isDbConnected ? 'bg-emerald-500 animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.5)]' : 'bg-red-500 shadow-[0_0_8px_rgba(239,68,68,0.5)]'}`}></div>
               <span className="text-[12px] font-black uppercase tracking-[0.2em] text-slate-500">{isDbConnected ? 'Sincronizado' : 'Modo Offline'}</span>
            </div>
          </div>
        </header>

        <div className="animate-in fade-in duration-500 pb-20 md:pb-0">
          {activeTab === 'dashboard' && (
            <div className="space-y-8">
              <div className="relative overflow-hidden bg-slate-900 rounded-[3.5rem] p-12 md:p-16 text-white shadow-xl min-h-[250px] flex items-center bg-cover bg-center" style={{ backgroundImage: `linear-gradient(rgba(15, 23, 42, 0.7), rgba(15, 23, 42, 0.7)), url(${relaxingImages[Math.floor(Math.random()*4)]})` }}>
                  <div className="relative z-10 w-full">
                    <p className="text-blue-400 font-black text-[14px] md:text-[16px] uppercase tracking-[0.5em] mb-6 md:mb-8">Estrategia & Visión Diaria</p>
                    <h2 className="text-2xl md:text-5xl font-[900] leading-tight tracking-tighter italic max-w-5xl">"{DAILY_QUOTES[Math.floor(Math.random()*DAILY_QUOTES.length)]}"</h2>
                  </div>
              </div>

              {/* NUEVA SECCIÓN: SOLICITUDES DE REGULARIZACIÓN PENDIENTES */}
              {role === Role.SUPER_ADMIN && pendingApprovals.length > 0 && (
                <div className="bg-white p-8 md:p-10 rounded-[3.5rem] border-4 border-blue-100 shadow-xl animate-bounce-subtle">
                   <div className="flex items-center gap-4 mb-8">
                      <div className="w-12 h-12 bg-blue-600 text-white rounded-2xl flex items-center justify-center text-2xl">⚖️</div>
                      <div>
                        <h3 className="text-[14px] font-black text-slate-900 uppercase tracking-widest leading-none mb-1">Autorizaciones de Asistencia</h3>
                        <p className="text-[10px] font-black text-blue-500 uppercase">Solicitudes por falta de acceso al panel</p>
                      </div>
                   </div>
                   <div className="space-y-4">
                      {pendingApprovals.map(req => {
                        const emp = employees.find(e => e.id === req.employeeId);
                        return (
                          <div key={req.id} className="flex flex-col md:flex-row items-center justify-between gap-6 p-6 bg-slate-50 rounded-[2rem] border border-blue-50">
                             <div className="flex items-center gap-4 flex-1">
                                <div className="w-12 h-12 bg-white rounded-2xl border flex items-center justify-center overflow-hidden shrink-0">
                                   {emp?.photo ? <img src={emp.photo} className="w-full h-full object-cover" /> : <span className="font-black">{emp?.name[0]}</span>}
                                </div>
                                <div>
                                   <p className="text-xs font-black text-slate-900 uppercase">{emp?.surname} {emp?.name}</p>
                                   <p className="text-[9px] font-bold text-slate-400 uppercase">{req.type === 'in' ? 'Ingreso' : 'Salida'} Olvidado • {new Date(req.timestamp).toLocaleString('es-EC')}</p>
                                   <p className="text-[9px] font-black text-blue-600 mt-1 italic">"{req.justification}"</p>
                                </div>
                             </div>
                             <div className="flex gap-3">
                                <button onClick={() => handleProcessApproval(req.id, 'rejected')} className="px-6 py-3 bg-white text-red-500 border-2 border-red-100 font-black rounded-xl uppercase text-[9px] hover:bg-red-50 transition-all">Rechazar</button>
                                <button onClick={() => handleProcessApproval(req.id, 'confirmed')} className="px-6 py-3 bg-emerald-600 text-white font-black rounded-xl uppercase text-[9px] shadow-lg hover:bg-emerald-700 transition-all">Aprobar Marcación</button>
                             </div>
                          </div>
                        );
                      })}
                   </div>
                </div>
              )}

              <div className="bg-white p-6 md:p-8 rounded-[3rem] border border-slate-100 shadow-sm">
                 <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-6 gap-4">
                    <div>
                      <h3 className="text-[13px] font-black text-slate-900 uppercase tracking-widest leading-none mb-2">Monitoreo de Jornada Diaria</h3>
                      <p className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Actividad Confirmada • {new Date().toLocaleDateString('es-EC', {day: 'numeric', month: 'long', year: 'numeric'})}</p>
                    </div>
                 </div>
                 {/* GRID AJUSTADO AL CONTENIDO CON MENOS GAP Y PADDING */}
                 <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-3 max-h-[400px] overflow-y-auto custom-scroll pr-2">
                    {todayMarkings.length === 0 ? (
                      <div className="col-span-full py-16 flex flex-col items-center justify-center opacity-40">
                         <span className="text-4xl mb-3">⌛</span>
                         <p className="text-[11px] font-black uppercase tracking-[0.2em] text-slate-400">Esperando marcaciones...</p>
                      </div>
                    ) : (
                      todayMarkings.map((mark) => {
                        const emp = employees.find(e => e.id === mark.employeeId);
                        const empMarksToday = (attendance || []).filter(a => a.employeeId === mark.employeeId && a.timestamp.startsWith(todayDateStr) && a.status === 'confirmed').sort((a, b) => a.timestamp.localeCompare(b.timestamp));
                        let specificLabel = ""; let labelColor = "";
                        if (mark.type === 'half_day') { specificLabel = "Media Jornada"; labelColor = "bg-amber-500 text-white"; }
                        else if (mark.type === 'in') { const inIndex = empMarksToday.filter(m => m.type === 'in').findIndex(m => m.id === mark.id); specificLabel = inIndex === 0 ? "In Mañana" : "In Tarde"; labelColor = inIndex === 0 ? "bg-emerald-600 text-white" : "bg-cyan-600 text-white"; }
                        else if (mark.type === 'out') { const outIndex = empMarksToday.filter(m => m.type === 'out').findIndex(m => m.id === mark.id); specificLabel = outIndex === 0 ? "Out M. Día" : "Out Fin"; labelColor = outIndex === 0 ? "bg-orange-600 text-white" : "bg-pink-600 text-white"; }

                        return (
                          <div key={mark.id} className="flex items-center gap-3 bg-slate-50/50 p-3 rounded-2xl border border-slate-100 transition-all hover:shadow-md hover:bg-white group">
                             <div className="w-8 h-8 bg-white rounded-xl border flex items-center justify-center overflow-hidden shrink-0">
                                {emp?.photo ? <img src={emp.photo} className="w-full h-full object-cover" /> : <span className="text-[10px] font-black uppercase text-slate-300">{emp?.name[0]}</span>}
                             </div>
                             <div className="flex-1 min-w-0">
                                <p className="text-[10px] font-black text-slate-900 uppercase leading-none truncate mb-1">{emp?.surname} {emp?.name}</p>
                                <div className="flex flex-wrap items-center gap-1">
                                   <span className={`text-[6px] font-black uppercase px-1.5 py-0.5 rounded-full ${labelColor}`}>{specificLabel}</span>
                                   {mark.isLate && <span className="text-[6px] font-black uppercase bg-red-100 text-red-600 px-1 py-0.5 rounded-full animate-pulse">Retraso</span>}
                                   {mark.isForgotten && <span className="text-[6px] font-black uppercase bg-blue-100 text-blue-600 px-1 py-0.5 rounded-full">Reg.</span>}
                                </div>
                             </div>
                             <div className="text-right shrink-0">
                                <p className="text-[11px] font-black text-slate-900 tabular-nums leading-none">{new Date(mark.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</p>
                             </div>
                          </div>
                        );
                      })
                    )}
                 </div>
              </div>
            </div>
          )}
          {activeTab === 'notifications' && <NotificationsModule notifications={notifications} onToggleRead={(id) => setNotifications(prev => prev.map(n => n.id === id ? {...n, isRead: !n.isRead} : n))} onToggleProcessed={(id) => setNotifications(prev => prev.map(n => n.id === id ? {...n, isProcessed: !n.isProcessed} : n))} onClearAll={() => { setNotifications([]); }} />}
          {activeTab === 'company' && <CompanyModule company={company} onUpdate={onUpdateCompany} role={role} />}
          {activeTab === 'employees' && <EmployeeModule employees={employees} onUpdate={onUpdateEmployees} role={role} attendance={attendance} payments={payments} company={company} />}
          {activeTab === 'payroll' && <PayrollModule employees={employees} payments={payments} onUpdatePayments={onUpdatePayments} onUpdateEmployees={onUpdateEmployees} attendance={attendance} company={company} settings={settings} role={role} />}
          {activeTab === 'payments' && <PaymentsModule employees={employees} payments={payments} onUpdate={onUpdatePayments} role={role} company={company} />}
          {activeTab === 'settings' && <SettingsModule settings={settings} onUpdate={onUpdateSettings} role={role} onPurge={handlePurgeData} allData={{ company, employees, attendance, payments, settings }} />}
          {activeTab === 'reports' && <ReportsModule employees={employees} payments={payments} attendance={attendance} company={company} settings={settings} role={role} />}
          {activeTab === 'ai' && <AiAssistant employees={employees} attendance={attendance} payments={payments} role={role} />}
        </div>
      </main>
    </div>
  );
};

const relaxingImages = [
  "https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&q=80&w=2070",
  "https://images.unsplash.com/photo-1441974231531-c6227db76b6e?auto=format&fit=crop&q=80&w=2071",
  "https://images.unsplash.com/photo-1579783902614-a3fb3927b6a5?auto=format&fit=crop&q=80&w=2070",
  "https://images.unsplash.com/photo-1541450805268-4822a3a774ce?auto=format&fit=crop&q=80&w=2070"
];

export default AdminDashboard;

import React, { useState, useMemo, useEffect } from 'react';
import { Role, CompanyConfig, Employee, AttendanceRecord, Payment, GlobalSettings, NotificationMessage } from '../types.ts';
import Sidebar from '../components/Sidebar.tsx';
import CompanyModule from './modules/CompanyModule.tsx';
import EmployeeModule from './modules/EmployeeModule.tsx';
import PayrollModule from './modules/PayrollModule.tsx';
import PaymentsModule from './modules/PaymentsModule.tsx';
import SettingsModule from './modules/SettingsModule.tsx';
import ReportsModule from './modules/ReportsModule.tsx';
import AiAssistant from './modules/AiAssistant.tsx';
import NotificationsModule from './modules/NotificationsModule.tsx';
import Modal from '../components/Modal.tsx';
import { DAILY_QUOTES, ACTIVE_BREAKS, ECUADOR_HOLIDAYS } from '../constants.tsx';

interface AdminDashboardProps {
  role: Role;
  isDbConnected?: boolean;
  onLogout: () => void;
  company: CompanyConfig | null;
  onUpdateCompany: (config: CompanyConfig) => void;
  employees: Employee[];
  onUpdateEmployees: (employees: Employee[]) => void;
  attendance: AttendanceRecord[];
  onUpdateAttendance?: (records: AttendanceRecord[]) => void;
  payments: Payment[];
  onUpdatePayments: (payments: Payment[]) => void;
  settings: GlobalSettings;
  onUpdateSettings: (settings: GlobalSettings) => void;
  onUpdateAppMode: (mode: 'full' | 'attendance') => void;
  appMode: 'full' | 'attendance';
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ 
  role, isDbConnected, onLogout, company, onUpdateCompany, employees, onUpdateEmployees, attendance, onUpdateAttendance, payments, onUpdatePayments, settings, onUpdateSettings, onUpdateAppMode, appMode 
}) => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'company' | 'employees' | 'payroll' | 'payments' | 'settings' | 'reports' | 'ai' | 'notifications'>('dashboard');
  const [notifications, setNotifications] = useState<NotificationMessage[]>([]);
  const [dismissedNotificationIds, setDismissedNotificationIds] = useState<Set<string>>(new Set());

  const today = useMemo(() => new Date(), []);
  const todayDateStr = useMemo(() => today.toISOString().split('T')[0], [today]);
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();

  const addNotification = (id: string, title: string, message: string, type: 'info' | 'alert' | 'critical') => {
    if (dismissedNotificationIds.has(id)) return;
    setNotifications(prev => {
      if (prev.some(n => n.id === id)) return prev;
      return [{ id, title, message, timestamp: new Date().toISOString(), type, isRead: false, isProcessed: false }, ...prev];
    });
  };

  useEffect(() => {
    if (currentYear < 2026 || (currentYear === 2026 && currentMonth < 1)) return;
    const activeEmployees = employees.filter(e => e.status === 'active');
    const markedTodayIds = new Set((attendance || []).filter(a => a.timestamp.includes(todayDateStr)).map(a => a.employeeId));
    const missingAttendanceCount = activeEmployees.filter(e => !markedTodayIds.has(e.id)).length;
    if (missingAttendanceCount > 0 && activeTab === 'dashboard') {
      addNotification(`missing-attendance-${todayDateStr}`, "Marcaciones Pendientes", `Hoy faltan ${missingAttendanceCount} registros de ingreso por completar.`, 'alert');
    }
  }, [employees, attendance, todayDateStr, activeTab, dismissedNotificationIds, currentMonth, currentYear]);

  // Cálculos para Calendario y Proximidad
  const calendarDays = useMemo(() => {
    const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
    const firstDay = new Date(currentYear, currentMonth, 1).getDay();
    const days = [];
    for (let i = 0; i < firstDay; i++) days.push(null);
    for (let i = 1; i <= daysInMonth; i++) days.push(i);
    return days;
  }, [currentMonth, currentYear]);

  const monthHolidays = useMemo(() => {
    const standard = ECUADOR_HOLIDAYS.filter(h => h.month === currentMonth).map(h => ({ day: h.day, name: h.name }));
    const custom = (settings.holidays || [])
      .filter(dateStr => {
        const d = new Date(dateStr + 'T00:00:00');
        return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
      })
      .map(dateStr => ({
        day: new Date(dateStr + 'T00:00:00').getDate(),
        name: "Feriado Institucional"
      }));
    return [...standard, ...custom].sort((a, b) => a.day - b.day);
  }, [currentMonth, currentYear, settings.holidays]);

  const monthBirthdays = useMemo(() => {
    return employees.filter(e => {
      if (!e.birthDate || e.status !== 'active') return false;
      return new Date(e.birthDate).getMonth() === currentMonth;
    }).sort((a, b) => {
      const dayA = new Date(a.birthDate).getDate() + 1;
      const dayB = new Date(b.birthDate).getDate() + 1;
      return dayA - dayB;
    });
  }, [employees, currentMonth]);

  const pendingApprovals = useMemo(() => {
    return (attendance || []).filter(a => a.status === 'pending_approval').sort((a, b) => b.timestamp.localeCompare(a.timestamp));
  }, [attendance]);

  const handleProcessApproval = (id: string, newStatus: 'confirmed' | 'rejected') => {
    if (!onUpdateAttendance) return;
    const recordsToUpdate = attendance.map(a => a.id === id ? { ...a, status: newStatus, validatedAt: new Date().toISOString() } : a);
    onUpdateAttendance(recordsToUpdate.filter(a => a.id === id));
  };

  const todayMarkings = useMemo(() => {
    return (attendance || [])
      .filter(a => a.timestamp.includes(todayDateStr) && a.status === 'confirmed')
      .sort((a, b) => {
        const empA = employees.find(e => e.id === a.employeeId);
        const empB = employees.find(e => e.id === b.employeeId);
        const nameA = `${empA?.surname || ''} ${empA?.name || ''}`;
        const nameB = `${empB?.surname || ''} ${empB?.name || ''}`;
        if (nameA !== nameB) return nameA.localeCompare(nameB);
        return a.timestamp.localeCompare(b.timestamp);
      });
  }, [attendance, todayDateStr, employees]);

  const handlePurgeData = async () => {
    if (role !== Role.SUPER_ADMIN) return;
    onUpdateEmployees([]);
    onUpdatePayments([]);
  };

  const relaxingImages = [
    "https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&q=80&w=2070",
    "https://images.unsplash.com/photo-1441974231531-c6227db76b6e?auto=format&fit=crop&q=80&w=2071",
    "https://images.unsplash.com/photo-1579783902614-a3fb3927b6a5?auto=format&fit=crop&q=80&w=2070",
    "https://images.unsplash.com/photo-1541450805268-4822a3a774ce?auto=format&fit=crop&q=80&w=2070"
  ];

  return (
    <div className="flex h-screen bg-[#fcfdfe] overflow-hidden flex-col md:flex-row">
      <Sidebar role={role} activeTab={activeTab} setActiveTab={setActiveTab} onLogout={onLogout} companyName={company?.name} unreadCount={notifications.filter(n => !n.isRead).length} />
      <main className="flex-1 overflow-y-auto px-4 md:px-8 py-4 md:py-8 scroll-smooth custom-scroll">
        <header className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4 no-print pt-14 md:pt-0">
          <div className="flex flex-col sm:flex-row items-start sm:items-center gap-3 w-full md:w-auto">
            <h1 className="text-3xl md:text-4xl font-[950] text-slate-900 tracking-tight uppercase leading-none italic">Management Hub</h1>
            <div className="flex items-center gap-2 px-4 py-2 bg-white border-2 border-slate-100 rounded-full shadow-sm w-fit">
               <div className={`w-3 h-3 rounded-full ${isDbConnected ? 'bg-emerald-500 animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.5)]' : 'bg-red-500 shadow-[0_0_8px_rgba(239,68,68,0.5)]'}`}></div>
               <span className="text-[12px] font-black uppercase tracking-[0.2em] text-slate-500">{isDbConnected ? 'Sincronizado' : 'Modo Offline'}</span>
            </div>
          </div>
        </header>

        <div className="animate-in fade-in duration-500 pb-20 md:pb-0">
          {activeTab === 'dashboard' && (
            <div className="space-y-8">
              {/* MENSAJE INSPIRACIONAL REDUCIDO */}
              <div className="relative overflow-hidden bg-slate-900 rounded-[2.5rem] p-6 md:p-8 text-white shadow-xl min-h-[160px] flex items-center bg-cover bg-center" style={{ backgroundImage: `linear-gradient(rgba(15, 23, 42, 0.7), rgba(15, 23, 42, 0.7)), url(${relaxingImages[Math.floor(today.getDate() % 4)]})` }}>
                  <div className="relative z-10 w-full">
                    <p className="text-blue-400 font-black text-[10px] md:text-[12px] uppercase tracking-[0.5em] mb-4">Estrategia & Visión Diaria</p>
                    <h2 className="text-xl md:text-3xl font-[900] leading-tight tracking-tighter italic max-w-4xl">"{DAILY_QUOTES[Math.floor(today.getDate() % DAILY_QUOTES.length)]}"</h2>
                  </div>
              </div>

              {/* AUTORIZACIONES PENDIENTES */}
              {role === Role.SUPER_ADMIN && pendingApprovals.length > 0 && (
                <div className="bg-white p-8 md:p-10 rounded-[3.5rem] border-4 border-blue-100 shadow-xl">
                   <div className="flex items-center gap-4 mb-8">
                      <div className="w-12 h-12 bg-blue-600 text-white rounded-2xl flex items-center justify-center text-2xl">⚖️</div>
                      <div>
                        <h3 className="text-[14px] font-black text-slate-900 uppercase tracking-widest leading-none mb-1">Autorizaciones Pendientes</h3>
                        <p className="text-[10px] font-black text-blue-500 uppercase">Solicitudes por regularizar</p>
                      </div>
                   </div>
                   <div className="space-y-4">
                      {pendingApprovals.map(req => {
                        const emp = employees.find(e => e.id === req.employeeId);
                        return (
                          <div key={req.id} className="flex flex-col md:flex-row items-center justify-between gap-6 p-6 bg-slate-50 rounded-[2rem] border border-blue-50">
                             <div className="flex items-center gap-4 flex-1">
                                <div className="w-12 h-12 bg-white rounded-2xl border flex items-center justify-center overflow-hidden shrink-0">
                                   {emp?.photo ? <img src={emp.photo} className="w-full h-full object-cover" /> : <span className="font-black">{emp?.name[0]}</span>}
                                </div>
                                <div>
                                   <p className="text-xs font-black text-slate-900 uppercase">{emp?.surname} {emp?.name}</p>
                                   <p className="text-[9px] font-bold text-slate-400 uppercase">{req.type === 'in' ? 'Ingreso' : 'Salida'} • {new Date(req.timestamp).toLocaleString('es-EC')}</p>
                                   <p className="text-[9px] font-black text-blue-600 mt-1 italic">"{req.justification}"</p>
                                </div>
                             </div>
                             <div className="flex gap-3">
                                <button onClick={() => handleProcessApproval(req.id, 'rejected')} className="px-6 py-3 bg-white text-red-500 border-2 border-red-100 font-black rounded-xl uppercase text-[9px]">Rechazar</button>
                                <button onClick={() => handleProcessApproval(req.id, 'confirmed')} className="px-6 py-3 bg-emerald-600 text-white font-black rounded-xl uppercase text-[9px] shadow-lg">Aprobar</button>
                             </div>
                          </div>
                        );
                      })}
                   </div>
                </div>
              )}

              {/* MONITOREO DE JORNADA DIARIA REDUCIDO */}
              <div className="bg-white p-6 md:p-8 rounded-[3rem] border border-slate-100 shadow-sm">
                 <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-6 gap-4">
                    <div>
                      <h3 className="text-[13px] font-black text-slate-900 uppercase tracking-widest leading-none mb-2">Monitoreo de Jornada Diaria</h3>
                      <p className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">Actividad Confirmada • {today.toLocaleDateString('es-EC', {day: 'numeric', month: 'long', year: 'numeric'})}</p>
                    </div>
                 </div>
                 <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-3 max-h-[300px] overflow-y-auto custom-scroll pr-2">
                    {todayMarkings.length === 0 ? (
                      <div className="col-span-full py-12 flex flex-col items-center justify-center opacity-40">
                         <span className="text-4xl mb-3">⌛</span>
                         <p className="text-[11px] font-black uppercase tracking-[0.2em] text-slate-400">Esperando marcaciones...</p>
                      </div>
                    ) : (
                      todayMarkings.map((mark) => {
                        const emp = employees.find(e => e.id === mark.employeeId);
                        const empMarksToday = (attendance || []).filter(a => a.employeeId === mark.employeeId && a.timestamp.startsWith(todayDateStr) && a.status === 'confirmed').sort((a, b) => a.timestamp.localeCompare(b.timestamp));
                        let specificLabel = ""; let labelColor = "";
                        if (mark.type === 'half_day') { specificLabel = "Media Jornada"; labelColor = "bg-amber-500 text-white"; }
                        else if (mark.type === 'in') { const inIndex = empMarksToday.filter(m => m.type === 'in').findIndex(m => m.id === mark.id); specificLabel = inIndex === 0 ? "In Mañana" : "In Tarde"; labelColor = inIndex === 0 ? "bg-emerald-600 text-white" : "bg-cyan-600 text-white"; }
                        else if (mark.type === 'out') { const outIndex = empMarksToday.filter(m => m.type === 'out').findIndex(m => m.id === mark.id); specificLabel = outIndex === 0 ? "Out M. Día" : "Out Fin"; labelColor = outIndex === 0 ? "bg-orange-600 text-white" : "bg-pink-600 text-white"; }

                        return (
                          <div key={mark.id} className="flex items-center gap-3 bg-slate-50/50 p-3 rounded-2xl border border-slate-100 transition-all hover:shadow-md hover:bg-white group">
                             <div className="w-8 h-8 bg-white rounded-xl border flex items-center justify-center overflow-hidden shrink-0">
                                {emp?.photo ? <img src={emp.photo} className="w-full h-full object-cover" /> : <span className="text-[10px] font-black uppercase text-slate-300">{emp?.name[0]}</span>}
                             </div>
                             <div className="flex-1 min-w-0">
                                <p className="text-[10px] font-black text-slate-900 uppercase leading-none truncate mb-1">{emp?.surname} {emp?.name}</p>
                                <div className="flex flex-wrap items-center gap-1">
                                   <span className={`text-[6px] font-black uppercase px-1.5 py-0.5 rounded-full ${labelColor}`}>{specificLabel}</span>
                                   {mark.isLate && <span className="text-[6px] font-black uppercase bg-red-100 text-red-600 px-1 py-0.5 rounded-full animate-pulse">Retraso</span>}
                                   {mark.isForgotten && <span className="text-[6px] font-black uppercase bg-blue-100 text-blue-600 px-1 py-0.5 rounded-full">Reg.</span>}
                                </div>
                             </div>
                             <div className="text-right shrink-0">
                                <p className="text-[11px] font-black text-slate-900 tabular-nums leading-none">{new Date(mark.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</p>
                             </div>
                          </div>
                        );
                      })
                    )}
                 </div>
              </div>

              {/* CALENDARIO CORPORATIVO Y AGENDA RESTAURADOS */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                <div className="bg-white p-8 md:p-10 rounded-[3rem] border border-slate-100 shadow-sm flex flex-col min-h-[450px]">
                   <div className="flex justify-between items-center mb-8">
                      <div>
                        <h3 className="text-[13px] font-black text-slate-900 uppercase tracking-widest leading-none mb-2">Calendario Corporativo</h3>
                        <p className="text-[11px] text-slate-400 font-bold uppercase tracking-widest">{new Intl.DateTimeFormat('es-EC', { month: 'long', year: 'numeric' }).format(today)}</p>
                      </div>
                      <div className="flex gap-4">
                         <span className="flex items-center gap-2 text-[10px] font-black text-blue-600 uppercase"><div className="w-2 h-2 bg-blue-500 rounded-full"></div> Feriado</span>
                         <span className="flex items-center gap-2 text-[10px] font-black text-emerald-600 uppercase"><div className="w-2 h-2 bg-emerald-500 rounded-full"></div> Cumple</span>
                      </div>
                   </div>
                   <div className="grid grid-cols-7 gap-2 text-center flex-1 items-center">
                      {['D', 'L', 'M', 'M', 'J', 'V', 'S'].map(d => (
                        <div key={d} className="text-[11px] font-black text-slate-300 uppercase py-2">{d}</div>
                      ))}
                      {calendarDays.map((day, i) => {
                        const isHoliday = day && monthHolidays.some(h => h.day === day);
                        const isBirthday = day && monthBirthdays.some(e => new Date(e.birthDate).getDate() + 1 === day);
                        const isToday = day === today.getDate();

                        return (
                          <div key={i} className={`
                            relative aspect-square flex items-center justify-center text-[12px] font-black rounded-2xl transition-all
                            ${!day ? 'opacity-0' : 'hover:bg-slate-50 cursor-pointer'}
                            ${isToday ? 'bg-slate-900 text-white shadow-lg scale-110 z-10' : 'text-slate-600'}
                            ${isHoliday ? 'text-blue-600 bg-blue-50/50' : ''}
                            ${isBirthday ? 'text-emerald-600 bg-emerald-50/50' : ''}
                          `}>
                            {day}
                            {(isHoliday || isBirthday) && <div className={`absolute bottom-1.5 w-1.5 h-1.5 rounded-full ${isHoliday ? 'bg-blue-600' : 'bg-emerald-600'}`}></div>}
                          </div>
                        );
                      })}
                   </div>
                </div>

                <div className="bg-slate-50 p-8 md:p-10 rounded-[3rem] border border-slate-100 flex flex-col min-h-[450px]">
                   <h3 className="text-[13px] font-black text-slate-400 uppercase tracking-widest border-b-2 border-slate-200 pb-4 mb-6">Agenda de Novedades (Proximidad)</h3>
                   <div className="space-y-3 overflow-y-auto custom-scroll flex-1 pr-2">
                      {monthHolidays.map((h, i) => (
                         <div key={i} className="flex gap-4 items-center bg-white p-4 rounded-2xl border border-slate-200/50 shadow-sm">
                            <div className="w-10 h-10 bg-blue-50 text-blue-600 rounded-xl flex items-center justify-center text-xl">📅</div>
                            <div>
                               <p className="text-[11px] font-black text-slate-900 uppercase leading-none">{h.name}</p>
                               <p className="text-[9px] font-black text-blue-500 uppercase mt-2">Día {h.day}</p>
                            </div>
                         </div>
                      ))}
                      {monthBirthdays.map((e, i) => (
                         <div key={i} className="flex gap-4 items-center bg-white p-4 rounded-2xl border border-slate-200/50 shadow-sm">
                            <div className="w-10 h-10 rounded-xl overflow-hidden border bg-slate-100 flex items-center justify-center text-[12px] font-black uppercase">
                               {e.photo ? <img src={e.photo} className="w-full h-full object-cover" /> : <span className="text-slate-400">{e.name[0]}</span>}
                            </div>
                            <div>
                               <p className="text-[11px] font-black text-slate-900 uppercase leading-none">{e.surname} {e.name}</p>
                               <p className="text-[9px] font-black text-emerald-500 uppercase mt-2">Cumpleaños • Día {new Date(e.birthDate).getDate() + 1}</p>
                            </div>
                         </div>
                      ))}
                      {monthHolidays.length === 0 && monthBirthdays.length === 0 && (
                        <div className="h-full flex flex-col items-center justify-center py-16 opacity-30">
                          <span className="text-4xl mb-4">🍃</span>
                          <p className="text-[11px] text-slate-400 font-black uppercase tracking-widest">Sin eventos próximos</p>
                        </div>
                      )}
                   </div>
                </div>
              </div>
            </div>
          )}
          {activeTab === 'notifications' && <NotificationsModule notifications={notifications} onToggleRead={(id) => setNotifications(prev => prev.map(n => n.id === id ? {...n, isRead: !n.isRead} : n))} onToggleProcessed={(id) => setNotifications(prev => prev.map(n => n.id === id ? {...n, isProcessed: !n.isProcessed} : n))} onClearAll={() => { setNotifications([]); }} />}
          {activeTab === 'company' && <CompanyModule company={company} onUpdate={onUpdateCompany} role={role} />}
          {activeTab === 'employees' && <EmployeeModule employees={employees} onUpdate={onUpdateEmployees} role={role} attendance={attendance} payments={payments} company={company} />}
          {activeTab === 'payroll' && <PayrollModule employees={employees} payments={payments} onUpdatePayments={onUpdatePayments} onUpdateEmployees={onUpdateEmployees} attendance={attendance} company={company} settings={settings} role={role} />}
          {activeTab === 'payments' && <PaymentsModule employees={employees} payments={payments} onUpdate={onUpdatePayments} role={role} company={company} />}
          {activeTab === 'settings' && <SettingsModule settings={settings} onUpdate={onUpdateSettings} role={role} onPurge={handlePurgeData} allData={{ company, employees, attendance, payments, settings }} />}
          {activeTab === 'reports' && <ReportsModule employees={employees} payments={payments} attendance={attendance} company={company} settings={settings} role={role} />}
          {activeTab === 'ai' && <AiAssistant employees={employees} attendance={attendance} payments={payments} role={role} />}
        </div>
      </main>
    </div>
  );
};

export default AdminDashboard;

import React, { useState } from 'react';
import { Employee, Payment, AttendanceRecord, CompanyConfig, GlobalSettings, Role } from '../../types.ts';
import Modal from '../../components/Modal.tsx';
import JSZip from 'jszip';

interface ReportsModuleProps {
  employees: Employee[];
  payments: Payment[];
  attendance: AttendanceRecord[];
  company: CompanyConfig | null;
  settings: GlobalSettings;
  role: Role;
}

const ReportsModule: React.FC<ReportsModuleProps> = ({ employees, payments = [], attendance = [], company, settings, role }) => {
  const [reportType, setReportType] = useState<'attendance' | 'payments' | 'history' | 'master'>('attendance');
  const [searchTerm, setSearchTerm] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [isZipping, setIsZipping] = useState(false);
  const [feedback, setFeedback] = useState({ isOpen: false, title: '', message: '', type: 'success' as any });

  const getCSVData = (type: 'employees' | 'payroll' | 'attendance' | 'novedades' | 'bajas') => {
    let csv = "\uFEFF";
    if (type === 'employees') {
      csv += "ID,COLABORADOR,CARGO,INGRESO,AFILIACION IESS,FONDOS RESERVA,DECIMOS,SUELDO,STATUS\n";
      employees.forEach(e => {
        csv += `"${e.identification}","${e.surname} ${e.name}","${e.role}","${e.startDate}","${e.isAffiliated ? 'SI' : 'NO'}","${e.reserveFundType || 'N/A'}","${e.overSalaryType}","${e.salary.toFixed(2)}","${e.status}"\n`;
      });
    } else if (type === 'payroll') {
      csv += "VOUCHER,FECHA,BENEFICIARIO,CONCEPTO,METODO,MONTO,STATUS\n";
      payments.forEach(p => {
        const emp = employees.find(e => e.id === p.employeeId);
        csv += `"${p.voucherCode}","${new Date(p.date).toLocaleDateString()}","${emp?.surname} ${emp?.name}","${p.type}","${p.method}","${p.amount.toFixed(2)}","${p.status}"\n`;
      });
    } else if (type === 'attendance') {
      csv += "FECHA,COLABORADOR,ID,TIPO,ESTADO,ATRASO,JUSTIFICACION\n";
      attendance.forEach(a => {
        const emp = employees.find(e => e.id === a.employeeId);
        csv += `"${new Date(a.timestamp).toLocaleString()}","${emp?.surname} ${emp?.name}","${emp?.identification}","${a.type}","${a.status}","${a.isLate ? 'SI' : 'NO'}","${a.justification || ''}"\n`;
      });
    } else if (type === 'novedades') {
      csv += "FECHA REGISTRO,COLABORADOR,EVENTO ADMINISTRATIVO\n";
      employees.forEach(e => {
        if (e.observations) e.observations.forEach(obs => {
          csv += `"${new Date(obs.date).toLocaleString()}","${e.surname} ${e.name}","${obs.text}"\n`;
        });
      });
    } else if (type === 'bajas') {
      csv += "COLABORADOR,IDENTIFICACION,SALIDA,MOTIVO LEGAL,DETALLES FINALES\n";
      employees.filter(e => e.status === 'terminated').forEach(e => {
        csv += `"${e.surname} ${e.name}","${e.identification}","${e.terminationDate}","${e.terminationReason}","${e.terminationDetails}"\n`;
      });
    }
    return csv;
  };

  const handleDownloadMasterZip = async () => {
    setIsZipping(true);
    try {
      const zip = new JSZip();
      const folder = zip.folder(`ARCHIVO_MAESTRO_ASISTUP_${new Date().getFullYear()}`);

      folder?.file("1_CENSO_PERSONAL_MAESTRO.csv", getCSVData('employees'));
      folder?.file("2_REGISTRO_PAGOS_NOMINA.csv", getCSVData('payroll'));
      folder?.file("3_BITACORA_ASISTENCIA.csv", getCSVData('attendance'));
      folder?.file("4_HISTORIAL_NOVEDADES.csv", getCSVData('novedades'));
      folder?.file("5_EXPEDIENTES_DESVINCULADOS.csv", getCSVData('bajas'));

      const blob = await zip.generateAsync({ type: "blob" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = `CONSOLIDADO_MASTER_ASISTUP_${new Date().toISOString().split('T')[0]}.zip`;
      link.click();
      setFeedback({ isOpen: true, title: "Éxito Corporativo", message: "Contenedor ZIP generado y descargado correctamente para archivo físico.", type: "success" });
    } catch (e) {
      setFeedback({ isOpen: true, title: "Fallo Crítico", message: "No se pudo consolidar el paquete comprimido.", type: "error" });
    } finally {
      setIsZipping(false);
    }
  };

  const generateReportExcel = (type: any) => {
    const csv = getCSVData(type);
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `REPORTE_MASTER_${type.toUpperCase()}.csv`;
    link.click();
  };

  const generateReportPDF = (type: any) => {
    setReportType(type);
    setTimeout(() => window.print(), 500);
  };

  // Lógica de filtrado por búsqueda y fecha
  const filterByDate = (timestamp: string) => {
    if (!startDate && !endDate) return true;
    const date = new Date(timestamp);
    const start = startDate ? new Date(startDate + 'T00:00:00') : null;
    const end = endDate ? new Date(endDate + 'T23:59:59') : null;
    if (start && date < start) return false;
    if (end && date > end) return false;
    return true;
  };

  const attendanceToDisplay = (attendance || []).filter(a => {
    const emp = employees.find(e => e.id === a.employeeId);
    const matchesSearch = `${emp?.surname} ${emp?.name} ${emp?.identification}`.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesSearch && filterByDate(a.timestamp);
  }).sort((a, b) => {
    const empA = employees.find(e => e.id === a.employeeId);
    const empB = employees.find(e => e.id === b.employeeId);
    const nameA = `${empA?.surname || ''} ${empA?.name || ''}`;
    const nameB = `${empB?.surname || ''} ${empB?.name || ''}`;
    if (nameA !== nameB) return nameA.localeCompare(nameB);
    return a.timestamp.localeCompare(b.timestamp);
  });

  const paymentsToDisplay = payments.filter(p => {
    const emp = employees.find(e => e.id === p.employeeId);
    const matchesSearch = `${emp?.surname} ${emp?.name} ${p.voucherCode}`.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesSearch && filterByDate(p.date);
  }).sort((a,b) => b.date.localeCompare(a.date));

  const historyToDisplay = employees.filter(e => {
    const searchStr = `${e.name} ${e.surname} ${e.identification} ${e.status}`.toLowerCase();
    const matchesSearch = searchStr.includes(searchTerm.toLowerCase());
    // Para historial de personal, filtramos por fecha de ingreso
    return matchesSearch && filterByDate(e.startDate);
  }).sort((a,b) => b.startDate.localeCompare(a.startDate));

  const translateAttendanceStatus = (record: AttendanceRecord) => {
    let base = "";
    if (record.type === 'in') base = record.status === 'confirmed' ? "INGRESO APROBADO" : record.status === 'pending_approval' ? "INGRESO PENDIENTE" : "INGRESO RECHAZADO";
    else if (record.type === 'out') base = record.status === 'confirmed' ? "SALIDA APROBADA" : record.status === 'pending_approval' ? "SALIDA PENDIENTE" : "SALIDA RECHAZADA";
    else if (record.type === 'half_day') base = "MEDIA JORNADA LIBRE";

    return (
      <span className="flex flex-col items-end">
        <span>{base}</span>
        {record.isLate && <span className="text-[8px] font-black lowercase opacity-60">(atraso)</span>}
      </span>
    );
  };

  return (
    <div className="space-y-6 md:space-y-8 fade-in">
      <div className="bg-white p-6 md:p-10 rounded-[2.5rem] shadow-sm border no-print flex flex-col md:flex-row justify-between items-center gap-6">
        <div className="shrink-0">
           <h2 className="text-2xl font-[950] text-slate-900 uppercase italic">Centro de Reportes Maestro</h2>
           <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest mt-2">Auditoría y Gestión de Datos Corporativos</p>
        </div>
        <div className="flex flex-col gap-4 w-full md:w-auto">
          <div className="flex gap-2 overflow-x-auto pb-2 no-scrollbar">
            {['attendance', 'payments', 'history', 'master'].map(t => (
              <button key={t} onClick={() => {setReportType(t as any); setSearchTerm('');}} className={`whitespace-nowrap px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${reportType === t ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-50 text-slate-400 border'}`}>
                {t === 'attendance' ? 'Asistencia' : t === 'payments' ? 'Pagos' : t === 'history' ? 'Historial' : 'Archivo Maestro'}
              </button>
            ))}
          </div>

          {reportType !== 'master' && (
            <div className="flex flex-col sm:flex-row gap-3">
              <input type="text" placeholder="Filtrar por nombre o CI..." className="flex-1 p-3 border-2 rounded-xl text-[11px] font-bold uppercase outline-none focus:border-blue-500" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
              <div className="flex gap-2">
                 <div className="flex flex-col gap-1">
                   <label className="text-[7px] font-black uppercase text-slate-400">Desde</label>
                   <input type="date" className="p-3 border-2 rounded-xl text-[10px] font-black uppercase outline-none" value={startDate} onChange={e => setStartDate(e.target.value)} />
                 </div>
                 <div className="flex flex-col gap-1">
                   <label className="text-[7px] font-black uppercase text-slate-400">Hasta</label>
                   <input type="date" className="p-3 border-2 rounded-xl text-[10px] font-black uppercase outline-none" value={endDate} onChange={e => setEndDate(e.target.value)} />
                 </div>
                 <button onClick={() => {setStartDate(''); setEndDate(''); setSearchTerm('');}} className="mt-4 p-3 bg-slate-100 text-slate-500 rounded-xl hover:bg-red-50 hover:text-red-600 transition-colors">✕</button>
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="bg-white rounded-[2.5rem] shadow-sm border overflow-hidden" id="reports-printable-area">
         {/* CABECERA ESTRICTA PARA IMPRESIÓN */}
         <div className="hidden print:block p-10 border-b-4 border-black text-center space-y-4">
            <div className="flex items-center justify-center gap-6">
               <div className="w-20 h-20 border-2 border-black flex items-center justify-center overflow-hidden">
                  {company?.logo ? <img src={company.logo} className="w-full h-full object-contain" /> : <span className="text-2xl font-black">LOGO</span>}
               </div>
               <div className="text-left">
                  <h1 className="text-3xl font-[950] uppercase italic leading-none">{company?.name || 'EMPRESA INSTITUCIONAL'}</h1>
                  <p className="text-sm font-black uppercase mt-1">RUC: {company?.ruc || '0000000000001'}</p>
                  <p className="text-[10px] font-bold uppercase tracking-tighter">{company?.address || 'QUITO, ECUADOR'}</p>
               </div>
            </div>
            <div className="pt-4 border-t-2 border-black/10">
               <p className="text-[12px] font-[950] uppercase tracking-[0.3em]">Reporte de {reportType.toUpperCase()}</p>
               {startDate || endDate ? (
                 <p className="text-[10px] font-black uppercase mt-1">Período: {startDate || 'Inicio'} al {endDate || 'Hoy'}</p>
               ) : null}
               <p className="text-[8px] font-bold uppercase opacity-60">Documento Generado el {new Date().toLocaleString()}</p>
            </div>
         </div>

         {reportType === 'master' ? (
           <div className="p-10 md:p-16 space-y-12 no-print text-center">
              <header className="border-b pb-8">
                <h3 className="text-2xl font-black text-slate-900 uppercase tracking-widest">Gestión de Archivo Maestro</h3>
                <p className="text-[11px] font-black text-blue-600 uppercase mt-2 tracking-widest italic leading-relaxed">Consolidado integral para cumplimiento legal y auditorías externas de talento humano</p>
              </header>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 text-left">
                 {[
                   { id: 'employees', title: 'Censo Personal', icon: '👥', desc: 'Fichas, cargos y sueldos.' },
                   { id: 'payroll', title: 'Registro Pagos', icon: '💰', desc: 'Nómina, bonos y egresos.' },
                   { id: 'attendance', title: 'Asistencia', icon: '🕒', desc: 'Marcaciones y atrasos.' },
                   { id: 'novedades', title: 'Bitácora Novedades', icon: '📝', desc: 'Incidencias administrativas.' },
                   { id: 'bajas', title: 'Bajas Laborales', icon: '🚪', desc: 'Historial de desvinculaciones.' }
                 ].map(seg => (
                   <div key={seg.id} className="bg-slate-50 p-6 rounded-[2rem] border-2 border-slate-100 flex flex-col justify-between hover:border-blue-200 transition-colors">
                      <div className="mb-4 flex items-start gap-3">
                        <div className="w-10 h-10 bg-white rounded-xl shadow-inner flex items-center justify-center text-2xl">{seg.icon}</div>
                        <div>
                           <h4 className="text-[11px] font-[950] uppercase text-slate-900 leading-none mb-1">{seg.title}</h4>
                           <p className="text-[9px] text-slate-400 font-bold uppercase tracking-tighter leading-tight">{seg.desc}</p>
                        </div>
                      </div>
                      <div className="flex gap-2">
                        <button onClick={() => generateReportExcel(seg.id)} className="flex-1 py-2.5 bg-emerald-600 text-white text-[9px] font-black rounded-lg uppercase shadow-md active:scale-95 transition-all">Excel</button>
                        <button onClick={() => generateReportPDF(seg.id as any)} className="flex-1 py-2.5 bg-blue-700 text-white text-[9px] font-black rounded-lg uppercase shadow-md active:scale-95 transition-all">PDF</button>
                      </div>
                   </div>
                 ))}
              </div>
              <div className="pt-10 border-t flex flex-col items-center gap-6">
                 <button 
                   onClick={handleDownloadMasterZip} 
                   disabled={isZipping} 
                   className="w-full max-w-md py-6 bg-slate-900 text-white font-[950] rounded-[2rem] uppercase text-[12px] tracking-[0.4em] shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-4 group"
                 >
                   <span>{isZipping ? '⌛' : '📦'}</span>
                   {isZipping ? 'CONSOLIDANDO DATOS...' : 'Descargar Archivo Maestro .ZIP'}
                 </button>
                 <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest text-center italic opacity-60">Este paquete comprimido incluye todos los reportes superiores en formato CSV para respaldo institucional.</p>
              </div>
           </div>
         ) : (
           <div className="p-4 md:p-10">
              <div className="table-responsive">
                  <table className="w-full text-left print:table-auto border-collapse text-[11px] font-bold uppercase">
                      <thead className="bg-slate-50 text-[10px] font-black text-slate-400 print:bg-white print:text-black">
                        <tr>
                           <th className="p-5 border-b-2">Detalle de Registro</th>
                           <th className="p-5 border-b-2">Colaborador Principal</th>
                           <th className="p-5 border-b-2 text-right">Situación / Valor</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y print:text-black">
                          {reportType === 'attendance' && attendanceToDisplay.map(a => (
                            <tr key={a.id}>
                               <td className="p-5">{new Date(a.timestamp).toLocaleString()}</td>
                               <td className="p-5">{employees.find(e => e.id === a.employeeId)?.surname} {employees.find(e => e.id === a.employeeId)?.name}</td>
                               <td className="p-5 text-right font-black">
                                  {translateAttendanceStatus(a)}
                               </td>
                            </tr>
                          ))}
                          {reportType === 'payments' && paymentsToDisplay.map(p => (
                            <tr key={p.id}>
                               <td className="p-5"><p className="text-blue-600">{p.voucherCode}</p><p className="text-[9px] text-slate-400">{new Date(p.date).toLocaleDateString()}</p></td>
                               <td className="p-5">{employees.find(e => e.id === p.employeeId)?.surname}</td>
                               <td className="p-5 text-right font-[950] text-emerald-700">${p.amount.toFixed(2)}</td>
                            </tr>
                          ))}
                          {reportType === 'history' && historyToDisplay.map(e => (
                            <tr key={e.id}>
                               <td className="p-5"><p className="text-slate-900">{e.surname} {e.name}</p><p className="text-[9px] text-slate-400">CI: {e.identification}</p></td>
                               <td className="p-5">{e.role}</td>
                               <td className={`p-5 text-right font-[950] ${e.status === 'active' ? 'text-emerald-600' : 'text-red-500'}`}>{e.status}</td>
                            </tr>
                          ))}
                      </tbody>
                  </table>
              </div>
           </div>
         )}
      </div>

      <Modal isOpen={feedback.isOpen} onClose={() => setFeedback({...feedback, isOpen: false})} title={feedback.title} type={feedback.type}>
          <div className="text-center p-6 space-y-6">
              <p className="text-slate-700 font-bold uppercase text-[11px] italic leading-relaxed">{feedback.message}</p>
              <button onClick={() => setFeedback({...feedback, isOpen: false})} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] tracking-widest shadow-xl active:scale-95 transition-all">Entendido</button>
          </div>
      </Modal>
    </div>
  );
};

