                      <div key={idx} className="flex gap-4 p-4 bg-slate-50 rounded-2xl border border-slate-100 hover:bg-white transition-all group">
                         <div className="flex flex-col items-center shrink-0">
                            <div className="w-2 h-2 bg-blue-600 rounded-full group-hover:scale-150 transition-transform"></div>
                            <div className="w-0.5 flex-1 bg-slate-200"></div>
                         </div>
                         <div className="flex-1">
                            <p className="text-[9px] font-black text-slate-400 uppercase mb-1">{new Date(obs.date).toLocaleString()}</p>
                            <p className="text-xs font-bold text-slate-700 uppercase italic">"{obs.text}"</p>
                         </div>
                      </div>
                    ))
                  ) : (
                    <div className="py-10 text-center opacity-30 italic font-bold uppercase text-[10px]">Sin novedades registradas en el historial del colaborador.</div>
                  )}
               </div>
            </section>

            {selectedEmpAction.status === 'terminated' && (
              <section className="bg-red-50 p-8 rounded-[2rem] border border-red-100">
                 <h4 className="text-[11px] font-black text-red-700 uppercase tracking-widest border-b border-red-200 pb-3 mb-4 flex items-center gap-2"><span>🚪</span> Acta de Desvinculación</h4>
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-8 text-[11px] font-black uppercase">
                    <div>
                       <p className="text-red-400 text-[9px] mb-1">FECHA DE SALIDA:</p>
                       <p className="text-red-900">{selectedEmpAction.terminationDate}</p>
                       <p className="text-red-400 text-[9px] mt-4 mb-1">MOTIVO LEGAL:</p>
                       <p className="text-red-900">{selectedEmpAction.terminationReason}</p>
                    </div>
                    <div>
                       <p className="text-red-400 text-[9px] mb-1">DETALLES Y OBSERVACIONES FINALES:</p>
                       <p className="text-red-900 italic">"{selectedEmpAction.terminationDetails}"</p>
                    </div>
                 </div>
              </section>
            )}
          </div>
        )}
      </Modal>

      {/* FORMULARIO DE REGISTRO/EDICIÓN */}
      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title={editingEmp ? "Actualizar Expediente" : "Registrar empleado"} maxWidth="max-w-4xl">
        <div className="space-y-8 max-h-[75vh] overflow-y-auto pr-2 custom-scroll pb-6">
          <div className="flex flex-col md:flex-row gap-6 items-center bg-slate-50 p-6 rounded-[2rem] border">
             <div className="relative w-32 h-32 bg-white rounded-3xl border-2 border-dashed border-blue-200 flex items-center justify-center overflow-hidden shadow-inner group">
                {form.photo ? <img src={form.photo} className="w-full h-full object-cover" /> : <span className="text-3xl opacity-20">📸</span>}
                <input type="file" accept="image/*" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handlePhotoUpload} />
                <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center text-white text-[8px] font-black uppercase pointer-events-none text-center p-2">Click para subir foto</div>
             </div>
             <div className="flex-1 grid grid-cols-1 md:grid-cols-2 gap-4 w-full">
                <div className="space-y-1">
                   <label className="text-[9px] font-black text-slate-400 uppercase">Nombres</label>
                   <input className="w-full p-3 border-2 rounded-xl text-xs font-bold uppercase focus:border-blue-500 outline-none" value={form.name} onChange={e => setForm({...form, name: e.target.value.toUpperCase()})} />
                </div>
                <div className="space-y-1">
                   <label className="text-[9px] font-black text-slate-400 uppercase">Apellidos</label>
                   <input className="w-full p-3 border-2 rounded-xl text-xs font-bold uppercase focus:border-blue-500 outline-none" value={form.surname} onChange={e => setForm({...form, surname: e.target.value.toUpperCase()})} />
                </div>
                <div className="space-y-1">
                   <label className="text-[9px] font-black text-slate-400 uppercase">Identificación (CI/RUC)</label>
                   <input className="w-full p-3 border-2 rounded-xl text-xs font-mono font-black focus:border-blue-500 outline-none" value={form.identification} onChange={e => setForm({...form, identification: e.target.value.replace(/\D/g,'')})} />
                </div>
                <div className="space-y-1">
                   <label className="text-[9px] font-black text-slate-400 uppercase">Sueldo Base ($)</label>
                   <input type="number" step="0.01" className="w-full p-3 border-2 rounded-xl text-lg font-black focus:border-blue-500 outline-none" value={form.salary} onChange={e => setForm({...form, salary: Number(e.target.value)})} />
                </div>
             </div>
          </div>

          <section className="space-y-4">
             <h4 className="text-[10px] font-black text-blue-700 uppercase tracking-widest border-b pb-1">Datos Personales Obligatorios</h4>
             <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-slate-400 uppercase">Fecha de Nacimiento</label>
                  <input type="date" className="w-full p-3 border-2 rounded-xl text-xs font-bold" value={form.birthDate} onChange={e => setForm({...form, birthDate: e.target.value})} />
                </div>
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-slate-400 uppercase">Sexo</label>
                  <select className="w-full p-3 border-2 rounded-xl text-xs font-bold uppercase" value={form.gender} onChange={e => setForm({...form, gender: e.target.value as any})}>
                    {Object.values(Gender).map(g => <option key={g} value={g}>{g}</option>)}
                  </select>
                </div>
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-slate-400 uppercase">Estado Civil</label>
                  <select className="w-full p-3 border-2 rounded-xl text-xs font-bold uppercase" value={form.civilStatus} onChange={e => setForm({...form, civilStatus: e.target.value as any})}>
                    {Object.values(CivilStatus).map(s => <option key={s} value={s}>{s}</option>)}
                  </select>
                </div>
                <div className="space-y-1">
                   <label className="text-[9px] font-black text-slate-400 uppercase">Correo Electrónico</label>
                   <input type="email" className="w-full p-3 border-2 rounded-xl text-xs font-bold" placeholder="email@institucional.com" value={form.email} onChange={e => setForm({...form, email: e.target.value})} />
                </div>
                <div className="md:col-span-2 space-y-1">
                  <label className="text-[9px] font-black text-slate-400 uppercase">Dirección de Domicilio</label>
                  <input className="w-full p-3 border-2 rounded-xl text-xs font-bold uppercase" placeholder="Calle principal, secundaria y # casa" value={form.address} onChange={e => setForm({...form, address: e.target.value.toUpperCase()})} />
                </div>
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-slate-400 uppercase font-bold text-blue-600">Fecha de Ingreso</label>
                  <input type="date" className="w-full p-3 border-2 border-blue-200 rounded-xl text-xs font-bold" value={form.startDate} onChange={e => setForm({...form, startDate: e.target.value})} />
                </div>
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-slate-400 uppercase">Cargo</label>
                  <select className="w-full p-3 border-2 rounded-xl text-xs font-bold uppercase" value={form.role} onChange={e => setForm({...form, role: e.target.value as any})}>
                    {Object.values(Role).map(r => <option key={r} value={r}>{r}</option>)}
                  </select>
                </div>
                <div className="space-y-1">
                   <label className="text-[9px] font-black text-slate-400 uppercase">Tipo de Sangre</label>
                   <select className="w-full p-3 border-2 rounded-xl text-xs font-bold uppercase" value={form.bloodType} onChange={e => setForm({...form, bloodType: e.target.value as any})}>
                      {Object.values(BloodType).map(t => <option key={t} value={t}>{t}</option>)}
                   </select>
                </div>
             </div>
          </section>

          <section className="space-y-4">
             <h4 className="text-[10px] font-black text-orange-600 uppercase tracking-widest border-b pb-1">Contacto de Emergencia</h4>
             <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-slate-400 uppercase">Persona de Contacto</label>
                  <input className="w-full p-3 border-2 rounded-xl text-xs font-bold uppercase" placeholder="Nombre completo del contacto" value={form.emergencyContact?.name} onChange={e => setForm({...form, emergencyContact: {...form.emergencyContact!, name: e.target.value.toUpperCase()}})} />
                </div>
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-slate-400 uppercase">Teléfono de Emergencia</label>
                  <input className="w-full p-3 border-2 rounded-xl text-xs font-bold" placeholder="EJ: 0999999999" value={form.emergencyContact?.phone} onChange={e => setForm({...form, emergencyContact: {...form.emergencyContact!, phone: e.target.value.replace(/\D/g,'')}})} />
                </div>
             </div>
          </section>

          <section className="space-y-4 border-t pt-6">
             <h4 className="text-[10px] font-black text-blue-700 uppercase tracking-widest border-b pb-1">Seguridad Social</h4>
             <div className="grid grid-cols-1 md:grid-cols-3 gap-6 items-end">
                <div className="p-4 bg-slate-50 rounded-2xl border flex items-center justify-between">
                   <span className="text-[10px] font-black uppercase text-slate-600">Afiliación IESS</span>
                   <button onClick={() => setForm({...form, isAffiliated: !form.isAffiliated})} className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${form.isAffiliated ? 'bg-blue-600' : 'bg-slate-300'}`}>
                     <span className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${form.isAffiliated ? 'translate-x-6' : 'translate-x-1'}`} />
                   </button>
                </div>
                <div className="space-y-1">
                    <label className="text-[9px] font-black text-slate-400 uppercase">Fondos de Reserva</label>
                    <select className="w-full p-3 border-2 rounded-xl text-[10px] font-black uppercase" value={form.reserveFundType || 'monthly'} onChange={e => setForm({...form, reserveFundType: e.target.value as any})}>
                      <option value="monthly">Mensualizar</option>
                      <option value="accumulate">Acumular</option>
                      <option value="none">No aplica</option>
                    </select>
                </div>
                <div className="space-y-1">
                  <label className="text-[9px] font-black text-slate-400 uppercase">Décimos Sueldos</label>
                  <select className="w-full p-3 border-2 rounded-xl text-[10px] font-black uppercase" value={form.overSalaryType} onChange={e => setForm({...form, overSalaryType: e.target.value as any})}>
                    <option value="monthly">Mensualizar</option>
                    <option value="accumulate">Acumular</option>
                    <option value="none">No Aplica</option>
                  </select>
                </div>
             </div>
          </section>

          <button onClick={handleSave} className="w-full py-5 bg-blue-700 text-white font-[950] rounded-2xl uppercase text-[11px] tracking-[0.3em] shadow-2xl active:scale-95 transition-all">Registrar empleado</button>
        </div>
      </Modal>

      {/* FEEDBACK */}
      <Modal isOpen={feedback.isOpen} onClose={() => setFeedback({...feedback, isOpen: false})} title={feedback.title} type={feedback.type}>
        <div className="text-center p-6">
          <p className="text-[11px] font-black uppercase text-slate-600 leading-relaxed italic">{feedback.message}</p>
          <button onClick={() => setFeedback({...feedback, isOpen: false})} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] mt-8 active:scale-95 transition-all tracking-widest shadow-lg">Entendido</button>
        </div>
      </Modal>

      {/* NOVEDADES Y DESVINCULACION */}
      <Modal isOpen={isNovedadModalOpen} onClose={() => setIsNovedadModalOpen(false)} title="Bitácora Administrativa">
         <div className="space-y-4">
            <textarea className="w-full border-2 p-4 rounded-xl text-xs font-bold uppercase focus:border-blue-500 outline-none min-h-[140px]" placeholder="Escriba la novedad..." value={novedadText} onChange={e => setNovedadText(e.target.value)} />
            <button onClick={handleAddNovedad} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] tracking-widest shadow-lg">Guardar Novedad</button>
         </div>
      </Modal>

      <Modal isOpen={isDesvinculacionModalOpen} onClose={() => setIsDesvinculacionModalOpen(false)} title="Dar de baja empleado" type="error">
         <div className="space-y-6">
            <div className="space-y-4">
               <input type="date" className="w-full border-2 p-3 rounded-xl text-xs font-bold" value={desvinculacionData.date} onChange={e => setDesvinculacionData({...desvinculacionData, date: e.target.value})} />
               <select className="w-full border-2 p-3 rounded-xl text-xs font-bold uppercase" value={desvinculacionData.reason} onChange={e => setDesvinculacionData({...desvinculacionData, reason: e.target.value as any})}>
                  {Object.values(TerminationReason).map(v => <option key={v} value={v}>{v}</option>)}
               </select>
               <textarea className="w-full border-2 p-3 rounded-xl text-xs font-bold uppercase h-24 focus:border-red-600 outline-none" placeholder="Observaciones finales..." value={desvinculacionData.details} onChange={e => setDesvinculacionData({...desvinculacionData, details: e.target.value})} />
            </div>
            <div className="flex gap-4">
               <button onClick={() => setIsDesvinculacionModalOpen(false)} className="flex-1 py-4 bg-slate-100 text-slate-500 font-black rounded-xl uppercase text-[10px]">Cancelar</button>
               <button onClick={handleProcessDesvinculacion} className="flex-1 py-4 bg-red-600 text-white font-black rounded-xl uppercase text-[10px] shadow-xl">Confirmar Baja</button>
            </div>
         </div>
      </Modal>
    </div>
  );
};

export default EmployeeModule;

import React, { useState } from 'react';
import { Employee, Payment, AttendanceRecord, CompanyConfig, GlobalSettings, Role } from '../../types.ts';
import Modal from '../../components/Modal.tsx';
import JSZip from 'jszip';

interface ReportsModuleProps {
  employees: Employee[];
  payments: Payment[];
  attendance: AttendanceRecord[];
  company: CompanyConfig | null;
  settings: GlobalSettings;
  role: Role;
}

const ReportsModule: React.FC<ReportsModuleProps> = ({ employees, payments = [], attendance = [], company, settings, role }) => {
  const [reportType, setReportType] = useState<'attendance' | 'payments' | 'history' | 'master' | 'employees' | 'payroll' | 'novedades' | 'bajas'>('attendance');
  const [searchTerm, setSearchTerm] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [isZipping, setIsZipping] = useState(false);
  const [feedback, setFeedback] = useState({ isOpen: false, title: '', message: '', type: 'success' as any });

  const getCSVData = (type: string) => {
    let csv = "\uFEFF";

    // Obtenemos los datos según el tipo
    if (type === 'employees' || type === 'history') {
      csv += "ID,COLABORADOR,CARGO,INGRESO,AFILIACION IESS,FONDOS RESERVA,DECIMOS,SUELDO,STATUS\n";
      const data = employees.filter(e => {
        const matchesSearch = `${e.name} ${e.surname} ${e.identification}`.toLowerCase().includes(searchTerm.toLowerCase());
        return matchesSearch && (type === 'bajas' ? filterByDate(e.terminationDate || '') : filterByDate(e.startDate));
      });
      data.forEach(e => {
        csv += `"${e.identification}","${e.surname} ${e.name}","${e.role}","${e.startDate}","${e.isAffiliated ? 'SI' : 'NO'}","${e.reserveFundType || 'N/A'}","${e.overSalaryType}","${e.salary.toFixed(2)}","${e.status}"\n`;
      });
    } else if (type === 'payroll' || type === 'payments') {
      csv += "VOUCHER,FECHA,BENEFICIARIO,CONCEPTO,METODO,MONTO,STATUS\n";
      const data = payments.filter(p => {
        const emp = employees.find(e => e.id === p.employeeId);
        const matchesSearch = `${emp?.surname} ${emp?.name} ${p.voucherCode}`.toLowerCase().includes(searchTerm.toLowerCase());
        return matchesSearch && filterByDate(p.date);
      });
      data.forEach(p => {
        const emp = employees.find(e => e.id === p.employeeId);
        csv += `"${p.voucherCode}","${new Date(p.date).toLocaleDateString()}","${emp?.surname} ${emp?.name}","${p.type}","${p.method}","${p.amount.toFixed(2)}","${p.status}"\n`;
      });
    } else if (type === 'attendance') {
      csv += "FECHA,COLABORADOR,ID,TIPO,ESTADO,ATRASO,JUSTIFICACION\n";
      const data = attendance.filter(a => {
        const emp = employees.find(e => e.id === a.employeeId);
        const matchesSearch = `${emp?.surname} ${emp?.name} ${emp?.identification}`.toLowerCase().includes(searchTerm.toLowerCase());
        return matchesSearch && filterByDate(a.timestamp);
      });
      data.forEach(a => {
        const emp = employees.find(e => e.id === a.employeeId);
        let statusTexto = a.status === 'confirmed' ? "CONFIRMADO" : "PENDIENTE";
        csv += `"${new Date(a.timestamp).toLocaleString()}","${emp?.surname} ${emp?.name}","${emp?.identification}","${a.type}","${statusTexto}","${a.isLate ? 'SI' : 'NO'}","${a.justification || ''}"\n`;
      });
    } else if (type === 'novedades') {
      csv += "FECHA REGISTRO,COLABORADOR,EVENTO ADMINISTRATIVO\n";
      const novedades = employees.flatMap(e => e.observations?.map(obs => ({ emp: e, obs })) || []).filter(item => filterByDate(item.obs.date));
      novedades.forEach(item => {
        csv += `"${new Date(item.obs.date).toLocaleString()}","${item.emp.surname} ${item.emp.name}","${item.obs.text}"\n`;
      });
    } else if (type === 'bajas') {
      csv += "COLABORADOR,IDENTIFICACION,SALIDA,MOTIVO LEGAL,DETALLES FINALES\n";
      const bajas = employees.filter(e => e.status === 'terminated' && filterByDate(e.terminationDate || ''));
      bajas.forEach(e => {
        csv += `"${e.surname} ${e.name}","${e.identification}","${e.terminationDate}","${e.terminationReason}","${e.terminationDetails}"\n`;
      });
    }
    return csv;
  };

  const handleDownloadMasterZip = async () => {
    setIsZipping(true);
    try {
      const zip = new JSZip();
      const folder = zip.folder(`ARCHIVO_MAESTRO_ASISTUP_${new Date().getFullYear()}`);

      folder?.file("1_CENSO_PERSONAL_MAESTRO.csv", getCSVData('employees'));
      folder?.file("2_REGISTRO_PAGOS_NOMINA.csv", getCSVData('payroll'));
      folder?.file("3_BITACORA_ASISTENCIA.csv", getCSVData('attendance'));
      folder?.file("4_HISTORIAL_NOVEDADES.csv", getCSVData('novedades'));
      folder?.file("5_EXPEDIENTES_DESVINCULADOS.csv", getCSVData('bajas'));

      const blob = await zip.generateAsync({ type: "blob" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = `CONSOLIDADO_MASTER_ASISTUP_${new Date().toISOString().split('T')[0]}.zip`;
      link.click();
      setFeedback({ isOpen: true, title: "Éxito Corporativo", message: "Contenedor ZIP generado y descargado correctamente para archivo físico.", type: "success" });
    } catch (e) {
      setFeedback({ isOpen: true, title: "Fallo Crítico", message: "No se pudo consolidar el paquete comprimido.", type: "error" });
    } finally {
      setIsZipping(false);
    }
  };

  const generateReportExcel = (type: string) => {
    const csv = getCSVData(type);
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `REPORTE_${type.toUpperCase()}_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  };

  const generateReportPDF = (type: any) => {
    // IMPORTANTE: Limpiar filtros para garantizar reporte completo desde el panel maestro
    setSearchTerm('');
    setStartDate('');
    setEndDate('');
    setReportType(type);

    // Timeout para asegurar que React termine el renderizado de la tabla antes de imprimir
    setTimeout(() => {
      window.print();
    }, 800);
  };

  const filterByDate = (timestamp: string) => {
    if (!startDate && !endDate) return true;
    const date = new Date(timestamp);
    const start = startDate ? new Date(startDate + 'T00:00:00') : null;
    const end = endDate ? new Date(endDate + 'T23:59:59') : null;
    if (start && date < start) return false;
    if (end && date > end) return false;
    return true;
  };

  const attendanceToDisplay = (attendance || []).filter(a => {
    const emp = employees.find(e => e.id === a.employeeId);
    const matchesSearch = `${emp?.surname} ${emp?.name} ${emp?.identification}`.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesSearch && filterByDate(a.timestamp);
  }).sort((a, b) => b.timestamp.localeCompare(a.timestamp));

  const paymentsToDisplay = payments.filter(p => {
    const emp = employees.find(e => e.id === p.employeeId);
    const matchesSearch = `${emp?.surname} ${emp?.name} ${p.voucherCode}`.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesSearch && filterByDate(p.date);
  }).sort((a,b) => b.date.localeCompare(a.date));

  const historyToDisplay = employees.filter(e => {
    const searchStr = `${e.name} ${e.surname} ${e.identification} ${e.status}`.toLowerCase();
    const matchesSearch = searchStr.includes(searchTerm.toLowerCase());
    return matchesSearch && (reportType === 'bajas' ? filterByDate(e.terminationDate || '') : filterByDate(e.startDate));
  }).sort((a,b) => b.startDate.localeCompare(a.startDate));

  const translateAttendanceStatus = (record: AttendanceRecord) => {
    let base = "";
    if (record.type === 'in') base = record.status === 'confirmed' ? "INGRESO APROBADO" : record.status === 'pending_approval' ? "INGRESO PENDIENTE" : "INGRESO RECHAZADO";
    else if (record.type === 'out') base = record.status === 'confirmed' ? "SALIDA APROBADA" : record.status === 'pending_approval' ? "SALIDA PENDIENTE" : "SALIDA RECHAZADA";
    else if (record.type === 'half_day') base = "MEDIA JORNADA LIBRE";

    return (
      <span className="flex flex-col items-end">
        <span>{base}</span>
        {record.isLate && <span className="text-[8px] font-black lowercase opacity-60">(atraso)</span>}
      </span>
    );
  };

  const renderTableRows = () => {
    switch (reportType) {
      case 'attendance':
        return attendanceToDisplay.map(a => (
          <tr key={a.id}>
            <td className="p-5">{new Date(a.timestamp).toLocaleString()}</td>
            <td className="p-5">{employees.find(e => e.id === a.employeeId)?.surname} {employees.find(e => e.id === a.employeeId)?.name}</td>
            <td className="p-5 text-right font-black">{translateAttendanceStatus(a)}</td>
          </tr>
        ));
      case 'payments':
      case 'payroll':
        return paymentsToDisplay.map(p => (
          <tr key={p.id}>
            <td className="p-5"><p className="text-blue-600">{p.voucherCode}</p><p className="text-[9px] text-slate-400">{new Date(p.date).toLocaleDateString()}</p></td>
            <td className="p-5">{employees.find(e => e.id === p.employeeId)?.surname}</td>
            <td className="p-5 text-right font-[950] text-emerald-700">${p.amount.toFixed(2)}</td>
          </tr>
        ));
      case 'history':
      case 'employees':
        return historyToDisplay.map(e => (
          <tr key={e.id}>
            <td className="p-5"><p className="text-slate-900">{e.surname} {e.name}</p><p className="text-[9px] text-slate-400">CI: {e.identification}</p></td>
            <td className="p-5">{e.role}</td>
            <td className={`p-5 text-right font-[950] ${e.status === 'active' ? 'text-emerald-600' : 'text-red-500'}`}>{e.status}</td>
          </tr>
        ));
      case 'novedades':
        const novedades = employees.flatMap(e => e.observations?.map(obs => ({ emp: e, obs })) || []).filter(item => filterByDate(item.obs.date));
        return novedades.map((item, idx) => (
          <tr key={idx}>
            <td className="p-5">{new Date(item.obs.date).toLocaleString()}</td>
            <td className="p-5">{item.emp.surname} {item.emp.name}</td>
            <td className="p-5 text-right font-black italic">{item.obs.text}</td>
          </tr>
        ));
      case 'bajas':
        const bajas = employees.filter(e => e.status === 'terminated' && filterByDate(e.terminationDate || ''));
        return bajas.map(e => (
          <tr key={e.id}>
            <td className="p-5">{e.terminationDate}</td>
            <td className="p-5">{e.surname} {e.name}</td>
            <td className="p-5 text-right font-black text-red-600">{e.terminationReason} <span className="text-[9px] opacity-60">({e.terminationDetails})</span></td>
          </tr>
        ));
      default:
        return null;
    }
  };

  const getReportHeaderTitle = () => {
    switch(reportType) {
      case 'employees': return 'CENSO DE PERSONAL MAESTRO';
      case 'payroll': return 'REGISTRO DE PAGOS DE NÓMINA';
      case 'novedades': return 'HISTORIAL DE NOVEDADES ADMINISTRATIVAS';
      case 'bajas': return 'EXPEDIENTES DE DESVINCULACIONES';
      case 'attendance': return 'BITÁCORA DE ASISTENCIA Y PUNTUALIDAD';
      case 'payments': return 'HISTORIAL DE EGRESOS Y PAGOS';
      case 'history': return 'EXPEDIENTES DE PERSONAL ACTIVO';
      default: return `REPORTE DE ${reportType.toUpperCase()}`;
    }
  };

  return (
    <div className="space-y-6 md:space-y-8 fade-in">
      <div className="bg-white p-6 md:p-10 rounded-[2.5rem] shadow-sm border no-print flex flex-col md:flex-row justify-between items-center gap-6">
        <div className="shrink-0">
           <h2 className="text-2xl font-[950] text-slate-900 uppercase italic">Centro de Reportes Maestro</h2>
           <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest mt-2">Auditoría y Gestión de Datos Corporativos</p>
        </div>
        <div className="flex flex-col gap-4 w-full md:w-auto">
          <div className="flex gap-2 overflow-x-auto pb-2 no-scrollbar">
            {['attendance', 'payments', 'history', 'master'].map(t => (
              <button key={t} onClick={() => {setReportType(t as any); setSearchTerm(''); setStartDate(''); setEndDate('');}} className={`whitespace-nowrap px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all ${reportType === t ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-50 text-slate-400 border'}`}>
                {t === 'attendance' ? 'Asistencia' : t === 'payments' ? 'Pagos' : t === 'history' ? 'Historial' : 'Archivo Maestro'}
              </button>
            ))}
          </div>

          {reportType !== 'master' && (
            <div className="flex flex-col sm:flex-row gap-3">
              <input type="text" placeholder="Filtrar por nombre o CI..." className="flex-1 p-3 border-2 rounded-xl text-[11px] font-bold uppercase outline-none focus:border-blue-500" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} />
              <div className="flex gap-2">
                 <div className="flex flex-col gap-1">
                   <label className="text-[7px] font-black uppercase text-slate-400">Desde</label>
                   <input type="date" className="p-3 border-2 rounded-xl text-[10px] font-black uppercase outline-none" value={startDate} onChange={e => setStartDate(e.target.value)} />
                 </div>
                 <div className="flex flex-col gap-1">
                   <label className="text-[7px] font-black uppercase text-slate-400">Hasta</label>
                   <input type="date" className="p-3 border-2 rounded-xl text-[10px] font-black uppercase outline-none" value={endDate} onChange={e => setEndDate(e.target.value)} />
                 </div>
                 <div className="flex gap-1 items-end">
                    <button 
                      onClick={() => generateReportExcel(reportType)} 
                      title="Descargar Excel"
                      className="p-3 bg-emerald-600 text-white rounded-xl shadow-md active:scale-95 transition-all text-[10px] font-black uppercase"
                    >
                      XLS
                    </button>
                    <button 
                      onClick={() => generateReportPDF(reportType)} 
                      title="Descargar PDF"
                      className="p-3 bg-blue-700 text-white rounded-xl shadow-md active:scale-95 transition-all text-[10px] font-black uppercase"
                    >
                      PDF
                    </button>
                    <button onClick={() => {setStartDate(''); setEndDate(''); setSearchTerm(''); setReportType('master');}} className="p-3 bg-slate-100 text-slate-500 rounded-xl hover:bg-red-50 hover:text-red-600 transition-colors">✕</button>
                 </div>
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="bg-white rounded-[2.5rem] shadow-sm border overflow-hidden" id="reports-printable-area">
         {/* CABECERA ESTRICTA PARA IMPRESIÓN */}
         <div className="hidden print:block p-10 border-b-4 border-black text-center space-y-4">
            <div className="flex items-center justify-center gap-6">
               <div className="w-20 h-20 border-2 border-black flex items-center justify-center overflow-hidden">
                  {company?.logo ? <img src={company.logo} className="w-full h-full object-contain" /> : <span className="text-2xl font-black">LOGO</span>}
               </div>
               <div className="text-left">
                  <h1 className="text-3xl font-[950] uppercase italic leading-none">{company?.name || 'EMPRESA INSTITUCIONAL'}</h1>
                  <p className="text-sm font-black uppercase mt-1">RUC: {company?.ruc || '0000000000001'}</p>
                  <p className="text-[10px] font-bold uppercase tracking-tighter">{company?.address || 'QUITO, ECUADOR'}</p>
               </div>
            </div>
            <div className="pt-4 border-t-2 border-black/10">
               <p className="text-[12px] font-[950] uppercase tracking-[0.3em]">{getReportHeaderTitle()}</p>
               {startDate || endDate ? (
                 <p className="text-[10px] font-black uppercase mt-1">Período: {startDate || 'Inicio'} al {endDate || 'Hoy'}</p>
               ) : null}
               {searchTerm && <p className="text-[9px] font-black uppercase italic">Filtro aplicado: "{searchTerm}"</p>}
               <p className="text-[8px] font-bold uppercase opacity-60">Documento Generado el {new Date().toLocaleString()}</p>
            </div>
         </div>

         {reportType === 'master' ? (
           <div className="p-10 md:p-16 space-y-12 no-print text-center">
              <header className="border-b pb-8">
                <h3 className="text-2xl font-black text-slate-900 uppercase tracking-widest">Gestión de Archivo Maestro</h3>
                <p className="text-[11px] font-black text-blue-600 uppercase mt-2 tracking-widest italic leading-relaxed">Consolidado integral para cumplimiento legal y auditorías externas de talento humano</p>
              </header>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 text-left">
                 {[
                   { id: 'employees', title: 'Censo Personal', icon: '👥', desc: 'Fichas, cargos y sueldos.' },
                   { id: 'payroll', title: 'Registro Pagos', icon: '💰', desc: 'Nómina, bonos y egresos.' },
                   { id: 'attendance', title: 'Asistencia', icon: '🕒', desc: 'Marcaciones y atrasos.' },
                   { id: 'novedades', title: 'Bitácora Novedades', icon: '📝', desc: 'Incidencias administrativas.' },
                   { id: 'bajas', title: 'Bajas Laborales', icon: '🚪', desc: 'Historial de desvinculaciones.' }
                 ].map(seg => (
                   <div key={seg.id} className="bg-slate-50 p-6 rounded-[2rem] border-2 border-slate-100 flex flex-col justify-between hover:border-blue-200 transition-colors">
                      <div className="mb-4 flex items-start gap-3">
                        <div className="w-10 h-10 bg-white rounded-xl shadow-inner flex items-center justify-center text-2xl">{seg.icon}</div>
                        <div>
                           <h4 className="text-[11px] font-[950] uppercase text-slate-900 leading-none mb-1">{seg.title}</h4>
                           <p className="text-[9px] text-slate-400 font-bold uppercase tracking-tighter leading-tight">{seg.desc}</p>
                        </div>
                      </div>
                      <div className="flex gap-2">
                        <button onClick={() => generateReportExcel(seg.id)} className="flex-1 py-2.5 bg-emerald-600 text-white text-[9px] font-black rounded-lg uppercase shadow-md active:scale-95 transition-all">Excel</button>
                        <button onClick={() => generateReportPDF(seg.id as any)} className="flex-1 py-2.5 bg-blue-700 text-white text-[9px] font-black rounded-lg uppercase shadow-md active:scale-95 transition-all">PDF</button>
                      </div>
                   </div>
                 ))}
              </div>
              <div className="pt-10 border-t flex flex-col items-center gap-6">
                 <button 
                   onClick={handleDownloadMasterZip} 
                   disabled={isZipping} 
                   className="w-full max-w-md py-6 bg-slate-900 text-white font-[950] rounded-[2rem] uppercase text-[12px] tracking-[0.4em] shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-4 group"
                 >
                   <span>{isZipping ? '⌛' : '📦'}</span>
                   {isZipping ? 'CONSOLIDANDO DATOS...' : 'Descargar Archivo Maestro .ZIP'}
                 </button>
                 <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest text-center italic opacity-60">Este paquete comprimido incluye todos los reportes superiores en formato CSV para respaldo institucional.</p>
              </div>
           </div>
         ) : (
           <div className="p-4 md:p-10">
              <div className="table-responsive">
                  <table className="w-full text-left print:table-auto border-collapse text-[11px] font-bold uppercase">
                      <thead className="bg-slate-50 text-[10px] font-black text-slate-400 print:bg-white print:text-black">
                        <tr>
                           <th className="p-5 border-b-2">Detalle de Registro</th>
                           <th className="p-5 border-b-2">Colaborador Principal</th>
                           <th className="p-5 border-b-2 text-right">Situación / Valor</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y print:text-black">
                          {renderTableRows()}
                      </tbody>
                  </table>
              </div>
           </div>
         )}
      </div>

      <Modal isOpen={feedback.isOpen} onClose={() => setFeedback({...feedback, isOpen: false})} title={feedback.title} type={feedback.type}>
          <div className="text-center p-6 space-y-6">
              <p className="text-slate-700 font-bold uppercase text-[11px] italic leading-relaxed">{feedback.message}</p>
              <button onClick={() => setFeedback({...feedback, isOpen: false})} className="w-full py-4 bg-slate-900 text-white font-black rounded-xl uppercase text-[10px] tracking-widest shadow-xl active:scale-95 transition-all">Entendido</button>
          </div>
      </Modal>
    </div>
  );
};

